window.SEMIPRIME_SOURCES={"RiemannGaussian.SemiprimeBinomialExecutionTracked":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeBinomialExecution\n\n/-! # Fully acquired integer Pascal, target and parity arrays -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeBinomialExecutionTracked\nopen scoped BigOperators\nopen SemiprimeBinomialExecution\n\n/-- Actual Pascal row and its scalar/read ledger. -/\nstructure PascalRun where\n  /-- Materialized natural coefficient row. -/\n  coefficients : Array ℕ\n  /-- Scalar integer additions in the coordinate callbacks. -/\n  additions : ℕ\n  /-- Conservative actual old-row reads, including the zero boundary slot. -/\n  reads : ℕ\n\n/-- Acquire Pascal coefficients without native choose or matrix advice. -/\ndef acquireChoose (R : ℕ) : ℕ → PascalRun\n  | 0 => ⟨Array.ofFn (fun k : Fin (R+1) => if k.val=0 then 1 else 0),0,0⟩\n  | A+1 =>\n      let old := acquireChoose R A\n      let next := Array.ofFn (fun k : Fin (R+1) => natCoeff old.coefficients k.val+\n        if k.val=0 then 0 else natCoeff old.coefficients (k.val-1))\n      ⟨next,old.additions+(R+1),old.reads+2*(R+1)⟩\n\n/-- The instrumented supplier returns exactly the proved Pascal row. -/\ntheorem acquireChoose_value (R A : ℕ) : (acquireChoose R A).coefficients=chooseRow R A := by\n  induction A with\n  | zero => rfl\n  | succ A ih => simp only [acquireChoose,chooseRow,ih]\n\n/-- Every Pascal coordinate addition/read is paid in the actual finite loops. -/\ntheorem acquireChoose_work (R A : ℕ) :\n    (acquireChoose R A).additions=A*(R+1) ∧ (acquireChoose R A).reads=2*A*(R+1) := by\n  induction A with\n  | zero => simp [acquireChoose]\n  | succ A ih => simp only [acquireChoose]; constructor <;> nlinarith\n\n/-- Compute the parity sign by actual integer negations. -/\ndef sign : ℕ → ℤ × ℕ\n  | 0 => (1,0)\n  | A+1 => let old := sign A; (-old.1,old.2+1)\n\ntheorem sign_value (A : ℕ) : (sign A).1=(-1 : ℤ)^A := by\n  induction A with\n  | zero => rfl\n  | succ A ih => simp only [sign,ih,pow_succ]; ring\n\ntheorem sign_work (A : ℕ) : (sign A).2=A := by\n  induction A with\n  | zero => rfl\n  | succ A ih => simp only [sign,ih]\n\n/-- Cached powers for the explicit lower Pascal solution. -/\nstructure LowerRun where\n  /-- Already computed lower coefficients. -/\n  coefficients : Array ℤ\n  /-- Next cached scalar power, never recomputed recursively from its exponent. -/\n  next : ℤ\n  /-- Actual integer products. -/\n  arithmetic : ℕ\n\n/-- Acquire a geometric target array by one multiplication per next entry. -/\ndef acquireLower (base : ℤ) : ℕ → LowerRun\n  | 0 => ⟨#[],base,0⟩\n  | len+1 =>\n      let old := acquireLower base len\n      ⟨old.coefficients.push old.next,old.next*(-2),old.arithmetic+1⟩\n\ntheorem acquireLower_size (base : ℤ) (len : ℕ) : (acquireLower base len).coefficients.size=len := by\n  induction len with\n  | zero => rfl\n  | succ len ih => simp only [acquireLower,Array.size_push,ih]\n\ntheorem acquireLower_next (base : ℤ) (len : ℕ) : (acquireLower base len).next=base*(-2 : ℤ)^len := by\n  induction len with\n  | zero => simp [acquireLower]\n  | succ len ih => simp only [acquireLower,ih,pow_succ]; ring\n\ntheorem acquireLower_work (base : ℤ) (len : ℕ) : (acquireLower base len).arithmetic=len := by\n  induction len with\n  | zero => rfl\n  | succ len ih => simp only [acquireLower,ih]\n\n/-- Each retained target entry is the actual explicitly computed geometric coefficient. -/\ntheorem acquireLower_value (base : ℤ) (len k : ℕ) (hk : k<len) :\n    coeff (acquireLower base len).coefficients k=base*(-2 : ℤ)^k := by\n  induction len with\n  | zero => omega\n  | succ len ih =>\n    by_cases he : k=len\n    · subst k\n      simp only [acquireLower,coeff,Array.getElem?_push,acquireLower_size,ite_true,\n        Option.getD_some,acquireLower_next]\n    · have hkl : k<len := by omega\n      simp only [acquireLower,coeff,Array.getElem?_push,acquireLower_size,ite_eq_right he]\n      exact ih hkl\n\n/-- A cached solve depends only on target coordinates that its loop actually reads. -/\ntheorem solve_target_ext (kernel : Array ℕ) (f g : ℕ → ℤ) (len : ℕ)\n    (h : ∀ k<len,f k=g k) : solve kernel f len=solve kernel g len := by\n  induction len with\n  | zero => rfl\n  | succ len ih =>\n    have ho := ih (fun k hk => h k (by omega))\n    simp only [solve,ho,h len (by omega)]\n\n/-- All integer coefficient arrays and complete scalar/read costs of the acquisition. -/\nstructure ParityRun where\n  /-- Reversed upper-solve output coefficients. -/\n  coefficients : Array ℤ\n  /-- Pascal additions, sign negations, target products and solve arithmetic. -/\n  arithmetic : ℕ\n  /-- Pascal/solve cached-array reads. -/\n  reads : ℕ\n\n/-- Full integer acquisition: Pascal kernel, geometric target and cached solve. -/\ndef acquireParity (A R : ℕ) : ParityRun :=\n  let kernel := acquireChoose R A\n  let phase := sign A\n  let targets := acquireLower phase.1 R\n  let out := solve kernel.coefficients (fun k => coeff targets.coefficients (R-(k+1))) R\n  ⟨out.coefficients,kernel.additions+phase.2+targets.arithmetic+out.arithmetic,\n    kernel.reads+out.reads⟩\n\n/-- Every acquired coefficient is the original exact parity coefficient, not advice. -/\ntheorem acquireParity_value (A R : ℕ) :\n    (acquireParity A R).coefficients=(parityArray A R).coefficients := by\n  simp only [acquireParity,acquireChoose_value,sign_value,parityArray]\n  apply congrArg SolveRun.coefficients\n  apply solve_target_ext\n  intro k hk\n  rw [acquireLower_value _ _ _ (by omega)]\n  rfl\n\n/-- The complete scalar/read work includes the two coefficient suppliers. -/\ntheorem acquireParity_work (A R : ℕ) :\n    (acquireParity A R).arithmetic=A*(R+1)+A+R+R^2 ∧\n      (acquireParity A R).reads=2*A*(R+1)+R^2 := by\n  have hp := acquireChoose_work R A\n  have hl := acquireLower_work (sign A).1 R\n  have hs := solve_work (acquireChoose R A).coefficients\n    (fun k => coeff (acquireLower (sign A).1 R).coefficients (R-(k+1))) R\n  simp only [acquireParity,sign_work]\n  constructor <;> omega\n\n/-- Original-order executable coefficient function with ALL sources acquired internally. -/\ndef acquiredParity (A R : ℕ) : Fin R → ℤ :=\n  let out := acquireParity A R\n  fun j => coeff out.coefficients j.rev.val\n\n/-- No runtime coefficient-vector supplier appears in this exact source equality. -/\ntheorem acquiredParity_eq (A R : ℕ) :\n    acquiredParity A R=OAI.Algorithms.SubexponentialSAT.BinomialInterpolation.parityCoefficients (K:=ℤ) A R := by\n  rw [← parity_eq]\n  funext j\n  simp only [acquiredParity,parity,acquireParity_value]\n\nend RiemannGaussian.SemiprimeBinomialExecutionTracked\n","RiemannGaussian.SemiprimeConstructedCounter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceLayoutHeight\nimport RiemannGaussian.SemiprimeLayoutSelection\nimport RiemannGaussian.SemiprimeCounterSearch\n\n/-!\n# The exact counter with its layout certificates constructed from original ports\n\nThe input is the original Boolean network and public numerical parameters.\nWords, complete blocks, pulled rows, bounded integer constraints, selected\nrows and node certificates are constructed, rather than supplied as oracles.\nThis is a mathematical counter and search correctness theorem; primitive\nexecution of finite enumerations, row selection and arithmetic remains separate.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeConstructedCounter\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT.SqrtLog\nopen RiemannGaussian.SemiprimeSourceLayout\nopen RiemannGaussian.SemiprimeSourceLayoutHeight\nopen RiemannGaussian.SemiprimeLayoutSelection\nopen RiemannGaussian.SemiprimeCounterCompose\nopen RiemannGaussian.SemiprimeCounterSearch\nopen RiemannGaussian.SemiprimeCountRecovery\nopen RiemannGaussian.SemiprimeHermiteRecovery\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\nvariable {A E : Type} [Fintype A] [DecidableEq A] [Fintype E] [DecidableEq E]\n\n/-- Literal original port incidence type. -/\nabbrev Incidence (arity : E → ℕ) := (e : E) × Fin (arity e)\n\n/-- Public layout dimensions and a bound on original coordinate occurrences. -/\nstructure Parameters (arity : E → ℕ) (coordinate : (e : E) → Fin (arity e) → A) where\n  /-- Number of heads. -/\n  r : ℕ\n  /-- Number of interpolation nodes. -/\n  Q : ℕ\n  /-- Replacement row degree. -/\n  R : ℕ\n  /-- Maximum original coordinate occurrence count. -/\n  B : ℕ\n  /-- Tolerance used by the actual word search. -/\n  epsilon : ℚ\n  /-- The universal swap alphabet has at least two heads. -/\n  groups : 2 ≤ r\n  /-- There are at least two interpolation nodes. -/\n  nodes : 2 ≤ Q\n  /-- The centered spectral interval has sufficient width. -/\n  degree : 4 ≤ R\n  /-- The centered interval lies in the node range. -/\n  size : 4 * R ≤ Q\n  /-- The bound concerns original ports, before constructing any rows. -/\n  occurrences : ∀ a, (Finset.univ.filter\n    (fun i : Incidence arity => coordinate i.1 i.2 = a)).card ≤ B\n\n/-- The public group range supplies the nonempty word alphabet. -/\ninstance Parameters.groupsNonzero {arity : E → ℕ}\n    {coordinate : (e : E) → Fin (arity e) → A} (p : Parameters arity coordinate) :\n    NeZero p.r := ⟨by have := p.groups; omega⟩\n\n/-- Sample nodes reindexed by their exact positive rational values. -/\ndef sampleEquiv (Q : ℕ) : Fin Q ≃ samplePoints Q :=\n  Equiv.ofBijective (fun t => ⟨sampleNode Q t, Finset.mem_image.mpr ⟨t, Finset.mem_univ t, rfl⟩⟩)\n    ⟨by\n      intro a b h\n      exact sampleNode_injective Q (congrArg Subtype.val h), by\n      intro t\n      obtain ⟨i, _, hi⟩ := Finset.mem_image.mp t.property\n      exact ⟨i, Subtype.ext hi⟩⟩\n\ntheorem sampleEquiv_symm_value (Q : ℕ) (t : samplePoints Q) :\n    sampleNode Q ((sampleEquiv Q).symm t) = t.val :=\n  congrArg Subtype.val ((sampleEquiv Q).apply_symm_apply t)\n\nvariable {arity : E → ℕ} {coordinate : (e : E) → Fin (arity e) → A}\n\n/-- Actual source layout, constructed on the network's dependent port indices. -/\ndef layout (p : Parameters arity coordinate) :\n    Layout.Data (O := ℚ) (G := Fin p.r)\n      (fun i : Incidence arity => coordinate i.1 i.2) Sigma.fst p.Q p.R :=\n  builtLayout (fun i : Incidence arity => coordinate i.1 i.2) Sigma.fst\n    defaultEnumerations p.epsilon p.R\n\n/-- Literal coefficient bound after original-coordinate pullback. -/\ndef height (p : Parameters arity coordinate) : ℕ := p.B * 2 * (8 * p.Q) ^ (2 * p.R)\n\ntheorem layout_height (p : Parameters arity coordinate) (t : Fin p.Q) (g : Fin p.r)\n    (j : Fin ((layout p).rowCount t g)) (v : {v : A // (layout p).head t v = g}) :\n    |(layout p).constraints t g j v| ≤ (height p : ℤ) := by\n  exact builtLayout_constraints_abs_le _ _ _ _ _ _ p.occurrences (by have := p.nodes; omega)\n    (Nat.le_trans (Nat.le_add_right _ _) (OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart_end_le\n      p.groups p.degree p.size)) t g j v\n\n/-- The bounded selected-row certificate at an actual source node. -/\ndef nodeDesign (p : Parameters arity coordinate) (t : Fin p.Q) :\n    NodeCertificate arity (nodeRows (layout p) arity (fun e i => ⟨e, i⟩) t) :=\n  nodeCertificate (layout p) arity (fun e i => ⟨e, i⟩) (by intro e i; rfl) t\n    (fun _ => height p) (layout_height p t)\n\n/-- The actual total rank of the constructed integer constraints. -/\ndef totalRank (p : Parameters arity coordinate) (t : Fin p.Q) : ℕ :=\n  ∑ g, LayoutRank.rowRank ((layout p).constraints t g)\n\n/-- The cardinality of the full finite tuple of stored summaries. -/\ndef summaryCount (p : Parameters arity coordinate) (t : Fin p.Q) : ℕ :=\n  Nat.card ((g : Fin p.r) → (nodeDesign p t).Summary g)\n\ntheorem summary_count (p : Parameters arity coordinate) (t : Fin p.Q) :\n    summaryCount p t = ∏ g,\n      (2 * (Fintype.card {v : A // (layout p).head t v = g} * height p) + 1) ^\n        LayoutRank.rowRank ((layout p).constraints t g) := by\n  let : Fintype ((g : Fin p.r) → (nodeDesign p t).Summary g) :=\n    nodeCertificateTupleFinite (layout p) arity (fun e i => ⟨e, i⟩)\n      (by intro e i; rfl) t (fun _ => height p) (layout_height p t)\n  exact (Nat.card_eq_fintype_card).trans\n    (nodeCertificate_summary_card (layout p) arity (fun e i => ⟨e, i⟩)\n      (by intro e i; rfl) t (fun _ => height p) (layout_height p t))\n\n/-- A common summary box with an exponent equal to the actual selected rank. -/\ntheorem summary_count_le (p : Parameters arity coordinate) (t : Fin p.Q) :\n    summaryCount p t ≤ (2 * (Fintype.card A * height p) + 1) ^ totalRank p t := by\n  rw [summary_count]\n  calc\n    _ ≤ ∏ g : Fin p.r, (2 * (Fintype.card A * height p) + 1) ^\n        LayoutRank.rowRank ((layout p).constraints t g) := by\n      apply Finset.prod_le_prod\n      intro g _\n      apply Nat.pow_le_pow_left\n      have hc := Fintype.card_le_of_injective\n        (fun v : {v : A // (layout p).head t v = g} => v.val) Subtype.val_injective\n      exact Nat.add_le_add_right (Nat.mul_le_mul_left 2 (Nat.mul_le_mul_right _ hc)) 1\n    _ = _ := Finset.prod_pow_eq_pow_sum _ _ _\n\n/-- The rank budget is a theorem about these constructed rows, assuming only\nthe source's public incidence, load and spectral-width guards. -/\ntheorem totalRank_le (p : Parameters arity coordinate) (a : ℕ)\n    (h : PackingGuard (fun i : Incidence arity => coordinate i.1 i.2) Sigma.fst\n      p.r p.Q p.epsilon p.B a)\n    (hwidth : 32 * ((p.Q - 1 : ℕ) : ℝ) * Real.log (2 / (p.epsilon : ℝ)) ≤ (p.R : ℝ)^2)\n    (t : Fin p.Q) :\n    (totalRank p t : ℚ) ≤ 2 * p.epsilon * Fintype.card (Incidence arity) := by\n  simpa only [totalRank, Nat.cast_sum, layout] using\n    builtLayout_total_rank (fun i : Incidence arity => coordinate i.1 i.2) Sigma.fst\n      defaultEnumerations p.epsilon p.R p.B a h p.groups p.nodes p.degree p.size hwidth t\n\n/-- The same certificate at the Hermite counter's positive rational sample node. -/\ndef design (p : Parameters arity coordinate) (t : samplePoints p.Q) :\n    NodeCertificate arity (fun e i v => ((layout p).row ⟨e, i⟩ v).eval t) := by\n  have h := nodeDesign p ((sampleEquiv p.Q).symm t)\n  change NodeCertificate arity (fun e i v =>\n    ((layout p).row ⟨e, i⟩ v).eval ((layout p).node ((sampleEquiv p.Q).symm t))) at h\n  have hv : (layout p).node ((sampleEquiv p.Q).symm t) = t.val :=\n    sampleEquiv_symm_value p.Q t\n  rw [hv] at h\n  exact h\n\n/-- The counter problem built solely from original tables, coordinates and parameters. -/\ndef problem (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate) : Problem A E where\n  arity := arity\n  table := table\n  coordinate := coordinate\n  coverage := coverage\n  rows := fun e i v => (layout p).row ⟨e, i⟩ v\n  Q := p.Q\n  R := p.R\n  Q_pos := by have := p.nodes; omega\n  design := design p\n  row_degree := fun e i v => (layout p).row_degree ⟨e, i⟩ v\n  restoration := fun e i v => (layout p).row_origin ⟨e, i⟩ v\n\n/-- Exact prefix counts with no supplied layout, row span, measurement certificate,\nor count-correctness premise. -/\ntheorem constructed_prefix_count\n    (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate)\n    (fixed : List (A × Bool)) :\n    prefixCount (problem table coverage p) fixed =\n      acceptedCount (restricted assignmentBit (originalPredicate arity table coordinate) fixed) :=\n  prefixCount_eq_accepted (problem table coverage p) fixed\n\n/-- Search using the constructed exact counter returns bits of one common original\naccepting assignment. This does not assert a primitive running-time bound. -/\ntheorem constructed_search_sound\n    (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate)\n    (indices : List A) (values : List (A × Bool))\n    (h : (counterSearch (problem table coverage p) indices).values = some values) :\n    values.map Prod.fst = indices ∧ ∃ x,\n      originalPredicate arity table coordinate x = true ∧\n      ∀ pair ∈ values, assignmentBit x pair.1 = pair.2 :=\n  counterSearch_some_sound (problem table coverage p) indices values h\n\n/-- A failed constructed search exactly characterizes an empty original solution set. -/\ntheorem constructed_search_none\n    (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate)\n    (indices : List A) :\n    (counterSearch (problem table coverage p) indices).values = none ↔\n      ¬ ∃ x, originalPredicate arity table coordinate x = true :=\n  counterSearch_none_iff (problem table coverage p) indices\n\n/-- Prefix recovery needs one initial constructed count and at most one per bit. -/\ntheorem constructed_search_queries\n    (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate)\n    (indices : List A) :\n    (counterSearch (problem table coverage p) indices).queries ≤ indices.length + 1 :=\n  counterSearch_queries_le (problem table coverage p) indices\n\n#print axioms constructed_prefix_count\n#print axioms constructed_search_sound\nend\nend RiemannGaussian.SemiprimeConstructedCounter\n","RiemannGaussian.SemiprimeD1ActualCallPolynomialAggregation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ActualCallAggregation\n\n/-! # Squared local branching overhead aggregates cubically\nAll sums use the literal actual child inventory and compatible remaining fuel.\nThe lemma is proof-only; it supplies no executable counter callback or cost.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1ActualCallPolynomialAggregation\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallState\n\n/-- Nonnegative scalar cubes sum to at most the cube of their total. -/\ntheorem sum_cubes (xs : List ℕ) : (xs.map (fun x => x^3)).sum ≤ xs.sum^3 := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    simp only [List.map_cons,List.sum_cons]\n    apply (Nat.add_le_add_left ih _).trans\n    nlinarith only [Nat.zero_le (x*x*xs.sum),Nat.zero_le (x*xs.sum*xs.sum)]\n\n/-- Positive child counts dominate their actual list length. -/\ntheorem length_le_sum (xs : List ℕ) (hx : ∀x∈xs,1 ≤ x) : xs.length ≤ xs.sum := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    have hh:=hx x (by simp)\n    have ht:=ih (by intro y hy;exact hx y (by simp [hy]))\n    simp only [List.length_cons,List.sum_cons]\n    omega\n\n/-- The local squared branching term and all child cubic terms fit one cube. -/\ntheorem step_budget (xs : List ℕ) (hx : ∀x∈xs,1 ≤ x) :\n    (xs.length+1)^2+(xs.map (fun x => x^3)).sum ≤ (1+xs.sum)^3 := by\n  have hl:=Nat.pow_le_pow_left (Nat.add_le_add_right (length_le_sum xs hx) 1) 2\n  have hc:=sum_cubes xs\n  nlinarith only [hl,hc,Nat.zero_le (xs.sum*xs.sum),Nat.zero_le xs.sum]\n\n/-- Every actual finite call inventory includes its current call. -/\ntheorem count_positive (s fuel : ℕ) (c : Call) : 1 ≤ count s fuel c := by\n  cases fuel <;> simp only [count] <;> omega\n\n/-- An actual local squared-degree envelope gives a cubic total-call overhead,\nwithout charging nonexistent remaining-fuel states. -/\ntheorem report_le_count_cube (s fuel threshold B : ℕ) (root : Call)\n    (report contribution : ℕ → Call → ℕ)\n    (hzero : ∀c,report 0 c=contribution 0 c)\n    (hsucc : ∀f c,report (f+1) c=contribution (f+1) c+\n      ((children s c).map (report f)).sum)\n    (hinv : threshold ≤ root.depth+fuel)\n    (hleaf : ∀c,Reach s root c → threshold ≤ c.depth → contribution 0 c ≤ B)\n    (hlocal : ∀c,Reach s root c → ∀f ≤ fuel,threshold ≤ c.depth+f →\n      contribution f c ≤ B*((children s c).length+1)^2) :\n    report fuel root ≤ B*(count s fuel root)^3 := by\n  have go : ∀f ≤ fuel,∀c,Reach s root c → threshold ≤ c.depth+f →\n      report f c ≤ B*(count s f c)^3 := by\n    intro f\n    induction f with\n    | zero =>\n      intro hf c hr hi\n      rw [hzero]\n      simp only [count,Nat.one_pow,Nat.mul_one]\n      exact hleaf c hr (by omega)\n    | succ f ih =>\n      intro hf c hr hi\n      have hs : ((children s c).map (report f)).sum ≤\n          ((children s c).map (fun child => B*(count s f child)^3)).sum := by\n        apply List.sum_le_sum\n        intro child hc\n        apply ih (by omega) child (Reach.step hr hc)\n        rw [mem_children_depth s c child hc]\n        omega\n      rw [hsucc,count]\n      have hstep:=step_budget ((children s c).map (count s f)) (by\n        intro x hx\n        obtain ⟨child,hc,rfl⟩:=List.mem_map.mp hx\n        exact count_positive s f child)\n      simp only [List.length_map,List.map_map,Function.comp_def] at hstep\n      rw [List.sum_map_mul_left] at hs\n      have hl:=hlocal c hr (f+1) hf hi\n      calc\n        _ ≤ B*((children s c).length+1)^2+\n            B*(((children s c).map (fun child => (count s f child)^3)).sum) := Nat.add_le_add hl hs\n        _ = B*(((children s c).length+1)^2+\n            (((children s c).map (fun child => (count s f child)^3)).sum)) := by ring\n        _ ≤ _ := Nat.mul_le_mul_left B hstep\n  exact go fuel le_rfl root Reach.root hinv\n\nend RiemannGaussian.SemiprimeD1ActualCallPolynomialAggregation\n","RiemannGaussian.SemiprimeD1AffineCoefficient":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Acquired single coefficient of an actual affine-row product\nOnly rows, literal coefficient lists and the acquired exponent tuple are runtime\ninputs. No polynomial, coefficient table or desired coefficient answer executes.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1AffineCoefficient\n\n/-- Actual affine row base and finite mode-coefficient list. -/\nstructure Row (R : Type*) where\n  /-- Coefficient of the constant monomial. -/\n  base : R\n  /-- Mode coefficients in literal0-based order. -/\n  coefficients : List R\n\n/-- Cached generic-ring result with separate ring-operation and native control work. -/\nstructure Run (R : Type*) where\n  /-- Actual acquired scalar. -/\n  value : R\n  /-- All generic-ring additions and multiplications. -/\n  ringOps : ℕ\n  /-- Actual tuple/list reads, copies and finite native control. -/\n  control : ℕ\n\n/-- Combined scoped report, not a full physical-ring-word clock. -/\ndef Run.work {R : Type*} (out : Run R) : ℕ := out.ringOps+out.control\n\n/-- Actual cached-list read and its finite traversal report. -/\ndef read {R : Type*} (default : R) : List R→ℕ→R×ℕ\n  | [],_ => (default,1)\n  | v::_,0 => (v,3)\n  | _::vs,i+1 => let tail:=read default vs i;(tail.1,tail.2+3)\n\n/-- Actual list lookup has the literal original value. -/\ntheorem read_value {R : Type*} (default : R) (vs : List R) (i : ℕ) :\n    (read default vs i).1=vs.getD i default := by\n  induction vs generalizing i with\n  | nil => simp [read]\n  | cons v vs ih => cases i <;> simp [read,ih]\n\n/-- Actual full tuple copy, used at the decreased coordinate's suffix. -/\ndef copyTuple : List ℕ→List ℕ×ℕ\n  | [] => ([],1)\n  | b::bs => let tail:=copyTuple bs;(b::tail.1,tail.2+3)\n\n/-- Acquired tuple copies preserve every original exponent. -/\ntheorem copyTuple_value (beta : List ℕ) : (copyTuple beta).1=beta := by\n  induction beta with\n  | nil => rfl\n  | cons b bs ih => simp [copyTuple,ih]\n\n/-- Decrement one actual mode exponent; NativeNat subtraction is explicit metadata. -/\ndef decrement : List ℕ→ℕ→List ℕ×ℕ\n  | [],_ => ([],1)\n  | b::bs,0 => let tail:=copyTuple bs;((b-1)::tail.1,tail.2+4)\n  | b::bs,i+1 => let tail:=decrement bs i;(b::tail.1,tail.2+3)\n\n/-- No branch alters the acquired tuple shape. -/\ntheorem decrement_length (beta : List ℕ) (i : ℕ) : (decrement beta i).1.length=beta.length := by\n  induction beta generalizing i with\n  | nil => rfl\n  | cons b bs ih => cases i <;> simp [decrement,copyTuple_value,ih]\n\n/-- Exact original exponent at EVERY coordinate after the literal decrement. -/\ntheorem decrement_getD (beta : List ℕ) (i j : ℕ) :\n    (decrement beta i).1.getD j 0=if j=i then beta.getD j 0-1 else beta.getD j 0 := by\n  induction beta generalizing i j with\n  | nil => simp [decrement]\n  | cons b bs ih =>\n    cases i with\n    | zero => cases j <;> simp [decrement,copyTuple_value]\n    | succ i =>\n      cases j with\n      | zero => simp [decrement]\n      | succ j =>\n        simpa only [decrement,List.getD_cons_succ,Nat.succ.injEq] using ih i j\n\n/-- The copied tuple denotes precisely exponent subtraction, not an advised target. -/\ntheorem decrement_finsupp (beta : List ℕ) (i : ℕ) :\n    (decrement beta i).1.toFinsupp=beta.toFinsupp-Finsupp.single i 1 := by\n  ext j\n  simp only [List.toFinsupp_apply,decrement_getD,Finsupp.tsub_apply,Finsupp.single_apply]\n  by_cases h : j=i\n  · subst j;simp\n  · simp [h,Ne.symm h]\n\n/-- Actual all-zero scan used at the row recursion's terminal leaf. -/\ndef zeroTest : List ℕ→Bool×ℕ\n  | [] => (true,1)\n  | b::bs => let tail:=zeroTest bs;(decide (b=0)&&tail.1,tail.2+3)\n\n/-- A literal tuple head is zero separately from its entire tail. -/\ntheorem cons_finsupp_zero (b : ℕ) (bs : List ℕ) :\n    (b::bs).toFinsupp=0 ↔ b=0 ∧ bs.toFinsupp=0 := by\n  constructor\n  · intro h\n    constructor\n    · have hz:=congrArg (fun f : ℕ→₀ℕ => f 0) h\n      simpa only [List.toFinsupp_apply,List.getD_cons_zero,Finsupp.zero_apply] using hz\n    · ext i\n      have hz:=congrArg (fun f : ℕ→₀ℕ => f (i+1)) h\n      simpa only [List.toFinsupp_apply,List.getD_cons_succ,Finsupp.zero_apply] using hz\n  · rintro ⟨hb,ht⟩\n    ext i\n    cases i with\n    | zero => simpa only [List.toFinsupp_apply,List.getD_cons_zero,Finsupp.zero_apply] using hb\n    | succ i =>\n      have hz:=congrArg (fun f : ℕ→₀ℕ => f i) ht\n      simpa only [List.toFinsupp_apply,List.getD_cons_succ,Finsupp.zero_apply] using hz\n\n/-- Terminal leaf scan is exactly the zero exponent test. -/\ntheorem zeroTest_value (beta : List ℕ) : (zeroTest beta).1=true ↔ beta.toFinsupp=0 := by\n  induction beta with\n  | nil => simp [zeroTest]\n  | cons b bs ih => simp [zeroTest,ih,cons_finsupp_zero]\n\n/-- Cache all branch reports, summing actual scalars and retaining every clock. -/\ndef sumRuns {R : Type*} [AddMonoid R] : List (Run R)→Run R\n  | [] => ⟨0,0,1⟩\n  | r::rs =>\n    let tail:=sumRuns rs\n    ⟨r.value+tail.value,r.ringOps+tail.ringOps+1,r.control+tail.control+3⟩\n\n/-- Actual branch accumulation is the sum of its acquired branch values. -/\ntheorem sumRuns_value {R : Type*} [AddMonoid R] (rs : List (Run R)) :\n    (sumRuns rs).value=(rs.map Run.value).sum := by\n  induction rs with\n  | nil => rfl\n  | cons r rs ih => simp only [sumRuns,List.map_cons,List.sum_cons,ih]\n\n/-- Recursion visits only the requested coefficient's actual predecessor tuples.\nEach branch is acquired ONCE into the finite branch-report list. -/\ndef evaluate {R : Type*} [CommRing R] (K : ℕ) : List (Row R)→List ℕ→Run R\n  | [],beta =>\n    let test:=zeroTest beta\n    ⟨if test.1 then 1 else 0,0,test.2+2⟩\n  | row::rows,beta =>\n    let base:=evaluate K rows beta\n    let branches:=(List.range K).map (fun i =>\n      let exponent:=read 0 beta i\n      if exponent.1=0 then (⟨0,0,exponent.2+3⟩ : Run R)\n      else\n        let target:=decrement beta i\n        let child:=evaluate K rows target.1\n        let coeff:=read 0 row.coefficients i\n        ⟨coeff.1*child.value,child.ringOps+1,\n          exponent.2+target.2+child.control+coeff.2+5⟩)\n    let total:=sumRuns branches\n    ⟨row.base*base.value+total.value,base.ringOps+total.ringOps+2,\n      base.control+total.control+10*K+8⟩\n\n/-- Actual affine row's mathematical polynomial; never executed by evaluate. -/\nnoncomputable def rowPolynomial {R : Type*} [CommRing R] (K : ℕ) (row : Row R) : MvPolynomial ℕ R :=\n  MvPolynomial.C row.base+\n    ((List.range K).map (fun i => MvPolynomial.C (row.coefficients.getD i 0)*MvPolynomial.X i)).sum\n\n/-- Literal product of the original finite affine rows. -/\nnoncomputable def polynomial {R : Type*} [CommRing R] (K : ℕ) (rows : List (Row R)) : MvPolynomial ℕ R :=\n  (rows.map (rowPolynomial K)).prod\n\n/-- The additive coefficient identity, avoiding deprecated polynomial aliases. -/\ntheorem coefficient_add {R : Type*} [CommRing R] (p q : MvPolynomial ℕ R) (e : ℕ→₀ℕ) :\n    (p+q).coeff e=p.coeff e+q.coeff e := (MvPolynomial.lcoeff R e).map_add p q\n\n/-- One selected linear mode contributes exactly the decremented requested exponent. -/\ntheorem mode_coefficient {R : Type*} [CommRing R] (c : R) (i : ℕ)\n    (p : MvPolynomial ℕ R) (beta : List ℕ) :\n    (MvPolynomial.C c*MvPolynomial.X i*p).coeff beta.toFinsupp=\n      if beta.getD i 0=0 then 0 else c*p.coeff (decrement beta i).1.toFinsupp := by\n  rw [mul_assoc,MvPolynomial.coeff_C_mul,MvPolynomial.coeff_X_mul']\n  simp [decrement_finsupp]\n\n/-- Finite row-mode sum has the exact coefficient recurrence. -/\ntheorem modes_coefficient {R : Type*} [CommRing R] (indices : List ℕ) (row : Row R)\n    (p : MvPolynomial ℕ R) (beta : List ℕ) :\n    (((indices.map (fun i => MvPolynomial.C (row.coefficients.getD i 0)*MvPolynomial.X i)).sum)*p).coeff\n      beta.toFinsupp=\n      (indices.map (fun i => if beta.getD i 0=0 then 0 else\n        row.coefficients.getD i 0*p.coeff (decrement beta i).1.toFinsupp)).sum := by\n  induction indices with\n  | nil => simp\n  | cons i indices ih =>\n    simp only [List.map_cons,List.sum_cons,add_mul,coefficient_add,mode_coefficient,ih]\n\n/-- The acquired single coefficient is EXACT for every original tuple/row list.\nNo dense polynomial or target coefficient answer is a runtime input. -/\ntheorem evaluate_value {R : Type*} [CommRing R] (K : ℕ) (rows : List (Row R)) (beta : List ℕ) :\n    (evaluate K rows beta).value=(polynomial K rows).coeff beta.toFinsupp := by\n  induction rows generalizing beta with\n  | nil =>\n    simp only [evaluate,polynomial,List.map_nil,List.prod_nil,MvPolynomial.coeff_one]\n    by_cases h : beta.toFinsupp=0\n    · simp [h,(zeroTest_value beta).mpr h]\n    · have hn : (zeroTest beta).1≠true := fun hz => h ((zeroTest_value beta).mp hz)\n      simp [Ne.symm h,hn]\n  | cons row rows ih =>\n    simp only [evaluate,polynomial,List.map_cons,List.prod_cons,rowPolynomial,add_mul,\n      coefficient_add,MvPolynomial.coeff_C_mul,modes_coefficient,read_value,sumRuns_value,\n      List.map_map,Function.comp_def]\n    rw [ih beta]\n    congr 1\n    congr 1\n    apply List.map_congr_left\n    intro i _\n    by_cases h : beta.getD i 0=0\n    · simp only [h,ite_true]\n    · simp only [h,ite_false]\n      exact congrArg (fun x => row.coefficients.getD i 0*x) (ih (decrement beta i).1)\n\n/-- Finite acquired mode-tuple interpretation for the actual weighted menu. -/\nnoncomputable def betaF (K : ℕ) (beta : List ℕ) : Fin K→₀ℕ :=\n  Finsupp.equivFunOnFinite.symm (fun i => beta.getD i.val 0)\n\n/-- Finite exponent interpretation reads the original acquired list entry. -/\ntheorem betaF_apply (K : ℕ) (beta : List ℕ) (i : Fin K) : betaF K beta i=beta.getD i.val 0 := rfl\n\n/-- Actual menu shape gives exact list recovery, with no exponent-value advice. -/\ntheorem betaF_inverse (K : ℕ) (beta : List ℕ) (h : beta.length=K) :\n    List.ofFn (fun i : Fin K => betaF K beta i)=beta := by\n  subst K\n  have hf : (fun i : Fin beta.length => betaF beta.length beta i)=\n      (fun i : Fin beta.length => beta[i.val]) := by\n    funext i\n    rw [betaF_apply]\n    exact List.getD_eq_getElem beta 0 i.isLt\n  rw [hf]\n  exact List.ofFn_getElem\n\n/-- Nat-mode polynomial exponents are the literal embedding of the acquiredFinK tuple. -/\ntheorem betaF_embDomain (K : ℕ) (beta : List ℕ) (h : beta.length=K) :\n    Finsupp.embDomain (Fin.valEmbedding : Fin K↪ℕ) (betaF K beta)=beta.toFinsupp := by\n  ext j\n  by_cases hj : j<K\n  · let i : Fin K:=⟨j,hj⟩\n    change (Finsupp.embDomain (Fin.valEmbedding : Fin K↪ℕ) (betaF K beta)) ((Fin.valEmbedding : Fin K↪ℕ) i)=_\n    rw [Finsupp.embDomain_apply_self,betaF_apply,List.toFinsupp_apply]\n  · have hn : j∉Set.range (Fin.valEmbedding : Fin K↪ℕ) := by\n      rintro ⟨i,hi⟩\n      exact hj (hi ▸ i.isLt)\n    rw [Finsupp.embDomain_of_notMem_range _ _ _ hn]\n    symm\n    exact List.toFinsupp_apply_le beta j (by omega)\n\nend RiemannGaussian.SemiprimeD1AffineCoefficient\n","RiemannGaussian.SemiprimeD1AuxiliaryRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PackingReady\n\n/-! # Auxiliary table and rank exponents fit the explicit main scale\nThe actual rounded degree cap and every fixed logarithmic power are paid at\ns/sqrt(clog2(s+2)), rather than merely described as sublinear. This arithmetic\nlemma does not identify any retained report with a primitive-machine runtime.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1AuxiliaryRate\nopen Filter SemiprimeD1PackingReady\nopen scoped Topology\n\n/-- Every fixed actual ceiling-log power is eventually below the original size. -/\ntheorem eventually_log_power (k : ℕ) : ∀ᶠ s : ℕ in atTop,(logarithm s)^k ≤ s := by\n  have hlog := (tendsto_add_atTop_nat 2).eventually\n    (SemiprimeSourceLayoutRate.eventually_clog_power_le_rpow k (1/2) (by norm_num))\n  filter_upwards [hlog,eventually_ge_atTop (3:ℕ)] with s hl hs\n  rw [←Real.sqrt_eq_rpow] at hl\n  have hsR : (3:ℝ) ≤ s := by exact_mod_cast hs\n  have hroot : Real.sqrt (s+2:ℕ) ≤ (s:ℝ) := by\n    apply (Real.sqrt_le_left (by positivity)).mpr\n    push_cast\n    nlinarith [sq_nonneg ((s:ℝ)-2)]\n  exact_mod_cast hl.trans hroot\n\n/-- Rounding the actual nine-tenths logarithmic exponent costs a fixed factor. -/\ntheorem degreeCap_tenth (s : ℕ) (hs : 2 ≤ s) (hl : 2 ≤ logarithm s) :\n    (degreeCap s)^10 ≤ 2^27*s^9 := by\n  have hp := root_power s hs hl\n  have he : ((9*logarithm s+9)/10)*10 ≤ 9*(logarithm s-2)+27 := by omega\n  calc\n    _ = 2^(((9*logarithm s+9)/10)*10) := by rw [degreeCap,←pow_mul]\n    _ ≤ 2^(9*(logarithm s-2)+27) := Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) he\n    _ = 2^27*(2^(logarithm s-2))^9 := by\n      rw [pow_add,Nat.mul_comm 9 (logarithm s-2),pow_mul]\n      exact Nat.mul_comm _ _\n    _ ≤ _ := Nat.mul_le_mul_left _ (Nat.pow_le_pow_left hp 9)\n\n/-- The actual complete-table exponent leaves a full logarithmic reserve. -/\ntheorem eventually_degree_times_log : ∀ᶠ s : ℕ in atTop,degreeCap s*logarithm s ≤ s := by\n  have ht : Tendsto logarithm atTop atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  filter_upwards [eventually_log_power 11,eventually_ge_atTop (2:ℕ),\n    ht.eventually (eventually_ge_atTop (2^27:ℕ))] with s hlog hs hl\n  have hltwo : 2 ≤ logarithm s := by omega\n  have hd := degreeCap_tenth s hs hltwo\n  have hreserve : 2^27*(logarithm s)^10 ≤ s := by\n    calc\n      _ ≤ logarithm s*(logarithm s)^10 := Nat.mul_le_mul_right _ hl\n      _ = (logarithm s)^11 := by ring\n      _ ≤ s := hlog\n  have hpower : (degreeCap s*logarithm s)^10 ≤ s^10 := by\n    calc\n      _ = (degreeCap s)^10*(logarithm s)^10 := by rw [mul_pow]\n      _ ≤ (2^27*s^9)*(logarithm s)^10 := Nat.mul_le_mul_right _ hd\n      _ = s^9*(2^27*(logarithm s)^10) := by ring\n      _ ≤ s^9*s := Nat.mul_le_mul_left _ hreserve\n      _ = s^10 := by ring\n  exact (Nat.pow_le_pow_iff_left (by decide : (10:ℕ) ≠ 0)).mp hpower\n\n/-- A fixed cubic logarithmic exponent leaves the same reserve. -/\ntheorem eventually_log_fourth : ∀ᶠ s : ℕ in atTop,(logarithm s+1)^4 ≤ s := by\n  have ht : Tendsto logarithm atTop atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  filter_upwards [eventually_log_power 5,ht.eventually (eventually_ge_atTop (16:ℕ))] with s hp hl\n  calc\n    _ ≤ (2*logarithm s)^4 := Nat.pow_le_pow_left (by omega) 4\n    _ = 16*(logarithm s)^4 := by ring\n    _ ≤ logarithm s*(logarithm s)^4 := Nat.mul_le_mul_right _ hl\n    _ = (logarithm s)^5 := by ring\n    _ ≤ s := hp\n\n/-- Both actual auxiliary exponent types are absorbed at the quantitative\nrequested scale. No extra logarithmic loss is introduced by this estimate. -/\ntheorem eventually_auxiliary_rate : ∀ᶠ s : ℕ in atTop,\n    ((degreeCap s+(logarithm s+1)^3:ℕ):ℝ) ≤\n      2*(s:ℝ)/Real.sqrt (logarithm s:ℕ) := by\n  have ht : Tendsto logarithm atTop atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  filter_upwards [eventually_degree_times_log,eventually_log_fourth,\n    ht.eventually (eventually_ge_atTop (1:ℕ))] with s hd hp hl\n  have hlR : (1:ℝ) ≤ logarithm s := by exact_mod_cast hl\n  have hroot : 0 < Real.sqrt (logarithm s:ℕ) := Real.sqrt_pos.mpr (by positivity)\n  have hsqrt : Real.sqrt (logarithm s:ℕ) ≤ (logarithm s:ℝ) := by\n    have hh := Real.sq_sqrt (show (0:ℝ) ≤ logarithm s by positivity)\n    nlinarith [Real.sqrt_nonneg (logarithm s:ℕ)]\n  have hdR : (degreeCap s:ℝ)*(logarithm s:ℝ) ≤ s := by exact_mod_cast hd\n  have hpR : ((logarithm s:ℝ)+1)^4 ≤ s := by exact_mod_cast hp\n  apply (le_div_iff₀ hroot).mpr\n  push_cast\n  have hdegree := mul_le_mul_of_nonneg_left hsqrt (show (0:ℝ) ≤ degreeCap s by positivity)\n  have hpoly := mul_le_mul_of_nonneg_left (hsqrt.trans (le_add_of_nonneg_right zero_le_one))\n    (show (0:ℝ) ≤ ((logarithm s:ℝ)+1)^3 by positivity)\n  nlinarith\n\nend RiemannGaussian.SemiprimeD1AuxiliaryRate\n","RiemannGaussian.SemiprimeD1ChildModeResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildOriginalFields\nimport RiemannGaussian.SemiprimeD1CatalogSize\n\n/-! # Actual original catalogue dimension and eager packet exponential\nThe catalogue is acquired from literal packets and computed precision. The\nnaive physical coefficient recursion plus all table assignments fits the fixed\noriginal degree envelope; no catalogue or coefficient-count answer is given.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 140000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1ChildModeResources\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkRecursion\n\n/-- Actual complete descriptor dimension for this original acquired node. -/\ndef catalogueLength (net : Network) (a u : ℕ) (i : Fin a) (p : ℕ) : ℕ :=\n  let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n    a u i.val p (arity net.rows) (owner net.rows)\n  (SemiprimeD1ModeCatalog.catalog (source.packets.state.packets.length*2^(i.val+1))\n    (source.precision-1)).length\n\n/-- The actual catalogue has a derived fixed quadratic original-scope bound. -/\ntheorem catalogue_quadratic (net : Network) (hw : WellFormed net) (D a u : ℕ) (i : Fin a) (p : ℕ)\n    (hd : DegreeBound net D) (hsmall : 2*(64^(2*a))^2*D ≤ edgeCount net)\n    (hsize : 64^(2*a)*2^a ≤ edgeCount net) (hu : 0 < u) (huM : u ≤ edgeCount net)\n    (hp : p*u ≤ edgeCount net*2^(a-i.val)) (ha : (a+1)*u ≤ 2^(a-i.val)) :\n    catalogueLength net a u i p ≤ 246*(edgeCount net)^2 := by\n  have hdegree := original_degree_contract net hw D a hd\n  have hM : (SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length a (arity net.rows)).length =\n      edgeCount net := by rw [SemiprimeD1TensorNetworkLayout.original_ports];rfl\n  have hpack := SemiprimeD1PacketReplayCapacity.threeM_capacity net.leftCount net.rows.length 64 a\n    (arity net.rows) (owner net.rows) D hdegree.1 hdegree.2 (by rw [hM];exact hsmall)\n    (by rw [hM];exact hsize)\n  rw [hM] at hpack\n  have h := SemiprimeD1CatalogSize.catalog_quadratic\n    (SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length 64 a\n      (arity net.rows) (owner net.rows)).state.packets.length\n    (edgeCount net) u a i.val p i.isLt.le hpack hu huM hp ha\n  change (SemiprimeD1ModeCatalog.catalog _\n    ((SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64 a u i.val p\n      (arity net.rows) (owner net.rows)).precision-1)).length ≤ _\n  rw [SemiprimeD1OriginalModeAcquisition.precision_original,SemiprimeD1TensorNetworkLayout.original_ports]\n  exact h\n\n/-- Actual original packet scopes fit the same fixed global stored-degree cap. -/\ntheorem slots_bound (lam a : ℕ) (hlam : 1000 ≤ lam) (ha : a ≤ 4*(lam/131072)) :\n    2*2^a ≤ 2^((9*lam+9)/10) := by\n  have h := (SemiprimeD1PackingReady.exponent_margin lam hlam).2\n  rw [←pow_succ']\n  exact Nat.pow_le_pow_right (by decide) (by omega)\n\n/-- Literal truth-table materialization and naive affine coefficient recursion\nare both absorbed by the original global degree envelope. -/\ntheorem coefficient_envelope (net : Network) (hw : WellFormed net) (lam a u : ℕ)\n    (i : Fin a) (p : ℕ) (hlam : 1000 ≤ lam) (haSmall : a ≤ 4*(lam/131072))\n    (hM : edgeCount net ≤ 2^lam)\n    (hd : DegreeBound net (2^((9*lam+9)/10)))\n    (hsmall : 2*(64^(2*a))^2*(2^((9*lam+9)/10)) ≤ edgeCount net)\n    (hsize : 64^(2*a)*2^a ≤ edgeCount net) (hu : 0 < u) (huM : u ≤ edgeCount net)\n    (hp : p*u ≤ edgeCount net*2^(a-i.val)) (ha : (a+1)*u ≤ 2^(a-i.val)) :\n    2^(2*2^a)*(catalogueLength net a u i p+1)^(2*2^a) ≤ 2^(2^((9*lam+9)/10)) := by\n  have hK := catalogue_quadratic net hw _ a u i p hd hsmall hsize hu huM hp ha\n  have hbin := SemiprimeD1CatalogSize.quadratic_binary (edgeCount net) lam (catalogueLength net a u i p) hM hK\n  exact SemiprimeD1CatalogSize.packet_coefficient_envelope lam a _ (2*2^a) hlam haSmall hbin le_rfl\n\nend RiemannGaussian.SemiprimeD1ChildModeResources\n","RiemannGaussian.SemiprimeD1ChildNetworkClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildClockFactor\n\n/-! # Concrete child-network table/report composition\nThis internal composition theorem is followed by original-constructor supplier\nbounds. It retains every source, pullback, graph, header and fresh report at the\nmultiplicity of the existing runtime; there is no silent sharing of reports.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 180000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1ChildNetworkClock\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1ChildNetwork\nopen SemiprimeD1ChildTableClock SemiprimeD1PacketTableClock SemiprimeD1ChildClockFactor\n\n/-- A finite cached vector report sum is bounded by its literal number of entries. -/\ntheorem ofFn_sum_le (n : ℕ) (f : Fin n → ℕ) (B : ℕ) (h : ∀i,f i ≤ B) :\n    (List.ofFn f).sum ≤ n*B := by\n  induction n with\n  | zero => simp only [List.ofFn_zero,List.sum_nil,Nat.zero_mul,le_refl]\n  | succ n ih =>\n    rw [List.ofFn_succ,List.sum_cons]\n    have hh := h 0\n    have ht := ih (fun i => f i.succ) (fun i => h i.succ)\n    calc\n      _ ≤ B+n*B := Nat.add_le_add hh ht\n      _ = _ := by ring\n\n/-- Fixed arithmetic prefactor; source/header/routing costs occur at their\nactual vertex multiplicities, not once for the entire network. -/\ndef prefactor (old : Context) (extra : List ℕ) (p a D A K P T B L E NF Fchild links S W G Z O H : ℕ) : ℕ :=\n  S+W+G+Z+NF*leftPolynomial old extra p D O NF+\n    Fchild*rightPolynomial ⟨extra++old.axes,p⟩ a A K P T B L E H Z G Fchild+\n    10*(NF+Fchild+links+1)^3\n\n/-- Complete actual child-network report at the global eager degree scale. -/\ndef budget (old : Context) (extra : List ℕ) (p a D A K P T B L E NF Fchild links S W G Z O H : ℕ) : ℕ :=\n  prefactor old extra p a D A K P T B L E NF Fchild links S W G Z O H*2^D\n\n/-- Concrete table composition. Original numeric/table-field and metadata\nsupplier premises are all discharged by the original-source wrapper; no\nrequested entry/coefficient or intermediate physical Fits answer occurs here. -/\ntheorem fromSource_clock {r a : ℕ} (net : Network) (source : Source net a) (i : Fin a) (g : Fin r)\n    (old : Context) (extra : List ℕ) (p : ℕ) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ)\n    (D A K P T B E O H : ℕ) (hg : Good old net) (he : 0 < extra.prod)\n    (hz : SemiprimeD1JetAffineCoefficientBounds.Good ⟨extra++old.axes,p⟩ z.words)\n    (hbeta : ∀b∈beta,b ≤ B)\n    (hcoefficient : 2^A*(K+1)^A ≤ 2^D)\n    (hleft : ∀v : Fin (net.leftCount+net.rows.length),\n      let data := SemiprimeD1ChildPortPullback.fromReplay (owner net.rows) source.packets i g\n      let order := SemiprimeD1ChildTableOrder.acquire (owner net.rows) data v\n      order.old.length ≤ D ∧ order.child.length ≤ D ∧\n        (leftPorts (SemiprimeD1TensorNetworkLayout.childRows data.graph) v).length ≤ D ∧\n        (parentVertex net v).ports.length ≤ D ∧ order.clock ≤ O)\n    (hright : ∀e : Fin (SemiprimeD1TensorNetworkLayout.childRows (graph net source i g)).length,\n      let header := SemiprimeD1PacketTensorTables.prepare (owner net.rows) source (packetIndex net source i g e) i g\n      header.endpoints.length ≤ A ∧ header.masks.items.length=K ∧\n      (∀item∈header.masks.items,item.mode.order ≤ P) ∧\n      (∀item∈header.masks.items,item.tile ≤ T) ∧\n      (∀endpoint∈header.endpoints,endpoint.slot.length ≤ a) ∧\n      (∀endpoint∈header.endpoints,endpoint.edge.length ≤ E) ∧ header.clock ≤ H) :\n    let data := SemiprimeD1ChildPortPullback.fromReplay (owner net.rows) source.packets i g\n    let childGraph := graph net source i g\n    let Fchild := (SemiprimeD1TensorNetworkLayout.childRows childGraph).length\n    (fromSource net source i g old extra p z t beta).clock ≤\n      budget old extra p a D A K P T B beta.length E (net.leftCount+net.rows.length) Fchild\n        data.links.length source.work data.work childGraph.work z.clock O H := by\n  dsimp only\n  let data := SemiprimeD1ChildPortPullback.fromReplay (owner net.rows) source.packets i g\n  let childGraph := graph net source i g\n  let rows := SemiprimeD1TensorNetworkLayout.childRows childGraph\n  let L := leftPolynomial old extra p D O (net.leftCount+net.rows.length)\n  let R := rightPolynomial ⟨extra++old.axes,p⟩ a A K P T B beta.length E H z.clock childGraph.work rows.length\n  have hleftClock (v : Fin (net.leftCount+net.rows.length)) :\n      (leftOne net data old extra p v).2 ≤ L*2^D := by\n    have hv := hleft v\n    have hc := leftOne_clock net data old extra p D v hg he hv.1 hv.2.1 hv.2.2.1 hv.2.2.2.1\n    have hp := leftBudget_factor old extra p D\n      (SemiprimeD1ChildTableOrder.acquire (owner net.rows) data v).clock v.val\n    have hm : leftPolynomial old extra p D\n        (SemiprimeD1ChildTableOrder.acquire (owner net.rows) data v).clock v.val ≤ L := by\n      dsimp only [L,leftPolynomial]\n      gcongr\n      · exact hv.2.2.2.2\n      · exact v.isLt.le\n    exact hc.trans (hp.trans (Nat.mul_le_mul_right _ hm))\n  have hrightClock (e : Fin rows.length) :\n      (rightOne net source i g ⟨extra++old.axes,p⟩ z t beta e).2 ≤ R*2^D := by\n    have hv := hright e\n    have hc := rightOne_clock net source i g ⟨extra++old.axes,p⟩ z hz t beta e A K P T B E\n      hv.1 hv.2.1 hv.2.2.1 hv.2.2.2.1 hbeta hv.2.2.2.2.1 hv.2.2.2.2.2.1\n    have hp := rightClock_factor ⟨extra++old.axes,p⟩ a A K P T B beta.length E\n      (SemiprimeD1PacketTensorTables.prepare (owner net.rows) source (packetIndex net source i g e) i g).clock\n      z.clock childGraph.work e.val\n    have hm : rightPolynomial ⟨extra++old.axes,p⟩ a A K P T B beta.length E\n      (SemiprimeD1PacketTensorTables.prepare (owner net.rows) source (packetIndex net source i g e) i g).clock\n      z.clock childGraph.work e.val ≤ R := by\n      dsimp only [R,rightPolynomial,rightControls]\n      gcongr\n      · exact hv.2.2.2.2.2.2\n      · exact e.isLt.le\n    exact hc.trans (hp.trans (Nat.mul_le_mul hm hcoefficient))\n  have hls := ofFn_sum_le (net.leftCount+net.rows.length)\n    (fun v => (leftOne net data old extra p v).2) (L*2^D) hleftClock\n  have hrs := ofFn_sum_le rows.length\n    (fun e => (rightOne net source i g ⟨extra++old.axes,p⟩ z t beta e).2) (R*2^D) hrightClock\n  have hdecomp : (fromSource net source i g old extra p z t beta).clock =\n      source.work+data.work+childGraph.work+z.clock+\n      (List.ofFn (fun v => (leftOne net data old extra p v).2)).sum+\n      (List.ofFn (fun e => (rightOne net source i g ⟨extra++old.axes,p⟩ z t beta e).2)).sum+\n      10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3 := by\n    simp only [fromSource,Vector.toList_ofFn,List.map_ofFn,Function.comp_def]\n    rfl\n  rw [hdecomp]\n  have hsum := Nat.add_le_add_right (Nat.add_le_add\n    (Nat.add_le_add_left hls (source.work+data.work+childGraph.work+z.clock)) hrs)\n    (10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3)\n  apply hsum.trans\n  have hq : 1 ≤ (2:ℕ)^D := Nat.one_le_pow _ _ (by decide)\n  have ho : source.work+data.work+childGraph.work+z.clock+\n      10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3 ≤\n      (source.work+data.work+childGraph.work+z.clock+\n      10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3)*2^D := by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left _ hq\n  calc\n    _ = source.work+data.work+childGraph.work+z.clock+\n        10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3+\n        ((net.leftCount+net.rows.length)*L+rows.length*R)*2^D := by ring\n    _ ≤ (source.work+data.work+childGraph.work+z.clock+\n        10*(net.leftCount+net.rows.length+rows.length+data.links.length+1)^3)*2^D+\n        ((net.leftCount+net.rows.length)*L+rows.length*R)*2^D := Nat.add_le_add_right ho _\n    _ = _ := by unfold budget prefactor L R;ring\n\nend RiemannGaussian.SemiprimeD1ChildNetworkClock\n","RiemannGaussian.SemiprimeD1CollisionVariance":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceIncidenceHistogram\n\n/-! # Original occurrence-list collision bound for D.1 packing\nParallel ports remain separate list occurrences. Degree bounds are bounds on\nliteral original owner/factor fibres, not on a supplied collision answer.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1CollisionVariance\nopen scoped BigOperators\nopen SemiprimeSourceHistogramGrouping\n\n/-- Literal ordered occurrence-pair sum. -/\ndef pairSum {I R : Type*} [AddCommMonoid R] (xs : List I) (f : I → I → R) : R :=\n  (xs.map (fun i => (xs.map (f i)).sum)).sum\n\n/-- A uniform per-occurrence bound pays every actual list entry. -/\ntheorem sum_map_le {I : Type*} (xs : List I) (f : I → ℚ) (C : ℚ)\n    (h : ∀ i∈xs, f i≤C) : (xs.map f).sum≤(xs.length:ℚ)*C := by\n  induction xs with\n  | nil => simp\n  | cons i xs ih =>\n    have hi:=h i List.mem_cons_self\n    have ht:=ih (fun j hj => h j (List.mem_cons_of_mem i hj))\n    simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.cast_add,Nat.cast_one]\n    nlinarith\n\n/-- Exact equality-pair count is the sum of the actual fibre loads. -/\ntheorem equal_pairs {I K : Type*} [DecidableEq K] (xs : List I) (key : I→K) :\n    pairSum xs (fun i j => if key i=key j then (1:ℕ) else 0)=\n      (xs.map (fun i => multiplicity key xs (key i))).sum := by\n  unfold pairSum\n  congr 1\n  apply List.map_congr_left\n  intro i _\n  simpa only [eq_comm] using indicator_sum key xs (key i)\n\n/-- Shared endpoints are an original finite predicate, not a collision oracle. -/\ndef sharedCount {I V E : Type*} [DecidableEq V] [DecidableEq E]\n    (xs : List I) (owner : I→V) (factor : I→E) : ℕ :=\n  pairSum xs (fun i j => if owner i=owner j ∨ factor i=factor j then 1 else 0)\n\n/-- The union of two endpoint equalities has at most two fibre-load budgets. -/\ntheorem shared_count_le {I V E : Type*} [DecidableEq V] [DecidableEq E]\n    (xs : List I) (owner : I→V) (factor : I→E) (Δ : ℕ)\n    (ho : ∀ i∈xs,multiplicity owner xs (owner i)≤Δ)\n    (hf : ∀ i∈xs,multiplicity factor xs (factor i)≤Δ) :\n    sharedCount xs owner factor≤2*xs.length*Δ := by\n  have hrow (i : I) (hi : i∈xs) :\n      (xs.map (fun j => if owner i=owner j ∨ factor i=factor j then 1 else 0)).sum≤2*Δ := by\n    calc\n      _ ≤ (xs.map (fun j => (if owner i=owner j then 1 else 0)+\n            (if factor i=factor j then 1 else 0))).sum := by\n        apply List.sum_le_sum\n        intro j _\n        by_cases ho : owner i=owner j <;> by_cases hf : factor i=factor j <;> simp [ho,hf]\n      _ = multiplicity owner xs (owner i)+multiplicity factor xs (factor i) := by\n        rw [List.sum_map_add]\n        rw [show (xs.map (fun j => if owner i=owner j then 1 else 0)).sum=\n          multiplicity owner xs (owner i) by simpa only [eq_comm] using indicator_sum owner xs (owner i)]\n        rw [show (xs.map (fun j => if factor i=factor j then 1 else 0)).sum=\n          multiplicity factor xs (factor i) by simpa only [eq_comm] using indicator_sum factor xs (factor i)]\n      _ ≤ 2*Δ := by have:=ho i hi;have:=hf i hi;omega\n  unfold sharedCount pairSum\n  calc\n    _ ≤ (xs.map (fun _ => 2*Δ)).sum := by\n      apply List.sum_le_sum\n      exact hrow\n    _ = 2*xs.length*Δ := by simp [Nat.mul_comm,Nat.mul_left_comm]\n\n/-- The original all-free equality probability for one endpoint namespace. -/\ndef freePotential {K : Type*} [DecidableEq K] (L : ℚ) (a b : K) : ℚ :=\n  if a=b then 1 else 1/L\n\n/-- Away from pairs sharing an endpoint the two equalities cost exactly L². -/\ntheorem free_product_le {V E : Type*} [DecidableEq V] [DecidableEq E]\n    (L : ℚ) (hL : 1≤L) (a c : V) (b d : E) :\n    freePotential L a c*freePotential L b d≤\n      1/L^2+(if a=c ∨ b=d then 1 else 0) := by\n  have hp : 0<L := by linarith\n  have hinv : 0≤1/L := by positivity\n  have hle : 1/L≤1 := (div_le_one hp).mpr hL\n  have hs : 0≤1/L^2 := by positivity\n  by_cases ha : a=c <;> by_cases hb : b=d <;>\n    simp only [freePotential,ha,hb,ite_true,ite_false,or_self,or_true,or_false,one_mul,mul_one]\n  all_goals first | nlinarith | (field_simp;norm_num)\n\n/-- All-free expected collision mass, computed from actual original ports. -/\ndef initialCollision {I V E : Type*} [DecidableEq V] [DecidableEq E]\n    (xs : List I) (owner : I→V) (factor : I→E) (L : ℚ) : ℚ :=\n  pairSum xs (fun i j => freePotential L (owner i) (owner j)*\n    freePotential L (factor i) (factor j))\n\n/-- Initial D.3 collision bound, including parallel ports and empty graphs. -/\ntheorem initial_collision_le {I V E : Type*} [DecidableEq V] [DecidableEq E]\n    (xs : List I) (owner : I→V) (factor : I→E) (Δ : ℕ) (L : ℚ) (hL : 1≤L)\n    (ho : ∀ i∈xs,multiplicity owner xs (owner i)≤Δ)\n    (hf : ∀ i∈xs,multiplicity factor xs (factor i)≤Δ) :\n    initialCollision xs owner factor L≤(xs.length:ℚ)^2/L^2+2*xs.length*Δ := by\n  have hshared : (sharedCount xs owner factor:ℚ)≤2*xs.length*Δ := by\n    exact_mod_cast shared_count_le xs owner factor Δ ho hf\n  have he : initialCollision xs owner factor L≤\n      (xs.length:ℚ)^2/L^2+(sharedCount xs owner factor:ℚ) := by\n    unfold initialCollision sharedCount pairSum\n    push_cast\n    calc\n      _ ≤ (xs.map (fun i => (xs.map (fun j => 1/L^2+\n          (if owner i=owner j ∨ factor i=factor j then (1:ℚ) else 0))).sum)).sum := by\n        apply List.sum_le_sum\n        intro i _\n        apply List.sum_le_sum\n        intro j _\n        exact free_product_le L hL _ _ _ _\n      _ = _ := by simp [List.sum_map_add,pow_two,Function.comp_def,List.map_map];ring\n  linarith\n\n/-- Literal scaled equality kernel at an all-free key. -/\ntheorem kernel_free {W : Type*} [DecidableEq W] (L : ℚ) (hL : L≠0)\n    (remaining : List ℕ) (ω : ℕ→W) (a c : ℕ) (ha : a∈remaining) :\n    SemiprimeSourceIncidenceHistogram.kernel L remaining ω a c=\n      L*freePotential L a c := by\n  by_cases h : a=c <;> simp [SemiprimeSourceIncidenceHistogram.kernel,freePotential,h,ha,hL]\n\n/-- The actual all-free sixteen-feature scalar equals L² times the expected load. -/\ntheorem histogram_initial {I W : Type*} [DecidableEq W] (xs : List I)\n    (owner factor : I→ℕ) (remaining : List ℕ) (ω : ℕ→W) (L : ℚ) (hL : L≠0)\n    (ho : ∀ i∈xs,owner i∈remaining) (hf : ∀ i∈xs,factor i∈remaining) :\n    SemiprimeSourceIncidenceHistogram.histogramSum L xs remaining ω owner factor=\n      L^2*initialCollision xs owner factor L := by\n  rw [← SemiprimeSourceIncidenceHistogram.kernel_pairs]\n  change pairSum xs _=L^2*pairSum xs _\n  rw [← show pairSum xs (fun i j => L^2*(freePotential L (owner i) (owner j)*\n      freePotential L (factor i) (factor j)))=L^2*pairSum xs (fun i j =>\n      freePotential L (owner i) (owner j)*freePotential L (factor i) (factor j)) by\n    simp only [pairSum,List.sum_map_mul_left]]\n  unfold pairSum\n  congr 1\n  apply List.map_congr_left\n  intro i hi\n  congr 1\n  apply List.map_congr_left\n  intro j _\n  dsimp only\n  rw [kernel_free L hL remaining ω _ _ (ho i hi),kernel_free L hL remaining ω _ _ (hf i hi)]\n  ring\n\n/-- The actual initial padded incidence scalar has the original D.3 bound. -/\ntheorem padded_initial_le {I W : Type*} [DecidableEq W] (xs : List I)\n    (owner factor : I→ℕ) (remaining : List ℕ) (ω : ℕ→W) (Δ : ℕ)\n    (L : ℚ) (hL : 1≤L)\n    (hao : ∀ i∈xs,owner i∈remaining) (haf : ∀ i∈xs,factor i∈remaining)\n    (ho : ∀ i∈xs,multiplicity owner xs (owner i)≤Δ)\n    (hf : ∀ i∈xs,multiplicity factor xs (factor i)≤Δ) :\n    L^2*SemiprimeSourceIncidenceHistogram.histogramSum L xs remaining ω owner factor≤\n      L^2*(xs.length:ℚ)^2+2*xs.length*Δ*L^4 := by\n  have hp : 0<L := by linarith\n  rw [histogram_initial xs owner factor remaining ω L (ne_of_gt hp) hao haf]\n  have h:=mul_le_mul_of_nonneg_left (initial_collision_le xs owner factor Δ L hL ho hf)\n    (show 0≤L^4 by positivity)\n  have he : L^4*((xs.length:ℚ)^2/L^2+2*xs.length*Δ)=\n      L^2*(xs.length:ℚ)^2+2*xs.length*Δ*L^4 := by field_simp\n  rw [he] at h\n  nlinarith [sq_nonneg L]\n\n/-- At completion no free keys remain: equality is purely the actual label pair. -/\ntheorem histogram_terminal {I W : Type*} [DecidableEq W] (xs : List I)\n    (owner factor : I→ℕ) (ω : ℕ→W) (L : ℚ) :\n    L^2*SemiprimeSourceIncidenceHistogram.histogramSum L xs [] ω owner factor=\n      L^4*pairs xs (fun i j => if ω (owner i)=ω (owner j) ∧\n        ω (factor i)=ω (factor j) then (1:ℚ) else 0) := by\n  rw [← SemiprimeSourceIncidenceHistogram.kernel_pairs,← pairs_scale,← pairs_scale]\n  unfold pairs\n  congr 1\n  apply List.map_congr_left\n  intro i _\n  congr 1\n  apply List.map_congr_left\n  intro j _\n  dsimp only\n  by_cases ho : owner i=owner j <;> by_cases hf : factor i=factor j <;>\n    by_cases hv : ω (owner i)=ω (owner j) <;> by_cases he : ω (factor i)=ω (factor j) <;>\n    simp_all [SemiprimeSourceIncidenceHistogram.kernel] <;> ring\n\nend RiemannGaussian.SemiprimeD1CollisionVariance\n","RiemannGaussian.SemiprimeD1CurrentTableDeformation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetLiteralLift\nimport RiemannGaussian.SemiprimeD1IntegralDeformation\n\n/-! # Eager CURRENT integer-table deformation over every old nilpotent coordinate\nLiteral coefficient words, rather than creator recipes or coefficient answers,\nare lifted to one integral old-jet ring. Mapping that ring to rational and modular\nold-jet rings gives the precise commuting square at each new call precision.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1CurrentTableDeformation\nopen scoped BigOperators\nopen Polynomial SemiprimeD1JetAlgebra SemiprimeD1JetScalarMap SemiprimeD1JetBoxIndex\n  SemiprimeD1JetLiteralLift SemiprimeD1DyadicInteger SemiprimeD1IntegralDeformation\n  SemiprimeD1OriginalDeformation\nnoncomputable section\n\n/-- Scalar constants commute with the ACTUAL old-jet quotient coefficient map. -/\ntheorem constants_square {R S : Type*} [CommRing R] [CommRing S]\n    (axes : List ℕ) (f : R →+* S) :\n    (scalarMap (dims axes) f).comp (constants (dims axes))=\n      (constants (dims axes)).comp f := by\n  ext r\n  exact scalarMap_constants (dims axes) f r\n\n/-- Actual original local replay wires with coefficients in the entire old integral jet ring. -/\ndef oldWire (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) : Polynomial (Integral axes) :=\n  (localWire n F r a arity owner t i j).map (constants (dims axes))\n\n/-- Actual current table bytes acquire the source deformation; no old tensor is recomputed. -/\ndef currentPolynomial (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool)) :\n    Polynomial (Integral axes) :=\n  SemiprimeD1Deformation.polynomial _ (fun x => literal axes (A x)) (fun x => literal axes (B x))\n    (oldWire axes n F r a arity owner t)\n\n/-- Actual local old-jet wires include to the original replay wires at the local affine node. -/\ntheorem oldWire_inclusion (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) :\n    (oldWire axes n F r a arity owner t i j).map (scalarMap (dims axes) integers.subtype)=\n      (wire (constants (dims axes)) n F r a arity owner i j).comp\n        ((SemiprimeD1WireKernelPaper.affine a t.val).map (constants (dims axes))) := by\n  rw [oldWire,Polynomial.map_map,constants_square,← Polynomial.map_map,localWire_inclusion,\n    Polynomial.map_comp]\n  congr 1\n  unfold wire\n  split_ifs <;> simp only [Polynomial.map_id,Polynomial.map_zero]\n\n/-- The literal rational CURRENT-table witness is the locally shifted original deformation. -/\ntheorem current_inclusion (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool)) :\n    (currentPolynomial axes n F r a arity owner t A B).map (scalarMap (dims axes) integers.subtype)=\n      (SemiprimeD1Deformation.polynomial _ (fun x => rational axes (A x)) (fun x => rational axes (B x))\n        (wire (constants (dims axes)) n F r a arity owner)).comp\n          ((SemiprimeD1WireKernelPaper.affine a t.val).map (constants (dims axes))) := by\n  rw [currentPolynomial,polynomial_map,polynomial_comp]\n  congr 1\n  funext i j\n  exact oldWire_inclusion axes n F r a arity owner t i j\n\n/-- EVERY old coordinate of EVERY retained local coefficient is integral,\nfrom the actual CURRENT literal word-table witness rather than an integrality oracle. -/\ntheorem current_coefficient_integral (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (j : ℕ) (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    SemiprimeD1DyadicBounds.AtLeast 0 (coefficient (dims axes) e he\n      (((SemiprimeD1Deformation.polynomial _ (fun x => rational axes (A x)) (fun x => rational axes (B x))\n        (wire (constants (dims axes)) n F r a arity owner)).comp\n          ((SemiprimeD1WireKernelPaper.affine a t.val).map (constants (dims axes)))).coeff j)) := by\n  rw [← current_inclusion,Polynomial.coeff_map,coefficient_scalarMap]\n  exact (coefficient (dims axes) e he\n    ((currentPolynomial axes n F r a arity owner t A B).coeff j)).property\n\n/-- Any target old-jet algebra sees the actual modular acquired entry on each local wire. -/\ntheorem oldWire_evaluate {S : Type*} [CommRing S] (axes : List ℕ) (p : ℕ)\n    (f : Algebra (dims axes) (ZMod (2^p)) →+* S) (z : S)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) :\n    ((oldWire axes n F r a arity owner t i j).map (scalarMap (dims axes) (reduction p))).eval₂ f z=\n      if packet n F r a arity owner i=packet n F r a arity owner j then\n        SemiprimeD1UniversalModeData.entryValue p (f.comp (constants (dims axes))) z\n          (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n            (slot n F r a arity owner i) (slot n F r a arity owner j))\n      else 0 := by\n  rw [oldWire,Polynomial.map_map,constants_square,← Polynomial.map_map,Polynomial.eval₂_map]\n  exact localWire_evaluate p (f.comp (constants (dims axes))) z n F r a arity owner t i j\n\n/-- The WHOLE modular contraction uses the actual CURRENT word tables and original\nacquired modular entries, including ALL old axes at the new call precision. -/\ntheorem current_modular_contraction {S : Type*} [CommRing S] (axes : List ℕ) (p : ℕ)\n    (f : Algebra (dims axes) (ZMod (2^p)) →+* S) (z : S)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool)) :\n    ((currentPolynomial axes n F r a arity owner t A B).map\n      (scalarMap (dims axes) (reduction p))).eval₂ f z=\n      ∑bits : Fin (Placements n F r a arity owner).length→Bool,\n        f (SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩ (B bits))*\n          SemiprimeStreamingTensor.evaluate _ (fun x => f (SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩ (A x)))\n            (fun i => ∑j,\n              (if packet n F r a arity owner i=packet n F r a arity owner j then\n                SemiprimeD1UniversalModeData.entryValue p (f.comp (constants (dims axes))) z\n                  (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n                    (slot n F r a arity owner i) (slot n F r a arity owner j))\n               else 0)*SemiprimeStreamingTensor.bit (bits j)) := by\n  rw [currentPolynomial,polynomial_map,polynomial_evaluate]\n  simp only [literal_reduce]\n  apply Finset.sum_congr rfl\n  intro bits _\n  congr 1\n  congr 1\n  funext i\n  apply Finset.sum_congr rfl\n  intro j _\n  rw [oldWire_evaluate]\n\nend\nend RiemannGaussian.SemiprimeD1CurrentTableDeformation\n","RiemannGaussian.SemiprimeD1CurrentTableRecoveryLicence":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetCoordinateLinear\nimport RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition\n\n/-! # Original CURRENT-table scalar D.5 references and derived child errors\nThe reference polynomial is constructed from literal current table bytes. Old\ncoordinate extraction is linear, not multiplicative. Actual child modular\ncoefficient equality derives the D.5 error; no error/degree/integrality answer is\nsupplied for this reference.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1CurrentTableRecoveryLicence\nopen scoped BigOperators\nopen Polynomial SemiprimeD1JetAlgebra SemiprimeD1JetScalarMap SemiprimeD1JetBoxIndex\n  SemiprimeD1JetLiteralLift SemiprimeD1DyadicInteger SemiprimeD1IntegralDeformation\n  SemiprimeD1OriginalDeformation SemiprimeD1CurrentTableDeformation\n  SemiprimeD1JetCoordinateLinear SemiprimeD1DyadicBounds\nnoncomputable section\n\n/-- The scalar rational reference comes from ALL actual CURRENT old coefficient words. -/\ndef reference (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) : Polynomial ℚ :=\n  polynomial (coordinate (dims axes) e he)\n    (SemiprimeD1Deformation.polynomial _ (fun x => rational axes (A x)) (fun x => rational axes (B x))\n      (wire (constants (dims axes)) n F r a arity owner))\n\n/-- The reference has the ORIGINAL D.8 degree budget, with no degree oracle. -/\ntheorem reference_degree (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    (reference axes n F r a arity owner A B e he).natDegree≤\n      (Placements n F r a arity owner).length*(2*(2^a)-1) :=\n  (polynomial_degree _ _).trans (original_degree _ n F r a arity owner _ _)\n\n/-- Old-coordinate linear extraction commutes with the EXACT original local substitution. -/\ntheorem reference_local (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    (reference axes n F r a arity owner A B e he).comp (SemiprimeD1WireKernelPaper.affine a t.val)=\n      polynomial (coordinate (dims axes) e he)\n        ((currentPolynomial axes n F r a arity owner t A B).map (scalarMap (dims axes) integers.subtype)) := by\n  have hsub := SemiprimeD1JetCoordinateLinear.polynomial_comp (coordinate (dims axes) e he)\n    (SemiprimeD1Deformation.polynomial _ (fun x => rational axes (A x)) (fun x => rational axes (B x))\n      (wire (constants (dims axes)) n F r a arity owner)) (SemiprimeD1WireKernelPaper.affine a t.val)\n  have hc : algebraMap ℚ (Algebra (dims axes) ℚ)=constants (dims axes) := Subsingleton.elim _ _\n  rw [hc] at hsub\n  rw [reference,← hsub,← current_inclusion]\n\n/-- The two original scalar affine-coordinate definitions are exactly the same polynomial. -/\ntheorem original_affine (a t : ℕ) : SemiprimeD1WireKernelPaper.affine a t=\n    SemiprimeD1ScaledHermite.affine (SemiprimeD1HermiteOriginal.alpha a) (SemiprimeD1HermiteNodes.node a t) := by\n  simp only [SemiprimeD1WireKernelPaper.affine,SemiprimeD1ScaledHermite.affine,\n    SemiprimeD1HermiteOriginal.alpha,SemiprimeD1HermiteNodes.node,Int.cast_ofNat]\n\n/-- ACTUAL child old-coordinate residue equality DERIVES the original retained D.5 error. -/\ntheorem child_error (axes : List ℕ) (n F r a p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) (j : ℕ) (bs : List Bool)\n    (hchild : coefficient (dims axes) e he\n      (scalarMap (dims axes) (reduction p) ((currentPolynomial axes n F r a arity owner t A B).coeff j))=\n        (SemiprimeBitArithmetic.bitValue bs:ZMod (2^p))) :\n    AtLeast (p:ℤ) ((SemiprimeBitArithmetic.bitValue bs:ℚ)-\n      (((reference axes n F r a arity owner A B e he).comp\n        (SemiprimeD1ScaledHermite.affine (SemiprimeD1HermiteOriginal.alpha a)\n          (SemiprimeD1HermiteNodes.node a t.val))).coeff j)) := by\n  rw [← original_affine,reference_local,polynomial_coefficient,Polynomial.coeff_map]\n  exact old_coordinate_word_error (dims axes) e he p\n    ((currentPolynomial axes n F r a arity owner t A B).coeff j) bs hchild\n\n/-- The reference's original value at zero is integral from the literal source contraction. -/\ntheorem reference_zero_integral (axes : List ℕ) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e) :\n    AtLeast 0 ((reference axes n F r a arity owner A B e he).eval 0) := by\n  rw [reference,polynomial_eval,map_zero,original_at_zero]\n  have hs : (∑bits,rational axes (A bits)*rational axes (B bits))=\n      scalarMap (dims axes) integers.subtype (∑bits,literal axes (A bits)*literal axes (B bits)) := by\n    simp only [map_sum,map_mul,rational]\n  change AtLeast 0 (coefficient (dims axes) e he _)\n  rw [hs,coefficient_scalarMap]\n  exact (coefficient (dims axes) e he (∑bits,literal axes (A bits)*literal axes (B bits))).property\n\n/-- ORIGINAL native integer D.5 recovery from actual modular child-coordinate\npostconditions. Degree, integrality, weights and the scalar error contract are\nALL derived here; no error/precision/weight/coefficient-answer oracle is supplied. -/\ntheorem original_word_recovery (axes : List ℕ) (n F r a u p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→List (List Bool))\n    (e : Fin axes.length→₀ℕ) (he : InBox (dims axes) e)\n    (hu : 0<u) (huM : u≤(Placements n F r a arity owner).length)\n    (children : ℕ → Array (List Bool))\n    (hchild : ∀t : Fin (SemiprimeD1WireKernelOriginal.size a),\n      t.val∈SemiprimeD1HermiteNodes.active a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u →\n      ∀j<SemiprimeD1JetRecoveryGrid.nodeMultiplicity a (SemiprimeD1TaperedLoss.height\n        (Placements n F r a arity owner).length u) u t.val,\n      coefficient (dims axes) e he\n        (scalarMap (dims axes) (reduction (SemiprimeD1WeightPrecision.precision a\n          (Placements n F r a arity owner).length u p t.val))\n          ((currentPolynomial axes n F r a arity owner t A B).coeff j))=\n        (SemiprimeBitArithmetic.bitValue ((children t.val)[j]?.getD []):ZMod\n          (2^SemiprimeD1WeightPrecision.precision a (Placements n F r a arity owner).length u p t.val))) :\n    SemiprimeD1IntegerRecoveryResidue.finish p\n      (SemiprimeD1IntegerRecoveryAcquisition.run a (Placements n F r a arity owner).length u children).result=\n      SemiprimeD1RecoveryResidue.reduce p ((reference axes n F r a arity owner A B e he).eval 0) := by\n  rw [SemiprimeD1IntegerRecoveryAcquisition.run_result]\n  apply SemiprimeD1IntegerRecoveryResidue.original_run_modulo a _ u p hu huM\n    (reference axes n F r a arity owner A B e he)\n    (reference_degree axes n F r a arity owner A B e he) children\n    (reference_zero_integral axes n F r a arity owner A B e he)\n  intro t ht j hj\n  have htN : t<SemiprimeD1WireKernelOriginal.size a :=\n    Finset.mem_range.mp (Finset.mem_filter.mp ht).1\n  rw [SemiprimeD1IntegerRecovery.decodedPackets_coefficient]\n  have h := child_error axes n F r a _ arity owner ⟨t,htN⟩ A B e he j\n    ((children t)[j]?.getD []) (hchild ⟨t,htN⟩ ht j hj)\n  simpa only [SemiprimeD1IntegerRecovery.decode_eq] using h\n\nend\nend RiemannGaussian.SemiprimeD1CurrentTableRecoveryLicence\n","RiemannGaussian.SemiprimeD1IntegerRecoveryResidue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IntegerRecoveryHeight\n\n/-! # Explicit dyadic cancellation of the actual integer recovery accumulator\nThe native path strips the common denominator's actual2-adic content and takes\none odd-unit inverse. No rational-to-modular map or requested residue is supplied.\nNative integer division/valuation/ZMod inverse are not yet physical bit programs.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1IntegerRecoveryResidue\nopen SemiprimeD1IntegerRecovery SemiprimeD1DyadicBounds\n  SemiprimeD1RecoveryResidue SemiprimeD1CrossingCoefficient\n  SemiprimeD1CrossingResidue SemiprimeD1JetRecoveryPrecision\n\n/-- The actual dyadic content of the acquired positive common denominator. -/\ndef content (D : ℕ) : ℕ := 2^padicValNat 2 D\n\n/-- Explicit integer cancellation before the one odd-unit inverse. -/\ndef stripped (N : ℤ) (D : ℕ) : Coefficient :=\n  ⟨N/(content D:ℤ),(D/content D:ℕ)⟩\n\n/-- Actual native modular output from the integer common-denominator accumulator. -/\ndef finish (p : ℕ) (r : Result) : ZMod (2^p) :=\n  residue p (stripped r.numerator r.denominator)\n\n/-- Dyadic content is a genuine positive divisor of the actual denominator. -/\ntheorem content_pos_dvd (D : ℕ) : 0<content D ∧ content D∣D :=\n  ⟨by unfold content;positivity,pow_padicValNat_dvd⟩\n\n/-- Stripping maximal content DERIVES oddness of the actual remaining denominator. -/\ntheorem stripped_odd (N : ℤ) (D : ℕ) (hD : 0<D) : Odd (stripped N D).denominator := by\n  have hp := content_pos_dvd D\n  have hq : 0<D/content D := Nat.div_pos (Nat.le_of_dvd hD hp.2) hp.1\n  have hv : padicValNat 2 (D/content D)=0 := by\n    simpa only [content,Nat.sub_self] using (padicValNat.div_pow (p:=2) (a:=padicValNat 2 D) hp.2)\n  have hn : ¬2∣D/content D := by\n    rcases padicValNat.eq_zero_iff.mp hv with h|h|h\n    · norm_num at h\n    · omega\n    · exact h\n  change Odd ((D/content D:ℕ):ℤ)\n  exact_mod_cast (Nat.not_even_iff_odd.mp (by simpa only [even_iff_two_dvd] using hn))\n\n/-- Integral-at2 actual fractions have enough numerator content for exact division. -/\ntheorem content_dvd_numerator (N : ℤ) (D : ℕ) (hD : 0<D)\n    (hi : AtLeast 0 ((N:ℚ)/(D:ℚ))) : (content D:ℤ)∣N := by\n  by_cases hN : N=0\n  · simp [hN]\n  have hNq : (N:ℚ)≠0 := by exact_mod_cast hN\n  have hDq : (D:ℚ)≠0 := by positivity\n  have hv := hi.resolve_left (div_ne_zero hNq hDq)\n  rw [padicValRat.div hNq hDq,padicValRat.of_int,padicValRat.of_nat] at hv\n  change (2:ℤ)^padicValNat 2 D∣N\n  exact (padicValInt_dvd_iff (p:=2) _ _).mpr (Or.inr (by omega))\n\n/-- The explicit cancelled integer fraction retains the EXACT scalar value. -/\ntheorem stripped_value (N : ℤ) (D : ℕ) (hD : 0<D)\n    (hi : AtLeast 0 ((N:ℚ)/(D:ℚ))) :\n    value (stripped N D)=(N:ℚ)/(D:ℚ) := by\n  have hN := content_dvd_numerator N D hD hi\n  have hp := content_pos_dvd D\n  have hP : (content D:ℚ)≠0 := by exact_mod_cast (ne_of_gt hp.1)\n  have hDq : (D:ℚ)≠0 := by positivity\n  simp only [stripped,value,Int.cast_natCast,Int.cast_div_charZero hN,Nat.cast_div_charZero hp.2]\n  field_simp\n\n/-- Explicit integer cancellation and unit inversion equals canonical native reduction. -/\ntheorem finish_eq_reduce (p : ℕ) (r : Result) (hD : 0<r.denominator)\n    (hi : AtLeast 0 ((r.numerator:ℚ)/(r.denominator:ℚ))) :\n    finish p r=SemiprimeD1RecoveryResidue.reduce p ((r.numerator:ℚ)/(r.denominator:ℚ)) := by\n  exact residue_eq_of_value_eq p _ _ (stripped_odd _ _ hD)\n    (by change Odd (((r.numerator:ℚ)/(r.denominator:ℚ)).den:ℤ)\n        exact_mod_cast denominator_odd _ hi)\n    (by rw [stripped_value _ _ hD hi,canonicalFraction_value])\n\n/-- The ACTUAL original child-word path gives precisely the frozen recovery residue.\nOnly integral recovery is an internal mathematical contract here; original D.5\nrepresentative precision derives it through the existing recover_integral theorem. -/\ntheorem run_finish (a M u p : ℕ) (children : ℕ → Array (List Bool))\n    (hi : AtLeast 0 (recover a M u (decodedPackets children))) :\n    finish p (run a M u children)=\n      SemiprimeD1RecoveryResidue.reduce p (recover a M u (decodedPackets children)) := by\n  have hD : 0<(run a M u children).denominator := by\n    simpa only [run,denominatorRun_value] using denominator_pos (terms a M u children)\n  have hv := run_recover a M u children\n  rw [← hv] at hi\n  rw [finish_eq_reduce p _ hD hi,hv]\n\n/-- Original child-precision contracts derive integrality and exact parent residue;\nno integrality, weight, inverse, or requested output answer is supplied. -/\ntheorem original_run_modulo (a M u p : ℕ) (hu : 0<u) (hM : u≤M) (H : Polynomial ℚ)\n    (hH : H.natDegree≤M*(2*(2^a)-1)) (children : ℕ → Array (List Bool))\n    (h0 : AtLeast 0 (H.eval 0))\n    (herr : ∀t∈SemiprimeD1HermiteNodes.active a (SemiprimeD1TaperedLoss.height M u) u,\n      ∀j<SemiprimeD1JetRecoveryGrid.nodeMultiplicity a (SemiprimeD1TaperedLoss.height M u) u t,\n      AtLeast (SemiprimeD1WeightPrecision.precision a M u p t:ℤ)\n        (SemiprimeJetArray.coefficient (decodedPackets children t) j-\n          (H.comp (SemiprimeD1ScaledHermite.affine (SemiprimeD1HermiteOriginal.alpha a)\n            (SemiprimeD1HermiteNodes.node a t))).coeff j)) :\n    finish p (run a M u children)=SemiprimeD1RecoveryResidue.reduce p (H.eval 0) := by\n  rw [run_finish a M u p children\n    (recover_integral a M u p hu hM H hH (decodedPackets children) h0 herr)]\n  exact original_recover_modulo a M u p hu hM H hH (decodedPackets children) h0 herr\n\nend RiemannGaussian.SemiprimeD1IntegerRecoveryResidue\n","RiemannGaussian.SemiprimeD1JetAlgebra":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Explicit rectangular multijet quotient algebra\nThe commutative ring is constructed from formal power series and an actual\ncoefficient-vanishing ideal. No caller-provided algebra or faithfulness oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1JetAlgebra\nnoncomputable section\nopen scoped BigOperators\nvariable {σ R : Type*} [CommRing R]\n\n/-- Exact componentwise nilpotent exponent box. A zero axis makes it empty. -/\ndef InBox (dims : σ→ℕ) (e : σ→₀ℕ) : Prop := ∀i,e i<dims i\n\n/-- The original rectangular coefficient-vanishing condition is an actual ideal. -/\ndef vanishing (dims : σ→ℕ) : Ideal (MvPowerSeries σ R) where\n  carrier := {f | ∀e,InBox dims e→MvPowerSeries.coeff e f=0}\n  zero_mem' := by intro e _;simp\n  add_mem' := by intro f g hf hg e he;simp only [map_add,hf e he,hg e he,zero_add]\n  smul_mem' := by\n    classical\n    intro a f hf e he\n    change MvPowerSeries.coeff e (a*f)=0\n    rw [MvPowerSeries.coeff_mul]\n    apply Finset.sum_eq_zero\n    rintro ⟨u,v⟩ huv\n    have heq : u+v=e := Finset.HasAntidiagonal.mem_antidiagonal.mp huv\n    have hv : InBox dims v := by\n      intro i\n      have hi:=he i\n      have hei:=congrArg (fun z : σ→₀ℕ => z i) heq\n      simp only [Finsupp.add_apply] at hei\n      omega\n    simp only [hf v hv,mul_zero]\n\n/-- Concrete truncated multijet ring, inheriting the ideal quotient CommRing. -/\nabbrev Algebra (dims : σ→ℕ) (R : Type*) [CommRing R] :=\n  MvPowerSeries σ R ⧸ vanishing (R:=R) dims\n\n/-- Concrete coefficient ring used by the acquired word backend. -/\nabbrev Modular (m p : ℕ) (dims : Fin m→ℕ) := Algebra dims (ZMod (2^p))\n\n/-- Actual quotient projection of a formal series. -/\ndef project (dims : σ→ℕ) : MvPowerSeries σ R→+*Algebra dims R := Ideal.Quotient.mk _\n\n/-- Quotient membership is exactly coefficient vanishing, not a desired identity. -/\ntheorem mem_vanishing (dims : σ→ℕ) (f : MvPowerSeries σ R) :\n    f∈vanishing dims ↔∀e,InBox dims e→MvPowerSeries.coeff e f=0 := Iff.rfl\n\n/-- Two representatives define the same jet iff ALL below-box coefficients agree. -/\ntheorem project_eq_iff (dims : σ→ℕ) (f g : MvPowerSeries σ R) :\n    project dims f=project dims g ↔\n      ∀e,InBox dims e→MvPowerSeries.coeff e f=MvPowerSeries.coeff e g := by\n  rw [project,Ideal.Quotient.mk_eq_mk_iff_sub_mem]\n  change (∀e,InBox dims e→MvPowerSeries.coeff e (f-g)=0)↔_\n  simp only [map_sub,sub_eq_zero]\n\n/-- Canonical bounded coefficient extraction from the actual quotient. -/\nnoncomputable def coefficient (dims : σ→ℕ) (e : σ→₀ℕ) (he : InBox dims e) :\n    Algebra dims R→R :=\n  Quotient.lift (fun f : MvPowerSeries σ R => MvPowerSeries.coeff e f) (by\n    intro f g h\n    have hm : f-g∈vanishing (R:=R) dims := (Submodule.quotientRel_def _).mp h\n    have hz:=hm e he\n    simpa only [map_sub,sub_eq_zero] using hz)\n\n/-- Extraction of a supplied representative has its literal original coefficient. -/\ntheorem coefficient_project (dims : σ→ℕ) (e : σ→₀ℕ) (he : InBox dims e)\n    (f : MvPowerSeries σ R) : coefficient dims e he (project dims f)=MvPowerSeries.coeff e f := rfl\n\n/-- No two different coefficient vectors are collapsed by the quotient. -/\ntheorem ext (dims : σ→ℕ) (f g : Algebra dims R)\n    (h : ∀e,(he : InBox dims e)→coefficient dims e he f=coefficient dims e he g) : f=g := by\n  induction f using Quotient.inductionOn with\n  | h f =>\n    induction g using Quotient.inductionOn with\n    | h g => exact (project_eq_iff dims f g).mpr h\n\n/-- Explicit quotient generator for an original nilpotent axis. -/\ndef generator (dims : σ→ℕ) (i : σ) : Algebra dims R := project dims (MvPowerSeries.X i)\n\n/-- The acquired axis dimension is its actual nilpotence exponent, includingzero. -/\ntheorem generator_pow (dims : σ→ℕ) (i : σ) : (generator (R:=R) dims i)^dims i=0 := by\n  classical\n  rw [generator,←map_pow]\n  apply Ideal.Quotient.eq_zero_iff_mem.mpr\n  intro e he\n  have hn : e≠Finsupp.single i (dims i) := by\n    intro hz\n    have hi:=he i\n    rw [hz,Finsupp.single_eq_same] at hi\n    omega\n  simp only [MvPowerSeries.coeff_X_pow,hn,ite_false]\n\n/-- A zero-dimensional axis gives the actual zero ring, not a malformed basis. -/\ntheorem project_zero_of_zero_axis (dims : σ→ℕ) (i : σ) (hi : dims i=0)\n    (f : MvPowerSeries σ R) : project dims f=0 := by\n  apply Ideal.Quotient.eq_zero_iff_mem.mpr\n  intro e he\n  have h:=he i\n  omega\n\n/-- The coefficient-ring constant map is an actual unital ring homomorphism. -/\ndef constants (dims : σ→ℕ) : R→+*Algebra dims R := (project dims).comp MvPowerSeries.C\n\n/-- Finite rectangular upper exponent, with zero axes filtered separately. -/\ndef bound [Fintype σ] (dims : σ→ℕ) : σ→₀ℕ :=\n  Finsupp.equivFunOnFinite.symm (fun i => dims i-1)\n\n/-- Literal finite monomial box; zero axes produce an empty set. -/\ndef box [Fintype σ] (dims : σ→ℕ) : Finset (σ→₀ℕ) := by\n  classical\n  exact (Finset.Iic (bound dims)).filter (InBox dims)\n\n/-- Finite catalogue membership is exactly the rectangular exponent predicate. -/\ntheorem mem_box [Fintype σ] (dims : σ→ℕ) (e : σ→₀ℕ) :\n    e∈box dims ↔InBox dims e := by\n  classical\n  unfold box\n  constructor\n  · intro h\n    exact (Finset.mem_filter.mp h).2\n  · intro h\n    apply Finset.mem_filter.mpr\n    refine ⟨Finset.mem_Iic.mpr ?_,h⟩\n    intro i\n    change e i≤dims i-1\n    have hi:=h i\n    omega\n\n/-- Original finite canonical representative, using actual bounded coefficients. -/\ndef normalForm [Fintype σ] (dims : σ→ℕ) (f : MvPowerSeries σ R) : MvPolynomial σ R :=\n  MvPowerSeries.truncFinset R (box dims) f\n\n/-- The finite canonical representative has all the original below-box coefficients. -/\ntheorem normalForm_coeff [Fintype σ] (dims : σ→ℕ) (f : MvPowerSeries σ R)\n    (e : σ→₀ℕ) (he : InBox dims e) :\n    (normalForm dims f).coeff e=MvPowerSeries.coeff e f :=\n  MvPowerSeries.coeff_truncFinset_of_mem f ((mem_box dims e).mpr he)\n\n/-- Every quotient element has the actual finite canonical polynomial representative. -/\ntheorem normalForm_project [Fintype σ] (dims : σ→ℕ) (f : MvPowerSeries σ R) :\n    project dims ((normalForm dims f : MvPolynomial σ R) : MvPowerSeries σ R)=project dims f := by\n  apply (project_eq_iff dims _ _).mpr\n  intro e he\n  simpa only [MvPolynomial.coeff_coe] using normalForm_coeff dims f e he\n\n/-- Explicit fresh outer axis at0; every existing axis is shifted bysucc. -/\ndef outerDims {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) : Fin (m+1)→ℕ := Fin.cases q dims\n\n/-- The actual fresh quotient generator occupies the new indexzero. -/\ndef fresh {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) : Algebra (outerDims q dims) R :=\n  generator (outerDims q dims) 0\n\n/-- Fresh generator nilpotence is proved from the concrete quotient, not advice. -/\ntheorem fresh_pow {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) : (fresh (R:=R) q dims)^q=0 := by\n  simpa only [fresh,outerDims,Fin.cases_zero] using\n    generator_pow (R:=R) (outerDims q dims) 0\n\n/-- The explicit embedding of all old exponent coordinates into the shifted axes. -/\ndef axisShift (m : ℕ) : Fin m↪Fin (m+1) := ⟨Fin.succ,Fin.succ_injective m⟩\n\n/-- Old bounded exponent vectors stay bounded after adding a fresh outer axis. -/\ntheorem shifted_inBox {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) (hq : 0<q)\n    (e : Fin m→₀ℕ) (he : InBox dims e) :\n    InBox (outerDims q dims) (Finsupp.embDomain (axisShift m) e) := by\n  intro i\n  refine Fin.cases ?_ (fun j => ?_) i\n  · have hz : (Finsupp.embDomain (axisShift m) e) 0=0 := by\n      apply Finsupp.embDomain_of_notMem_range\n      intro h\n      rcases h with ⟨j,hj⟩\n      exact Fin.succ_ne_zero j hj\n    simpa only [hz,outerDims,Fin.cases_zero] using hq\n  · have hj := he j\n    change (Finsupp.embDomain (axisShift m) e) ((axisShift m) j)<dims j\n    rw [Finsupp.embDomain_apply_self]\n    exact hj\n\n/-- Same-precision variable renaming carries the actual old vanishing ideal into\nthe actual new ideal, so quotient extension is a genuine ring map. -/\ntheorem rename_mem_vanishing {m : ℕ} (q : ℕ) (dims : Fin m→ℕ)\n    (f : MvPowerSeries (Fin m) R) (hf : f∈vanishing dims) :\n    MvPowerSeries.rename (axisShift m) f∈vanishing (outerDims q dims) := by\n  classical\n  intro e he\n  by_cases hx : e∈Set.range (Finsupp.mapDomain (axisShift m))\n  · rcases hx with ⟨d,rfl⟩\n    rw [← Finsupp.embDomain_eq_mapDomain,MvPowerSeries.coeff_embDomain_rename]\n    apply hf\n    intro j\n    have hj:=he j.succ\n    change (Finsupp.mapDomain (axisShift m) d) ((axisShift m) j)<dims j at hj\n    rw [Finsupp.mapDomain_apply_of_injective (axisShift m).injective] at hj\n    exact hj\n  · exact MvPowerSeries.coeff_rename_eq_zero (axisShift m) f hx\n\n/-- Explicit same-precision constant-in-new-axis embedding of the quotient rings. -/\ndef outerEmbedding {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) :\n    Algebra dims R→+*Algebra (outerDims q dims) R :=\n  Ideal.Quotient.lift (vanishing (R:=R) dims)\n    ((project (R:=R) (outerDims q dims)).comp (MvPowerSeries.rename (R:=R) (axisShift m)).toRingHom)\n    (fun f hf => Ideal.Quotient.eq_zero_iff_mem.mpr (rename_mem_vanishing q dims f hf))\n\n/-- Existing series are extended by the actual variable renaming, not reevaluated. -/\ntheorem outerEmbedding_project {m : ℕ} (q : ℕ) (dims : Fin m→ℕ)\n    (f : MvPowerSeries (Fin m) R) :\n    outerEmbedding q dims (project dims f)=\n      project (outerDims q dims) (MvPowerSeries.rename (axisShift m) f) := rfl\n\n/-- All old coefficients are preserved by constant embedding in the fresh axis. -/\ntheorem outerEmbedding_coefficient {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) (hq : 0<q)\n    (e : Fin m→₀ℕ) (he : InBox dims e) (f : Algebra dims R) :\n    coefficient (outerDims q dims) (Finsupp.embDomain (axisShift m) e)\n      (shifted_inBox q dims hq e he) (outerEmbedding q dims f)=coefficient dims e he f := by\n  induction f using Quotient.inductionOn with\n  | h f =>\n    change coefficient (outerDims q dims) (Finsupp.embDomain (axisShift m) e)\n      (shifted_inBox q dims hq e he) (outerEmbedding q dims (project dims f))=\n        coefficient dims e he (project dims f)\n    rw [outerEmbedding_project,coefficient_project,coefficient_project,\n      MvPowerSeries.coeff_embDomain_rename]\n\n/-- A positive fresh axis preserves the entire old algebra, not just constants. -/\ntheorem outerEmbedding_injective {m : ℕ} (q : ℕ) (dims : Fin m→ℕ) (hq : 0<q) :\n    Function.Injective (outerEmbedding (R:=R) q dims) := by\n  intro f g hfg\n  apply ext dims f g\n  intro e he\n  have hc:=congrArg (coefficient (outerDims q dims) (Finsupp.embDomain (axisShift m) e)\n    (shifted_inBox q dims hq e he)) hfg\n  rw [outerEmbedding_coefficient q dims hq e he,outerEmbedding_coefficient q dims hq e he] at hc\n  exact hc\n\nend\nend RiemannGaussian.SemiprimeD1JetAlgebra\n","RiemannGaussian.SemiprimeD1JetScalarBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetAxes\n\n/-! # Actual unsigned coordinate arithmetic modulo2^p\nOutput truncation scans/copies physical bits, never decodes and reencodes them.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1JetScalarBits\nopen SemiprimeBitArithmetic\n/-- Actual physical scalar output and retained bit/cell report. -/\nabbrev Report := SemiprimeSourceCompactBits.Report\n\n/-- Copy at most p low bits, with every visited cell charged. -/\ndef takeBits : ℕ→List Bool→Report\n  | 0,_ => ⟨[],1⟩\n  | _+1,[] => ⟨[],1⟩\n  | p+1,b::bs =>\n    let tail:=takeBits p bs\n    ⟨b::tail.bits,tail.clock+3⟩\n\n/-- The acquired output is exactly the low physical prefix. -/\ntheorem takeBits_bits (p : ℕ) (bits : List Bool) : (takeBits p bits).bits=bits.take p := by\n  induction p generalizing bits with\n  | zero => rfl\n  | succ p ih => cases bits <;> simp [takeBits,ih]\n\n/-- Truncation performs only the actual prefix scan. -/\ntheorem takeBits_clock (p : ℕ) (bits : List Bool) : (takeBits p bits).clock≤3*p+1 := by\n  induction p generalizing bits with\n  | zero => simp [takeBits]\n  | succ p ih =>\n    cases bits with\n    | nil => simp [takeBits]\n    | cons b bs =>\n      have h:=ih bs\n      simp only [takeBits]\n      omega\n\n/-- Exact low/high binary decomposition, independent of compactness. -/\ntheorem bitValue_split (p : ℕ) (bits : List Bool) :\n    bitValue bits=bitValue (bits.take p)+2^p*bitValue (bits.drop p) := by\n  induction p generalizing bits with\n  | zero => simp [bitValue]\n  | succ p ih =>\n    cases bits with\n    | nil => simp [bitValue]\n    | cons b bs =>\n      simp only [List.take_succ_cons,List.drop_succ_cons,bitValue,pow_succ]\n      rw [ih bs]\n      ring\n\n/-- A low prefix has a genuine modulus-sized numerical bound. -/\ntheorem bitValue_take_lt (p : ℕ) (bits : List Bool) : bitValue (bits.take p)<2^p :=\n  (bitValue_lt_width _).trans_le (Nat.pow_le_pow_right (by decide : 1≤2) (List.length_take_le p bits))\n\n/-- Taking low bits implements the exact residue, not a magnitude-linear reencoding. -/\ntheorem bitValue_take (p : ℕ) (bits : List Bool) : bitValue (bits.take p)=bitValue bits%2^p := by\n  rw [bitValue_split p bits,Nat.add_mul_mod_self_left,Nat.mod_eq_of_lt (bitValue_take_lt p bits)]\n\n/-- Physical modular reduction followed by high-zero removal. -/\ndef reduce (p : ℕ) (bits : List Bool) : Report :=\n  let low:=takeBits p bits\n  let out:=SemiprimeSourceCompactBits.trim low.bits\n  ⟨out.bits,low.clock+out.clock+3⟩\n\n/-- Modular output has the canonical numerical value. -/\ntheorem reduce_value (p : ℕ) (bits : List Bool) : bitValue (reduce p bits).bits=bitValue bits%2^p := by\n  simp only [reduce,SemiprimeSourceCompactBits.trim_value,takeBits_bits,bitValue_take]\n\n/-- Physical reduction always yields a compact word. -/\ntheorem reduce_compact (p : ℕ) (bits : List Bool) :\n    SemiprimeSourceCompactBits.Compact (reduce p bits).bits := SemiprimeSourceCompactBits.trim_compact _\n\n/-- Actual output width is bounded by the target precision. -/\ntheorem reduce_length (p : ℕ) (bits : List Bool) : (reduce p bits).bits.length≤p := by\n  exact (SemiprimeSourceCompactBits.trim_length _).trans (by rw [takeBits_bits];exact List.length_take_le p bits)\n\n/-- No original or intermediate word-width premise controls reduction. -/\ntheorem reduce_clock (p : ℕ) (bits : List Bool) : (reduce p bits).clock≤9*p+5 := by\n  have hl : (takeBits p bits).bits.length≤p := by rw [takeBits_bits];exact List.length_take_le p bits\n  have ht:=takeBits_clock p bits\n  have hc:=SemiprimeSourceCompactBits.trim_clock (takeBits p bits).bits\n  simp only [reduce]\n  omega\n\n/-- Actual physical modular coordinate sum, retaining the original scalar circuit. -/\ndef add (p : ℕ) (a b : List Bool) : Report :=\n  let out:=addBits a b false\n  let reduced:=reduce p out.bits\n  ⟨reduced.bits,bitCost out+reduced.clock+3⟩\n\n/-- Actual physical modular coordinate product, retaining all shifted/addition work. -/\ndef mul (p : ℕ) (a b : List Bool) : Report :=\n  let out:=mulBits a b\n  let reduced:=reduce p out.bits\n  ⟨reduced.bits,bitCost out+reduced.clock+3⟩\n\n/-- Modular addition correctness without output advice. -/\ntheorem add_value (p : ℕ) (a b : List Bool) :\n    bitValue (add p a b).bits=(bitValue a+bitValue b)%2^p := by\n  simp only [add,reduce_value,addBits_correct,bitNat,Bool.false_eq_true,ite_false,Nat.add_zero]\n\n/-- Modular product correctness without output advice. -/\ntheorem mul_value (p : ℕ) (a b : List Bool) :\n    bitValue (mul p a b).bits=(bitValue a*bitValue b)%2^p := by\n  simp only [mul,reduce_value,mulBits_correct]\n\n/-- Every sum word has target width. -/\ntheorem add_length (p : ℕ) (a b : List Bool) : (add p a b).bits.length≤p := reduce_length _ _\n\n/-- Every product word has target width. -/\ntheorem mul_length (p : ℕ) (a b : List Bool) : (mul p a b).bits.length≤p := reduce_length _ _\n\n/-- Every modular sum is intrinsically compact. -/\ntheorem add_compact (p : ℕ) (a b : List Bool) :\n    SemiprimeSourceCompactBits.Compact (add p a b).bits := reduce_compact _ _\n\n/-- Every modular product is intrinsically compact. -/\ntheorem mul_compact (p : ℕ) (a b : List Bool) :\n    SemiprimeSourceCompactBits.Compact (mul p a b).bits := reduce_compact _ _\n\n/-- All addition/reduction work is retained with explicit input widths. -/\ntheorem add_clock (p : ℕ) (a b : List Bool) :\n    (add p a b).clock≤11*max a.length b.length+9*p+12 := by\n  have ha:=addBits_cost a b false\n  have hr:=reduce_clock p (addBits a b false).bits\n  simp only [add]\n  omega\n\n/-- All product/reduction work is retained with explicit input widths. -/\ntheorem mul_clock (p : ℕ) (a b : List Bool) :\n    (mul p a b).clock≤12*a.length*(a.length+b.length+2)+9*p+9 := by\n  have ha:=mulBits_cost a b\n  have hr:=reduce_clock p (mulBits a b).bits\n  simp only [mul]\n  omega\n\n/-- The acquired scalar sum denotes addition in the actual residue ring. -/\ntheorem add_zmod (p : ℕ) (a b : List Bool) :\n    (bitValue (add p a b).bits : ZMod (2^p))=(bitValue a:ZMod (2^p))+(bitValue b:ZMod (2^p)) := by\n  rw [add_value,ZMod.natCast_mod,Nat.cast_add]\n\n/-- The acquired scalar product denotes multiplication in the actual residue ring. -/\ntheorem mul_zmod (p : ℕ) (a b : List Bool) :\n    (bitValue (mul p a b).bits : ZMod (2^p))=(bitValue a:ZMod (2^p))*(bitValue b:ZMod (2^p)) := by\n  rw [mul_value,ZMod.natCast_mod,Nat.cast_mul]\n\nend RiemannGaussian.SemiprimeD1JetScalarBits\n","RiemannGaussian.SemiprimeD1JetWordModeBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordModeBits\n\n/-! # Complete word-mode report bounds after the acquired base entry\nThe literal actual base report is retained, not replaced by an old clock. All\nremaining source/Horner/step/power stages have explicit original-input bounds.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1JetWordModeBounds\nopen SemiprimeBitArithmetic SemiprimeD1JetAxes\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nopen SemiprimeD1JetPolynomialBits SemiprimeD1JetPolynomialBitsBounds\nopen SemiprimeD1JetAffineCoefficientBounds SemiprimeD1RecoveryIntegerBits\nopen SemiprimeD1WireKernelOriginal\nattribute [local irreducible] SemiprimeD1JetWordModeScalarBits.acquireOriginal\n  SemiprimeD1JetWordKernelBits.acquireOriginal\n\n/-- Structural actual base rank and width, requiring no semantic unit advice. -/\ntheorem base_good (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    Good ctx (SemiprimeD1JetWordKernelBits.acquireOriginal ctx z a t x y₀).words := by\n  unfold SemiprimeD1JetWordKernelBits.acquireOriginal SemiprimeD1JetWordKernelBits.entry\n  exact mul_good _ _ _\n\n/-- Every non-base original source and physical mode stage, with exact repetitions. -/\ndef budget (ctx : Context) (W a i b : ℕ) : ℕ :=\n  SemiprimeD1JetWordModeScalarBounds.budget ctx.precision a i+\n  ctx.precision*(3*W+3*ctx.rank+\n    SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+addBudget ctx W+12)+ctx.rank+1+\n  (12*ctx.precision*(ctx.precision+(i+2)+2)+13*ctx.precision+3*ctx.rank+27)+\n  2*SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+\n  b*(SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+3)+\n  9*ctx.precision+3*ctx.rank+8+20\n\n/-- Complete actual mode clock, retaining the entire actual acquired-base clock. -/\ntheorem acquireOriginal_clock (ctx : Context) (z : JetRun) (a i b W : ℕ)\n    (t : Fin (size a)) (x y₀ : Fin (2^a))\n    (hp:ctx.precision ≤ W) (hz:z.words.length ≤ ctx.rank) (hw:∀w∈z.words,w.length ≤ W) :\n    (SemiprimeD1JetWordModeBits.acquireOriginal ctx z a i b t x y₀).clock ≤ \n      (SemiprimeD1JetWordKernelBits.acquireOriginal ctx z a t x y₀).clock+budget ctx W a i b := by\n  let base:=SemiprimeD1JetWordKernelBits.acquireOriginal ctx z a t x y₀\n  let source:=SemiprimeD1JetWordModeScalarBits.acquireOriginal ctx.precision a i t x y₀\n  let inverse:=horner ctx z.words source.cache.words\n  let tile:=SemiprimeD1JetWordSourceBits.constant ctx (positive source.step)\n  let ratio:=SemiprimeD1JetRingBits.mul ctx tile.words inverse.words\n  let raised:=power ctx ratio.words b\n  let out:=SemiprimeD1JetRingBits.mul ctx base.words raised.words\n  have hsc:source.clock ≤ SemiprimeD1JetWordModeScalarBounds.budget ctx.precision a i:=\n    SemiprimeD1JetWordModeScalarBounds.acquire_clock _ _ _ _ _ _\n  have hsw:=SemiprimeD1JetWordModeScalarBounds.acquire_width ctx.precision a i t x y₀\n  have hh:=horner_clock ctx z.words source.cache.words W hp hz hw (fun w h=>(hsw.2.1 w h).trans hp)\n  rw [show source.cache.words.length=ctx.precision from hsw.1] at hh\n  have ht:tile.clock ≤ 12*ctx.precision*(ctx.precision+(i+2)+2)+13*ctx.precision+3*ctx.rank+27:=by\n    have h:=SemiprimeD1JetWordSourceBits.constant_clock ctx (positive source.step)\n    exact h.trans (by gcongr;exact hsw.2.2)\n  have htg:Good ctx tile.words:=SemiprimeD1JetWordSourceBits.constant_good ctx _\n  have hhg:Good ctx inverse.words:=horner_good _ _ _\n  have hr:=SemiprimeD1JetRingBounds.mul_clock ctx tile.words inverse.words W htg.1.le hhg.1.le\n    (fun w h=>(htg.2 w h).trans hp) (fun w h=>(hhg.2 w h).trans hp)\n  have hrg:Good ctx ratio.words:=mul_good _ _ _\n  have hpw:=power_clock ctx ratio.words b W hp hrg.1.le (fun w h=>(hrg.2 w h).trans hp)\n  have hpg:Good ctx raised.words:=power_good _ _ _\n  have hbg:Good ctx base.words:=base_good ctx z a t x y₀\n  have ho:=SemiprimeD1JetRingBounds.mul_clock ctx base.words raised.words W hbg.1.le hpg.1.le\n    (fun w h=>(hbg.2 w h).trans hp) (fun w h=>(hpg.2 w h).trans hp)\n  change inverse.clock ≤ _ at hh\n  change ratio.clock ≤ _ at hr\n  change raised.clock ≤ _ at hpw\n  change out.clock ≤ _ at ho\n  change base.clock+source.clock+inverse.clock+tile.clock+ratio.clock+raised.clock+out.clock+20 ≤ base.clock+_\n  unfold budget\n  omega\nend RiemannGaussian.SemiprimeD1JetWordModeBounds\n","RiemannGaussian.SemiprimeD1LeafCounter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTables\nimport RiemannGaussian.SemiprimeD1JetAffineCoefficientBounds\n\n/-! # Actual eager leaf contraction from literal local tensor tables\nOnly ordered native port lists and literal current coefficient-word tables are\nruntime inputs. Each global assignment is gathered by paid list reads, evaluated\nby physical table lookup/products, and stored once. Actual physical sums then\ncontract the complete table. Native index/control lowering remains separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1LeafCounter\nopen scoped BigOperators\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation SemiprimeD1JetOperations\n/-- Physical current-context coefficient vector and its retained report. -/\nabbrev JetRun := SemiprimeD1JetRingBits.Run\n\n/-- A literal local tensor and its actual ordered global variable indices. -/\nstructure Vertex where\n  /-- Actual ordered global bit indices, never an entry evaluator closure. -/\n  ports : List ℕ\n  /-- Entire current local tensor table. -/\n  table : SemiprimeD1TensorTables.Table ports.length\n\n/-- Actual data well-formedness: every local port is a global variable. -/\ndef WellFormed (M : ℕ) (vertices : List Vertex) : Prop :=\n  ∀v∈vertices,∀p∈v.ports,p<M\n\n/-- Every actual stored table is canonical in the current context. -/\ndef Good (ctx : Context) (vertices : List Vertex) : Prop :=\n  ∀v∈vertices,SemiprimeD1TensorTables.Good ctx v.table\n\n/-- One actual Boolean list-read report. -/\nstructure BitRead where\n  /-- Copied selected bit, with false default. -/\n  bit : Bool\n  /-- Visited list cells and finite branch/copy charges. -/\n  clock : ℕ\n\n/-- Bounded actual global assignment read, not a semantic assignment callback. -/\ndef readBit : List Bool → ℕ → BitRead\n  | [],_ => ⟨false,1⟩\n  | b::_,0 => ⟨b,3⟩\n  | _::bs,i+1 => let tail:=readBit bs i;⟨tail.bit,tail.clock+3⟩\n\n/-- Actual bit reads preserve literal list values and defaults. -/\ntheorem readBit_value (bits : List Bool) (i : ℕ) :\n    (readBit bits i).bit=(bits[i]?).getD false := by\n  induction bits generalizing i with\n  | nil => simp [readBit]\n  | cons b bs ih => cases i <;> simp [readBit,ih]\n\n/-- The complete actual local assignment and retained read/copy reports. -/\nstructure Gathered where\n  /-- Local assignment in the literal port ordering. -/\n  bits : List Bool\n  /-- Every selected global read and copied local cell. -/\n  clock : ℕ\n\n/-- Gather each local bit exactly once by its actual ordered port index. -/\ndef gather (bits : List Bool) : List ℕ → Gathered\n  | [] => ⟨[],1⟩\n  | p::ps =>\n    let head:=readBit bits p\n    let tail:=gather bits ps\n    ⟨head.bit::tail.bits,head.clock+tail.clock+3⟩\n\n/-- Gathered assignment size is exactly the literal local scope. -/\ntheorem gather_length (bits : List Bool) (ports : List ℕ) :\n    (gather bits ports).bits.length=ports.length := by\n  induction ports with\n  | nil => rfl\n  | cons p ps ih => simp [gather,ih]\n\n/-- Every gathered bit is the original actual global read. -/\ntheorem gather_value (bits : List Bool) (ports : List ℕ) :\n    (gather bits ports).bits=ports.map (fun p => (bits[p]?).getD false) := by\n  induction ports with\n  | nil => rfl\n  | cons p ps ih => simp [gather,readBit_value,ih]\n\n/-- Actual local lookup, retaining the gathered assignment report. -/\ndef evaluateVertex (v : Vertex) (bits : List Bool) : JetRun :=\n  let localBits:=gather bits v.ports\n  let entry:=SemiprimeD1TensorTables.lookup v.table localBits.bits\n  ⟨entry.words,localBits.clock+entry.clock+3⟩\n\n/-- Proof-side local assignment; no function-valued entry occurs in runtime data. -/\ndef localAssignment {M : ℕ} (bits : Fin M→Bool) (v : Vertex) : Fin v.ports.length→Bool :=\n  fun j => ((List.ofFn bits)[v.ports[j.val]]?).getD false\n\n/-- Actual physical gather and lookup recovers the literal ordered-port tensor entry. -/\ntheorem evaluateVertex_value {M : ℕ} (v : Vertex) (bits : Fin M→Bool) :\n    (evaluateVertex v (List.ofFn bits)).words=\n      SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v) := by\n  change (SemiprimeD1TensorTables.lookup v.table (gather (List.ofFn bits) v.ports).bits).words=_\n  rw [SemiprimeD1TensorTables.lookup_value _ _ (gather_length _ _)]\n  congr 1\n  funext j\n  simp only [gather_value,List.getElem_map,localAssignment]\n\n/-- The actual multiplicative assignment evaluation, with no entry-value oracle. -/\ndef evaluateAssignment (ctx : Context) : List Vertex → List Bool → JetRun\n  | [],_ => SemiprimeD1JetAffineCoefficient.one ctx\n  | v::vs,bits =>\n    let head:=evaluateVertex v bits\n    let tail:=evaluateAssignment ctx vs bits\n    let out:=SemiprimeD1JetRingBits.mul ctx head.words tail.words\n    ⟨out.words,head.clock+tail.clock+out.clock+3⟩\n\n/-- Actual assignment evaluation equals the product of its literal local tensor values. -/\ntheorem evaluateAssignment_value {M : ℕ} (ctx : Context) (hpos : ∀q∈ctx.axes,0<q)\n    (vertices : List Vertex) (bits : Fin M→Bool) :\n    interpret ctx (evaluateAssignment ctx vertices (List.ofFn bits)).words=\n      (vertices.map (fun v => interpret ctx (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod := by\n  induction vertices with\n  | nil => simpa only [evaluateAssignment,List.map_nil,List.prod_nil] using\n      SemiprimeD1JetAffineCoefficient.interpret_one ctx hpos\n  | cons v vs ih =>\n    change interpret ctx (SemiprimeD1JetRingBits.mul ctx\n      (evaluateVertex v (List.ofFn bits)).words (evaluateAssignment ctx vs (List.ofFn bits)).words).words=_\n    rw [interpret_mul ctx _ _ hpos,evaluateVertex_value,ih]\n    rfl\n\n/-- Physical contraction of every materialized global table leaf. -/\ndef sumTable (ctx : Context) : {n : ℕ} → SemiprimeD1TensorTables.Table n → JetRun\n  | _,.leaf words => let out:=copyVector words;⟨out.1,out.2⟩\n  | _,.fork low high =>\n    let left:=sumTable ctx low\n    let right:=sumTable ctx high\n    let out:=SemiprimeD1JetRingBits.add ctx left.words right.words\n    ⟨out.words,left.clock+right.clock+out.clock+3⟩\n\n/-- Summing a literal table computes its complete Boolean assignment contraction. -/\ntheorem sumTable_value (ctx : Context) (hpos : ∀q∈ctx.axes,0<q) {n : ℕ}\n    (table : SemiprimeD1TensorTables.Table n) :\n    interpret ctx (sumTable ctx table).words=\n      ∑bits : Fin n→Bool,interpret ctx (SemiprimeD1TensorTables.valueAt table bits) := by\n  induction table with\n  | leaf words => simp [sumTable,copyVector_value,SemiprimeD1TensorTables.valueAt]\n  | @fork n low high ihlow ihhigh =>\n    change interpret ctx (SemiprimeD1JetRingBits.add ctx (sumTable ctx low).words (sumTable ctx high).words).words=_\n    rw [interpret_add ctx _ _ hpos,ihlow,ihhigh]\n    rw [← (Equiv.sum_comp (Fin.consEquiv (fun _ : Fin (n+1) => Bool)))]\n    simp only [Fintype.sum_prod_type,Fintype.sum_bool,SemiprimeD1TensorTables.valueAt,\n      Fin.consEquiv_apply,Fin.cons_zero,Fin.cons_succ,Bool.false_eq_true,ite_false,ite_true]\n    exact add_comm _ _\n\n/-- Every built table entry is the actual assignment producer result. -/\ntheorem build_valueAt (n : ℕ) (producer : List Bool→JetRun) (bits : Fin n→Bool) :\n    SemiprimeD1TensorTables.valueAt (SemiprimeD1TensorTables.build n producer).table bits=\n      (producer (List.ofFn bits)).words := by\n  have hl:=SemiprimeD1TensorTables.lookup_value (SemiprimeD1TensorTables.build n producer).table\n    (List.ofFn bits) (by simp)\n  have hb:=SemiprimeD1TensorTables.build_value n producer (List.ofFn bits) (by simp)\n  simpa only [List.getElem_ofFn] using hl.symm.trans hb\n\n/-- Actual global eager table and its physically summed result. -/\nstructure LeafRun (M : ℕ) where\n  /-- The entire actual assignment table; permitted subexponential-space storage. -/\n  table : SemiprimeD1TensorTables.Table M\n  /-- Physical contracted coefficient vector. -/\n  words : List (List Bool)\n  /-- All assignment-table producer/allocation and summation reports retained. -/\n  clock : ℕ\n\n/-- Eager leaf counter from literal original network data, without entry or count advice. -/\ndef run (M : ℕ) (ctx : Context) (vertices : List Vertex) : LeafRun M :=\n  let table:=SemiprimeD1TensorTables.build M (evaluateAssignment ctx vertices)\n  let total:=sumTable ctx table.table\n  ⟨table.table,total.words,table.clock+total.clock+3⟩\n\n/-- The executed leaf counter is the EXACT contraction of the actual literal network tables. -/\ntheorem run_value (M : ℕ) (ctx : Context) (hpos : ∀q∈ctx.axes,0<q) (vertices : List Vertex) :\n    interpret ctx (run M ctx vertices).words=\n      ∑bits : Fin M→Bool,(vertices.map (fun v => interpret ctx\n        (SemiprimeD1TensorTables.valueAt v.table (localAssignment bits v)))).prod := by\n  rw [run,sumTable_value ctx hpos]\n  apply Finset.sum_congr rfl\n  intro bits _\n  rw [build_valueAt]\n  exact evaluateAssignment_value ctx hpos vertices bits\n\nend RiemannGaussian.SemiprimeD1LeafCounter\n","RiemannGaussian.SemiprimeD1OddInverseBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetScalarBits\n\n/-! # Physical odd inversion using only bounded binary additions and products\nThe inverse is acquired by p explicit Newton steps modulo2^p. Negative one is\nthe actual p-cell all-true word. No native modular inverse or requested inverse\nword is supplied; every old report is retained once.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1OddInverseBits\nopen SemiprimeBitArithmetic\nopen SemiprimeD1JetScalarBits\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- Exact interpretation of one actual scalar word. -/\ndef value (p : ℕ) (bits : List Bool) : ZMod (2^p) := bitValue bits\n\n/-- Physically allocate the modular negative-one word once. -/\ndef negativeOne (p : ℕ) : Report := ⟨List.replicate p true,p+2⟩\n\n/-- Exact unsigned all-one word value, without subtraction conventions at zero. -/\ntheorem negativeOne_value (p : ℕ) : bitValue (negativeOne p).bits+1=2^p := by\n  induction p with\n  | zero => simp [negativeOne,bitValue]\n  | succ p ih =>\n    simp only [negativeOne,List.replicate_succ,bitValue,bitNat,ite_true,pow_succ] at ih ⊢\n    omega\n\n/-- The acquired all-one word really denotes negative one in the target ring. -/\ntheorem negativeOne_zmod (p : ℕ) : value p (negativeOne p).bits = -1 := by\n  have h : (bitValue (negativeOne p).bits:ZMod (2^p))+1=0 := by\n    have he := congrArg (fun n : ℕ => (n:ZMod (2^p))) (negativeOne_value p)\n    simpa only [Nat.cast_add,Nat.cast_one,ZMod.natCast_self] using he\n  exact add_eq_zero_iff_eq_neg.mp h\n\n/-- Physical reduction agrees with the original word's target-ring value. -/\ntheorem reduce_zmod (p : ℕ) (bits : List Bool) : value p (reduce p bits).bits=value p bits := by\n  simp only [value,reduce_value,ZMod.natCast_mod]\n\n/-- One literal Newton step, with each product and sum cached exactly once. -/\ndef step (p : ℕ) (a negative two current : List Bool) : Report :=\n  let product := mul p a current\n  let opposite := mul p negative product.bits\n  let correction := add p two opposite.bits\n  let out := mul p current correction.bits\n  ⟨out.bits,product.clock+opposite.clock+correction.clock+out.clock+10⟩\n\n/-- Every actual step produces a compact target-width word. -/\ntheorem step_good (p : ℕ) (a negative two current : List Bool) :\n    (step p a negative two current).bits.length≤p ∧ Compact (step p a negative two current).bits :=\n  ⟨mul_length _ _ _,mul_compact _ _ _⟩\n\n/-- The actual scalar circuit implements x*(2-a*x), using no signed division. -/\ntheorem step_value (p : ℕ) (a negative two current : List Bool)\n    (hnegative : value p negative = -1) (htwo : value p two=2) :\n    value p (step p a negative two current).bits =\n      value p current*(2-value p a*value p current) := by\n  change (bitValue (mul p current (add p two (mul p negative (mul p a current).bits).bits).bits).bits:ZMod (2^p))=_\n  rw [mul_zmod,add_zmod,mul_zmod,mul_zmod]\n  change value p current*(value p two+value p negative*(value p a*value p current))=_\n  rw [hnegative,htwo]\n  ring\n\n/-- One actual Newton step squares the old inverse error. -/\ntheorem step_error (p : ℕ) (a negative two current : List Bool)\n    (hnegative : value p negative = -1) (htwo : value p two=2) :\n    value p a*value p (step p a negative two current).bits-1 =\n      -(value p a*value p current-1)^2 := by\n  rw [step_value p a negative two current hnegative htwo]\n  ring\n\n/-- Explicit row of p bounded-word Newton updates, retaining every previous report. -/\ndef loop (p : ℕ) (a negative two : List Bool) : ℕ→Report\n  | 0 => reduce p [true]\n  | n+1 =>\n    let previous := loop p a negative two n\n    let here := step p a negative two previous.bits\n    ⟨here.bits,previous.clock+here.clock+3⟩\n\n/-- All actual inverse iterates remain compact and have intrinsic precision width. -/\ntheorem loop_good (p : ℕ) (a negative two : List Bool) (n : ℕ) :\n    (loop p a negative two n).bits.length≤p ∧ Compact (loop p a negative two n).bits := by\n  cases n with\n  | zero => exact ⟨reduce_length _ _,reduce_compact _ _⟩\n  | succ n => exact step_good _ _ _ _ _\n\n/-- Each actual iterate gains at least one dyadic bit; the ring may have zero divisors. -/\ntheorem loop_content (p : ℕ) (a negative two : List Bool)\n    (hnegative : value p negative = -1) (htwo : value p two=2)\n    (ha : ∃k : ZMod (2^p),value p a-1=2*k) (n : ℕ) :\n    ∃c : ZMod (2^p),value p a*value p (loop p a negative two n).bits-1=2^(n+1)*c := by\n  induction n with\n  | zero =>\n    obtain ⟨k,hk⟩ := ha\n    refine ⟨k,?_⟩\n    change value p a*value p (reduce p [true]).bits-1=2^(0+1)*k\n    rw [reduce_zmod]\n    have hone : value p [true]=(1:ZMod (2^p)) := by norm_num [value,bitValue,bitNat]\n    simpa only [hone,mul_one,Nat.zero_add,pow_one] using hk\n  | succ n ih =>\n    obtain ⟨c,hc⟩ := ih\n    refine ⟨-(2:ZMod (2^p))^n*c^2,?_⟩\n    change value p a*value p (step p a negative two (loop p a negative two n).bits).bits-1=_\n    rw [step_error p a negative two _ hnegative htwo,hc,mul_pow]\n    have he : ((2:ZMod (2^p))^(n+1))^2=2^(n+1+1)*2^n := by\n      rw [←pow_mul,←pow_add]\n      congr 1\n      omega\n    rw [he]\n    ring\n\n/-- Actual odd-input word inverse, with source truncation and constants paid once. -/\ndef inverse (p : ℕ) (input : List Bool) : Report :=\n  let a := reduce p input\n  let negative := negativeOne p\n  let two := reduce p [false,true]\n  let out := loop p a.bits negative.bits two.bits p\n  ⟨out.bits,a.clock+negative.clock+two.clock+out.clock+10⟩\n\n/-- The actual acquired inverse has no high zero bytes or supplied width premise. -/\ntheorem inverse_good (p : ℕ) (input : List Bool) :\n    (inverse p input).bits.length≤p ∧ Compact (inverse p input).bits :=\n  loop_good _ _ _ _ _\n\n/-- Every original odd word has its true multiplicative inverse modulo2^p.\nNo native inverse operation, desired inverse answer or unit oracle is an input. -/\ntheorem inverse_correct (p : ℕ) (input : List Bool) (hodd : Odd (bitValue input)) :\n    value p input*value p (inverse p input).bits=1 := by\n  let a := (reduce p input).bits\n  let negative := (negativeOne p).bits\n  let two := (reduce p [false,true]).bits\n  have ha : ∃k : ZMod (2^p),value p a-1=2*k := by\n    obtain ⟨k,hk⟩ := hodd\n    refine ⟨(k:ZMod (2^p)),?_⟩\n    rw [show value p a=value p input from reduce_zmod p input]\n    have he : value p input=2*(k:ZMod (2^p))+1 := by\n      change (bitValue input:ZMod (2^p))=2*(k:ZMod (2^p))+1\n      rw [hk]\n      push_cast\n      rfl\n    rw [he]\n    ring\n  have ht : value p two=2 := by\n    rw [show value p two=value p [false,true] from reduce_zmod p _]\n    norm_num [value,bitValue,bitNat]\n  obtain ⟨c,hc⟩ := loop_content p a negative two (negativeOne_zmod p) ht ha p\n  have hz : (2:ZMod (2^p))^p=0 := by\n    simpa only [Nat.cast_pow,Nat.cast_ofNat] using ZMod.natCast_self (2^p)\n  rw [pow_succ,hz,zero_mul,zero_mul,sub_eq_zero] at hc\n  change value p input*value p (loop p a negative two p).bits=1\n  rw [←show value p a=value p input from reduce_zmod p input]\n  exact hc\n\nend RiemannGaussian.SemiprimeD1OddInverseBits\n","RiemannGaussian.SemiprimeD1OriginalChildGraphBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildMetadataPrimitives\nimport RiemannGaussian.SemiprimeD1OriginalModeAcquisition\n\n/-! # Original-source child graph metadata supplier\nAll widths and stream sizes are derived from the actual original selector,\ndictionary and replay. The bound retains its acquisition report. Native typed\nowner/index evaluation is a separate finite metadata stage, not a free bit oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1OriginalChildGraphBudget\nopen scoped BigOperators\nopen SemiprimeD1ChildGraph SemiprimeD1ChildMetadataPrimitives\nopen SemiprimeD1PacketInventory SemiprimeSourceHistogramTrie\n\n/-- Literal original retained replay source. -/\nabbrev source (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :=\n  SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n\n/-- Original selected-pair byte width from the already executed compact producer. -/\ndef keyCap (n F r a : ℕ) : ℕ :=\n  3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+1\n\n/-- Original dictionary payload width, independent of the queried ID. -/\ndef rowCap (r a : ℕ) : ℕ := a*(2*(r+1)+1)\n\n/-- Closed original replay report envelope used as a conservative byte cap. -/\ndef replayCap (n F r a M : ℕ) : ℕ := SemiprimeD1PacketReplayBudget.budget n F r a M\n\n/-- Every original pair/placement occurs once in this literal metadata stream. -/\ntheorem pairs_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ((source n F r a arity owner).padding.source.selection.cache.data.metadata.incidences.zip\n      (source n F r a arity owner).placements).length=∑e,arity e := by\n  have hm : (SemiprimeD1CollisionOriginal.ports n F a arity).length=∑e,arity e :=\n    (SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n  have hp:=(SemiprimeD1OriginalModeAcquisition.original_size n F r a arity owner).trans hm\n  rw [SemiprimeD1ChildGraphSemantics.original_ports,List.length_zip,hp,hm,Nat.min_self]\n\n/-- Each original placed pair key has its actually acquired finite width. -/\ntheorem placement_source (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ∀p∈(source n F r a arity owner).placements,p.source.length ≤ keyCap n F r a := by\n  intro p hp\n  have hmem : p.source∈((source n F r a arity owner).placements.map Placement.source):=List.mem_map.mpr ⟨p,hp,rfl⟩\n  rw [SemiprimeD1PacketReplayOriginal.sources] at hmem\n  exact SemiprimeD1IncidenceAcquisitionBounds.key_length n F r a arity owner p.source hmem\n\n/-- Literal original dictionary, not a row-answer callback. -/\ntheorem dictionary (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (source n F r a arity owner).padding.source.selection.cache.rows.source.dictionary=\n      SemiprimeSourceHistogramRows.acquire r a := rfl\n\n/-- Actual original dictionary payload widths apply to every total byte lookup. -/\ntheorem dictionary_width (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (id : List Bool) :\n    (stored (source n F r a arity owner).padding.source.selection.cache.rows.source.dictionary.trie id).length ≤ rowCap r a := by\n  rw [dictionary]\n  exact SemiprimeSourceHistogramRowsBounds.acquire_width r a id\n\n/-- Entire original emitted endpoint payloads have report-derived byte caps. -/\ntheorem endpoint_payload (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r) :\n    ∀e∈(fromReplay owner (source n F r a arity owner) q g).endpoints,\n      e.packet.length ≤ replayCap n F r a (∑e,arity e) ∧\n      e.edge.length ≤ replayCap n F r a (∑e,arity e) ∧ e.slot.length ≤ a := by\n  let src:=source n F r a arity owner\n  have hc:=SemiprimeD1PacketReplayBudget.acquire_work n F r a arity owner\n  apply scan_payload\n  intro x hx\n  have hp:=SemiprimeD1ReplayMetadataBounds.original_placements n F r a arity owner x.2\n    (List.of_mem_zip hx).2\n  exact ⟨hp.1.trans hc,hp.2.1.trans hc,hp.2.2⟩\n\n/-- Actual emitted endpoint count, without an advised group load. -/\ntheorem endpoints_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (fromReplay owner (source n F r a arity owner) q g).endpoints.length ≤ 2*∑e,arity e := by\n  have h:=scan_length owner (source n F r a arity owner).padding.source.selection.cache.rows.source.dictionary\n    a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits\n    ((source n F r a arity owner).padding.source.selection.cache.data.metadata.incidences.zip\n      (source n F r a arity owner).placements)\n  rwa [pairs_length] at h\n\n/-- All observed factors, including empty buckets, are retained and counted. -/\ntheorem factors_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (fromReplay owner (source n F r a arity owner) q g).factors.length ≤ ∑e,arity e := by\n  rw [SemiprimeD1ChildGraphSemantics.factors_length]\n  exact SemiprimeD1ReplayMetadataBounds.original_count n F r a arity owner\n\n/-- Conservative cached-factor incidence count from actual bucket loops. -/\ntheorem factors_flatten_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (fromReplay owner (source n F r a arity owner) q g).factors.flatten.length ≤ 2*(∑e,arity e)^2 := by\n  have h:=buckets_length (fromReplay owner (source n F r a arity owner) q g).endpoints\n    (source n F r a arity owner).state.packets\n  have hP:=SemiprimeD1ReplayMetadataBounds.original_count n F r a arity owner\n  have hE:=endpoints_length n F r a arity owner q g\n  change _ ≤ 2*(∑e,arity e)^2\n  exact h.trans (by nlinarith)\n\n/-- Explicit supplier overhead, a fixed polynomial in original dimensions and\nretained replay envelope. No2^M or full palette orbit enumeration occurs. -/\ndef overhead (n F r a M : ℕ) : ℕ :=\n  SemiprimeSourceHistogramPortKeys.encodeBudget r+\n    M*(oneBudget a a (keyCap n F r a) (rowCap r a) (SemiprimeSourceHistogramPortKeys.keyWidth r)+8)+2+\n    M*((2*M)*(6*replayCap n F r a M+9)+6)+2+2*M+12\n\n/-- CLOSED actual fromReplay supplier report: source is retained once, and all\nphysical row, comparison, endpoint, bucket and constructor reports are paid. -/\ntheorem fromReplay_work (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (fromReplay owner (source n F r a arity owner) q g).work ≤\n      (source n F r a arity owner).state.clock+overhead n F r a (∑e,arity e) := by\n  let src:=source n F r a arity owner\n  let target:=SemiprimeSourceHistogramPortKeys.encodeKey g.val\n  let xs:=src.padding.source.selection.cache.data.metadata.incidences.zip src.placements\n  let emitted:=scan owner src.padding.source.selection.cache.rows.source.dictionary a q.val target.bits xs\n  have ht:=SemiprimeSourceHistogramPortKeys.encodeKey_clock g.val r (by omega)\n  change target.clock ≤ SemiprimeSourceHistogramPortKeys.encodeBudget r at ht\n  have hG:=SemiprimeSourceHistogramPortKeys.encodeKey_length g.val r (by omega)\n  have hx : xs.length=∑e,arity e:=pairs_length n F r a arity owner\n  have hs:=scan_work owner src.padding.source.selection.cache.rows.source.dictionary a q.val target.bits xs\n    (keyCap n F r a) (rowCap r a) (SemiprimeSourceHistogramPortKeys.keyWidth r)\n    (fun x hx=>placement_source n F r a arity owner x.2 (List.of_mem_zip hx).2) hG\n    (dictionary_width n F r a arity owner)\n  rw [hx] at hs\n  have he:=endpoints_length n F r a arity owner q g\n  change emitted.value.length ≤ 2*∑e,arity e at he\n  have hp:=SemiprimeD1ReplayMetadataBounds.original_count n F r a arity owner\n  change src.state.packets.length ≤ ∑e,arity e at hp\n  have hb:=buckets_work emitted.value src.state.packets (replayCap n F r a (∑e,arity e))\n    (fun e he=>(endpoint_payload n F r a arity owner q g e he).1)\n  have hread : emitted.work ≤ (∑e,arity e)*(oneBudget a a (keyCap n F r a) (rowCap r a)\n      (SemiprimeSourceHistogramPortKeys.keyWidth r)+8)+2 := hs.trans (by unfold oneBudget colourBudget;gcongr;exact Nat.le_of_lt q.isLt)\n  have hbucket : (buckets emitted.value src.state.packets).work ≤\n      (∑e,arity e)*((2*∑e,arity e)*(6*replayCap n F r a (∑e,arity e)+9)+6)+2 := hb.trans (by gcongr)\n  have hmeta : src.padding.source.selection.cache.data.metadata.incidences.length+src.placements.length=2*∑e,arity e := by\n    rw [SemiprimeD1ChildGraphSemantics.original_ports,SemiprimeD1OriginalModeAcquisition.original_size]\n    have hm : (SemiprimeD1CollisionOriginal.ports n F a arity).length=∑e,arity e:=\n      (SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n    rw [hm]\n    omega\n  change src.state.clock+target.clock+emitted.work+(buckets emitted.value src.state.packets).work+\n    src.padding.source.selection.cache.data.metadata.incidences.length+src.placements.length+12 ≤\n      src.state.clock+overhead n F r a (∑e,arity e)\n  unfold overhead\n  omega\n\nend RiemannGaussian.SemiprimeD1OriginalChildGraphBudget\n","RiemannGaussian.SemiprimeD1OriginalScalarResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OriginalEnvelopeRate\n\n/-! # One uniform scalar for every actual original recursive call\nThe scalar is 2^((lambda+1)^3), with lambda the actual ceiling logarithm.\nEvery cap is derived from the original reachable-state bound. Full literal\ntable inventory still has its additional 2^delta factor; it is not silently\nreplaced by this scalar.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1OriginalScalarResources\nopen SemiprimeD1PackingReady SemiprimeD1OriginalStateResources\nopen SemiprimeD1OriginalEnvelopeRate SemiprimeD1RecursiveCallTree\nopen SemiprimeD1TensorNetwork SemiprimeD1Schedule\n\n/-- The literal logarithm pays the original scale as a binary power. -/\ntheorem scale_le_power (s : ℕ) : s ≤ 2^logarithm s :=\n  (show s ≤ s+2 by omega).trans (Nat.le_pow_clog (by decide:1<2) (s+2))\n\n/-- Every smaller binary exponent is covered by the single actual scalar. -/\ntheorem power_le_scalar (s e : ℕ) (h:e ≤ (logarithm s+1)^3) : 2^e ≤ scalar s :=\n  Nat.pow_le_pow_right (by decide:0<(2:ℕ)) h\n\n/-- One linear exponent reserve covers all fixed coefficients used below. -/\ntheorem linear_exponent_bound (s : ℕ) (hl:1000 ≤ logarithm s) :\n    24*(logarithm s+1) ≤ (logarithm s+1)^3 := by\n  have hs:24 ≤ (logarithm s+1)^2:=by nlinarith\n  calc\n    _ ≤ (logarithm s+1)^2*(logarithm s+1) := Nat.mul_le_mul_right _ hs\n    _ = _ := by ring\n\n/-- Literal scale, vertex factor and logarithmic controls share the scalar. -/\ntheorem base_caps (s : ℕ) (hl:1000 ≤ logarithm s) :\n    s ≤ scalar s ∧5*s ≤ scalar s ∧logarithm s+1 ≤ scalar s := by\n  have hs:=scale_le_power s\n  have he:=linear_exponent_bound s hl\n  have hp:5*s ≤ 2^(logarithm s+3):=by\n    rw [pow_add]\n    norm_num\n    omega\n  have hlarge:=power_le_scalar s (logarithm s+3) (by omega)\n  have hlog:logarithm s+1 ≤ 2^logarithm s:=Nat.lt_two_pow_self\n  refine ⟨hs.trans (power_le_scalar s (logarithm s) (by omega)),hp.trans hlarge,\n    hlog.trans (power_le_scalar s (logarithm s) (by omega))⟩\n\n/-- Actual stored dense rank is within the scalar; every old axis is retained. -/\ntheorem rankCap_le (s : ℕ) (hl:1000 ≤ logarithm s) : rankCap s ≤ scalar s := by\n  have hs:=scale_le_power s\n  have hbase:4*s ≤ 2^(logarithm s+2):=by rw [pow_add];norm_num;omega\n  calc\n    _ ≤ (2^(logarithm s+2))^(logarithm s+1) := Nat.pow_le_pow_left hbase _\n    _ = 2^((logarithm s+2)*(logarithm s+1)) := by rw [pow_mul]\n    _ ≤ scalar s := power_le_scalar s _ (by\n      have h:logarithm s+2 ≤ (logarithm s+1)^2:=by nlinarith\n      calc\n        _ ≤ (logarithm s+1)^2*(logarithm s+1) := Nat.mul_le_mul_right _ h\n        _ = _ := by ring)\n\n/-- Computed precision includes all previous increments and is still scalar. -/\ntheorem precisionCap_le (s : ℕ) (hl:1000 ≤ logarithm s) : precisionCap s ≤ scalar s := by\n  have hs:=scale_le_power s\n  have hlog:logarithm s+1 ≤ 2^logarithm s:=Nat.lt_two_pow_self\n  have hp:precisionCap s ≤ 2^(7*logarithm s+8):=by\n    calc\n      _ ≤ (2^logarithm s)*(2^8*(2^logarithm s)^2)*2^(4*logarithm s) := by\n        unfold precisionCap\n        gcongr\n        norm_num\n      _ = _ := by rw [←pow_mul,←pow_add,←pow_add,←pow_add];congr 1;ring\n  exact hp.trans (power_le_scalar s _ (by have h:=linear_exponent_bound s hl;omega))\n\n/-- The actual rounded degree cap keeps its own exponential-table role. -/\ntheorem degreeCap_le (s : ℕ) (hl:1000 ≤ logarithm s) : degreeCap s ≤ scalar s := by\n  unfold degreeCap\n  apply power_le_scalar\n  have hd:(9*logarithm s+9)/10 ≤ logarithm s+1:=by omega\n  exact hd.trans (by have h:=linear_exponent_bound s hl;omega)\n\n/-- Every dimension used in one actual reachable call, before source-specific\npolynomial enlargement. This record stores inequalities only, never answers. -/\nstructure Caps (S : ℕ) (call : Call) (a : ℕ) : Prop where\n  /-- Actual left-vertex count. -/\n  left : call.net.leftCount ≤ S\n  /-- Actual right-row count. -/\n  rows : call.net.rows.length ≤ S\n  /-- Actual edge occurrences. -/\n  edges : edgeCount call.net ≤ S\n  /-- Actual schedule exponent. -/\n  exponent : a ≤ S\n  /-- Actual computed scalar precision. -/\n  precision : call.ctx.precision ≤ S\n  /-- Actual dense jet rank. -/\n  rank : call.ctx.rank ≤ S\n  /-- Actual number of inherited axes. -/\n  axes : call.ctx.axes.length ≤ S\n  /-- Entire actual interpolation grid. -/\n  grid : 2^(a+1) ≤ S\n  /-- Entire actual group-power scale. -/\n  groups : 64^a ≤ S\n  /-- Actual depth. -/\n  depth : call.depth ≤ S\n\n/-- CLOSED actual-state substitution, without a dimension/precision supplier. -/\ntheorem of_bound (s : ℕ) (call : Call) (a : ℕ) (hl:1000 ≤ logarithm s)\n    (hb:Bound s call) (ha:a ≤ 4*(logarithm s/131072)) : Caps (scalar s) call a := by\n  have hc:=base_caps s hl\n  have hv:=hb.vertex_count\n  change call.net.leftCount+call.net.rows.length ≤ 5*s at hv\n  have hal:a ≤ 4*logarithm s:=(ha.trans (Nat.mul_le_mul_left _ (Nat.div_le_self _ _)))\n  have he:=linear_exponent_bound s hl\n  have haexp:a+1 ≤ (logarithm s+1)^3:=by omega\n  have hagroup:6*a ≤ (logarithm s+1)^3:=by omega\n  have hag:a ≤ scalar s:=by\n    have had:a ≤ 2^(a+1):=(Nat.lt_two_pow_self (n:=a+1)).le.trans' (by omega)\n    exact had.trans (power_le_scalar s _ haexp)\n  refine ⟨(show call.net.leftCount ≤ 5*s by omega).trans hc.2.1,\n    (show call.net.rows.length ≤ 5*s by omega).trans hc.2.1,hb.edge_count.trans hc.1,hag,\n    hb.precision.trans (precisionCap_le s hl),hb.rank.trans (rankCap_le s hl),\n    ?_,power_le_scalar s _ haexp,?_,hb.depth.trans hc.2.2⟩\n  · rw [hb.axes_length]\n    exact hb.depth.trans hc.2.2\n  · calc\n      _ = (2^6)^a := by norm_num\n      _ = 2^(6*a) := by rw [pow_mul]\n      _ ≤ scalar s := power_le_scalar s _ hagroup\n\nend RiemannGaussian.SemiprimeD1OriginalScalarResources\n","RiemannGaussian.SemiprimeD1PackedNetworkReindex":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PackedMomentPrecision\nimport RiemannGaussian.SemiprimeD1PackedMomentSemiprime\nimport RiemannGaussian.SemiprimePublicAcquiredExecution\n/-! # Exact weighted public reindexing before the final scalar reduction\nThe full natural contraction retains every higher moment. These identities\nuse the original public vertex and wire enumerations; they add no evaluator\nor supplied scalar to the finite source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeD1PackedNetworkReindex\nopen scoped BigOperators\nopen SemiprimePublicAcquiredExecution SemiprimeMacroGraph SemiprimeMacroGraphSemantics SemiprimeMacroParameters\nopen SemiprimeD1PackedMomentOriginal SemiprimeD1PackedMomentPrecision\nattribute [local instance] Classical.propDecidable\n/-- The actual finite wire and vertex enumerations preserve arbitrary local weights. -/\ntheorem indexed_sum {R : Type*} [CommSemiring R] (N : ℕ) (hN : 0<N)\n    (table : (v : PublicVertex N)→(Fin (subdividedArity v)→Bool)→R) :\n    (∑a : Fin (wireCount N)→Bool,∏e : Fin (factorCount N),\n      table ((vertexEnumeration N).equivFin e) (fun i => a (indexedCoordinate N hN e i)))=\n      ∑a : PublicEdge N→Bool,∏v : PublicVertex N,\n        table v (fun i => a (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) v i)) := by\n  apply Fintype.sum_equiv (assignmentEquiv N)\n  intro a\n  exact (vertexEnumeration N).equivFin.prod_comp\n    (fun v => table v (fun i => a ((edgeEnumeration N).equivFin.symm\n      (SemiprimeScheduledCounter.publicCoordinate (bitLength_pos hN) v i))))\n/-- Exact natural coefficient casts at every target semiring, without early truncation. -/\ntheorem coefficient_cast {R : Type*} [CommSemiring R] (N : ℕ) (hN : 0<N)\n    (v : PublicVertex N) (input : Fin (subdividedArity v)→Bool) :\n    (coefficient N hN v input : R)=\n      markedTable (SemiprimePublicFactorCount.publicConfig N hN) ((2^bitLength N : ℕ) : R) v input := by\n  unfold coefficient markedTable\n  split <;> simp only [Nat.cast_add,Nat.cast_one,Nat.cast_mul,Nat.cast_zero]\n/-- Full indexed natural contraction, including ALL higher powers of the marker. -/\ndef full (N : ℕ) (hN : 0<N) : ℕ :=\n  ∑a : Fin (wireCount N)→Bool,∏e : Fin (factorCount N),\n    coefficient N hN ((vertexEnumeration N).equivFin e) (fun i => a (indexedCoordinate N hN e i))\n/-- Cast finite sums and products before inserting concrete public metadata. -/\ntheorem cast_sum_product {R I J : Type*} [CommSemiring R] [Fintype I] [Fintype J]\n    (f : I→J→ℕ) : ((∑i,∏j,f i j : ℕ) : R)=∑i,∏j,(f i j : R) := by\n  simp only [Nat.cast_sum,Nat.cast_prod]\n/-- Full natural contraction is the same original weighted public graph, over ANY semiring. -/\ntheorem cast_full {R : Type*} [CommSemiring R] (N : ℕ) (hN : 0<N) :\n    (full N hN : R)=contraction (SemiprimePublicFactorCount.publicConfig N hN) ((2^bitLength N : ℕ) : R) := by\n  unfold full\n  rw [cast_sum_product]\n  refine Eq.trans ?_ (indexed_sum N hN\n    (markedTable (SemiprimePublicFactorCount.publicConfig N hN) ((2^bitLength N : ℕ) : R)))\n  apply Finset.sum_congr rfl\n  intro a _\n  apply Finset.prod_congr rfl\n  intro e _\n  exact coefficient_cast N hN ((vertexEnumeration N).equivFin e) (fun i => a (indexedCoordinate N hN e i))\n/-- A proved equality of final moduli preserves the decoded residue of the SAME integer. -/\ntheorem val_modulus (a p q : ℕ) (h : p=q) :\n    (a : ZMod p).val=(a : ZMod q).val := by cases h;rfl\n/-- The actual public 2ell-bit scalar readout is obtained ONLY at this final reduction. -/\ntheorem packed_value (N : ℕ) (hN : 0<N) :\n    ((full N hN : ZMod (2^precision N))).val=SemiprimeD1PackedMomentSemiprime.packedValue N hN := by\n  calc\n    _ = (full N hN : ZMod ((2^bitLength N)^2)).val := val_modulus _ _ _ (modulus N)\n    _ = _ := congrArg ZMod.val (cast_full (R:=ZMod ((2^bitLength N)^2)) N hN)\nend RiemannGaussian.SemiprimeD1PackedNetworkReindex\n","RiemannGaussian.SemiprimeD1PacketCoefficientAlignment":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketAffineRowEvaluation\n\n/-! # Actual real-row coefficients and original routing masks\nFor a mode in the actual packet, the executed coefficient is zero at its local\nsource group and is exactly the signed original D.12 mode otherwise. Original\nrouting proves the target and same-bit tests; neither is supplied as advice.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nnamespace RiemannGaussian.SemiprimeD1PacketCoefficientAlignment\nopen SemiprimeD1PacketEntryInputs SemiprimeD1PacketEntryBits\nopen SemiprimeD1PacketEntryComponents SemiprimeD1PacketRowExpansion SemiprimeD1PacketGlobalRowForm\nopen SemiprimeD1ChildGraph SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n/-- The actual tile ordinal is its literal flattened-slot residue in both\nclassifier branches. -/\ntheorem acquireOne_tile {n F a : ℕ} {arity : Fin F→ℕ}\n    (source : SemiprimeD1PacketReplayOriginal.Acquired n F a arity)\n    (packet : Fin source.state.packets.length) (i : Fin a) (group : List Bool)\n    (mode : SemiprimeD1ModeCatalog.Mode) :\n    (SemiprimeD1PacketModeMask.acquireOne source packet i group mode).tile=mode.slot%2^(i.val+1) := by\n  unfold SemiprimeD1PacketModeMask.acquireOne\n  dsimp only\n  split_ifs <;> rfl\n\n/-- Actual original in-packet row coefficient, with both physical routing tests\nclosed from the real endpoint and original group relation. -/\ntheorem coefficient_in_packet (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (endpoint : Endpoint (n+F))\n    (he : endpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hside : endpoint.side=true) (bit : Bool) (mode : SemiprimeD1ModeCatalog.Mode)\n    (hpacket : mode.slot/2^(i.val+1)=packet.val)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (hpos : ctx.Positive) (hp : 0<ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    let source := SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n    let tile : Fin (2^(i.val+1)) := ⟨mode.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n    let item := SemiprimeD1PacketModeMask.acquireOne source packet i\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode\n    let row := (wire a endpoint bit).1\n    interpret ctx (coefficient ctx z a i t row item).words=\n      if (SemiprimeD1ModeRoutingBits.acquire source.state.packets[packet.val] a i tile).source=\n          (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits then 0\n      else if bit then modeValue ctx z a i t row tile mode.order else -modeValue ctx z a i t row tile mode.order := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n  let tile : Fin (2^(i.val+1)) := ⟨mode.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n  let item := SemiprimeD1PacketModeMask.acquireOne source packet i\n    (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode\n  let row := (wire a endpoint bit).1\n  have hh := SemiprimeD1PacketModeMask.acquireOne_here source packet i\n    (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode hpacket\n  have hc := coefficient_value ctx z a i t row item hpos hp ht hi\n  dsimp only at hc\n  change interpret ctx (coefficient ctx z a i t row item).words=\n    if (SemiprimeD1ModeRoutingBits.acquire source.state.packets[packet.val] a i tile).source=\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits then 0\n    else if bit then modeValue ctx z a i t row tile mode.order else -modeValue ctx z a i t row tile mode.order\n  have hip : item.inPacket=true := hh.1\n  by_cases hs : (SemiprimeD1ModeRoutingBits.acquire source.state.packets[packet.val] a i tile).source=\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits\n  · have hf : item.sourceHere=true := hh.2.2.mpr hs\n    rw [hc]\n    simp only [hf,Bool.not_true,Bool.and_false,Bool.false_and,Bool.false_eq_true,ite_false,hs,ite_true]\n  · have htarget := original_row_target n F r a arity owner packet i g tile endpoint he hside hs\n    have htf : item.targetHere=true := hh.2.1.mpr htarget\n    have hsf : item.sourceHere=false := by\n      cases hx : item.sourceHere\n      · rfl\n      · exact False.elim (hs (hh.2.2.mp hx))\n    have hb := SemiprimeD1PacketModeOriginal.row_test_true n F r a arity owner packet i g tile\n      endpoint he hside hs bit\n    rw [sameBit_value] at hb\n    have hb' : (row.slot.val.testBit i.val == tile.val.testBit i.val)=true := hb\n    have hrowbit : row.bit=bit := (wire_data a endpoint bit).1\n    have hti : item.tile=tile.val := acquireOne_tile source packet i _ mode\n    have htl : tile.val<2^a := tile.isLt.trans_le (Nat.pow_le_pow_right (by omega) (by omega))\n    have hm : item.mode=mode := SemiprimeD1PacketModeMask.acquireOne_mode source packet i _ mode\n    rw [hc]\n    simp only [hip,htf,hsf,Bool.not_false,Bool.and_true,hti,Nat.mod_eq_of_lt htl,hb',hrowbit,ite_true,\n      hs,ite_false,hm]\n    rfl\n\nend\nend RiemannGaussian.SemiprimeD1PacketCoefficientAlignment\n","RiemannGaussian.SemiprimeD1PacketEntryBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketModeMask\nimport RiemannGaussian.SemiprimeD1PacketEntryInputs\nimport RiemannGaussian.SemiprimeD1JetKernelBits\nimport RiemannGaussian.SemiprimeD1JetModeBits\nimport RiemannGaussian.SemiprimeD1TensorTables\n\n/-! # Concrete packet row recipes and eager packet tables\nThe actual child bucket supplies every row/column bit and orientation slot.\nGlobal beta is restricted to this packet's target modes before coefficient\nextraction. Source factors use the original beta. No old tensor evaluator,\nmode-coefficient callback, or semantic ring value appears on the runtime path.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1PacketEntryBits\nopen SemiprimeD1JetAxes SemiprimeD1PacketEntryInputs\nopen SemiprimeD1JetAffineCoefficient (JetRun Row)\n\n/-- Borrow an already cached physical jet without recounting its producer. -/\ndef borrow (value : JetRun) : JetRun := ⟨value.words,0⟩\n\n/-- Concrete product retaining both actual producer reports exactly once. -/\ndef multiply (ctx : Context) (left right : JetRun) : JetRun :=\n  let out := SemiprimeD1JetRingBits.mul ctx left.words right.words\n  ⟨out.words,left.clock+right.clock+out.clock+3⟩\n\n/-- Literal sign application; negative uses the actual acquired modular minus one. -/\ndef signed (ctx : Context) (negative : Bool) (value : JetRun) : JetRun :=\n  if negative then multiply ctx (SemiprimeD1JetKernelBits.integerVector ctx (-1)) value\n  else\n    let out := copyVector value.words\n    ⟨out.1,value.clock+out.2+3⟩\n\n/-- One actual local-column contribution to a real row. -/\ndef baseTerm (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) : JetRun :=\n  if column.bit then SemiprimeD1JetKernelBits.acquireOriginal ctx (borrow z) a t row.slot column.slot\n  else SemiprimeD1JetAffineCoefficient.zero ctx\n\n/-- Actual local constant term, including `1-base` for a false row bit. -/\ndef rowBase (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) : JetRun :=\n  let base := SemiprimeD1JetAffineCoefficient.sumRuns ctx (columns.map (baseTerm ctx z a t row))\n  if row.bit then base else\n    let one := SemiprimeD1JetAffineCoefficient.one ctx\n    let negative := signed ctx true base\n    let out := SemiprimeD1JetRingBits.add ctx one.words negative.words\n    ⟨out.words,one.clock+negative.clock+out.clock+5⟩\n\n/-- Acquire the two original finite indices and compare their actual ith Boolean bits. -/\ndef sameBit (x y i : ℕ) : SemiprimeMaterializedWords.Run Bool :=\n  let xb := SemiprimeSourceHistogramPortKeys.encodeKey x\n  let yb := SemiprimeSourceHistogramPortKeys.encodeKey y\n  let left := SemiprimeD1ModeRoutingBits.readBit xb.bits i\n  let right := SemiprimeD1ModeRoutingBits.readBit yb.bits i\n  ⟨left.value==right.value,xb.clock+yb.clock+left.work+right.work+5⟩\n\n/-- The bit test is executed from acquired index bytes, not a supplied branch answer. -/\ntheorem sameBit_value (x y i : ℕ) : (sameBit x y i).value=(x.testBit i == y.testBit i) := by\n  simp only [sameBit,SemiprimeD1ModeRoutingTile.readBit_testBit,\n    SemiprimeSourceHistogramPortKeys.encodeKey_value]\n\n/-- Actual signed crossing mode. A physical same-bit test also guards the original\nodd-unit mode supplier, rather than assuming that bit relation as advice. -/\ndef coefficient (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) : JetRun :=\n  let tile : Fin (2^a) := ⟨item.tile%2^a,Nat.mod_lt _ (by positivity)⟩\n  let test := sameBit row.slot.val tile.val i.val\n  if item.inPacket && item.targetHere && !item.sourceHere && test.value then\n    let mode := SemiprimeD1JetModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile\n    let out := signed ctx (!row.bit) mode\n    ⟨out.words,out.clock+test.work+item.tile+row.slot.val+2^a+10⟩\n  else\n    let out := SemiprimeD1JetAffineCoefficient.zero ctx\n    ⟨out.words,out.clock+test.work+item.tile+row.slot.val+2^a+10⟩\n\n/-- Actual coefficient vector acquisition in the unchanged global catalogue order. -/\ndef coefficients (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) :\n    List SemiprimeD1PacketModeMask.Item→SemiprimeMaterializedWords.Run (List (List (List Bool)))\n  | [] => ⟨[],1⟩\n  | item::items =>\n    let value := coefficient ctx z a i t row item\n    let tail := coefficients ctx z a i t row items\n    ⟨value.words::tail.value,value.clock+tail.work+4⟩\n\n/-- Concrete row recipe and its retained base/mode data acquisition. -/\ndef recipe (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) : SemiprimeMaterializedWords.Run Row :=\n  let base := rowBase ctx z a t row columns\n  let modes := coefficients ctx z a i t row items\n  ⟨⟨base.words,modes.value⟩,base.clock+modes.work+5⟩\n\n/-- Acquire every actual real-row recipe once and preserve the original row order. -/\ndef recipes (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) : List (Wire a)→SemiprimeMaterializedWords.Run (List Row)\n  | [] => ⟨[],1⟩\n  | row::rows =>\n    let value := recipe ctx z a i t row columns items\n    let tail := recipes ctx z a i t columns items rows\n    ⟨value.value::tail.value,value.work+tail.work+4⟩\n\n/-- Actual source-tile column contribution `j^order * X`, with j acquired from\nthis literal slot; no native power or supplied ring coefficient is used. -/\ndef sourceTerm (ctx : Context) (a : ℕ) (i : Fin a)\n    (item : SemiprimeD1PacketModeMask.Item) (column : Wire a) : JetRun :=\n  let tiles := 2^(i.val+1)\n  if column.bit && (column.slot.val%tiles == item.tile) then\n    let index := SemiprimeD1JetPolynomialBits.magnitude ctx.precision (column.slot.val/tiles)\n    let scalar := SemiprimeD1JetPolynomialBits.scalar ctx index.bits\n    let out := SemiprimeD1JetPolynomialBits.power ctx scalar.words item.mode.order\n    ⟨out.words,index.clock+scalar.clock+out.clock+column.slot.val+tiles+8⟩\n  else\n    let out := SemiprimeD1JetAffineCoefficient.zero ctx\n    ⟨out.words,out.clock+column.slot.val+tiles+5⟩\n\n/-- One source mode factor uses the ORIGINAL global exponent, including 0^0=1. -/\ndef sourceFactor (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (index : ℕ) (item : SemiprimeD1PacketModeMask.Item) : JetRun :=\n  if item.inPacket && item.sourceHere then\n    let exponent := SemiprimeD1AffineCoefficient.read 0 beta index\n    let base := SemiprimeD1JetAffineCoefficient.sumRuns ctx (columns.map (sourceTerm ctx a i item))\n    let out := SemiprimeD1JetPolynomialBits.power ctx base.words exponent.1\n    ⟨out.words,exponent.2+base.clock+out.clock+6⟩\n  else\n    let out := SemiprimeD1JetAffineCoefficient.one ctx\n    ⟨out.words,out.clock+4⟩\n\n/-- Concrete ordered source-mode product, with all actual factors retained. -/\ndef sourceProduct (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) : List SemiprimeD1PacketModeMask.Item→ℕ→JetRun\n  | [],_ => SemiprimeD1JetAffineCoefficient.one ctx\n  | item::items,index =>\n    let head := sourceFactor ctx a i columns beta index item\n    let tail := sourceProduct ctx a i columns beta items (index+1)\n    multiply ctx head tail\n\n/-- Actual single-entry execution. Header/source producers are retained by the\nouter table acquisition once; this function retains all per-assignment work. -/\ndef evaluate {V : ℕ} (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (items : SemiprimeD1PacketModeMask.Cache)\n    (endpoints : List (SemiprimeD1ChildGraph.Endpoint V)) (beta : List ℕ) (bits : List Bool) : JetRun :=\n  let input := gather a endpoints bits\n  let restricted := SemiprimeD1PacketModeMask.restrict items beta\n  let rows := recipes ctx (borrow z) a i t input.columns items.items input.rows\n  let target := SemiprimeD1JetAffineCoefficient.evaluate ctx items.items.length rows.value restricted.value\n  let source := sourceProduct ctx a i input.columns beta items.items 0\n  let out := multiply ctx target source\n  ⟨out.words,input.clock+restricted.work+rows.work+out.clock+beta.length+10⟩\n\nend RiemannGaussian.SemiprimeD1PacketEntryBits\n","RiemannGaussian.SemiprimeD1PacketGlobalRowForm":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketColumnPartition\n\n/-! # Original cross-group real-row expansion\nActual child source lists and actual replay routing discharge every crossing\nbit test. Global endpoint assignments are restricted by the literal acquired\nbucket order; no desired column list, owner map or row form is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nnamespace RiemannGaussian.SemiprimeD1PacketGlobalRowForm\nopen scoped BigOperators\nopen SemiprimeD1PacketEntryInputs SemiprimeD1PacketEntryBits\nopen SemiprimeD1PacketSourceAlignment SemiprimeD1PacketRowExpansion\nopen SemiprimeD1PacketColumnPartition SemiprimeD1ChildGraph\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n/-- Every acquired source-column wire has its literal original endpoint and\nassignment bit. This is derived from the actual gather scan. -/\ntheorem column_origin {V : ℕ} (a : ℕ) (bucket : List (Endpoint V))\n    (assignment : Endpoint V→Bool) (column : Wire a)\n    (hc : column∈(gather a bucket (bucket.map assignment)).columns) :\n    ∃e∈bucket,e.side=false ∧ column=(wire a e (assignment e)).1 := by\n  rw [(gather_assignment a bucket assignment).2] at hc\n  obtain ⟨e,he,hval⟩ := List.mem_filterMap.mp hc\n  cases hs : e.side\n  · simp only [hs,Bool.false_eq_true,ite_false,Option.some.injEq] at hval\n    exact ⟨e,he,hs,hval.symm⟩\n  · simp only [hs,ite_true,reduceCtorEq] at hval\n\n/-- A real row and a real column in different acquired groups meet the original\ncrossing bit condition. The column's source is proved from the physical group\ntest, rather than passed as an algebraic owner certificate. -/\ntheorem original_cross_column_test (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g h : Fin r) (hne : h≠g)\n    (rowEndpoint columnEndpoint : Endpoint (n+F))\n    (hr : rowEndpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hc : columnEndpoint∈((acquire n F r a arity owner i h).factors[packet.val]?).getD [])\n    (hrs : rowEndpoint.side=true) (hcs : columnEndpoint.side=false) (rowBit columnBit : Bool) :\n    (sameBit (wire a rowEndpoint rowBit).1.slot.val\n      (tileBase a i (wire a columnEndpoint columnBit).1).val i.val).value=true := by\n  let tile : Fin (2^(i.val+1)) :=\n    ⟨SemiprimeBitArithmetic.bitValue columnEndpoint.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n  have hs := original_column_source n F r a arity owner packet i h columnEndpoint hc hcs\n  have hsource : (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n    rw [hs]\n    intro he\n    have hn := congrArg SemiprimeBitArithmetic.bitValue he\n    simp only [SemiprimeSourceHistogramPortKeys.encodeKey_value] at hn\n    exact hne (Fin.ext hn)\n  have hb := SemiprimeD1PacketModeOriginal.row_test_true n F r a arity owner packet i g tile\n    rowEndpoint hr hrs hsource rowBit\n  have hlen := SemiprimeD1PacketEndpointOriginal.original_slot_length n F r a arity owner packet i h columnEndpoint hc\n  simpa only [tileBase,wire_slot a columnEndpoint columnBit hlen,tile] using hb\n\n/-- Original real-row term expansion for every actual source-column member. -/\ntheorem original_cross_term_D12 (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g h : Fin r) (hne : h≠g) (rowEndpoint : Endpoint (n+F))\n    (hr : rowEndpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hrs : rowEndpoint.side=true) (rowBit : Bool) (assignment : Endpoint (n+F)→Bool)\n    (column : Wire a)\n    (hc : column∈(let bucket := ((acquire n F r a arity owner i h).factors[packet.val]?).getD []\n      gather a bucket (bucket.map assignment)).columns)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (hpos : ctx.Positive) (hp : 0<ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    let row := (wire a rowEndpoint rowBit).1\n    interpret ctx (baseTerm ctx z a t row column).words=\n      if column.bit then ∑ b∈Finset.range (ctx.precision-1),\n        SemiprimeD1UniversalModeData.evaluate ctx.precision\n          (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes)) (interpret ctx z.words)\n          (SemiprimeD1UniversalModeData.acquireOriginal ctx.precision a i.val b t row.slot (tileBase a i column))*\n        (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes)\n          ((column.slot.val/2^(i.val+1):ℕ):ZMod (2^ctx.precision)))^b else 0 := by\n  obtain ⟨e,he,hs,hwire⟩ := column_origin a _ assignment column hc\n  subst column\n  exact baseTerm_D12 ctx z a i t _ _ hpos hp ht hi\n    (original_cross_column_test n F r a arity owner packet i g h hne rowEndpoint e hr he hrs hs rowBit (assignment e))\n\n/-- Fixed-tile D.12 only needs the bit condition at columns actually contributing\nto that tile; empty tiles require no crossing certificate. -/\ntheorem row_tile_relevant (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (row : Wire a) (tile : Fin (2^(i.val+1))) (columns : List (Wire a))\n    (hp : 0<ctx.precision) (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val)\n    (hb : ∀c∈columns,(c.bit && (c.slot.val%2^(i.val+1) == tile.val))=true →\n      (sameBit row.slot.val tile.val i.val).value=true) :\n    (columns.map (columnEntry ctx z a i t row tile)).sum=\n      ∑b∈Finset.range (ctx.precision-1),modeValue ctx z a i t row tile b*tilePower ctx a i columns tile.val b := by\n  simp_rw [tilePower_columns]\n  induction columns with\n  | nil => simp only [List.map_nil,List.sum_nil,mul_zero,Finset.sum_const_zero]\n  | cons c cs ih =>\n    have hc : columnEntry ctx z a i t row tile c=\n        ∑b∈Finset.range (ctx.precision-1),modeValue ctx z a i t row tile b*columnPower ctx a i tile c b := by\n      by_cases he : (c.bit && (c.slot.val%2^(i.val+1) == tile.val))=true\n      · exact column_D12 ctx z a i t row tile c hp ht hi (hb c List.mem_cons_self he)\n      · simp only [columnEntry,columnPower,he,Bool.false_eq_true,ite_false,mul_zero,Finset.sum_const_zero]\n    simp only [List.map_cons,List.sum_cons]\n    rw [hc,ih (fun c hc => hb c (List.mem_cons_of_mem _ hc)),←Finset.sum_add_distrib]\n    apply Finset.sum_congr rfl\n    intro b _\n    exact (mul_add _ _ _).symm\n\n/-- Every actual source group distinct from the real row's group has the exact\nfixed-tile expansion; all relevant bit tests are derived from real endpoints. -/\ntheorem original_cross_tile_D12 (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g h : Fin r) (hne : h≠g) (rowEndpoint : Endpoint (n+F))\n    (hr : rowEndpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hrs : rowEndpoint.side=true) (rowBit : Bool) (assignment : Endpoint (n+F)→Bool)\n    (tile : Fin (2^(i.val+1))) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (hp : 0<ctx.precision) (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    let bucket := ((acquire n F r a arity owner i h).factors[packet.val]?).getD []\n    let columns := (gather a bucket (bucket.map assignment)).columns\n    let row := (wire a rowEndpoint rowBit).1\n    (columns.map (columnEntry ctx z a i t row tile)).sum=\n      ∑b∈Finset.range (ctx.precision-1),modeValue ctx z a i t row tile b*tilePower ctx a i columns tile.val b := by\n  apply row_tile_relevant ctx z a i t _ tile _ hp ht hi\n  intro c hc htile\n  obtain ⟨e,he,hs,hwire⟩ := column_origin a _ assignment c hc\n  have hb := original_cross_column_test n F r a arity owner packet i g h hne rowEndpoint e\n    hr he hrs hs rowBit (assignment e)\n  have hv : c.slot.val%2^(i.val+1)=tile.val := beq_iff_eq.mp (Bool.and_eq_true_iff.mp htile).2\n  rw [←hwire] at hb\n  simpa only [tileBase,hv] using hb\n\n/-- The complete finite tile scan contains each original column term exactly\nonce, including Boolean-off columns and empty tiles. -/\ntheorem column_tiles (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (row column : Wire a) (hpos : ctx.Positive) (hp : 0<ctx.precision) :\n    (∑tile : Fin (2^(i.val+1)),columnEntry ctx z a i t row tile column)=\n      interpret ctx (baseTerm ctx z a t row column).words := by\n  let selected : Fin (2^(i.val+1)) := ⟨column.slot.val%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n  rw [SemiprimeD1PacketEntryComponents.baseTerm_value ctx z a t row column hpos hp]\n  rw [Finset.sum_eq_single selected]\n  · simp only [columnEntry,selected,beq_self_eq_true,Bool.and_true]\n  · intro tile _ hne\n    have hn : column.slot.val%2^(i.val+1)≠tile.val := by\n      intro he\n      exact hne (Fin.ext he.symm)\n    simp only [columnEntry,beq_iff_eq.not.mpr hn,Bool.and_false,Bool.false_eq_true,ite_false]\n  · simp only [Finset.mem_univ,not_true_eq_false,false_implies]\n\n/-- A literal column sum splits into the complete arithmetic-tile sum. -/\ntheorem columns_tiles (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (row : Wire a) (columns : List (Wire a)) (hpos : ctx.Positive) (hp : 0<ctx.precision) :\n    (columns.map (fun c => interpret ctx (baseTerm ctx z a t row c).words)).sum=\n      ∑tile : Fin (2^(i.val+1)),(columns.map (columnEntry ctx z a i t row tile)).sum := by\n  induction columns with\n  | nil => simp only [List.map_nil,List.sum_nil,Finset.sum_const_zero]\n  | cons c cs ih =>\n    simp only [List.map_cons,List.sum_cons,Finset.sum_add_distrib]\n    rw [column_tiles ctx z a i t row c hpos hp,ih]\n\n/-- Actual source-group columns under a common global endpoint assignment. -/\ndef columnsOf (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (i : Fin a)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (assignment : Endpoint (n+F)→Bool) (g : Fin r) : List (Wire a) :=\n  let bucket := ((acquire n F r a arity owner i g).factors[packet.val]?).getD []\n  (gather a bucket (bucket.map assignment)).columns\n\n/-- Distributing a list-valued group scan preserves all additive occurrences. -/\ntheorem sum_flatMap_map {A B C : Type*} [AddCommMonoid C]\n    (xs : List A) (f : A→List B) (value : B→C) :\n    ((xs.flatMap f).map value).sum=(xs.map (fun x => ((f x).map value).sum)).sum := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih =>\n    simp only [List.flatMap_cons,List.map_append,List.sum_append,List.map_cons,List.sum_cons,ih]\n\n/-- The full original packet-column sum is exactly the sum of the actual\nsource-group column sums; no partition or coverage premise is supplied. -/\ntheorem original_column_sum {C : Type*} [AddCommMonoid C]\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (i : Fin a)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (assignment : Endpoint (n+F)→Bool) (value : Wire a→C) :\n    ((originalSideWires n F r a arity owner false packet assignment).map value).sum=\n      ∑g : Fin r,((columnsOf n F r a arity owner i packet assignment g).map value).sum := by\n  have hp := original_groups_perm n F r a arity owner i false packet assignment\n  have hs := (hp.map value).sum_eq\n  simp only [Bool.false_eq_true,ite_false] at hs\n  rw [sum_flatMap_map] at hs\n  rw [←List.ofFn_eq_map,List.sum_ofFn] at hs\n  exact hs.symm\n\n/-- Full original evaluated real-row form: the same-group column contribution\nis retained literally, and every other actual source group is expanded over\nall original tiles and strict mode orders. All column and crossing hypotheses\nare derived from the actual graph, assignment restriction and replay routing. -/\ntheorem full_row_D12 (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (rowEndpoint : Endpoint (n+F))\n    (hr : rowEndpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hrs : rowEndpoint.side=true) (rowBit : Bool) (assignment : Endpoint (n+F)→Bool)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (hpos : ctx.Positive) (hp : 0<ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    let row := (wire a rowEndpoint rowBit).1\n    ((originalSideWires n F r a arity owner false packet assignment).map\n      (fun c => interpret ctx (baseTerm ctx z a t row c).words)).sum=\n      ∑h : Fin r,if h=g then\n        ((columnsOf n F r a arity owner i packet assignment h).map\n          (fun c => interpret ctx (baseTerm ctx z a t row c).words)).sum\n      else ∑tile : Fin (2^(i.val+1)),∑b∈Finset.range (ctx.precision-1),\n        modeValue ctx z a i t row tile b*\n          tilePower ctx a i (columnsOf n F r a arity owner i packet assignment h) tile.val b := by\n  dsimp only\n  rw [original_column_sum n F r a arity owner i packet assignment]\n  apply Finset.sum_congr rfl\n  intro h _\n  by_cases hh : h=g\n  · simp only [hh,ite_true]\n  · simp only [hh,ite_false]\n    rw [columns_tiles ctx z a i t _ _ hpos hp]\n    apply Finset.sum_congr rfl\n    intro tile _\n    exact original_cross_tile_D12 ctx z n F r a arity owner packet i g h hh rowEndpoint hr hrs\n      rowBit assignment tile t hp ht hi\n\n/-- Every actual source form outside its computed source group is zero. Empty\ntiles are handled by the literal list sum, without an occupancy hypothesis. -/\ntheorem original_tilePower_zero (ctx : Context) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (h : Fin r) (assignment : Endpoint (n+F)→Bool)\n    (tile : Fin (2^(i.val+1))) (b : ℕ)\n    (hn : (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n      (SemiprimeSourceHistogramPortKeys.encodeKey h.val).bits) :\n    tilePower ctx a i (columnsOf n F r a arity owner i packet assignment h) tile.val b=0 := by\n  rw [tilePower_columns]\n  apply List.sum_eq_zero\n  intro value hv\n  obtain ⟨c,hc,rfl⟩ := List.mem_map.mp hv\n  by_cases helig : (c.bit && (c.slot.val%2^(i.val+1) == tile.val))=true\n  · obtain ⟨e,he,hs,hwire⟩ := column_origin a _ assignment c hc\n    have hlen := SemiprimeD1PacketEndpointOriginal.original_slot_length n F r a arity owner packet i h e he\n    have hslot : c.slot.val=SemiprimeBitArithmetic.bitValue e.slot := by\n      rw [hwire,wire_slot a e (assignment e) hlen]\n    have hres : c.slot.val%2^(i.val+1)=tile.val := beq_iff_eq.mp (Bool.and_eq_true_iff.mp helig).2\n    rw [hslot] at hres\n    have ht : (⟨SemiprimeBitArithmetic.bitValue e.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩ : Fin (2^(i.val+1)))=tile :=\n      Fin.ext hres\n    have hsource := original_column_source n F r a arity owner packet i h e he hs\n    dsimp only at hsource\n    rw [ht] at hsource\n    exact False.elim (hn hsource)\n  · simp only [columnPower,helig,Bool.false_eq_true,ite_false]\n\n/-- The actual other-end route target of a crossing original row is its acquired\ngroup. This closes the target mask from replay data and the executed row test. -/\ntheorem original_row_target (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (tile : Fin (2^(i.val+1))) (endpoint : Endpoint (n+F))\n    (he : endpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hside : endpoint.side=true)\n    (hn : (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits) :\n    (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).target=\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n  obtain ⟨port,out,ho,hpacket,horigin⟩ :=\n    SemiprimeD1PacketEndpointOriginal.endpoint_origin owner source packet i g endpoint he\n  rcases horigin with ⟨heq,hrow⟩|⟨heq,hcolumn⟩\n  · have hnum := (testColour_correct (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits i.val\n      (SemiprimeD1PacketRows.read source.padding.source.selection.cache.rows.source.dictionary a out.source).left).mp hrow\n    have hsc : SemiprimeSourceCompactBits.Compact (SemiprimeD1ModeRoutingBits.fromReplay source packet i tile).source :=\n      (SemiprimeD1ModeRoutingOriginal.route_palette n F r a arity owner packet i tile).1\n    have hx : (((SemiprimeD1ModeRoutingOriginal.actualRows source out).left[i.val]?).getD [])≠\n        (SemiprimeD1ModeRoutingBits.fromReplay source packet i tile).source := by\n      intro heq\n      apply hn\n      rw [←(SemiprimeD1ModeRoutingBits.fromReplay_data source packet i tile).1]\n      apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ hsc\n        (SemiprimeSourceHistogramPortKeys.encodeKey_compact g.val)\n      rw [←heq]\n      exact hnum\n    have ht := (SemiprimeD1ModeRoutingOriginal.row_target_original n F r a arity owner packet i tile out ho hpacket hx).2\n    have htc := (SemiprimeD1ModeRoutingOriginal.route_palette n F r a arity owner packet i tile).2.2.1\n    have htarget : (SemiprimeD1ModeRoutingBits.fromReplay source packet i tile).target=\n        (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n      apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ htc\n        (SemiprimeSourceHistogramPortKeys.encodeKey_compact g.val)\n      rw [←ht]\n      exact hnum\n    rw [(SemiprimeD1ModeRoutingBits.fromReplay_data source packet i tile).2] at htarget\n    exact htarget\n  · rw [heq] at hside\n    simp only [endpoints,Bool.false_eq_true] at hside\n\nend\nend RiemannGaussian.SemiprimeD1PacketGlobalRowForm\n","RiemannGaussian.SemiprimeD1PacketInventory":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketRows\nimport RiemannGaussian.SemiprimeSourceHistogramTrieStore\n\n/-! # Sparse replay inventory of actual real ports\nEach original occurrence is replayed once. Its old class counter is the padding\nindex; the physical orientation produces packet and slot bytes. Only observed\npacket keys are recorded. Slot payloads are positive physical occurrence IDs.\nGlobal slot injectivity/capacity is a separate obligation, not a runtime oracle.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1PacketInventory\nopen SemiprimeSourceHistogramTrie\n\n/-- One acquired real-port placement, in original occurrence order. -/\nstructure Placement where\n  /-- Original selected pair bytes. -/\n  source : List Bool\n  /-- Old class-frequency bytes copied by the same bump traversal. -/\n  padding : List Bool\n  /-- Actual generated packet key. -/\n  packet : List Bool\n  /-- Actual orientation slot. -/\n  slot : List Bool\n  /-- Positive original occurrence ID, physically incremented. -/\n  edge : List Bool\n  /-- Parser and equal-row-shape flags. -/\n  valid : Bool\n\n/-- Sparse persistent inventory, with no full orbit or palette catalogue. -/\nstructure State where\n  /-- Original pair-class frequencies during replay. -/\n  classes : Trie\n  /-- Marker map for observed packet keys only. -/\n  seen : Trie\n  /-- Actual distinct-key insertion candidates, in reverse discovery order. -/\n  packets : List (List Bool)\n  /-- Framed packet/slot map to positive original occurrence IDs. -/\n  slots : Trie\n  /-- Last assigned occurrence ID. -/\n  next : List Bool\n  /-- Retained producer, reader, replay and control reports. -/\n  clock : ℕ\n\n/-- Start replay with the already paid original acquisition retained exactly once. -/\ndef initial (clock : ℕ) : State := ⟨.empty,.empty,[],.empty,[],clock+2⟩\n\n/-- One literal replay step. No native labels or semantic row getters execute. -/\ndef step (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) : Placement × State :=\n  let changed := bump state.classes key\n  let rows := SemiprimeD1PacketRows.read dict a key\n  let oriented := SemiprimeD1OrientationBits.acquire rows.left rows.right changed.old\n  let id := SemiprimeSourceCompactBits.increment state.next\n  let address := SemiprimeSourceHistogramKeyBits.pair oriented.key oriented.slots\n  let written := SemiprimeSourceHistogramTrieStore.put state.slots address.bits id.bits\n  let present := lookup state.seen oriented.key\n  let marked := SemiprimeSourceHistogramTrieStore.put state.seen oriented.key [true]\n  let copied := SemiprimeSourceCompactBits.copy oriented.key\n  let fresh := present.bits.isEmpty\n  let packets := if fresh then copied.bits::state.packets else state.packets\n  let out := ⟨changed.trie,marked.trie,packets,written.trie,id.bits,\n    state.clock+changed.clock+rows.clock+oriented.clock+id.clock+address.clock+\n      written.clock+present.clock+marked.clock+copied.clock+25⟩\n  (⟨key,changed.old,oriented.key,oriented.slots,id.bits,rows.valid && oriented.valid⟩,out)\n\n/-- Actual same-order traversal of the original selected-pair stream. -/\ndef replay (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    : List (List Bool) → State → List Placement × State\n  | [],state => ([],state)\n  | key::keys,state =>\n    let here := step dict a state key\n    let tail := replay dict a keys here.2\n    (here.1::tail.1,tail.2)\n\n/-- Retained original selection and sparse placements; no supplied answer fields. -/\nstructure Acquired (n F a : ℕ) (arity : Fin F→ℕ) where\n  /-- Once-acquired original cache, selected IDs, real keys and frequency state. -/\n  source : SemiprimeD1IncidenceAcquisition.Acquired n F a arity\n  /-- One placement per actual original occurrence. -/\n  placements : List Placement\n  /-- Final sparse replay inventory and complete retained report. -/\n  state : State\n\n/-- Original-input endpoint: acquire once, then replay only its actual real keys. -/\ndef acquire (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) : Acquired n F a arity :=\n  let source := SemiprimeD1IncidenceAcquisition.acquire n F r a arity owner\n  let out := replay source.selection.cache.rows.source.dictionary a source.keys\n    (initial source.state.clock)\n  ⟨source,out.1,out.2⟩\n\n/-- Replay preserves every original occurrence and its exact order/multiplicity. -/\ntheorem replay_sources (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    ((replay dict a keys state).1.map Placement.source)=keys := by\n  induction keys generalizing state with\n  | nil => rfl\n  | cons key keys ih => simp only [replay,List.map_cons,step,ih]\n\n/-- Every original real port appears once, even parallel equal-key occurrences. -/\ntheorem acquire_sources (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ((acquire n F r a arity owner).placements.map Placement.source)=\n      (SemiprimeD1IncidenceAcquisition.acquire n F r a arity owner).keys :=\n  replay_sources _ _ _ _\n\n/-- Exact old counter from the very same executed update, not an advised index. -/\ntheorem step_padding (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) :\n    (step dict a state key).1.padding=stored state.classes key := bump_old _ _\n\n/-- The positive occurrence counter really advances by one. -/\ntheorem step_edge (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) :\n    SemiprimeBitArithmetic.bitValue (step dict a state key).1.edge=\n      SemiprimeBitArithmetic.bitValue state.next+1 :=\n  SemiprimeSourceCompactBits.increment_value _\n\n/-- Exact per-key replay frequency transition, including missing and prefix keys. -/\ntheorem step_frequency (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key query : List Bool) :\n    value (step dict a state key).2.classes query=\n      if query=key then value state.classes query+1 else value state.classes query :=\n  bump_value _ _ _\n\n/-- The just-produced packet/slot address really stores this positive edge ID.\nGlobal preservation for other steps additionally needs slot-address injectivity. -/\ntheorem step_slot (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) :\n    stored (step dict a state key).2.slots\n      (SemiprimeSourceHistogramKeyBits.frame (step dict a state key).1.packet\n        (step dict a state key).1.slot)=(step dict a state key).1.edge := by\n  simp only [step,SemiprimeSourceHistogramKeyBits.pair_bits,\n    SemiprimeSourceHistogramTrieStore.put_stored,ite_true]\n\n/-- No earlier producer/read/replay report is dropped by one step. -/\ntheorem step_retains (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) : state.clock≤(step dict a state key).2.clock := by\n  unfold step\n  dsimp only\n  omega\n\n/-- The final report retains the entire actual traversal prefix. -/\ntheorem replay_retains (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    state.clock≤(replay dict a keys state).2.clock := by\n  induction keys generalizing state with\n  | nil => exact le_rfl\n  | cons key keys ih => exact le_trans (step_retains dict a state key) (ih _)\n\n/-- Later occurrences cannot reuse a class index already present at entry. -/\ntheorem replay_padding_lower (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (out : Placement)\n    (hout : out∈(replay dict a keys state).1) :\n    value state.classes out.source≤SemiprimeBitArithmetic.bitValue out.padding := by\n  induction keys generalizing state with\n  | nil => simp [replay] at hout\n  | cons key keys ih =>\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at hout\n    rcases List.mem_cons.mp hout with h|h\n    · subst out\n      rw [step_padding]\n      exact le_rfl\n    · have hh := ih (step dict a state key).2 h\n      have hm : value state.classes out.source≤value (step dict a state key).2.classes out.source := by\n        rw [step_frequency]\n        split_ifs <;> omega\n      exact le_trans hm hh\n\n/-- Distinct real occurrences have distinct (original class, padding) pairs. -/\ntheorem replay_indices_nodup (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    ((replay dict a keys state).1.map (fun p => (p.source,SemiprimeBitArithmetic.bitValue p.padding))).Nodup := by\n  induction keys generalizing state with\n  | nil => exact List.nodup_nil\n  | cons key keys ih =>\n    rw [replay,List.map_cons,List.nodup_cons]\n    refine ⟨?_,ih _⟩\n    intro hm\n    obtain ⟨out,hout,heq⟩ := List.mem_map.mp hm\n    have hs : out.source=key := congrArg Prod.fst heq\n    have hv := congrArg Prod.snd heq\n    have hl := replay_padding_lower dict a keys (step dict a state key).2 out hout\n    rw [hs,step_frequency] at hl\n    simp only [ite_true] at hl\n    have old : SemiprimeBitArithmetic.bitValue (step dict a state key).1.padding=value state.classes key := by\n      rw [step_padding]\n      rfl\n    rw [old] at hv\n    omega\n\n/-- Exact sparse discovery-marker invariant; no bucket coverage is supplied. -/\ndef SeenGood (state : State) : Prop := state.packets.Nodup ∧\n  ∀ key,stored state.seen key=if key∈state.packets then [true] else []\n\n/-- The empty discovery state satisfies its concrete marker invariant. -/\ntheorem initial_seen (clock : ℕ) : SeenGood (initial clock) := by\n  refine ⟨List.nodup_nil,?_⟩\n  intro key\n  simp only [initial,stored_empty,List.not_mem_nil,ite_false]\n\n/-- Exactly first observations enter the sparse packet list. -/\ntheorem step_seen (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) (hg : SeenGood state) :\n    SeenGood (step dict a state key).2 := by\n  let packet := (SemiprimeD1OrientationBits.acquire\n    (SemiprimeD1PacketRows.read dict a key).left\n    (SemiprimeD1PacketRows.read dict a key).right (bump state.classes key).old).key\n  have hp : (lookup state.seen packet).bits=if packet∈state.packets then [true] else [] := by\n    rw [lookup_bits,hg.2]\n  have hpacks : (step dict a state key).2.packets=\n      if packet∈state.packets then state.packets else packet::state.packets := by\n    change (if (lookup state.seen packet).bits.isEmpty then\n      (SemiprimeSourceCompactBits.copy packet).bits::state.packets else state.packets)=_\n    rw [hp,SemiprimeSourceCompactBits.copy_bits]\n    by_cases hm : packet∈state.packets <;> simp only [hm,ite_true,ite_false,List.isEmpty_cons,\n      List.isEmpty_nil,Bool.false_eq_true]\n  constructor\n  · rw [hpacks]\n    split_ifs with hm\n    · exact hg.1\n    · exact List.nodup_cons.mpr ⟨hm,hg.1⟩\n  · intro query\n    change stored (SemiprimeSourceHistogramTrieStore.put state.seen packet [true]).trie query=_\n    rw [SemiprimeSourceHistogramTrieStore.put_stored,hg.2,hpacks]\n    by_cases hm : packet∈state.packets <;> by_cases he : query=packet <;> simp [hm,he]\n\n/-- Discovery list remains duplicate-free after the actual entire replay. -/\ntheorem replay_seen (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (hg : SeenGood state) :\n    SeenGood (replay dict a keys state).2 := by\n  induction keys generalizing state with\n  | nil => exact hg\n  | cons key keys ih => exact ih _ (step_seen dict a state key hg)\n\n/-- Exact actual per-class frequency after replay, including every multiplicity. -/\ntheorem replay_frequency (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (query : List Bool) :\n    value (replay dict a keys state).2.classes query=value state.classes query+keys.count query := by\n  induction keys generalizing state with\n  | nil => simp only [replay,List.count_nil,Nat.add_zero]\n  | cons key keys ih =>\n    rw [replay,ih,step_frequency,List.count_cons]\n    by_cases he : query=key\n    · subst query\n      simp\n      omega\n    · have hb : (key==query)=false := by simp [Ne.symm he]\n      simp only [he,ite_false,hb,Bool.false_eq_true,ite_false]\n      omega\n\n/-- No class count decreases during the literal suffix traversal. -/\ntheorem replay_frequency_mono (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (query : List Bool) :\n    value state.classes query≤value (replay dict a keys state).2.classes query := by\n  rw [replay_frequency]\n  omega\n\n/-- Every copied old class counter is strictly below its final actual load. -/\ntheorem replay_padding_upper (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (out : Placement)\n    (hout : out∈(replay dict a keys state).1) :\n    SemiprimeBitArithmetic.bitValue out.padding<value (replay dict a keys state).2.classes out.source := by\n  induction keys generalizing state with\n  | nil => simp [replay] at hout\n  | cons key keys ih =>\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at hout\n    rcases List.mem_cons.mp hout with h|h\n    · subst out\n      have hm := replay_frequency_mono dict a keys (step dict a state key).2 key\n      change SemiprimeBitArithmetic.bitValue (step dict a state key).1.padding<_\n      rw [step_padding]\n      have hs := step_frequency dict a state key key\n      simp only [ite_true] at hs\n      change SemiprimeBitArithmetic.bitValue (stored state.classes key)<_\n      change value state.classes key<_\n      change value state.classes key<value (replay dict a keys (step dict a state key).2).2.classes key\n      omega\n    · exact ih (step dict a state key).2 h\n\n/-- Original compact frequency counters give compact copied old indices. -/\ntheorem replay_padding_compact (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (hc : CompactCounters state.classes)\n    (out : Placement) (hout : out∈(replay dict a keys state).1) :\n    SemiprimeSourceCompactBits.Compact out.padding := by\n  induction keys generalizing state with\n  | nil => simp [replay] at hout\n  | cons key keys ih =>\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at hout\n    rcases List.mem_cons.mp hout with h|h\n    · subst out\n      rw [step_padding]\n      exact hc key\n    · exact ih _ (bump_compact state.classes key hc) h\n\n/-- Each retained placement is literally the physical reader/orientation output. -/\ntheorem replay_oriented (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (out : Placement)\n    (hout : out∈(replay dict a keys state).1) :\n    let rows := SemiprimeD1PacketRows.read dict a out.source\n    let oriented := SemiprimeD1OrientationBits.acquire rows.left rows.right out.padding\n    out.packet=oriented.key ∧ out.slot=oriented.slots ∧ out.valid=(rows.valid && oriented.valid) := by\n  induction keys generalizing state with\n  | nil => simp [replay] at hout\n  | cons key keys ih =>\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at hout\n    rcases List.mem_cons.mp hout with h|h\n    · subst out\n      exact ⟨rfl,rfl,rfl⟩\n    · exact ih _ h\n\n/-- Sparse discovery records only keys of genuinely generated real placements. -/\ntheorem replay_packets_generated (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (packet : List Bool)\n    (hp : packet∈(replay dict a keys state).2.packets) :\n    packet∈state.packets ∨ ∃ out∈(replay dict a keys state).1,out.packet=packet := by\n  induction keys generalizing state with\n  | nil => exact Or.inl hp\n  | cons key keys ih =>\n    rcases ih (step dict a state key).2 hp with h|h\n    · change packet∈(if _ then _ else state.packets) at h\n      split_ifs at h with hf\n      · rcases List.mem_cons.mp h with he|he\n        · right\n          refine ⟨(step dict a state key).1,List.mem_cons_self,?_⟩\n          simpa only [step,SemiprimeSourceCompactBits.copy_bits] using he.symm\n        · exact Or.inl he\n      · exact Or.inl h\n    · right\n      obtain ⟨out,ho,he⟩ := h\n      exact ⟨out,List.mem_cons_of_mem _ ho,he⟩\n\n/-- Exact physical slot-address layout used by the insertion call. -/\ndef slotAddress (out : Placement) : List Bool :=\n  SemiprimeSourceHistogramKeyBits.frame out.packet out.slot\n\n/-- A suffix that writes no selected address preserves its exact stored bytes. -/\ntheorem replay_preserves (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (address : List Bool)\n    (ha : address∉(replay dict a keys state).1.map slotAddress) :\n    stored (replay dict a keys state).2.slots address=stored state.slots address := by\n  induction keys generalizing state with\n  | nil => rfl\n  | cons key keys ih =>\n    change address∉slotAddress (step dict a state key).1::\n      ((replay dict a keys (step dict a state key).2).1.map slotAddress) at ha\n    have hh := ih (step dict a state key).2 (fun hm => ha (List.mem_cons_of_mem _ hm))\n    change stored (replay dict a keys (step dict a state key).2).2.slots address=_\n    rw [hh]\n    have hn : address≠slotAddress (step dict a state key).1 := by\n      intro he\n      exact ha (List.mem_cons.mpr (Or.inl he))\n    have hput := SemiprimeSourceHistogramTrieStore.put_stored state.slots\n      (slotAddress (step dict a state key).1) (step dict a state key).1.edge address\n    simp only [hn,ite_false] at hput\n    simpa only [step,slotAddress,SemiprimeSourceHistogramKeyBits.pair_bits] using hput\n\n/-- Without duplicate generated addresses, the final sparse dictionary returns\nexactly the actual occurrence ID of every real port, not merely its last writer. -/\ntheorem replay_lookup (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State)\n    (hn : ((replay dict a keys state).1.map slotAddress).Nodup)\n    (out : Placement) (ho : out∈(replay dict a keys state).1) :\n    stored (replay dict a keys state).2.slots (slotAddress out)=out.edge := by\n  induction keys generalizing state with\n  | nil => simp [replay] at ho\n  | cons key keys ih =>\n    change (slotAddress (step dict a state key).1::\n      ((replay dict a keys (step dict a state key).2).1.map slotAddress)).Nodup at hn\n    have hnd := List.nodup_cons.mp hn\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at ho\n    rcases List.mem_cons.mp ho with he|he\n    · subst out\n      change stored (replay dict a keys (step dict a state key).2).2.slots _=_\n      rw [replay_preserves dict a keys (step dict a state key).2 _ hnd.1]\n      exact step_slot _ _ _ _\n    · exact ih (step dict a state key).2 hnd.2 he\n\n/-- Physical occurrence IDs are positive and grow beyond the entry counter. -/\ntheorem replay_edge_lower (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (out : Placement)\n    (ho : out∈(replay dict a keys state).1) :\n    SemiprimeBitArithmetic.bitValue state.next<SemiprimeBitArithmetic.bitValue out.edge := by\n  induction keys generalizing state with\n  | nil => simp [replay] at ho\n  | cons key keys ih =>\n    change out∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at ho\n    rcases List.mem_cons.mp ho with h|h\n    · subst out\n      rw [step_edge]\n      omega\n    · have hh := ih (step dict a state key).2 h\n      have hn : SemiprimeBitArithmetic.bitValue (step dict a state key).2.next=\n          SemiprimeBitArithmetic.bitValue state.next+1 := SemiprimeSourceCompactBits.increment_value _\n      omega\n\n/-- Literal positive edge IDs are exactly consecutive original occurrence numbers. -/\ntheorem replay_edges (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    ((replay dict a keys state).1.map (fun out => SemiprimeBitArithmetic.bitValue out.edge))=\n      List.range' (SemiprimeBitArithmetic.bitValue state.next+1) keys.length := by\n  induction keys generalizing state with\n  | nil => rfl\n  | cons key keys ih =>\n    change SemiprimeBitArithmetic.bitValue (step dict a state key).1.edge::\n      ((replay dict a keys (step dict a state key).2).1.map _)=_\n    rw [ih,step_edge]\n    have hn : SemiprimeBitArithmetic.bitValue (step dict a state key).2.next=\n        SemiprimeBitArithmetic.bitValue state.next+1 := SemiprimeSourceCompactBits.increment_value _\n    rw [hn]\n    simp only [List.length_cons,List.range'_succ,Nat.add_assoc]\n\n/-- Physical lookup of a completed packet slot, including address framing/read. -/\ndef lookupSlot (state : State) (packet slot : List Bool) : SemiprimeSourceCompactBits.Report :=\n  let address := SemiprimeSourceHistogramKeyBits.pair packet slot\n  let out := lookup state.slots address.bits\n  ⟨out.bits,address.clock+out.clock+4⟩\n\n/-- Literal byte semantics of the executed slot lookup. -/\ntheorem lookupSlot_bits (state : State) (packet slot : List Bool) :\n    (lookupSlot state packet slot).bits=stored state.slots\n      (SemiprimeSourceHistogramKeyBits.frame packet slot) := by\n  simp only [lookupSlot,SemiprimeSourceHistogramKeyBits.pair_bits,lookup_bits]\n\nend RiemannGaussian.SemiprimeD1PacketInventory\n","RiemannGaussian.SemiprimeD1PacketReplayCapacity":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketReplayOriginal\nimport RiemannGaussian.SemiprimeD1PacketSlotCapacity\n\n/-! # Full-slot coverage and capacity of the actual sparse packet inventory\nFinite palette functions occur only in this erased image-counting proof. The\nexecuted inventory enumerates actual real ports and observed packet keys only.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2600000\nnamespace RiemannGaussian.SemiprimeD1PacketReplayCapacity\nopen SemiprimeD1PacketReplayOriginal SemiprimeD1OrientationPalette\nopen SemiprimeD1OrientationComplete SemiprimeBitArithmetic\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\n\n/-- Erased finite padded-input domain used solely for cardinality. -/\nabbrev Input (r a H : ℕ) := (Word r a×Word r a)×Fin H\n\n/-- Deterministic orientation map, used only for a finite image proof. -/\nnoncomputable def encode (r a H : ℕ) (input : Input r a H) : List Bool×(Fin a→Bool) :=\n  let out := SemiprimeD1OrientationBits.acquire (fields input.1.1) (fields input.1.2)\n    (SemiprimeSourceHistogramHeadRefinement.numberKey input.2.val)\n  (out.key,fun q => (out.slots[q.val]?).getD false)\n\n/-- Every slot of each actually observed packet has a genuine finite original\npalette/padding preimage. No desired inverse or bucket catalogue is supplied. -/\ntheorem covers (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (packet : List Bool)\n    (hp : packet∈(acquire n F r a arity owner).state.packets) (slot : Fin a→Bool) :\n    ∃ input : Input r a (bitValue (acquire n F r a arity owner).padding.padding),\n      encode r a _ input=(packet,slot) := by\n  obtain ⟨left,right,j,hl,hr,hla,hra,hj,hjlt,hkey⟩ :=\n    observed_generated n F r a arity owner packet hp\n  let H := bitValue (acquire n F r a arity owner).padding.padding\n  have hd : 2^a∣H := SemiprimeD1PacketPadding.packet_dvd_padding n F r a arity owner\n  have hfull := SemiprimeD1OrientationForward.generated_full_slots r a left right j\n    (List.ofFn slot) H (hl.trans hr.symm) hl hla hra hj hjlt hd List.length_ofFn\n  let back := SemiprimeD1OrientationInverse.recover\n    (SemiprimeD1OrientationBits.acquire left right j).key (List.ofFn slot)\n  change SemiprimeSourceCompactBits.Compact back.index ∧ bitValue back.index<H ∧ _ at hfull\n  obtain ⟨leftId,_,hleft⟩ := hfull.2.2.2.1\n  obtain ⟨rightId,_,hright⟩ := hfull.2.2.2.2\n  have hi : SemiprimeSourceHistogramHeadRefinement.numberKey (bitValue back.index)=back.index := by\n    apply SemiprimeSourceCompactWordIds.compact_value_injective _ _\n      (SemiprimeSourceHistogramHeadRefinement.numberKey_compact _) hfull.1\n    exact SemiprimeSourceHistogramHeadRefinement.numberKey_value _\n  refine ⟨((SemiprimeSourceWordBankSemantics.decode r a leftId,\n    SemiprimeSourceWordBankSemantics.decode r a rightId),⟨bitValue back.index,hfull.2.1⟩),?_⟩\n  have hk := congrArg Prod.fst hfull.2.2.1\n  have hs := congrArg (fun out => out.2.1) hfull.2.2.1\n  change (SemiprimeD1OrientationBits.acquire back.left back.right back.index).key=\n    (SemiprimeD1OrientationBits.acquire left right j).key at hk\n  change (SemiprimeD1OrientationBits.acquire back.left back.right back.index).slots=List.ofFn slot at hs\n  apply Prod.ext\n  · change (SemiprimeD1OrientationBits.acquire _ _ _).key=packet\n    rw [hleft,hright,hi,hk,hkey]\n  · funext q\n    change ((SemiprimeD1OrientationBits.acquire _ _ _).slots[q.val]?).getD false=slot q\n    rw [hleft,hright,hi,hs]\n    simp only [List.getElem?_ofFn,q.isLt,↓reduceDIte,Option.getD_some]\n\n/-- The actual sparse observed-packet capacity is at most the full padded input size. -/\ntheorem capacity (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquire n F r a arity owner).state.packets.length*2^a≤\n      r^(2*a)*bitValue (acquire n F r a arity owner).padding.padding := by\n  have hh := SemiprimeD1PacketSlotCapacity.boolean_capacity\n    (acquire n F r a arity owner).state.packets (packets_nodup n F r a arity owner) a\n    (encode r a _) (covers n F r a arity owner)\n  simpa only [Input,Word,Fintype.card_prod,Fintype.card_fun,Fintype.card_fin,Fintype.card_bool,\n    ←pow_add,←two_mul] using hh\n\n/-- Original degree and D.3 size bounds yield at most3M sparse acquired slots.\nEvery producer is the literal original-input endpoint; no packet answer is supplied. -/\ntheorem threeM_capacity (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (Δ : ℕ)\n    (ho : ∀ i∈SemiprimeD1CollisionOriginal.ports n F a arity,\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i => (owner i).val)\n        (SemiprimeD1CollisionOriginal.ports n F a arity) (owner i).val≤Δ)\n    (hf : ∀ i∈SemiprimeD1CollisionOriginal.ports n F a arity,\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i => n+i.1.val)\n        (SemiprimeD1CollisionOriginal.ports n F a arity) (n+i.1.val)≤Δ)\n    (hsmall : 2*(r^(2*a))^2*Δ≤(SemiprimeD1CollisionOriginal.ports n F a arity).length)\n    (hsize : r^(2*a)*2^a≤(SemiprimeD1CollisionOriginal.ports n F a arity).length) :\n    (acquire n F r a arity owner).state.packets.length*2^a≤\n      3*(SemiprimeD1CollisionOriginal.ports n F a arity).length :=\n  (capacity n F r a arity owner).trans\n    (SemiprimeD1PacketPadding.padding_scaled_le n F r a arity owner Δ ho hf hsmall hsize)\n\nend RiemannGaussian.SemiprimeD1PacketReplayCapacity\n","RiemannGaussian.SemiprimeD1PacketSourceProduct":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketModeOriginal\nimport RiemannGaussian.SemiprimeD1PacketEntryComponents\n\n/-! # Original-beta source product equals the actual supported exponent product\nThe base at each mode is constructed from the executed local column terms.\nOriginal acquired tuple membership discharges finite support/length internally;\nno source-factor answer or requested exponent catalogue is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2800000\nnamespace RiemannGaussian.SemiprimeD1PacketSourceProduct\nopen scoped BigOperators\nopen SemiprimeD1PacketModeProjection SemiprimeD1PacketEntryBits\nopen SemiprimeD1PacketEntryValue SemiprimeD1PacketEntryComponents SemiprimeD1PacketEntryInputs\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n/-- Actual acquired source base, zero past the finite descriptor cache. -/\ndef sourceBase (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (cache : SemiprimeD1PacketModeMask.Cache) (j : ℕ) : Carrier ctx :=\n  match cache.items[j]? with\n  | none => 0\n  | some item => (columns.map (fun column => interpret ctx (sourceTerm ctx a i item column).words)).sum\n\n/-- The literal indexed list is exactly its complete ordered finite-index enumeration. -/\ntheorem zipIdx_ofFn {A : Type*} (items : List A) :\n    items.zipIdx 0=List.ofFn (fun j : Fin items.length => (items[j.val],j.val)) := by\n  apply List.ext_getElem\n  · simp only [List.length_zipIdx,List.length_ofFn]\n  · intro j hj hj'\n    simp only [List.getElem_zipIdx,List.getElem_ofFn,Nat.zero_add]\n\n/-- Every actual global source slot occurs once with its ORIGINAL beta exponent. -/\ntheorem sourceProduct_finite (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (cache : SemiprimeD1PacketModeMask.Cache) (hpos : ctx.Positive) :\n    interpret ctx (sourceProduct ctx a i columns beta cache.items 0).words=\n      ∏ j : Fin cache.items.length,\n        if j.val∈sourceSet cache then sourceBase ctx a i columns cache j.val ^ beta.getD j.val 0 else 1 := by\n  rw [sourceProduct_value ctx _ _ _ _ _ _ hpos,zipIdx_ofFn,List.map_ofFn,List.prod_ofFn]\n  apply Finset.prod_congr rfl\n  intro j _\n  dsimp only [Function.comp_def]\n  rw [sourceFactor_value ctx a i columns beta j.val cache.items[j.val] hpos]\n  simp only [sourceSet,Set.mem_ofPred_eq,sourceEnabled,sourceBase,List.getElem?_eq_getElem j.isLt,\n    List.getD_eq_getElem?_getD]\n\n/-- Actual finite source-product execution equals the supported Finsupp product.\nThe sole generic support premise is later discharged from actual acquired tuples. -/\ntheorem sourceProduct_toFinsupp (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (cache : SemiprimeD1PacketModeMask.Cache) (hpos : ctx.Positive)\n    (hlen : beta.length≤cache.items.length) :\n    interpret ctx (sourceProduct ctx a i columns beta cache.items 0).words=\n      beta.toFinsupp.prod (fun j exponent =>\n        if j∈sourceSet cache then sourceBase ctx a i columns cache j ^ exponent else 1) := by\n  have hs : beta.toFinsupp.support⊆Finset.range cache.items.length := by\n    intro j hj\n    apply Finset.mem_range.mpr\n    by_contra hn\n    have hz := List.toFinsupp_apply_le beta j (hlen.trans (Nat.le_of_not_gt hn))\n    exact (Finsupp.mem_support_iff.mp hj) hz\n  have hp := Finsupp.prod_of_support_subset beta.toFinsupp hs\n    (fun j exponent => if j∈sourceSet cache then sourceBase ctx a i columns cache j ^ exponent else 1)\n    (by intro j _;simp only [pow_zero,ite_self])\n  rw [hp,Finset.prod_range]\n  simpa only [List.toFinsupp_apply] using sourceProduct_finite ctx a i columns beta cache hpos\n\n/-- Every ACTUALLY acquired original query has exactly the actual descriptor length. -/\ntheorem original_query_length (n F r a u p : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (i : Fin a)\n    (packet : Fin (SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner).packets.state.packets.length)\n    (g : Fin r) (beta : List ℕ)\n    (hb : beta∈(SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner).modes.values) :\n    beta.length=(SemiprimeD1PacketModeMask.fromModes\n      (SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner) packet i g).items.length := by\n  have hm := (SemiprimeD1OriginalModeAcquisition.modes_correct n F r a u i.val p arity owner beta).1.mp hb\n  have hlen := hm.1\n  simp only [SemiprimeD1ModeCatalog.weights,List.length_map,SemiprimeD1ModeCatalog.catalog_length] at hlen\n  have hc := congrArg List.length (SemiprimeD1PacketModeMask.fromModes_catalogue\n    (SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner) packet i g)\n  simp only [List.length_map,SemiprimeD1ModeCatalog.catalog_length] at hc\n  rw [SemiprimeD1OriginalModeAcquisition.precision_original] at hc\n  exact hlen.trans hc.symm\n\n/-- Closed original-query product identity: actual membership replaces length advice. -/\ntheorem original_source_product (ctx : Context) (n F r a u p : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (i : Fin a)\n    (packet : Fin (SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner).packets.state.packets.length)\n    (g : Fin r) (columns : List (Wire a)) (beta : List ℕ)\n    (hb : beta∈(SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner).modes.values)\n    (hpos : ctx.Positive) :\n    let cache := SemiprimeD1PacketModeMask.fromModes\n      (SemiprimeD1OriginalModeAcquisition.acquire n F r a u i.val p arity owner) packet i g\n    interpret ctx (sourceProduct ctx a i columns beta cache.items 0).words=\n      beta.toFinsupp.prod (fun j exponent =>\n        if j∈sourceSet cache then sourceBase ctx a i columns cache j ^ exponent else 1) := by\n  exact sourceProduct_toFinsupp ctx a i columns beta _ hpos\n    (original_query_length n F r a u p arity owner i packet g beta hb).le\n\nend\nend RiemannGaussian.SemiprimeD1PacketSourceProduct\n","RiemannGaussian.SemiprimeD1PhysicalRecursiveClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PhysicalRecursiveBounds\nimport RiemannGaussian.SemiprimeD1RecursiveCallTree\n\n/-! # Exact child-report separation for the actual physical recursive controller\nClock erasure below is a proof-side contribution measure retaining actual child\npayloads. It is not claimed to execute those payloads for free. Local phase work\nretains repeated source/header construction, including acquired menu reports.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 600000\nnamespace RiemannGaussian.SemiprimeD1PhysicalRecursiveClock\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- Proof-side removal of a continuation's report, retaining its actual payload. -/\ndef eraseClock (next : Context → Network → JetRun) (ctx : Context) (net : Network) : JetRun :=\n  ⟨(next ctx net).words,0⟩\n\n/-- Cached products preserve payload equality and exactly add child contributions. -/\ntheorem product_map {A : Type} (ctx : Context) (xs : List A)\n    (f g : A → JetRun) (cost : A → ℕ)\n    (hw : ∀ x ∈ xs, (f x).words=(g x).words)\n    (hc : ∀ x ∈ xs, (f x).clock=(g x).clock+cost x) :\n    (product ctx (xs.map f)).words=(product ctx (xs.map g)).words ∧\n    (product ctx (xs.map f)).clock=(product ctx (xs.map g)).clock+(xs.map cost).sum := by\n  induction xs with\n  | nil => simp [product]\n  | cons x xs ih =>\n    have ht:=ih (fun y hy => hw y (by simp [hy])) (fun y hy => hc y (by simp [hy]))\n    have hword:=hw x (by simp)\n    have hcost:=hc x (by simp)\n    constructor\n    · simp only [List.map_cons,product,hword,ht.1]\n    · simp only [List.map_cons,product,List.sum_cons]\n      rw [hword,ht.1,hcost,ht.2]\n      omega\n\n/-- Cached sums preserve payload equality and exactly add child contributions. -/\ntheorem sum_map {A : Type} (ctx : Context) (xs : List A)\n    (f g : A → JetRun) (cost : A → ℕ)\n    (hw : ∀ x ∈ xs, (f x).words=(g x).words)\n    (hc : ∀ x ∈ xs, (f x).clock=(g x).clock+cost x) :\n    (SemiprimeD1JetAffineCoefficient.sumRuns ctx (xs.map f)).words=\n      (SemiprimeD1JetAffineCoefficient.sumRuns ctx (xs.map g)).words ∧\n    (SemiprimeD1JetAffineCoefficient.sumRuns ctx (xs.map f)).clock=\n      (SemiprimeD1JetAffineCoefficient.sumRuns ctx (xs.map g)).clock+(xs.map cost).sum := by\n  induction xs with\n  | nil => simp [SemiprimeD1JetAffineCoefficient.sumRuns]\n  | cons x xs ih =>\n    have ht:=ih (fun y hy => hw y (by simp [hy])) (fun y hy => hc y (by simp [hy]))\n    have hword:=hw x (by simp)\n    have hcost:=hc x (by simp)\n    constructor\n    · simp only [List.map_cons,SemiprimeD1JetAffineCoefficient.sumRuns,hword,ht.1]\n    · simp only [List.map_cons,SemiprimeD1JetAffineCoefficient.sumRuns,List.sum_cons]\n      rw [hword,ht.1,hcost,ht.2]\n      omega\n\n/-- The literal mode/group product in one phase, as a proof-side named subterm. -/\ndef phaseTerm (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) (beta : List ℕ) : JetRun :=\n  let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n    parent.net.rows.length 64 a u i.val parent.ctx.precision\n    (arity parent.net.rows) (owner parent.net.rows)\n  let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n  let fresh:=SemiprimeD1FreshJetBits.acquireFresh parent.ctx q source.precision\n  let current : Context:=⟨q::parent.ctx.axes,source.precision⟩\n  product current ((List.finRange 64).map (fun g =>\n    let data:=SemiprimeD1ChildNetwork.fromSource parent.net source i g parent.ctx [q]\n      source.precision fresh t beta\n    let answer:=next current data.network\n    (⟨answer.words,data.clock+answer.clock+5⟩:JetRun)))\n\n/-- Exact one-mode report separation retains every repeated child/header/source\nconstruction cost in the erased local term. -/\ntheorem phaseTerm_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) (beta : List ℕ) :\n    (phaseTerm next parent a u t i beta).words=\n      (phaseTerm (eraseClock next) parent a u t i beta).words ∧\n    (phaseTerm next parent a u t i beta).clock=\n      (phaseTerm (eraseClock next) parent a u t i beta).clock+\n      ((List.finRange 64).map (fun g =>\n        (next (child parent a u t i beta g).ctx (child parent a u t i beta g).net).clock)).sum := by\n  unfold phaseTerm\n  apply product_map\n  · intro g hg\n    rfl\n  · intro g hg\n    dsimp only [eraseClock,child]\n    omega\n\n/-- The literal sum of acquired-mode products in a guarded phase. -/\ndef phaseTotal (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) : JetRun :=\n  let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n    parent.net.rows.length 64 a u i.val parent.ctx.precision\n    (arity parent.net.rows) (owner parent.net.rows)\n  let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n  SemiprimeD1JetAffineCoefficient.sumRuns ⟨q::parent.ctx.axes,source.precision⟩\n    (source.modes.values.map (phaseTerm next parent a u t i))\n\n/-- The sum of literal child clocks over an original active mode/group menu. -/\ndef modeChildClocks (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) : ℕ :=\n  let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n    parent.net.rows.length 64 a u i.val parent.ctx.precision\n    (arity parent.net.rows) (owner parent.net.rows)\n  (source.modes.values.map (fun beta => ((List.finRange 64).map (fun g =>\n    (next (child parent a u t i beta g).ctx (child parent a u t i beta g).net).clock)).sum)).sum\n\n/-- Actual mode sums preserve payloads and add exactly their real child clocks. -/\ntheorem phaseTotal_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) :\n    (phaseTotal next parent a u t i).words=\n      (phaseTotal (eraseClock next) parent a u t i).words ∧\n    (phaseTotal next parent a u t i).clock=\n      (phaseTotal (eraseClock next) parent a u t i).clock+modeChildClocks next parent a u t i := by\n  unfold phaseTotal modeChildClocks\n  apply sum_map\n  · intro beta hb\n    exact (phaseTerm_clock next parent a u t i beta).1\n  · intro beta hb\n    exact (phaseTerm_clock next parent a u t i beta).2\n\n/-- Literal flat-map child inventory retains multiplicities in its clock sum. -/\ntheorem sum_flatMap {A B : Type} (xs : List A) (f : A → List B) (cost : B → ℕ) :\n    ((xs.flatMap f).map cost).sum=(xs.map (fun x => ((f x).map cost).sum)).sum := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [List.flatMap_cons,List.map_append,List.sum_append,ih,\n      List.map_cons,List.sum_cons]\n\n/-- Exact phase report separation on the literal original grid and child menu.\nThe local replay retains EVERY nonrecursive source/header/acquisition report. -/\ntheorem phase_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) :\n    (phase next parent.ctx parent.net a u t).blocks=\n      (phase (eraseClock next) parent.ctx parent.net a u t).blocks ∧\n    (phase next parent.ctx parent.net a u t).precision=\n      (phase (eraseClock next) parent.ctx parent.net a u t).precision ∧\n    (phase next parent.ctx parent.net a u t).clock=\n      (phase (eraseClock next) parent.ctx parent.net a u t).clock+\n      ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum := by\n  dsimp only [phase,phaseChildren]\n  split\n  · rename_i hi\n    let i : Fin a:=⟨_,hi.1⟩\n    let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n      parent.net.rows.length 64 a u i.val parent.ctx.precision\n      (arity parent.net.rows) (owner parent.net.rows)\n    let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n    have ht:=phaseTotal_clock next parent a u t i\n    have hw : (phaseTotal next parent a u t i).words=\n        (phaseTotal (eraseClock next) parent a u t i).words := ht.1\n    refine ⟨?_,rfl,?_⟩\n    · simp only [List.map_map,Function.comp_def]\n      change ((List.range q).map (fun j =>\n          (SemiprimeD1JetBlockBits.extract parent.ctx j (phaseTotal next parent a u t i).words).words)).toArray=\n        ((List.range q).map (fun j =>\n          (SemiprimeD1JetBlockBits.extract parent.ctx j\n            (phaseTotal (eraseClock next) parent a u t i).words).words)).toArray\n      rw [hw]\n    · have hc:=ht.2\n      have hsum : ((source.modes.values.flatMap (fun beta =>\n          (List.finRange 64).map (child parent a u t i beta))).map\n          (fun c => (next c.ctx c.net).clock)).sum=modeChildClocks next parent a u t i := by\n        rw [sum_flatMap]\n        simp only [List.map_map,Function.comp_def,modeChildClocks,source]\n      change _+(phaseTotal next parent a u t i).clock+\n        (((List.range q).map (fun j =>\n          SemiprimeD1JetBlockBits.extract parent.ctx j (phaseTotal next parent a u t i).words)).map\n          (fun block => block.clock)).sum+_ =\n        _+(phaseTotal (eraseClock next) parent a u t i).clock+\n        (((List.range q).map (fun j => SemiprimeD1JetBlockBits.extract parent.ctx j\n          (phaseTotal (eraseClock next) parent a u t i).words)).map\n          (fun block => block.clock)).sum+_+_\n      rw [hw,hsum]\n      omega\n  · simp only [List.map_nil,List.sum_nil,Nat.add_zero,and_self]\n\n/-- Coordinate acquisition consumes only literal phase blocks, not phase reports. -/\ntheorem coordinate_congr (xs ys : Array PhaseRun) (k : ℕ)\n    (h : xs.map PhaseRun.blocks=ys.map PhaseRun.blocks) : coordinate xs k=coordinate ys k := by\n  let convert : Array (Array (List (List Bool))) → CoordinateData := fun blocks =>\n    let rows:=blocks.map (fun block =>\n      let copied:=block.map (fun words => SemiprimeD1JetBlockBits.readCopy words k)\n      (copied.map (fun out => out.bits),(copied.toList.map (fun out => out.clock)).sum+5*copied.size+3))\n    ⟨rows.map Prod.fst,(rows.toList.map Prod.snd).sum+5*rows.size+3⟩\n  have hx : coordinate xs k=convert (xs.map PhaseRun.blocks) := by\n    simp only [coordinate,convert,Array.map_map,Function.comp_def]\n  have hy : coordinate ys k=convert (ys.map PhaseRun.blocks) := by\n    simp only [coordinate,convert,Array.map_map,Function.comp_def]\n  exact hx.trans ((congrArg convert h).trans hy.symm)\n\n/-- The actual retained payload array is unchanged by proof-side child-report erasure. -/\ntheorem retained_blocks (next : Context → Network → JetRun) (parent : Call) (a u : ℕ) :\n    (SemiprimeD1RecursiveRecovery.retained next parent.ctx parent.net a u).map PhaseRun.blocks=\n    (SemiprimeD1RecursiveRecovery.retained (eraseClock next) parent.ctx parent.net a u).map PhaseRun.blocks := by\n  apply Array.toList_inj.mp\n  simp only [SemiprimeD1RecursiveRecovery.retained,Array.toList_map,\n    List.map_map,Function.comp_def]\n  apply List.map_congr_left\n  intro t ht\n  exact (phase_clock next parent a u t).1\n\n/-- Both the physical coordinate payload AND its entire local report are\nunchanged by erasing only phase-level child reports. -/\ntheorem recoverCoordinate_congr (ctx : Context) (a M u P : ℕ) (xs ys : Array PhaseRun)\n    (k : ℕ) (h : xs.map PhaseRun.blocks=ys.map PhaseRun.blocks) :\n    SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate ctx a M u P xs k=\n      SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate ctx a M u P ys k := by\n  unfold SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate\n  rw [coordinate_congr xs ys k h]\n\n/-- Exact sum of the actual retained phase reports; duplicate children keep their\nmultiplicity and every local source/header report remains in the erased term. -/\ntheorem phases_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ) :\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (phase next parent.ctx parent.net a u)).map PhaseRun.clock).sum=\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (phase (eraseClock next) parent.ctx parent.net a u)).map PhaseRun.clock).sum+\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).flatMap\n      (phaseChildren parent a u)).map (fun c => (next c.ctx c.net).clock)).sum := by\n  rw [sum_flatMap]\n  simp only [List.map_map,Function.comp_def]\n  have h : ∀ t ∈ List.finRange (SemiprimeD1WireKernelOriginal.size a),\n      (phase next parent.ctx parent.net a u t).clock=\n      (phase (eraseClock next) parent.ctx parent.net a u t).clock+\n        ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum := by\n    intro t ht\n    exact (phase_clock next parent a u t).2.2\n  rw [show (List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (fun t => (phase next parent.ctx parent.net a u t).clock)=\n      (List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (fun t => (phase (eraseClock next) parent.ctx parent.net a u t).clock+\n        ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum) from\n        List.map_congr_left h]\n  exact List.sum_map_add\n\nend RiemannGaussian.SemiprimeD1PhysicalRecursiveClock\n","RiemannGaussian.SemiprimeD1RecoveryRowsRun":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryWeightRunBounds\nimport RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition\n\n/-! # Cached canonical recovery rows from the original grid\nAll original node producers are executed internally. The native signed integer\nand rational-normalization boundary is explicit; no physical-bit clock is claimed.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1RecoveryRowsRun\nopen SemiprimeD1RecoveryScalarRun SemiprimeD1RecoveryWeightRun\nopen SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid\n\n/-- An actual cached canonical row with its original node and retained jet index. -/\nstructure Row where\n  /-- Original grid node. -/\n  node : ℕ\n  /-- Original local retained coefficient index. -/\n  index : ℕ\n  /-- Actual computed canonical signed numerator. -/\n  numerator : ℤ\n  /-- Actual computed canonical positive denominator. -/\n  denominator : ℕ\n  deriving Repr\n\n/-- Native grid enumeration with explicit traversal report. -/\ndef nodeIndices (a : ℕ) : Run (List (Fin (size a))) :=\n  let g:=geometry a 0\n  let ns:=indices g.size\n  let values:=ns.value.attach.map fun t =>\n    (⟨t.val,by\n      have ht : t.val ∈ (indices (geometry a 0).size).value := t.property\n      simpa only [indices_value,geometry_size,List.mem_range] using ht⟩:Fin (size a))\n  ⟨values,g.work+ns.work+4*ns.value.length+3⟩\n\n/-- Original node ordering, without an advised node list. -/\ntheorem nodeIndices_values (a : ℕ) :\n    (nodeIndices a).value.map Fin.val=List.range (size a) := by\n  simp [nodeIndices,indices_value,geometry_size]\n\n/-- Cached per-node row data and the full native acquisition report. -/\nstructure RowsReport where\n  /-- Actual original rows in node-major, local-index-major order. -/\n  rows : List Row\n  /-- All original node producers and copied canonical rows retained. -/\n  work : ℕ\n\n/-- Actual row traversal. Even inactive nodes are acquired before filtering,\na polynomial-overhead choice that avoids an unpaid multiplicity oracle. -/\ndef gather (a M u : ℕ) : List (Fin (size a)) → RowsReport\n  | [] => ⟨[],1⟩\n  | t::ts =>\n    let current:=SemiprimeD1RecoveryWeightRun.acquire a M u t\n    let tail:=gather a M u ts\n    if t.val=center a ∨ current.data.retained=0 then\n      ⟨tail.rows,current.work+tail.work+4⟩\n    else\n      let js:=indices current.rows.length\n      let rows:=js.value.map fun j =>\n        let r:=(current.rows[j]?).getD ⟨0,1⟩\n        Row.mk t.val j r.numerator r.denominator\n      ⟨rows++tail.rows,current.work+tail.work+js.work+8*current.rows.length+5⟩\n\n/-- Complete original-grid acquisition, internally generating all nodes. -/\ndef acquire (a M u : ℕ) : RowsReport :=\n  let ns:=nodeIndices a\n  let rows:=gather a M u ns.value\n  ⟨rows.rows,ns.work+rows.work+3⟩\n\n/-- Full canonical row list with the precise original active-node ordering. -/\ndef originalRows (a M u : ℕ) : List Row :=\n  (List.range (size a)).flatMap fun t =>\n    let w:=SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t\n    if t=center a ∨ w.retained=0 then [] else\n      (List.range w.weights.size).map fun j =>\n        let q:=SemiprimeJetArray.coefficient w.weights j\n        Row.mk t j q.num q.den\n\n/-- Actual cached canonical row access uses the corresponding acquired scalar. -/\ntheorem canonical_at (a M u : ℕ) (t : Fin (size a)) (j : ℕ) :\n    ((SemiprimeD1RecoveryWeightRun.acquire a M u t).rows[j]?).getD ⟨0,1⟩=\n      let q:=SemiprimeJetArray.coefficient\n        (SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t.val).weights j\n      CanonicalRow.mk q.num q.den := by\n  rw [acquire_original_rows]\n  simp only [List.getElem?_map,Array.getElem?_toList,SemiprimeJetArray.coefficient]\n  cases (SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t.val).weights[j]? <;> rfl\n\n/-- Actual canonical cache length agrees with the acquired weight array. -/\ntheorem canonical_length (a M u : ℕ) (t : Fin (size a)) :\n    (SemiprimeD1RecoveryWeightRun.acquire a M u t).rows.length=\n      (SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t.val).weights.size := by\n  rw [acquire_original_rows]\n  simp\n\n/-- Every recursive row-acquisition frame agrees with the original finite data. -/\ntheorem gather_rows (a M u : ℕ) (ts : List (Fin (size a))) :\n    (gather a M u ts).rows=(ts.map Fin.val).flatMap fun t =>\n      let w:=SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t\n      if t=center a ∨ w.retained=0 then [] else\n        (List.range w.weights.size).map fun j =>\n          let q:=SemiprimeJetArray.coefficient w.weights j\n          Row.mk t j q.num q.den := by\n  induction ts with\n  | nil => rfl\n  | cons t ts ih =>\n    simp only [gather,List.map_cons,List.flatMap_cons,acquire_data]\n    split_ifs\n    · exact ih\n    · simp only [indices_value,canonical_length,canonical_at,ih]\n\n/-- Original-input row acquisition equals the original canonical weight data. -/\ntheorem acquire_rows (a M u : ℕ) : (acquire a M u).rows=originalRows a M u := by\n  simp only [acquire,gather_rows,nodeIndices_values,originalRows]\n\n/-- Every ACTUALLY cached canonical weight row has a positive denominator and\noriginal-derived dyadic numerator/denominator bounds. No height answer is supplied. -/\ntheorem canonical_bounds (a M u : ℕ) (t : Fin (size a)) (j : ℕ)\n    (hj : j < (SemiprimeD1RecoveryWeightRun.acquire a M u t).rows.length) :\n    let r:=((SemiprimeD1RecoveryWeightRun.acquire a M u t).rows[j]?).getD ⟨0,1⟩\n    0 < r.denominator ∧\n    r.denominator ≤ 2^SemiprimeD1HermiteWeightBits.weightExponent a (height M u) u t.val ∧\n    r.numerator.natAbs ≤ 2^SemiprimeD1HermiteWeightBits.weightExponent a (height M u) u t.val := by\n  rw [canonical_length,SemiprimeD1JetRecoveryWeights.acquire_weights_size] at hj\n  have hp : 0 < nodeMultiplicity a (height M u) u t.val := by omega\n  have hb:=SemiprimeD1HermiteWeightBits.original_weight_bits a (height M u) u t hp j hj\n  rw [canonical_at]\n  exact ⟨Rat.den_pos _,hb⟩\n\n/-- Actual canonical rows contain exactly the retained original multiplicity. -/\ntheorem canonical_length_le (a M u : ℕ) (t : Fin (size a)) :\n    (SemiprimeD1RecoveryWeightRun.acquire a M u t).rows.length ≤ (height M u)*u := by\n  rw [canonical_length,SemiprimeD1JetRecoveryWeights.acquire_weights_size]\n  rw [← multiplicityRun_value a (height M u) u t.val t.val t.isLt]\n  exact SemiprimeD1RecoveryWeightRunBounds.multiplicity_value_le _ _ _ _\n\n/-- Original row count bounds every recursive global cache frame. -/\ntheorem gather_length (a M u : ℕ) (ts : List (Fin (size a))) :\n    (gather a M u ts).rows.length ≤ ts.length*((height M u)*u) := by\n  induction ts with\n  | nil => simp [gather]\n  | cons t ts ih =>\n    have hc:=canonical_length_le a M u t\n    simp only [gather]\n    split_ifs <;> dsimp only\n    · simp only [List.length_cons]; nlinarith\n    · simp only [List.length_append,List.length_map,indices_value,List.length_range,List.length_cons]\n      nlinarith\n\n/-- The original full grid producer stores at most N*h*u canonical rows. -/\ntheorem acquire_length (a M u : ℕ) :\n    (acquire a M u).rows.length ≤ size a*((height M u)*u) := by\n  have h:=gather_length a M u (nodeIndices a).value\n  have hn : (nodeIndices a).value.length=size a := by\n    have hv:=congrArg List.length (nodeIndices_values a)\n    simpa using hv\n  simpa only [acquire,hn] using h\n\n/-- All stages of original grid enumeration are retained. -/\ntheorem nodeIndices_work (a : ℕ) :\n    (nodeIndices a).work=3*a+8+(size a*size a+4*size a+1)+4*size a+3 := by\n  simp [nodeIndices,geometry,intPower_work,indices_work,indices_value,List.length_range,\n    ← geometry_size a 0]\n\n/-- Actual per-node cache traversal has a uniform original-parameter polynomial. -/\ndef nodeCacheBudget (a N h u : ℕ) : ℕ :=\n  SemiprimeD1RecoveryWeightRunBounds.nodeBudget a N h u+(h*u)^2+12*(h*u)+6\n\n/-- Every global row-cache recursion retains the complete actual node producer. -/\ntheorem gather_work (a M u : ℕ) (ts : List (Fin (size a))) :\n    (gather a M u ts).work ≤ ts.length*nodeCacheBudget a (size a) (height M u) u+1 := by\n  induction ts with\n  | nil => simp [gather]\n  | cons t ts ih =>\n    simp only [nodeCacheBudget] at ih\n    have hn:=SemiprimeD1RecoveryWeightRunBounds.acquire_work a M u t\n    have hl:=canonical_length_le a M u t\n    have hi : (SemiprimeD1RecoveryWeightRun.acquire a M u t).rows.length^2 ≤ ((height M u)*u)^2 := by gcongr\n    simp only [gather]\n    split_ifs <;> dsimp only\n    · simp only [List.length_cons,nodeCacheBudget,Nat.add_mul,Nat.one_mul]\n      omega\n    · simp only [List.length_cons,indices_work,nodeCacheBudget,Nat.add_mul,Nat.one_mul]\n      simp only [pow_two] at hi ih ⊢\n      omega\n\n/-- Full original-input canonical row-cache acquisition budget. -/\ndef budget (a M u : ℕ) : ℕ :=\n  3*a+8+(size a*size a+4*size a+1)+4*size a+3+\n    size a*nodeCacheBudget a (size a) (height M u) u+4\n\n/-- Actual original scalar/canonical row producer, with no work/weight advice.\nThe bound is a retained native report; scalar normalization requires bit refinement. -/\ntheorem acquire_work (a M u : ℕ) : (acquire a M u).work ≤ budget a M u := by\n  have hg:=gather_work a M u (nodeIndices a).value\n  have hn : (nodeIndices a).value.length=size a := by\n    have hv:=congrArg List.length (nodeIndices_values a)\n    simpa using hv\n  simp only [acquire,nodeIndices_work,budget]\n  rw [hn] at hg\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryRowsRun\n","RiemannGaussian.SemiprimeD1RootCoordinates":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RootEntrySemantics\nimport RiemannGaussian.SemiprimeD1TensorNetworkFactorization\n\n/-! # Exact original coordinates in actual root occurrence/port order\nEvery factor port is its original indexed coordinate, derived from cached rows\nand the actual canonical edge index search. No bijection is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeD1RootCoordinates\nopen SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkLayout SemiprimeD1RootEntrySemantics\nopen SemiprimePublicAcquiredExecution SemiprimeD1RootNetworkOrder\nnoncomputable section\n\n/-- Original factor degree is the actual acquired row degree. -/\ntheorem original_arity (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool))\n    (e : Fin (factorCount N)) :\n    arity (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n      (factorIndex N hN fixed e)=indexedArity N e := original_row_length N hN fixed e\n\n/-- Original local port in the actual typed root row layout. -/\ndef portIndex (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool))\n    (e : Fin (factorCount N)) (j : Fin (indexedArity N e)) :\n    Incidence (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)) :=\n  ⟨factorIndex N hN fixed e,⟨j.val,by rw [original_arity]; exact j.isLt⟩⟩\n\n/-- The actual root row owner read is its literal original public coordinate. -/\ntheorem owner_portIndex (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool))\n    (e : Fin (factorCount N)) (j : Fin (indexedArity N e)) :\n    owner (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n      (portIndex N hN fixed e j)=indexedCoordinate N hN e j := by\n  have he : e.val<(SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)).length :=\n    (factorIndex N hN fixed e).isLt\n  let row := (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))[e.val]'he\n  have hr : row=(List.finRange (indexedArity N e)).map (indexedCoordinate N hN e) := original_row N hN fixed e\n  have hj : j.val<row.length := by\n    rw [hr,List.length_map,List.length_finRange]\n    exact j.isLt\n  have hf : j.val<(List.finRange (indexedArity N e)).length := by\n    simpa only [List.length_finRange] using j.isLt\n  have hg := congrArg (fun xs : List (Fin (wireCount N)) => xs[j.val]?) hr\n  rw [List.getElem?_eq_getElem hj,List.getElem?_map,List.getElem?_eq_getElem hf] at hg\n  have hg' := Option.some.inj hg\n  have hfin : (List.finRange (indexedArity N e))[j.val]'hf=j := by\n    apply Fin.ext\n    simp only [List.getElem_finRange,Fin.val_cast]\n  calc\n    _ = row[j.val] := rfl\n    _ = indexedCoordinate N hN e ((List.finRange (indexedArity N e))[j.val]) := hg'\n    _ = _ := congrArg (indexedCoordinate N hN e) hfin\n\n/-- Canonical right-port ordering retains each original local port's exact\ncomputed global occurrence identifier. -/\ntheorem right_port_at (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool))\n    (e : Fin (factorCount N)) (j : Fin (indexedArity N e)) :\n    (rightPorts (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n      (factorIndex N hN fixed e))[j.val]?=\n      some (edgeID (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n        (portIndex N hN fixed e j)) := by\n  rw [rightPorts_order,List.getElem?_map]\n  have hj : j.val<(List.finRange (arity\n      (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n      (factorIndex N hN fixed e))).length := by\n    rw [List.length_finRange,original_arity]\n    exact j.isLt\n  rw [List.getElem?_eq_getElem hj]\n  simp only [Option.map_some]\n  congr 1\n  apply congrArg (fun k => edgeID\n    (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))\n    ⟨factorIndex N hN fixed e,k⟩)\n  apply Fin.ext\n  simp only [List.getElem_finRange,Fin.val_cast]\n\n/-- An actual canonical global read of pulled-back owner bits is exactly its\noriginal occurrence owner, with the literal edgeID/edgeEquiv index search. -/\ntheorem pullback_read {n : ℕ} (rs : Rows n) (bits : Fin n→Bool) (p : Incidence rs) :\n    ((List.ofFn (fun j : Fin (scope rs) => bits (leftGroup rs j)))[edgeID rs p]?).getD false=bits (owner rs p) := by\n  have hp := edgeID_lt rs p\n  rw [List.getElem?_eq_getElem (by simpa only [List.length_ofFn] using hp)]\n  simp only [List.getElem_ofFn,Option.getD_some]\n  have he : (⟨edgeID rs p,hp⟩ : Fin (scope rs))=edgeEquiv rs p := Fin.ext rfl\n  rw [he]\n  change bits (owner rs ((edgeEquiv rs).symm (edgeEquiv rs p)))=_\n  rw [Equiv.symm_apply_apply]\n\nend\nend RiemannGaussian.SemiprimeD1RootCoordinates\n","RiemannGaussian.SemiprimeD1RootNetworkOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RootNetwork\nset_option autoImplicit false\nset_option maxHeartbeats 60000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RootNetworkOrder\n/-- Selecting one fibre of a nodup finite list retains its literal block order. -/\nprivate theorem selector {A B : Type} [DecidableEq A] (xs : List A) (f : A→List B)\n    (e : A) (hn : xs.Nodup) :\n    xs.flatMap (fun a => if a=e then f a else [])=if e∈xs then f e else [] := by\n  induction xs with\n  | nil => simp\n  | cons a xs ih =>\n    have hx := List.nodup_cons.mp hn\n    by_cases he : a=e\n    · subst a\n      have hnot : e∉xs := hx.1\n      simp [List.flatMap_cons,ih hx.2,hnot]\n    · simp [List.flatMap_cons,he,ih hx.2,Ne.symm he]\n/-- A factor fibre of the original incidence stream has its original local order. -/\ntheorem indexed_filter (F : ℕ) (arity : Fin F→ℕ) (e : Fin F) :\n ((SemiprimeFiniteEnumerations.indexedIncidences F arity).values.filter\n   (fun p => decide (p.1=e)))=(List.finRange (arity e)).map (Sigma.mk (β := fun e => Fin (arity e)) e) := by\n  simp only [SemiprimeFiniteEnumerations.indexedIncidences,SemiprimeFiniteEnumerations.sigma,\n    SemiprimeFiniteEnumerations.fin,List.filter_flatMap,List.filter_map]\n  have h (a : Fin F) :\n      ((List.finRange (arity a)).filter ((fun p : Sigma (fun e => Fin (arity e)) => decide (p.fst=e)) ∘ Sigma.mk (β := fun e => Fin (arity e)) a)).map (Sigma.mk (β := fun e => Fin (arity e)) a)=\n      if a=e then (List.finRange (arity a)).map (Sigma.mk (β := fun e => Fin (arity e)) a) else [] := by\n    by_cases ha : a=e\n    · simp [Function.comp_def,ha]\n    · simp [Function.comp_def,ha]\n  simp_rw [h]\n  rw [selector _ _ _ (List.nodup_finRange F)]\n  simp\n/-- Canonical right ports preserve factor-local order in every concrete network. -/\ntheorem rightPorts_order {n : ℕ} (rs : SemiprimeD1TensorNetwork.Rows n)\n    (e : Fin rs.length) :\n    SemiprimeD1TensorNetwork.rightPorts rs e=\n      (List.finRange (SemiprimeD1TensorNetwork.arity rs e)).map\n        (fun j => SemiprimeD1TensorNetwork.edgeID rs ⟨e,j⟩) := by\n  unfold SemiprimeD1TensorNetwork.rightPorts SemiprimeD1TensorNetwork.incidences\n  rw [indexed_filter]\n  simp only [List.map_map,Function.comp_def]\n\n/-- The canonical actual factor scope equals its cached owner-row length. -/\ntheorem rightPorts_length {n : ℕ} (rs : SemiprimeD1TensorNetwork.Rows n)\n    (e : Fin rs.length) :\n    (SemiprimeD1TensorNetwork.rightPorts rs e).length=SemiprimeD1TensorNetwork.arity rs e := by\n  rw [rightPorts_order,List.length_map,List.length_finRange]\n\n/-- Cached-record equality determines literal row order without inspecting any tables. -/\ntheorem row_of_map {n F : ℕ} {arity : Fin F→ℕ}\n    (data : SemiprimeD1RootTensorTables.Acquired n F arity)\n    (coordinate : (e : Fin F)→Fin (arity e)→Fin n)\n    (hr : data.records=(SemiprimeFiniteEnumerations.indexedIncidences F arity).values.map\n      (fun p => ⟨p,coordinate p.1 p.2⟩)) (e : Fin F) :\n    (SemiprimeD1RootNetwork.rows data)[e.val]'(by\n      rw [SemiprimeD1RootNetwork.rows_length];exact e.isLt)=\n    (List.finRange (arity e)).map (coordinate e) := by\n  simp only [SemiprimeD1RootNetwork.rows,List.getElem_ofFn]\n  change (data.records.filter (fun p => decide (p.port.1=e))).map\n    SemiprimeD1RootTensorTables.PortRecord.owner=(List.finRange (arity e)).map (coordinate e)\n  rw [hr]\n  simp only [List.filter_map,List.map_map,Function.comp_def]\n  rw [indexed_filter]\n  simp only [List.map_map,Function.comp_def]\n\n/-- Actual cached owner rows preserve the original local-port sequence. -/\ntheorem original_row (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (SemiprimePublicAcquiredExecution.wireCount N)×Bool))\n    (e : Fin (SemiprimePublicAcquiredExecution.factorCount N)) :\n    (SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))[e.val]'(by\n      rw [SemiprimeD1RootNetwork.rows_length];exact e.isLt)=\n    (List.finRange (SemiprimePublicAcquiredExecution.indexedArity N e)).map\n      (SemiprimePublicAcquiredExecution.indexedCoordinate N hN e) := by\n  apply row_of_map _ (SemiprimePublicAcquiredExecution.indexedCoordinate N hN)\n  exact SemiprimeD1RootTensorTables.acquirePositive_records N hN fixed\n/-- Actual root rows have exactly the original acquired factor degree. -/\ntheorem original_row_length (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (SemiprimePublicAcquiredExecution.wireCount N)×Bool))\n    (e : Fin (SemiprimePublicAcquiredExecution.factorCount N)) :\n    ((SemiprimeD1RootNetwork.rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))[e.val]'(by\n      rw [SemiprimeD1RootNetwork.rows_length];exact e.isLt)).length=\n        SemiprimePublicAcquiredExecution.indexedArity N e := by\n  rw [original_row N hN fixed e,List.length_map,List.length_finRange]\nend RiemannGaussian.SemiprimeD1RootNetworkOrder\n","RiemannGaussian.SemiprimeD1ScaledHermite":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HermiteIdentity\n\n/-! # Exact scaled variable-multiplicity Hermite recovery from retained jets\nAll substitution occurs on scalar rational polynomials, followed by a scalar\nlinear coefficient functional. This is not a ring evaluation on a jet quotient.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1ScaledHermite\nopen Polynomial\nopen scoped BigOperators\nopen SemiprimeHermiteRecovery SemiprimeD1HermiteIdentity\nvariable {K : Type*} [Field K] {ι : Type*} [DecidableEq ι]\n\n/-- Original local affine parameter T=t+alpha*z. -/\nnoncomputable def affine (α t : K) : K[X] := C t+C α*X\n\n/-- Scalar polynomial inverse parameter z=(T-t)/alpha. -/\nnoncomputable def pullback (α t : K) : K[X] := (X-C t)*C α⁻¹\n\n/-- The ORIGINAL affine parameter changes are inverse over the scalar field. -/\ntheorem affine_pullback (α t : K) (hα : α≠0) : (affine α t).comp (pullback α t)=X := by\n  simp only [affine,pullback,add_comp,C_comp,mul_comp,X_comp]\n  have hi : C α*C α⁻¹=(1:K[X]) := by rw [← C_mul,mul_inv_cancel₀ hα,C_1]\n  calc\n    _ = C t+(C α*C α⁻¹)*(X-C t) := by ring\n    _ = X := by rw [hi,one_mul];ring\n\n/-- The actual scaled local Hermite quotient uses its constructed finite inverse. -/\nnoncomputable def quotient (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (α : K) (H : K[X]) (t : ι) : K[X] :=\n  localQuotient (H.comp (affine α (node t)))\n    ((cardinal s node m t).comp (affine α (node t))) (m t)\n\n/-- Constructed scaled Hermite term in the ORIGINAL T variable. -/\nnoncomputable def term (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (α : K) (H : K[X]) (t : ι) : K[X] :=\n  cardinal s node m t*(quotient s node m α H t).comp (pullback α (node t))\n\n/-- Own-node agreement is DERIVED from the finite local inverse and affine composition. -/\ntheorem term_local (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (hinj : Set.InjOn node (s:Set ι)) (α : K) (hα : α≠0) (H : K[X]) (t : ι) (ht : t∈s) :\n    (X-C (node t))^m t∣term s node m α H t-H := by\n  have hL : ((cardinal s node m t).comp (affine α (node t))).coeff 0=1 := by\n    rw [coeff_zero_eq_eval_zero,eval_comp]\n    simpa [affine] using cardinal_eval s node m hinj t ht\n  have hlocal := localQuotient_congruence (H.comp (affine α (node t)))\n    ((cardinal s node m t).comp (affine α (node t))) (m t) hL\n  have hd := map_dvd (compRingHom (pullback α (node t))) hlocal\n  change (X^m t).comp (pullback α (node t))∣\n    (((cardinal s node m t).comp (affine α (node t)))*quotient s node m α H t-\n      H.comp (affine α (node t))).comp (pullback α (node t)) at hd\n  simp only [pow_comp,X_comp,sub_comp,mul_comp,comp_assoc,affine_pullback α (node t) hα,comp_X] at hd\n  have hbase : (X-C (node t))^m t∣(pullback α (node t))^m t :=\n    pow_dvd_pow_of_dvd (dvd_mul_right _ _) _\n  exact hbase.trans hd\n\n/-- Other-node vanishing uses only the explicit cardinal factor. -/\ntheorem term_other (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (α : K) (H : K[X]) (t q : ι) (hq : q∈s) (hqt : q≠t) :\n    (X-C (node q))^m q∣term s node m α H t :=\n  (cardinal_dvd s node m t q hq hqt).mul_right _\n\n/-- Actual term degree is strictly below total retained multiplicity. -/\ntheorem term_degree (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (α : K) (H : K[X]) (t : ι) (ht : t∈s) (hm : 0< m t) :\n    (term s node m α H t).natDegree<total s m := by\n  have h1 := cardinal_degree s node m t\n  have h2 := localQuotient_degree (H.comp (affine α (node t)))\n    ((cardinal s node m t).comp (affine α (node t))) (m t) hm\n  have hp : (pullback α (node t)).natDegree≤1 := by\n    exact (natDegree_mul_C_le (X-C (node t)) α⁻¹).trans_eq (natDegree_X_sub_C (node t))\n  have hc : ((quotient s node m α H t).comp (pullback α (node t))).natDegree≤\n      (quotient s node m α H t).natDegree := by\n    exact natDegree_comp_le.trans (by simpa only [Nat.mul_one] using\n      (Nat.mul_le_mul_left ((quotient s node m α H t).natDegree) hp))\n  have h3 : (term s node m α H t).natDegree≤(cardinal s node m t).natDegree+\n      (quotient s node m α H t).natDegree := natDegree_mul_le.trans (Nat.add_le_add_left hc _)\n  have he := Finset.sum_erase_add s m ht\n  change _=total s m at he\n  change (quotient s node m α H t).natDegree< m t at h2\n  omega\n\n/-- Scaled GLOBAL Hermite identity, from actual variable multiplicities and finite inverse. -/\ntheorem reconstruction (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (hinj : Set.InjOn node (s:Set ι)) (hm : ∀t∈s,0< m t)\n    (α : K) (hα : α≠0) (H : K[X]) (hH : H.natDegree<total s m) :\n    (∑ t∈s,term s node m α H t)=H := by\n  apply eq_of_packets s node m hinj\n  · refine (natDegree_sum_le _ _).trans_lt ?_\n    apply (Finset.sup_lt_iff (by omega : 0<total s m)).mpr\n    intro t ht\n    exact term_degree s node m α H t ht (hm t ht)\n  · exact hH\n  · intro t ht k hk\n    have hd : (X-C (node t))^m t∣∑ q∈s,(term s node m α H q-if q=t then H else 0) := by\n      apply Finset.dvd_sum\n      intro q hq\n      by_cases hqt : q=t\n      · subst q\n        simpa using term_local s node m hinj α hα H t ht\n      · simp only [hqt,ite_false,sub_zero]\n        exact term_other s node m α H q t ht (Ne.symm hqt)\n    have he : (X-C (node t))^m t∣(∑ q∈s,term s node m α H q)-H := by\n      simpa only [Finset.sum_sub_distrib,Finset.sum_ite_eq',ht,ite_true] using hd\n    rw [X_sub_C_pow_dvd_iff,X_pow_dvd_iff] at he\n    simpa only [taylor_apply,sub_comp,coeff_sub,sub_eq_zero] using he k hk\n\n/-- EXACT D.9 at zero, using ONLY the actual retained SCALED Taylor packets. -/\ntheorem at_zero (s : Finset ι) (node : ι→K) (m : ι→ℕ)\n    (hinj : Set.InjOn node (s:Set ι)) (hm : ∀t∈s,0< m t)\n    (α : K) (hα : α≠0) (H : K[X]) (hH : H.natDegree<total s m) :\n    H.eval 0=∑ t∈s,(cardinal s node m t).eval 0*\n      (localQuotient ((H.comp (affine α (node t)))%ₘ X^m t)\n        ((cardinal s node m t).comp (affine α (node t))) (m t)).eval (-(node t)/α) := by\n  have he := congrArg (fun p:K[X] => p.eval 0) (reconstruction s node m hinj hm α hα H hH)\n  simp only [eval_finsetSum,term,eval_mul,eval_comp,pullback,eval_mul,eval_sub,eval_X,eval_C,\n    zero_sub,quotient,localQuotient_truncate,div_eq_mul_inv] at he ⊢\n  exact he.symm\n\nend RiemannGaussian.SemiprimeD1ScaledHermite\n","RiemannGaussian.SemiprimeD1Schedule":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PrecisionEnvelope\n\n/-! # Literal dyadic schedule and original inherited-precision guards\n\nEvery path precision is computed by the actual D.11 update from the edge and\nnode history. No precision sequence is supplied. A conservative extra leaf\nguard stops when fewer than minimumLevels valuation levels remain. Bounding\nthose leaves and the full recursive machine is a separate obligation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1Schedule\nopen scoped BigOperators\nopen SemiprimeD1ModeRate SemiprimeD1PrecisionEnvelope\n\n/-- Fixed original D.1 epsilon denominator, before all input sizes. -/\ndef epsilonDenominator : ℕ := 128*1024\n\n/-- Original dyadically decreasing retained valuation levels. -/\ndef levels (lam depth : ℕ) : ℕ := (lam/epsilonDenominator)/2^depth\n\n/-- Actual cumulative exponent inherited from earlier recursion levels. -/\ndef previous (lam depth : ℕ) : ℕ := 2*∑ j∈Finset.range depth,levels lam j\n\n/-- Packet exponent after adding this call's twice-taper increment. -/\ndef exponent (lam depth : ℕ) : ℕ := previous lam depth+2*levels lam depth\n\n/-- Original leaf scale; a finite quotient avoids a real square-root oracle. -/\ndef leafSize (s lam : ℕ) : ℕ := s/(Nat.sqrt lam+1)+1\n\n/-- The explicit active-call test; all three failing cases become leaves. -/\ndef Active (s lam depth M : ℕ) : Prop :=\n  leafSize s lam < M ∧ minimumLevels lam ≤ levels lam depth ∧ levels lam depth ≤ M\n\n/-- Halving is exact even across all integer floors. -/\ntheorem levels_succ (lam depth : ℕ) : levels lam (depth+1)=levels lam depth/2 := by\n  simp only [levels,pow_succ,Nat.div_div_eq_div_mul,Nat.mul_assoc]\n\n/-- Every actually retained level is bounded by its original input parameter. -/\ntheorem levels_le (lam depth : ℕ) : levels lam depth ≤ lam := by\n  exact (Nat.div_le_self _ _).trans (Nat.div_le_self _ _)\n\n/-- The finite cumulative taper never exceeds twice its first block. -/\ntheorem sum_levels (lam depth : ℕ) :\n    (∑ j∈Finset.range depth,levels lam j)+2*levels lam depth ≤ 2*(lam/epsilonDenominator) := by\n  induction depth with\n  | zero => simp [levels]\n  | succ depth ih =>\n    rw [Finset.sum_range_succ,levels_succ]\n    have hh := Nat.div_mul_le_self (levels lam depth) 2\n    omega\n\n/-- The explicit packet exponent stays below four original epsilon blocks. -/\ntheorem exponent_le (lam depth : ℕ) : exponent lam depth ≤ 4*(lam/epsilonDenominator) := by\n  have h := sum_levels lam (depth+1)\n  rw [Finset.sum_range_succ] at h\n  unfold exponent previous\n  omega\n\n/-- The conservative numeric envelope used in the inherited-precision proof. -/\ntheorem exponent_le_lam (lam depth : ℕ) : exponent lam depth ≤ 4*lam :=\n  (exponent_le lam depth).trans (Nat.mul_le_mul_left 4 (Nat.div_le_self _ _))\n\n/-- The next call inherits exactly the previous call's cumulative exponent. -/\ntheorem previous_succ (lam depth : ℕ) : previous lam (depth+1)=exponent lam depth := by\n  simp only [previous,exponent,Finset.sum_range_succ,Nat.mul_add]\n\n/-- Nonempty retained levels force a genuine logarithmic depth bound. -/\ntheorem depth_le (lam depth : ℕ) (hu : 0 < levels lam depth) : depth ≤ lam := by\n  have hp : 0 < (2:ℕ)^depth := by positivity\n  have hb : 2^depth ≤ lam/epsilonDenominator := by\n    have h := (Nat.le_div_iff_mul_le hp).mp (show 1 ≤ levels lam depth by omega)\n    simpa only [Nat.one_mul] using h\n  have hd := depth.lt_two_pow_self\n  have hl := Nat.div_le_self lam epsilonDenominator\n  omega\n\n/-- Every active node has a strictly positive actual taper. -/\ntheorem active_positive (s lam depth M : ℕ) (h : Active s lam depth M) : 0 < levels lam depth := by\n  have hh : 8 ≤ minimumLevels lam := by unfold minimumLevels;omega\n  exact lt_of_lt_of_le (by omega : 0 < minimumLevels lam) h.2.1\n\n/-- Original active edge count pays the root-size factor in inherited precision. -/\ntheorem active_size (s lam depth M : ℕ) (h : Active s lam depth M) : s ≤ M*(lam+1) := by\n  have hk : 0 < Nat.sqrt lam+1 := by omega\n  have hq : s < (s/(Nat.sqrt lam+1)+1)*(Nat.sqrt lam+1) := by\n    exact (Nat.div_lt_iff_lt_mul hk).mp (by omega)\n  have hs := Nat.sqrt_le_self lam\n  have hm : s/(Nat.sqrt lam+1)+1 ≤ M := by have hh := h.1;unfold leafSize at hh;omega\n  have hb := Nat.mul_le_mul hm (show Nat.sqrt lam+1 ≤ lam+1 by omega)\n  omega\n\n/-- Actual precisions generated from original edge/node histories, not advice. -/\ndef precision (lam : ℕ) (edges node : ℕ→ℕ) (p0 : ℕ) : ℕ→ℕ\n  | 0 => p0\n  | depth+1 => workingPrecision (edges depth) (levels lam depth)\n      (exponent lam depth) (node depth) (precision lam edges node p0 depth)\n\n/-- Every computed precision along an admissible path satisfies the preserved envelope. -/\ntheorem precision_cap (s lam depth : ℕ) (edges node : ℕ→ℕ) (p0 : ℕ) (hp0 : p0 ≤ s)\n    (hpath : ∀ j < depth,edges j ≤ s ∧ levels lam j ≤ edges j) :\n    precision lam edges node p0 depth ≤ pathCap s lam depth (previous lam depth) := by\n  induction depth with\n  | zero => simpa [precision,previous,root_cap] using hp0\n  | succ depth ih =>\n    have hprev := ih (fun j hj => hpath j (by omega))\n    have hh := hpath depth (by omega)\n    rw [precision,previous_succ]\n    exact update_cap s lam depth (previous lam depth) (edges depth) (levels lam depth)\n      (exponent lam depth) (node depth) _ hh.1 hh.2 (exponent_le_lam lam depth)\n        (by unfold exponent;omega) hprev\n\n/-- All three mode-acquisition guards hold at every actual active path node.\nThe remaining graph/packing/child correctness joins do not enter this arithmetic proof. -/\ntheorem active_guards (s lam depth : ℕ) (edges node : ℕ→ℕ) (p0 : ℕ) (hp0 : p0 ≤ s)\n    (hpath : ∀ j < depth,edges j ≤ s ∧ levels lam j ≤ edges j)\n    (hactive : Active s lam depth (edges depth)) (hi : node depth < levels lam depth) :\n    node depth ≤ exponent lam depth ∧\n      precision lam edges node p0 depth*levels lam depth ≤ edges depth*2^(exponent lam depth-node depth) ∧\n      (exponent lam depth+1)*levels lam depth ≤ 2^(exponent lam depth-node depth) := by\n  have hpos := active_positive s lam depth (edges depth) hactive\n  have hd := depth_le lam depth hpos\n  have hpc := precision_cap s lam depth edges node p0 hp0 hpath\n  have hx := exponent_le_lam lam depth\n  have hstep : previous lam depth+2*levels lam depth ≤ exponent lam depth := by rfl\n  refine ⟨by unfold exponent;omega,?_,?_⟩\n  · exact input_guard s lam depth (previous lam depth) (edges depth) (levels lam depth)\n      (exponent lam depth) (node depth) _ hpc hd (active_size _ _ _ _ hactive)\n        (levels_le _ _) hactive.2.1 hstep (by omega)\n  · exact evaluation_guard lam (levels lam depth) (exponent lam depth) (node depth)\n      (levels_le _ _) hactive.2.1 hx (by unfold exponent;omega) (by omega)\n\nend RiemannGaussian.SemiprimeD1Schedule\n","RiemannGaussian.SemiprimeD1StackBinarySquareRootOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBinarySquareRootStorage\n/-! # Universal original-binary square-root correctness, bit time and all-word space\nThe original input is the sole physical operand. All powers, trials, verdicts\nand the compact root are acquired by the SAME literal finite program.\nPacked factor-count/sum extraction and the final factor-recovery caller remain\nseparate joins; this source is the binary square-root primitive only.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackBinarySquareRootOriginal\nopen scoped BigOperators\nopen SemiprimeD1StackBinarySquareRoot SemiprimeD1StackBinarySquareRootEncoding\nopen SemiprimeD1StackBinarySquareRootExecution SemiprimeD1StackBinarySquareRootStorage\nopen SemiprimeBitArithmetic SemiprimeSourceCompactBits\n/-- Original binary D is retained verbatim, even for padded zero/input words. -/\ntheorem retained_input (bits : List Bool) : (done bits).data originalInput=bits := rfl\n/-- The descending power is actually consumed and its final borrowed trim storage cleared. -/\ntheorem power_empty (bits : List Bool) : (done bits).data power=[] := rfl\n/-- The internal raw root is physically consumed by the actual final reversal. -/\ntheorem root_empty (bits : List Bool) : (done bits).data (aux .root)=[] := rfl\n/-- Every one of the eighteen actual private arithmetic roles is empty at halt. -/\ntheorem private_empty (bits : List Bool) (i : Fin 18) : (done bits).data (clearStack i)=[] := by\n  fin_cases i <;> rfl\n/-- Output correctness is universal; no compactness, positivity, square or factoring advice is supplied. -/\ntheorem output_value (bits : List Bool) :\n    bitValue ((done bits).data (aux .output))=Nat.sqrt (bitValue bits) :=\n  SemiprimeD1StackBinarySquareRootArithmetic.output_value bits\n/-- Actual final byte output is compact, including the empty representation of zero. -/\ntheorem output_compact (bits : List Bool) : Compact ((done bits).data (aux .output)) :=\n  SemiprimeD1StackBinarySquareRootArithmetic.output_compact bits\n/-- Ordinary integer square-root inequalities hold for the ACTUAL stopped output. -/\ntheorem output_bounds (bits : List Bool) :\n    (bitValue ((done bits).data (aux .output)))^2 ≤ bitValue bits ∧\n      bitValue bits < (bitValue ((done bits).data (aux .output))+1)^2 := by\n  rw [output_value]\n  exact ⟨Nat.sqrt_le' _,Nat.lt_succ_sqrt' _⟩\n/-- Original-binary acquisition, exact sqrt and its OWN fixed quartic bit-time bound. -/\ntheorem source_original (bits : List Bool) :\n    ∃t ≤ 100000000*(bits.length+1)^4,\n      SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) ∧\n      (done bits).data originalInput=bits ∧\n      bitValue ((done bits).data (aux .output))=Nat.sqrt (bitValue bits) ∧\n      Compact ((done bits).data (aux .output)) := by\n  obtain ⟨t,ht,hr⟩:=source_run_bounded bits\n  exact ⟨t,ht,hr,retained_input bits,output_value bits,output_compact bits⟩\n/-- Genuine Turing.initList binary-input machine, with the SAME proved actual quartic clock. -/\nnoncomputable def machineOriginal (bits : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (100000000*(bits.length+1)^4) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (aux .output) (ctl .start) program\n  let h:=source_run_bounded bits\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- All33 words and actual saved-return cells are paid at EVERY actual compiled prefix. -/\ntheorem original_prefix_cells (bits : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 10000000000*(bits.length+1)^4 :=\n  machine_prefix_cells bits fuel cfg hp\nend RiemannGaussian.SemiprimeD1StackBinarySquareRootOriginal\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankAbort":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankCleanup\n/-! # Physical mismatch/EOF rejection and complete actual work cleanup\nThe real abort path drains every nonpersistent callee word and all six outer\nwork words. Original heap/counter/reference/child banks survive. Only afterward\nis the now-empty actual scratch given singleton false status.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankAbort\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankState\nopen SemiprimeD1StackCachePhaseBankPrimitives SemiprimeD1StackCachePhaseBankClearEncoding\nopen SemiprimeD1StackProcedureTrace\n/-- Real outer work port at each of six fixed abort labels. -/\ndef auxRole (i:Fin 6):Aux:=\n  if i=0 then .referenceReader else if i=1 then .childReader else if i=2 then .valid\n  else if i=3 then .history else if i=4 then .buffer else .output\n/-- Exact partial view of physically drained outer work, with both original vectors retained. -/\ndef auxThrough (w:Aux→List Bool) (n:Nat):Aux→List Bool\n  | .references=>w .references | .children=>w .children\n  | .referenceReader=>if 0<n then [] else w .referenceReader\n  | .childReader=>if 1<n then [] else w .childReader\n  | .valid=>if 2<n then [] else w .valid\n  | .history=>if 3<n then [] else w .history\n  | .buffer=>if 4<n then [] else w .buffer\n  | .output=>if 5<n then [] else w .output\n/-- No actual outer word is changed before its sweep starts. -/\ntheorem aux_zero (w:Aux→List Bool):auxThrough w 0=w:=by funext k;cases k <;> rfl\n/-- Every finite outer cleanup label refers to its real physical tape. -/\ntheorem aux_address (i:Fin 6):abortWord i=aux (auxRole i):=by fin_cases i <;> rfl\n/-- Earlier abort drains do not silently modify a future physical work word. -/\ntheorem aux_current (w:Aux→List Bool) (i:Fin 6):auxThrough w i.val (auxRole i)=w (auxRole i):=by fin_cases i <;> rfl\n/-- Exactly one physical drain advances each outer-work partial view. -/\ntheorem aux_step (w:Aux→List Bool) (i:Fin 6):\n    Function.update (auxThrough w i.val) (auxRole i) []=auxThrough w (i.val+1):=by\n  funext k;fin_cases i <;> cases k <;> rfl\n/-- Actual physical one-port abort drain, including the final empty pop and genuine caller frames. -/\ntheorem part_run (bank:P.Stack→List Bool) (w:Aux→List Bool) (i:Fin 6):\n    Runs program ((w (auxRole i)).length+1) (.local (.abortAux i)) (data bank (auxThrough w i.val))\n      (nextAbort i) (data bank (auxThrough w (i.val+1))):=by\n  have h0:=drain_loop (.abortAux i) (nextAbort i) (abortWord i) rfl\n    (data bank (auxThrough w i.val)) (w (auxRole i)) (by rw [aux_address,data_aux,aux_current])\n  rw [aux_address,←data_update_aux,aux_step] at h0\n  exact h0\n/-- Actual sum of the six physical outer work payloads. -/\ndef auxMass (w:Aux→List Bool):Nat:=\n  (w .referenceReader).length+(w .childReader).length+(w .valid).length+\n    (w .history).length+(w .buffer).length+(w .output).length\n/-- Complete six-word outer cleanup, retaining both original vectors literally. -/\ntheorem aux_run (bank:P.Stack→List Bool) (w:Aux→List Bool):\n    Runs program (auxMass w+6) (.local (.abortAux 0)) (data bank w) (.local .reject) (data bank (auxThrough w 6)):=by\n  have h0:=part_run bank w 0\n  simp only [Fin.val_zero,Nat.zero_add,aux_zero] at h0\n  have h1:=part_run bank w 1\n  have h2:=part_run bank w 2\n  have h3:=part_run bank w 3\n  have h4:=part_run bank w 4\n  have h5:=part_run bank w 5\n  have h:=join (join (join (join (join h0 h1) h2) h3) h4) h5\n  have ht:auxMass w+6=(((w .referenceReader).length+1+((w .childReader).length+1)+\n      ((w .valid).length+1))+((w .history).length+1))+((w .buffer).length+1)+((w .output).length+1):=by\n    unfold auxMass\n    omega\n  rw [ht]\n  exact h\n/-- Exact rejected source bank after all actual work drains; original four operands are retained. -/\ndef rejectedData (bank:P.Stack→List Bool) (w:Aux→List Bool):Stack→List Bool:=\n  Function.update (data (cleared bank) (auxThrough w 6)) status [false]\n/-- Real rejection time through complete236+6 cleanup, final false push and physical halt. -/\ndef abortTime (bank:P.Stack→List Bool) (w:Aux→List Bool):Nat:=1+sweepTime bank 0+(auxMass w+6)+1+1\n/-- Once a real parser/tag/EOF mismatch enters abort, actual cleanup guarantees false status and no partial output. -/\ntheorem abort_trace (bank:P.Stack→List Bool) (w:Aux→List Bool):\n    Runs program (abortTime bank w-1) (.local .abort) (data bank w) (.local .done) (rejectedData bank w):=by\n  have h0:=jump_run .abort (.local (.clear true 0)) (data bank w) rfl\n  have h1:=SemiprimeD1StackCachePhaseBankCleanup.source_run true bank w\n  have h2:=aux_run (cleared bank) w\n  have h3:=push_run .reject (.local .done) status false (data (cleared bank) (auxThrough w 6)) rfl\n  change Runs program 1 _ _ _ (Function.update (data (cleared bank) (auxThrough w 6)) status (false::cleared bank P.copyScratch)) at h3\n  rw [cleared_scratch] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  have ht:abortTime bank w-1=1+sweepTime bank 0+(auxMass w+6)+1:=by unfold abortTime;omega\n  rw [ht]\n  exact h\n/-- Rejection emits no partial phase bank, only a real singleton false status word. -/\ntheorem rejected_output (bank:P.Stack→List Bool) (w:Aux→List Bool):\n    rejectedData bank w output=[] ∧ rejectedData bank w status=[false]:=by\n  constructor\n  · rfl\n  · simp only [rejectedData,Function.update_self]\n/-- Actual rejected halt clears both transient flags and all real returns after the physical work sweep. -/\ntheorem abort_run (bank:P.Stack→List Bool) (w:Aux→List Bool):\n    SemiprimeD1StackCalls.run program (abortTime bank w)\n      (⟨some (.local .abort),none,none,data bank w,[]⟩:C.State Stack Label)=\n        some (⟨none,none,none,rejectedData bank w,[]⟩:C.State Stack Label):=by\n  let start:C.State Stack Label:=⟨some (.local .abort),none,none,data bank w,[]⟩\n  obtain ⟨out,hr,ha⟩:=abort_trace bank w [] start ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (.local .done) rfl (rejectedData bank w) [] out ha\n  have ht:abortTime bank w=(abortTime bank w-1)+1:=by unfold abortTime;omega\n  rw [ht,SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  exact hh\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankAbort\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankBinding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankReady\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankStopped\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankClearEncoding\n/-! # Exact shared heap/counter retention and cleared next-phase input\nGeneric full-bank bridges precede any original-N instantiation, preventing\nnative graph/context normalization from entering the actual source handoff.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankBinding\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankClearEncoding\nopen SemiprimeD1StackCachePhaseBankStopped\n/-- Fixed actual heap role in the complete238-role bank. -/\ndef heapRole:P.Stack:=P.restoreStack (SemiprimeD1StackCachePhase.Restore.heapStack .heap)\n/-- Fixed actual counter role in the complete238-role bank. -/\ndef counterRole:P.Stack:=P.restoreStack (SemiprimeD1StackCachePhase.Restore.heapStack .counter)\n/-- Every actually initialized fold word is empty before children/context are acquired. -/\ntheorem fold_empty (k:SemiprimeD1StackCachePhase.Fold.Stack):\n    ((SemiprimeD1StackCachePhase.Fold.initial [] [] []).data k)=[]:=by\n  have h:=SemiprimeD1StackCachePhaseStorage.fold_initial_length [] k\n  exact List.eq_nil_of_length_eq_zero (Nat.eq_zero_of_le_zero h)\n/-- Exactly heap/counter are present in the genuinely clean next-phase callee input. -/\ntheorem input_base (hp cn:List Bool):P.input hp cn [] []=\n    (fun k=>if k=heapRole then hp else if k=counterRole then cn else []):=by\n  funext k\n  rcases k with r|tail\n  · rcases r with fresh|h\n    · rfl\n    · cases h <;> rfl\n  · rcases tail with fold|tail\n    · exact fold_empty fold\n    · rcases tail with blocks|u <;> rfl\n/-- Actual physical cleanup yields EXACT the next callee input, without resetting any word by advice. -/\ntheorem cleared_input (bank:P.Stack→List Bool) (hp cn:List Bool)\n    (hh:bank heapRole=hp) (hc:bank counterRole=cn):cleared bank=P.input hp cn [] []:=by\n  rw [input_base]\n  funext k\n  by_cases hk:k=heapRole\n  · subst k\n    rw [cleared_retained bank heapRole (by decide),ite_eq_left rfl]\n    exact hh\n  · by_cases hcn:k=counterRole\n    · subst k\n      rw [cleared_retained bank counterRole (by decide),ite_eq_right hk,ite_eq_left rfl]\n      exact hc\n    · have hper:persistent k=false:=by\n        apply Bool.eq_false_of_not_eq_true\n        intro htrue\n        rcases (SemiprimeD1StackCachePhaseBankState.persistent_heap k).mp htrue with he|he\n        · exact hk (cached_injective he)\n        · exact hcn (cached_injective he)\n      simp only [cleared,hper,Bool.false_eq_true,ite_false,ite_eq_right hk,ite_eq_right hcn]\nnamespace O\nexport SemiprimeD1StackCachePhaseRootOriginal (rootDone)\nend O\nnamespace A\nexport SemiprimeD1StackFreshBankRestoreOriginal (banks root_heap root_counter)\nend A\nnamespace R\nexport SemiprimeD1StackRootPhaseFreshRecords (heap aux)\nexport SemiprimeD1StackRootPhaseFreshRecordsEncoding (result)\nend R\nopen SemiprimeD1StackJetFoldWords (Modes)\nattribute [local irreducible] SemiprimeD1StackRootPhaseFreshRecordsEncoding.result\n  SemiprimeD1StackFreshBankRestoreOriginal.banks\n  SemiprimeD1StackRootPhaseFreshRecordsEncoding.freshResult\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n  SemiprimeD1StackRootPhaseParametersEncoding.exponentValue\n  SemiprimeD1StackRootPhaseParametersEncoding.levelsValue\n  SemiprimeD1StackRootPhaseParametersEncoding.edgeValue\n  SemiprimeD1StackCachePhaseRootOriginal.good\n  SemiprimeD1StackCachePhaseRootOriginal.dimension\n  SemiprimeD1StackCachePhaseRootOriginal.newPrecision\n  SemiprimeD1StackCachePhaseExecution.done\n  SemiprimeD1StackCachePhaseRejected.done\n/-- The actual original source's accepted/rejected guard NEVER changes the retained physical heap. -/\ntheorem original_heap (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length)\n    (modes:Modes):(O.rootDone bits i modes).data heapRole=R.result bits R.heap:=by\n  unfold O.rootDone\n  split_ifs\n  · rw [heapRole,accepted_heap]\n    exact (A.root_heap bits).symm\n  · rw [heapRole,rejected_heap]\n    exact (A.root_heap bits).symm\n/-- The actual original source's accepted/rejected guard NEVER changes the retained allocation counter. -/\ntheorem original_counter (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length)\n    (modes:Modes):(O.rootDone bits i modes).data counterRole=R.result bits (R.aux .counter):=by\n  unfold O.rootDone\n  split_ifs\n  · rw [counterRole,accepted_counter]\n    exact (A.root_counter bits).symm\n  · rw [counterRole,rejected_counter]\n    exact (A.root_counter bits).symm\n/-- The entire real238-role sweep closes EXACT the next original callee's clean physical input. -/\ntheorem original_cleared (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length)\n    (modes:Modes):cleared (O.rootDone bits i modes).data=\n      P.input (R.result bits R.heap) (R.result bits (R.aux .counter)) [] []:=\n  cleared_input _ _ _ (original_heap bits i modes) (original_counter bits i modes)\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankBinding\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankExecution\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankRowBounds\n/-! # Own complete physical phase-bank polynomial\nActual occurrence count, stopped output lengths and236-word cleanup costs are\npaid by actual input bytes and real source traces. No subtree clock is raised.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankBounds\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankEncoding\nopen SemiprimeD1StackCachePhaseBankInputBounds SemiprimeD1StackCachePhaseBankRowBounds\nopen SemiprimeD1StackCachePhaseBankStep SemiprimeD1StackCachePhaseBankLoop\nopen SemiprimeD1StackCachePhaseBankFinish SemiprimeD1StackCachePhaseBankPrepare\nopen SemiprimeD1StackCachePhaseBankExecution\n/-- Sum of actual whole-source per-phase caps, independent of prior logger history. -/\ndef rowsSum (bits:List Bool):List (Request bits)→Nat\n  | []=>0\n  | r::rs=>rowBound bits r+rowsSum bits rs\n/-- Actual tagged chunk-history length recurrence. -/\ntheorem chunks_cons_length (bits:List Bool) (r:Request bits) (requests:List (Request bits)):\n    (chunks bits (r::requests)).length=(chunk (payload bits r)).length+(chunks bits requests).length:=by\n  rw [chunks,List.length_append]\n/-- Exact actual source-loop cap: real phase work and ONE real final history reversal. -/\ntheorem replay_eq (bits:List Bool) (requests:List (Request bits)) (history:List Bool):\n    replayBound bits requests history=rowsSum bits requests+2*(chunks bits requests).length+2*history.length+8:=by\n  induction requests generalizing history with\n  | nil=>\n    simp only [replayBound,rowsSum,chunks,finishTime,List.length_nil,Nat.mul_zero,Nat.add_zero]\n    omega\n  | cons r requests ih=>\n    rw [replayBound,ih,rowsSum,chunks_cons_length,List.length_append,List.length_reverse]\n    omega\n/-- Real per-occurrence caps sum only over physically present input references. -/\ntheorem rowsSum_le (bits:List Bool) (requests:List (Request bits)) (B:Nat)\n    (hb:∀r∈requests,rowBound bits r ≤B):rowsSum bits requests ≤requests.length*B:=by\n  induction requests with\n  | nil=>simp only [rowsSum,List.length_nil,Nat.zero_mul,Nat.le_refl]\n  | cons r requests ih=>\n    have h0:=hb r List.mem_cons_self\n    have h1:=ih (fun q hq=>hb q (List.mem_cons_of_mem r hq))\n    simp only [rowsSum,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n/-- Real acquired output payload widths pay their exact physically logged chunks. -/\ntheorem chunks_bound (bits:List Bool) (requests:List (Request bits)) (B:Nat)\n    (hb:∀r∈requests,(payload bits r).length ≤B):\n    (chunks bits requests).length ≤requests.length*(2*B+2):=by\n  induction requests with\n  | nil=>simp only [chunks,List.length_nil,Nat.zero_mul,Nat.le_refl]\n  | cons r requests ih=>\n    have h0:=hb r List.mem_cons_self\n    have h1:=ih (fun q hq=>hb q (List.mem_cons_of_mem r hq))\n    rw [chunks_cons_length,chunk_length,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n/-- Fixed degree18 and coefficient are chosen before every physical input. -/\ndef runBound (bits:List Bool) (requests:List (Request bits)):Nat:=10^100*(capacity bits requests)^18\n/-- SAME whole literal program's actual source cap fits its own four-input physical-byte polynomial. -/\ntheorem timeBound_le (bits:List Bool) (requests:List (Request bits)):\n    timeBound bits requests ≤runBound bits requests:=by\n  let S:=capacity bits requests\n  have hS:1 ≤S:=by dsimp [S,capacity];omega\n  have hn:requests.length ≤S:=by\n    have h:=request_count bits requests\n    dsimp [S,capacity,resource]\n    omega\n  have hrow:=rowsSum_le bits requests (10^85*S^16) (fun r hr=>row_bound bits requests r hr)\n  have hsum:rowsSum bits requests ≤10^85*S^17:=by\n    calc\n      _ ≤requests.length*(10^85*S^16):=hrow\n      _ ≤S*(10^85*S^16):=Nat.mul_le_mul_right _ hn\n      _=10^85*S^17:=by ring\n  have hword:=chunks_bound bits requests (10^81*S^16) (fun r hr=>payload_length bits requests r hr)\n  have hpos:1 ≤S^16:=Nat.pow_pos (by omega)\n  have hinner:2*(10^81*S^16)+2 ≤10^82*S^16:=by norm_num only;omega\n  have hchunks:(chunks bits requests).length ≤10^82*S^17:=by\n    calc\n      _ ≤requests.length*(2*(10^81*S^16)+2):=hword\n      _ ≤S*(10^82*S^16):=Nat.mul_le_mul hn hinner\n      _=10^82*S^17:=by ring\n  have hprep:prepareTime (references bits requests) (children requests) ≤10*S:=by\n    dsimp [S,capacity,resource]\n    unfold prepareTime\n    omega\n  have hpow:S^17 ≤S^18:=Nat.pow_le_pow_right hS (by decide)\n  have hlin:S ≤S^18:=by simpa only [pow_one] using Nat.pow_le_pow_right hS (by decide:1 ≤18)\n  have hp:1 ≤S^18:=Nat.pow_pos (by omega)\n  have hr:rowsSum bits requests ≤10^85*S^18:=hsum.trans (Nat.mul_le_mul_left _ hpow)\n  have hc:(chunks bits requests).length ≤10^82*S^18:=hchunks.trans (Nat.mul_le_mul_left _ hpow)\n  unfold timeBound runBound\n  change prepareTime (references bits requests) (children requests)+replayBound bits requests []+1 ≤10^100*S^18\n  rw [replay_eq]\n  simp only [List.length_nil,Nat.mul_zero,Nat.add_zero]\n  norm_num only at hr hc ⊢\n  omega\n/-- Actual whole4input program truly halts with exact data and own fixed physical-byte polynomial. -/\ntheorem source_run_bounded (bits:List Bool) (requests:List (Request bits)):\n    ∃t ≤runBound bits requests,SemiprimeD1StackCalls.run program t (source bits requests)=some (done bits requests):=by\n  obtain ⟨t,ht,hr⟩:=source_run bits requests\n  exact ⟨t,ht.trans (timeBound_le bits requests),hr⟩\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankBounds\n","RiemannGaussian.SemiprimeD1StackCachePhaseGuard":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseProjection\n/-! # Actual restored phase flag, retaining every source/cache field -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseGuard\nopen SemiprimeD1StackCachePhase SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- One real peek selects the original phase branch without consuming its retained flag. -/\ntheorem guard_run (before:Stack→List Bool) (b:Bool) (hb:before phaseValid=[b]) :\n    Runs program 1 (ctl .check) before (if b then ctl (.copy .newAxes) else ctl .reject) before :=by\n  apply one_base program (ctl .check) _\n    (.peek phaseValid (ctl .reject) (ctl .reject) (ctl (.copy .newAxes))) _ _ rfl\n  · change some (SemiprimeD1StackBytecode.choose (ctl .reject) (ctl .reject)\n      (ctl (.copy .newAxes)) (before phaseValid).head?)=_\n    rw [hb]\n    cases b <;> rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackCachePhaseGuard\n","RiemannGaussian.SemiprimeD1StackCachePhaseOldCache":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhasePrimitives\n/-! # Six actual OLD-cache/q/coefficient copies after the real ordered fold\nThe raw coefficient vector comes from the actual fold output. OLD precision\nand NEW folded coefficient precision remain separate throughout this source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseOldCache\nopen SemiprimeD1StackCachePhase SemiprimeD1StackCachePhaseView SemiprimeD1StackCachePhasePrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Entire actual OLD context projection, retained in the real restored bank. -/\ndef oldContext (restored:Restore.Stack→List Bool) (k:X.Stack) :List Bool :=\n  restored (Restore.freshStack (Fresh.contextStack (Header.oldStack k)))\n/-- Actual P48 q marker word in the SAME restored phase record. -/\ndef blockWord (restored:Restore.Stack→List Bool) :List Bool :=\n  restored (Restore.freshStack (Fresh.contextStack Header.blocks))\n/-- Full physical31-role block-ready bank, produced by six actual preserving copies. -/\ndef blockReady (restored:Restore.Stack→List Bool) (fold:Fold.Stack→List Bool) :Blocks.Stack→List Bool :=\n  (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (fun _=>[]) (Blocks.contextStack X.axesCache) (oldContext restored X.axesCache)) (Blocks.contextStack X.precisionBits) (oldContext restored X.precisionBits)) (Blocks.contextStack X.rankCache) (oldContext restored X.rankCache)) (Blocks.contextStack X.widthCache) (oldContext restored X.widthCache)) (Blocks.aux .blocks) (blockWord restored)) (Blocks.aux .coefficients) (fold Fold.output))\n/-- Exact six-copy clock, including all actual caller returns. -/\ndef oldCopyTime (restored:Restore.Stack→List Bool) (fold:Fold.Stack→List Bool) :Nat :=\n  5*((oldContext restored X.axesCache).length+(oldContext restored X.precisionBits).length+(oldContext restored X.rankCache).length+(oldContext restored X.widthCache).length+(blockWord restored).length+(fold Fold.output).length)+24\n/-- All six actual post-fold handoffs preserve the complete95 and111 preceding component banks. -/\ntheorem old_cache_run (restored:Restore.Stack→List Bool) (fold:Fold.Stack→List Bool) :\n    Runs program (oldCopyTime restored fold) (ctl (.copy .oldAxes))\n      (data restored fold (fun _=>[]) []) (ctl .blocks) (data restored fold (blockReady restored fold) []) :=by\n  let b0:Blocks.Stack→List Bool:=fun _=>[]\n  let b1:=Function.update b0 (Blocks.contextStack X.axesCache) (oldContext restored X.axesCache)\n  let b2:=Function.update b1 (Blocks.contextStack X.precisionBits) (oldContext restored X.precisionBits)\n  let b3:=Function.update b2 (Blocks.contextStack X.rankCache) (oldContext restored X.rankCache)\n  let b4:=Function.update b3 (Blocks.contextStack X.widthCache) (oldContext restored X.widthCache)\n  let b5:=Function.update b4 (Blocks.aux .blocks) (blockWord restored)\n  let b6:=Function.update b5 (Blocks.aux .coefficients) (fold Fold.output)\n  have h0:=copy_call .oldAxes (data restored fold b0 []) (oldContext restored X.axesCache) [] rfl rfl rfl\n  simp only [List.append_nil] at h0\n  change Runs program (5*(oldContext restored X.axesCache).length+4) _ _ _\n    (Function.update (data restored fold b0 []) (blockStack (Blocks.contextStack X.axesCache)) (oldContext restored X.axesCache)) at h0\n  rw [data_blocks] at h0\n  have h1:=copy_call .oldPrecision (data restored fold b1 []) (oldContext restored X.precisionBits) [] rfl rfl rfl\n  simp only [List.append_nil] at h1\n  change Runs program (5*(oldContext restored X.precisionBits).length+4) _ _ _\n    (Function.update (data restored fold b1 []) (blockStack (Blocks.contextStack X.precisionBits)) (oldContext restored X.precisionBits)) at h1\n  rw [data_blocks] at h1\n  have h2:=copy_call .oldRank (data restored fold b2 []) (oldContext restored X.rankCache) [] rfl rfl rfl\n  simp only [List.append_nil] at h2\n  change Runs program (5*(oldContext restored X.rankCache).length+4) _ _ _\n    (Function.update (data restored fold b2 []) (blockStack (Blocks.contextStack X.rankCache)) (oldContext restored X.rankCache)) at h2\n  rw [data_blocks] at h2\n  have h3:=copy_call .oldWidth (data restored fold b3 []) (oldContext restored X.widthCache) [] rfl rfl rfl\n  simp only [List.append_nil] at h3\n  change Runs program (5*(oldContext restored X.widthCache).length+4) _ _ _\n    (Function.update (data restored fold b3 []) (blockStack (Blocks.contextStack X.widthCache)) (oldContext restored X.widthCache)) at h3\n  rw [data_blocks] at h3\n  have h4:=copy_call .blocks (data restored fold b4 []) (blockWord restored) [] rfl rfl rfl\n  simp only [List.append_nil] at h4\n  change Runs program (5*(blockWord restored).length+4) _ _ _\n    (Function.update (data restored fold b4 []) (blockStack (Blocks.aux .blocks)) (blockWord restored)) at h4\n  rw [data_blocks] at h4\n  have h5:=copy_call .coefficients (data restored fold b5 []) (fold Fold.output) [] rfl rfl rfl\n  simp only [List.append_nil] at h5\n  change Runs program (5*(fold Fold.output).length+4) _ _ _\n    (Function.update (data restored fold b5 []) (blockStack (Blocks.aux .coefficients)) (fold Fold.output)) at h5\n  rw [data_blocks] at h5\n  have h:=(join (join (join (join (join h0 h1) h2) h3) h4) h5)\n  change Runs program _ _ _ (ctl .blocks) _ at h\n  change Runs program _ _ _ _ (data restored fold b6 [])\n  convert h using 1\n  unfold oldCopyTime\n  omega\nend RiemannGaussian.SemiprimeD1StackCachePhaseOldCache\n\n","RiemannGaussian.SemiprimeD1StackCarryEquation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordEqualBounds\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\nimport RiemannGaussian.SemiprimeD1StackCopy\n/-! # Physical INTEGER carry equation from one framed operand record\nThe offset is the LENGTH of the physically retained template. No congruence,\ndecoded integer, expected shift, sum or accepted Boolean is a runtime input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackCarryEquation\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace A\nexport SemiprimeD1StackAdder (Stack Label code state store)\nend A\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active initial)\nend F\n/-- Fixed physical data roles, including all parser/shift/arithmetic work. -/\ninductive Stack where\n  | input | cached | count | scratch | valid | coefficient | previous | target | next | left | right | output\n  deriving DecidableEq,Repr\ninstance : Fintype Stack := Fintype.ofList\n  [.input,.cached,.count,.scratch,.valid,.coefficient,.previous,.target,.next,.left,.right,.output]\n  (by intro k;cases k <;> simp)\n/-- The actual four framed operand destinations. -/\ndef operand (k : Fin 4) : Stack := if k=0 then .coefficient else if k=1 then .previous else if k=2 then .target else .next\n/-- Static field parser wiring; source bytes and work are all physical. -/\ndef fieldStack (k : Fin 4) : F.Stack→Stack\n  | .inl .input=>.input\n  | .inl .scratch=>.scratch\n  | .inl .output=>operand k\n  | .inr _=>.valid\n/-- Actual preserving cached-template copy. -/\ndef copyStack (k : Fin 3) : Stack := if k=0 then .cached else if k=1 then .count else .scratch\n/-- The TWO actual integer ripple-adders, sharing only empty work. -/\ndef addStack (right : Bool) : A.Stack→Stack\n  | .left=>if right then .target else .coefficient\n  | .right=>if right then .next else .previous\n  | .scratch=>.scratch\n  | .output=>if right then .right else .left\n/-- Actual final numeric comparison wiring. -/\ndef equalStack : A.Stack→Stack\n  | .left=>.left | .right=>.right | .scratch=>.scratch | .output=>.output\n/-- Fixed finite control and literal component locations. -/\ninductive Label where\n  | read (k : Fin 4) | check (k : Fin 4) | copyCache | shift | prepend | addLeft | addRight | compare | done | bad\n  | field (k : Fin 4) (pc : F.Label) | copy (pc : Fin 9)\n  | add (right : Bool) (pc : A.Label) | equal (pc : SemiprimeD1StackWordEqual.Label)\n  deriving DecidableEq,Fintype\n/-- After each parsed field, consume the actual parser validity Boolean. -/\ndef afterField (k : Fin 4) : Label := if k=0 then .read 1 else if k=1 then .read 2 else if k=2 then .read 3 else .copyCache\n/-- ONE fixed code table. Every arithmetic/parser subroutine is actual included code. -/\ndef program : Label→C.Instruction Stack Label\n  | .read k=>.call (.field k (F.active .tagPop (none,false))) (.check k)\n  | .check k=>.base (.pop .valid .bad .bad (afterField k))\n  | .copyCache=>.call (.copy 0) .shift\n  | .shift=>.base (.pop .count .addLeft .prepend .prepend)\n  | .prepend=>.base (.push .next false .shift)\n  | .addLeft=>.call (.add false (.start false)) .addRight\n  | .addRight=>.call (.add true (.start false)) .compare\n  | .compare=>.call (.equal .loop) .done\n  | .done | .bad=>.base .halt\n  | .field k pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack k) (Label.field k) (F.code pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .add right pc=>SemiprimeD1StackMultiplierLink.instruction (addStack right) (Label.add right) (A.code pc)\n  | .equal pc=>SemiprimeD1StackMultiplierLink.instruction equalStack Label.equal (SemiprimeD1StackWordEqual.code pc)\n/-- Literal physical payload view, never a decoded arithmetic input. -/\ndef store (input cached count scratch valid coefficient previous target next left right output : List Bool) : Stack→List Bool\n  | .input=>input | .cached=>cached | .count=>count | .scratch=>scratch | .valid=>valid\n  | .coefficient=>coefficient | .previous=>previous | .target=>target | .next=>next\n  | .left=>left | .right=>right | .output=>output\n/-- One physical framed record, with arbitrary unconsumed suffix. -/\ndef record (coefficient previous target next tail : List Bool) : List Bool :=\n  SemiprimeSourceHistogramKeyBits.frame coefficient\n    (SemiprimeSourceHistogramKeyBits.frame previous\n      (SemiprimeSourceHistogramKeyBits.frame target (SemiprimeSourceHistogramKeyBits.frame next tail)))\n/-- Only original physical record and offset template are supplied. -/\ndef input (code cached : List Bool) : Stack→List Bool := store code cached [] [] [] [] [] [] [] [] [] []\n/-- Literal source entry with every temporary and return stack empty. -/\ndef initial (code cached : List Bool) : C.State Stack Label := ⟨some (.read 0),none,none,input code cached,[]⟩\n/-- All four parser roles are distinct for every actual operand field. -/\ntheorem field_injective (k : Fin 4) : Function.Injective (fieldStack k) := by\n  fin_cases k <;> intro i j h <;> rcases i with i|i <;> rcases j with j|j <;>\n    cases i <;> cases j <;> simp_all [fieldStack,operand]\n/-- Preserving copy has genuinely separate source/destination/scratch. -/\ntheorem copy_injective : Function.Injective copyStack := by decide\n/-- Both ripple-add calls have separate actual operands, scratch and output. -/\ntheorem add_injective (right : Bool) : Function.Injective (addStack right) := by\n  cases right <;> intro i j h <;> cases i <;> cases j <;> simp_all [addStack]\n/-- Actual comparator roles are distinct. -/\ntheorem equal_injective : Function.Injective equalStack := by\n  intro i j h;cases i <;> cases j <;> simp_all [equalStack]\n/-- Actual finite INTEGER checker; syntax/record acquisition remains caller work. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.input Stack.output (.read 0) program\n/-- Every actual data and return alphabet is fixed and finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite Stack.input Stack.output (Label.read 0) program\n/-- No integer/list/function appears in finite control. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite Stack.input Stack.output (Label.read 0) program\n/-- Exact physical data-role count. -/\ntheorem stack_card : Fintype.card Stack=12 := by decide\nend RiemannGaussian.SemiprimeD1StackCarryEquation\n","RiemannGaussian.SemiprimeD1StackCartesian4":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureFragments\nimport RiemannGaussian.SemiprimeD1StackFrame\n\n/-! # Fixed four-axis physical Cartesian record engine\nAll four limits, indices and the cached finite constructor tag are Boolean\npayloads. Four statically nested real procedures consume copied counters;\nthe leaf frames all four actual indices and the actual cached tag. No body\ncallback, runtime native index/list or input-dependent program label occurs.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackCartesian4\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (instruction DataRel data_unique Rel run_rel)\nend Link\n/-- Four limit stacks, four current indices and four fixed auxiliary roles. -/\nabbrev Stack := Fin 4⊕(Fin 4⊕Fin 4)\n/-- Actual cached source limit. -/\ndef limitStack (level:Fin 4) : Stack := .inl level\n/-- Actual mutable physical index. -/\ndef indexStack (level:Fin 4) : Stack := .inr (.inl level)\n/-- Copy scratch, Frame scratch, record output and cached constructor tag. -/\ndef aux (role:Fin 4) : Stack := .inr (.inr role)\n/-- Statically nested four-loop control and five physical field calls. -/\ninductive Local where\n  | main | ret | halt\n  | entry (level:Fin 4) | drop (level:Fin 4) | child (level:Fin 4) | after (level:Fin 4)\n  | fields (part:Fin 5)\n  deriving DecidableEq,Repr\n/-- Exhaustive finite local labels before every payload. -/\ninstance : Fintype Local where\n  elems:={.main,.ret,.halt}∪Finset.univ.image Local.entry∪Finset.univ.image Local.drop∪\n    Finset.univ.image Local.child∪Finset.univ.image Local.after∪Finset.univ.image Local.fields\n  complete:=by intro pc;cases pc <;> simp\n/-- Fixed local labels, four included Copy and five included Frame instances. -/\nabbrev Label := Local⊕((Fin 4×Fin 9)⊕(Fin 5×Fin 11))\n/-- Copy reads a real limit, writes its corresponding empty current index. -/\ndef copyStack (level:Fin 4) (k:Fin 3) : Stack :=\n  if k=0 then limitStack level else if k=1 then indexStack level else aux 0\n/-- Literal fixed Copy inclusion labels. -/\ndef copyLabel (level:Fin 4) (pc:Fin 9) : Label := .inr (.inl (level,pc))\n/-- The first four emitted fields are indices3,2,1,0; the final field is the cached tag. -/\ndef fieldSource (part:Fin 5) : Stack :=\n  if h:part.val<4 then indexStack ⟨3-part.val,by omega⟩ else aux 3\n/-- Actual physical Frame roles. -/\ndef frameStack (part:Fin 5) (k:Fin 3) : Stack :=\n  if k=0 then fieldSource part else if k=1 then aux 2 else aux 1\n/-- Literal static Frame inclusion labels. -/\ndef frameLabel (part:Fin 5) (pc:Fin 11) : Label := .inr (.inr (part,pc))\n/-- Statically selected lower nesting level; never an input-dependent native index. -/\ndef nextLevel (level:Fin 4) : Fin 4 := if h:level.val<3 then ⟨level.val+1,by omega⟩ else 0\n/-- Actual fixed child entry. -/\ndef childEntry (level:Fin 4) : Label :=\n  if level=3 then .inl (.fields 0) else .inl (.entry (nextLevel level))\n/-- Static successor after one physical field call. -/\ndef nextField (part:Fin 5) : Label :=\n  if h:part.val<4 then .inl (.fields ⟨part.val+1,by omega⟩) else .inl .ret\n/-- ONE fixed literal instruction table, with real nested calls and returns. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inl (level,pc)) => Link.instruction (copyStack level) (copyLabel level) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr (part,pc)) => Link.instruction (frameStack part) (frameLabel part) (SemiprimeD1StackFrame.code pc)\n  | .inl .main => .call (.inl (.entry 0)) (.inl .halt)\n  | .inl .ret => .ret\n  | .inl .halt => .base .halt\n  | .inl (.entry level) => .call (copyLabel level 0) (.inl (.drop level))\n  | .inl (.drop level) => .base (.pop (indexStack level) (.inl .ret) (.inl (.child level)) (.inl (.child level)))\n  | .inl (.child level) => .call (childEntry level) (.inl (.after level))\n  | .inl (.after level) => .base (.pop (indexStack level) (.inl .ret) (.inl (.child level)) (.inl (.child level)))\n  | .inl (.fields part) => .call (frameLabel part 0) (nextField part)\n/-- Fixed internal engine machine; original-input wrapper will acquire all limits and tag. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (limitStack 0) (aux 2) (.inl .main) program\n/-- Real component maps have disjoint physical roles. -/\ntheorem copyStack_injective (level:Fin 4) : Function.Injective (copyStack level) := by fin_cases level <;> decide\n/-- Frame source/output/scratch roles are disjoint for every actual field. -/\ntheorem frameStack_injective (part:Fin 5) : Function.Injective (frameStack part) := by fin_cases part <;> decide\n/-- Twelve fixed Boolean stacks. -/\ntheorem stack_card : Fintype.card Stack=12 := by decide\n/-- One hundred fifteen fixed control labels. -/\ntheorem label_card : Fintype.card Label=115 := by decide\n/-- Every stack alphabet is finite; the real return alphabet is fixed too. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (limitStack 0) (aux 2) (.inl .main) program\nend RiemannGaussian.SemiprimeD1StackCartesian4\n","RiemannGaussian.SemiprimeD1StackCartesian4Execution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCartesian4Loop\n\n/-! # Closed four-level physical Cartesian execution\nAll lower-procedure premises are discharged here from actual included Frame\ncalls. This internal primitive still requires its physical limits/tag; the\noriginal-input catalogue wrapper acquires those from the real public data.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackCartesian4Execution\nopen SemiprimeD1StackCartesian4 SemiprimeD1StackCartesian4Components SemiprimeD1StackCartesian4Body\nopen SemiprimeD1StackCartesian4Loop\nopen SemiprimeD1StackProcedureFragments (Runs)\n\n/-- Actual remaining level counters are empty between physical calls. -/\ndef ReadyFrom (level:ℕ) (indices:Fin 4→List Bool) : Prop := ∀j,level≤j.val→indices j=[]\n/-- Common finite word-width bound for actual current indices. -/\ndef IndexBound (D:ℕ) (indices:Fin 4→List Bool) : Prop := ∀j,(indices j).length≤D\n\n/-- A bounded physically visited index preserves the actual index-length bound. -/\ntheorem update_bound (indices:Fin 4→List Bool) (level:Fin 4) (i D:ℕ)\n    (hb:IndexBound D indices) (hi:i≤D) :\n    IndexBound D (Function.update indices level (List.replicate i true)) := by\n  intro j\n  by_cases h:j=level\n  · subst j;simpa only [Function.update_self,List.length_replicate] using hi\n  · simpa only [Function.update_of_ne h] using hb j\n\n/-- A real outer index never changes any lower-level empty work counter. -/\ntheorem update_ready (indices:Fin 4→List Bool) (level:Fin 4) (word:List Bool)\n    (hr:ReadyFrom level.val indices) : ReadyFrom (level.val+1) (Function.update indices level word) := by\n  intro j hj\n  have hn:j≠level:=by intro h;subst j;omega\n  rw [Function.update_of_ne hn]\n  exact hr j (by omega)\n\n/-- Exact innermost record fold. -/\ndef box3 (dims:Fin 4→ℕ) (indices:Fin 4→List Bool) (tag output:List Bool) : List Bool :=\n  rangeFold (dims 3) (fun i out=>record tag (Function.update indices 3 (List.replicate i true)) out) output\n/-- Exact third-level product fold. -/\ndef box2 (dims:Fin 4→ℕ) (indices:Fin 4→List Bool) (tag output:List Bool) : List Bool :=\n  rangeFold (dims 2) (fun i out=>box3 dims (Function.update indices 2 (List.replicate i true)) tag out) output\n/-- Exact second-level product fold. -/\ndef box1 (dims:Fin 4→ℕ) (indices:Fin 4→List Bool) (tag output:List Bool) : List Bool :=\n  rangeFold (dims 1) (fun i out=>box2 dims (Function.update indices 1 (List.replicate i true)) tag out) output\n/-- Exact whole four-axis product fold, in original ascending lexicographic order. -/\ndef box0 (dims:Fin 4→ℕ) (indices:Fin 4→List Bool) (tag output:List Bool) : List Bool :=\n  rangeFold (dims 0) (fun i out=>box1 dims (Function.update indices 0 (List.replicate i true)) tag out) output\n\n/-- Fixed-degree polynomial clock, with the number of loop levels fixed to four. -/\ndef stageBudget (D T:ℕ) : ℕ→ℕ\n  | 0 => 6*(4*D+T)+25\n  | n+1 => D*(stageBudget D T n+8)+5\n\n/-- Actual closed physical level3, retaining all child calls and original counter copies. -/\ntheorem level3_run (dims:Fin 4→ℕ) (limits indices:Fin 4→List Bool) (tag output:List Bool) (D:ℕ)\n    (hl:∀j,limits j=List.replicate (dims j) true) (hd:∀j,dims j≤D)\n    (hb:IndexBound D indices) (hc:ReadyFrom 3 indices) :\n    ∃m≤stageBudget D tag.length 1,Runs program m (.inl (.entry 3)) (store limits indices tag output)\n      (.inl .ret) (store limits indices tag (box3 dims indices tag output)) := by\n  have hchild:∀i<dims 3,∀out,∃m≤stageBudget D tag.length 0,\n      Runs program m (childEntry 3)\n        (store limits (Function.update indices 3 (List.replicate i true)) tag out)\n        (.inl .ret) (store limits (Function.update indices 3 (List.replicate i true)) tag\n          (record tag (Function.update indices 3 (List.replicate i true)) out)):=by\n    intro i hi out\n    let current:=Function.update indices 3 (List.replicate i true)\n    have hbi:IndexBound D current:=update_bound indices 3 i D hb ((Nat.le_of_lt hi).trans (hd 3))\n    refine ⟨bodyClock current tag,bodyClock_le current tag D hbi,?_⟩\n    change Runs program _ (.inl (.fields 0)) _ (.inl .ret) _\n    exact body_run limits current tag out\n  obtain ⟨m,hm,ht⟩:=entry_run (dims 3) 3 limits indices tag (hl 3) (hc 3 (le_refl _))\n    (fun i out=>record tag (Function.update indices 3 (List.replicate i true)) out) (stageBudget D tag.length 0) hchild output\n  refine ⟨m,hm.trans ?_,ht⟩\n  exact Nat.add_le_add_right (Nat.mul_le_mul_right _ (hd 3)) 5\n\n/-- Actual closed physical level2, retaining all child calls and original counter copies. -/\ntheorem level2_run (dims:Fin 4→ℕ) (limits indices:Fin 4→List Bool) (tag output:List Bool) (D:ℕ)\n    (hl:∀j,limits j=List.replicate (dims j) true) (hd:∀j,dims j≤D)\n    (hb:IndexBound D indices) (hc:ReadyFrom 2 indices) :\n    ∃m≤stageBudget D tag.length 2,Runs program m (.inl (.entry 2)) (store limits indices tag output)\n      (.inl .ret) (store limits indices tag (box2 dims indices tag output)) := by\n  have hchild:∀i<dims 2,∀out,∃m≤stageBudget D tag.length 1,\n      Runs program m (childEntry 2)\n        (store limits (Function.update indices 2 (List.replicate i true)) tag out)\n        (.inl .ret) (store limits (Function.update indices 2 (List.replicate i true)) tag\n          (box3 dims (Function.update indices 2 (List.replicate i true)) tag out)):=by\n    intro i hi out\n    let current:=Function.update indices 2 (List.replicate i true)\n    have hbi:IndexBound D current:=update_bound indices 2 i D hb ((Nat.le_of_lt hi).trans (hd 2))\n    have hci:ReadyFrom 3 current:=update_ready indices 2 (List.replicate i true) hc\n    obtain ⟨m,hm,ht⟩:=level3_run dims limits current tag out D hl hd hbi hci\n    refine ⟨m,hm,?_⟩\n    change Runs program m (.inl (.entry 3)) _ (.inl .ret) _\n    exact ht\n  obtain ⟨m,hm,ht⟩:=entry_run (dims 2) 2 limits indices tag (hl 2) (hc 2 (le_refl _))\n    (fun i out=>box3 dims (Function.update indices 2 (List.replicate i true)) tag out) (stageBudget D tag.length 1) hchild output\n  refine ⟨m,hm.trans ?_,ht⟩\n  exact Nat.add_le_add_right (Nat.mul_le_mul_right _ (hd 2)) 5\n\n/-- Actual closed physical level1, retaining all child calls and original counter copies. -/\ntheorem level1_run (dims:Fin 4→ℕ) (limits indices:Fin 4→List Bool) (tag output:List Bool) (D:ℕ)\n    (hl:∀j,limits j=List.replicate (dims j) true) (hd:∀j,dims j≤D)\n    (hb:IndexBound D indices) (hc:ReadyFrom 1 indices) :\n    ∃m≤stageBudget D tag.length 3,Runs program m (.inl (.entry 1)) (store limits indices tag output)\n      (.inl .ret) (store limits indices tag (box1 dims indices tag output)) := by\n  have hchild:∀i<dims 1,∀out,∃m≤stageBudget D tag.length 2,\n      Runs program m (childEntry 1)\n        (store limits (Function.update indices 1 (List.replicate i true)) tag out)\n        (.inl .ret) (store limits (Function.update indices 1 (List.replicate i true)) tag\n          (box2 dims (Function.update indices 1 (List.replicate i true)) tag out)):=by\n    intro i hi out\n    let current:=Function.update indices 1 (List.replicate i true)\n    have hbi:IndexBound D current:=update_bound indices 1 i D hb ((Nat.le_of_lt hi).trans (hd 1))\n    have hci:ReadyFrom 2 current:=update_ready indices 1 (List.replicate i true) hc\n    obtain ⟨m,hm,ht⟩:=level2_run dims limits current tag out D hl hd hbi hci\n    refine ⟨m,hm,?_⟩\n    change Runs program m (.inl (.entry 2)) _ (.inl .ret) _\n    exact ht\n  obtain ⟨m,hm,ht⟩:=entry_run (dims 1) 1 limits indices tag (hl 1) (hc 1 (le_refl _))\n    (fun i out=>box2 dims (Function.update indices 1 (List.replicate i true)) tag out) (stageBudget D tag.length 2) hchild output\n  refine ⟨m,hm.trans ?_,ht⟩\n  exact Nat.add_le_add_right (Nat.mul_le_mul_right _ (hd 1)) 5\n\n/-- Actual closed physical level0, retaining all child calls and original counter copies. -/\ntheorem level0_run (dims:Fin 4→ℕ) (limits indices:Fin 4→List Bool) (tag output:List Bool) (D:ℕ)\n    (hl:∀j,limits j=List.replicate (dims j) true) (hd:∀j,dims j≤D)\n    (hb:IndexBound D indices) (hc:ReadyFrom 0 indices) :\n    ∃m≤stageBudget D tag.length 4,Runs program m (.inl (.entry 0)) (store limits indices tag output)\n      (.inl .ret) (store limits indices tag (box0 dims indices tag output)) := by\n  have hchild:∀i<dims 0,∀out,∃m≤stageBudget D tag.length 3,\n      Runs program m (childEntry 0)\n        (store limits (Function.update indices 0 (List.replicate i true)) tag out)\n        (.inl .ret) (store limits (Function.update indices 0 (List.replicate i true)) tag\n          (box1 dims (Function.update indices 0 (List.replicate i true)) tag out)):=by\n    intro i hi out\n    let current:=Function.update indices 0 (List.replicate i true)\n    have hbi:IndexBound D current:=update_bound indices 0 i D hb ((Nat.le_of_lt hi).trans (hd 0))\n    have hci:ReadyFrom 1 current:=update_ready indices 0 (List.replicate i true) hc\n    obtain ⟨m,hm,ht⟩:=level1_run dims limits current tag out D hl hd hbi hci\n    refine ⟨m,hm,?_⟩\n    change Runs program m (.inl (.entry 1)) _ (.inl .ret) _\n    exact ht\n  obtain ⟨m,hm,ht⟩:=entry_run (dims 0) 0 limits indices tag (hl 0) (hc 0 (le_refl _))\n    (fun i out=>box1 dims (Function.update indices 0 (List.replicate i true)) tag out) (stageBudget D tag.length 3) hchild output\n  refine ⟨m,hm.trans ?_,ht⟩\n  exact Nat.add_le_add_right (Nat.mul_le_mul_right _ (hd 0)) 5\n\n/-- A complete actual finite range fold has the literal original ascending list order. -/\ntheorem rangeFold_range (n:ℕ) (F:ℕ→List Bool→List Bool) (tail:List Bool) :\n    rangeFold n F tail=(List.range n).foldr F tail := by\n  induction n generalizing tail with\n  | zero => rfl\n  | succ n ih => simp only [rangeFold,ih,List.range_succ,List.foldr_append,List.foldr_cons,List.foldr_nil]\nend RiemannGaussian.SemiprimeD1StackCartesian4Execution\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTraceBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOperationBounds\n/-! # Raw occurrence, endpoint and packet counts/bytes come from actual input tapes\nNo decoded count, field length, classification or recursive-child runtime is\nsupplied. The mathematical record views are bounded directly by their actual\nretained framed source words.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields payload)\nend P\nnamespace K\nexport SemiprimeD1StackChildGroupFactoryEndpointKeys (pairs placements)\nend K\nnamespace R\nexport SemiprimeD1StackChildGroupFactoryEndpointLoop (Row)\nend R\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (side selected oldPoints)\nend Code\nnamespace Op\nexport SemiprimeD1StackChildGroupFactoryOperationBounds (endpointBytes)\nend Op\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- All seven acquired original occurrence/placement fields, plus a positive byte. -/\ndef fieldBytes (f:P.Fields):Nat:=f.owner.length+f.factor.length+f.source.length+f.padding.length+\n  f.packet.length+f.slot.length+f.edge.length+1\n/-- The actual pair/placement record tapes pay every acquired field byte. -/\ntheorem field_le_tapes (fields:List P.Fields) (f:P.Fields) (hf:f∈fields):\n    fieldBytes f≤(K.pairs fields).length+(K.placements fields).length:=by\n  induction fields with\n  | nil=>simp only [List.not_mem_nil] at hf\n  | cons g gs ih=>\n    simp only [List.mem_cons] at hf\n    rcases hf with rfl|hf\n    · simp only [K.pairs,K.placements,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,\n        P.payload,List.length_nil,fieldBytes]\n      omega\n    · have ht:=ih hf\n      simp only [K.pairs,K.placements,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n/-- Every actual paired source row has a physically present TRUE/tag/frame footprint. -/\ntheorem fields_count (fields:List P.Fields):fields.length≤(K.pairs fields).length:=by\n  induction fields with\n  | nil=>simp only [List.length_nil,K.pairs,List.length_cons];omega\n  | cons f fs ih=>\n    simp only [List.length_cons,K.pairs,SemiprimeSourceHistogramKeyBits.frame_length]\n    omega\n/-- All actual source packets are charged even when their raw word is empty. -/\ntheorem packet_count (packets:List (List Bool)):packets.length≤(vectorBits packets).length:=by\n  induction packets with\n  | nil=>simp only [List.length_nil,vectorBits,List.length_cons];omega\n  | cons p ps ih=>\n    simp only [List.length_cons,vectorBits,SemiprimeSourceHistogramKeyBits.frame_length]\n    omega\n/-- Any actual raw packet word has a paid physical representation in the retained source tape. -/\ntheorem packet_word (packets:List (List Bool)) (packet:List Bool) (hp:packet∈packets):\n    packet.length≤(vectorBits packets).length:=by\n  induction packets with\n  | nil=>simp only [List.not_mem_nil] at hp\n  | cons p ps ih=>\n    simp only [List.mem_cons] at hp\n    rcases hp with rfl|hp\n    · simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length];omega\n    · have ht:=ih hp\n      simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length];omega\n/-- An emitted side contains only actual source fields and its one literal side bit. -/\ntheorem side_bytes (owner:Bool) (r:R.Row):Op.endpointBytes (Code.side owner r)≤fieldBytes r.fields+2:=by\n  cases owner <;> simp only [Code.side,Op.endpointBytes,fieldBytes,Bool.false_eq_true,ite_false,ite_true,\n    List.length_cons,List.length_nil] <;> omega\n/-- Computed activation may retain both/one/neither endpoint; no branch creates more than two. -/\ntheorem selected_count (rows:List R.Row):(Code.selected rows).length≤2*rows.length:=by\n  induction rows with\n  | nil=>simp only [Code.selected,List.length_nil,Nat.mul_zero,le_refl]\n  | cons r rs ih=>\n    cases ho:r.ownerFlag <;> cases hf:r.factorFlag <;>\n      simp only [Code.selected,ho,hf,Bool.false_eq_true,ite_false,ite_true,List.length_append,\n        List.length_cons,List.length_nil] <;> omega\n/-- Every actual selected endpoint inherits its raw-byte bound from a real original row. -/\ntheorem selected_bytes (rows:List R.Row) (cap:Nat) (hc:∀r∈rows,fieldBytes r.fields≤cap):\n    ∀e∈Code.selected rows,Op.endpointBytes e≤cap+2:=by\n  induction rows with\n  | nil=>intro e he;simp only [Code.selected,List.not_mem_nil] at he\n  | cons r rs ih=>\n    have hh:=hc r List.mem_cons_self\n    have ht:=ih (fun q h=>hc q (List.mem_cons_of_mem r h))\n    intro e he\n    cases ho:r.ownerFlag <;> cases hf:r.factorFlag\n    all_goals simp only [Code.selected,ho,hf,Bool.false_eq_true,ite_false,ite_true,\n      List.nil_append,List.cons_append,List.mem_cons] at he\n    · exact ht e he\n    · rcases he with rfl|he\n      · exact (side_bytes false r).trans (Nat.add_le_add_right hh 2)\n      · exact ht e he\n    · rcases he with rfl|he\n      · exact (side_bytes true r).trans (Nat.add_le_add_right hh 2)\n      · exact ht e he\n    · rcases he with rfl|rfl|he\n      · exact (side_bytes true r).trans (Nat.add_le_add_right hh 2)\n      · exact (side_bytes false r).trans (Nat.add_le_add_right hh 2)\n      · exact ht e he\n/-- Both old endpoints are retained literally regardless of activation, so old port count is exactly twice original rows. -/\ntheorem old_count (rows:List R.Row):(Code.oldPoints rows).length=2*rows.length:=by\n  induction rows with\n  | nil=>rfl\n  | cons r rs ih=>\n    simp only [Code.oldPoints,List.flatMap_cons,List.length_append,List.length_cons,List.length_nil] at ih ⊢\n    omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivation\n/-! # Abstract physical boundaries for one whole activation iteration\nThese are full115-word specifications. No boundary structure or evaluator\noccurs in the literal program or its thirteen-word input interface.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactory\nopen SemiprimeD1StackChildGroupFactoryCalls SemiprimeD1StackChildGroupFactoryActivation\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Only the genuinely acquired colour supplies this proof-side Boolean. -/\ndef active (i:Inputs) (coordinate:Nat) (colours:List (List Bool)):Bool:=\n  decide (SemiprimeBitArithmetic.bitValue (Col.result coordinate colours).1=\n    SemiprimeBitArithmetic.bitValue i.group)\n/-- All eleven lookup allocations are clean; the discovered ID is in its real word. -/\ndef selectedData (i:Inputs) (todo key hist map selected:List Bool):Stack→List Bool:=\n  Function.update (data i todo key hist map) (aux .selectedID) selected\n/-- Both real catalogue rows and unary coordinate have been physically acquired. -/\ndef rowData (i:Inputs) (todo key hist map selected:List Bool) (coordinate:Nat)\n    (colours:List (List Bool)):Stack→List Bool:=\n  let base:=Function.update (selectedData i todo key hist map selected) (aux .jointKey) (frame selected selected)\n  let full:=withRows base (SemiprimeD1StackPacketRowsExecution.result\n    (frame selected selected) i.catalogue colours colours)\n  Function.update (Function.update full (aux .colourReader) (vectorBits colours))\n    (aux .colourCursor) (List.replicate coordinate true)\n/-- The actual flag and map row are logged; precisely listed work remains to be drained. -/\ndef loggedData (i:Inputs) (todo key hist map selected:List Bool) (coordinate:Nat)\n    (colours:List (List Bool)):Stack→List Bool:=\n  let flag:=active i coordinate colours\n  let base:=selectedData i todo key (flag::hist) (true::frame key (frame [flag] map)) selected\n  let joint:=Function.update base (aux .jointKey) (frame selected selected)\n  let full:=withRows joint (SemiprimeD1StackPacketRowsExecution.result\n    (frame selected selected) i.catalogue colours colours)\n  Function.update (Function.update (Function.update full (aux .colourReader) (Col.result coordinate colours).2)\n    (aux .colourWord) (Col.result coordinate colours).1) (aux .flagScratch) [flag]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsLoopView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsLoop\n/-! # Exact entire chronological observed-packet output of the real loop\nThe fresh child-global counter spans all buckets; neither repeated prepared\npackets nor observed zero-arity buckets are deleted or identified.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsLoopView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryBucketsLoop\nnamespace OV\nexport SemiprimeD1StackChildGroupFactoryBucketOneView (result_other result_factorHistory bucketRow result_position)\nend OV\n/-- Exact ordered raw bucket-record stream, before its final FALSE. -/\ndef records:List (List Bool)→List Parse.Endpoint→List Bool→List Bool\n  | [],_,_=>[]\n  | packet::packets,es,position=>OV.bucketRow es packet position++records packets es (LV.finalPosition es packet position)\n/-- Actual final fresh binary position after every observed packet. -/\ndef finalPosition:List (List Bool)→List Parse.Endpoint→List Bool→List Bool\n  | [],_,position=>position\n  | packet::packets,es,position=>finalPosition packets es (LV.finalPosition es packet position)\n/-- All actual observed buckets are retained in exact input order. -/\ntheorem result_factorHistory (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool):\n    result packets before es position (aux .factorHistory)=\n      (records packets es position).reverse++before (aux .factorHistory):=by\n  induction packets generalizing before position with\n  | nil=>simp only [result,atEOF,records,List.reverse_nil,List.nil_append];rfl\n  | cons packet packets ih=>\n    rw [result,ih,OV.result_factorHistory]\n    simp only [records,List.reverse_append,List.append_assoc]\n/-- Entire actual scan leaves its observed-packet reader empty. -/\ntheorem result_packetReader (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool):\n    result packets before es position (aux .packetReader)=[]:=by\n  induction packets generalizing before position with\n  | nil=>rfl\n  | cons packet packets ih=>exact ih _ _\n/-- The actual fresh counter has advanced once for every emitted child occurrence. -/\ntheorem result_position (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (hp:before (aux .globalPosition)=position):\n    result packets before es position (aux .globalPosition)=finalPosition packets es position:=by\n  induction packets generalizing before position with\n  | nil=>simpa [result,atEOF,finalPosition,aux] using hp\n  | cons packet packets ih=>exact ih _ _ (OV.result_position _ _ _ _ _ hp)\n/-- All retained caller/cache bytes outside the exact actual work roles are unchanged. -/\ntheorem result_other (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool) (k:Stack)\n    (hf:∀j,Cleanup.role j≠k) (hu:∀j,Reuse.role j≠k)\n    (hpr:k≠aux .packetReader) (her:k≠aux .endpointReader) (hbh:k≠aux .bucketHistory)\n    (hph:k≠aux .portHistory) (hpos:k≠aux .globalPosition) (hfh:k≠aux .factorHistory):\n    result packets before es position k=before k:=by\n  induction packets generalizing before position with\n  | nil=>simp only [result,atEOF,Function.update_of_ne hpr]\n  | cons packet packets ih=>rw [result,ih];exact OV.result_other _ _ _ _ _ _ hf hu hpr her hbh hph hpos hfh\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsLoopView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueCodecs":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointLoopView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsLoopView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortParse\n/-! # Byte identities joining actual forward, bucket and original-order scans\nEvery decoded record below is a proof interpretation of emitted actual fields.\nThere is no additional physical input, permutation or classification premise.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueCodecs\nnamespace End\nexport SemiprimeD1StackChildGroupFactoryEndpointLoop (Row)\nexport SemiprimeD1StackChildGroupFactoryEndpointLoopView (oldRecords selectedRecords chosen)\nend End\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point payload records)\nexport SemiprimeD1StackChildGroupFactoryEndpointOldLog (oldPoint row)\nend Old\nnamespace Emit\nexport SemiprimeD1StackChildGroupFactoryEndpointEmit (endpoint row)\nend Emit\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint payload records)\nend E\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket payload records)\nend B\nnamespace Child\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (records)\nexport SemiprimeD1StackChildGroupFactoryBucketEmit (payload row)\nend Child\nnamespace Scan\nexport SemiprimeD1StackChildGroupFactoryBucketLoopView (selected records portWords finalPosition)\nend Scan\nnamespace Bank\nexport SemiprimeD1StackChildGroupFactoryBucketsLoopView (records)\nend Bank\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Framing retains the literal tail, without interpreting any raw packet bits. -/\ntheorem frame_tail (word xs ys:List Bool):frame word (xs++ys)=frame word xs++ys:=by\n  induction word with\n  | nil=>rfl\n  | cons b bs ih=>simp only [frame,ih,List.cons_append]\n/-- The two real old-endpoint rows are owner before factor at every occurrence. -/\ndef oldPoints (rows:List End.Row):List Old.Point:=rows.flatMap fun r=>\n  [⟨r.fields.owner,r.fields.edge,[true]⟩,⟨r.fields.factor,r.fields.edge,[false]⟩]\n/-- Proof interpretation of each actual selected side's five emitted raw fields. -/\ndef side (owner:Bool) (r:End.Row):E.Endpoint:=\n  ⟨if owner then r.fields.owner else r.fields.factor,r.fields.packet,r.fields.slot,r.fields.edge,[owner]⟩\n/-- Exact owner-before-factor selected endpoint fields in physical source order. -/\ndef selected :List End.Row→List E.Endpoint\n  | []=>[]\n  | r::rows=>(if r.ownerFlag then [side true r] else [])++\n      (if r.factorFlag then [side false r] else [])++selected rows\n/-- Joining the old endpoint parser adds no newly supplied table or order. -/\ntheorem oldPoints_records (rows:List End.Row):Old.records (oldPoints rows)=End.oldRecords rows++[false]:=by\n  induction rows with\n  | nil=>rfl\n  | cons r rs ih=>\n    simp only [oldPoints,List.flatMap_cons,List.cons_append,List.nil_append,Old.records,End.oldRecords]\n    change true::frame (Old.oldPoint true r.fields.owner r.fields.edge)\n      (true::frame (Old.oldPoint false r.fields.factor r.fields.edge) (Old.records (oldPoints rs)))=_\n    rw [ih]\n    simp only [Old.row,List.cons_append,←frame_tail,List.nil_append]\n/-- Exact selected endpoint record joining, including both/one/neither sides. -/\ntheorem selected_records (rows:List End.Row):E.records (selected rows)=End.selectedRecords rows++[false]:=by\n  induction rows with\n  | nil=>rfl\n  | cons r rs ih=>\n    cases ho:r.ownerFlag <;> cases hf:r.factorFlag\n    all_goals simp only [selected,ho,hf,Bool.false_eq_true,ite_false,ite_true,\n      List.nil_append,List.cons_append,List.append_nil,E.records,End.selectedRecords,End.chosen,ih,\n      side,E.payload,Emit.row,Emit.endpoint,←frame_tail]\n/-- Every actual six-field child record retains its raw endpoint and generated ID word. -/\ntheorem child_records (children:List (E.Endpoint×List Bool)):\n    Child.records children=children.flatMap (fun c=>Child.row c.1 c.2)++[false]:=by\n  induction children with\n  | nil=>rfl\n  | cons c cs ih=>\n    simp only [Child.records,List.flatMap_cons,Child.row,ih,List.cons_append,←frame_tail,List.nil_append]\n/-- Typed view of real buckets emitted in actual observed-packet order. -/\ndef buckets : List (List Bool)→List E.Endpoint→List Bool→List B.Bucket\n  | [],_,_=>[]\n  | packet::packets,es,position=>\n      ⟨packet,Scan.selected es packet position,SemiprimeD1StackPortOrdinalStream.result (Scan.portWords es packet position)⟩::\n        buckets packets es (Scan.finalPosition es packet position)\n/-- Exact byte bridge from emitted chronological buckets to the real subsequent parser. -/\ntheorem buckets_records (packets:List (List Bool)) (es:List E.Endpoint) (position:List Bool):\n    B.records (buckets packets es position)=Bank.records packets es position++[false]:=by\n  induction packets generalizing position with\n  | nil=>rfl\n  | cons packet packets ih=>\n    simp only [buckets,B.records,B.payload,child_records,ih,Bank.records,\n      SemiprimeD1StackChildGroupFactoryBucketOneView.bucketRow,Scan.records,\n      SemiprimeD1StackChildGroupFactoryBucketRecord.row,List.cons_append,←frame_tail,List.nil_append]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueCodecs\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryChildParse":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryFields\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketEmit\n/-! # Actual six-field child-endpoint parser at both literal scan sites\nThe Boolean theorem index names two fixed source-code families only; no search\nmode, child record or decoded address is an additional runtime operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryChildParse\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryFields SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nopen SemiprimeD1StackChildGroupFactoryBucketEmit (payload)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Two literal location families, fixed before all inputs. -/\ndef pc (search:Bool) (slot:Fin 18):Label:=if search then match slot.val with\n  | 0=>(.local 12 9)\n  | 1=>(.local 12 10)\n  | 2=>(.local 12 11)\n  | 3=>(.local 12 12)\n  | 4=>(.local 12 13)\n  | 5=>(.local 12 14)\n  | 6=>(.local 12 15)\n  | 7=>(.local 12 16)\n  | 8=>(.local 12 17)\n  | 9=>(.local 12 18)\n  | 10=>(.local 12 19)\n  | 11=>(.local 12 20)\n  | 12=>(.local 12 21)\n  | 13=>(.local 12 22)\n  | 14=>(.local 12 23)\n  | 15=>(.local 12 24)\n  | 16=>(.local 12 25)\n  | 17=>(.local 12 26)\n  | _=>(.local 12 26)\nelse match slot.val with\n  | 0=>(.local 9 20)\n  | 1=>(.local 9 21)\n  | 2=>(.local 9 22)\n  | 3=>(.local 9 23)\n  | 4=>(.local 9 24)\n  | 5=>(.local 9 25)\n  | 6=>(.local 9 26)\n  | 7=>(.local 9 27)\n  | 8=>(.local 9 28)\n  | 9=>(.local 9 29)\n  | 10=>(.local 9 30)\n  | 11=>(.local 9 31)\n  | 12=>(.local 10 0)\n  | 13=>(.local 10 1)\n  | 14=>(.local 10 2)\n  | 15=>(.local 10 3)\n  | 16=>(.local 10 4)\n  | 17=>(.local 10 5)\n  | _=>(.local 10 5)\n/-- Every real destination and parser-private role is physically fresh. -/\ndef cleanRoles:List Stack:=[aux .ownerKey,aux .sourceKey,aux .slotWord,aux .edgeWord,aux .sideWord,\n  aux .globalPosition,aux .rowBuffer,field (.inl .scratch),field (.inr ())]\n/-- Full actual parsed child bank with literal original fields and actual fresh-global ID. -/\ndef result (before:Stack→List Bool) (e:Endpoint) (position tail:List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (Function.update\n    (Function.update (Function.update before (aux .endpointReader) tail) (aux .ownerKey) e.vertex)\n      (aux .sourceKey) e.packet) (aux .slotWord) e.slot) (aux .edgeWord) e.edge) (aux .sideWord) e.side)\n      (aux .globalPosition) position\n/-- Seven actual Field calls/validity pops, one vector-tag pop and one actual EOF test. -/\ndef timeBound (e:Endpoint) (position:List Bool):Nat:=\n  8*((payload e position).length+e.vertex.length+e.packet.length+e.slot.length+e.edge.length+e.side.length+position.length)+58\n/-- The literal six-field child source at either actually present program site. -/\ntheorem source_trace (search:Bool) (before:Stack→List Bool) (e:Endpoint) (position tail:List Bool)\n    (hi:before (aux .endpointReader)=true::frame (payload e position) tail)\n    (hz:∀k∈cleanRoles,before k=[]):\n    Runs program (timeBound e position) (pc search 0) before (pc search 17) (result before e position tail):=by\n  have hz0:before (aux .ownerKey)=[]:=hz _ (by simp [cleanRoles])\n  have hz1:before (aux .sourceKey)=[]:=hz _ (by simp [cleanRoles])\n  have hz2:before (aux .slotWord)=[]:=hz _ (by simp [cleanRoles])\n  have hz3:before (aux .edgeWord)=[]:=hz _ (by simp [cleanRoles])\n  have hz4:before (aux .sideWord)=[]:=hz _ (by simp [cleanRoles])\n  have hz5:before (aux .globalPosition)=[]:=hz _ (by simp [cleanRoles])\n  have hz6:before (aux .rowBuffer)=[]:=hz _ (by simp [cleanRoles])\n  have hz7:before (field (.inl .scratch))=[]:=hz _ (by simp [cleanRoles])\n  have hz8:before (field (.inr ()))=[]:=hz _ (by simp [cleanRoles])\n  simp only [aux,field,payload] at hi hz0 hz1 hz2 hz3 hz4 hz5 hz6 hz7 hz8\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .endpointReader) (frame (payload e position) tail)\n  have h0a:=pop_run (pc search 0) abort (pc search 1) (pc search 2) (aux .endpointReader) b0\n      (true::frame (payload e position) tail) (by cases search <;> rfl) (by simp [b0,aux,payload,hi])\n  have h0:Runs program 1 (pc search 0) b0 (pc search 2) b1:=by\n    simpa only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] using h0a\n  let b2:Stack→List Bool:=Function.update (Function.update b1 (aux .endpointReader) tail) (aux .rowBuffer) (payload e position)\n  have h1:Runs program (8*((payload e position)).length+8) (pc search 2) b1 (pc search 4) b2:=\n    field_read 11 (pc search 2) (pc search 3) (pc search 4) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b1 (payload e position) tail (by simp [b0,b1,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,aux,fieldStack,fieldPorts,payload,hz6]) (by simp [b0,b1,aux,field,payload,hz7]) (by simp [b0,b1,aux,field,payload,hz8])\n  let b3:Stack→List Bool:=Function.update (Function.update b2 (aux .rowBuffer) (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))) (aux .ownerKey) e.vertex\n  have h2:Runs program (8*(e.vertex).length+8) (pc search 4) b2 (pc search 6) b3:=\n    field_read 12 (pc search 4) (pc search 5) (pc search 6) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b2 e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position []))))) (by simp [b0,b1,b2,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,aux,fieldStack,fieldPorts,payload,hz0]) (by simp [b0,b1,b2,aux,field,payload,hz7]) (by simp [b0,b1,b2,aux,field,payload,hz8])\n  let b4:Stack→List Bool:=Function.update (Function.update b3 (aux .rowBuffer) (frame e.slot (frame e.edge (frame e.side (frame position []))))) (aux .sourceKey) e.packet\n  have h3:Runs program (8*(e.packet).length+8) (pc search 6) b3 (pc search 8) b4:=\n    field_read 13 (pc search 6) (pc search 7) (pc search 8) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b3 e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))) (by simp [b0,b1,b2,b3,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,aux,fieldStack,fieldPorts,payload,hz1]) (by simp [b0,b1,b2,b3,aux,field,payload,hz7]) (by simp [b0,b1,b2,b3,aux,field,payload,hz8])\n  let b5:Stack→List Bool:=Function.update (Function.update b4 (aux .rowBuffer) (frame e.edge (frame e.side (frame position [])))) (aux .slotWord) e.slot\n  have h4:Runs program (8*(e.slot).length+8) (pc search 8) b4 (pc search 10) b5:=\n    field_read 14 (pc search 8) (pc search 9) (pc search 10) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b4 e.slot (frame e.edge (frame e.side (frame position []))) (by simp [b0,b1,b2,b3,b4,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,b4,aux,fieldStack,fieldPorts,payload,hz2]) (by simp [b0,b1,b2,b3,b4,aux,field,payload,hz7]) (by simp [b0,b1,b2,b3,b4,aux,field,payload,hz8])\n  let b6:Stack→List Bool:=Function.update (Function.update b5 (aux .rowBuffer) (frame e.side (frame position []))) (aux .edgeWord) e.edge\n  have h5:Runs program (8*(e.edge).length+8) (pc search 10) b5 (pc search 12) b6:=\n    field_read 15 (pc search 10) (pc search 11) (pc search 12) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b5 e.edge (frame e.side (frame position [])) (by simp [b0,b1,b2,b3,b4,b5,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,b4,b5,aux,fieldStack,fieldPorts,payload,hz3]) (by simp [b0,b1,b2,b3,b4,b5,aux,field,payload,hz7]) (by simp [b0,b1,b2,b3,b4,b5,aux,field,payload,hz8])\n  let b7:Stack→List Bool:=Function.update (Function.update b6 (aux .rowBuffer) (frame position [])) (aux .sideWord) e.side\n  have h6:Runs program (8*(e.side).length+8) (pc search 12) b6 (pc search 14) b7:=\n    field_read 16 (pc search 12) (pc search 13) (pc search 14) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b6 e.side (frame position []) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,fieldStack,fieldPorts,payload,hz4]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,field,payload,hz7]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,field,payload,hz8])\n  let b8:Stack→List Bool:=Function.update (Function.update b7 (aux .rowBuffer) []) (aux .globalPosition) position\n  have h7:Runs program (8*(position).length+8) (pc search 14) b7 (pc search 16) b8:=\n    field_read 19 (pc search 14) (pc search 15) (pc search 16) abort abort\n      (by cases search <;> rfl) (by cases search <;> rfl)\n      b7 position [] (by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,fieldStack,fieldPorts,payload]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,fieldStack,fieldPorts,payload,hz5]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,field,payload,hz7]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,field,payload,hz8])\n  have h8a:=peek_run (pc search 16) (pc search 17) abort abort (aux .rowBuffer) b8 []\n      (by cases search <;> rfl) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload])\n  have h8:Runs program 1 (pc search 16) b8 (pc search 17) b8:=by\n    simpa only [List.head?_nil,SemiprimeD1StackBytecode.choose] using h8a\n  have hout:b8=result before e position tail:=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,result]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,payload,hz6,result]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (join h7 (h8))))))))\n  rw [hout] at hwhole\n  have ht:(1)+((8*((payload e position)).length+8))+((8*(e.vertex).length+8))+((8*(e.packet).length+8))+((8*(e.slot).length+8))+((8*(e.edge).length+8))+((8*(e.side).length+8))+((8*(position).length+8))+(1)=timeBound e position:=by dsimp only [timeBound];omega\n  simpa only [←ht,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryChildParse\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryCounterBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueCodecs\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStreamBounds\n/-! # Internally generated counter bounds, allowing repeated prepared packets\nThe actual global counter starts at zero at the whole source's front door.\nBoth its raw binary width and numeric value are bounded by the actual emitted\nendpoint count. No original occurrence address or supplied unary ordinal is\nidentified with this distinct child-global domain.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryCounterBounds\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace Scan\nexport SemiprimeD1StackChildGroupFactoryBucketLoopView (selected finalPosition portWords)\nend Scan\nnamespace Inc\nexport SemiprimeD1StackChildGroupFactoryBucketIncrement (successor)\nend Inc\nnamespace Step\nexport SemiprimeD1StackChildGroupFactoryBucketVisitView (nextPosition)\nend Step\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (buckets)\nend Code\nopen SemiprimeBitArithmetic (bitValue)\n/-- Actual full binary successor has its true numeric value, including padded source words. -/\ntheorem successor_value (position:List Bool):bitValue (Inc.successor position)=bitValue position+1:=\n  SemiprimeD1StackChildGroupFactoryActivationLoop.advance_value position\n/-- Raw successor padding is paid additively, independently of numeric value. -/\ntheorem successor_length (position:List Bool):(Inc.successor position).length≤position.length+2:=\n  SemiprimeD1StackChildGroupFactoryActivationLoop.advance_length position\n/-- One actual packet scan emits at most one occurrence per forward endpoint. -/\ntheorem selected_length (es:List E.Endpoint) (packet position:List Bool):\n    (Scan.selected es packet position).length≤es.length:=by\n  induction es generalizing position with\n  | nil=>exact le_rfl\n  | cons e es ih=>\n    by_cases h:e.packet=packet\n    · simpa only [Scan.selected,h,ite_true,List.length_cons] using Nat.add_le_add_right (ih (Inc.successor position)) 1\n    · have ht:=ih position\n      simp only [Scan.selected,h,ite_false,List.length_cons]\n      omega\n/-- Both final raw width and final value are bounded by the actual EOF-limited visit count. -/\ntheorem scan_bounds (es:List E.Endpoint) (packet position:List Bool):\n    (Scan.finalPosition es packet position).length≤position.length+2*es.length ∧\n      bitValue (Scan.finalPosition es packet position)≤bitValue position+es.length:=by\n  induction es generalizing position with\n  | nil=>simp only [Scan.finalPosition,List.length_nil,Nat.mul_zero,Nat.add_zero,le_refl,and_self]\n  | cons e es ih=>\n    by_cases h:e.packet=packet\n    · have htail:=ih (Inc.successor position)\n      have hl:=successor_length position\n      have hv:=successor_value position\n      simp only [Scan.finalPosition,Step.nextPosition,h,ite_true,List.length_cons]\n      constructor <;> omega\n    · have htail:=ih position\n      simp only [Scan.finalPosition,Step.nextPosition,h,ite_false,List.length_cons]\n      constructor <;> omega\n/-- Every actually emitted ID inherits the bound of the same physical generated counter. -/\ntheorem selected_word_bounds (es:List E.Endpoint) (packet position:List Bool)\n    (p:E.Endpoint×List Bool) (hp:p∈Scan.selected es packet position):\n    p.2.length≤position.length+2*es.length ∧ bitValue p.2≤bitValue position+es.length:=by\n  induction es generalizing position with\n  | nil=>simp only [Scan.selected,List.not_mem_nil] at hp\n  | cons e es ih=>\n    by_cases h:e.packet=packet\n    · simp only [Scan.selected,h,ite_true,List.mem_cons] at hp\n      rcases hp with rfl|hp\n      · simp only [List.length_cons];constructor <;> omega\n      · have htail:=ih (Inc.successor position) hp\n        have hl:=successor_length position\n        have hv:=successor_value position\n        simp only [List.length_cons];constructor <;> omega\n    · have htail:=ih position (by simpa only [Scan.selected,h,ite_false] using hp)\n      simp only [List.length_cons];constructor <;> omega\n/-- Prepared duplicate packets may replicate endpoint occurrences K times; no uniqueness is assumed. -/\ntheorem catalogue_count (packets:List (List Bool)) (es:List E.Endpoint) (position:List Bool):\n    ((Code.buckets packets es position).flatMap (fun b=>b.children)).length≤packets.length*es.length:=by\n  induction packets generalizing position with\n  | nil=>simp only [Code.buckets,List.flatMap_nil,List.length_nil,Nat.zero_mul,le_refl]\n  | cons packet packets ih=>\n    have ht:=ih (Scan.finalPosition es packet position)\n    have hh:=selected_length es packet position\n    simp only [Code.buckets,List.flatMap_cons,List.length_append,List.length_cons]\n    nlinarith\n/-- Every ID in the complete actual catalogue has a raw/value bound in K times forward-endpoint count. -/\ntheorem catalogue_word_bounds (packets:List (List Bool)) (es:List E.Endpoint) (position:List Bool)\n    (p:E.Endpoint×List Bool) (hp:p∈(Code.buckets packets es position).flatMap (fun b=>b.children)):\n    p.2.length≤position.length+2*(packets.length*es.length) ∧\n      bitValue p.2≤bitValue position+packets.length*es.length:=by\n  induction packets generalizing position with\n  | nil=>simp only [Code.buckets,List.flatMap_nil,List.not_mem_nil] at hp\n  | cons packet packets ih=>\n    simp only [Code.buckets,List.flatMap_cons,List.mem_append] at hp\n    rcases hp with hp|hp\n    · have hh:=selected_word_bounds es packet position p hp\n      simp only [List.length_cons];constructor <;> nlinarith\n    · have ht:=ih (Scan.finalPosition es packet position) hp\n      have hs:=scan_bounds es packet position\n      simp only [List.length_cons];constructor <;> nlinarith\n/-- At the real zero-counter front door, generated ordinal VALUE is bounded by the actual emitted-node cap. -/\ntheorem generated_value (packets:List (List Bool)) (es:List E.Endpoint)\n    (p:E.Endpoint×List Bool) (hp:p∈(Code.buckets packets es []).flatMap (fun b=>b.children)):\n    bitValue p.2≤packets.length*es.length:=by\n  have h:=catalogue_word_bounds packets es [] p hp\n  simpa only [SemiprimeBitArithmetic.bitValue,Nat.zero_add] using h.2\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryCounterBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointOldLog\n/-! # Actual selected endpoint row emission\nThe preceding actual lookup branches to these literal source sites. All five\nfields are framed from retained parsed bytes, including WHOLE raw packet bytes.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointEmit\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackChildGroupFactoryEndpointOldLog (vertex)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- The two finite literal row-emission code families, never input modes. -/\ndef pc (owner:Bool) (slot:Fin 10):Label:=if owner then match slot.val with\n  | 0=>(.local 4 16)\n  | 1=>(.local 4 17)\n  | 2=>(.local 4 18)\n  | 3=>(.local 4 19)\n  | 4=>(.local 4 20)\n  | 5=>(.local 4 21)\n  | 6=>(.local 4 22)\n  | 7=>(.local 4 23)\n  | 8=>(.local 4 24)\n  | 9=>(.local 4 25)\n  | _=>(.local 4 25)\nelse match slot.val with\n  | 0=>(.local 5 28)\n  | 1=>(.local 5 29)\n  | 2=>(.local 5 30)\n  | 3=>(.local 5 31)\n  | 4=>(.local 6 0)\n  | 5=>(.local 6 1)\n  | 6=>(.local 6 2)\n  | 7=>(.local 6 3)\n  | 8=>(.local 6 4)\n  | 9=>(.local 6 5)\n  | _=>(.local 6 5)\n/-- Exact five-field actual endpoint payload in original occurrence-major side order. -/\ndef endpoint (owner:Bool) (v packet slot edge:List Bool):List Bool:=\n  frame v (frame packet (frame slot (frame edge (frame [owner] []))))\n/-- Exact physical vector record put on the reversed actual endpoint log. -/\ndef row (owner:Bool) (v packet slot edge:List Bool):List Bool:=true::frame (endpoint owner v packet slot edge) []\n/-- All six preserving frames, actual tag, consuming reversal and buffer erase. -/\ndef timeBound (owner:Bool) (v packet slot edge:List Bool):Nat:=\n  (6*([owner]:List Bool).length+5)+(6*edge.length+5)+(6*slot.length+5)+(6*packet.length+5)+\n  (6*v.length+5)+(6*(endpoint owner v packet slot edge).length+5)+1+\n  (2*(row owner v packet slot edge).length+3)+((endpoint owner v packet slot edge).length+1)\n/-- Actual endpoint logger preserves raw packet padding and every unrelated physical word. -/\ntheorem source_trace (owner:Bool) (before:Stack→List Bool) (v packet slot edge:List Bool)\n    (hv:before (vertex owner)=v) (hp:before (aux .packetKey)=packet)\n    (hs:before (aux .slotWord)=slot) (he:before (aux .edgeWord)=edge)\n    (hside:before (aux .sideWord)=[owner]) (hr:before (aux .rowBuffer)=[])\n    (hb:before (aux .frameBuffer)=[]) (hc:before (aux .copyScratch)=[]):\n    Runs program (timeBound owner v packet slot edge) (pc owner 0) before (pc owner 9)\n      (Function.update before (aux .endpointHistory)\n        ((row owner v packet slot edge).reverse++before (aux .endpointHistory))):=by\n  simp only [vertex,aux] at hv hp hs he hside hr hb hc\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .rowBuffer) (frame [owner] [])\n  have h0:Runs program (6*([owner]).length+5) (pc owner 0) b0 (pc owner 1) b1:=\n    frame_call 3 (pc owner 0) (pc owner 1) (by cases owner <;> rfl)\n      b0 [owner] [] (by cases owner <;> simp at hv <;> simp [b0,aux,frameStack,framePorts,hside]) (by cases owner <;> simp at hv <;> simp [b0,aux,frameStack,framePorts,hr]) (by cases owner <;> simp at hv <;> simp [b0,aux,frameStack,hc])\n  let b2:Stack→List Bool:=Function.update b1 (aux .rowBuffer) (frame edge (frame [owner] []))\n  have h1:Runs program (6*(edge).length+5) (pc owner 1) b1 (pc owner 2) b2:=\n    frame_call 4 (pc owner 1) (pc owner 2) (by cases owner <;> rfl)\n      b1 edge (frame [owner] []) (by cases owner <;> simp at hv <;> simp [b0,b1,aux,frameStack,framePorts,he]) (by cases owner <;> simp at hv <;> simp [b0,b1,aux,frameStack,framePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,aux,frameStack,hc])\n  let b3:Stack→List Bool:=Function.update b2 (aux .rowBuffer) (frame slot (frame edge (frame [owner] [])))\n  have h2:Runs program (6*(slot).length+5) (pc owner 2) b2 (pc owner 3) b3:=\n    frame_call 7 (pc owner 2) (pc owner 3) (by cases owner <;> rfl)\n      b2 slot (frame edge (frame [owner] [])) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,aux,frameStack,framePorts,hs]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,aux,frameStack,framePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,aux,frameStack,hc])\n  let b4:Stack→List Bool:=Function.update b3 (aux .rowBuffer) (frame packet (frame slot (frame edge (frame [owner] []))))\n  have h3:Runs program (6*(packet).length+5) (pc owner 3) b3 (pc owner 4) b4:=\n    frame_call 8 (pc owner 3) (pc owner 4) (by cases owner <;> rfl)\n      b3 packet (frame slot (frame edge (frame [owner] []))) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,aux,frameStack,framePorts,hp]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,aux,frameStack,framePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,aux,frameStack,hc])\n  let b5:Stack→List Bool:=Function.update b4 (aux .rowBuffer) (frame v (frame packet (frame slot (frame edge (frame [owner] [])))))\n  have h4a:=frame_call (if owner then 5 else 9) (pc owner 4) (pc owner 5) (by cases owner <;> rfl)\n      b4 v (frame packet (frame slot (frame edge (frame [owner] [])))) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,aux,frameStack,framePorts,hv]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,aux,frameStack,framePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,aux,frameStack,hc])\n  have h4:Runs program (6*(v).length+5) (pc owner 4) b4 (pc owner 5) b5:=by\n    cases owner <;> simpa [b5,frameStack,framePorts] using h4a\n  let b6:Stack→List Bool:=Function.update b5 (aux .frameBuffer) (frame (endpoint owner v packet slot edge) [])\n  have h5:Runs program (6*((endpoint owner v packet slot edge)).length+5) (pc owner 5) b5 (pc owner 6) b6:=\n    frame_call 6 (pc owner 5) (pc owner 6) (by cases owner <;> rfl)\n      b5 (endpoint owner v packet slot edge) [] (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,endpoint,aux,frameStack,framePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,aux,frameStack,framePorts,hb]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,aux,frameStack,hc])\n  let b7:Stack→List Bool:=Function.update b6 (aux .frameBuffer) (row owner v packet slot edge)\n  have h6p:b6 (aux .frameBuffer)=frame (endpoint owner v packet slot edge) []:=(by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,b6,endpoint,aux])\n  have h6a:=push_run (pc owner 6) (pc owner 7) (aux .frameBuffer) true b6 (by cases owner <;> rfl)\n  have h6:Runs program 1 (pc owner 6) b6 (pc owner 7) b7:=by simpa only [h6p,b7,row] using h6a\n  let b8:Stack→List Bool:=Function.update (Function.update b7 (aux .frameBuffer) []) (aux .endpointHistory) ((row owner v packet slot edge).reverse++before (aux .endpointHistory))\n  have h7:Runs program (2*(row owner v packet slot edge).length+3) (pc owner 7) b7 (pc owner 8) b8:=\n    reverse_call 2 (pc owner 7) (pc owner 8) (by cases owner <;> rfl) b7 (row owner v packet slot edge) (before (aux .endpointHistory)) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,endpoint,row,aux,reverseStack,reversePorts]) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,endpoint,row,aux,reverseStack,reversePorts])\n  let b9:Stack→List Bool:=Function.update b8 (aux .rowBuffer) []\n  have h8:Runs program ((endpoint owner v packet slot edge).length+1) (pc owner 8) b8 (pc owner 9) b9:=\n    drain_loop (pc owner 8) (pc owner 9) (aux .rowBuffer) (by cases owner <;> rfl) b8 (endpoint owner v packet slot edge) (by cases owner <;> simp at hv <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,endpoint,row,aux])\n  have hout:b9=Function.update before (aux .endpointHistory) ((row owner v packet slot edge).reverse++before (aux .endpointHistory)):=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux]\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux]\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux]\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux]\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux]\n    · cases k <;> cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,endpoint,row,aux,hp,hs,he,hside,hr,hb,hc]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (join h7 (h8))))))))\n  rw [hout] at hwhole\n  simpa only [timeBound,Nat.add_assoc] using hwhole\n/-- The real selected-endpoint logger is linear in its actual raw field bytes. -/\ntheorem timeBound_le (owner:Bool) (v packet slot edge:List Bool):\n    timeBound owner v packet slot edge≤256*(v.length+packet.length+slot.length+edge.length+1):=by\n  simp only [timeBound,row,endpoint,List.length_cons,List.length_nil,\n    SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointEmit\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortVisit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryChildParse\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexCompare\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryWordLog\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryChildCleanup\n/-! # Whole actual child-endpoint visit for one old vertex's left ports\nA real six-field parse supplies the vertex/global-ID words. Real numeric vertex\nequality selects whether to log that actual ID. All six fields are then erased.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortVisit\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nexport SemiprimeD1StackChildGroupFactoryChildParse (pc cleanRoles result timeBound source_trace)\nend Parse\nnamespace Compare\nexport SemiprimeD1StackChildGroupFactoryVertexCompare (pc next matched different timeBound source_trace)\nend Compare\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (pc row timeBound source_trace)\nend Log\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryChildCleanup (pc role result timeBound source_trace)\nend Cleanup\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Complete actual parsed child bank. -/\ndef parsed (before:Stack→List Bool) (e:Parse.Endpoint) (position tail:List Bool):Stack→List Bool:=Parse.result before e position tail\n/-- Actual matched word logger effect. -/\ndef logged (before:Stack→List Bool) (position:List Bool):Stack→List Bool:=\n  Function.update before (aux .portHistory) ((Log.row position).reverse++before (aux .portHistory))\n/-- Only an actual numeric equality result changes the port history. -/\ndef result (before:Stack→List Bool) (e:Parse.Endpoint) (position tail target:List Bool):Stack→List Bool:=\n  Cleanup.result (if bitValue e.vertex=bitValue target then logged (parsed before e position tail) position else parsed before e position tail)\n/-- Actual cleanup bytes of the six physically parsed fields. -/\ndef cleanupTime (e:Parse.Endpoint) (position:List Bool):Nat:=\n  e.vertex.length+e.packet.length+e.slot.length+e.edge.length+e.side.length+position.length+6\n/-- Complete literal parse/test/conditional-log/cleanup clock. -/\ndef timeBound (e:Parse.Endpoint) (position target:List Bool):Nat:=\n  Parse.timeBound e position+Compare.timeBound e.vertex target+\n    (if bitValue e.vertex=bitValue target then Log.timeBound position else 0)+cleanupTime e position\n/-- Complete actual child visit, without any supplied membership, port or order answer. -/\ntheorem source_trace (before:Stack→List Bool) (e:Parse.Endpoint) (position tail target:List Bool)\n    (hi:before (aux .endpointReader)=true::frame (SemiprimeD1StackChildGroupFactoryBucketEmit.payload e position) tail)\n    (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (hb:before (aux .frameBuffer)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound e position target) (.local 9 20) before (.local 9 20)\n      (result before e position tail target):=by\n  have h0:=Parse.source_trace false before e position tail hi hz\n  change Runs program _ (.local 9 20) before (.local 10 5) (parsed before e position tail) at h0\n  have ht':parsed before e position tail (aux .vertexKey)=target:=by simpa [parsed,Parse.result,aux] using ht\n  have hb':parsed before e position tail (aux .frameBuffer)=[]:=by simpa [parsed,Parse.result,aux] using hb\n  have hc':parsed before e position tail (aux .copyScratch)=[]:=by simpa [parsed,Parse.result,aux] using hc\n  have ha':∀k,parsed before e position tail (arithmetic k)=[]:=by\n    intro k;simpa [parsed,Parse.result,aux,arithmetic] using ha k\n  have h1:=Compare.source_trace 0 (parsed before e position tail) e.vertex target rfl ht' hc' ha'\n  by_cases h:bitValue e.vertex=bitValue target\n  · simp only [Compare.next,h,ite_true] at h1\n    change Runs program _ (.local 10 5) (parsed before e position tail) (.local 10 15) _ at h1\n    have h2:=Log.source_trace 0 (parsed before e position tail) position rfl hb' hc'\n    change Runs program _ (.local 10 15) _ (.local 10 9) (logged (parsed before e position tail) position) at h2\n    have h3:=Cleanup.source_trace false (logged (parsed before e position tail) position)\n    change Runs program (cleanupTime e position) (.local 10 9) _ (.local 9 20)\n      (Cleanup.result (logged (parsed before e position tail) position)) at h3\n    have hwhole:=join h0 (join h1 (join h2 h3))\n    simpa only [timeBound,result,h,ite_true,Nat.add_assoc] using hwhole\n  · simp only [Compare.next,h,ite_false] at h1\n    change Runs program _ (.local 10 5) (parsed before e position tail) (.local 10 9) _ at h1\n    have h2:=Cleanup.source_trace false (parsed before e position tail)\n    change Runs program (cleanupTime e position) (.local 10 9) _ (.local 9 20)\n      (Cleanup.result (parsed before e position tail)) at h2\n    have hwhole:=join h0 (join h1 h2)\n    simpa only [timeBound,result,h,ite_false,Nat.add_zero,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortVisit\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeActivation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBounds\nimport RiemannGaussian.SemiprimeD1ChildActivationOriginal\n/-! # Exact original all-vertex activation at the actual whole factory halt\nEvery original vertex is included, also isolated/inactive vertices. Arbitrarily\npadded binary group operands are interpreted numerically; colourIndex remains\nthe colour coordinate, never the distinct NEW context jetAxis.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeActivation\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactory\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryExecution (result)\nend E\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardSource (activation rows)\nend Forward\nnamespace A\nexport SemiprimeD1StackChildGroupFactoryActivationSource (result)\nexport SemiprimeD1StackChildGroupFactoryActivationMap (flags)\nend A\nnamespace M\nexport SemiprimeD1StackChildGroupFactoryActivationMeaning (plan_flags active_original)\nend M\nnamespace V\nexport SemiprimeD1StackChildGroupFactoryVerticesSource (result scopeDone loopBank copied)\nexport SemiprimeD1StackChildGroupFactoryVerticesLoopView (result_other)\nend V\nnamespace EV\nexport SemiprimeD1StackChildGroupFactoryEndpointSourceView (result_other)\nend EV\nnamespace BV\nexport SemiprimeD1StackChildGroupFactoryBucketsSourceView (result_other)\nend BV\nnamespace Native\nexport SemiprimeD1ChildActivation (acquire fromReplay fromReplay_bits readOne)\nend Native\nopen SemiprimeBitArithmetic (bitValue)\n/-- Actual all-vertex activation output survives every later source and the full physical sweep. -/\ntheorem result_flags (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool))\n    (fields:List SemiprimeD1StackChildGroupFactoryEndpointParse.Fields):\n    E.result i a coordinate ids packets fields (aux .activation)=A.flags i coordinate (Forward.activation a ids):=by\n  unfold E.result SemiprimeD1StackChildGroupFactorySuffix.result\n  rw [SemiprimeD1StackChildGroupFactoryFinish.result_retained _ _ (by decide) (by decide),\n    SemiprimeD1StackChildGroupFactoryFinalFrames.result_other _ _ (by decide)]\n  dsimp only [V.result,V.scopeDone]\n  rw [Function.update_of_ne (by decide:aux .activation≠aux .orders),\n    Function.update_of_ne (by decide:aux .activation≠aux .factorHistory),\n    Function.update_of_ne (by decide:aux .activation≠aux .leftPorts),\n    Function.update_of_ne (by decide:aux .activation≠aux .vertexHistory)]\n  unfold V.loopBank\n  rw [V.result_other _ _ _ _ _ _ (by\n      constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide) (by decide)]\n  rw [show V.copied (SemiprimeD1StackChildGroupFactoryForwardBucketsSource.result i a coordinate ids packets fields)\n      i.owners i.factors (aux .activation)=\n      SemiprimeD1StackChildGroupFactoryForwardBucketsSource.result i a coordinate ids packets fields (aux .activation) from\n        Function.update_of_ne (by decide) _ _]\n  unfold SemiprimeD1StackChildGroupFactoryForwardBucketsSource.result\n  rw [BV.result_other _ _ _ _ _ (by\n    constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide)]\n  unfold SemiprimeD1StackChildGroupFactoryForwardSource.result\n  rw [EV.result_other _ _ _ (by\n    constructor;all_goals first | (intro j;fin_cases j <;> decide) | decide)]\n  simp only [A.result,Function.update_self,SemiprimeD1StackChildGroupFactoryActivationResults.finish_history,\n    List.append_nil,List.reverse_reverse,A.flags]\n/-- Proof-side original selected IDs, acquired by the actual original finite search. -/\ndef originalIDs (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n):List (List Bool):=\n  (SemiprimeD1IncidenceSearch.run n F 64 a arity owner).value\n/-- The exact actual computed flag vector equals the legacy original activation producer. -/\ntheorem flags_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:bitValue i.group=g.val):\n    A.flags i q.val (Forward.activation a (originalIDs n F a arity owner))=\n      (Native.acquire n F 64 a arity owner q g).bits:=by\n  let ids:=originalIDs n F a arity owner\n  let canonical:Inputs:={i with group:=(SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits}\n  have hactive (colours:List (List Bool)):\n      SemiprimeD1StackChildGroupFactoryActivationView.active i q.val colours=\n        SemiprimeD1StackChildGroupFactoryActivationView.active canonical q.val colours:=by\n    simp only [SemiprimeD1StackChildGroupFactoryActivationView.active,canonical,\n      SemiprimeSourceHistogramPortKeys.encodeKey_value,hg]\n  rw [A.flags,Forward.activation,M.plan_flags]\n  change ids.reverse.map (fun id=>SemiprimeD1StackChildGroupFactoryActivationView.active i q.val\n    (SemiprimeD1StackPacketRowsMeaning.fields 64 a id))=(Native.fromReplay _ q g).bits\n  rw [Native.fromReplay_bits]\n  change ids.reverse.map (fun id=>SemiprimeD1StackChildGroupFactoryActivationView.active i q.val\n    (SemiprimeD1StackPacketRowsMeaning.fields 64 a id))=ids.reverse.map (fun id=>\n      (Native.readOne (SemiprimeSourceHistogramRows.acquire 64 a) a q.val\n        (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits id).value)\n  apply List.map_congr_left\n  intro id hi\n  have hmem:=SemiprimeD1IncidenceSearch.run_valid n F 64 a arity owner id (List.mem_reverse.mp hi)\n  rw [hactive]\n  exact M.active_original canonical a q.val id hmem\n/-- The actual whole halt contains exactly every original colour activation bit. -/\ntheorem result_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (packets:List (List Bool)) (fields:List SemiprimeD1StackChildGroupFactoryEndpointParse.Fields)\n    (hg:bitValue i.group=g.val):\n    E.result i a q.val (originalIDs n F a arity owner) packets fields (aux .activation)=\n      (Native.acquire n F 64 a arity owner q g).bits:=\n  (result_flags i a q.val (originalIDs n F a arity owner) packets fields).trans\n    (flags_original i n F a arity owner q g hg)\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeActivation\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeScopes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeBuckets\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCanonicalPorts\n/-! # Exact canonical original child scopes from the real generated ID filter\nThe source filters the actual packet-major child stream and converts its actual\nbinary global IDs. Its unary scope is exactly the native canonical left ports;\nno port list/permutation or equal original/generated ID namespace is assumed.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeScopes\nopen SemiprimeD1StackChildGroupFactory (Inputs)\nopen SemiprimeBitArithmetic (bitValue)\nnamespace I\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (Child portWords)\nend I\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket portWords)\nend B\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (buckets)\nend Code\nnamespace N\nexport SemiprimeD1StackChildGroupFactoryNativeEndpoints (encode)\nexport SemiprimeD1StackChildGroupFactoryNativeBuckets (numbering_original)\nend N\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source fields)\nend Fld\nnamespace Act\nexport SemiprimeD1StackChildGroupFactoryNativeActivation (originalIDs)\nend Act\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints)\nend Forward\n/-- Actual inner numeric filtering retains exactly the same generated global-ID values. -/\ntheorem inner_values (children:List I.Child) (target:List Bool):\n    (I.portWords children target).map bitValue=\n      (((children.map (fun p=>(p.1,bitValue p.2))).filter\n        (fun p=>decide (bitValue p.1.vertex=bitValue target))).map Prod.snd):=by\n  induction children with\n  | nil=>rfl\n  | cons p ps ih=>\n    by_cases h:bitValue p.1.vertex=bitValue target <;>\n      simp only [I.portWords,h,ite_true,ite_false,List.map_cons,List.filter_cons,\n        decide_true,decide_false,Bool.false_eq_true,ih]\n/-- Actual outer filtering preserves every real packet-major ordinal and multiplicity. -/\ntheorem scope_values (buckets:List B.Bucket) (target:List Bool):\n    (B.portWords buckets target).map bitValue=\n      ((((buckets.flatMap (fun b=>b.children)).map (fun p=>(p.1,bitValue p.2))).filter\n        (fun p=>decide (bitValue p.1.vertex=bitValue target))).map Prod.snd):=by\n  induction buckets with\n  | nil=>rfl\n  | cons b bs ih=>\n    simp only [B.portWords,List.flatMap_cons,List.map_append,List.filter_append,inner_values,ih]\n/-- Per-vertex actual generated values are the EXACT native child canonical port list. -/\ntheorem values_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:bitValue i.group=g.val) (v:Fin (n+F)) (target:List Bool) (ht:bitValue target=v.val):\n    (B.portWords (Code.buckets (Fld.source n F a arity owner).state.packets\n      (Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)) []) target).map bitValue=\n      SemiprimeD1TensorNetwork.leftPorts (SemiprimeD1TensorNetworkLayout.childRows\n        (SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g)) v:=by\n  rw [scope_values,N.numbering_original i n F a arity owner q g hg,\n    SemiprimeD1StackChildGroupFactoryCanonicalPorts.leftPorts_zipIdx]\n  change _=((((SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g).factors.map\n      (List.map SemiprimeD1ChildGraph.Endpoint.vertex)).flatten.zipIdx).filter\n        (fun p=>decide (p.1=v))).map Prod.snd\n  rw [←List.map_flatten,List.zipIdx_map,List.zipIdx_map]\n  simp only [List.filter_map,List.map_map,Function.comp_def,Prod.map,id_eq,N.encode,\n    SemiprimeSourceHistogramHeadRefinement.numberKey_value,ht,Fin.ext_iff]\n/-- Exact old unary portTape bytes come from the REAL numeric-bank-to-unary converter. -/\ntheorem unary_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:bitValue i.group=g.val) (v:Fin (n+F)) (target:List Bool) (ht:bitValue target=v.val):\n    SemiprimeD1StackPortOrdinalStream.result\n      (B.portWords (Code.buckets (Fld.source n F a arity owner).state.packets\n        (Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)) []) target)=\n      SemiprimeD1TensorTapeCodec.vectorBits ((SemiprimeD1TensorNetwork.leftPorts\n        (SemiprimeD1TensorNetworkLayout.childRows (SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g)) v).map\n          (fun id=>List.replicate id true)):=by\n  dsimp only [SemiprimeD1StackPortOrdinalStream.result]\n  apply congrArg SemiprimeD1TensorTapeCodec.vectorBits\n  have h:=congrArg (List.map (fun id=>List.replicate id true))\n    (values_original i n F a arity owner q g hg v target ht)\n  simpa only [List.map_map,Function.comp_def] using h\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeScopes\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsByteBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryStructuralByteBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop\n/-! # Additive real byte potential across the entire original-port query loop\nQueries really restore their twenty work roles and arithmetic bank. The only\npersistent growth is their real ordered binary answer row; original readers\nshrink. This avoids feeding a prefix runtime back into later query operands.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsByteBounds\nopen SemiprimeD1StackChildGroupFactoryRoles\nnamespace Loop\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (Fresh freshRole fresh_step result timeBound atEOF)\nend Loop\nnamespace One\nexport SemiprimeD1StackChildGroupFactoryOldPortOne (result)\nend One\nnamespace View\nexport SemiprimeD1StackChildGroupFactoryOldPortOneView\n  (result_other result_oldReader result_orderHistory answerWord)\nend View\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket)\nend B\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records)\nend P\nnamespace Early\nexport SemiprimeD1StackChildGroupFactoryTagEarlyClear (role)\nend Early\n/-- Actual early-stop roles are among the fixed twenty restored query roles. -/\ntheorem early_fresh (j:Fin 11):∃n:Fin 20,Loop.freshRole n=Early.role j:=by\n  fin_cases j\n  all_goals first\n    | exact ⟨0,rfl⟩ | exact ⟨1,rfl⟩ | exact ⟨2,rfl⟩ | exact ⟨3,rfl⟩\n    | exact ⟨4,rfl⟩ | exact ⟨5,rfl⟩ | exact ⟨6,rfl⟩ | exact ⟨7,rfl⟩\n    | exact ⟨8,rfl⟩ | exact ⟨9,rfl⟩ | exact ⟨10,rfl⟩\n/-- One actual restored query adds at most its computed binary answer row. -/\ntheorem one_word_le (before:Stack→List Bool) (buckets:List B.Bucket) (p:P.Point)\n    (tail target:List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap)\n    (hf:Loop.Fresh before) (ht:tail.length≤cap):\n    ∀k,(One.result before buckets p tail target k).length≤\n      cap+4*(buckets.flatMap (fun b=>b.children)).length+2:=by\n  have hnew:=Loop.fresh_step before buckets p tail target hf\n  have ha: (View.answerWord buckets p target).length≤2*(buckets.flatMap (fun b=>b.children)).length:=\n    (SemiprimeD1StackChildGroupFactoryOrderBounds.answer_bounds buckets p target).1\n  intro k\n  by_cases hw:∃j:Fin 20,Loop.freshRole j=k\n  · obtain ⟨j,rfl⟩:=hw\n    rw [hnew j]\n    simp only [List.length_nil]\n    omega\n  · have hnot:∀j:Fin 20,Loop.freshRole j≠k:=by intro j hj;exact hw ⟨j,hj⟩\n    have hearly:∀j:Fin 11,Early.role j≠k:=by\n      intro j hj;obtain ⟨n,hn⟩:=early_fresh j;exact hnot n (hn.trans hj)\n    by_cases hr:k=aux .oldReader\n    · subst k;rw [View.result_oldReader];omega\n    · by_cases hh:k=aux .orderHistory\n      · subst k\n        rw [View.result_orderHistory,List.length_append]\n        have hlog:(SemiprimeD1StackChildGroupFactoryWordLog.row (View.answerWord buckets p target)).length≤\n            4*(buckets.flatMap (fun b=>b.children)).length+2:=by\n          simp only [SemiprimeD1StackChildGroupFactoryWordLog.row,List.length_cons,\n            SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n          omega\n        have hbefore:=hc (aux .orderHistory)\n        split_ifs <;> simp only [List.length_reverse,List.length_nil] <;> omega\n      · rw [View.result_other _ _ _ _ _ _ hearly hr\n          (Ne.symm (hnot 11)) (Ne.symm (hnot 12)) (Ne.symm (hnot 13)) hh]\n        exact (hc k).trans (by omega)\n/-- Every old-record suffix is bounded by the original retained old-record tape. -/\ntheorem records_tail (p:P.Point) (ps:List P.Point):\n    (P.records ps).length≤(P.records (p::ps)).length:=by\n  simp only [P.records,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\n/-- Whole actual loop has only additive answer-row growth across all original records. -/\ntheorem result_word_le (points:List P.Point) (before:Stack→List Bool) (buckets:List B.Bucket)\n    (target:List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap)\n    (hf:Loop.Fresh before) (hr:(P.records points).length≤cap):\n    ∀k,(Loop.result points before buckets target k).length≤\n      cap+points.length*(4*(buckets.flatMap (fun b=>b.children)).length+2):=by\n  induction points generalizing before cap with\n  | nil=>\n    intro k\n    simp only [Loop.result,Loop.atEOF,Function.update_apply,List.length_nil,Nat.zero_mul,Nat.add_zero]\n    split_ifs\n    · simp only [List.length_nil];omega\n    · exact hc k\n  | cons p ps ih=>\n    let Q:=4*(buckets.flatMap (fun b=>b.children)).length+2\n    have hs:=one_word_le before buckets p (P.records ps) target cap hc hf ((records_tail p ps).trans hr)\n    have hf':=Loop.fresh_step before buckets p (P.records ps) target hf\n    have ht: (P.records ps).length≤cap+Q:=((records_tail p ps).trans hr).trans (Nat.le_add_right _ _)\n    have h:=ih (One.result before buckets p (P.records ps) target) (cap+Q) hs hf' ht\n    intro k\n    have hk:=h k\n    simp only [Loop.result,List.length_cons]\n    dsimp only [Q] at hk\n    nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsByteBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop\n/-! # Exact whole original-port index vector and actual full reuse invariant -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryOldPortsLoop\n/-- The actual original-port reader has consumed its real FALSE and passed physical EOF. -/\ntheorem result_oldReader (points:List Parse.Point) (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool):\n    result points before buckets target (aux .oldReader)=[]:=by\n  induction points generalizing before with\n  | nil=>rfl\n  | cons p ps ih=>exact ih _\n/-- All twenty actual query/parser/buffer words are fresh after the complete original-port scan. -/\ntheorem result_fresh (points:List Parse.Point) (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool)\n    (hf:Fresh before):Fresh (result points before buckets target):=by\n  induction points generalizing before with\n  | nil=>\n    intro j\n    have hn:freshRole j≠aux .oldReader:=by fin_cases j <;> decide\n    exact (Function.update_of_ne hn _ _).trans (hf j)\n  | cons p ps ih=>exact ih _ (fresh_step _ _ _ _ _ hf)\n/-- Every other actual caller/cache word survives the entire old-port scan. -/\ntheorem result_other (points:List Parse.Point) (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool) (k:Stack)\n    (hf:∀j,Early.role j≠k) (ho:k≠aux .oldReader) (ha:k≠aux .answerPosition)\n    (hp:k≠aux .localPosition) (ht:k≠aux .tagWord) (hh:k≠aux .orderHistory):\n    result points before buckets target k=before k:=by\n  induction points generalizing before with\n  | nil=>simp only [result,atEOF,Function.update_of_ne ho]\n  | cons p ps ih=>rw [result,ih];exact OV.result_other _ _ _ _ _ k hf ho ha hp ht hh\n/-- Exact chronological computed index records for EVERY matching original port, preserving duplicates. -/\ntheorem result_orderHistory (points:List Parse.Point) (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool):\n    result points before buckets target (aux .orderHistory)=\n      ((orderWords buckets points target).flatMap Log.row).reverse++before (aux .orderHistory):=by\n  induction points generalizing before with\n  | nil=>simp only [result,atEOF,orderWords,List.flatMap_nil,List.reverse_nil,List.nil_append];rfl\n  | cons p ps ih=>\n    rw [result,ih,OV.result_orderHistory]\n    by_cases h:SemiprimeBitArithmetic.bitValue p.vertex=SemiprimeBitArithmetic.bitValue target <;>\n      simp [orderWords,h,List.reverse_append,List.append_assoc]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactory\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryWiringFacts\n/-! # Actual generic source fragments for the complete child factory\nGeneric physical banks and label parameters keep native graphs and input\nmetadata opaque. Every clock below belongs to the actual literal procedure.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryWiringFacts\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological composition preserves all real outer returns. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after):\n    Runs program (m+n) pc before next after:=runs_trans program m n pc mid next before between after h g\n/-- A genuine preserving copy includes both restoration loops and its real return. -/\ntheorem copy_call (site:Fin 38) (pc next:Label)\n    (hc:program pc=.call (.copy site 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack site 0)=xs) (hy:before (copyStack site 1)=ys) (hs:before (copyStack site 2)=[]):\n    Runs program (5*xs.length+4) pc before next (Function.update before (copyStack site 1) (xs++ys)):=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- A genuine Frame preserves its source and prepends actual framed bytes. -/\ntheorem frame_call (site:Fin 25) (pc next:Label)\n    (hc:program pc=.call (.frame site 0) next) (before:Stack→List Bool) (word buffer:List Bool)\n    (hw:before (frameStack site 0)=word) (hb:before (frameStack site 1)=buffer) (hs:before (frameStack site 2)=[]):\n    Runs program (6*word.length+5) pc before next\n      (Function.update before (frameStack site 1) (SemiprimeSourceHistogramKeyBits.frame word buffer)):=by\n  let start:=SemiprimeD1StackFrame.state 0 none word buffer []\n  let stop:=SemiprimeD1StackFrame.done word (SemiprimeSourceHistogramKeyBits.frame word buffer)\n  have hi:Link.DataRel (frameStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hw\n      · exact hb\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (frameStack site) (frame_injective site) before start.store before hi (1:Fin 3)\n    (SemiprimeSourceHistogramKeyBits.frame word buffer)\n  have he:Function.update start.store 1 (SemiprimeSourceHistogramKeyBits.frame word buffer)=stop.store:=by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack site) (Label.frame site) (frame_injective site)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) pc next hc (6*word.length+4) start stop before _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words word buffer none) hi ho\n/-- Real consuming reversal pays its source bytes and actual return. -/\ntheorem reverse_call (site:Fin 16) (pc next:Label)\n    (hc:program pc=.call (.reverse site 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack site 0)=xs) (hy:before (reverseStack site 1)=ys):\n    Runs program (2*xs.length+3) pc before next\n      (Function.update (Function.update before (reverseStack site 0) []) (reverseStack site 1) (xs.reverse++ys)):=by\n  let start:=SemiprimeD1StackReverseWord.state none xs ys\n  let stop:=SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi:Link.DataRel (reverseStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  have h0:=Link.data_update (reverseStack site) (reverse_injective site) before start.store before hi (0:Fin 2) []\n  have h1:=Link.data_update (reverseStack site) (reverse_injective site) before _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he:Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at h1\n  exact included_call program (reverseStack site) (Label.reverse site) (reverse_injective site)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) pc next hc (2*xs.length+2) start stop before _ rfl rfl\n    (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi h1\n/-- One actual literal push writes only its real Boolean cell. -/\ntheorem push_run (pc next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)):\n    Runs program 1 pc before next (Function.update before k (b::before k)):=\n  one_base program pc next (.push k b next) before _ hc rfl rfl\n/-- One actual literal pop consumes its physical Boolean head. -/\ntheorem pop_run (pc empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs):\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?)\n      (Function.update before k xs.tail):=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real physical EOF peek retains every payload byte. -/\ntheorem peek_run (pc empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs):\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before:=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Real work-word cleanup pays every bit and its final empty pop. -/\ntheorem drain_loop (pc next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs):\n    Runs program (xs.length+1) pc before next (Function.update before k []):=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have h:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using h\n/-- One actual static jump preserves the entire physical bank. -/\ntheorem jump_run (pc next:Label) (before:Stack→List Bool) (hc:program pc=.base (.jump next)):\n    Runs program 1 pc before next before:=one_base program pc next (.jump next) before before hc rfl rfl\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagInnerView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop\n/-! # Entire actual nested first-index search through acquired bucket bytes\nThe real source parses each visited bucket header and child vector, stops at\nits first actual match, or physically reaches outer EOF. No found bit, index,\npermutation, decoded tag, scope or clock is a runtime operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagLoop\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Inner\nexport SemiprimeD1StackChildGroupFactoryTagInner (found next result timeBound source_trace)\nend Inner\nnamespace IV\nexport SemiprimeD1StackChildGroupFactoryTagInnerView (finalPosition result_other result_clean result_reader result_candidate result_position)\nend IV\nnamespace Encoding\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (records)\nend Encoding\nnamespace Buckets\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket payload records)\nend Buckets\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryChildParse (cleanRoles)\nend Parse\nnamespace Header\nexport SemiprimeD1StackChildGroupFactoryBucketHeader (result cleanRoles timeBound source_trace)\nend Header\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryChildCleanup (role)\nend Cleanup\n/-- Actual raw parsed-header boundary. -/\ndef head (before:Stack→List Bool) (b:Buckets.Bucket) (tail:List Bool):Stack→List Bool:=\n  Header.result before (Encoding.records b.children) tail\n/-- Exact actual one-bucket first-hit/exhaustion boundary. -/\ndef step (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool):Stack→List Bool:=\n  Inner.result b.children (head before b tail) target tag position\n/-- Both actual header and actually executed child-prefix clocks. -/\ndef stepTime (b:Buckets.Bucket) (target tag position:List Bool):Nat:=\n  Header.timeBound b.packet (Encoding.records b.children) b.ports+Inner.timeBound b.children target tag position\n/-- Real header+child source, with a next site computed by the actual child tests. -/\ntheorem step_trace (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool)\n    (hi:before (aux .outerReader)=true::SemiprimeSourceHistogramKeyBits.frame (Buckets.payload b) tail)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (htag:before (aux .tagWord)=tag)\n    (hp:before (aux .localPosition)=position) (hcan:before (aux .candidateTag)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (stepTime b target tag position) (.local 11 28) before (Inner.next b.children target tag)\n      (step before b tail target tag position):=by\n  have h0:=Header.source_trace true before b.packet (Encoding.records b.children) b.ports tail hi hh\n  change Runs program _ (.local 11 28) before (.local 12 9) (head before b tail) at h0\n  have h1:=Inner.source_trace b.children (head before b tail) target tag position rfl\n    (by simpa [head,Header.result,Parse.cleanRoles,aux,field] using hz)\n    (by simpa [head,Header.result,aux] using ht) (by simpa [head,Header.result,aux] using htag)\n    (by simpa [head,Header.result,aux] using hp) (by simpa [head,Header.result,aux] using hcan)\n    (by simpa [head,Header.result,aux] using hc) (by intro k;simpa [head,Header.result,aux,arithmetic] using ha k)\n  exact join h0 h1\n/-- Complete actual cache retention outside child/search data and both readers. -/\ntheorem step_other (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool) (k:Stack)\n    (hf:∀j,Cleanup.role j≠k) (he:k≠aux .endpointReader) (ho:k≠aux .outerReader)\n    (hcan:k≠aux .candidateTag) (hp:k≠aux .localPosition):step before b tail target tag position k=before k:=by\n  rw [step,IV.result_other _ _ _ _ _ k hf he hcan hp]\n  simp only [head,Header.result,Function.update_of_ne he,Function.update_of_ne ho]\n/-- Actual current outer suffix, even at an early hit where it will be physically drained later. -/\ntheorem step_outerReader (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool):\n    step before b tail target tag position (aux .outerReader)=tail:=by\n  rw [step,IV.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)]\n  rfl\n/-- Exact physically computed local position after this actual bucket prefix. -/\ntheorem step_position (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool)\n    (hp:before (aux .localPosition)=position):\n    step before b tail target tag position (aux .localPosition)=IV.finalPosition b.children target tag position:=by\n  exact IV.result_position _ _ _ _ _ (by simpa [head,Header.result,aux] using hp)\n/-- Only actual exhausted buckets promise child-parser freshness. -/\ntheorem step_clean (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]) (hf:Inner.found b.children target tag=false):\n    ∀k∈Parse.cleanRoles,step before b tail target tag position k=[]:=by\n  apply IV.result_clean\n  · simpa [head,Header.result,Parse.cleanRoles,aux,field] using hz\n  · exact hf\n/-- Only actual exhausted buckets promise a fresh temporary candidate tag. -/\ntheorem step_candidate (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool)\n    (hc:before (aux .candidateTag)=[]) (hf:Inner.found b.children target tag=false):\n    step before b tail target tag position (aux .candidateTag)=[]:=by\n  exact IV.result_candidate _ _ _ _ _ (by simpa [head,Header.result,aux] using hc) hf\n/-- Only actual exhausted buckets promise every header/parser destination is fresh again. -/\ntheorem step_headerClean (before:Stack→List Bool) (b:Buckets.Bucket) (tail target tag position:List Bool)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hf:Inner.found b.children target tag=false):\n    ∀k∈Header.cleanRoles,step before b tail target tag position k=[]:=by\n  intro k hk\n  simp only [Header.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl\n  · exact (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n  · exact (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n  · exact IV.result_reader _ _ _ _ _ hf\n  all_goals\n    exact (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n/-- The actual first-hit outcome of the complete physical nested scan. -/\ndef found:List Buckets.Bucket→List Bool→List Bool→Bool\n  | [],_,_=>false\n  | b::bs,target,tag=>if Inner.found b.children target tag=true then true else found bs target tag\n/-- Actual literal found/exhausted search continuation. -/\ndef next (buckets:List Buckets.Bucket) (target tag:List Bool):Label:=\n  if found buckets target tag=true then .local 13 19 else .local 13 31\n/-- Physical outer EOF consumes its real terminator and tests actual EOF. -/\ndef atEOF (before:Stack→List Bool):Stack→List Bool:=Function.update before (aux .outerReader) []\n/-- Full actual short-circuit or physical-EOF bank of the complete search. -/\ndef result:List Buckets.Bucket→(Stack→List Bool)→List Bool→List Bool→List Bool→Stack→List Bool\n  | [],before,_,_,_=>atEOF before\n  | b::bs,before,target,tag,position=>if Inner.found b.children target tag=true then step before b (Buckets.records bs) target tag position\n    else result bs (step before b (Buckets.records bs) target tag position) target tag (IV.finalPosition b.children target tag position)\n/-- Sum only actually executed bucket/child-prefix clocks and two actual final EOF instructions. -/\ndef timeBound:List Buckets.Bucket→List Bool→List Bool→List Bool→Nat\n  | [],_,_,_=>2\n  | b::bs,target,tag,position=>stepTime b target tag position+\n      if Inner.found b.children target tag=true then 0 else timeBound bs target tag (IV.finalPosition b.children target tag position)\n/-- Exact real outer-EOF instructions before copying the computed missing-index answer. -/\ntheorem eof_trace (before:Stack→List Bool) (ho:before (aux .outerReader)=[false]):\n    Runs program 2 (.local 11 28) before (.local 13 31) (atEOF before):=by\n  have h0:=pop_run (.local 11 28) abort (.local 11 29) (.local 11 30) (aux .outerReader) before [false] rfl ho\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  have h1:=peek_run (.local 11 29) (.local 13 31) abort abort (aux .outerReader) (atEOF before) [] rfl (Function.update_self _ _ _)\n  simp only [List.head?_nil,SemiprimeD1StackBytecode.choose] at h1\n  exact join h0 h1\n/-- Whole actual first-index nested search, from real framed bucket bytes alone. -/\ntheorem source_trace (buckets:List Buckets.Bucket) (before:Stack→List Bool) (target tag position:List Bool)\n    (hi:before (aux .outerReader)=Buckets.records buckets)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (htag:before (aux .tagWord)=tag)\n    (hp:before (aux .localPosition)=position) (hcan:before (aux .candidateTag)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound buckets target tag position) (.local 11 28) before (next buckets target tag)\n      (result buckets before target tag position):=by\n  induction buckets generalizing before position with\n  | nil=>simpa only [timeBound,next,found,Bool.false_eq_true,ite_false,result] using eof_trace before hi\n  | cons b bs ih=>\n    have h0:=step_trace before b (Buckets.records bs) target tag position hi hh hz ht htag hp hcan hc ha\n    by_cases hf:Inner.found b.children target tag=true\n    · have h0':Runs program (stepTime b target tag position) (.local 11 28) before (.local 13 19)\n          (step before b (Buckets.records bs) target tag position):=by simpa only [Inner.next,hf,ite_true] using h0\n      simpa [timeBound,result,found,next,hf] using h0'\n    · have hnf:Inner.found b.children target tag=false:=by\n        cases hval:Inner.found b.children target tag with\n        | false=>rfl\n        | true=>exact False.elim (hf hval)\n      have h0':Runs program (stepTime b target tag position) (.local 11 28) before (.local 11 28)\n          (step before b (Buckets.records bs) target tag position):=by simpa only [Inner.next,hf,Bool.false_eq_true,ite_false] using h0\n      let after:=step before b (Buckets.records bs) target tag position\n      have hi':after (aux .outerReader)=Buckets.records bs:=step_outerReader _ _ _ _ _ _\n      have hh':∀k∈Header.cleanRoles,after k=[]:=step_headerClean _ _ _ _ _ _ hh hnf\n      have hz':∀k∈Parse.cleanRoles,after k=[]:=step_clean _ _ _ _ _ _ hz hnf\n      have ht':after (aux .vertexKey)=target:=\n        (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans ht\n      have htag':after (aux .tagWord)=tag:=\n        (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans htag\n      have hp':after (aux .localPosition)=IV.finalPosition b.children target tag position:=step_position _ _ _ _ _ _ hp\n      have hcan':after (aux .candidateTag)=[]:=step_candidate _ _ _ _ _ _ hcan hnf\n      have hc':after (aux .copyScratch)=[]:=\n        (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)).trans hc\n      have ha':∀k,after (arithmetic k)=[]:=by\n        intro k\n        exact (step_other _ _ _ _ _ _ _ (by intro j;fin_cases j <;> simp [Cleanup.role,arithmetic,aux])\n          (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])).trans (ha k)\n      have h1:=ih after (IV.finalPosition b.children target tag position) hi' hh' hz' ht' htag' hp' hcan' hc' ha'\n      have hwhole:=join h0' h1\n      simpa only [timeBound,result,found,hf,Bool.false_eq_true,ite_false,next] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagLoop\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBodyBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBody\n/-! # One complete physical vertex body has a fixed byte/count bound\nThe intermediate bank cap follows this SAME actual left-source execution once.\nAcross later vertices the separate additive row potential is used instead of\nfeeding this local runtime estimate into the next iteration's operands.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBodyBounds\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackProcedureTrace\nnamespace Body\nexport SemiprimeD1StackChildGroupFactoryVertexBody (Ready timeBound left_arithmetic)\nend Body\nnamespace Left\nexport SemiprimeD1StackChildGroupFactoryLeftPortsSource (result timeBound source_trace drained)\nend Left\nnamespace LV\nexport SemiprimeD1StackChildGroupFactoryLeftPortsSourceView (result_other result_fresh drained_fresh)\nend LV\nnamespace Work\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (headerFresh childFresh Fresh)\nend Work\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket records)\nend B\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records)\nend P\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortsBounds (source_time)\nend Old\nnamespace OB\nexport SemiprimeD1StackChildGroupFactoryOldPortOneBounds (pointBytes)\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds (queryBudget)\nend OB\n/-- Actual complete left-scope allowance, including converted ordinal VALUE. -/\ndef leftBudget (cap H D K G:Nat):Nat:=1000000*(cap+G+H+1)*(D+1)*(K+1)\n/-- One fixed formula bounds both actual full source calls and the binary successor. -/\ndef bodyBudget (cap H D K J G:Nat):Nat:=\n  leftBudget cap H D K G+1000000000*\n    (cap+leftBudget cap H D K G+J*(4*D+2)+3*H+OB.queryBudget H D K+D+1)*(J+1)+100*(H+1)\n/-- Ready caller data, not an advised flag, discharges the actual left-source ABI. -/\ntheorem left_trace (before:Stack→List Bool) (buckets:List B.Bucket) (target:List Bool)\n    (hr:Body.Ready before) (hb:before (aux .buckets)=B.records buckets)\n    (ht:before (aux .vertexKey)=target):\n    ∃t≤Left.timeBound before buckets target,\n      Runs program t (.local 9 5) before (.local 11 6) (Left.result before buckets target):=by\n  have hd:=LV.drained_fresh before hr.work\n  have hh:∀k∈SemiprimeD1StackChildGroupFactoryBucketHeader.cleanRoles,before k=[]:=by\n    simpa [Left.drained,SemiprimeD1StackChildGroupFactoryBucketHeader.cleanRoles,aux,field] using Work.headerFresh (Left.drained before) hd\n  have hz:∀k∈SemiprimeD1StackChildGroupFactoryChildParse.cleanRoles,k≠aux .globalPosition→before k=[]:=by\n    intro k hk hn\n    have h:=Work.childFresh (Left.drained before) hd k hk\n    simpa only [Left.drained,Function.update_of_ne hn] using h\n  exact Left.source_trace before buckets target hb (hr.work 0 (by decide)) hh hz ht\n    (hr.work 18 (by decide)) (hr.work 19 (by decide)) hr.arithmetic_clean hr.ordinal_clean\n    hr.portHistory_empty hr.portBank_empty\n/-- SAME actual left-source trace bounds every intermediate stopped physical word. -/\ntheorem left_word_le (before:Stack→List Bool) (buckets:List B.Bucket) (target:List Bool)\n    (cap:Nat) (hc:∀k,(before k).length≤cap) (hr:Body.Ready before)\n    (hb:before (aux .buckets)=B.records buckets) (ht:before (aux .vertexKey)=target):\n    ∀k,(Left.result before buckets target k).length≤cap+Left.timeBound before buckets target:=by\n  obtain ⟨t,htime,hrun⟩:=left_trace before buckets target hr hb ht\n  let start:C.State Stack Label:=⟨some (.local 9 5),none,none,before,[]⟩\n  obtain ⟨finish,hf,hat⟩:=hrun [] start ⟨rfl,rfl,rfl⟩\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program t cap start finish hc hf\n  rw [hat.2.1] at hd\n  intro k\n  exact (hd k).trans (Nat.add_le_add_left htime _)\n/-- Whole actual body budget, with no supplied route, order, scope or output sizes. -/\ntheorem timeBound_le (before:Stack→List Bool) (points:List P.Point) (buckets:List B.Bucket)\n    (target:List Bool) (cap H D G:Nat) (hc:∀k,(before k).length≤cap) (hr:Body.Ready before)\n    (hp:before (aux .oldEndpoints)=P.records points) (hb:before (aux .buckets)=B.records buckets)\n    (ht:before (aux .vertexKey)=target) (hbs:(B.records buckets).length≤H)\n    (hps:(P.records points).length≤H) (htar:target.length≤H)\n    (hd:(buckets.flatMap (fun b=>b.children)).length≤D)\n    (hv:∀p∈buckets.flatMap (fun b=>b.children),SemiprimeBitArithmetic.bitValue p.2≤G):\n    Body.timeBound before points buckets target≤bodyBudget cap H D buckets.length points.length G:=by\n  have hbsCap:(B.records buckets).length≤cap:=by rw [←hb];exact hc _\n  have hleft:=SemiprimeD1StackChildGroupFactoryLeftPortsBounds.source_time before buckets target cap D G hc hbsCap hd hv\n  have hleft':Left.timeBound before buckets target≤leftBudget cap H D buckets.length G:=by\n    apply hleft.trans\n    dsimp only [leftBudget]\n    gcongr\n  have hafter:=left_word_le before buckets target cap hc hr hb ht\n  have hafter':∀k,(Left.result before buckets target k).length≤cap+leftBudget cap H D buckets.length G:=by\n    intro k;exact (hafter k).trans (Nat.add_le_add_left hleft' _)\n  have same (k:Stack) (hn:∀j,SemiprimeD1StackChildGroupFactoryChildCleanup.role j≠k)\n      (he:k≠aux .endpointReader) (ho:k≠aux .outerReader) (hh:k≠aux .portHistory)\n      (hx:∀j,SemiprimeD1StackChildGroupFactoryPortReuse.role false j≠k) (hv:k≠aux .vertexHistory):\n      Left.result before buckets target k=before k:=LV.result_other _ _ _ _ hn he ho hh hx hv\n  have hp':Left.result before buckets target (aux .oldEndpoints)=P.records points:=\n    (same _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hp\n  have hb':Left.result before buckets target (aux .buckets)=B.records buckets:=\n    (same _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hb\n  have ht':Left.result before buckets target (aux .vertexKey)=target:=\n    (same _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans ht\n  have hpsCap:(P.records points).length≤cap+leftBudget cap H D buckets.length G:=by\n    rw [←hp'];exact hafter' _\n  have hold:=Old.source_time (Left.result before buckets target) points buckets target\n    (cap+leftBudget cap H D buckets.length G) H D hafter' (LV.result_fresh _ _ _ hr.work) hpsCap hb' ht'\n    (Body.left_arithmetic _ _ _ hr.arithmetic_clean) hbs\n    (fun p hp=>(SemiprimeD1StackChildGroupFactoryStructuralByteBounds.point_fields points p hp).trans hps) htar hd\n  have hinc:=SemiprimeD1StackChildGroupFactoryOperationBounds.increment_time target\n  change SemiprimeD1StackChildGroupFactoryVertexIncrement.timeBound target≤100*(target.length+1) at hinc\n  dsimp only [Body.timeBound,bodyBudget]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBodyBounds\n","RiemannGaussian.SemiprimeD1StackChildLiftTableInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildLiftTable\n/-! # Exact Entry61 initialization and own bit budget at every actual table leaf -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildLiftTableInput\nopen SemiprimeD1StackChildLiftTable\nopen SemiprimeD1TensorTapeCodec (tape vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nnamespace V\nexport SemiprimeD1StackVectorTableSpec (CheckerTrace checkerInitial)\nend V\n/-- Six actual source words are retained in the template; the assignment role starts EMPTY. -/\ndef original (table order oldAxes oldp newAxes newp : List Bool) : E.Stack→List Bool :=\n  (E.initial table order [] oldAxes oldp newAxes newp).data\n/-- The source's actual physical raw-assignment role is empty before each real reversal. -/\ntheorem raw_empty (table order oldAxes oldp newAxes newp : List Bool) :\n    original table order oldAxes oldp newAxes newp source.raw=[] := rfl\n/-- One physical assignment update changes exactly the intended Entry61 input. -/\ntheorem assignment_update (table order oldAxes oldp newAxes newp raw : List Bool) :\n    Function.update (original table order oldAxes oldp newAxes newp) (E.gather .assignment) raw=\n      (E.initial table order raw oldAxes oldp newAxes newp).data := by\n  funext k\n  rcases k with k|k|k|k|k|k\n  · rfl\n  · rfl\n  · cases k <;> rfl\n  · rfl\n  · rfl\n  · rfl\n/-- The actual copied/reversed leaf entry is the whole physical source's original seven-word front door. -/\ntheorem checker_initial (table order oldAxes oldp newAxes newp raw : List Bool) :\n    V.checkerInitial source (original table order oldAxes oldp newAxes newp) raw=\n      E.initial table order raw oldAxes oldp newAxes newp := by\n  change (⟨some (.local .start),none,none,\n    Function.update (original table order oldAxes oldp newAxes newp) (E.gather .assignment) raw,[]⟩ :\n      SemiprimeD1StackCalls.State E.Stack E.Label)=E.initial table order raw oldAxes oldp newAxes newp\n  rw [assignment_update]\n  rfl\n/-- Every leaf has the SAME own physical input-byte/rank/precision resource, with assignment length charged. -/\ndef budget {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (table : SemiprimeD1TensorTables.Table d) (order : List ℕ) (n : ℕ) : ℕ :=\n  SemiprimeD1StackChildTableEntryClock.wholePolynomial old.axes (extra++old.axes) oldp newp table order\n    (List.replicate n false)\n/-- Only physical assignment length is replaced in this SAME own-source budget. -/\ntheorem budget_exact {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (table : SemiprimeD1TensorTables.Table d) (order : List ℕ) (raw : List Bool) :\n    budget old extra oldp newp table order raw.length=\n      SemiprimeD1StackChildTableEntryClock.wholePolynomial old.axes (extra++old.axes) oldp newp table order raw := by\n  simp only [budget,SemiprimeD1StackChildTableEntryClock.wholePolynomial,\n    SemiprimeD1StackChildTableEntryBounds.resource,List.length_replicate]\n/-- The concrete physical Entry61 proves EVERY leaf trace; no entry evaluator or answer is input. -/\ntheorem source_trace {d : ℕ} (old : SemiprimeD1JetAxes.Context) (ho : old.Positive)\n    (extra : List ℕ) (he : 0<extra.prod) (oldp newp : List Bool)\n    (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (table : SemiprimeD1TensorTables.Table d) (hg : SemiprimeD1TensorTables.Good old table) (order : List ℕ) :\n    V.CheckerTrace source\n      (original (tape table) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp)\n      (fun raw => (SemiprimeD1ChildTableCopyTape.entry old extra (SemiprimeBitArithmetic.bitValue newp) table order raw).words)\n      (budget old extra oldp newp table order) := by\n  intro raw\n  obtain ⟨t,ht,hr,hout,_⟩ := SemiprimeD1StackChildTableEntryOriginal.source_run_original_bounded\n    old ho extra he oldp newp hp table hg order raw\n  refine ⟨t,?_,SemiprimeD1StackChildTableEntryEncoding.done old.axes (extra++old.axes)\n    oldp newp (tape table) (SemiprimeD1StackChildTableEntryPrepare.orderTape order) raw\n      (SemiprimeD1StackChildTableEntryPrepare.selected table raw order),rfl,rfl,?_,hout⟩\n  · rw [budget_exact]\n    exact ht\n  · rw [checker_initial]\n    exact hr\nend RiemannGaussian.SemiprimeD1StackChildLiftTableInput\n","RiemannGaussian.SemiprimeD1StackChildLiftTableResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildLiftTableInput\n/-! # Actual source-byte, acquired-rank and precision-VALUE caps for whole child tables\nThe resource includes the original table/order/header bytes, physically paid\nrank and precision VALUES and actual scope bytes. No child answer, native\nruntime or recursively enlarged elapsed-clock width supplies a resource.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildLiftTableResources\nopen SemiprimeD1StackChildLiftTable\nopen SemiprimeD1TensorTapeCodec (tape vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nnamespace Input\nexport SemiprimeD1StackChildLiftTableInput (original budget)\nend Input\n/-- Fixed physical resource: source bytes and actual acquired dimension VALUES plus scope tape bytes. -/\ndef resource {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) : ℕ :=\n  SemiprimeD1StackChildTableEntryBounds.resource old.axes (extra++old.axes) oldp newp parent order []+\n    (vectorBits scope).length\n/-- Every actual source resource includes its own positive constant overhead. -/\ntheorem resource_pos {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) :\n    1≤resource old extra oldp newp parent order scope := by\n  unfold resource SemiprimeD1StackChildTableEntryBounds.resource\n  omega\n/-- Physically counting scope records pays arity by actual tape bytes, including empty zero-ID fields. -/\ntheorem scope_le {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) :\n    scope.length≤resource old extra oldp newp parent order scope :=\n  (SemiprimeD1StackVectorTableBounds.scope_count_le scope).trans (Nat.le_add_left _ _)\n/-- All61 original-template roles are physically counted, including all empty private shadows. -/\ntheorem template_bytes {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) :\n    SemiprimeD1StackVectorTableSpec.inputBytes\n      (Input.original (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp)≤\n      61*resource old extra oldp newp parent order scope := by\n  have h (k : E.Stack) := SemiprimeD1StackChildTableEntryStorage.initial_length old.axes (extra++old.axes)\n    oldp newp parent order [] k\n  have hb (k : E.Stack) :\n      (Input.original (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp k).length≤\n      resource old extra oldp newp parent order scope := (h k).trans (Nat.le_add_right _ _)\n  unfold SemiprimeD1StackVectorTableSpec.inputBytes\n  calc\n    _≤∑_k : E.Stack,resource old extra oldp newp parent order scope := Finset.sum_le_sum (fun k _ => hb k)\n    _=_ := by simp only [Finset.sum_const,Finset.card_univ,E.stack_card,smul_eq_mul]\n/-- EVERY actual assignment has one fixed quadratic Entry61 budget in the same physically paid resource. -/\ntheorem entry_budget {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) :\n    Input.budget old extra oldp newp parent order scope.length≤10^8*(resource old extra oldp newp parent order scope)^2 := by\n  have hn := SemiprimeD1StackVectorTableBounds.scope_count_le scope\n  have hres : SemiprimeD1StackChildTableEntryBounds.resource old.axes (extra++old.axes) oldp newp parent order\n      (List.replicate scope.length false)≤resource old extra oldp newp parent order scope := by\n    unfold resource SemiprimeD1StackChildTableEntryBounds.resource\n    simp only [List.length_replicate,List.length_nil]\n    omega\n  exact Nat.mul_le_mul_left (10^8) (Nat.pow_le_pow_left hres 2)\nend RiemannGaussian.SemiprimeD1StackChildLiftTableResources\n","RiemannGaussian.SemiprimeD1StackChildLiftTableStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildLiftTableBounds\n/-! # ALL134 whole child-table roles and genuine DFS return cells at every prefix\nThe original table/header/order template and actual scope are acquired caller\noperands. This is a prepared machine configuration, not an N-only initList.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildLiftTableStorage\nopen SemiprimeD1StackChildLiftTable\nopen SemiprimeD1TensorTapeCodec (tape vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nnamespace R\nexport SemiprimeD1StackChildLiftTableResources (resource resource_pos template_bytes)\nend R\nnamespace O\nexport SemiprimeD1StackChildLiftTableOriginal (original answer done timeBound)\nend O\n/-- One fixed whole physical-space bound precedes the entire table/context/scope family. -/\ndef spacePolynomial {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) : ℕ :=\n  10^24*(R.resource old extra oldp newp parent order scope)^2*2^scope.length\n/-- Whole source/runtime and actually initialized bytes jointly pay ALL134 data words and real returns. -/\ntheorem cells_le {d : ℕ} (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (oldp newp : List Bool)\n    (parent : SemiprimeD1TensorTables.Table d) (order : List ℕ) (scope : List (List Bool)) :\n    135*(SemiprimeD1StackVectorTableSpec.inputBytes (O.original old extra oldp newp parent order)+\n      (vectorBits scope).length+O.timeBound old extra oldp newp parent order scope+1)≤\n      spacePolynomial old extra oldp newp parent order scope := by\n  let r := R.resource old extra oldp newp parent order scope\n  let e := 2^scope.length\n  have hr : 1≤r := R.resource_pos old extra oldp newp parent order scope\n  have he : 1≤e := Nat.one_le_pow _ _ (by decide : 1≤(2 : ℕ))\n  have hp : r≤r^2 := Nat.le_pow (by decide : 0<2)\n  have hpay : r^2≤r^2*e := by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (r^2) he\n  have hi := R.template_bytes old extra oldp newp parent order scope\n  change SemiprimeD1StackVectorTableSpec.inputBytes (O.original old extra oldp newp parent order)≤61*r at hi\n  have hi' := hi.trans (Nat.mul_le_mul_left 61 (hp.trans hpay))\n  have hs : (vectorBits scope).length≤r := Nat.le_add_left _ _\n  have hs' := hs.trans (hp.trans hpay)\n  have h1 := hr.trans (hp.trans hpay)\n  have ht := SemiprimeD1StackChildLiftTableBounds.timeBound_le old extra oldp newp parent order scope\n  have ht' : O.timeBound old extra oldp newp parent order scope≤10^20*(r^2*e) := by\n    simpa only [SemiprimeD1StackChildLiftTableBounds.polynomial,Nat.mul_assoc] using ht\n  unfold spacePolynomial\n  rw [Nat.mul_assoc]\n  change _≤10^24*(r^2*e)\n  omega\n/-- EVERY genuine same-source primitive prefix counts both full61-role banks and all real recursive returns. -/\ntheorem prefix_cells {d : ℕ} (old : SemiprimeD1JetAxes.Context) (ho : old.Positive)\n    (extra : List ℕ) (he : 0<extra.prod) (oldp newp : List Bool)\n    (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (parent : SemiprimeD1TensorTables.Table d) (hg : SemiprimeD1TensorTables.Good old parent)\n    (order : List ℕ) (scope : List (List Bool)) (fuel : ℕ)\n    (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel\n      (initial (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp (vectorBits scope))=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤ spacePolynomial old extra oldp newp parent order scope := by\n  have h := SemiprimeD1StackVectorTableBounds.prefix_cells source\n    (O.original old extra oldp newp parent order) (SemiprimeD1StackChildLiftTableInput.raw_empty _ _ _ _ _ _)\n    (O.answer old extra newp parent order) (SemiprimeD1StackChildLiftTableInput.budget old extra oldp newp parent order)\n    (SemiprimeD1StackChildLiftTableInput.source_trace old ho extra he oldp newp hp parent hg order) scope fuel out hr\n  rw [E.stack_card] at h\n  exact h.trans (cells_le old extra oldp newp parent order scope)\n/-- All actual compiled prefix stacks include every source/template/shadow/counter/tree word and actual return cell. -/\ntheorem machine_prefix_cells {d : ℕ} (old : SemiprimeD1JetAxes.Context) (ho : old.Positive)\n    (extra : List ℕ) (he : 0<extra.prod) (oldp newp : List Bool)\n    (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (parent : SemiprimeD1TensorTables.Table d) (hg : SemiprimeD1TensorTables.Good old parent)\n    (order : List ℕ) (scope : List (List Bool)) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun c => c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n          (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp (vectorBits scope))))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤ spacePolynomial old extra oldp newp parent order scope := by\n  have heq := SemiprimeD1StackCalls.run_correct (SemiprimeD1StackVectorTable.counter .bank)\n    (SemiprimeD1StackVectorTable.aux .output) .start program fuel\n    (initial (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n      (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp (vectorBits scope))\n  have hh := heq.trans hr\n  cases hout : SemiprimeD1StackCalls.run program fuel\n      (initial (tape parent) (SemiprimeD1StackChildTableEntryPrepare.orderTape order)\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp (vectorBits scope)) with\n  | none => rw [hout] at hh;cases hh\n  | some out =>\n    rw [hout] at hh\n    have hcfg : cfg=SemiprimeD1StackCalls.configuration out := (Option.some.inj hh).symm\n    subst cfg\n    exact prefix_cells old ho extra he oldp newp hp parent hg order scope fuel out hout\nend RiemannGaussian.SemiprimeD1StackChildLiftTableStorage\n","RiemannGaussian.SemiprimeD1StackChildLiftVertexMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildLiftVertexStorage\nimport RiemannGaussian.SemiprimeD1ChildTableDirect\nimport RiemannGaussian.SemiprimeD1ChildOldEntrySemantics\n/-! # The actual active old vertex needs neither aligned-table nor canonical-recopy acquisition\nBoth original metadata lengths are derived from the actual child acquisitions.\nThe full native vertex/record is preserved; no native clock is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildLiftVertexMeaning\nopen SemiprimeD1StackChildLiftVertexOriginal\nopen SemiprimeD1TensorNetwork (Network leftPorts)\nopen SemiprimeD1ChildOldEntrySemantics (data order)\n/-- Generic actual active source loses neither a coefficient nor a canonical port when the two intermediates are removed. -/\ntheorem active_vertex {a : ℕ} (net : Network) (pulled : SemiprimeD1ChildNetwork.Pullback net a)\n    (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (newp : List Bool)\n    (v : Fin (net.leftCount+net.rows.length))\n    (ha : (pulled.activation.bits[v.val]?).getD false=true)\n    (hc : (leftPorts (SemiprimeD1TensorNetworkLayout.childRows pulled.graph) v).length=\n      (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) pulled v).child.length) :\n    (SemiprimeD1ChildNetworkTape.leftOne net pulled old extra (SemiprimeBitArithmetic.bitValue newp) v).1=\n      vertex old extra newp (SemiprimeD1ChildNetwork.parentVertex net v).table\n        (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) pulled v).order\n        (leftPorts (SemiprimeD1TensorNetworkLayout.childRows pulled.graph) v) := by\n  dsimp only [SemiprimeD1ChildNetworkTape.leftOne,SemiprimeD1ChildTensorTablesTape.fromCache]\n  rw [ha]\n  exact SemiprimeD1ChildTableDirect.copy_lift_aligned old extra (SemiprimeBitArithmetic.bitValue newp)\n    (SemiprimeD1ChildNetwork.parentVertex net v).table\n    (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) pulled v).order\n    (leftPorts (SemiprimeD1TensorNetworkLayout.childRows pulled.graph) v) _ _\n    (SemiprimeD1ChildTableOrder.order_length _ _ _) hc\n/-- Actual original-family lengths discharge the generic degree condition, including empty/isolated vertices. -/\ntheorem original_active_vertex (net : Network) (r a : ℕ) [NeZero r] (q : Fin a) (g : Fin r)\n    (old : SemiprimeD1JetAxes.Context) (extra : List ℕ) (newp : List Bool)\n    (v : Fin (net.leftCount+net.rows.length))\n    (ha : ((data net r a q g).activation.bits[v.val]?).getD false=true) :\n    (SemiprimeD1ChildNetworkTape.leftOne net (data net r a q g) old extra (SemiprimeBitArithmetic.bitValue newp) v).1=\n      vertex old extra newp (SemiprimeD1ChildNetwork.parentVertex net v).table (order net r a q g v).order\n        (leftPorts (SemiprimeD1TensorNetworkLayout.childRows (data net r a q g).graph) v) :=\n  active_vertex net (data net r a q g) old extra newp v ha\n    (SemiprimeD1ChildOldEntrySemantics.child_length net r a q g v)\n/-- SAME physical source writes the ENTIRE actual native active child record, from original parent and actual routing operands. -/\ntheorem source_run_actual (net : Network) (r a : ℕ) [NeZero r] (q : Fin a) (g : Fin r)\n    (old : SemiprimeD1JetAxes.Context) (ho : old.Positive) (extra : List ℕ) (he : 0<extra.prod)\n    (oldp newp : List Bool) (hp : SemiprimeBitArithmetic.bitValue oldp=old.precision)\n    (hg : SemiprimeD1TensorNetwork.Good old net) (v : Fin (net.leftCount+net.rows.length))\n    (ha : ((data net r a q g).activation.bits[v.val]?).getD false=true) :\n    let parent:=(SemiprimeD1ChildNetwork.parentVertex net v).table\n    let permutation:=(order net r a q g v).order\n    let ports:=leftPorts (SemiprimeD1TensorNetworkLayout.childRows (data net r a q g).graph) v\n    ∃t≤SemiprimeD1StackChildLiftVertexBounds.polynomial old extra oldp newp parent permutation ports,\n      SemiprimeD1StackCalls.run SemiprimeD1StackChildLiftVertex.program t\n        (originalInitial old extra oldp newp parent permutation ports)=some (done old extra oldp newp parent permutation ports) ∧\n      (done old extra oldp newp parent permutation ports).data (SemiprimeD1StackChildLiftVertex.aux .record)=\n        SemiprimeD1StackVertexProduct.records\n          [(SemiprimeD1ChildNetworkTape.leftOne net (data net r a q g) old extra (SemiprimeBitArithmetic.bitValue newp) v).1] := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackChildLiftVertexBounds.source_run_bounded old ho extra he oldp newp hp\n    (SemiprimeD1ChildNetwork.parentVertex net v).table (SemiprimeD1ChildNetwork.parentVertex_good old net hg v)\n    (order net r a q g v).order (leftPorts (SemiprimeD1TensorNetworkLayout.childRows (data net r a q g).graph) v)\n  refine ⟨t,ht,hr,?_⟩\n  rw [original_active_vertex net r a q g old extra newp v ha]\n  rfl\nend RiemannGaussian.SemiprimeD1StackChildLiftVertexMeaning\n","RiemannGaussian.SemiprimeD1StackChildTableEntryBackend":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryView\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryPrimitives\n/-! # Real ordered physical gather and actual serialized parent table lookup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildTableEntryBackend\nopen SemiprimeD1StackChildTableEntry SemiprimeD1StackChildTableEntryEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend Link\nlocal notation \"ctl\"=>Label.local\n/-- Actual gather reads the paid physical unary-index vector and retains the whole original assignment. -/\ntheorem gather_call (assignment:List Bool) (indices:List (List Bool)) (old child:J.Stack→List Bool)\n    (t:T.Stack→List Bool) (r:R.Stack→List Bool) (a:Aux→List Bool):\n    ∃q ≤ SemiprimeD1StackGatherBytecode.budget assignment.length (vectorBits indices).length+1,\n      Runs program q (ctl .gather)\n        (bank old child (G.contents (vectorBits indices) assignment [] [] [] []) t r a) (ctl .copyTable)\n        (bank old child (G.contents [] assignment [] [] [] (SemiprimeD1StackBitGather.values assignment indices)) t r a):=by\n  let start:SemiprimeD1StackBytecode.State G.Stack G.Label:=\n    ⟨some G.entry,none,G.contents (vectorBits indices) assignment [] [] [] []⟩\n  let stop:SemiprimeD1StackBytecode.State G.Stack G.Label:=\n    ⟨none,none,G.contents [] assignment [] [] [] (SemiprimeD1StackBitGather.values assignment indices)⟩\n  have hin:Link.DataRel gather (bank old child start.store t r a) start.store (bank old child start.store t r a):=⟨fun _=>rfl,fun _ _=>rfl⟩\n  have hout:Link.DataRel gather (bank old child start.store t r a) stop.store (bank old child stop.store t r a):=by\n    constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k|k|k|k|k\n      · rfl\n      · rfl\n      · exact False.elim (hk k rfl)\n      · rfl\n      · rfl\n      · rfl\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackGatherBytecode.gather_run assignment indices [] []\n  have hrun:SemiprimeD1StackBytecode.run G.code q start=some stop:=by simpa only [List.append_nil] using hr\n  exact ⟨q+1,by omega,included_call program gather Label.gather gather_injective G.code G.entry (fun _=>rfl)\n    (ctl .gather) (ctl .copyTable) rfl q start stop _ _ rfl rfl hrun hin hout⟩\n/-- Actual serialized tree read consumes DIRECT gathered path bits, scans all skipped subtrees and acquires every original coefficient byte. -/\ntheorem tree_call {d:Nat} (table:SemiprimeD1TensorTables.Table d) (path assignment:List Bool)\n    (old child:J.Stack→List Bool) (r:R.Stack→List Bool) (a:Aux→List Bool):\n    ∃q ≤ SemiprimeD1StackTreeBytecode.budget (tape table).length+1,\n      Runs program q (ctl .lookup)\n        (bank old child (G.contents [] assignment [] [] [] path) (T.contents (tape table) [] [] [] []) r a) (ctl .copyEntry)\n        (bank old child (G.contents [] assignment [] [] [] (path.drop d))\n          (T.contents [] [] [] [] (vectorBits (SemiprimeD1TensorTables.lookup table path).words)) r a):=by\n  let start:SemiprimeD1StackBytecode.State T.Stack T.Label:=⟨some T.entry,none,T.contents (tape table) [] path [] []⟩\n  let stop:SemiprimeD1StackBytecode.State T.Stack T.Label:=\n    ⟨none,none,T.contents [] [] (path.drop d) [] (vectorBits (SemiprimeD1TensorTables.lookup table path).words)⟩\n  let before:=bank old child (G.contents [] assignment [] [] [] path) (T.contents (tape table) [] [] [] []) r a\n  let after:=bank old child (G.contents [] assignment [] [] [] (path.drop d))\n    (T.contents [] [] [] [] (vectorBits (SemiprimeD1TensorTables.lookup table path).words)) r a\n  have hin:Link.DataRel tree before start.store before:=by\n    constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  have hout:Link.DataRel tree before stop.store after:=by\n    constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k|k|k|k|k\n      · rfl\n      · rfl\n      · cases k with\n        | output=>exact False.elim (hk .path rfl)\n        | input|assignment|reader|scratch|accumulator=>rfl\n      · cases k with\n        | path=>rfl\n        | input=>exact False.elim (hk .input rfl)\n        | tasks=>exact False.elim (hk .tasks rfl)\n        | scratch=>exact False.elim (hk .scratch rfl)\n        | output=>exact False.elim (hk .output rfl)\n      · rfl\n      · rfl\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackTreeBytecode.tree_run table path []\n  have hrun:SemiprimeD1StackBytecode.run T.code q start=some stop:=by simpa only [List.append_nil] using hr\n  exact ⟨q+1,by omega,included_call program tree Label.tree tree_injective T.code T.entry (fun _=>rfl)\n    (ctl .lookup) (ctl .copyEntry) rfl q start stop before after rfl rfl hrun hin hout⟩\nend RiemannGaussian.SemiprimeD1StackChildTableEntryBackend\n","RiemannGaussian.SemiprimeD1StackChildTableEntryContexts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryView\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryPrimitives\n/-! # Real acquisition of both retained original context banks -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildTableEntryContexts\nopen SemiprimeD1StackChildTableEntry SemiprimeD1StackChildTableEntryEncoding\nopen SemiprimeD1StackChildTableEntryView SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend Link\nlocal notation \"ctl\"=>Label.local\n/-- Complete actual old context acquisition preserves every other physical field and all genuine outer returns. -/\ntheorem old_call (axes:List Nat) (hp:∀q∈axes,0<q) (p:List Bool)\n    (child:J.Stack→List Bool) (g:G.Stack→List Bool) (t:T.Stack→List Bool) (r:R.Stack→List Bool) (a:Aux→List Bool):\n    ∃q ≤ SemiprimeD1StackJetContextCorrectness.budget axes p+1,Runs program q (ctl .start)\n      (bank (J.initial (vectorBits (axes.map unary)) p).data child g t r a) (ctl .childContext) (bank (Context.finalData axes p) child g t r a):=by\n  let start:=J.initial (vectorBits (axes.map unary)) p\n  let stop:C.State J.Stack J.Label:=⟨none,none,none,Context.finalData axes p,[]⟩\n  have hin:Link.DataRel (context false) (bank (J.initial (vectorBits (axes.map unary)) p).data child g t r a) start.data (bank (J.initial (vectorBits (axes.map unary)) p).data child g t r a):=by\n    constructor\n    · intro k;rfl\n    · intro k _;rfl\n  have hout:Link.DataRel (context false) (bank (J.initial (vectorBits (axes.map unary)) p).data child g t r a) stop.data (bank (Context.finalData axes p) child g t r a):=by\n    constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k|k|k|k|k\n      · exact False.elim (hk k rfl)\n      · rfl\n      · rfl\n      · rfl\n      · rfl\n      · rfl\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackJetContextCorrectness.source_run axes hp p\n  refine ⟨q+1,by omega,?_⟩\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program (context false) (Label.context false)\n    (context_injective false) J.program .start (fun _=>rfl) (ctl .start) (ctl .childContext) rfl\n    q start stop _ _ rfl rfl rfl rfl hr hin hout\n/-- Complete actual child context acquisition preserves every other physical field and all genuine outer returns. -/\ntheorem child_call (axes:List Nat) (hp:∀q∈axes,0<q) (p:List Bool)\n    (old:J.Stack→List Bool) (g:G.Stack→List Bool) (t:T.Stack→List Bool) (r:R.Stack→List Bool) (a:Aux→List Bool):\n    ∃q ≤ SemiprimeD1StackJetContextCorrectness.budget axes p+1,Runs program q (ctl .childContext)\n      (bank old (J.initial (vectorBits (axes.map unary)) p).data g t r a) (ctl .ready) (bank old (Context.finalData axes p) g t r a):=by\n  let start:=J.initial (vectorBits (axes.map unary)) p\n  let stop:C.State J.Stack J.Label:=⟨none,none,none,Context.finalData axes p,[]⟩\n  have hin:Link.DataRel (context true) (bank old (J.initial (vectorBits (axes.map unary)) p).data g t r a) start.data (bank old (J.initial (vectorBits (axes.map unary)) p).data g t r a):=by\n    constructor\n    · intro k;rfl\n    · intro k _;rfl\n  have hout:Link.DataRel (context true) (bank old (J.initial (vectorBits (axes.map unary)) p).data g t r a) stop.data (bank old (Context.finalData axes p) g t r a):=by\n    constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k|k|k|k|k\n      · rfl\n      · exact False.elim (hk k rfl)\n      · rfl\n      · rfl\n      · rfl\n      · rfl\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackJetContextCorrectness.source_run axes hp p\n  refine ⟨q+1,by omega,?_⟩\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program (context true) (Label.context true)\n    (context_injective true) J.program .start (fun _=>rfl) (ctl .childContext) (ctl .ready) rfl\n    q start stop _ _ rfl rfl rfl rfl hr hin hout\nend RiemannGaussian.SemiprimeD1StackChildTableEntryContexts\n","RiemannGaussian.SemiprimeD1StackChildTableEntryOld":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryRows\n/-! # Entire original-coefficient loop, preserving every coordinate and its order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildTableEntryOld\nopen SemiprimeD1StackChildTableEntry SemiprimeD1StackChildTableEntryEncoding\nopen SemiprimeD1StackChildTableEntryView SemiprimeD1StackChildTableEntryPrimitives\nopen SemiprimeD1StackChildTableEntryScalar SemiprimeD1StackChildTableEntryFields SemiprimeD1StackChildTableEntryRows\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nlocal notation \"ctl\"=>Label.local\n/-- Exact sum of actual old-coefficient row costs and the three final physical EOF checks. -/\ndef budget (p:List Bool):List (List Bool)→Nat\n  | []=>3\n  | word::rest=>rowTime word p+budget p rest\n/-- Actual vector terminator pop, actual inputEOF peek and actual exhausted-old-rank peek. -/\ntheorem empty_run (old child:J.Stack→List Bool) (assignment path table order entry remaining hist:List Bool):\n    Runs program 3 (ctl .header) (state old child assignment path table order entry [false] [] remaining hist)\n      (ctl .zeros) (state old child assignment path table order entry [] [] remaining hist):=by\n  let w:=loopWords table order entry [] remaining hist\n  have h0:=pop_run .header (ctl .abort) (ctl .inputEOF) (ctl .parse) (tree .output)\n    (view old child assignment path [false] w) [false] rfl rfl\n  change Runs program 1 _ _ _ (Function.update (view old child assignment path [false] w) (treeAllocation .output) []) at h0\n  dsimp only [view] at h0\n  rw [update_tree,tree_reader] at h0\n  have h1:=peek_run .inputEOF (ctl .oldEOF) (ctl .abort) (ctl .abort) (tree .output)\n    (view old child assignment path [] w) [] rfl rfl\n  have h2:=peek_run .oldEOF (ctl .zeros) (ctl .abort) (ctl .abort) (aux .oldRemaining)\n    (view old child assignment path [] w) [] rfl rfl\n  exact join (join h0 h1) h2\n/-- Every old coordinate is parsed and individually reduced; no aggregate lift or coefficient truncation occurs. -/\ntheorem old_run (old child:J.Stack→List Bool) (assignment path table order entry hist p:List Bool)\n    (ws:List (List Bool)) (zeros:Nat) (hp:child J.precisionBits=p):\n    Runs program (budget p ws) (ctl .header)\n      (state old child assignment path table order entry (vectorBits ws) (unary ws.length) (unary (ws.length+zeros)) hist)\n      (ctl .zeros) (state old child assignment path table order entry [] [] (unary zeros)\n        ((history (ws.map (fun word=>SR.result word p))).reverse++hist)):=by\n  induction ws generalizing hist with\n  | nil=>simpa only [budget,List.map_nil,history,List.flatMap_nil,List.reverse_nil,List.nil_append,vectorBits,List.length_nil,Nat.zero_add,unary,List.replicate_zero] using\n      empty_run old child assignment path table order entry (unary zeros) hist\n  | cons word ws ih=>\n    have h0:=row_run old child assignment path table order entry word (vectorBits ws) (unary ws.length)\n      (unary (ws.length+zeros)) hist p hp\n    have h1:=ih ((row (SR.result word p)).reverse++hist)\n    have he:unary ((word::ws).length+zeros)=true::unary (ws.length+zeros):=by\n      rw [show (word::ws).length+zeros=(ws.length+zeros)+1 by simp only [List.length_cons];omega]\n      rfl\n    rw [he]\n    have h:=join h0 h1\n    simpa only [budget,List.map_cons,history,List.flatMap_cons,List.reverse_append,List.append_assoc,vectorBits,List.length_cons,unary,List.replicate_succ] using h\nend RiemannGaussian.SemiprimeD1StackChildTableEntryOld\n","RiemannGaussian.SemiprimeD1StackChildTableEntryStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryClock\n/-! # All61 actual Boolean roles and genuine return cells at every prefix\nThe actual cached ranks/precision marker VALUES remain explicit resources.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildTableEntryStorage\nopen SemiprimeD1StackChildTableEntry SemiprimeD1StackChildTableEntryEncoding\nopen SemiprimeD1StackChildTableEntryPrepare SemiprimeD1StackChildTableEntryExecution\nopen SemiprimeD1StackChildTableEntryBounds SemiprimeD1StackChildTableEntryClock\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Every physically acquired context role is one of its actual retained header/precision/rank/width words, or empty. -/\ntheorem context_length (axes:List Nat) (p:List Bool) (k:J.Stack):\n    (Context.finalData axes p k).length    ≤   (vectorBits (axes.map unary)).length+p.length+axes.prod+bitValue p+1:=by\n  rcases k with k|k\n  · cases k <;> simp_all [Context.finalData,SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContextExecution.ready,\n      SemiprimeD1StackJetSuffix.data,unary]\n    omega\n  · rcases k with k|k\n    · cases k <;> simp_all [Context.finalData,SemiprimeD1StackJetContext.bank,SemiprimeD1StackAdder.store,\n        SemiprimeD1StackUnaryCounterExecution.markers]\n      omega\n    · fin_cases k <;> simp_all [Context.finalData,SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContext.cached] <;> omega\n/-- The whole front door has only actual axis headers/binary precision in its context allocations. -/\ntheorem context_initial_length (axes p:List Bool) (k:J.Stack):\n    ((J.initial axes p).data k).length    ≤   axes.length+p.length+1:=by\n  rcases k with k|k\n  · exact Nat.zero_le _\n  · rcases k with k|k\n    · exact Nat.zero_le _\n    · fin_cases k <;> simp_all [SemiprimeD1StackJetContext.initial,SemiprimeD1StackJetContext.bank,\n        SemiprimeD1StackJetContext.cached] <;> omega\n/-- All seven actual source operands, no rank/cache answers, are counted before whole acquisition. -/\ntheorem initial_length {d:Nat} (oldAxes newAxes:List Nat) (oldp newp:List Bool)\n    (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool) (k:Stack):\n    ((initial (tape table) (orderTape order) assignment (vectorBits (oldAxes.map unary)) oldp\n      (vectorBits (newAxes.map unary)) newp).data k).length    ≤   resource oldAxes newAxes oldp newp table order assignment:=by\n  let S:=resource oldAxes newAxes oldp newp table order assignment\n  change _    ≤   S\n  rcases k with k|k|k|k|k|k\n  · exact (context_initial_length _ _ k).trans (by dsimp [S,resource];omega)\n  · exact (context_initial_length _ _ k).trans (by dsimp [S,resource];omega)\n  · cases k <;> first | exact Nat.zero_le _ | change assignment.length    ≤   S;dsimp [S,resource];omega\n  · cases k <;> exact Nat.zero_le _\n  · cases k <;> exact Nat.zero_le _\n  · cases k <;> first | exact Nat.zero_le _ | change (tape table).length    ≤   S;dsimp [S,resource];omega | change (orderTape order).length    ≤   S;dsimp [S,resource];omega\n/-- The exact ready bank counts all30 already acquired context fields, including their VALUE-materialized rank and precision words. -/\ntheorem ready_length {d:Nat} (oldAxes newAxes:List Nat) (oldp newp:List Bool)\n    (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool) (k:Stack):\n    ((ready oldAxes newAxes oldp newp (tape table) (orderTape order) assignment).data k).length    ≤\n      resource oldAxes newAxes oldp newp table order assignment:=by\n  let S:=resource oldAxes newAxes oldp newp table order assignment\n  change _    ≤   S\n  rcases k with k|k|k|k|k|k\n  · exact (context_length _ _ k).trans (by dsimp [S,resource];omega)\n  · exact (context_length _ _ k).trans (by dsimp [S,resource];omega)\n  · cases k <;> first | exact Nat.zero_le _ | change assignment.length    ≤   S;dsimp [S,resource];omega\n  · cases k <;> exact Nat.zero_le _\n  · cases k <;> exact Nat.zero_le _\n  · cases k <;> first | exact Nat.zero_le _ | change (tape table).length    ≤   S;dsimp [S,resource];omega | change (orderTape order).length    ≤   S;dsimp [S,resource];omega\n/-- Deterministic final halt bounds every reached prefix of the same whole source. -/\ntheorem source_prefix_fuel {d:Nat} (oldAxes newAxes:List Nat) (ho:∀q∈oldAxes,0<q) (hn:∀q∈newAxes,0<q)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod   ≤   newAxes.prod)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (initial (tape table) (orderTape order) assignment\n      (vectorBits (oldAxes.map unary)) oldp (vectorBits (newAxes.map unary)) newp)=some out):\n    fuel    ≤   wholePolynomial oldAxes newAxes oldp newp table order assignment:=by\n  obtain ⟨t,ht,hstop⟩:=source_run_bounded oldAxes newAxes ho hn oldp newp table order assignment hs hr\n  have hf:fuel    ≤   t:=by\n    by_contra h\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hp\n    have hz:SemiprimeD1StackCalls.run program 1 (done oldAxes newAxes oldp newp (tape table) (orderTape order) assignment (selected table assignment order))=none:=rfl\n    rw [hz,Option.bind_none] at hp\n    cases hp\n  exact hf.trans ht\n/-- Deterministic same-program ready halt bounds every reached ready prefix, without any acquisition replay. -/\ntheorem ready_prefix_fuel {d:Nat} (oldAxes newAxes:List Nat) (ho:0<oldAxes.prod) (hn:0<newAxes.prod)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod   ≤   newAxes.prod)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (ready oldAxes newAxes oldp newp (tape table) (orderTape order) assignment)=some out):\n    fuel    ≤   readyPolynomial oldAxes newAxes oldp newp table order assignment:=by\n  obtain ⟨t,ht,hstop⟩:=ready_run_bounded oldAxes newAxes ho hn oldp newp table order assignment hs hr\n  have hf:fuel    ≤   t:=by\n    by_contra h\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hp\n    have hz:SemiprimeD1StackCalls.run program 1 (done oldAxes newAxes oldp newp (tape table) (orderTape order) assignment (selected table assignment order))=none:=rfl\n    rw [hz,Option.bind_none] at hp\n    cases hp\n  exact hf.trans ht\n/-- Sum ALL61 physical roles before instantiating any large concrete original state. -/\ntheorem word_sum (words:Stack→List Bool) (cap:Nat) (h:∀k,(words k).length   ≤  cap):\n    (∑k:Stack,(words k).length)   ≤  61*cap:=by\n  calc\n    _   ≤  ∑_k:Stack,cap:=Finset.sum_le_sum (fun k _=>h k)\n    _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n/-- Generic SAME-program physical prefix lemma abstracts source arguments before all-state elaboration. -/\ntheorem prefix_cells_at (S fuel:Nat) (before out:C.State Stack Label)\n    (hd:∀k,(before.data k).length   ≤  S) (hf:before.frames=[])\n    (ht:fuel   ≤  100000000*S^2) (hp:SemiprimeD1StackCalls.run program fuel before=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length   ≤  100000000000*S^2:=by\n  have hdata:=SemiprimeD1StackReturnLink.run_data_bound program fuel S before out hd hp\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel before out hp\n  rw [hf,List.length_nil] at hframes\n  have hs:=word_sum out.data (S+fuel) hdata\n  have h2:S  ≤  S^2:=Nat.le_pow (by decide:0<(2:Nat))\n  omega\n/-- Every whole-source prefix counts all61 data roles INCLUDING the unused shadow and all genuine saved return labels. -/\ntheorem prefix_cells {d:Nat} (oldAxes newAxes:List Nat) (ho:∀q∈oldAxes,0<q) (hn:∀q∈newAxes,0<q)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod  ≤  newAxes.prod)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (initial (tape table) (orderTape order) assignment\n      (vectorBits (oldAxes.map unary)) oldp (vectorBits (newAxes.map unary)) newp)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length   ≤  100000000000*(resource oldAxes newAxes oldp newp table order assignment)^2:=by\n  exact prefix_cells_at _ fuel _ out (initial_length oldAxes newAxes oldp newp table order assignment) rfl\n    (source_prefix_fuel oldAxes newAxes ho hn oldp newp table order assignment hs hr fuel out hp) hp\n/-- Same ready-prefix bound includes all acquired caches, every private/shadow word and every real return cell. -/\ntheorem ready_prefix_cells {d:Nat} (oldAxes newAxes:List Nat) (ho:0<oldAxes.prod) (hn:0<newAxes.prod)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod  ≤  newAxes.prod)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hp:SemiprimeD1StackCalls.run program fuel (ready oldAxes newAxes oldp newp (tape table) (orderTape order) assignment)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length   ≤  100000000000*(resource oldAxes newAxes oldp newp table order assignment)^2:=by\n  have ht:=ready_prefix_fuel oldAxes newAxes ho hn oldp newp table order assignment hs hr fuel out hp\n  have ht':fuel  ≤  100000000*(resource oldAxes newAxes oldp newp table order assignment)^2:=by\n    unfold readyPolynomial at ht\n    omega\n  exact prefix_cells_at _ fuel _ out (ready_length oldAxes newAxes oldp newp table order assignment) rfl ht' hp\n/-- Generic exact compiler projection is proved before instantiating original context/table arguments. -/\ntheorem machine_cells_at (bound fuel:Nat) (before:C.State Stack Label) (cfg:machine.Cfg)\n    (hp:(fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration before))=some cfg)\n    (hc:∀out,SemiprimeD1StackCalls.run program fuel before=some out→\n      (∑k:Stack,(out.data k).length)+out.frames.length  ≤ bound):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length  ≤ bound:=by\n  have he:=SemiprimeD1StackCalls.run_correct (aux .parentTable) (aux .output) (Label.local .start) program fuel before\n  have hh:=he.trans hp\n  cases hout:SemiprimeD1StackCalls.run program fuel before with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact hc out hout\n/-- Every genuine compiled whole-source prefix counts all61 roles and the actual none-labelled return stack. -/\ntheorem machine_prefix_cells {d:Nat} (oldAxes newAxes:List Nat) (ho:∀q∈oldAxes,0<q) (hn:∀q∈newAxes,0<q)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod ≤ newAxes.prod)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration\n      (initial (tape table) (orderTape order) assignment (vectorBits (oldAxes.map unary)) oldp (vectorBits (newAxes.map unary)) newp)))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length  ≤ 100000000000*(resource oldAxes newAxes oldp newp table order assignment)^2:=by\n  apply machine_cells_at _ fuel _ cfg hp\n  intro out hr'\n  exact prefix_cells oldAxes newAxes ho hn oldp newp table order assignment hs hr fuel out hr'\n/-- SAME-program compiled ready prefixes retain/count both actual context banks, every private/shadow word and every real return. -/\ntheorem machine_ready_prefix_cells {d:Nat} (oldAxes newAxes:List Nat) (ho:0<oldAxes.prod) (hn:0<newAxes.prod)\n    (oldp newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool)\n    (hs:(selected table assignment order).length=oldAxes.prod) (hr:oldAxes.prod ≤ newAxes.prod)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration\n      (ready oldAxes newAxes oldp newp (tape table) (orderTape order) assignment)))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length  ≤ 100000000000*(resource oldAxes newAxes oldp newp table order assignment)^2:=by\n  apply machine_cells_at _ fuel _ cfg hp\n  intro out hr'\n  exact ready_prefix_cells oldAxes newAxes ho hn oldp newp table order assignment hs hr fuel out hr'\nend RiemannGaussian.SemiprimeD1StackChildTableEntryStorage\n","RiemannGaussian.SemiprimeD1StackChildUnitVertexOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildUnitVertexFrames\nimport RiemannGaussian.SemiprimeD1StackChildUnitVertexSpec\nimport RiemannGaussian.SemiprimeD1StackVertexProduct\n/-! # Whole inactive vertex acquisition from two actual context headers\nThe same finite source acquires context dimensions, constructs the literal unit,\nframes its table and emits every record bit. It takes no unit/table/rank advice.\nActivation branching and the parent-stream loop remain separate caller work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildUnitVertexOriginal\nopen SemiprimeD1StackChildUnitVertex SemiprimeD1StackChildUnitVertexCalls\nopen SemiprimeD1StackChildUnitVertexFrames SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Actual original two-header input, before acquisition of either rank or precision markers. -/\ndef originalInitial (axes : List ℕ) (precision : List Bool) : C.State Stack Label :=\n  initial (vectorBits (axes.map unary)) precision\n/-- Full actual32-role halt; both transient flags and actual saved-return stack are empty. -/\ndef done (axes : List ℕ) (precision : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,result axes precision,[]⟩\n/-- Own whole-source time pays both real producer calls, one table frame, six literal bits and true halt. -/\ndef timeBound (axes : List ℕ) (precision : List Bool) : ℕ :=\n  1000*(SemiprimeD1StackJetContextBounds.resource axes precision+1)^2+\n    SemiprimeD1StackJetUnitExecution.totalTime (width axes precision) (rank axes precision)+\n    6*(tableWord axes precision).length+14\n/-- The actual acquired unit table is byte-identical to the ENTIRE original inactive table. -/\ntheorem table_original (axes : List ℕ) (precision : List Bool) (hp : ∀q∈axes,0<q) :\n    tableWord axes precision=tape (SemiprimeD1StackChildUnitVertexSpec.vertex (ctx axes precision)).table :=\n  SemiprimeD1StackChildUnitVertexSpec.table_tape (ctx axes precision) hp\n/-- Actual literal scope and record tags coincide with the existing canonical whole-vertex codec. -/\ntheorem record_original (axes : List ℕ) (precision : List Bool) (hp : ∀q∈axes,0<q) :\n    recordWord axes precision=SemiprimeD1StackVertexProduct.records [SemiprimeD1StackChildUnitVertexSpec.vertex (ctx axes precision)] := by\n  unfold recordWord\n  rw [table_original axes precision hp]\n  rfl\n/-- SAME finite32-role source acquires the complete inactive unit record from ONLY original two-header words. -/\ntheorem source_run (axes : List ℕ) (hp : ∀q∈axes,0<q) (precision : List Bool) :\n    ∃t≤timeBound axes precision,\n      SemiprimeD1StackCalls.run program t (originalInitial axes precision)=some (done axes precision) := by\n  obtain ⟨t,ht,h0⟩:=context_call axes hp precision\n  have h1:=unit_call axes precision\n  have h2:=assemble_run axes precision\n  have h:=runs_trans program _ _ _ _ _ _ _ _ h0 (runs_trans program _ _ _ _ _ _ _ _ h1 h2)\n  obtain ⟨finish,hfinish,hAt⟩:=h [] (originalInitial axes precision) ⟨rfl,rfl,rfl⟩\n  refine ⟨t+(SemiprimeD1StackJetUnitExecution.totalTime (width axes precision) (rank axes precision)+1+\n    (6*(tableWord axes precision).length+11))+1,?_,?_⟩\n  · unfold timeBound;omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some]\n    exact halt_run program (.local .done) rfl _ [] finish hAt\n/-- Complete output and source run concern the SAME actual data bank and existing original codec. -/\ntheorem source_original (axes : List ℕ) (hp : ∀q∈axes,0<q) (precision : List Bool) :\n    ∃t≤timeBound axes precision,\n      SemiprimeD1StackCalls.run program t (originalInitial axes precision)=some (done axes precision) ∧\n      (done axes precision).data (aux .record)=\n        SemiprimeD1StackVertexProduct.records [SemiprimeD1StackChildUnitVertexSpec.vertex (ctx axes precision)] := by\n  obtain ⟨t,ht,hr⟩:=source_run axes hp precision\n  exact ⟨t,ht,hr,record_original axes precision hp⟩\nend RiemannGaussian.SemiprimeD1StackChildUnitVertexOriginal\n","RiemannGaussian.SemiprimeD1StackDescriptorRecordExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecordLoad\n/-! # Actual descriptor loader, whole static-table source and record execution -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackDescriptorRecordExecution\nopen SemiprimeD1StackDescriptorRecord SemiprimeD1StackDescriptorRecordLoadView\nopen SemiprimeD1StackDescriptorRecordLoad SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackStaticTableSpec (CheckerTrace)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : T.Static K L) (sourceMap : K→Option (Fin 6))\nomit [DecidableEq K] [Fintype K] in\n/-- The proved loaded store is exactly the actual component initialization,\nwith every unselected metadata/assignment/result/cache field empty. -/\ntheorem loaded_initial (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (bank hist out : List Bool) :\n    loaded sourceMap (initial s oldTemplate fields bank hist out).data=afterLoad s sourceMap fields bank hist out := by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k <;> rfl\n    · rfl\n  · rfl\n/-- Actual input inventory and every old template byte contribute to loader time. -/\ndef prepareBound (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (bank hist out : List Bool) : Nat :=\n  s.roles.length*loadUnit (initial s oldTemplate fields bank hist out).data+2\n/-- The finite template loader makes real copies and a real return for every\nstatic position, including all empty/unselected private and alias fields. -/\ntheorem prepare_call (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (bank hist out : List Bool) :\n    ∃t≤prepareBound s oldTemplate fields bank hist out,Runs (program s sourceMap) t (.inl .start)\n      (initial s oldTemplate fields bank hist out).data (.inl .record) (afterLoad s sourceMap fields bank hist out) := by\n  obtain ⟨t,ht,hr⟩:=load_returns s sourceMap (initial s oldTemplate fields bank hist out).data rfl\n  have h:=SemiprimeD1StackProcedureReturns.call (program s sourceMap) t (.inl .start) (.inl (.load 0))\n    (.inl .record) _ _ rfl hr\n  rw [loaded_initial] at h\n  exact ⟨1+t,by unfold prepareBound;omega,h⟩\n/-- The actual static-record call consumes its acquired source outputs and\nretains all six original physical descriptor/N fields and loader scratch. -/\ntheorem record_call (fields : Fin 6→List Bool) (hraw : selected sourceMap fields s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hc : CheckerTrace s (selected sourceMap fields) answer budget)\n    (words : List (List Bool)) (hist out : List Bool) :\n    ∃t≤SemiprimeD1StackStaticRecordExecution.timeBound s (selected sourceMap fields) words answer budget,\n      Runs (program s sourceMap) (t+1) (.inl .record) (afterLoad s sourceMap fields (vectorBits words) hist out)\n        (.inl .done) (done s sourceMap fields words answer hist out).data := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackStaticRecordExecution.source_run s (selected sourceMap fields) hraw\n    answer budget hc words hist out\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call (program s sourceMap) recordStack recordLabel\n    Sum.inl_injective (R.program s) (.inl .start) (fun _=>rfl) (.inl .record) (.inl .done) rfl t\n    (SemiprimeD1StackStaticRecord.initial s (selected sourceMap fields) (vectorBits words) hist out)\n    (SemiprimeD1StackStaticRecord.done s (selected sourceMap fields) words answer hist out)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>rfl\n/-- Full same-source clock: charged dirty-template drain/load, actual whole\ntable source, scope serialization, consuming logger, all calls and final halt. -/\ndef timeBound (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (words : List (List Bool))\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hist out : List Bool) : Nat :=\n  prepareBound s oldTemplate fields (vectorBits words) hist out+\n    SemiprimeD1StackStaticRecordExecution.timeBound s (selected sourceMap fields) words answer budget+2\n/-- Entire real descriptor-to-record execution. Every mathematical checker\ncontract is a correctness proof for a checker fixed before original N. -/\ntheorem source_run (oldTemplate : K→List Bool) (fields : Fin 6→List Bool)\n    (hraw : selected sourceMap fields s.raw=[]) (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (selected sourceMap fields) answer budget) (words : List (List Bool)) (hist out : List Bool) :\n    ∃t≤timeBound s sourceMap oldTemplate fields words answer budget hist out,C.run (program s sourceMap) t\n      (initial s oldTemplate fields (vectorBits words) hist out)=some (done s sourceMap fields words answer hist out) := by\n  obtain ⟨a,ha,h0⟩:=prepare_call s sourceMap oldTemplate fields (vectorBits words) hist out\n  obtain ⟨b,hb,h1⟩:=record_call s sourceMap fields hraw answer budget hc words hist out\n  have h:=runs_trans (program s sourceMap) _ _ _ _ _ _ _ _ h0 h1\n  obtain ⟨finish,hr,hAt⟩:=h [] (initial s oldTemplate fields (vectorBits words) hist out) ⟨rfl,rfl,rfl⟩\n  refine ⟨a+(b+1)+1,by unfold timeBound;omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  rcases hAt with ⟨hpc,hd,hframes⟩\n  change SemiprimeD1StackCalls.step (program s sourceMap) finish=some (done s sourceMap fields words answer hist out)\n  simp [SemiprimeD1StackCalls.step,hpc,program,SemiprimeD1StackCalls.execute,hd,hframes,done]\n/-- Complete trace of the same genuine finite machine and actual return cells. -/\nnoncomputable def recordInTime [Fintype L] (oldTemplate : K→List Bool) (fields : Fin 6→List Bool)\n    (hraw : selected sourceMap fields s.raw=[]) (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (selected sourceMap fields) answer budget) (words : List (List Bool)) (hist out : List Bool) :\n    StateTransition.EvalsToInTime (machine s sourceMap).step\n      (SemiprimeD1StackCalls.configuration (initial s oldTemplate fields (vectorBits words) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done s sourceMap fields words answer hist out)))\n      (timeBound s sourceMap oldTemplate fields words answer budget hist out) := by\n  apply SemiprimeD1StackCalls.evalsCorrect original output (.inl .start) (program s sourceMap)\n  let h:=source_run s sourceMap oldTemplate fields hraw answer budget hc words hist out\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\nend RiemannGaussian.SemiprimeD1StackDescriptorRecordExecution\n","RiemannGaussian.SemiprimeD1StackEuclidGCDSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEuclidGCDCalls\n/-! # Physically acquired byte fuel and actual initial Euclid operands -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackEuclidGCDSetup\nopen SemiprimeD1StackEuclidGCD SemiprimeD1StackEuclidGCDEncoding SemiprimeD1StackEuclidGCDCalls\nopen SemiprimeD1StackProcedureTrace\n/-- Every real byte pop executes both literal true-marker pushes; the EOF is charged too. -/\ntheorem scan_run (right:Bool) (w:Words) (xs:List Bool) :\n    Runs program (3*xs.length+1) (.scan right) (bank {w with scan:=xs})\n      (if right then .initialX else .copyFuelRight)\n      (bank {w with scan:=[],fuel:=List.replicate (2*xs.length) true++w.fuel}) :=by\n  induction xs generalizing w with\n  | nil=>\n    have h:=P.pop_run (.scan right) (if right then .initialX else .copyFuelRight)\n      (.pushOne right) (.pushOne right) (aux .scan) (bank {w with scan:=[]}) [] rfl rfl\n    rw [update_scan] at h\n    exact h\n  | cons b xs ih=>\n    have h0:=P.pop_run (.scan right) (if right then .initialX else .copyFuelRight)\n      (.pushOne right) (.pushOne right) (aux .scan) (bank {w with scan:=b::xs}) (b::xs) rfl rfl\n    rw [update_scan] at h0\n    have hchoose:SemiprimeD1StackBytecode.choose (if right then Label.initialX else .copyFuelRight)\n        (.pushOne right) (.pushOne right) (b::xs).head?=Label.pushOne right:=by cases b <;> rfl\n    rw [hchoose] at h0\n    have h1:=P.push_run (.pushOne right) (.pushTwo right) (aux .fuel) true (bank {w with scan:=xs}) rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (aux .fuel) (true::w.fuel)) at h1\n    rw [update_fuel] at h1\n    have h2:=P.push_run (.pushTwo right) (.scan right) (aux .fuel) true\n      (bank {w with scan:=xs,fuel:=true::w.fuel}) rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (aux .fuel) (true::true::w.fuel)) at h2\n    rw [update_fuel] at h2\n    have h3:=ih {w with fuel:=true::true::w.fuel}\n    have h:=P.join (P.join (P.join h0 h1) h2) h3\n    have he:List.replicate (2*xs.length) true++true::true::w.fuel=\n        List.replicate (2*(b::xs).length) true++w.fuel:=by\n      rw [show 2*(b::xs).length=2*xs.length+2 by simp only [List.length_cons];omega,\n        List.replicate_add,List.append_assoc]\n      rfl\n    change Runs _ _ _ _ _ (bank {w with scan:=[],fuel:=List.replicate (2*xs.length) true++true::true::w.fuel}) at h\n    rw [he] at h\n    convert h using 1\n    simp only [List.length_cons]\n    omega\n/-- Literal total source clock through the first clean Euclid loop boundary. -/\ndef setupTime (left right:List Bool) :Nat:=\n  1+(5*left.length+4)+(3*left.length+1)+(5*right.length+4)+(3*right.length+1)+\n    (5*left.length+4)+(5*right.length+4)+(2*right.length+3)+\n      (SemiprimeD1StackReduceExecution.trimTime right.reverse+1)\n/-- The source pays four preserving input copies, actual scans and the actual initial trim. -/\ntheorem setup_run (left right:List Bool) :\n    Runs program (setupTime left right) .start (input left right) .loop\n      (bank (loopWords left right (List.replicate (SemiprimeD1StackEuclidGCDSpec.fuelLength left right) true)\n        left (SemiprimeD1StackSourceEnvironmentEncoding.normalize right))) :=by\n  rw [initial_bank]\n  have h0:=P.push_run .start .copyFuelLeft (aux .fuel) true\n    (bank {originalLeft:=left,originalRight:=right}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .fuel) [true]) at h0\n  rw [update_fuel] at h0\n  have h1:=P.copy_call .fuelLeft .copyFuelLeft (.scan false) rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=[true]}) left [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .scan) (left++[])) at h1\n  rw [List.append_nil,update_scan] at h1\n  have h2:=scan_run false {originalLeft:=left,originalRight:=right,fuel:=[true]} left\n  have h3:=P.copy_call .fuelRight .copyFuelRight (.scan true) rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=List.replicate (2*left.length) true++[true]})\n    right [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .scan) (right++[])) at h3\n  rw [List.append_nil,update_scan] at h3\n  have h4:=scan_run true {originalLeft:=left,originalRight:=right, fuel:=List.replicate (2*left.length) true++[true]} right\n  let fuel:=List.replicate (2*right.length) true++(List.replicate (2*left.length) true++[true])\n  have h5:=P.copy_call .initialX .initialX .initialY rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel}) left [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (dividerStack (.inr .input)) (left++[])) at h5\n  rw [List.append_nil,update_x] at h5\n  have h6:=P.copy_call .initialY .initialY .reverseInitial rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,x:=left}) right [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (dividerStack (.inr .divisor)) (right++[])) at h6\n  rw [List.append_nil,update_y] at h6\n  have h7:=P.reverse_call .initialY .reverseInitial .trimInitial rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,x:=left,y:=right}) right [] rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (dividerStack (.inr .divisor)) [])\n    (aux .trimScratch) (right.reverse++[])) at h7\n  rw [List.append_nil,update_y,update_trimScratch] at h7\n  have h8:=P.trim_call .divisor .trimInitial .loop rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,x:=left,trimScratch:=right.reverse}) right.reverse [] rfl rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (aux .trimScratch) [])\n    (dividerStack (.inr .divisor)) (SemiprimeD1StackReduceExecution.trimReverse right.reverse++[])) at h8\n  rw [List.append_nil,update_trimScratch,update_y] at h8\n  have h:=P.join (P.join (P.join (P.join (P.join (P.join (P.join (P.join h0 h1) h2) h3) h4) h5) h6) h7) h8\n  have hf:fuel=List.replicate (SemiprimeD1StackEuclidGCDSpec.fuelLength left right) true:=by\n    change List.replicate (2*right.length) true++(List.replicate (2*left.length) true++List.replicate 1 true)=_\n    rw [←List.replicate_add,←List.replicate_add]\n    congr 1\n    unfold SemiprimeD1StackEuclidGCDSpec.fuelLength\n    omega\n  simpa only [setupTime,hf,loopWords,SemiprimeD1StackSourceEnvironmentEncoding.normalize] using h\nend RiemannGaussian.SemiprimeD1StackEuclidGCDSetup\n","RiemannGaussian.SemiprimeD1StackExprCodec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMacroEntryBitPrimitives\nimport RiemannGaussian.SemiprimeSourceHistogramKeyBits\n\n/-! # Physical public arithmetic expression syntax\nPrefix tags 00/01/10/11 denote literal/add/sub/multiply. Literal payloads are\nself-delimiting actual bit fields. All repeated subtree and literal cells are\nretained in the size; no expression object or integer is put in finite control.\nThe fixed recursive evaluator will use actual finite-label call/return frames.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprCodec\nopen SemiprimeMacroEntryBitPrimitives (Expr nodes)\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Literal prefix byte stream, with an explicit already acquired suffix. -/\ndef encode : Expr→List Bool→List Bool\n  | .literal bits,tail => false::false::frame bits tail\n  | .add a b,tail => false::true::encode a (encode b tail)\n  | .sub a b,tail => true::false::encode a (encode b tail)\n  | .mul a b,tail => true::true::encode a (encode b tail)\n\n/-- Every occurrence of a literal payload is counted, including repeated words. -/\ndef literalCells : Expr→ℕ\n  | .literal bits => bits.length\n  | .add a b | .sub a b | .mul a b => literalCells a+literalCells b\n\n/-- Exact physical syntax size, including both tags and literal delimiters. -/\ndef size : Expr→ℕ\n  | .literal bits => 2*bits.length+3\n  | .add a b | .sub a b | .mul a b => size a+size b+2\n\n/-- The actual syntax consumes exactly its own counted physical prefix. -/\ntheorem encode_length (expr : Expr) (tail : List Bool) :\n    (encode expr tail).length=size expr+tail.length := by\n  induction expr generalizing tail <;>\n    simp_all only [encode,size,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length] <;> omega\n\n/-- Framed payloads preserve arbitrary literal stream suffixes. -/\ntheorem frame_append (word tail : List Bool) : frame word tail=frame word []++tail := by\n  induction word with\n  | nil => rfl\n  | cons b word ih => simpa only [frame,List.cons_append] using congrArg (fun t=>true::b::t) ih\n\n/-- Encoding retains the exact supplied suffix, without an input-sized label. -/\ntheorem encode_append (expr : Expr) (tail : List Bool) :\n    encode expr tail=encode expr []++tail := by\n  induction expr generalizing tail with\n  | literal bits => exact congrArg (fun s=>false::false::s) (frame_append bits tail)\n  | add a b ia ib =>\n    change false::true::encode a (encode b tail)=false::true::(encode a (encode b [])++tail)\n    apply congrArg (fun s=>false::true::s)\n    rw [ia (encode b tail),ib tail,ia (encode b []),List.append_assoc]\n  | sub a b ia ib =>\n    change true::false::encode a (encode b tail)=true::false::(encode a (encode b [])++tail)\n    apply congrArg (fun s=>true::false::s)\n    rw [ia (encode b tail),ib tail,ia (encode b []),List.append_assoc]\n  | mul a b ia ib =>\n    change true::true::encode a (encode b tail)=true::true::(encode a (encode b [])++tail)\n    apply congrArg (fun s=>true::true::s)\n    rw [ia (encode b tail),ib tail,ia (encode b []),List.append_assoc]\n\n/-- Whole syntax acquisition must pay every literal occurrence and node tag. -/\ntheorem size_le (expr : Expr) : size expr ≤ 2*literalCells expr+3*nodes expr := by\n  induction expr <;> simp_all only [size,literalCells,nodes] <;> omega\n\n/-- Every syntax tree occupies a nonempty physical prefix. -/\ntheorem size_pos (expr : Expr) : 0 < size expr := by\n  cases expr <;> simp only [size] <;> omega\n\n/-- The two-tag syntax always begins with two actual available Boolean cells. -/\ntheorem encode_two_tags (expr : Expr) (tail : List Bool) :\n    ∃a b rest,encode expr tail=a::b::rest := by\n  cases expr <;> exact ⟨_,_,_,rfl⟩\n\nend RiemannGaussian.SemiprimeD1StackExprCodec\n","RiemannGaussian.SemiprimeD1StackExprDotBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprDotExecution\nimport RiemannGaussian.SemiprimeD1StackJetPointBounds\n\n/-! # Closed physical dot-source cost and storage\nThe inventory includes the entire encoded input vector and all physically\nacquired marker words. Products and repeated syntax construction are paid by\ntheir actual traces. This is a prepared-cache source builder; original-input\nacquisition of those caches is still the enclosing caller's work.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprDotBounds\nopen SemiprimeD1StackExprDot SemiprimeD1StackExprDotExecution\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Actual physical argument inventory, including complete source and metadata. -/\ndef inputSize (c : Cache) : ℕ :=\n  c.base.length+c.words.length+c.stride.length+c.frequency.length+c.count.length+1\n\n/-- Fixed polynomial envelope for a single whole term, not an advised clock. -/\ndef termBound (S : ℕ) : ℕ :=\n  (5*S+4)+(5*(S*(2*S+3)+1)+1)+(5*((S*S)*(2*S+3)+1)+1)+\n    (S^3*(5*S+18)+17)+(S^3+1)+(5*S+4)+(30*(2*S+2)+1)+\n    (6*S+5)+4+(S+1)\n\n/-- Every selected word and both acquired exponent products are bounded by the\nphysical input inventory; no selected value or exponent cap is a premise. -/\ntheorem budget_le (c : Cache) (words : List (List Bool)) (stride frequency j S : ℕ)\n    (hb : c.base.length ≤ S) (hw : (vectorBits words).length ≤ S)\n    (hs : stride ≤ S) (hf : frequency ≤ S) (hj : j ≤ S) :\n    SemiprimeD1StackExprDotTerm.budget c words stride frequency j ≤ termBound S := by\n  have hword : (SemiprimeD1StackExprDotSpec.wordAt words j).length ≤ S :=\n    (SemiprimeD1StackJetPointBounds.coefficient_length words j).trans hw\n  have hjf : j*frequency ≤ S*S := Nat.mul_le_mul hj hf\n  have he : stride*(j*frequency) ≤ S^3 := by\n    calc\n      _ ≤ S*(S*S) := Nat.mul_le_mul hs hjf\n      _ = _ := by ring\n  have hp1 : 5*(j*(2*frequency+3)+1)+1 ≤ 5*(S*(2*S+3)+1)+1 := by gcongr\n  have hp2 : 5*((j*frequency)*(2*stride+3)+1)+1 ≤ 5*((S*S)*(2*S+3)+1)+1 := by\n    gcongr\n  have hpower : stride*(j*frequency)*(5*c.base.length+18)+17 ≤ S^3*(5*S+18)+17 := by\n    gcongr\n  have hr := SemiprimeD1StackJetReadExecution.totalTime_le (unary j) words\n  simp only [SemiprimeD1StackJetReadExecution.timeBound,unary,List.length_replicate] at hr\n  have hread : SemiprimeD1StackJetReadExecution.totalTime (unary j) words ≤ 30*(2*S+2) := by\n    simp only [unary]\n    omega\n  unfold SemiprimeD1StackExprDotTerm.budget termBound\n  rw [SemiprimeD1StackExprPowerBounds.totalTime_eq]\n  simp only [unary,List.length_replicate]\n  omega\n\n/-- Uniform fourth degree envelope includes every copied base subtree. -/\ntheorem termBound_le (S : ℕ) : termBound S ≤ 1000*(S+1)^4 := by\n  unfold termBound\n  nlinarith [Nat.zero_le (S^2),Nat.zero_le (S^3),Nat.zero_le (S^4)]\n\n/-- All visits of the actual decreasing counter are counted. -/\ntheorem loopBudget_le (c : Cache) (words : List (List Bool)) (stride frequency S : ℕ)\n    (hb : c.base.length ≤ S) (hw : (vectorBits words).length ≤ S)\n    (hs : stride ≤ S) (hf : frequency ≤ S) (n : ℕ) (hn : n ≤ S) :\n    loopBudget c words stride frequency n ≤ (n+1)*(termBound S+1) := by\n  induction n with\n  | zero => simp only [loopBudget,Nat.zero_add,Nat.one_mul];omega\n  | succ n ih =>\n    have hprev := ih (by omega)\n    have hterm := budget_le c words stride frequency n S hb hw hs hf (by omega)\n    simp only [loopBudget]\n    nlinarith\n\n/-- Derived fifth degree own-program bound from actual cache bytes only. -/\ntheorem timeBound_le (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) :\n    timeBound c words stride frequency n ≤ 10000*(inputSize c+1)^5 := by\n  let S:=inputSize c\n  have hb : c.base.length ≤ S := by dsimp [S,inputSize];omega\n  have hw : (vectorBits words).length ≤ S := by dsimp [S,inputSize];rw [hc];omega\n  have hstride : stride ≤ S := by dsimp [S,inputSize];rw [hs];simp only [unary,List.length_replicate];omega\n  have hfreq : frequency ≤ S := by dsimp [S,inputSize];rw [hf];simp only [unary,List.length_replicate];omega\n  have hcount : n ≤ S := by dsimp [S,inputSize];rw [hn];simp only [unary,List.length_replicate];omega\n  have hloop:=loopBudget_le c words stride frequency S hb hw hstride hfreq n hcount\n  have hterm:=termBound_le S\n  have hprod : (n+1)*(termBound S+1) ≤ (S+1)*(1000*(S+1)^4+1) := by gcongr\n  have hp : (S+1)*(1000*(S+1)^4+1)+13*S+13 ≤ 10000*(S+1)^5 := by\n    nlinarith [Nat.zero_le (S^2),Nat.zero_le (S^3),Nat.zero_le (S^4),Nat.zero_le (S^5)]\n  change timeBound c words stride frequency n ≤ 10000*(S+1)^5\n  unfold timeBound\n  omega\n\n/-- An actual source certificate for the complete program, never a callback. -/\nnoncomputable def sourceBuild (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool) :\n    StateTransition.EvalsToInTime (C.step program) (initial c tail)\n      (some (done c words stride frequency n tail)) (10000*(inputSize c+1)^5) := by\n  let h:=source_run c words stride frequency n hs hf hn hc tail\n  let m:=Classical.choose h\n  have hm:=Classical.choose_spec h\n  exact ⟨⟨m,hm.2⟩,hm.1.trans (timeBound_le c words stride frequency n hs hf hn hc)⟩\n\n/-- The same completed trace on a fixed finite-stack bit machine. -/\nnoncomputable def machineBuild (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial c tail))\n      (some (SemiprimeD1StackCalls.configuration (done c words stride frequency n tail)))\n      (10000*(inputSize c+1)^5) :=\n  SemiprimeD1StackCalls.evalsCorrect (K:=Stack) (L:=Label) Stack.base Stack.output (Label.control .start) program _ _ _\n    (sourceBuild c words stride frequency n hs hf hn hc tail)\n\n/-- Exact original dot-expression source bytes and retained physical suffix. -/\ntheorem output_original (c : Cache) (baseExpr : SemiprimeMacroEntryBitPrimitives.Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr [])\n    (words : List (List Bool)) (stride frequency n : ℕ) (tail : List Bool) :\n    (done c words stride frequency n tail).data .output=\n      SemiprimeD1StackExprCodec.encode\n        (SemiprimeMacroEntryBitPrimitives.dotExpr baseExpr stride frequency\n          (SemiprimeD1StackExprDotSpec.wordAt words) n) tail := by\n  change SemiprimeD1StackExprDotSpec.result n c.base words stride frequency tail=_\n  rw [hbase]\n  exact SemiprimeD1StackExprDotSpec.result_original baseExpr words stride frequency n tail\n\n/-- Every successful prefix stops by the proved own-program halt. -/\ntheorem prefix_fuel_le (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label) (hr : C.run program fuel (initial c tail)=some out) :\n    fuel ≤ 10000*(inputSize c+1)^5 := by\n  obtain ⟨m,hm,he⟩:=source_run c words stride frequency n hs hf hn hc tail\n  have hfm : fuel ≤ m := by\n    by_contra h\n    have hh : fuel=m+(1+(fuel-(m+1))) := by omega\n    rw [hh,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done c words stride frequency n tail)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hfm.trans (hm.trans (timeBound_le c words stride frequency n hs hf hn hc))\n\n/-- Every prefix counts all22 Boolean stacks and real finite-label return cells. -/\ntheorem prefix_cells (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label) (hr : C.run program fuel (initial c tail)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤\n      23*(inputSize c+tail.length+10000*(inputSize c+1)^5) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (inputSize c+tail.length) _ out\n    (by intro k;cases k <;> simp [initial,bank,inputSize] <;> omega) hr\n  have hfuel:=prefix_fuel_le c words stride frequency n hs hf hn hc tail fuel out hr\n  have hframe:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hframe\n  have hsum : (∑k : Stack,(out.data k).length) ≤ 22*(inputSize c+tail.length+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(inputSize c+tail.length+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  omega\n\n/-- The same every-prefix storage bound on the actual finite machine. -/\ntheorem machine_prefix_cells (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c tail)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      23*(inputSize c+tail.length+10000*(inputSize c+1)^5) := by\n  have he:=SemiprimeD1StackCalls.run_correct Stack.base Stack.output (.control .start) program fuel (initial c tail)\n  change (C.run program fuel (initial c tail)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c tail))) at he\n  have hh:=he.trans hr\n  cases hrun:C.run program fuel (initial c tail) with\n  | none => rw [hrun] at hh;cases hh\n  | some out =>\n    rw [hrun] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells c words stride frequency n hs hf hn hc tail fuel out hrun\n\nend RiemannGaussian.SemiprimeD1StackExprDotBounds\n","RiemannGaussian.SemiprimeD1StackExprDotComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprDotSpec\n\n/-! # Actual copy and exponent-acquisition calls inside dot construction\nThe products below are consequences of included literal machine traces. No\nintermediate product, timing, selected value or resolved syntax is an input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprDotComponents\nopen SemiprimeD1StackExprDot SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackUnaryDivmod (unary)\nlocal notation \"ctl\" => SemiprimeD1StackExprDot.Label.control\n\n/-- A real included Copy works on the reached bank and restores its own scratch. -/\ntheorem copy_call (kind : CopyKind) (data : Stack→List Bool) (hs : data .copyScratch=[])\n    (pc next : Label) (hcall : program pc=.call (.copy kind 0) next) :\n    Runs program (5*(data (copyInput kind)).length+4) pc data next\n      (Function.update data (copyOutput kind) (data (copyInput kind)++data (copyOutput kind))) := by\n  apply included_call program (copyStack kind) (Label.copy kind) (copyStack_injective kind)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hcall\n    (5*(data (copyInput kind)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (data (copyInput kind)) (data (copyOutput kind)) [])\n    (SemiprimeD1StackCopy.done (data (copyInput kind)) (data (copyInput kind)++data (copyOutput kind)))\n    data (Function.update data (copyOutput kind) (data (copyInput kind)++data (copyOutput kind)))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words _ _ none\n  · constructor\n    · intro k;fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.state,SemiprimeD1StackCopy.payload,hs]\n    · intro k _;rfl\n  · constructor\n    · intro k\n      cases kind <;> fin_cases k <;>\n        simp [copyStack,copyInput,copyOutput,SemiprimeD1StackCopy.done,SemiprimeD1StackCopy.payload,Function.update,hs]\n    · intro k hk\n      have hn : k≠copyOutput kind := by\n        intro he\n        apply hk 1\n        simpa only [copyStack,show ¬((1:Fin 3)=0) by decide,ite_false,ite_true] using he.symm\n      exact Function.update_of_ne hn _ _\n\n/-- The loop-index multiplier is acquired by an actual preserving copy. -/\ntheorem copy_product (c : Cache) (remaining out : List Bool) :\n    Runs program (5*remaining.length+4) (ctl .copyProduct) (bank c {remaining:=remaining,output:=out})\n      (ctl .productFirst) (bank c {remaining:=remaining,multiplier:=remaining,output:=out}) := by\n  have h:=copy_call .product (bank c {remaining:=remaining,output:=out}) rfl\n    (ctl .copyProduct) (ctl .productFirst) rfl\n  have he : Function.update (bank c {remaining:=remaining,output:=out}) .multiplier remaining=\n      bank c {remaining:=remaining,multiplier:=remaining,output:=out} := by\n    funext k;cases k <;> simp [Function.update,bank]\n  simpa only [copyInput,copyOutput,bank,List.append_nil,he] using h\n\n/-- Actual first unary product acquires j*frequency and preserves the frequency\ncache. Its only numeric premises identify the physically present original tapes. -/\ntheorem product_first (c : Cache) (j frequency : ℕ) (hf : c.frequency=unary frequency)\n    (out : List Bool) :\n    ∃t ≤ 5*(j*(2*frequency+3)+1),Runs program (t+1) (ctl .productFirst)\n      (bank c {remaining:=unary j,multiplier:=unary j,output:=out}) (ctl .productSecond)\n      (bank c {remaining:=unary j,intermediate:=unary (j*frequency),output:=out}) := by\n  obtain ⟨t,ht,hr⟩:=U.product_run j frequency\n  refine ⟨t,ht,?_⟩\n  apply included_call program (productStack false) (Label.product false) (productStack_injective false)\n    U.code U.entry (fun _=>rfl) (ctl .productFirst) (ctl .productSecond) rfl t\n    (⟨some U.entry,none,U.contents (unary j) (unary frequency) [] []⟩:\n      SemiprimeD1StackBytecode.State U.Stack U.Label)\n    (⟨none,none,U.contents [] (unary frequency) [] (unary (j*frequency))⟩:\n      SemiprimeD1StackBytecode.State U.Stack U.Label)\n    (bank c {remaining:=unary j,multiplier:=unary j,output:=out})\n    (bank c {remaining:=unary j,intermediate:=unary (j*frequency),output:=out})\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;cases k <;> simp [productStack,bank,U.contents,hf]\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> simp [productStack,bank,U.contents,hf]\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk .multiplier rfl) | exact False.elim (hk .product rfl)\n\n/-- The actual second product consumes the actual first product directly and\nacquires the complete original exponent stride*(j*frequency). -/\ntheorem product_second (c : Cache) (j stride frequency : ℕ) (hs : c.stride=unary stride)\n    (out : List Bool) :\n    ∃t ≤ 5*((j*frequency)*(2*stride+3)+1),Runs program (t+1) (ctl .productSecond)\n      (bank c {remaining:=unary j,intermediate:=unary (j*frequency),output:=out}) (ctl .powerCall)\n      (bank c {remaining:=unary j,exponent:=unary (stride*(j*frequency)),output:=out}) := by\n  obtain ⟨t,ht,hr⟩:=U.product_run (j*frequency) stride\n  refine ⟨t,ht,?_⟩\n  apply included_call program (productStack true) (Label.product true) (productStack_injective true)\n    U.code U.entry (fun _=>rfl) (ctl .productSecond) (ctl .powerCall) rfl t\n    (⟨some U.entry,none,U.contents (unary (j*frequency)) (unary stride) [] []⟩:\n      SemiprimeD1StackBytecode.State U.Stack U.Label)\n    (⟨none,none,U.contents [] (unary stride) [] (unary (stride*(j*frequency)))⟩:\n      SemiprimeD1StackBytecode.State U.Stack U.Label)\n    (bank c {remaining:=unary j,intermediate:=unary (j*frequency),output:=out})\n    (bank c {remaining:=unary j,exponent:=unary (stride*(j*frequency)),output:=out})\n  · rfl\n  · rfl\n  · simpa only [Nat.mul_comm (j*frequency) stride] using hr\n  · constructor\n    · intro k;cases k <;> simp [productStack,bank,U.contents,hs]\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> simp [productStack,bank,U.contents,hs]\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk .multiplier rfl) | exact False.elim (hk .product rfl)\n\n/-- The actual full power-syntax builder executes with the product tape acquired\nabove. All syntax/base/counter scratch and both caches follow its literal trace. -/\ntheorem power_call (c : Cache) (j e : ℕ) (out : List Bool) :\n    Runs program (SemiprimeD1StackExprPowerExecution.totalTime c.base (unary e)+1)\n      (ctl .powerCall) (bank c {remaining:=unary j,exponent:=unary e,output:=out})\n      (ctl .clearExponent) (bank c {remaining:=unary j,exponent:=unary e,output:=SemiprimeD1StackExprPowerSpec.result e c.base out}) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program powerStack Label.power powerStack_injective\n    Power.program .start (fun _=>rfl) (ctl .powerCall) (ctl .clearExponent) rfl\n    (SemiprimeD1StackExprPowerExecution.totalTime c.base (unary e)) (Power.initial c.base (unary e) out)\n    (SemiprimeD1StackExprPowerExecution.done c.base (unary e) out)\n    (bank c {remaining:=unary j,exponent:=unary e,output:=out})\n    (bank c {remaining:=unary j,exponent:=unary e,output:=SemiprimeD1StackExprPowerSpec.result e c.base out})\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackExprPowerExecution.source_run c.base (unary e) out\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      fin_cases k <;> simp [powerStack,bank,SemiprimeD1StackExprPowerExecution.done,\n        SemiprimeD1StackExprPower.store,unary]\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk 4 rfl)\n\n/-- Every preserved exponent marker is physically cleared before the next term. -/\ntheorem clear_exponent (c : Cache) (remaining exponent out : List Bool) :\n    Runs program (exponent.length+1) (ctl .clearExponent)\n      (bank c {remaining:=remaining,exponent:=exponent,output:=out}) (ctl .copyIndex)\n      (bank c {remaining:=remaining,output:=out}) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (ctl .clearExponent) (ctl .copyIndex)\n    Stack.exponent rfl (bank c {remaining:=remaining,output:=out}) exponent\n  have hi : Function.update (bank c {remaining:=remaining,output:=out}) Stack.exponent exponent=\n      bank c {remaining:=remaining,exponent:=exponent,output:=out} := by\n    funext k;cases k <;> simp [Function.update,bank]\n  have ho : Function.update (bank c {remaining:=remaining,output:=out}) Stack.exponent []=\n      bank c {remaining:=remaining,output:=out} := Function.update_eq_self _ _\n  rw [hi,ho] at h\n  exact h\n\n/-- The selected-word index comes from another real preserving loop-counter Copy. -/\ntheorem copy_index (c : Cache) (remaining out : List Bool) :\n    Runs program (5*remaining.length+4) (ctl .copyIndex) (bank c {remaining:=remaining,output:=out})\n      (ctl .readCall) (bank c {remaining:=remaining,index:=remaining,output:=out}) := by\n  have h:=copy_call .index (bank c {remaining:=remaining,output:=out}) rfl (ctl .copyIndex) (ctl .readCall) rfl\n  have he : Function.update (bank c {remaining:=remaining,output:=out}) .index remaining=\n      bank c {remaining:=remaining,index:=remaining,output:=out} := by\n    funext k;cases k <;> simp [Function.update,bank]\n  simpa only [copyInput,copyOutput,bank,List.append_nil,he] using h\n\nend RiemannGaussian.SemiprimeD1StackExprDotComponents\n","RiemannGaussian.SemiprimeD1StackExprDotExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprDotTerm\n\n/-! # Whole physical dot-expression source construction\nAll term calls are the proved closed literal pipeline. The decreasing counter,\nzero constructor, second count copy and final addition tags execute physically.\nNo abstract loop body, chosen word, exponent or syntax producer is a premise.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprDotExecution\nopen SemiprimeD1StackExprDot SemiprimeD1StackExprDotComponents SemiprimeD1StackExprDotTerm\nopen SemiprimeD1StackExprDotSpec (terms addTags addTags_push)\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => SemiprimeD1StackExprDot.Label.control\n\n/-- A real preserving count copy initializes each physical construction pass. -/\ntheorem count_copy (c : Cache) (out : List Bool) (pc next : Label)\n    (hcall : program pc=.call (.copy .count 0) next) :\n    Runs program (5*c.count.length+4) pc (bank c {output:=out}) next (bank c {remaining:=c.count,output:=out}) := by\n  have h:=copy_call .count (bank c {output:=out}) rfl pc next hcall\n  have he : Function.update (bank c {output:=out}) .remaining c.count=bank c {remaining:=c.count,output:=out} := by\n    funext k;cases k <;> simp [Function.update,bank]\n  simpa only [copyInput,copyOutput,bank,List.append_nil,he] using h\n\n/-- All three literal-zero source cells are actually pushed. -/\ntheorem zero_run (c : Cache) (out : List Bool) :\n    Runs program 3 (ctl .zero0) (bank c {output:=out}) (ctl .copyAgain)\n      (bank c {output:=false::false::false::out}) := by\n  have h0:=push_run c {output:=out} .zero0 .zero1 false rfl\n  have h1:=push_run c {output:=false::out} .zero1 .zero2 false rfl\n  have h2:=push_run c {output:=false::false::out} .zero2 .copyAgain false rfl\n  exact runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n\n/-- Counted actual addition-constructor loop, with no supplied constructor count. -/\ntheorem add_loop (count : List Bool) (c : Cache) (out : List Bool) :\n    Runs program (3*count.length+1) (ctl .addLoop) (bank c {remaining:=count,output:=out})\n      (ctl .done) (bank c {output:=addTags count.length out}) := by\n  induction count generalizing out with\n  | nil =>\n    apply one_base program (ctl .addLoop) (ctl .done) (.pop .remaining (ctl .done) (ctl .add0) (ctl .add0)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | cons bit count ih =>\n    have h0 : Runs program 1 (ctl .addLoop) (bank c {remaining:=bit::count,output:=out})\n        (ctl .add0) (bank c {remaining:=count,output:=out}) := by\n      apply one_base program (ctl .addLoop) (ctl .add0) (.pop .remaining (ctl .done) (ctl .add0) (ctl .add0)) _ _ rfl\n      · cases bit <;> rfl\n      · funext k;cases k <;> rfl\n    have h1:=push_run c {remaining:=count,output:=out} .add0 .add1 true rfl\n    have h2:=push_run c {remaining:=count,output:=true::out} .add1 .addLoop false rfl\n    have h3:=ih (false::true::out)\n    rw [addTags_push] at h3\n    have h:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3\n    simpa only [List.length_cons,addTags,\n      show (1+1)+1+(3*count.length+1)=3*(count.length+1)+1 by omega] using h\n\n/-- Retains the actual closed pipeline cost for every counted term visit. -/\ndef loopBudget (c : Cache) (words : List (List Bool)) (stride frequency : ℕ) : ℕ→ℕ\n  | 0 => 1\n  | n+1 => 1+SemiprimeD1StackExprDotTerm.budget c words stride frequency n+\n      loopBudget c words stride frequency n\n\n/-- Complete decreasing-index term construction, including all zero/default\nword cases. Its numeric indices arise from the ACTUAL popped counter. -/\ntheorem loop_run (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency) (hc : c.words=vectorBits words)\n    (out : List Bool) :\n    ∃t ≤ loopBudget c words stride frequency n,Runs program t (ctl .loop)\n      (bank c {remaining:=unary n,output:=out}) (ctl .zero0)\n      (bank c {output:=terms n c.base words stride frequency out}) := by\n  induction n generalizing out with\n  | zero =>\n    refine ⟨1,le_refl _,?_⟩\n    apply one_base program (ctl .loop) (ctl .zero0) (.pop .remaining (ctl .zero0) (ctl .copyProduct) (ctl .copyProduct)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | succ n ih =>\n    have h0 : Runs program 1 (ctl .loop) (bank c {remaining:=unary (n+1),output:=out})\n        (ctl .copyProduct) (bank c {remaining:=unary n,output:=out}) := by\n      apply one_base program (ctl .loop) (ctl .copyProduct)\n        (.pop .remaining (ctl .zero0) (ctl .copyProduct) (ctl .copyProduct)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> rfl\n    obtain ⟨m,hm,h1⟩:=term_run c words stride frequency n hs hf hc out\n    obtain ⟨k,hk,h2⟩:=ih (SemiprimeD1StackExprDotSpec.term c.base words stride frequency n out)\n    have h:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n    refine ⟨1+m+k,?_,h⟩\n    unfold loopBudget\n    omega\n\n/-- Whole own budget: count copies, every actual term, zero, add tags and halt. -/\ndef timeBound (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ) : ℕ :=\n  (5*n+4)+loopBudget c words stride frequency n+3+(5*n+4)+(3*n+1)+1\n/-- Exact final data, including all retained argument caches and physical suffix. -/\ndef done (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ) (tail : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,bank c {output:=SemiprimeD1StackExprDotSpec.result n c.base words stride frequency tail},[]⟩\n\n/-- COMPLETE actual dot-expression source acquisition. Only original physical\ncache representations are identified; no producer/body/value/clock is supplied. -/\ntheorem source_run (c : Cache) (words : List (List Bool)) (stride frequency n : ℕ)\n    (hs : c.stride=unary stride) (hf : c.frequency=unary frequency) (hn : c.count=unary n)\n    (hc : c.words=vectorBits words) (tail : List Bool) :\n    ∃t ≤ timeBound c words stride frequency n,\n      C.run program t (initial c tail)=some (done c words stride frequency n tail) := by\n  have h0:=count_copy c tail (ctl .start) (ctl .loop) rfl\n  rw [hn] at h0\n  simp only [unary,List.length_replicate] at h0\n  obtain ⟨m,hm,h1⟩:=loop_run c words stride frequency n hs hf hc tail\n  have h2:=zero_run c (terms n c.base words stride frequency tail)\n  have h3:=count_copy c (false::false::false::terms n c.base words stride frequency tail)\n    (ctl .copyAgain) (ctl .addLoop) rfl\n  rw [hn] at h3\n  simp only [unary,List.length_replicate] at h3\n  have h4:=add_loop (unary n) c (false::false::false::terms n c.base words stride frequency tail)\n  simp only [unary,List.length_replicate] at h4\n  have h:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4\n  obtain ⟨finish,hr,ho⟩:=h [] (initial c tail) ⟨rfl,rfl,rfl⟩\n  have he:=halt_run program (ctl .done) rfl\n    (bank c {output:=SemiprimeD1StackExprDotSpec.result n c.base words stride frequency tail}) [] finish ho\n  refine ⟨(5*n+4)+m+3+(5*n+4)+(3*n+1)+1,?_,?_⟩\n  · unfold timeBound\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,he]\n    rfl\n\nend RiemannGaussian.SemiprimeD1StackExprDotExecution\n","RiemannGaussian.SemiprimeD1StackFactorScopePairParse":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFactorScopePairPrimitives\n/-! # All nine physical field parses, validity reads and exact cache updates -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFactorScopePairParse\nopen SemiprimeD1StackFactorScopePairs SemiprimeD1FactorScopePairEncoding\nopen SemiprimeD1StackFactorScopePairView SemiprimeD1StackFactorScopePairPrimitives\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\n/-- One actual parser call and its actual positive-validity pop. -/\ntheorem field_run (part : Fin 9) (base : S.Stack→List Bool) (w : Record) (tail raw : List Bool) :\n    Runs program (8*(w part).length+8) (.local (.field part))\n      (clean base (suffix w part.val tail) (parsed part.val w) raw)\n      (nextField part) (clean base (suffix w (part.val+1) tail) (parsed (part.val+1) w) raw) := by\n  have h0:=field_call part (clean base (suffix w part.val tail) (parsed part.val w) raw)\n    (w part) (suffix w (part.val+1) tail)\n    (suffix_step w part tail) (by change (if part.val<part.val then w part else [])=[];simp) rfl rfl\n  unfold clean at h0\n  rw [update_reader,update_cache,parsed_step,update_valid] at h0\n  have h1 : Runs program 1 (.local (.valid part))\n      (data base (suffix w (part.val+1) tail) (parsed (part.val+1) w) raw [] [] [true])\n      (nextField part) (clean base (suffix w (part.val+1) tail) (parsed (part.val+1) w) raw) := by\n    apply one_base program (.local (.valid part)) (nextField part)\n      (.pop (aux .valid) (.local .abort) (.local .abort) (nextField part)) _ _ rfl\n    · rfl\n    · exact update_valid _ _ _ _ _ _ _ _\n  have h:=h0.trans h1\n  simpa only [clean,Nat.add_assoc,show 7+1=8 from rfl] using h\n/-- Fixed nine-field parser, covering empty fields and every original payload byte. -/\ntheorem all_fields (base : S.Stack→List Bool) (w : Record) (tail raw : List Bool) :\n    Runs program (8*mass w+72) (.local (.field 0))\n      (clean base (record w tail) (fun _=>[]) raw)\n      (.local .tag) (clean base tail w raw) := by\n  have h0:=field_run 0 base w tail raw\n  have h1:=field_run 1 base w tail raw\n  have h2:=field_run 2 base w tail raw\n  have h3:=field_run 3 base w tail raw\n  have h4:=field_run 4 base w tail raw\n  have h5:=field_run 5 base w tail raw\n  have h6:=field_run 6 base w tail raw\n  have h7:=field_run 7 base w tail raw\n  have h8:=field_run 8 base w tail raw\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans (h4.trans (h5.trans (h6.trans (h7.trans h8)))))))\n  have hm : mass w=(w 0).length+((w 1).length+((w 2).length+((w 3).length+((w 4).length+\n      ((w 5).length+((w 6).length+((w 7).length+((w 8).length+0)))))))) := rfl\n  have ht:(8*(w 0).length+8)+((8*(w 1).length+8)+((8*(w 2).length+8)+((8*(w 3).length+8)+\n      ((8*(w 4).length+8)+((8*(w 5).length+8)+((8*(w 6).length+8)+((8*(w 7).length+8)+(8*(w 8).length+8))))))))=\n      8*mass w+72 := by omega\n  rw [ht] at h\n  change Runs program (8*mass w+72) (.local (.field 0))\n    (clean base (record w tail) (parsed 0 w) raw) (.local .tag) (clean base tail (parsed 9 w) raw) at h\n  have hz:parsed 0 w=fun _=>[]:=by funext k;simp [parsed]\n  rw [parsed_end,hz] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackFactorScopePairParse\n","RiemannGaussian.SemiprimeD1StackFermatComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFermatConstants\n\n/-! # Actual metadata and counter-copy calls for public constants\nThe original metadata nested calls are included literally. No source counter,\nconstant value, inverse or desired word is passed to the original-input program.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackFermatComponents\nopen SemiprimeD1StackFermatConstants\nopen SemiprimeD1StackProcedureFragments (At Runs included_call one_base)\n\n/-- Exact actual metadata payload, overlaid only at its empty work and two new outputs. -/\ndef data (base:Meta.Stack→List Bool) (rw ew tmp modulus normalizer:List Bool) : Stack→List Bool\n  | .inl .squareWork => rw\n  | .inl .thresholdWork => ew\n  | .inl .temporary => tmp\n  | .inl k => base k\n  | .inr false => modulus\n  | .inr true => normalizer\n\n/-- Actual Copy input projection requires only its actual empty scratch. -/\ntheorem copy_input (mode:Bool) (store:Stack→List Bool) (ht:store (.inl .temporary)=[]) :\n    LinkB.DataRel (copyStack mode) store\n      (SemiprimeD1StackCopy.payload (store (copyInput mode)) (store (copyOutput mode)) []) store := by\n  constructor\n  · intro k\n    fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.payload,ht]\n  · intro k _\n    rfl\n\n/-- The copied R/E words are acquired from their actual retained source stacks. -/\ntheorem copy_output (mode:Bool) (store:Stack→List Bool) (ht:store (.inl .temporary)=[]) :\n    LinkB.DataRel (copyStack mode) store\n      (SemiprimeD1StackCopy.payload (store (copyInput mode))\n        (store (copyInput mode)++store (copyOutput mode)) [])\n      (Function.update store (copyOutput mode) (store (copyInput mode)++store (copyOutput mode))) := by\n  constructor\n  · intro k\n    cases mode <;> fin_cases k <;>\n      simp [copyStack,copyInput,copyOutput,SemiprimeD1StackCopy.payload,Function.update,ht]\n  · intro k hk\n    have hne:k≠copyOutput mode:=by\n      intro he\n      apply hk 1\n      simpa only [copyStack,show ¬((1:Fin 3)=0) by decide,ite_false,ite_true] using he.symm\n    exact Function.update_of_ne hne _ _\n\n/-- Real included Copy call with its actual continuation push and return pop. -/\ntheorem copy_call (mode:Bool) (store:Stack→List Bool) (ht:store (.inl .temporary)=[])\n    (pc next:Label) (hcall:program pc=.call (copyLabel mode 0) next) :\n    Runs program (5*(store (copyInput mode)).length+4) pc store next\n      (Function.update store (copyOutput mode) (store (copyInput mode)++store (copyOutput mode))) := by\n  apply included_call program (copyStack mode) (copyLabel mode) (copyStack_injective mode)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hcall\n    (5*(store (copyInput mode)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (store (copyInput mode)) (store (copyOutput mode)) [])\n    (SemiprimeD1StackCopy.done (store (copyInput mode)) (store (copyInput mode)++store (copyOutput mode)))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words _ _ none\n  · exact copy_input mode store ht\n  · exact copy_output mode store ht\n\n/-- Original-input projection has no prepared metadata or constant output. -/\ntheorem meta_input (bits:List Bool) :\n    LinkB.DataRel Sum.inl (input bits) (Meta.initial bits).data (input bits) := by\n  constructor\n  · intro k;rfl\n  · intro k _;rfl\n\n/-- The actual completed metadata source determines all acquired operands. -/\ntheorem meta_output (bits:List Bool) :\n    LinkB.DataRel Sum.inl (input bits) (SemiprimeD1StackTransformExecution.done bits).data\n      (data (SemiprimeD1StackTransformExecution.result bits) [] [] [] [] []) := by\n  constructor\n  · intro k\n    cases k <;> rfl\n  · intro k hk\n    cases k with\n    | inl k => exact False.elim (hk k rfl)\n    | inr bit => cases bit <;> rfl\n\n/-- Actual nested metadata execution from N alone; every source call and return is retained. -/\ntheorem metadata_call (bits:List Bool) :\n    Runs program (SemiprimeD1StackTransformArithmetic.totalTime bits.length+1) (.inl .start) (input bits)\n      (.inl .modStart) (data (SemiprimeD1StackTransformExecution.result bits) [] [] [] [] []) := by\n  intro frames target h\n  rcases h with ⟨hpc,hdata,hframes⟩\n  let entry:Meta.Label:=.inl .start\n  let mid:=C.execute (.call (metaLabel entry) (.inl .modStart)) target\n  have hm:C.run program 1 target=some mid:=by\n    change C.step program target=some mid\n    simp [C.step,SemiprimeD1StackCalls.step,hpc,program,mid,entry]\n  have hrel:LinkC.Rel Sum.inl metaLabel (input bits) (.inl .modStart) frames (Meta.initial bits) mid:=by\n    constructor\n    · change LinkB.DataRel Sum.inl (input bits) (Meta.initial bits).data target.data\n      rw [hdata]\n      exact meta_input bits\n    · simp [SemiprimeD1StackValidationLink.PcRel,Meta.initial,mid,C.execute,hframes,entry]\n  obtain ⟨finish,hfinish,hrel⟩:=LinkC.run_rel Sum.inl metaLabel Sum.inl_injective program Meta.program\n    (fun _=>rfl) (input bits) (.inl .modStart) frames\n    (SemiprimeD1StackTransformArithmetic.totalTime bits.length) (Meta.initial bits)\n    (SemiprimeD1StackTransformExecution.done bits) mid hrel\n    (SemiprimeD1StackTransformExecution.acquire_run bits) rfl\n  have hd:finish.data=data (SemiprimeD1StackTransformExecution.result bits) [] [] [] [] []:=\n    LinkB.data_unique Sum.inl (input bits) _ _ _ hrel.1 (meta_output bits)\n  have hp:finish.pc=some (.inl .modStart) ∧ finish.frames=frames:=by\n    simpa only [SemiprimeD1StackValidationLink.PcRel,SemiprimeD1StackTransformExecution.done] using hrel.2\n  refine ⟨finish,?_,hp.1,hd,hp.2⟩\n  rw [show SemiprimeD1StackTransformArithmetic.totalTime bits.length+1=\n    1+SemiprimeD1StackTransformArithmetic.totalTime bits.length by omega,\n    SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,hfinish]\nend RiemannGaussian.SemiprimeD1StackFermatComponents\n","RiemannGaussian.SemiprimeD1StackFreshBankRestoreOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFreshBankRestoreBounds\nimport RiemannGaussian.SemiprimeD1StackFreshBankRestoreLineage\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsOriginal\n/-! # Actual Root345 issued-reference lineage and complete Fresh85 restoration\nThe physical root producer determines the heap, allocation count and ordered\nreference vector. This consumer restores their exact original stopped words;\nit never reruns phase geometry, contexts or coefficient acquisition.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackFreshBankRestoreOriginal\nopen SemiprimeD1StackFreshBankRestore SemiprimeD1StackFreshBankRestoreExecution\nopen SemiprimeD1StackFreshBankRestoreBounds\nnamespace R\nexport SemiprimeD1StackRootPhaseFreshRecords (Stack heap output aux program initial)\nend R\nnamespace E\nexport SemiprimeD1StackRootPhaseFreshRecordsEncoding (freshRecord freshResult records result done)\nend E\nnamespace O\nexport SemiprimeD1StackRootPhaseParametersEncoding (phases references exponentValue levelsValue edgeValue)\nend O\nnamespace Old\nexport SemiprimeD1StackRootPhaseFreshRecordsOriginal\n  (heap_original counter_original output_original source_original)\nend Old\nnamespace L\nexport SemiprimeD1StackFreshBankRestoreLineage (history issued)\nend L\nattribute [local irreducible] SemiprimeD1StackRootPhaseFreshRecordsEncoding.result\n  SemiprimeD1StackRootPhaseFreshRecordsEncoding.freshResult\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n  SemiprimeD1StackRootPhaseParametersEncoding.exponentValue\n  SemiprimeD1StackRootPhaseParametersEncoding.levelsValue\n  SemiprimeD1StackRootPhaseParametersEncoding.edgeValue\n/-- Generic physical initial-state bridge, before any original arithmetic source is instantiated. -/\ntheorem initial_from (bs:List (F.Stack→List Bool)) (i:Fin bs.length) (heap counter reference:List Bool)\n    (hh:heap=SemiprimeD1StackHeapAllocate.heapBytes (records bs))\n    (hc:counter=List.replicate bs.length true) (hr:reference=List.replicate i.val true):\n    initial heap counter reference=source bs i:=by\n  subst heap;subst counter;subst reference;rfl\n/-- Generic complete physical target bridge avoids expanding any native original bank. -/\ntheorem done_from (bs:List (F.Stack→List Bool)) (i:Fin bs.length) (bank:F.Stack→List Bool)\n    (heap counter reference:List Bool) (hb:bank=bs[i.val])\n    (hh:heap=SemiprimeD1StackHeapAllocate.heapBytes (records bs))\n    (hc:counter=List.replicate bs.length true) (hr:reference=List.replicate i.val true):\n    done bank heap counter reference=target bs i:=by\n  subst bank;subst heap;subst counter;subst reference;rfl\n/-- Generic physical-byte bound bridge uses only the actual three input words. -/\ntheorem cap_from (bs:List (F.Stack→List Bool)) (i:Fin bs.length) (heap counter reference:List Bool)\n    (hh:heap=SemiprimeD1StackHeapAllocate.heapBytes (records bs))\n    (hc:counter=List.replicate bs.length true) (hr:reference=List.replicate i.val true):\n    1000*resource heap counter reference=linearBound bs i:=by\n  subst heap;subst counter;subst reference;rfl\n/-- Exact generic physical-byte resource equality, independent of native original graph definitions. -/\ntheorem resource_from (bs:List (F.Stack→List Bool)) (i:Fin bs.length) (heap counter reference:List Bool)\n    (hh:heap=SemiprimeD1StackHeapAllocate.heapBytes (records bs))\n    (hc:counter=List.replicate bs.length true) (hr:reference=List.replicate i.val true):\n    resource heap counter reference=inputSize bs i:=by\n  subst heap;subst counter;subst reference;rfl\n/-- The consumer's fixed85 consecutive frames are IDENTICAL to the actual producer's record ABI. -/\ntheorem record_abi (bank:F.Stack→List Bool):record bank=E.freshRecord bank:=rfl\n/-- Proof-side names of every actual originally stopped Fresh bank, in original phase order. -/\ndef banks (bits:List Bool):List (F.Stack→List Bool):=\n  (O.phases bits).map (E.freshResult (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits))\n/-- The phase ordinal is only cast across the exact original bank-list length. -/\ndef ordinal (bits:List Bool) (i:Fin (O.phases bits).length):Fin (banks bits).length:=\n  ⟨i.val,by simpa only [banks,List.length_map] using i.isLt⟩\n/-- Every complete record follows the exact original chronological phase, including rejected/repeated banks. -/\ntheorem records_original (bits:List Bool):records (banks bits)=\n    E.records (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits):=by\n  simp only [records,banks,E.records,List.map_map,Function.comp_def,record_abi]\n  rfl\n/-- The actual original allocation counter counts the entire acquired phase list. -/\ntheorem banks_length (bits:List Bool):(banks bits).length=(O.phases bits).length:=by\n  simp only [banks,List.length_map]\n/-- Exact selected original stopped bank, without decoding or recomputing any field. -/\ntheorem bank_at (bits:List Bool) (i:Fin (O.phases bits).length):\n    (banks bits)[(ordinal bits i).val]=E.freshResult (O.exponentValue bits) (O.levelsValue bits)\n      (O.edgeValue bits) (O.phases bits)[i.val]:=by\n  simp only [banks,ordinal,List.getElem_map]\n/-- Original reference bytes are the literal i-th entry of the physically produced ordered vector. -/\ndef reference (bits:List Bool) (i:Fin (O.phases bits).length):List Bool:=\n  (O.references (O.phases bits).length)[i.val]'(by\n    simpa only [O.references,List.length_map,List.length_range] using i.isLt)\n/-- The actual issued byte word at chronological position i has exactly i unary markers. -/\ntheorem reference_eq (bits:List Bool) (i:Fin (O.phases bits).length):reference bits i=List.replicate i.val true:=by\n  simp only [reference,O.references,List.getElem_map,List.getElem_range]\n/-- The ENTIRE actual source reference output has its original chronological byte layout. -/\ntheorem output_references (bits:List Bool):E.result bits R.output=\n    SemiprimeD1TensorTapeCodec.vectorBits (List.ofFn (fun i:Fin (O.phases bits).length=>reference bits i)):=by\n  rw [Old.output_original]\n  simp only [reference_eq]\n  congr 1\n  unfold O.references\n  simpa only [List.length_range,List.getElem_range,Fin.val_cast] using\n    (List.ofFn_getElem_eq_map (List.range (O.phases bits).length) (fun n=>List.replicate n true)).symm\n/-- Genuine allocator transitions witness the exact physical original Root345 heap/counter history. -/\ntheorem root_history (bits:List Bool):SemiprimeD1StackHeapReadBounds.History (records (banks bits))\n    (E.result bits R.heap) (E.result bits (R.aux .counter)):=by\n  have h:=L.history (records (banks bits))\n  have hl:(records (banks bits)).length=(O.phases bits).length:=by\n    simp only [records,List.length_map,banks_length]\n  rw [hl] at h\n  rw [Old.heap_original,Old.counter_original,←records_original]\n  exact h\n/-- Actual source heap bytes match the complete chronological stored bank records. -/\ntheorem root_heap (bits:List Bool):E.result bits R.heap=SemiprimeD1StackHeapAllocate.heapBytes (records (banks bits)):=\n  (Old.heap_original bits).trans (congrArg SemiprimeD1StackHeapAllocate.heapBytes (records_original bits).symm)\n/-- Actual source counter is the literal original complete bank count. -/\ntheorem root_counter (bits:List Bool):E.result bits (R.aux .counter)=List.replicate (banks bits).length true:=by\n  rw [banks_length]\n  exact Old.counter_original bits\n/-- Every actual i-th output reference was physically issued and persists through subsequent allocations. -/\ntheorem root_issued (bits:List Bool) (i:Fin (O.phases bits).length):\n    SemiprimeD1StackHeapReadBounds.Issued (records (banks bits)) (reference bits i):=by\n  rw [reference_eq]\n  have h:=L.issued (records (banks bits)) (index (banks bits) (ordinal bits i))\n  exact h\n/-- Actual N-only producer execution and issued-reference lineage hold together for the SAME reached heap. -/\ntheorem producer_lineage (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<SemiprimeBitArithmetic.bitValue bits):\n    ∃q ≤ SemiprimeD1StackRootPhaseFreshRecordsExecution.runBound bits,\n      SemiprimeD1StackCalls.run R.program q (R.initial bits)=some (E.done bits) ∧\n      SemiprimeD1StackHeapReadBounds.History (records (banks bits))\n        (E.result bits R.heap) (E.result bits (R.aux .counter)) ∧\n      E.result bits R.output=SemiprimeD1TensorTapeCodec.vectorBits\n        (List.ofFn (fun i:Fin (O.phases bits).length=>reference bits i)) ∧\n      ∀i:Fin (O.phases bits).length,\n        SemiprimeD1StackHeapReadBounds.Issued (records (banks bits)) (reference bits i):=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootPhaseFreshRecordsExecution.source_run bits hc hN\n  exact ⟨q,hq,hr,root_history bits,output_references bits,root_issued bits⟩\n/-- Honest prepared consumer inputs are ONLY the actual reached heap/counter and its actual issued reference. -/\ndef initialRoot (bits:List Bool) (i:Fin (O.phases bits).length):C.State Stack Label:=\n  initial (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i)\n/-- Exact restored target contains ALL85 original stopped fields and ALL10 completed heap-reader roles. -/\ndef doneRoot (bits:List Bool) (i:Fin (O.phases bits).length):C.State Stack Label:=\n  done (E.freshResult (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)[i.val])\n    (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i)\n/-- Original actual operands match the complete physical generic source, with no supplied answer tape. -/\ntheorem initialRoot_eq (bits:List Bool) (i:Fin (O.phases bits).length):\n    initialRoot bits i=source (banks bits) (ordinal bits i):=by\n  exact initial_from (banks bits) (ordinal bits i) _ _ _ (root_heap bits) (root_counter bits) (reference_eq bits i)\n/-- Exact reached physical target is the original selected bank, including all rejected/empty caches. -/\ntheorem doneRoot_eq (bits:List Bool) (i:Fin (O.phases bits).length):doneRoot bits i=target (banks bits) (ordinal bits i):=by\n  exact done_from (banks bits) (ordinal bits i) _ _ _ _ (bank_at bits i).symm\n    (root_heap bits) (root_counter bits) (reference_eq bits i)\n/-- Exact whole physical-input byte bound of the original cache consumer. -/\ntheorem capRoot_eq (bits:List Bool) (i:Fin (O.phases bits).length):\n    1000*resource (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i)=\n      linearBound (banks bits) (ordinal bits i):=\n  cap_from (banks bits) (ordinal bits i) _ _ _ (root_heap bits) (root_counter bits) (reference_eq bits i)\n/-- SAME actual95-role consumer restores the original selected bank at its actual input-byte linear clock. -/\ntheorem source_original (bits:List Bool) (i:Fin (O.phases bits).length):\n    ∃q ≤1000*resource (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i),\n      SemiprimeD1StackCalls.run program q (initialRoot bits i)=some (doneRoot bits i):=by\n  obtain ⟨q,hq,hr⟩:=source_run_linear (banks bits) (ordinal bits i)\n  refine ⟨q,?_,?_⟩\n  · exact hq.trans (capRoot_eq bits i).ge\n  · exact (congrArg (SemiprimeD1StackCalls.run program q) (initialRoot_eq bits i)).trans\n      (hr.trans (congrArg some (doneRoot_eq bits i)).symm)\n/-- ALL95 tapes and real return cells at every original-input consumer prefix use the SAME physical byte cap. -/\ntheorem prefix_original (bits:List Bool) (i:Fin (O.phases bits).length) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (initialRoot bits i)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      100000*resource (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i):=by\n  have hr':SemiprimeD1StackCalls.run program fuel (source (banks bits) (ordinal bits i))=some out:=\n    (congrArg (SemiprimeD1StackCalls.run program fuel) (initialRoot_eq bits i)).symm.trans hr\n  have h:=prefix_cells (banks bits) (ordinal bits i) fuel out hr'\n  have hs:=resource_from (banks bits) (ordinal bits i) _ _ _ (root_heap bits) (root_counter bits) (reference_eq bits i)\n  exact h.trans (congrArg (fun n=>100000*n) hs).ge\n/-- Every original Fresh field is restored literally; OLD and NEW precision/context banks stay distinct. -/\ntheorem fresh_restored (bits:List Bool) (i:Fin (O.phases bits).length) (k:F.Stack):\n    (doneRoot bits i).data (freshStack k)=E.freshResult (O.exponentValue bits) (O.levelsValue bits)\n      (O.edgeValue bits) (O.phases bits)[i.val] k:=rfl\n/-- Every heap-reader role equals the real completed reader's preserved inputs and cleared private words. -/\ntheorem heap_retained (bits:List Bool) (i:Fin (O.phases bits).length) (k:H.Stack):\n    (doneRoot bits i).data (heapStack k)=H.input (E.result bits R.heap)\n      (E.result bits (R.aux .counter)) (reference bits i) k:=rfl\n/-- Genuine compiled95-role endpoint consumes the actual original issued bytes at its own source clock. -/\nnoncomputable def restoreOriginalInTime (bits:List Bool) (i:Fin (O.phases bits).length):\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initialRoot bits i))\n      (some (SemiprimeD1StackCalls.configuration (doneRoot bits i)))\n      (1000*resource (E.result bits R.heap) (E.result bits (R.aux .counter)) (reference bits i)):=by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (.inl .start) program\n  let h:=source_original bits i\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackFreshBankRestoreOriginal\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogueSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFullFactorCatalogueView\nimport RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual original-N setup of the retained-source full factor sweep -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogueSource\nopen SemiprimeD1StackFullFactorCatalogue SemiprimeD1StackFullFactorCatalogueView\nopen SemiprimeD1StackProcedureFragments (Runs included_call one_base)\nnamespace FS\nexport SemiprimeD1StackFactorScopeFibre (result)\nend FS\nnamespace VS\nexport SemiprimeD1StackVertexCatalogue (input initial)\nexport SemiprimeD1StackVertexCatalogueExecution (result done)\nend VS\n/-- Actual source retains original binary N, without normalization or re-encoding. -/\ntheorem retained_N (bits : List Bool) : FS.result bits [] F.originalInput=bits := by rfl\n/-- The actual catalogue initializer loads binary N in exactly its single input role. -/\ntheorem catalogue_input (bits : List Bool) (k : V.Stack) :\n    VS.input bits k=(if k=V.originalInput then bits else []) := by\n  have hi:=SemiprimeD1StackCalls.initial_correct V.originalInput catalogueOutput (.inl .main) V.program bits\n  have he:=hi.trans (SemiprimeD1StackVertexCatalogueExecution.initial_eq bits)\n  have hd:=congrArg (fun cfg:SemiprimeD1StackVertexCatalogue.machine.Cfg=>cfg.stk (some k)) he\n  exact hd.symm\n/-- Genuine physical data after the complete source and its first actual factor query. -/\ndef afterSource (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (fun _=>[]) (fun _=>[]) [] []\n/-- Genuine physical data after the real preserving binary-N copy. -/\ndef afterCopy (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.input bits) (fun _=>[]) [] []\n/-- Genuine physical data after all original descriptors are actually acquired. -/\ndef afterCatalogue (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.result bits) (fun _=>[]) [] []\n/-- The loop-ready data include the one physically pushed final false terminator. -/\ndef ready (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.result bits) (fun _=>[]) [] [false]\n/-- One real included call executes the source once and computes the first actual scope. -/\ntheorem source_call (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ SemiprimeD1StackFactorScopeFibreBounds.runBound bits [],\n      Runs program (t+1) (.local .main) (input bits) (.local .copyN) (afterSource bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackFactorScopeFibreExecution.source_run bits [] hb\n  refine ⟨t,ht.trans (SemiprimeD1StackFactorScopeFibreBounds.timeBound_le bits [] hb),?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program sourceStack Label.source Sum.inl_injective\n    F.program .main (fun _=>rfl) (.local .main) (.local .copyN) rfl t\n    (F.initial bits []) (SemiprimeD1StackFactorScopeFibre.done bits [])\n    (input bits) (afterSource bits) rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>unfold afterSource;rw [empty_outer];rfl\n/-- Original binary N is copied physically; no second N value is preloaded. -/\ntheorem copy_N (bits : List Bool) :\n    Runs program (5*bits.length+4) (.local .copyN) (afterSource bits) (.local .catalogue) (afterCopy bits) := by\n  apply included_call program copyStack Label.copy copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (.local .copyN) (.local .catalogue) rfl (5*bits.length+3)\n    (SemiprimeD1StackCopy.state 0 none bits [] []) (SemiprimeD1StackCopy.done bits bits)\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words bits [] none\n  · constructor\n    · intro k\n      fin_cases k\n      · exact retained_N bits\n      · rfl\n      · rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      fin_cases k\n      · exact retained_N bits\n      · change VS.input bits V.originalInput=bits\n        rw [catalogue_input,ite_eq_left rfl]\n      · rfl\n    · intro k hk\n      rcases k with k|k|k|k\n      · rfl\n      · have hn:k≠V.originalInput:=by intro h;subst k;exact hk 1 rfl\n        change VS.input bits k=[]\n        rw [catalogue_input,ite_eq_right hn]\n      · rfl\n      · rfl\n/-- The actual complete53-role original catalogue source runs after the paid N copy. -/\ntheorem catalogue_call (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ 10000000000000*(bits.length+1)^5,\n      Runs program (t+1) (.local .catalogue) (afterCopy bits) (.local .seed) (afterCatalogue bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackVertexCatalogueBounds.source_run_polynomial bits hb\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program catalogueStack Label.catalogue\n    (by intro a b h;exact Sum.inl_injective (Sum.inr_injective h)) V.program (.inl .main)\n    (fun _=>rfl) (.local .catalogue) (.local .seed) rfl t (VS.initial bits) (VS.done bits)\n    (afterCopy bits) (afterCatalogue bits) rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k|k|k\n      · rfl\n      · exact (hk k rfl).elim\n      · rfl\n      · rfl\n/-- The record terminator is one actual allocated false bit on the physical output. -/\ntheorem seed_run (bits : List Bool) :\n    Runs program 1 (.local .seed) (afterCatalogue bits) (.local .loop) (ready bits) := by\n  apply one_base program (.local .seed) (.local .loop) (.push output false (.local .loop)) _ _ rfl\n  · rfl\n  · exact update_output _ _ _ _ _ _ _\n/-- Own setup clock includes the source/filter, N copy, catalogue and false push. -/\ndef setupBound (bits : List Bool) : Nat :=\n  SemiprimeD1StackFactorScopeFibreBounds.runBound bits []+10000000000000*(bits.length+1)^5+5*bits.length+7\n/-- Complete original-N setup trace, before the separately required descriptor loop. -/\ntheorem setup_run (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ setupBound bits,Runs program t (.local .main) (input bits) (.local .loop) (ready bits) := by\n  obtain ⟨s,hs,h0⟩:=source_call bits hb\n  have h1:=copy_N bits\n  obtain ⟨c,hc,h2⟩:=catalogue_call bits hb\n  have h3:=seed_run bits\n  refine ⟨(s+1)+((5*bits.length+4)+((c+1)+1)),?_,h0.trans (h1.trans (h2.trans h3))⟩\n  unfold setupBound\n  omega\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogueSource\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogueView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFullFactorCatalogue\n/-! # Complete physical views of shared N/scope and actual five-field inputs -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 3000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 1000000\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogueView\nopen SemiprimeD1StackFullFactorCatalogue\n/-- Original binary N followed by the five acquired raw descriptor fields, proof notation only. -/\ndef raw (bits:List Bool) (words:Fin 5→List Bool) :Fin 6→List Bool:=\n  ![bits,words 0,words 1,words 2,words 3,words 4]\n/-- Actual original descriptor catalogue output role. -/\ndef catalogueOutput :V.Stack:=V.kernelStack (SemiprimeD1StackCartesian4.aux 2)\n/-- Complete1454-role store with BOTH unused N/scope shadows empty and real validity bytes. -/\ndef data (fibre:F.Stack→List Bool) (catalogue:V.Stack→List Bool) (words:Fin 5→List Bool)\n    (hist out:List Bool) (validBytes:List Bool:=[]) :Stack→List Bool:=\n  Sum.elim fibre (Sum.elim catalogue (Sum.elim (D.cleanData (raw [] words) [] hist out) (fun _=>validBytes)))\n/-- Actual retained source projection, with no normalization of its acquired metadata. -/\ntheorem data_source (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) (k:F.Stack) :data f v w hist out flag (sourceStack k)=f k:=rfl\n/-- Actual original descriptor catalogue projection. -/\ntheorem data_catalogue (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) (k:V.Stack) :data f v w hist out flag (catalogueStack k)=v k:=rfl\n/-- The record source reads actual N and scope DIRECTLY from the physical source. -/\ntheorem data_descriptor (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) (k:D.Stack) :\n    data f v w hist out flag (descriptorStack k)=D.cleanData (raw (f F.originalInput) w) (f F.output) hist out k:=by\n  cases k with\n  | inl k=>\n    cases k with\n    | source i=>fin_cases i <;> rfl\n    | bank | history | output | tagReader | copyScratch=>rfl\n  | inr k=>rfl\n/-- The actual tag and coordinate cache holds exactly the physically parsed field. -/\ntheorem data_cache (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) (i:Fin 5) :data f v w hist out flag (cache i)=w i:=by\n  rw [cache_private]\n  fin_cases i <;> rfl\n/-- The actual parser validity word is separate from every source and work role. -/\ntheorem data_valid (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) :data f v w hist out flag valid=flag:=rfl\n/-- Both reusable parser/N-copy work words are physically empty at interfaces. -/\ntheorem data_scratch (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) :data f v w hist out flag scratch=[]:=rfl\n/-- Actual reverse logger operands; both unused consuming fields are genuinely empty. -/\ntheorem data_logger (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag:List Bool) (k:Log.Stack) :\n    data f v w hist out flag (loggerStack k)=SemiprimeD1StackVertexRecordStream.data [] [] hist out k:=by\n  cases k <;> rfl\n/-- Physical source writes preserve catalogue, fields, accumulators and validity bytes. -/\ntheorem update_source (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) (k:F.Stack) :\n    Function.update (data f v w hist out flag) (sourceStack k) value=\n      data (Function.update f k value) v w hist out flag:=by\n  unfold data sourceStack\n  rw [Sum.update_elim_inl]\n/-- Actual descriptor consumption changes exactly the catalogue reader suffix. -/\ntheorem update_catalogue (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) (k:V.Stack) :\n    Function.update (data f v w hist out flag) (catalogueStack k) value=\n      data f (Function.update v k value) w hist out flag:=by\n  unfold data catalogueStack\n  rw [Sum.update_elim_inr,Sum.update_elim_inl]\n/-- Actual one-field write/erasure preserves N, binary scope and every other original field. -/\ntheorem raw_update (w:Fin 5→List Bool) (hist out value:List Bool) (i:Fin 5) :\n    Function.update (D.cleanData (raw [] w) [] hist out) (D.source (fieldPart i)) value=\n      D.cleanData (raw [] (Function.update w i value)) [] hist out:=by\n  funext k\n  cases k with\n  | inl k=>\n    cases k with\n    | source j=>fin_cases i <;> fin_cases j <;> rfl\n    | bank | history | output | tagReader | copyScratch=>rfl\n  | inr k=>rfl\n/-- Real parser writes and drains act only on their one actual field cache. -/\ntheorem update_cache (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) (i:Fin 5) :\n    Function.update (data f v w hist out flag) (cache i) value=\n      data f v (Function.update w i value) hist out flag:=by\n  rw [cache_private]\n  unfold data\n  rw [Sum.update_elim_inr,Sum.update_elim_inr,Sum.update_elim_inl,raw_update]\n/-- Actual validity push/pop changes only its single allocated Unit role. -/\ntheorem update_valid (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) :\n    Function.update (data f v w hist out flag) valid value=data f v w hist out value:=by\n  unfold data valid\n  rw [Sum.update_elim_inr,Sum.update_elim_inr,Sum.update_elim_inr]\n  congr 1\n/-- Actual history write in the clean descriptor block, before including other source inventories. -/\ntheorem raw_history (w:Fin 5→List Bool) (hist out value:List Bool) :\n    Function.update (D.cleanData (raw [] w) [] hist out) D.history value=\n      D.cleanData (raw [] w) [] value out:=by\n  funext k;cases k with\n  | inl k=>cases k <;> rfl\n  | inr k=>rfl\n/-- Actual final-output write in the clean descriptor block. -/\ntheorem raw_output (w:Fin 5→List Bool) (hist out value:List Bool) :\n    Function.update (D.cleanData (raw [] w) [] hist out) D.output value=\n      D.cleanData (raw [] w) [] hist value:=by\n  funext k;cases k with\n  | inl k=>cases k <;> rfl\n  | inr k=>rfl\n/-- Physical history writes change no acquired source, raw descriptor or caller output byte. -/\ntheorem update_history (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) :\n    Function.update (data f v w hist out flag) history value=data f v w value out flag:=by\n  change Function.update (data f v w hist out flag) (.inr (.inr (.inl D.history))) value=_\n  unfold data\n  rw [Sum.update_elim_inr,Sum.update_elim_inr,Sum.update_elim_inl,raw_history]\n/-- Actual sentinel/final reversal writes only the shared output accumulator. -/\ntheorem update_output (f:F.Stack→List Bool) (v:V.Stack→List Bool) (w:Fin 5→List Bool)\n    (hist out flag value:List Bool) :\n    Function.update (data f v w hist out flag) output value=data f v w hist value flag:=by\n  change Function.update (data f v w hist out flag) (.inr (.inr (.inl D.output))) value=_\n  unfold data\n  rw [Sum.update_elim_inr,Sum.update_elim_inr,Sum.update_elim_inl,raw_output]\n/-- No descriptor, scope, validity or output sentinel is supplied at original initialization. -/\ntheorem empty_outer (f:F.Stack→List Bool) :data f (fun _=>[]) (fun _=>[]) [] []=Sum.elim f (fun _=>[]):=by\n  funext k;rcases k with k|k|k|k\n  · rfl\n  · rfl\n  · cases k with\n    | inl k=>cases k with\n      | source i=>fin_cases i <;> rfl\n      | bank | history | output | tagReader | copyScratch=>rfl\n    | inr k=>rfl\n  · rfl\n/-- Standard binary-only initialization is the exact empty-work physical store. -/\ntheorem input_data (bits:List Bool) :input bits=data (F.initial bits []).data (fun _=>[]) (fun _=>[]) [] []:=by\n  rw [empty_outer];rfl\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogueView\n","RiemannGaussian.SemiprimeD1StackIncrement":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldMachine\nimport RiemannGaussian.SemiprimeBitArithmetic\n\n/-! # Fixed-width physical increment with overflow\nA fixed finite-control machine consumes an arbitrary little-endian Boolean word\nand returns its overflow bit followed by an equally wide wrapped word. All\nlength/value arithmetic below is specification/proof data, never machine state.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackIncrement\nopen Turing Turing.TM2 Turing.TM2.Stmt\nopen SemiprimeBitArithmetic (bitValue bitNat)\nopen SemiprimeD1TensorTapeFieldMachine (Stack Alphabet Registers contents)\n\n/-- The four fixed carry/copy/output phases. -/\ninductive PC | carry | copy | reverse | finish deriving DecidableEq,Inhabited,Repr\ninstance : Fintype PC where\n  elems := {.carry,.copy,.reverse,.finish}\n  complete := by intro k; cases k <;> simp\n\n/-- Actual little-endian wrapped word, used only in specifications. -/\ndef wrapped : List Bool → List Bool\n  | [] => []\n  | false::xs => true::xs\n  | true::xs => false::wrapped xs\n\n/-- Carry leaving the most significant bit, including overflow at width zero. -/\ndef overflow : List Bool → Bool\n  | [] => true\n  | false::_ => false\n  | true::xs => overflow xs\n\n/-- Actual fixed stack program: no arithmetic or native length operation. -/\ndef program : PC → Stmt Alphabet PC Registers\n  | .carry => .pop .input (fun _ b => (b,false))\n      (.branch (fun v => v.1.isSome)\n        (.branch (fun v => v.1==some true)\n          (.push .scratch (fun _ => false) (.goto (fun _ => .carry)))\n          (.push .scratch (fun _ => true) (.goto (fun _ => .copy))))\n        (.load (fun _ => (none,true)) (.goto (fun _ => .reverse))))\n  | .copy => .pop .input (fun _ b => (b,false))\n      (.branch (fun v => v.1.isSome)\n        (.push .scratch (fun v => v.1.getD false) (.goto (fun _ => .copy)))\n        (.goto (fun _ => .reverse)))\n  | .reverse => .pop .scratch (fun v b => (b,v.2))\n      (.branch (fun v => v.1.isSome)\n        (.push .output (fun v => v.1.getD false) (.goto (fun _ => .reverse)))\n        (.goto (fun _ => .finish)))\n  | .finish => .push .output (fun v => v.2) .halt\n\n/-- Genuine finite-alphabet machine, with only six finite register settings. -/\ndef machine : FinTM2 where\n  K := Stack\n  k₀ := .input\n  k₁ := .output\n  Γ := Alphabet\n  Λ := PC\n  main := .carry\n  σ := Registers\n  initialState := (none,false)\n  m := program\n\n/-- Literal configurations of its three Boolean stacks. -/\ndef cfg (pc : Option PC) (v : Registers) (input scratch output : List Bool) :\n    Cfg Alphabet PC Registers := ⟨pc,v,contents input scratch output⟩\n\n/-- Actual primitive transition function. -/\ndef step := TM2.step program\n\n/-- Exact transition paths; the count exists only in the proof. -/\ninductive Executes : ℕ → Cfg Alphabet PC Registers → Cfg Alphabet PC Registers → Prop\n  | refl (c) : Executes 0 c c\n  | next {n c d e} : step c=some d → Executes n d e → Executes (n+1) c e\n\n/-- Concatenate actual executions. -/\ntheorem Executes.trans {n m : ℕ} {a b c : Cfg Alphabet PC Registers}\n    (h : Executes n a b) (g : Executes m b c) : Executes (n+m) a c := by\n  induction h with\n  | refl => simpa using g\n  | @next n a d b hs ht ih =>\n    simpa only [Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using Executes.next hs (ih g)\n\n/-- Actual Mathlib iterate equation for every proved path. -/\ntheorem Executes.iterates {n : ℕ} {a b : Cfg Alphabet PC Registers} (h : Executes n a b) :\n    ((fun x : Option (Cfg Alphabet PC Registers) => x.bind step)^[n]) (some a)=some b := by\n  induction h with\n  | refl => rfl\n  | @next n a d b hs ht ih =>\n    rw [Function.iterate_succ_apply]\n    simpa only [Option.bind_some,hs] using ih\n\n/-- Copy the high suffix after carry has terminated. -/\ntheorem copy_exec (v : Registers) (xs rev out : List Bool) :\n    Executes (xs.length+1) (cfg (some .copy) v xs rev out)\n      (cfg (some .reverse) (none,false) [] (xs.reverse++rev) out) := by\n  induction xs generalizing v rev with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .copy) v (b::bs) rev out)=\n        some (cfg (some .copy) (some b,false) bs (b::rev) out) := by\n      simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using Executes.next hs (ih (some b,false) (b::rev))\n\n/-- Actual carry scan produces the wrapped bytes and the actual overflow flag. -/\ntheorem carry_exec (v : Registers) (xs rev out : List Bool) :\n    Executes (xs.length+1) (cfg (some .carry) v xs rev out)\n      (cfg (some .reverse) (none,overflow xs) [] ((wrapped xs).reverse++rev) out) := by\n  induction xs generalizing v rev with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackIncrement.step,program,cfg,contents,wrapped,overflow,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    cases b with\n    | false =>\n      have hs : step (cfg (some .carry) v (false::bs) rev out)=\n          some (cfg (some .copy) (some false,false) bs (true::rev) out) := by\n        simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n      simpa [wrapped,overflow,List.reverse_cons,List.append_assoc] using\n        Executes.next hs (copy_exec (some false,false) bs (true::rev) out)\n    | true =>\n      have hs : step (cfg (some .carry) v (true::bs) rev out)=\n          some (cfg (some .carry) (some true,false) bs (false::rev) out) := by\n        simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n      simpa [wrapped,overflow,List.reverse_cons,List.append_assoc] using\n        Executes.next hs (ih (some true,false) (false::rev))\n\n/-- Physical reversal preserves the finite overflow flag. -/\ntheorem reverse_exec (v : Registers) (rev out : List Bool) :\n    Executes (rev.length+1) (cfg (some .reverse) v [] rev out)\n      (cfg (some .finish) (none,v.2) [] [] (rev.reverse++out)) := by\n  induction rev generalizing v out with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have hs : step (cfg (some .reverse) v [] (b::bs) out)=\n        some (cfg (some .reverse) (some b,v.2) [] bs (b::out)) := by\n      simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using Executes.next hs (ih (some b,v.2) (b::out))\n\n/-- Wrapped width is EXACTLY the original width, including zero. -/\ntheorem wrapped_length (xs : List Bool) : (wrapped xs).length=xs.length := by\n  induction xs with\n  | nil => rfl\n  | cons b bs ih => cases b <;> simp [wrapped,ih]\n\n/-- Overflow is precisely the all-one condition, vacuously true at width zero. -/\ntheorem overflow_iff (xs : List Bool) : overflow xs=true ↔ ∀b∈xs,b=true := by\n  induction xs with\n  | nil => simp [overflow]\n  | cons b bs ih => cases b <;> simp [overflow,ih]\n\n/-- The emitted overflow agrees with the literal all-true Boolean test. -/\ntheorem overflow_eq_all (xs : List Bool) : overflow xs=xs.all id := by\n  induction xs with\n  | nil => rfl\n  | cons b bs ih => cases b <;> simp [overflow,ih]\n\n/-- Exact integer balance proves both wraparound and the emitted carry. -/\ntheorem value_balance (xs : List Bool) :\n    bitValue (wrapped xs)+2^xs.length*bitNat (overflow xs)=bitValue xs+1 := by\n  induction xs with\n  | nil => simp [wrapped,overflow,bitValue,bitNat]\n  | cons b bs ih =>\n    cases b <;> cases ho : overflow bs <;>\n      simp [wrapped,overflow,bitValue,bitNat,ho,pow_succ] at * <;> omega\n\n/-- Mathematical modular meaning of the actual fixed-width bytes. -/\ntheorem wrapped_value (xs : List Bool) : bitValue (wrapped xs)=(bitValue xs+1)%2^xs.length := by\n  have hb := value_balance xs\n  have hw := SemiprimeBitArithmetic.bitValue_lt_width (wrapped xs)\n  rw [wrapped_length] at hw\n  rw [←hb,Nat.add_mod]\n  simp [Nat.mod_eq_of_lt hw]\n\n/-- Entire literal output, exact length and transition count; old output tail retained. -/\ntheorem increment_exec (xs out : List Bool) :\n    Executes (2*xs.length+3) (cfg (some .carry) (none,false) xs [] out)\n      (cfg none (none,overflow xs) [] [] (overflow xs::(wrapped xs++out))) := by\n  have hc := carry_exec (none,false) xs [] out\n  have hr := reverse_exec (none,overflow xs) ((wrapped xs).reverse++[]) out\n  have hf : step (cfg (some .finish) (none,overflow xs) [] [] (wrapped xs++out))=\n      some (cfg none (none,overflow xs) [] [] (overflow xs::(wrapped xs++out))) := by\n    simp [SemiprimeD1StackIncrement.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  have h := hc.trans (hr.trans (by simpa using Executes.next hf (Executes.refl _)))\n  simp only [List.append_nil,List.length_reverse,wrapped_length] at h\n  convert h using 1\n  omega\n\n/-- Genuine actual transition-time certificate, not an annotated scalar clock. -/\ndef incrementInTime (xs out : List Bool) :\n    StateTransition.EvalsToInTime machine.step (cfg (some .carry) (none,false) xs [] out)\n      (some (cfg none (none,overflow xs) [] [] (overflow xs::(wrapped xs++out)))) (2*xs.length+3) :=\n  ⟨⟨_,(increment_exec xs out).iterates⟩,le_rfl⟩\n\n/-- The official input initialization acquires only the actual input word. -/\ntheorem init_eq (xs : List Bool) : Turing.initList machine xs=\n    cfg (some .carry) (none,false) xs [] [] := by\n  unfold Turing.initList cfg\n  dsimp only [machine]\n  congr 1\n  funext k\n  cases k <;> rfl\n\n/-- Actual official bundled-machine certificate from its one Boolean-word input. -/\ndef bundledInTime (xs : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine xs)\n      (some (cfg none (none,overflow xs) [] [] (overflow xs::wrapped xs))) (2*xs.length+3) := by\n  rw [init_eq]\n  simpa using incrementInTime xs []\n\n/-- Every stack alphabet has exactly two physical symbols. -/\ntheorem alphabet_card (k : Stack) : Fintype.card (Alphabet k)=2 := by\n  change Fintype.card Bool=2\n  decide\n\n/-- Finite registers have only six settings, independent of every width. -/\ntheorem registers_card : Fintype.card Registers=6 := by decide\n\n/-- Static elementary stack/control syntax depth. -/\ndef instructionDepth : Stmt Alphabet PC Registers → ℕ\n  | .push _ _ q => 1+instructionDepth q\n  | .peek _ _ q => 1+instructionDepth q\n  | .pop _ _ q => 1+instructionDepth q\n  | .load _ q => 1+instructionDepth q\n  | .branch _ q r => 1+max (instructionDepth q) (instructionDepth r)\n  | .goto _ => 1\n  | .halt => 1\n\n/-- A transition contains at most five elementary stack/control syntax nodes. -/\ntheorem program_depth (pc : PC) : instructionDepth (program pc)≤5 := by\n  cases pc <;> decide\n\n/-- Every jump stays within the same fixed four-label catalogue. -/\ntheorem program_supports : TM2.Supports program Finset.univ := by\n  constructor\n  · simp\n  · intro pc hpc\n    cases pc <;> simp [program,TM2.SupportsStmt]\n\n/-- Total unbounded data in all actual Boolean stacks. -/\ndef cells (c : Cfg Alphabet PC Registers) : ℕ :=\n  (c.stk Stack.input).length+(c.stk Stack.scratch).length+(c.stk Stack.output).length\n\n/-- Every actual instruction creates at most one Boolean cell. -/\ntheorem step_cells (c d : Cfg Alphabet PC Registers) (h : step c=some d) :\n    cells d≤cells c+1 := by\n  rcases c with ⟨pc,⟨flag,carry⟩,store⟩\n  cases pc with\n  | none => simp [SemiprimeD1StackIncrement.step,TM2.step] at h\n  | some pc =>\n    cases pc <;>\n      simp [SemiprimeD1StackIncrement.step,TM2.step,program,TM2.stepAux,\n        Bool.cond_eq_ite,Function.update] at h <;>\n      (try split_ifs at h) <;> cases h <;> simp [cells,Function.update] <;> omega\n\n/-- All actual intermediate paths have derived storage, not only final output. -/\ntheorem path_cells {n : ℕ} {c d : Cfg Alphabet PC Registers} (h : Executes n c d) :\n    cells d≤cells c+n := by\n  induction h with\n  | refl => omega\n  | @next n c e d hs ht ih =>\n    have hh := step_cells c e hs\n    omega\n\n/-- Linear all-prefix Boolean storage, including physical copy/reversal scratch. -/\ntheorem increment_cells (xs out : List Bool) (n : ℕ) (c : Cfg Alphabet PC Registers)\n    (h : Executes n (cfg (some .carry) (none,false) xs [] out) c)\n    (hn : n≤2*xs.length+3) : cells c≤3*xs.length+out.length+3 := by\n  have hh := path_cells h\n  simp only [cells,cfg,contents,List.length_nil,Nat.add_zero] at hh\n  unfold cells\n  omega\n\nend RiemannGaussian.SemiprimeD1StackIncrement\n","RiemannGaussian.SemiprimeD1StackInputDescriptorRecordOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackInputDescriptorRecordBounds\n/-! # Exact old input row from the actual retained six-field descriptor\nThe N and descriptor/scope acquisitions are explicit upstream caller work.\nThis actual loader consumes their physical bytes, constructs no advised cache,\nand returns the entire original row in unchanged chronological port order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackInputDescriptorRecordOriginal\nopen SemiprimeD1StackInputDescriptorRecord SemiprimeD1StackInputDescriptorRecordExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (idAt)\nend Bank\nnamespace Log\nexport SemiprimeD1StackVertexRecordStreamExecution (rows history)\nend Log\n/-- Exact old input vertex with the caller's unchanged ordered numeric scope. -/\nabbrev vertex :=SemiprimeD1StackPublicInputRecordOriginal.vertex\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (side : Fin 2) (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n  (indexWord : List Bool) (hi : indexWord.length=i.val) (M : Nat) (ports : List Nat)\n  (hp : ∀j∈ports,j<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.input side i):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hi hp\n/-- Actual newly loaded input row bytes are exactly the frozen entire old input\nrecord, including complete original tensor framing and unary numeric ports. -/\ntheorem record_bytes_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicInputTableExecution.table bits indexWord (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.input side i)) ports hlen::rest) :=\n  SemiprimeD1StackPublicInputRecordOriginal.record_bytes_original bits hc hN side i indexWord hi M ports hp hlen rest\n/-- Actual physical descriptor initialization followed by the actual record\ncall preserves every previous row in its original chronological order. -/\ntheorem history_original (tag coord0 coord2 coord3 : List Bool)\n    (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done (fields bits tag coord0 indexWord coord2 coord3) (ports.map (Bank.idAt M))\n      (Log.history previous old) out).data D.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen]) old := by\n  change (done _ _ _ _).data (D.recordStack SemiprimeD1StackPublicInputRecord.G.history)=_\n  rw [component_done]\n  exact SemiprimeD1StackPublicInputRecordOriginal.history_original bits hc hN side i indexWord hi M ports hp hlen previous old out\n/-- One final actual logger reversal emits exactly the forward old record list\nand final false tag, retaining the caller's final output suffix. -/\ntheorem reverse_original (tag coord0 coord2 coord3 : List Bool)\n    (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done (fields bits tag coord0 indexWord coord2 coord3) (ports.map (Bank.idAt M))\n          (Log.history previous []) (false::out)).data D.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen])++out)⟩ := by\n  rw [history_original bits hc hN side i indexWord hi M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- Complete real source trace and exact old chronological record, from ONLY\nactual six acquired fields, acquired numeric scope, caller words and erased dirty template. -/\ntheorem source_run_original (oldTemplate : Checker→List Bool) (tag coord0 coord2 coord3 : List Bool)\n    (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound oldTemplate (fields bits tag coord0 indexWord coord2 coord3)\n      (ports.map (Bank.idAt M)) (Log.history previous old) out,∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial oldTemplate (fields bits tag coord0 indexWord coord2 coord3)\n          (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M))) (Log.history previous old) out)=some finish ∧\n      finish=done (fields bits tag coord0 indexWord coord2 coord3) (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data D.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen]) old := by\n  have hb:bits≠[]:=by intro he;subst bits;exact (Nat.not_lt_zero _ hN).elim\n  obtain ⟨t,ht,hr⟩:=source_run oldTemplate (fields bits tag coord0 indexWord coord2 coord3) hb\n    (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_original bits hc hN side i indexWord hi M ports hp hlen tag coord0 coord2 coord3 previous old out⟩\nend RiemannGaussian.SemiprimeD1StackInputDescriptorRecordOriginal\n","RiemannGaussian.SemiprimeD1StackInputVertices":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackTransformBounds\nimport RiemannGaussian.SemiprimeD1StackValidationLink\nimport RiemannGaussian.SemiprimeD1StackFrame\n\n/-! # Actual tagged input-vertex acquisition\nThe original Cartesian family Fin2×FinR is materialized as literal framed\nconstructor/side/index records. Only retained original metadata are read.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackInputVertices\nnamespace Meta\nexport SemiprimeD1StackTransform (Stack Label program input initial)\nend Meta\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace LinkB\nexport SemiprimeD1StackMultiplierLink (instruction DataRel data_unique Rel run_rel)\nend LinkB\nnamespace LinkC\nexport SemiprimeD1StackValidationLink (instruction Rel run_rel)\nend LinkC\n/-- Original metadata plus framed output and physical frame scratch. -/\nabbrev Stack := Meta.Stack⊕Bool\n/-- Fixed control for both actual input-vertex sides and six record-tag pushes. -/\ninductive Local where\n  | start | halt\n  | ready (side:Bool) | copyIndex (side:Bool) | dropRemaining (side:Bool) | dropIndex (side:Bool)\n  | emit (side:Bool) | check (side:Bool) | dec (side:Bool) | tag (side:Bool) (pc:Fin 6)\n  deriving DecidableEq,Repr\n/-- Exhaustive static local instruction catalogue. -/\ninstance : Fintype Local where\n  elems:={.start,.halt}∪Finset.univ.image Local.ready∪Finset.univ.image Local.copyIndex∪\n    Finset.univ.image Local.dropRemaining∪Finset.univ.image Local.dropIndex∪\n    Finset.univ.image Local.emit∪Finset.univ.image Local.check∪Finset.univ.image Local.dec∪\n    Finset.univ.image (fun x:Bool×Fin 6=>Local.tag x.1 x.2)\n  complete:=by intro pc;cases pc <;> simp\n/-- Static metadata, two Copy instances, and the real Frame code. -/\nabbrev Label := Local⊕(Meta.Label⊕((Bool×Fin 9)⊕Fin 11))\n/-- Original metadata label inclusion. -/\ndef metaLabel (pc:Meta.Label) : Label := .inr (.inl pc)\n/-- Copy radius to remaining or current-index work. -/\ndef copyOutput (mode:Bool) : Stack := .inl (if mode then .thresholdWork else .squareWork)\n/-- Real disjoint Copy roles. -/\ndef copyStack (mode:Bool) (k:Fin 3) : Stack :=\n  if k=0 then .inl .radius else if k=1 then copyOutput mode else .inl .temporary\n/-- Fixed Copy labels. -/\ndef copyLabel (mode:Bool) (pc:Fin 9) : Label := .inr (.inr (.inl (mode,pc)))\n/-- Current physical index, output tape, and actual frame scratch. -/\ndef frameStack (k:Fin 3) : Stack :=\n  if k=0 then .inl .thresholdWork else if k=1 then .inr false else .inr true\n/-- Static actual Frame instruction labels. -/\ndef frameLabel (pc:Fin 11) : Label := .inr (.inr (.inr pc))\n/-- Both side blocks are prepended in reverse outer order to produce original Fin2 order. -/\ndef afterSide (side:Bool) : Label := if side then .inl (.ready false) else .inl .halt\n/-- One fixed program builds actual constructor/side/index records. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inl pc) => LinkC.instruction Sum.inl metaLabel (Meta.program pc)\n  | .inr (.inr (.inl (mode,pc))) => LinkB.instruction (copyStack mode) (copyLabel mode) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr (.inr pc)) => LinkB.instruction frameStack frameLabel (SemiprimeD1StackFrame.code pc)\n  | .inl .start => .call (metaLabel (.inl .start)) (.inl (.ready true))\n  | .inl (.ready side) => .call (copyLabel false 0) (.inl (.copyIndex side))\n  | .inl (.copyIndex side) => .call (copyLabel true 0) (.inl (.dropRemaining side))\n  | .inl (.dropRemaining side) => .base (.pop (.inl .squareWork) (afterSide side) (.inl (.dropIndex side)) (.inl (.dropIndex side)))\n  | .inl (.dropIndex side) => .base (.pop (.inl .thresholdWork) (.inl (.emit side)) (.inl (.emit side)) (.inl (.emit side)))\n  | .inl (.emit side) => .call (frameLabel 0) (.inl (.tag side 0))\n  | .inl (.tag side pc) =>\n      if pc=0 then .base (.push (.inr false) false (.inl (.tag side 1)))\n      else if pc=1 then .base (.push (.inr false) side (.inl (.tag side 2)))\n      else if pc=2 then .base (.push (.inr false) true (.inl (.tag side 3)))\n      else if pc=3 then .base (.push (.inr false) false (.inl (.tag side 4)))\n      else if pc=4 then .base (.push (.inr false) false (.inl (.tag side 5)))\n      else .base (.push (.inr false) true (.inl (.check side)))\n  | .inl (.check side) => .base (.pop (.inl .squareWork) (afterSide side) (.inl (.dec side)) (.inl (.dec side)))\n  | .inl (.dec side) => .base (.pop (.inl .thresholdWork) (.inl (.emit side)) (.inl (.emit side)) (.inl (.emit side)))\n  | .inl .halt => .base .halt\n/-- Fixed finite original-input machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inl .input) (.inr false) (.inl .start) program\n/-- The only supplied input is original binary N. -/\ndef input (bits:List Bool) : Stack→List Bool := Sum.elim (Meta.input bits) (fun _=>[])\n/-- Actual unprepared initial state. -/\ndef initial (bits:List Bool) : C.State Stack Label := ⟨some (.inl .start),none,none,input bits,[]⟩\n/-- Both Copy operands are pairwise disjoint. -/\ntheorem copyStack_injective (mode:Bool) : Function.Injective (copyStack mode) := by cases mode <;> decide\n/-- The Frame operand map is injective. -/\ntheorem frameStack_injective : Function.Injective frameStack := by decide\n/-- Thirteen fixed Boolean data stacks. -/\ntheorem stack_card : Fintype.card Stack=13 := by decide\n/-- One hundred fifty-six fixed control labels. -/\ntheorem label_card : Fintype.card Label=156 := by decide\n/-- All alphabets are finite, including every return-tag symbol. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inl .input) (.inr false) (.inl .start) program\nend RiemannGaussian.SemiprimeD1StackInputVertices\n","RiemannGaussian.SemiprimeD1StackJetBlocks":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetContextBounds\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackReverseWord\nimport RiemannGaussian.SemiprimeD1StackAssignmentBody\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nimport RiemannGaussian.SemiprimeD1JetBlockBits\n/-! # Sequential actual fresh-axis coefficient blocks from an acquired context\nThe whole source REAL-acquires the old context from its unary-axis header and\nbinary precision. The same ready entry reuses the EXACTactual context cache.\nActual q markers and the actual retained rank word drive the outer/inner loops;\ncoefficient fields are copied in one forward scan, with literal empty-word\npadding after source EOF. No rank, offset, block getter or coefficient answer\nis a control operand. Old/new precision equality is never required: coefficients\nare copied unchanged and extraction uses only the old axes/rank.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackJetBlocks\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace X\nexport SemiprimeD1StackJetContext (Stack Label program initial axesCache precisionBits rankCache)\nend X\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\nnamespace Body\nexport SemiprimeD1StackAssignmentBody (Stack Label code entry)\nend Body\n/-- All actual retained vector/q inputs and per-field/per-block/logging words. -/\ninductive Aux where\n  | coefficients | blocks | todo | reader | rankTodo | word | fieldScratch | valid | copyScratch\n  | frameBuffer | frameScratch | rowHistory | row | logScratch | history | output\n  deriving DecidableEq,Repr\ninstance :Fintype Aux :=Fintype.ofList\n  [.coefficients,.blocks,.todo,.reader,.rankTodo,.word,.fieldScratch,.valid,.copyScratch,.frameBuffer,\n    .frameScratch,.rowHistory,.row,.logScratch,.history,.output] (by intro k;cases k <;> simp)\n/-- All15actual context words and16actual new source/loop/output words. -/\nabbrev Stack :=X.Stack⊕Aux\n/-- Actual old-context cache inclusion, retained literally during the entire block traversal. -/\ndef contextStack :X.Stack→Stack :=Sum.inl\n/-- Actual local word inclusion. -/\ndef aux :Aux→Stack :=Sum.inr\n/-- Three real preserving-copy operand choices. -/\ninductive Copy where | blocks | vector | rank deriving DecidableEq\ninstance :Fintype Copy :=Fintype.ofList [.blocks,.vector,.rank] (by intro k;cases k <;> simp)\n/-- q is copied once, coefficients once, and the ACTUALacquired rank markers once per emitted block. -/\ndef copyStack (part:Copy) (k:Fin 3) :Stack :=\n  if k=0 then match part with | .blocks=>aux .blocks | .vector=>aux .coefficients | .rank=>contextStack X.rankCache\n  else if k=1 then match part with | .blocks=>aux .todo | .vector=>aux .reader | .rank=>aux .rankTodo\n  else aux .copyScratch\n/-- Real coefficient field parsing; a zero coefficient is still a tagged empty field. -/\ndef fieldStack :Field.Stack→Stack\n  | .inl .input=>aux .reader | .inl .scratch=>aux .fieldScratch | .inl .output=>aux .word | .inr _=>aux .valid\n/-- Every coefficient's raw binary bytes are preserved by the real Frame routine. -/\ndef frameStack (k:Fin 3) :Stack :=if k=0 then aux .word else if k=1 then aux .frameBuffer else aux .frameScratch\n/-- Actual field-to-block, block-completion and final chronological-output reversals. -/\ninductive Reverse where | field | row | output deriving DecidableEq\ninstance :Fintype Reverse :=Fintype.ofList [.field,.row,.output] (by intro k;cases k <;> simp)\n/-- All actual source/destination reversal pairs are distinct. -/\ndef reverseStack (part:Reverse) (k:Fin 2) :Stack :=\n  if k=0 then match part with | .field=>aux .frameBuffer | .row=>aux .rowHistory | .output=>aux .history\n  else match part with | .field=>aux .rowHistory | .row=>aux .row | .output=>aux .output\n/-- The real outer row logger preserves and frames the actual completed block vector. -/\ndef bodyStack :Body.Stack→Stack\n  | .word=>aux .row | .scratch=>aux .logScratch | .history=>aux .history\n/-- Fixed actual context/copy/q/rank/parser/frame/log/cleanup control. -/\ninductive Control where\n  | start | ready | copyVector | outer | copyRank | inner | peek | tag | field | valid | frame | fieldTag | fieldReverse\n  | clearWord | rowSeed | rowReverse | logRow | clearRow | finishSeed | outputReverse | clearReader | done | abort\n  deriving DecidableEq\ninstance :Fintype Control :=Fintype.ofList\n  [.start,.ready,.copyVector,.outer,.copyRank,.inner,.peek,.tag,.field,.valid,.frame,.fieldTag,.fieldReverse,\n    .clearWord,.rowSeed,.rowReverse,.logRow,.clearRow,.finishSeed,.outputReverse,.clearReader,.done,.abort]\n  (by intro k;cases k <;> simp)\n/-- All actual context/primitive return labels are fixed finite before every operand family. -/\ninductive Label where\n  | local (pc:Control) | context (pc:X.Label) | copy (part:Copy) (pc:Fin 9) | field (pc:Field.Label)\n  | frame (pc:Fin 11) | reverse (part:Reverse) (pc:Fin 4) | body (pc:Body.Label)\n  deriving Fintype\nlocal notation \"ctl\" => Label.local\n/-- One literal source: real context once, then an actual q-by-rank field scan with no numeric offset evaluator. -/\ndef program :Label→C.Instruction Stack Label\n  | .local .start=>.call (.context .start) (ctl .ready)\n  | .local .ready=>.call (.copy .blocks 0) (ctl .copyVector)\n  | .local .copyVector=>.call (.copy .vector 0) (ctl .outer)\n  | .local .outer=>.base (.pop (aux .todo) (ctl .finishSeed) (ctl .abort) (ctl .copyRank))\n  | .local .copyRank=>.call (.copy .rank 0) (ctl .inner)\n  | .local .inner=>.base (.pop (aux .rankTodo) (ctl .rowSeed) (ctl .abort) (ctl .peek))\n  | .local .peek=>.base (.peek (aux .reader) (ctl .frame) (ctl .frame) (ctl .tag))\n  | .local .tag=>.base (.pop (aux .reader) (ctl .abort) (ctl .abort) (ctl .field))\n  | .local .field=>.call (.field (Field.active .tagPop (none,false))) (ctl .valid)\n  | .local .valid=>.base (.pop (aux .valid) (ctl .abort) (ctl .abort) (ctl .frame))\n  | .local .frame=>.call (.frame 0) (ctl .fieldTag)\n  | .local .fieldTag=>.base (.push (aux .frameBuffer) true (ctl .fieldReverse))\n  | .local .fieldReverse=>.call (.reverse .field 0) (ctl .clearWord)\n  | .local .clearWord=>.base (.pop (aux .word) (ctl .inner) (ctl .clearWord) (ctl .clearWord))\n  | .local .rowSeed=>.base (.push (aux .row) false (ctl .rowReverse))\n  | .local .rowReverse=>.call (.reverse .row 0) (ctl .logRow)\n  | .local .logRow=>.call (.body Body.entry) (ctl .clearRow)\n  | .local .clearRow=>.base (.pop (aux .row) (ctl .outer) (ctl .clearRow) (ctl .clearRow))\n  | .local .finishSeed=>.base (.push (aux .output) false (ctl .outputReverse))\n  | .local .outputReverse=>.call (.reverse .output 0) (ctl .clearReader)\n  | .local .clearReader=>.base (.pop (aux .reader) (ctl .done) (ctl .clearReader) (ctl .clearReader))\n  | .local .done|.local .abort=>.base .halt\n  | .context pc=>SemiprimeD1StackValidationLink.instruction contextStack Label.context (X.program pc)\n  | .copy part pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack part) (Label.copy part) (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (Field.code pc)\n  | .frame pc=>SemiprimeD1StackMultiplierLink.instruction frameStack Label.frame (SemiprimeD1StackFrame.code pc)\n  | .reverse part pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack part) (Label.reverse part) (SemiprimeD1StackReverseWord.code pc)\n  | .body pc=>SemiprimeD1StackMultiplierLink.instruction bodyStack Label.body (Body.code pc)\n/-- Only the actual q word and actual coefficient vector are installed in the new private input bank. -/\ndef privateInput (q coefficients:List Bool) :Aux→List Bool :=fun k=>if k=.blocks then q else if k=.coefficients then coefficients else []\n/-- The actual whole source has four physical operands: old header, binary precision, q markers and coefficient vector. -/\ndef input (axes precision q coefficients:List Bool) :Stack→List Bool :=Sum.elim (X.initial axes precision).data (privateInput q coefficients)\n/-- Whole actual context-acquiring front door, before any rank/width supplier result. -/\ndef initial (axes precision q coefficients:List Bool) :C.State Stack Label :=\n  ⟨some (ctl .start),none,none,input axes precision q coefficients,[]⟩\n/-- One fixed finite31-role prepared-input block source. -/\ndef machine :Turing.FinTM2 :=SemiprimeD1StackCalls.machine (aux .coefficients) (aux .output) (ctl .start) program\n/-- All actual preserving-copy operands are separate. -/\ntheorem copy_injective (part:Copy) :Function.Injective (copyStack part) :=by cases part <;> decide\n/-- The real parser input/output/scratch/valid addresses are distinct. -/\ntheorem field_injective :Function.Injective fieldStack :=by decide\n/-- Real framing preserves a distinct coefficient source with separate output/restoration scratch. -/\ntheorem frame_injective :Function.Injective frameStack :=by decide\n/-- All actual reversals have distinct operands. -/\ntheorem reverse_injective (part:Reverse) :Function.Injective (reverseStack part) :=by cases part <;> decide\n/-- Real block logger input/scratch/history are distinct. -/\ntheorem body_injective :Function.Injective bodyStack :=by decide\n/-- Every31actual context/private word and helper is included in allocation. -/\ntheorem stack_card :Fintype.card Stack=31 :=by rw [Fintype.card_sum];decide\n/-- All runtime control is finite Boolean/read/return flags, never numeric offsets or evaluators. -/\ntheorem control_finite :Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- All31data and actual return alphabets are fixed finite before every input. -/\ntheorem alphabets_finite :∀k,Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackJetBlocks\n","RiemannGaussian.SemiprimeD1StackJetContext":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetMulBounds\nimport RiemannGaussian.SemiprimeD1StackUnaryCounterExecution\n/-! # Physical jet context-cache acquisition\nThe original encoded positive unary axes are preserved while the actual suffix\nproducer computes rank. Binary precision is preserved while the actual unary\ncounter acquires precision markers. Generated suffix records are physically\ncleared, not silently projected away. No rank/precision-count answer is supplied.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 8192\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeD1StackJetContext\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace S\nexport SemiprimeD1StackJetSuffix (Stack Label code control data)\nend S\nnamespace U\nexport SemiprimeD1StackUnaryCounter (Label code state)\nend U\n\n/-- Eight suffix registers, four precision-decoder registers and three fixed caches. -/\nabbrev Stack := S.Stack ⊕ (SemiprimeD1StackAdder.Stack ⊕ Fin 3)\n/-- Retained original axis-vector tape. -/\ndef axesCache : Stack := .inr (.inr 0)\n/-- Retained original binary precision word. -/\ndef precisionBits : Stack := .inr (.inr 1)\n/-- Cleared copy work. -/\ndef copyWork : Stack := .inr (.inr 2)\n/-- Physically acquired unary rank; no extra rank cache copy is needed. -/\ndef rankCache : Stack := .inl .radix\n/-- Physically acquired unary precision markers. -/\ndef widthCache : Stack := .inr (.inl .output)\n/-- Literal precision decoder inclusion. -/\ndef unaryStack (k : SemiprimeD1StackAdder.Stack) : Stack := .inr (.inl k)\n/-- Two actual source copies preserve both original context inputs. -/\ndef copyStack (precision : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if precision then precisionBits else axesCache)\n  else if k=1 then (if precision then unaryStack .left else .inl .axes) else copyWork\n\n/-- Fixed finite caller/component labels, before all context values. -/\ninductive Label where\n  | start | callSuffix | suffixDone | clearRecords | copyPrecision | callUnary | done | reject\n  | copy (precision : Bool) (pc : Fin 9)\n  | suffix (pc : S.Label)\n  | unary (pc : U.Label)\n  deriving DecidableEq,Fintype\n\n/-- Actual context supplier: no native rank, big-integer precision decoding or\nrecord-discard operation occurs in the executed instruction table. -/\ndef program : Label → C.Instruction Stack Label\n  | .start => .call (.copy false 0) .callSuffix\n  | .callSuffix => .call (.suffix (S.control .vector)) .suffixDone\n  | .suffixDone => .base (.pop (.inl .valid) .reject .reject .clearRecords)\n  | .clearRecords => .base (.pop (.inl .records) .copyPrecision .clearRecords .clearRecords)\n  | .copyPrecision => .call (.copy true 0) .callUnary\n  | .callUnary => .call (.unary .reverse) .done\n  | .done | .reject => .base .halt\n  | .copy precision pc => SemiprimeD1StackMultiplierLink.instruction (copyStack precision) (Label.copy precision)\n      (SemiprimeD1StackCopy.code pc)\n  | .suffix pc => SemiprimeD1StackValidationLink.instruction Sum.inl Label.suffix (S.code pc)\n  | .unary pc => SemiprimeD1StackMultiplierLink.instruction unaryStack Label.unary (U.code pc)\n\n/-- Literal retained original input tapes and empty copy workspace. -/\ndef cached (axes precision : List Bool) (k : Fin 3) : List Bool :=\n  if k=0 then axes else if k=1 then precision else []\n/-- Declarative component-state bank; its functions are refinement invariants,\nnot callbacks accepted by the executed supplier. -/\ndef bank (axes precision : List Bool) (suffix : S.Stack → List Bool)\n    (unary : SemiprimeD1StackAdder.Stack → List Bool) : Stack → List Bool :=\n  Sum.elim suffix (Sum.elim unary (cached axes precision))\n/-- Actual entry takes only encoded original axes and binary precision. -/\ndef initial (axes precision : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,bank axes precision (fun _=>[]) (fun _=>[]),[]⟩\n/-- Actual fixed finite-stack context-cache machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine axesCache rankCache Label.start program\n\n/-- Both original-source copy inclusions have distinct data registers. -/\ntheorem copyStack_injective (precision : Bool) : Function.Injective (copyStack precision) := by\n  cases precision <;> decide\n/-- Unary precision decoding uses distinct actual registers. -/\ntheorem unaryStack_injective : Function.Injective unaryStack := by\n  intro a b h\n  simpa only [unaryStack,Sum.inr.injEq,Sum.inl.injEq] using h\n\nend RiemannGaussian.SemiprimeD1StackJetContext\n","RiemannGaussian.SemiprimeD1StackJetFoldMoves":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetFoldPrimitives\n/-! # Physically paid sum/product transfers and old-operand cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackJetFoldMoves\nopen SemiprimeD1StackJetFold SemiprimeD1StackJetFoldState SemiprimeD1StackJetFoldPrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Exact physical tail-sum transfer: actual preserving copy followed by actual source drain. -/\ndef movedSum (v:Values):Values:=Function.update (Function.update v .tailSum (v .sum)) .sum []\n/-- The recursively acquired tail sum is physically retained while the actual head product is computed. -/\ntheorem move_sum (v:Values) (hz:v .tailSum=[]):\n    Runs program (6*(v .sum).length+5) (ctl .copySum) (data v) (ctl .productCall) (data (movedSum v)):=by\n  let b:=Function.update v .tailSum (v .sum)\n  have h0:=copy_view .sum .copySum .clearSum v rfl\n  change Runs program (5*(v .sum).length+4) _ _ _\n    (data (Function.update v .tailSum (v .sum++v .tailSum))) at h0\n  rw [hz,List.append_nil] at h0\n  have h1:=drain_view .clearSum .productCall .sum b rfl\n  change Runs program ((v .sum).length+1) _ _ _ (data (movedSum v)) at h1\n  have h:=join h0 h1\n  convert h using 1;omega\n/-- Exact cleaned current product after both old operands and temporary output are physically drained. -/\ndef movedProduct (v:Values):Values:=\n  Function.update (Function.update (Function.update v .left []) .product (v .result)) .result []\n/-- All consumed original/padded operand bits and all produced output bits are counted in the real transfer trace. -/\ntheorem move_product (v:Values):\n    Runs program ((v .left).length+(v .product).length+6*(v .result).length+7)\n      (ctl .clearLeft) (data v) (ctl .returning) (data (movedProduct v)):=by\n  let a:=Function.update v .left []\n  let b:=Function.update a .product []\n  let c:=Function.update b .product (v .result)\n  have h0:=drain_view .clearLeft .clearRight .left v rfl\n  change Runs program ((v .left).length+1) _ _ _ (data a) at h0\n  have h1:=drain_view .clearRight .copyProduct .product a rfl\n  change Runs program ((v .product).length+1) _ _ _ (data b) at h1\n  have h2:=copy_view .product .copyProduct .clearOutput b rfl\n  change Runs program (5*(v .result).length+4) _ _ _\n    (data (Function.update b .product (v .result++[]))) at h2\n  rw [List.append_nil] at h2\n  have h3:=drain_view .clearOutput .returning .result c rfl\n  change Runs program ((v .result).length+1) _ _ _ (data (Function.update c .result [])) at h3\n  have he:Function.update c .result []=movedProduct v:=by funext s;cases s <;> rfl\n  rw [he] at h3\n  have h:=join h0 (join h1 (join h2 h3))\n  convert h using 1;omega\nend RiemannGaussian.SemiprimeD1StackJetFoldMoves\n","RiemannGaussian.SemiprimeD1StackJetPoint":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRoute\nimport RiemannGaussian.SemiprimeD1StackJetIndexEq\nimport RiemannGaussian.SemiprimeD1StackJetReadExecution\nimport RiemannGaussian.SemiprimeD1StackJetScalarMulExecution\nimport RiemannGaussian.SemiprimeD1StackJetScalarAddExecution\n\n/-! # Fixed physical routed jet-coefficient controller\nThe two nested loops consume physical copies of the rank counter. Each candidate\npair calls the actual mixed-radix router, compares its acquired result with the\nphysical target index, and only then reads/multiplies/adds coefficient payloads.\nNo scalar/vector/routing result is an instruction argument. Context preparation\nis a separate physical caller; correctness and time are separate obligations.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 8192\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackJetPoint\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace R\nexport SemiprimeD1StackJetRoute (Stack Label code control)\nend R\nnamespace M\nexport SemiprimeD1StackJetScalarMul (Stack Label program reduceStack)\nend M\nnamespace A\nexport SemiprimeD1StackJetScalarAdd (Stack Label program)\nend A\nnamespace V\nexport SemiprimeD1StackJetRead (Stack Label program)\nend V\nnamespace E\nexport SemiprimeD1StackJetIndexEq (Label code)\nend E\n\n/-- Constructive equality of literal finite statement locations. -/\ndef locationsDecidableEq {K L S : Type} (q : Turing.TM2.Stmt (fun _ : K => Bool) L S) :\n    DecidableEq (SemiprimeD1StackFiniteControl.Locations q) :=\n  match q with\n  | .push _ _ q | .peek _ _ q | .pop _ _ q | .load _ q =>\n    letI := locationsDecidableEq q\n    inferInstanceAs (DecidableEq (Unit ⊕ SemiprimeD1StackFiniteControl.Locations q))\n  | .branch _ q r =>\n    letI := locationsDecidableEq q\n    letI := locationsDecidableEq r\n    inferInstanceAs (DecidableEq (Unit ⊕ (SemiprimeD1StackFiniteControl.Locations q ⊕\n      SemiprimeD1StackFiniteControl.Locations r)))\n  | .goto _ | .halt => inferInstanceAs (DecidableEq Unit)\n\n/-- Executable equality for compiled finite-control labels, without choice. -/\ninstance finiteControlLabelDecidableEq {K L S : Type} [DecidableEq L] [DecidableEq S]\n    (p : L → Turing.TM2.Stmt (fun _ : K => Bool) L S) :\n    DecidableEq (SemiprimeD1StackFiniteControl.Label p) := by\n  letI : ∀l, DecidableEq (SemiprimeD1StackFiniteControl.Locations (p l)) :=\n    fun l => locationsDecidableEq (p l)\n  exact inferInstanceAs (DecidableEq ((l : L) × (S × SemiprimeD1StackFiniteControl.Locations (p l))))\n\n/-- Persistent physical metadata/caches and literal reader/comparator workspace. -/\ninductive Aux where\n  | a | b | axes | rank | i | j | target | acc | reader | index | parser | skipped\n  | valid | readCopy | eqRight | eqValid | eqScratch | addWork | copyWork\n  deriving DecidableEq,Repr\ninstance : Fintype Aux := Fintype.ofList\n  [.a,.b,.axes,.rank,.i,.j,.target,.acc,.reader,.index,.parser,.skipped,.valid,\n   .readCopy,.eqRight,.eqValid,.eqScratch,.addWork,.copyWork]\n  (by intro k; cases k <;> simp)\n\n/-- Fixed finite data bank, every stack has Boolean alphabet. -/\nabbrev Stack := R.Stack ⊕ (M.Stack ⊕ (SemiprimeD1StackAdder.Stack ⊕ Aux))\n/-- Literal persistent/workspace address. -/\ndef aux (k : Aux) : Stack := .inr (.inr (.inr k))\n/-- Literal multiplier-bank address. -/\ndef mulStack (k : M.Stack) : Stack := .inr (.inl k)\n/-- Literal temporary addition-bank address. -/\ndef addBank (k : SemiprimeD1StackAdder.Stack) : Stack := .inr (.inr (.inl k))\n/-- The actual linked multiplier's preserved precision cache. -/\ndef precision : Stack := mulStack (.inr false)\n/-- Product output of the real modular scalar multiplier. -/\ndef product : Stack := mulStack (M.reduceStack .output)\n/-- Newly acquired modular partial sum. -/\ndef newAcc : Stack := addBank .output\n\n/-- Actual scalar-add aliases consume product and accumulator without a getter. -/\ndef addStack : A.Stack → Stack\n  | .inl .left => product\n  | .inl .right => aux .acc\n  | .inl .scratch => addBank .scratch\n  | .inl .output => newAcc\n  | .inr false => precision\n  | .inr true => aux .addWork\n\n/-- Both actual readers share cleared workspace, preserving their own source cache. -/\ndef readStack (right : Bool) : V.Stack → Stack\n  | .cache => aux (if right then .b else .a)\n  | .reader => aux .reader\n  | .index => aux .index\n  | .parser => aux .parser\n  | .skipped => aux .skipped\n  | .output => mulStack (.inl (if right then SemiprimeD1StackMultiplier.factor else SemiprimeD1StackMultiplier.input))\n  | .valid => aux .valid\n  | .copy => aux .readCopy\n\n/-- The comparator consumes the router's actual unary sum-index word. -/\ndef equalStack : SemiprimeD1StackAdder.Stack → Stack\n  | .left => .inl .result\n  | .right => aux .eqRight\n  | .scratch => aux .eqScratch\n  | .output => aux .eqValid\n\n/-- Nine literal real-copy sites, all before the data-dependent run. -/\ninductive Transfer where\n  | rankI | rankJ | axes | routeI | routeJ | target | readI | readJ | accumulator\n  deriving DecidableEq,Repr\ninstance : Fintype Transfer := Fintype.ofList\n  [.rankI,.rankJ,.axes,.routeI,.routeJ,.target,.readI,.readJ,.accumulator]\n  (by intro k; cases k <;> simp)\n/-- Actual copy source. -/\ndef copySource : Transfer → Stack\n  | .rankI | .rankJ => aux .rank\n  | .axes => aux .axes\n  | .routeI | .readI => aux .i\n  | .routeJ | .readJ => aux .j\n  | .target => aux .target\n  | .accumulator => newAcc\n/-- Actual copy destination. -/\ndef copyTarget : Transfer → Stack\n  | .rankI => aux .i\n  | .rankJ => aux .j\n  | .axes => .inl .axes\n  | .routeI => .inl .left\n  | .routeJ => .inl .right\n  | .target => aux .eqRight\n  | .readI | .readJ => aux .index\n  | .accumulator => aux .acc\n/-- Actual copy inclusion, with a shared cleared scratch stack. -/\ndef copyStack (site : Transfer) (k : Fin 3) : Stack :=\n  if k=0 then copySource site else if k=1 then copyTarget site else aux .copyWork\n\n/-- Fixed finite nested-call program labels. -/\ninductive Label where\n  | start | outer | innerInit | inner | axesCopy | leftCopy | rightCopy | routeCall\n  | routeDone | targetCopy | equalCall | equalDone | readLeftCopy | readLeftCall\n  | readRightCopy | readRightCall | multiply | add | retain | clearNew | done\n  | copy (site : Transfer) (pc : Fin 9)\n  | route (pc : R.Label)\n  | equal (pc : E.Label)\n  | read (right : Bool) (pc : V.Label)\n  | scalarMul (pc : M.Label)\n  | scalarAdd (pc : A.Label)\n  deriving DecidableEq,Fintype\n\n/-- Actual fixed convolution-point machine, with physical nested loops and calls. -/\ndef program : Label → C.Instruction Stack Label\n  | .start => .call (.copy .rankI 0) .outer\n  | .outer => .base (.pop (aux .i) .done .innerInit .innerInit)\n  | .innerInit => .call (.copy .rankJ 0) .inner\n  | .inner => .base (.pop (aux .j) .outer .axesCopy .axesCopy)\n  | .axesCopy => .call (.copy .axes 0) .leftCopy\n  | .leftCopy => .call (.copy .routeI 0) .rightCopy\n  | .rightCopy => .call (.copy .routeJ 0) .routeCall\n  | .routeCall => .call (.route (R.control .copyLeft)) .routeDone\n  | .routeDone => .base (.pop (.inl .valid) .inner .inner .targetCopy)\n  | .targetCopy => .call (.copy .target 0) .equalCall\n  | .equalCall => .call (.equal .loop) .equalDone\n  | .equalDone => .base (.pop (aux .eqValid) .inner .inner .readLeftCopy)\n  | .readLeftCopy => .call (.copy .readI 0) .readLeftCall\n  | .readLeftCall => .call (.read false .start) .readRightCopy\n  | .readRightCopy => .call (.copy .readJ 0) .readRightCall\n  | .readRightCall => .call (.read true .start) .multiply\n  | .multiply => .call (.scalarMul .start) .add\n  | .add => .call (.scalarAdd .start) .retain\n  | .retain => .call (.copy .accumulator 0) .clearNew\n  | .clearNew => .base (.pop newAcc .inner .clearNew .clearNew)\n  | .done => .base .halt\n  | .copy site pc => SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site)\n      (SemiprimeD1StackCopy.code pc)\n  | .route pc => SemiprimeD1StackValidationLink.instruction Sum.inl Label.route (R.code pc)\n  | .equal pc => SemiprimeD1StackMultiplierLink.instruction equalStack Label.equal (E.code pc)\n  | .read right pc => SemiprimeD1StackValidationLink.instruction (readStack right) (Label.read right) (V.program pc)\n  | .scalarMul pc => SemiprimeD1StackValidationLink.instruction mulStack Label.scalarMul (M.program pc)\n  | .scalarAdd pc => SemiprimeD1StackValidationLink.instruction addStack Label.scalarAdd (A.program pc)\n\n/-- Real compiled finite-stack target, with prepared physical caches and target index. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (aux .a) (aux .acc) Label.start program\n\n/-- Prepared physical source data. Axes, rank, target and precision are words,\nnot native loop bounds; acquisition of the context is a separate caller. -/\ndef inputData (a b axes width rank target : List Bool) : Stack → List Bool :=\n  Function.update (Function.update (Function.update (Function.update\n    (Function.update (Function.update (fun _ => []) (aux .a) a) (aux .b) b)\n      (aux .axes) axes) precision width) (aux .rank) rank) (aux .target) target\n\n/-- Literal source entry, without a preloaded result, continuation or work value. -/\ndef initial (a b axes width rank target : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,inputData a b axes width rank target,[]⟩\n\n/-- All component scalar-add registers remain physically distinct. -/\ntheorem addStack_injective : Function.Injective addStack := by decide\n/-- Both literal vector-reader inclusions have distinct physical registers. -/\ntheorem readStack_injective (right : Bool) : Function.Injective (readStack right) := by cases right <;> decide\n/-- The acquired-index comparator has distinct operand/work/result registers. -/\ntheorem equalStack_injective : Function.Injective equalStack := by decide\n/-- Every literal copy site has distinct physical source, destination and scratch. -/\ntheorem copyStack_injective (site : Transfer) : Function.Injective (copyStack site) := by cases site <;> decide\n\nend RiemannGaussian.SemiprimeD1StackJetPoint\n","RiemannGaussian.SemiprimeD1StackJetRouteMachine":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRouteExecution\n/-! # Genuine finite-machine route time and every-prefix storage\nThe input is the explicitly prepared physical axis/index tapes. The fixed\nprogram acquires every suffix and performs every actual digit calculation.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteMachine\nopen SemiprimeD1StackJetRoute SemiprimeD1StackJetRouteCalls SemiprimeD1StackJetRouteExecution\nopen SemiprimeD1StackJetRouteStep (bank_width)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\n\n/-- Literal encoded argument inventory; caller acquisition is not silently free. -/\ndef inputSize (axes : List ℕ) (i j : ℕ) : ℕ :=\n  (vectorBits (axes.map unary)).length+i+j\n\n/-- A true FinTM2 time certificate for the SAME executed fixed instruction table.\nChoice selects a proved bounded transition count only inside this proof object;\nthe executable code and physical path contain no choice or solved-value supplier. -/\nnoncomputable def routeInTime (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive) (i j : ℕ) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial ctx.axes i j))\n      (some (SemiprimeD1StackCalls.configuration (final ctx.axes i j)))\n      (budget ctx.axes i j+1) := by\n  let m := Classical.choose (route_run ctx hp i j)\n  have h := Classical.choose_spec (route_run ctx hp i j)\n  exact SemiprimeD1StackCalls.evalsCorrect Stack.axes Stack.result (ctl .copyLeft) code\n    (initial ctx.axes i j) (final ctx.axes i j) (budget ctx.axes i j+1)\n    ⟨⟨m,h.2⟩,h.1⟩\n\n/-- Every real source prefix has bounded physical Boolean stacks. -/\ntheorem prefix_data (axes : List ℕ) (i j fuel : ℕ) (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run code fuel (initial axes i j)=some out) :\n    ∀k,(out.data k).length ≤ inputSize axes i j+fuel := by\n  have hw := bank_width (vectorBits (axes.map unary)) [] (unary i) (unary j) [] [] [] [] [] [] [] [] []\n  simp only [List.length_nil,unary,List.length_replicate,Nat.add_zero] at hw\n  exact SemiprimeD1StackReturnLink.run_data_bound code fuel (inputSize axes i j)\n    (initial axes i j) out hw hr\n\n/-- The actual finite-label return stack is also bounded at every prefix. -/\ntheorem prefix_frames (axes : List ℕ) (i j fuel : ℕ) (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run code fuel (initial axes i j)=some out) :\n    out.frames.length≤fuel := by\n  simpa only [initial,List.length_nil,Nat.zero_add] using\n    SemiprimeD1StackCalls.run_frame_bound code fuel (initial axes i j) out hr\n\n/-- Every literal data symbol and return-label symbol is counted. Labels are a\nfixed finite alphabet independent of axes, rank, indices and context precision. -/\ntheorem prefix_cells (axes : List ℕ) (i j fuel : ℕ) (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run code fuel (initial axes i j)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤20*(inputSize axes i j+fuel+1) := by\n  have hd := prefix_data axes i j fuel out hr\n  have hf := prefix_frames axes i j fuel out hr\n  have hs := Finset.sum_le_sum (s:=Finset.univ) (fun k _=>hd k)\n  have hc : Fintype.card Stack=19 := by decide\n  simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul,hc] at hs\n  omega\n\n/-- All genuinely reached target-machine prefixes satisfy the same physical\npayload bound. This includes skipped input, all internal copies and real frames. -/\ntheorem machine_prefix_cells (axes : List ℕ) (i j fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial axes i j)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      20*(inputSize axes i j+fuel+1) := by\n  dsimp only [SemiprimeD1StackJetRoute.machine] at cfg hr ⊢\n  have he := SemiprimeD1StackCalls.run_correct Stack.axes Stack.result (ctl .copyLeft) code fuel\n    (initial axes i j)\n  have hefinal := he.trans hr\n  cases hs : SemiprimeD1StackCalls.run code fuel (initial axes i j) with\n  | none=>rw [hs] at hefinal; cases hefinal\n  | some out=>\n    rw [hs] at hefinal\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hefinal\n    rw [←hcfg]\n    exact prefix_cells axes i j fuel out hs\nend RiemannGaussian.SemiprimeD1StackJetRouteMachine\n","RiemannGaussian.SemiprimeD1StackJetRouteRecords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetSuffixOriginal\n/-! # Original-derived routing record tape and byte bounds -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteRecords\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Specification of the acquired record bytes, not an input to the route. -/\ndef tape : List (ℕ×ℕ)→List Bool\n  | []=>[]\n  | (q,d)::xs=>frame (unary q) (frame (unary d) (tape xs))\n@[simp] theorem tape_cons_length (q d : ℕ) (xs : List (ℕ×ℕ)) :\n    (tape ((q,d)::xs)).length=2*q+2*d+2+(tape xs).length := by\n  simp [tape,SemiprimeSourceHistogramKeyBits.frame_length,unary]\n  omega\n/-- The executed supplier's record bytes are precisely the frozen original suffix records. -/\ntheorem acquired_tape (axes : List ℕ) :\n    SemiprimeD1StackJetSuffixOriginal.recordTape axes 1 []=\n      tape (SemiprimeD1StackRouteArithmetic.records axes) := by\n  induction axes with\n  | nil=>rfl\n  | cons q qs ih=>simp only [SemiprimeD1StackJetSuffixOriginal.recordTape,\n      SemiprimeD1StackRouteArithmetic.records,tape,Nat.mul_one,ih]\n\n/-- Every original suffix record is rank-bounded, so the actual encoded inventory\nis polynomial in axis count and the rank acquired by the supplier. -/\ntheorem original_tape_length (axes : List ℕ) (hp : ∀q∈axes,0<q) :\n    (tape (SemiprimeD1StackRouteArithmetic.records axes)).length≤(4*axes.prod+2)*axes.length := by\n  have aux : ∀(rs : List (ℕ×ℕ)) (cap : ℕ),\n      (∀p∈rs,p.1≤cap ∧ p.2≤cap)→(tape rs).length≤(4*cap+2)*rs.length := by\n    intro rs cap hb\n    induction rs with\n    | nil=>simp [tape]\n    | cons p ps ih=>\n      rcases p with ⟨q,d⟩\n      have hqd:=hb (q,d) (by simp)\n      have ht:=ih (fun p hp=>hb p (by simp [hp]))\n      rw [tape_cons_length,List.length_cons]\n      nlinarith\n  have hb : ∀p∈SemiprimeD1StackRouteArithmetic.records axes,p.1≤axes.prod ∧ p.2≤axes.prod := by\n    intro p hmem\n    have h:=SemiprimeD1StackRouteArithmetic.record_bounds axes hp p.1 p.2 hmem\n    exact ⟨h.2.2.1,h.2.2.2.1⟩\n  have hlen : (SemiprimeD1StackRouteArithmetic.records axes).length=axes.length := by\n    clear hp hb\n    induction axes with\n    | nil=>rfl\n    | cons q qs ih=>simp [SemiprimeD1StackRouteArithmetic.records,ih]\n  simpa only [hlen] using aux _ axes.prod hb\nend RiemannGaussian.SemiprimeD1StackJetRouteRecords\n","RiemannGaussian.SemiprimeD1StackJetSuffix":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackUnaryProduct\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\n\n/-! # Physical acquisition of original mixed-radix suffix records\nThe first pass parses/reverses the actual axis fields. The second pass starts\nfrom product one and physically acquires every suffix product with UnaryProduct.\nFraming/copying/parser work is part of the fixed included program. Rank is an\nactual retained product output, not an input bound or supplied value.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetSuffix\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\nnamespace P\nexport SemiprimeD1StackUnaryProduct (Stack Label code entry)\nend P\n\n/-- Fixed physical Boolean argument/cache/work stacks. -/\ninductive Stack | axes | reverseAxes | axis | radix | product | records | scratch | valid\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype Stack where\n  elems := {.axes,.reverseAxes,.axis,.radix,.product,.records,.scratch,.valid}\n  complete := by intro k; cases k <;> simp\n\n/-- Finite control stages; failure cleanup enumerates only the fixed stack bank. -/\ninductive Control\n  | vector | readAxis | axisRead | positive | reverseFrame | clearAxis | startSuffix\n  | suffixPeek | readReverse | reverseRead | frameRadix | frameAxis | productCall\n  | clearRadix | moveProduct | movePush | success | fail (stage : Fin 8) | failure | halt\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype Control := Fintype.ofList\n  ([.vector,.readAxis,.axisRead,.positive,.reverseFrame,.clearAxis,.startSuffix,\n    .suffixPeek,.readReverse,.reverseRead,.frameRadix,.frameAxis,.productCall,\n    .clearRadix,.moveProduct,.movePush,.success,.failure,.halt]++(List.finRange 8).map .fail)\n  (by intro k; cases k <;> simp)\n\n/-- Fixed disjoint copies of Field, Frame and actual UnaryProduct instruction tables. -/\nabbrev Label := F.Label ⊕ (F.Label ⊕ (Fin 11 ⊕ (Fin 11 ⊕ (Fin 11 ⊕ (P.Label ⊕ Control)))))\n\n/-- Literal control label. -/\ndef control (c : Control) : Label := .inr (.inr (.inr (.inr (.inr (.inr c)))))\n/-- Axis-input field-parser label. -/\ndef axesField (l : F.Label) : Label := .inl l\n/-- Reverse-axis field-parser label. -/\ndef reverseField (l : F.Label) : Label := .inr (.inl l)\n/-- Actual reverse-axis framing label. -/\ndef reverseFrame (l : Fin 11) : Label := .inr (.inr (.inl l))\n/-- Actual suffix-divisor framing label. -/\ndef radixFrame (l : Fin 11) : Label := .inr (.inr (.inr (.inl l)))\n/-- Actual axis framing label. -/\ndef axisFrame (l : Fin 11) : Label := .inr (.inr (.inr (.inr (.inl l))))\n/-- Actual metadata-product label. -/\ndef productLabel (l : P.Label) : Label := .inr (.inr (.inr (.inr (.inr (.inl l)))))\n\n/-- Original axis parser reads actual source tape, with physical validity bit. -/\ndef axesFieldStack : F.Stack → Stack\n  | .inl .input => .axes\n  | .inl .scratch => .scratch\n  | .inl .output => .axis\n  | .inr _ => .valid\n/-- Reverse parser reads actual acquired reverse-axis records. -/\ndef reverseFieldStack : F.Stack → Stack\n  | .inl .input => .reverseAxes\n  | .inl .scratch => .scratch\n  | .inl .output => .axis\n  | .inr _ => .valid\n/-- Axis-framing acquisition retains the original counter while prepending its field. -/\ndef reverseFrameStack : Fin 3 → Stack := fun k => if k=0 then .axis else if k=1 then .reverseAxes else .scratch\n/-- Suffix-radix framing retains the actual acquired product. -/\ndef radixFrameStack : Fin 3 → Stack := fun k => if k=0 then .radix else if k=1 then .records else .scratch\n/-- Axis-framing prepends the first field of each actual (q,d) record. -/\ndef axisFrameStack : Fin 3 → Stack := fun k => if k=0 then .axis else if k=1 then .records else .scratch\n/-- Product consumes the actual axis counter and copies/restores the actual radix. -/\ndef productStack : P.Stack → Stack\n  | .multiplier => .axis\n  | .multiplicand => .radix\n  | .scratch => .scratch\n  | .product => .product\n\n/-- Fixed failure-clearing catalogue, with no input-sized control address. -/\ndef clearStack (k : Fin 8) : Stack :=\n  if k=0 then .axes else if k=1 then .reverseAxes else if k=2 then .axis else if k=3 then .radix\n  else if k=4 then .product else if k=5 then .records else if k=6 then .scratch else .valid\n\n/-- Actual closed finite program: all suffix products are physically acquired. -/\ndef code : Label → C.Instruction Stack Label\n  | .inl l => SemiprimeD1StackMultiplierLink.instruction axesFieldStack axesField (F.code l)\n  | .inr (.inl l) => SemiprimeD1StackMultiplierLink.instruction reverseFieldStack reverseField (F.code l)\n  | .inr (.inr (.inl l)) => SemiprimeD1StackMultiplierLink.instruction reverseFrameStack reverseFrame\n      (SemiprimeD1StackFrame.code l)\n  | .inr (.inr (.inr (.inl l))) => SemiprimeD1StackMultiplierLink.instruction radixFrameStack radixFrame\n      (SemiprimeD1StackFrame.code l)\n  | .inr (.inr (.inr (.inr (.inl l)))) => SemiprimeD1StackMultiplierLink.instruction axisFrameStack axisFrame\n      (SemiprimeD1StackFrame.code l)\n  | .inr (.inr (.inr (.inr (.inr (.inl l))))) =>\n      SemiprimeD1StackMultiplierLink.instruction productStack productLabel (P.code l)\n  | .inr (.inr (.inr (.inr (.inr (.inr c))))) => match c with\n    | .vector => .base (.pop .axes (control (.fail 0)) (control .startSuffix) (control .readAxis))\n    | .readAxis => .call (axesField (F.active .tagPop (none,false))) (control .axisRead)\n    | .axisRead => .base (.pop .valid (control (.fail 0)) (control (.fail 0)) (control .positive))\n    | .positive => .base (.peek .axis (control (.fail 0)) (control .reverseFrame) (control .reverseFrame))\n    | .reverseFrame => .call (reverseFrame 0) (control .clearAxis)\n    | .clearAxis => .base (.pop .axis (control .vector) (control .clearAxis) (control .clearAxis))\n    | .startSuffix => .base (.push .radix true (control .suffixPeek))\n    | .suffixPeek => .base (.peek .reverseAxes (control .success) (control .readReverse) (control .readReverse))\n    | .readReverse => .call (reverseField (F.active .tagPop (none,false))) (control .reverseRead)\n    | .reverseRead => .base (.pop .valid (control (.fail 0)) (control (.fail 0)) (control .frameRadix))\n    | .frameRadix => .call (radixFrame 0) (control .frameAxis)\n    | .frameAxis => .call (axisFrame 0) (control .productCall)\n    | .productCall => .call (productLabel P.entry) (control .clearRadix)\n    | .clearRadix => .base (.pop .radix (control .moveProduct) (control .clearRadix) (control .clearRadix))\n    | .moveProduct => .base (.pop .product (control .suffixPeek) (control .movePush) (control .movePush))\n    | .movePush => .base (.push .radix true (control .moveProduct))\n    | .success => .base (.push .valid true (control .halt))\n    | .fail k => .base (.pop (clearStack k)\n        (if h : k.val<7 then control (.fail ⟨k.val+1,by omega⟩) else control .failure)\n        (control (.fail k)) (control (.fail k)))\n    | .failure => .base (.push .valid false (control .halt))\n    | .halt => .base .halt\n\n/-- Actual fixed finite machine. Prepared physical axes are its sole argument stack. -/\ndef machine := SemiprimeD1StackCalls.machine Stack.axes Stack.records (control .vector) code\n\n/-- Explicit physical data bank. -/\ndef data (axes reverseAxes axis radix product records scratch valid : List Bool) : Stack → List Bool\n  | .axes => axes\n  | .reverseAxes => reverseAxes\n  | .axis => axis\n  | .radix => radix\n  | .product => product\n  | .records => records\n  | .scratch => scratch\n  | .valid => valid\n\nend RiemannGaussian.SemiprimeD1StackJetSuffix\n","RiemannGaussian.SemiprimeD1StackKernelLinearDivisionView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearView\n/-! # Exact retained29-role restoring-division views and updates -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearDivisionView\nopen SemiprimeD1StackKernelLinear SemiprimeD1StackKernelLinearView\n/-- Complete division preparation/result bank; all other divider work is empty. -/\ndef divisionData (w:Words) (input divisor remainder quotient:List Bool):Stack→List Bool:=\n  bank (SemiprimeD1StackDivider.payload input divisor [] [] [] [] [] remainder quotient [] []) w\n/-- Every unused arithmetic role is physically empty at these boundaries. -/\ntheorem divisionData_empty (w:Words):divisionData w [] [] [] []=data w:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r <;> cases r <;> rfl\n  · rfl\n/-- Auxiliary updates preserve the actual whole eleven-role divider bank. -/\ntheorem divisionData_aux_update (w:Words) (input divisor remainder quotient:List Bool) (role:Aux) (value:List Bool):\n    Function.update (divisionData w input divisor remainder quotient) (aux role) value=\n      divisionData (SemiprimeD1StackKernelLinearView.set w role value) input divisor remainder quotient:=\n  bank_aux_update _ _ _ _\n/-- Exact actual dividend-copy update. -/\ntheorem divisionData_input_update (w:Words) (input divisor remainder quotient value:List Bool):\n    Function.update (divisionData w input divisor remainder quotient) (divider (.inr .input)) value=\n      divisionData w value divisor remainder quotient:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r\n    · cases r <;> rfl\n    · cases r <;> rfl\n  · rfl\n/-- Exact actual divisor-copy update. -/\ntheorem divisionData_divisor_update (w:Words) (input divisor remainder quotient value:List Bool):\n    Function.update (divisionData w input divisor remainder quotient) (divider (.inr .divisor)) value=\n      divisionData w input value remainder quotient:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r\n    · cases r <;> rfl\n    · cases r <;> rfl\n  · rfl\n/-- Exact actual quotient cleanup update. -/\ntheorem divisionData_quotient_update (w:Words) (input divisor remainder quotient value:List Bool):\n    Function.update (divisionData w input divisor remainder quotient) (divider (.inr .quotient)) value=\n      divisionData w input divisor remainder value:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r\n    · cases r <;> rfl\n    · cases r <;> rfl\n  · rfl\n/-- Exact actual remainder cleanup update. -/\ntheorem divisionData_remainder_update (w:Words) (input divisor remainder quotient value:List Bool):\n    Function.update (divisionData w input divisor remainder quotient) (divider (.inr .remainder)) value=\n      divisionData w input divisor value quotient:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r\n    · cases r <;> rfl\n    · cases r <;> rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackKernelLinearDivisionView\n","RiemannGaussian.SemiprimeD1StackLeafExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafSetup\n/-! # Closed actual original-header leaf execution, exact old leaf words -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeD1StackLeafExecution\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Proof-side tuple of the original encoded headers and literal vertex records. -/\ndef originalProductValues (ctx : SemiprimeD1JetAxes.Context) (pBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) : PS.Values :=\n  SemiprimeD1StackVertexProductState.values (vectorBits (ctx.axes.map unary)) pBits\n    (SemiprimeD1StackVertexProduct.records vertices) [] [] [] [] [] [] [] [] [] []\n/-- The original binary assignment-width word is the only initially live outer register. -/\ndef originalValues (mBits : List Bool) : Values\n  | .widthBits => mBits\n  | _ => []\n/-- Actual original physical start satisfies the declarative register invariant. -/\ntheorem initial_data (ctx : SemiprimeD1JetAxes.Context) (pBits mBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) :\n    (initial (vectorBits (ctx.axes.map unary)) pBits mBits\n      (SemiprimeD1StackVertexProduct.records vertices)).data=\n      data (originalProductValues ctx pBits vertices) (originalValues mBits) := by\n  funext k\n  fin_cases k <;> rfl\n\n/-- Exact clean final store: original inputs and actually acquired caches retained,\nonly the leaf sum is added; every other data/return/work register is empty. -/\ndef finalData (M : ℕ) (ctx : SemiprimeD1JetAxes.Context) (pBits mBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) : Stack→List Bool :=\n  data (Function.update (Function.update (originalProductValues ctx pBits vertices) .rank (unary ctx.rank))\n      .width (SemiprimeD1StackUnaryCounterExecution.markers ctx.precision))\n    (Function.update (originalValues mBits) .sum\n      (vectorBits (SemiprimeD1TensorTapeLeaf.run M ctx vertices).words))\n\n/-- Actual complete transition budget from original headers and literal records,\nretaining real context acquisition, width conversion, all assignments and folds. -/\ndef budget (M : ℕ) (ctx : SemiprimeD1JetAxes.Context) (pBits mBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) : ℕ :=\n  let ready:=Function.update (Function.update (originalProductValues ctx pBits vertices) .rank (unary ctx.rank))\n    .width (SemiprimeD1StackUnaryCounterExecution.markers ctx.precision)\n  1000*(SemiprimeD1StackJetContextBounds.resource ctx.axes pBits+1)^2+1+\n    SemiprimeD1StackLeafSetup.enumeratedBudget M ctx vertices ready (originalValues mBits)+1\n\n/-- One fixed finite program, starting with original physical headers and literal\ntables only, executes actual enumeration/products/sums and returns EXACT bytes\nof the frozen eager leaf routine. No prepared assignment, rank, precision count,\nentry, coefficient, route, cost or leaf answer is supplied. -/\ntheorem source_run (M : ℕ) (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (pBits mBits : List Bool) (hprecision : SemiprimeBitArithmetic.bitValue pBits=ctx.precision)\n    (hM : SemiprimeBitArithmetic.bitValue mBits=M) (vertices : List SemiprimeD1LeafCounter.Vertex) :\n    ∃ m ≤ budget M ctx pBits mBits vertices, SemiprimeD1StackCalls.run program m\n      (initial (vectorBits (ctx.axes.map unary)) pBits mBits (SemiprimeD1StackVertexProduct.records vertices))=\n      some (⟨none,none,none,finalData M ctx pBits mBits vertices,[]⟩:\n        SemiprimeD1StackCalls.State Stack Label) := by\n  let p:=originalProductValues ctx pBits vertices\n  let v:=originalValues mBits\n  let ready:=Function.update (Function.update p .rank (unary ctx.rank)) .width\n    (SemiprimeD1StackUnaryCounterExecution.markers ctx.precision)\n  obtain ⟨m,hmb,hm⟩:=SemiprimeD1StackLeafAcquisition.context_call p v ctx.axes hp rfl rfl rfl\n  have hm' : Runs program m .start (data p v) .widthCopy (data ready v) := by\n    simpa only [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values,\n      SemiprimeD1JetAxes.Context.rank,hprecision] using hm\n  obtain ⟨n,hnb,hn⟩:=SemiprimeD1StackLeafSetup.enumerated_run M ctx hp vertices ready v\n    hM (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    rfl rfl rfl rfl rfl rfl rfl\n    (by simp [ready,p,originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [ready,SemiprimeD1StackUnaryCounterExecution.markers]) (by simp [ready])\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hm' hn\n  obtain ⟨finish,hfinish,hout⟩:=hc []\n    (initial (vectorBits (ctx.axes.map unary)) pBits mBits (SemiprimeD1StackVertexProduct.records vertices))\n    ⟨rfl,initial_data ctx pBits mBits vertices,rfl⟩\n  have hh:=SemiprimeD1StackProcedureTrace.halt_run program .done rfl _ [] finish hout\n  refine ⟨m+n+1,?_,?_⟩\n  · change m+n+1 ≤ 1000*(SemiprimeD1StackJetContextBounds.resource ctx.axes pBits+1)^2+1+\n        SemiprimeD1StackLeafSetup.enumeratedBudget M ctx vertices ready v+1\n    simpa only [p,originalProductValues,SemiprimeD1StackVertexProductState.values] using\n      Nat.add_le_add_right (Nat.add_le_add hmb hnb) 1\n  · rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some,hh]\n    rfl\n\nend RiemannGaussian.SemiprimeD1StackLeafExecution\n","RiemannGaussian.SemiprimeD1StackLeafMoves":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafAddition\n/-! # Actual catalogue reads, validity pops, sum copies and assignment cleanup -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackLeafMoves\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState\nopen SemiprimeD1StackProcedureTrace (Runs one_base runs_trans)\n\n/-- Real drain loop on an outer physical buffer. -/\ntheorem drain (p : PS.Values) (v : Values) (s : Slot) (pc next : Label)\n    (hcode : program pc=.base (.pop (address s) next pc pc)) (he : v s=[]) (word : List Bool) :\n    Runs program (word.length+1) pc (data p (Function.update v s word)) next (data p v) := by\n  induction word with\n  | nil =>\n    have hd : Function.update v s []=v := Function.update_eq_self_iff.mpr he.symm\n    rw [hd]\n    apply one_base program pc next (.pop (address s) next pc pc) _ _ hcode\n    · simp only [SemiprimeD1StackBytecode.execute,data_get,he,List.head?_nil,SemiprimeD1StackBytecode.choose]\n    · change Function.update (data p v) (address s) ((data p v (address s)).tail)=data p v\n      rw [data_get,he,List.tail_nil,←data_update,hd]\n  | cons bit word ih =>\n    have h1 : Runs program 1 pc (data p (Function.update v s (bit::word))) pc (data p (Function.update v s word)) := by\n      apply one_base program pc pc (.pop (address s) next pc pc) _ _ hcode\n      · simp only [SemiprimeD1StackBytecode.execute,data_get,Function.update_self,List.head?_cons]\n        cases bit <;> rfl\n      · change Function.update (data p (Function.update v s (bit::word))) (address s)\n          ((data p (Function.update v s (bit::word)) (address s)).tail)=_\n        rw [data_get,Function.update_self,List.tail_cons,←data_update,Function.update_idem]\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ h1 ih\n    simpa only [List.length_cons,Nat.add_comm,Nat.add_left_comm,Nat.add_assoc] using hh\n\n/-- Current sum-result bytes are physically cleared, not discarded in a projection. -/\ntheorem clear_sum (p : PS.Values) (v : Values) :\n    Runs program ((v .sumResult).length+1) .clearSumResult (data p v) .clearAssignment\n      (data p (Function.update v .sumResult [])) := by\n  have h:=drain p (Function.update v .sumResult []) .sumResult .clearSumResult .clearAssignment rfl (by simp) (v .sumResult)\n  simpa only [Function.update_idem,Function.update_eq_self] using h\n\n/-- Actual selected assignment bytes are physically cleared after use. -/\ntheorem clear_assignment (p : PS.Values) (v : Values) :\n    Runs program ((p .assignment).length+1) .clearAssignment (data p v) .catalogueTag\n      (data (Function.update p .assignment []) v) := by\n  let base:=Function.update p .assignment []\n  have he : base .assignment=[] := by simp [base]\n  have h : ∀word, Runs program (word.length+1) .clearAssignment\n      (data (Function.update base .assignment word) v) .catalogueTag (data base v) := by\n    intro word\n    induction word with\n    | nil =>\n      have hd : Function.update base .assignment []=base := Function.update_eq_self_iff.mpr he.symm\n      rw [hd]\n      apply one_base program .clearAssignment .catalogueTag\n        (.pop (productStack (PS.address .assignment)) .catalogueTag .clearAssignment .clearAssignment) _ _ rfl\n      · simp only [SemiprimeD1StackBytecode.execute,data_product_get,he,List.head?_nil,SemiprimeD1StackBytecode.choose]\n      · change Function.update (data base v) (productStack (PS.address .assignment))\n          ((data base v (productStack (PS.address .assignment))).tail)=_\n        rw [data_product_get,he,List.tail_nil,←data_product_update,hd]\n    | cons bit word ih =>\n      have h1 : Runs program 1 .clearAssignment (data (Function.update base .assignment (bit::word)) v)\n          .clearAssignment (data (Function.update base .assignment word) v) := by\n        apply one_base program .clearAssignment .clearAssignment\n          (.pop (productStack (PS.address .assignment)) .catalogueTag .clearAssignment .clearAssignment) _ _ rfl\n        · simp only [SemiprimeD1StackBytecode.execute,data_product_get,Function.update_self,List.head?_cons]\n          cases bit <;> rfl\n        · change Function.update (data (Function.update base .assignment (bit::word)) v)\n            (productStack (PS.address .assignment))\n            ((data (Function.update base .assignment (bit::word)) v (productStack (PS.address .assignment))).tail)=_\n          rw [data_product_get,Function.update_self,List.tail_cons,←data_product_update,Function.update_idem]\n      have hh:=runs_trans program _ _ _ _ _ _ _ _ h1 ih\n      simpa only [List.length_cons,Nat.add_comm,Nat.add_left_comm,Nat.add_assoc] using hh\n  simpa only [base,Function.update_idem,Function.update_eq_self] using h (p .assignment)\n\n/-- Real retained-source sum copy; the current accumulator is a reached operand. -/\ntheorem copy_sum (p : PS.Values) (v : Values) :\n    Runs program (5*(v .sumResult).length+4) .copySum (data p v) .clearSumResult\n      (data p (Function.update v .sum (v .sumResult++v .sum))) := by\n  apply SemiprimeD1StackProcedureTrace.included_call program (copyStack true) (Label.copy true)\n    (copyStack_injective true) SemiprimeD1StackCopy.code (0:Fin 9) (fun _=>rfl) .copySum .clearSumResult rfl _\n    (SemiprimeD1StackCopy.state 0 none (v .sumResult) (v .sum) [])\n    (SemiprimeD1StackCopy.done (v .sumResult) (v .sumResult++v .sum))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words (v .sumResult) (v .sum) none\n  · constructor\n    · intro k\n      fin_cases k\n      · exact data_get p v .sumResult\n      · exact data_get p v .sum\n      · rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      fin_cases k\n      · change data p (Function.update v .sum (v .sumResult++v .sum)) (address .sumResult)=v .sumResult\n        rw [data_get,Function.update_of_ne (by decide : Slot.sumResult ≠ .sum)]\n      · exact data_get p (Function.update v .sum (v .sumResult++v .sum)) .sum\n      · rfl\n    · intro k hk\n      have hn : k ≠ address .sum := fun he=>hk 1 he.symm\n      rw [data_update]\n      exact Function.update_of_ne hn _ _\n\n/-- Actual catalogue field parsing directly acquires the next assignment. -/\ntheorem field_call (p : PS.Values) (v : Values) (word tail : List Bool)\n    (hr : v .catalogue=SemiprimeSourceHistogramKeyBits.frame word tail)\n    (ha : p .assignment=[]) (hv : v .valid=[]) :\n    Runs program (8*word.length+7) .parse (data p v) .parsed\n      (data (Function.update p .assignment word)\n        (Function.update (Function.update v .catalogue tail) .valid [true])) := by\n  apply SemiprimeD1StackProcedureTrace.included_call program fieldStack Label.field fieldStack_injective\n    F.code (F.active .tagPop (none,false)) (fun _=>rfl) .parse .parsed rfl (8*word.length+6)\n    (SemiprimeD1TensorTapeFieldBytecode.initial (SemiprimeSourceHistogramKeyBits.frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩:\n      SemiprimeD1StackBytecode.State F.Stack F.Label)\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k\n      rw [field_project]\n      fin_cases k <;> simp [SemiprimeD1TensorTapeFieldBytecode.initial,\n        SemiprimeD1TensorTapeFieldMachine.contents,hr,ha,hv]\n    · intro k hk; rfl\n  · constructor\n    · intro k\n      rw [field_project]\n      fin_cases k <;> simp [SemiprimeD1TensorTapeFieldMachine.contents]\n    · intro k hk\n      have hc : k ≠ address .catalogue := fun he=>hk (.inl .input) he.symm\n      have ha : k ≠ productStack (PS.address .assignment) := fun he=>hk (.inl .output) he.symm\n      have hv : k ≠ address .valid := fun he=>hk (.inr ()) he.symm\n      rw [data_update,data_update,data_product_update]\n      simp only [Function.update_of_ne hc,Function.update_of_ne ha,Function.update_of_ne hv]\n\n/-- The actual acquired field-validity bit controls the next real call. -/\ntheorem field_flag (p : PS.Values) (v : Values) :\n    Runs program 1 .parsed (data p (Function.update v .valid [true])) .callProduct\n      (data p (Function.update v .valid [])) := by\n  apply one_base program .parsed .callProduct (.pop (address .valid) .abort .abort .callProduct) _ _ rfl\n  · simp only [SemiprimeD1StackBytecode.execute,data_get,Function.update_self,List.head?_cons,\n      SemiprimeD1StackBytecode.choose]\n  · change Function.update (data p (Function.update v .valid [true])) (address .valid)\n      ((data p (Function.update v .valid [true]) (address .valid)).tail)=_\n    rw [data_get,Function.update_self,List.tail_cons,←data_update,Function.update_idem]\n\nend RiemannGaussian.SemiprimeD1StackLeafMoves\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputBounds\nimport RiemannGaussian.SemiprimeD1StackWordBlockBounds\nimport RiemannGaussian.SemiprimeD1StackUnaryProductRaw\n\n/-! # Physical marked first-input coefficient acquisition\nThe only inputs are original binary N, the original assignment, the actual\nunary descriptor index and the actual side singleton. The literal checker\nexecutes first. A marked successful row then reacquires its word and its\nradix-position shift from the retained physical inputs and paid caches.\nAll coefficient arithmetic remains binary; only bounded offsets are unary.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInput\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace P\nexport SemiprimeD1StackPublicInput (Stack Label program initial assignment index output modulusKey)\nend P\nnamespace B\nexport SemiprimeD1StackWordBlock (Label program)\nend B\nnamespace F\nexport SemiprimeD1StackWordFit (Label program)\nend F\nnamespace U\nexport SemiprimeD1StackUnaryProduct (Stack Label code entry)\nend U\n/-- Five private Boolean words; no derived number is an input cell. -/\ninductive Aux where\n  | side | widthTemplate | shifted | copyScratch | output\n  deriving DecidableEq, Repr\n/-- Complete literal private inventory, independent of the original input. -/\ninstance : Fintype Aux := Fintype.ofList\n  [.side,.widthTemplate,.shifted,.copyScratch,.output] (by intro k; cases k <;> simp)\n/-- All checker caches, five extractor allocations, four product roles and\nfive private words; the unused extractor-template shadow remains counted. -/\nabbrev Stack := P.Stack ⊕ (Fin 5 ⊕ (U.Stack ⊕ Aux))\n/-- Whole original checker bank retained by direct inclusion. -/\ndef checker : P.Stack → Stack := Sum.inl\n/-- Allocated extractor role, including its unused template shadow. -/\ndef word : Fin 5 → Stack := fun k => .inr (.inl k)\n/-- Actual offset-product roles. -/\ndef product : U.Stack → Stack := fun k => .inr (.inr (.inl k))\n/-- Private physical word. -/\ndef aux : Aux → Stack := fun k => .inr (.inr (.inr k))\n/-- Paid ell marker cache of the actual checker acquisition. -/\ndef ell : Stack := checker (.inl (.inl SemiprimeD1StackPublicInputWidth.widthKey))\n/-- Paid TRUE radix marker cache; this is not the signal-word width. -/\ndef radix : Stack := checker (.inl (.inl SemiprimeD1StackPublicInputWidth.radixKey))\n/-- Real word extraction directly shares the paid signal-width template. -/\ndef blockStack (k : Fin 5) : Stack :=\n  if k=1 then checker (.inl P.modulusKey) else word k\n/-- The real fitter reuses only the extractor's empty counter and scratch. -/\ndef fitStack (k : Fin 5) : Stack :=\n  if k=0 then aux .shifted else if k=1 then aux .widthTemplate\n  else if k=4 then aux .output else word k\n/-- Six static preserving-copy sources; no runtime role selector exists. -/\ndef copySource (kind : Fin 6) : Stack :=\n  if kind=0 then checker P.assignment else if kind=1 then checker P.index\n  else if kind=2 then radix else if kind=4 then word 4 else ell\n/-- Each destination is an actual empty or explicitly retained word. -/\ndef copyTarget (kind : Fin 6) : Stack :=\n  if kind=0 then word 0 else if kind=1 then product .multiplier\n  else if kind=2 then product .multiplicand else if kind=3 then product .product\n  else if kind=4 then aux .shifted else aux .widthTemplate\n/-- Literal three-role preserving-copy wiring. -/\ndef copyStack (kind : Fin 6) (k : Fin 3) : Stack :=\n  if k=0 then copySource kind else if k=1 then copyTarget kind else aux .copyScratch\n/-- Finite local stages contain no decoded operand, width or offset. -/\ninductive Control where\n  | start | checked | side | zero | one | raw | extract | index | radix | multiply\n  | offset | digit | shift | shiftZero | low | setOne | widthA | widthB | fit\n  | clearRaw | clearWord | clearRadix | done | bad\n  deriving DecidableEq, Repr\n/-- Explicit complete local control inventory. -/\ninstance : Fintype Control := Fintype.ofList\n  [.start,.checked,.side,.zero,.one,.raw,.extract,.index,.radix,.multiply,\n   .offset,.digit,.shift,.shiftZero,.low,.setOne,.widthA,.widthB,.fit,\n   .clearRaw,.clearWord,.clearRadix,.done,.bad] (by intro k; cases k <;> simp)\n/-- Every included label is static before N and the actual assignment. -/\nabbrev Label := Control ⊕ (P.Label ⊕ (B.Label ⊕ (U.Label ⊕ (F.Label ⊕ (Fin 6 × Fin 9)))))\n/-- Literal local stage inclusion. -/\ndef ctl : Control → Label := Sum.inl\n/-- Literal whole-checker label inclusion. -/\ndef checkerLabel : P.Label → Label := fun k => .inr (.inl k)\n/-- Literal extractor label inclusion. -/\ndef blockLabel : B.Label → Label := fun k => .inr (.inr (.inl k))\n/-- Literal unary-product label inclusion. -/\ndef productLabel : U.Label → Label := fun k => .inr (.inr (.inr (.inl k)))\n/-- Literal final-fitting label inclusion. -/\ndef fitLabel : F.Label → Label := fun k => .inr (.inr (.inr (.inr (.inl k))))\n/-- Literal preserving-copy label inclusion. -/\ndef copyLabel (kind : Fin 6) (k : Fin 9) : Label :=\n  .inr (.inr (.inr (.inr (.inr (kind,k)))))\n/-- One closed finite Boolean-stack instruction table. In particular, no\nnative digit extraction, multiplication, shift, fit or coefficient opcode occurs. -/\ndef program : Label → C.Instruction Stack Label\n  | .inl .start => .call (checkerLabel .start) (ctl .checked)\n  | .inl .checked => .base (.peek (checker P.output) (ctl .bad) (ctl .zero) (ctl .side))\n  | .inl .side => .base (.peek (aux .side) (ctl .bad) (ctl .raw) (ctl .one))\n  | .inl .zero => .base (.jump (ctl .widthA))\n  | .inl .one => .base (.push (aux .shifted) true (ctl .widthA))\n  | .inl .raw => .call (copyLabel 0 0) (ctl .extract)\n  | .inl .extract => .call (blockLabel .start) (ctl .index)\n  | .inl .index => .call (copyLabel 1 0) (ctl .radix)\n  | .inl .radix => .call (copyLabel 2 0) (ctl .multiply)\n  | .inl .multiply => .call (productLabel U.entry) (ctl .offset)\n  | .inl .offset => .call (copyLabel 3 0) (ctl .digit)\n  | .inl .digit => .call (copyLabel 4 0) (ctl .shift)\n  | .inl .shift => .base (.pop (product .product) (ctl .low) (ctl .shiftZero) (ctl .shiftZero))\n  | .inl .shiftZero => .base (.push (aux .shifted) false (ctl .shift))\n  | .inl .low => .base (.pop (aux .shifted) (ctl .bad) (ctl .setOne) (ctl .bad))\n  | .inl .setOne => .base (.push (aux .shifted) true (ctl .widthA))\n  | .inl .widthA => .call (copyLabel 5 0) (ctl .widthB)\n  | .inl .widthB => .call (copyLabel 5 0) (ctl .fit)\n  | .inl .fit => .call (fitLabel .start) (ctl .clearRaw)\n  | .inl .clearRaw => .base (.pop (word 0) (ctl .clearWord) (ctl .clearRaw) (ctl .clearRaw))\n  | .inl .clearWord => .base (.pop (word 4) (ctl .clearRadix) (ctl .clearWord) (ctl .clearWord))\n  | .inl .clearRadix => .base (.pop (product .multiplicand) (ctl .done) (ctl .clearRadix) (ctl .clearRadix))\n  | .inl .done | .inl .bad => .base .halt\n  | .inr (.inl k) => SemiprimeD1StackValidationLink.instruction checker checkerLabel (P.program k)\n  | .inr (.inr (.inl k)) => SemiprimeD1StackValidationLink.instruction blockStack blockLabel (B.program k)\n  | .inr (.inr (.inr (.inl k))) => SemiprimeD1StackMultiplierLink.instruction product productLabel (U.code k)\n  | .inr (.inr (.inr (.inr (.inl k)))) => SemiprimeD1StackValidationLink.instruction fitStack fitLabel (F.program k)\n  | .inr (.inr (.inr (.inr (.inr (kind,k))))) =>\n      SemiprimeD1StackMultiplierLink.instruction (copyStack kind) (copyLabel kind) (SemiprimeD1StackCopy.code k)\n/-- Initial private bank contains only the physical descriptor-side singleton. -/\ndef privateInput (side : List Bool) : Fin 5 ⊕ (U.Stack ⊕ Aux) → List Bool\n  | .inr (.inr .side) => side\n  | _ => []\n/-- Exactly four source words; every coefficient, metadata and work output is empty. -/\ndef initial (bits raw indexWord side : List Bool) : C.State Stack Label :=\n  ⟨some (ctl .start),none,none,\n    Sum.elim (P.initial bits raw indexWord).data (privateInput side),[]⟩\n/-- Every real block operand is distinct despite the direct template alias. -/\ntheorem block_injective : Function.Injective blockStack := by decide\n/-- The five real fitter operands remain distinct. -/\ntheorem fit_injective : Function.Injective fitStack := by decide\n/-- Each preserving-copy call has three genuinely distinct physical roles. -/\ntheorem copy_injective (kind : Fin 6) : Function.Injective (copyStack kind) := by\n  fin_cases kind <;> decide\n/-- Fixed genuine bit machine; descriptor acquisition remains caller work. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine\n  (checker (.inl SemiprimeD1StackPublicInputWidth.original)) (aux .output) (ctl .start) program\n/-- Every allocated role, including the unused template shadow, is counted. -/\ntheorem stack_card : Fintype.card Stack=66 := by decide\n/-- No unbounded metadata, coefficient or evaluator enters transient control. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackCalls.control_finite\n  (checker (.inl SemiprimeD1StackPublicInputWidth.original)) (aux .output) (ctl .start) program\n/-- All physical data and return alphabets are finite before the input. -/\ntheorem all_alphabets_finite : ∀ k, Finite (machine.Γ k) := SemiprimeD1StackCalls.all_alphabets_finite\n  (checker (.inl SemiprimeD1StackPublicInputWidth.original)) (aux .output) (ctl .start) program\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInput\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsResources\n/-! # All-role resources for the SAME actual retained-root-cache continuation -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsReady\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsExecution\nopen SemiprimeD1StackMarkedRootRecordsBounds SemiprimeD1StackMarkedRootRecordsView\nopen SemiprimeBitArithmetic (bitValue)\n/-- Initial continuation caches are paid by their actual old1804 acquisition, never supplied answers. -/\ntheorem initial_length (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (k : Stack) : ((ready bits hN).data k).length ≤ bits.length+RB.runBound bits := by\n  rcases k with k|k\n  · exact retained_length bits hc hN k\n  · rcases k with k|k\n    · exact Nat.zero_le _\n    · rcases k with k|k\n      · change (privateTable (SemiprimeD1StackMarkedRootRecordsTableView.tableWords bits [] [] [] [] []) k).length ≤ _\n        rw [congrFun (private_empty bits) k]\n        simp [privateTable]\n      · cases k <;> exact Nat.zero_le _\n/-- SAME ready source cannot execute successfully beyond its actual final halt. -/\ntheorem prefix_fuel_le (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (hr : C.run program fuel (ready bits hN)=some finish) :\n    fuel ≤ readyBound bits hN := by\n  obtain ⟨t,ht,he⟩ := ready_run bits hc hN\n  have hf : fuel ≤ t := by\n    by_contra hn\n    have h : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done bits hN)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Every ready-source prefix counts all retained1804/fresh53/private144/Aux10 and real returns. -/\ntheorem prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (hr : C.run program fuel (ready bits hN)=some finish) :\n    (∑ k : Stack,(finish.data k).length)+finish.frames.length ≤\n      2012*(bits.length+RB.runBound bits+readyBound bits hN) := by\n  have hd := SemiprimeD1StackReturnLink.run_data_bound program fuel (bits.length+RB.runBound bits) _ finish\n    (initial_length bits hc hN) hr\n  have hf := SemiprimeD1StackCalls.run_frame_bound program fuel _ finish hr\n  change finish.frames.length ≤ 0+fuel at hf\n  have ht := prefix_fuel_le bits hc hN fuel finish hr\n  have hs : (∑ k : Stack,(finish.data k).length) ≤ 2011*(bits.length+RB.runBound bits+fuel) := by\n    calc\n      _ ≤ ∑ _k : Stack,(bits.length+RB.runBound bits+fuel) := Finset.sum_le_sum (fun k _ => hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  omega\n/-- The continuation has its own paid source bound under the same fixed original-scope envelope. -/\ntheorem readyBound_le (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits) :\n    readyBound bits hN ≤ runBound bits := by\n  have h0 : readyBound bits hN ≤ timeBound bits hN := by unfold timeBound;omega\n  exact h0.trans (timeBound_le bits hc hN)\n/-- Actual compiled continuation starts with exactly the ACTUALLY acquired root cache. -/\nnoncomputable def machineReady (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (ready bits hN))\n      (some (SemiprimeD1StackCalls.configuration (done bits hN))) (readyBound bits hN) := by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (aux .output) (ctl .start) program\n  let h := ready_run bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Actual compiled ready prefixes include the complete2011-field bank and the real return word. -/\ntheorem machine_prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q => q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (ready bits hN)))=some cfg) :\n    (∑ k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      2012*(bits.length+RB.runBound bits+readyBound bits hN) := by\n  have he := SemiprimeD1StackCalls.run_correct originalInput (aux .output) (ctl .start) program fuel (ready bits hN)\n  have hh := he.trans hr\n  cases hrun : C.run program fuel (ready bits hN) with\n  | none => rw [hrun] at hh;cases hh\n  | some finish =>\n    rw [hrun] at hh\n    have hc' : SemiprimeD1StackCalls.configuration finish=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel finish hrun\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsReady\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsBounds\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsStorage\n/-! # Fixed-before-N source constants, genuine machine and all2011 prefix resources -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsResources\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsExecution\nopen SemiprimeD1StackMarkedRootRecordsBounds\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeReportPolynomialGrowth (Bound constant_bound identity_bound add_bound mul_bound pow_bound)\n/-- The actual width-only coefficient is one fixed polynomial BEFORE every original input. -/\ntheorem widthPolynomial_monomial : Bound widthPolynomial := by\n  have hr : Bound (fun n => RB.prefixPolynomial n 1) :=\n    SemiprimeD1StackRootNetworkRecordsResources.polynomial_monomial\n  have hv : Bound (fun n => 10^13*(n+1)^5) :=\n    mul_bound (constant_bound (10^13)) (pow_bound (add_bound identity_bound (constant_bound 1)) 5)\n  exact mul_bound (constant_bound 100) (add_bound (add_bound (add_bound identity_bound hr) hv) (constant_bound 2))\n/-- Fixed constants precede N; the same actual source has exponent58 times the original local-scope cap. -/\ntheorem runBound_monomial : ∃ A d : Nat, ∀ bits : List Bool,\n    runBound bits ≤ A*(bits.length+1)^d*2^(58*scopeCap bits) := by\n  obtain ⟨A,d,h⟩ := widthPolynomial_monomial\n  refine ⟨10^28*A^3,3*d,?_⟩\n  intro bits\n  have hp := Nat.pow_le_pow_left (h bits.length) 3\n  rw [mul_pow,←pow_mul,Nat.mul_comm d 3] at hp\n  have hc := Nat.mul_le_mul_right (2^(58*scopeCap bits)) (Nat.mul_le_mul_left (10^28) hp)\n  exact hc.trans_eq (by ring)\n/-- Complete SAME source and actual halt, with fixed constants before the input family. -/\ntheorem source_run_monomial : ∃ A d : Nat, ∀ (bits : List Bool)\n    (_hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits),\n    ∃ t ≤ A*(bits.length+1)^d*2^(58*scopeCap bits), C.run program t (initial bits)=some (done bits hN) := by\n  obtain ⟨A,d,h⟩ := runBound_monomial\n  refine ⟨A,d,?_⟩\n  intro bits hc hN\n  obtain ⟨t,ht,hr⟩ := source_run_bounded bits hc hN\n  exact ⟨t,ht.trans (h bits),hr⟩\n/-- Every actual source prefix counts ALL2011 roles, the shared-N shadow and every saved return. -/\ntheorem prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (hr : C.run program fuel (initial bits)=some finish) :\n    (∑ k : Stack,(finish.data k).length)+finish.frames.length ≤ 2012*(bits.length+runBound bits) := by\n  have hs := SemiprimeD1StackMarkedRootRecordsStorage.prefix_cells bits hc hN fuel finish hr\n  have ht := timeBound_le bits hc hN\n  omega\n/-- Genuine binary-N-only compiled machine with the SAME fixed original-scope source budget. -/\nnoncomputable def machineSource (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits hN))) (runBound bits) := by\n  rw [SemiprimeD1StackMarkedRootRecordsStorage.initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (aux .output) (ctl .start) program\n  let h := source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every actual compiled prefix includes the full2011 words AND real finite-label return stack. -/\ntheorem machine_prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q => q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑ k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 2012*(bits.length+runBound bits) := by\n  have hs := SemiprimeD1StackMarkedRootRecordsStorage.machine_prefix_cells bits hc hN fuel cfg hr\n  have ht := timeBound_le bits hc hN\n  omega\n/-- Fixed width-only coefficient for the entire source's all-role storage envelope. -/\ndef spaceWidth (n : Nat) : Nat := 2012*(n+10^28*(widthPolynomial n)^3)\n/-- Storage coefficients too are fixed before the whole original input family. -/\ntheorem spaceWidth_monomial : Bound spaceWidth :=\n  mul_bound (constant_bound 2012) (add_bound identity_bound\n    (mul_bound (constant_bound (10^28)) (pow_bound widthPolynomial_monomial 3)))\n/-- SAME actual-prefix resource bound at the original scope rate. -/\ntheorem prefix_scope_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0 < bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (hr : C.run program fuel (initial bits)=some finish) :\n    (∑ k : Stack,(finish.data k).length)+finish.frames.length ≤ spaceWidth bits.length*2^(58*scopeCap bits) := by\n  have hs := prefix_cells bits hc hN fuel finish hr\n  have hn := Nat.le_mul_of_pos_right bits.length (by positivity : 0 < (2:Nat)^(58*scopeCap bits))\n  unfold spaceWidth runBound at *\n  nlinarith only [hs,hn]\n/-- All prefix cells and real returns admit fixed polynomial constants BEFORE N. -/\ntheorem prefix_monomial : ∃ A d : Nat, ∀ (bits : List Bool)\n    (_hc : SemiprimeSourceCompactBits.Compact bits) (_hN : 0 < bitValue bits)\n    (fuel : Nat) (finish : C.State Stack Label) (_hr : C.run program fuel (initial bits)=some finish),\n    (∑ k : Stack,(finish.data k).length)+finish.frames.length ≤ A*(bits.length+1)^d*2^(58*scopeCap bits) := by\n  obtain ⟨A,d,h⟩ := spaceWidth_monomial\n  refine ⟨A,d,?_⟩\n  intro bits hc hN fuel finish hr\n  exact (prefix_scope_cells bits hc hN fuel finish hr).trans (Nat.mul_le_mul_right _ (h bits.length))\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsResources\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsBody\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsCleanup\n/-! # One complete original-order row, including byte acquisition and cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRows\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsView\nopen SemiprimeD1StackMarkedRootRecordsRowView SemiprimeD1StackMarkedRootRecordsEncoding\nopen SemiprimeD1StackMarkedRootRecordsBody SemiprimeD1StackMarkedRootRecordsCleanup\nopen SemiprimeD1StackMarkedRootRecordsPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- All five descriptor byte lengths; this proof precedes any concrete graph instantiation. -/\ntheorem mass_eq (fields : Fin 5 → List Bool) :\n    SemiprimeD1StackMarkedRootRecordsParse.mass fields=\n      (fields 0).length+(fields 1).length+(fields 2).length+(fields 3).length+(fields 4).length := by\n  simp only [SemiprimeD1StackMarkedRootRecordsParse.mass,Fin.sum_univ_succ,Fin.sum_univ_zero]\n  change (fields 0).length+((fields 1).length+((fields 2).length+((fields 3).length+((fields 4).length+0))))=_\n  omega\n/-- The common logger consumes exactly the original port tape on both actual branches. -/\ntheorem branch_ports (bits : List Bool) (row : Row) : (branchTable bits row).portsWord=vectorBits row.scope := by\n  cases h : row.inputSide <;> simp only [branchTable,h]\n/-- The common logger sees the actual new marked table or byte-identical original relay. -/\ntheorem branch_table (bits : List Bool) (row : Row) : (branchTable bits row).tableWord=newTable bits row := by\n  cases h : row.inputSide <;> simp only [branchTable,newTable,h]\n/-- The actual log accumulator is unchanged by the tag/side/table acquisition. -/\ntheorem branch_history (row : Row) (rec desc hist out : List Bool) :\n    (branchWork row rec desc hist out).history=hist := by cases h : row.inputSide <;> simp only [branchWork,h]\n/-- Every physically acquired count/side and every retained raw field byte is paid in cleanup. -/\ntheorem cleanup_bound (bits : List Bool) (row : Row) (rec desc hist out : List Bool) :\n    let p := branchTable bits row\n    let w := branchWork row rec desc hist out\n    w.tag.length+w.coord0.length+p.indexWord.length+w.coord2.length+w.coord3.length+\n      p.sideWord.length+p.countWord.length+8 ≤\n      SemiprimeD1StackMarkedRootRecordsParse.mass row.fields+row.scope.length+10 := by\n  have hm := mass_eq row.fields\n  cases h : row.inputSide <;>\n    simp only [branchTable,branchWork,h,List.length_cons,List.length_nil,List.length_replicate] <;> omega\n/-- Own per-row cap sums only the actual parser/source/logger/cleanup caps. -/\ndef rowBudget (bits : List Bool) (row : Row) : Nat :=\n  8*((vectorBits row.scope).length+row.oldTable.length+SemiprimeD1StackMarkedRootRecordsParse.mass row.fields)+57+\n    bodyBudget bits row+(3*((vectorBits row.scope).length+(newTable bits row).length)+7)+\n    (SemiprimeD1StackMarkedRootRecordsParse.mass row.fields+row.scope.length+10)\n/-- All actual parsed fields and counted arity words are empty at the next physical row boundary. -/\ntheorem row_run (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (row : Row) (recordTail descriptorTail hist out : List Bool)\n    (hn : r R.originalInput=bits) (hb : bits≠[]) :\n    ∃ t ≤ rowBudget bits row, Runs program t (ctl .rowTag)\n      (view r v bits {} {records := true::frame (vectorBits row.scope) (frame row.oldTable recordTail),descriptors := SemiprimeD1EdgeCatalogueEncoding.record row.fields descriptorTail,history := hist,output := out})\n      (ctl .rowTag)\n      (view r v bits {} {records := recordTail,descriptors := descriptorTail,history := (newRow bits row).reverse++hist,output := out}) := by\n  have h0 := SemiprimeD1StackMarkedRootRecordsParse.parse_run r v bits (vectorBits row.scope)\n    row.oldTable row.fields recordTail descriptorTail hist out\n  obtain ⟨a,ha,h1⟩ := body_run r v bits row recordTail descriptorTail hist out hn hb\n  let p := branchTable bits row\n  let w := branchWork row recordTail descriptorTail hist out\n  have h2 := log_run r v bits p w\n  have h3 := cleanup_run r v bits {p with portsWord := [],tableWord := []}\n    {w with history := (SemiprimeD1StackVertexRecordStream.row p.portsWord p.tableWord).reverse++w.history}\n  have h := join h0 (join h1 (join h2 h3))\n  have hc := cleanup_bound bits row recordTail descriptorTail hist out\n  let t := (8*((vectorBits row.scope).length+row.oldTable.length+SemiprimeD1StackMarkedRootRecordsParse.mass row.fields)+57)+\n    (a+((SemiprimeD1StackVertexRecordStream.recordTime p.portsWord p.tableWord+1)+\n      (w.tag.length+w.coord0.length+p.indexWord.length+w.coord2.length+w.coord3.length+p.sideWord.length+p.countWord.length+8)))\n  refine ⟨t,?_,?_⟩\n  · dsimp only [t,p,w] at *\n    unfold rowBudget SemiprimeD1StackVertexRecordStream.recordTime\n    rw [branch_ports,branch_table]\n    omega\n  · change Runs program t _ _ _ _ at h\n    dsimp only [p,w] at h\n    cases hs : row.inputSide <;>\n      simpa only [t,p,w,branchTable,branchWork,newRow,newTable,hs] using h\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRows\n","RiemannGaussian.SemiprimeD1StackNetworkRowsOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsBounds\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsOrder\n/-! # Actual whole original-network owner rows and n/F/M acquisition\nALL original well-formed networks discharge the physical lookup contracts.\nRuntime input remains only the old complete vertex records and unary left\ncount; the global N-only producer/controller join is separate work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkRowsOriginal\nopen SemiprimeD1StackNetworkRows SemiprimeD1StackNetworkRowsExecution\nopen SemiprimeD1StackNetworkRowsEncoding SemiprimeD1StackNetworkRowsOrder\nopen SemiprimeD1StackNetworkRowsLoop SemiprimeD1StackNetworkRowsBounds\nnamespace Net\nexport SemiprimeD1TensorNetwork (Network WellFormed vertices)\nend Net\n/-- Every physically parsed original factor port has the unique actual-index singleton and allocated owner width. -/\ntheorem original_contract (net:Net.Network) (hw:Net.WellFormed net) :\n    ∀v∈net.right.toList,∀p∈v.ports,\n      SemiprimeD1StackOwnerFibre.values (SemiprimeD1StackUnaryDivmod.unary p) (dictionaryRows net.left.toList)=[ownerAt net p] ∧\n        (ownerAt net p).length≤net.left.toList.length+1 :=by\n  intro v hv p hp\n  have h:=right_port_lt net hw v hv p hp\n  exact ⟨original_singleton net hw p h,by rw [ownerAt_length net p h,Vector.length_toList]⟩\n/-- The two physical inputs are EXACTold original vertex bytes and the acquired unary left count. -/\ntheorem initial_original (net:Net.Network) :\n    source net.left.toList net.right.toList=\n      initial (SemiprimeD1StackVertexProduct.records (Net.vertices net)) (List.replicate net.leftCount true) :=by\n  unfold source inputTape\n  rw [SemiprimeD1StackNetworkOwnerIndexOriginal.input_original,Vector.length_toList]\n/-- Same-program final bank for the entire original family; no routing/rows function is a runtime argument. -/\ndef originalDone (net:Net.Network) :C.State Stack Label :=done net.left.toList net.right.toList (ownerAt net)\n/-- Exact old literal row order, repetitions and empty rows, with n+1-bit binary owner fields. -/\ntheorem output_original (net:Net.Network) (hw:Net.WellFormed net) :\n    (originalDone net).data (aux .output)=originalTape net :=by\n  change rowsTape (resolvedRows net)=_\n  exact rowsTape_original net hw\n/-- Every original index/source/factor-suffix/catalogue cache word survives the whole physical row producer. -/\ntheorem index_retained (net:Net.Network) (k:I.Stack) :\n    (originalDone net).data (indexStack k)=\n      SemiprimeD1StackNetworkOwnerIndexExecution.result net.left.toList\n        (SemiprimeD1StackVertexProduct.records net.right.toList) k :=rfl\n/-- Actual n metadata is retained directly from the acquired count input. -/\ntheorem left_count (net:Net.Network) :\n    (originalDone net).data (indexStack .leftCount)=List.replicate net.leftCount true :=by\n  rw [index_retained]\n  simpa only [SemiprimeD1StackNetworkOwnerIndexExecution.done,Vector.length_toList] using SemiprimeD1StackNetworkOwnerIndexExecution.count_retained net.left.toList\n    (SemiprimeD1StackVertexProduct.records net.right.toList)\n/-- Every original factor, including zero-port factors, physically pushes one marker. -/\ntheorem factor_count (net:Net.Network) :\n    (originalDone net).data (aux .factors)=List.replicate net.rows.length true :=by\n  change List.replicate net.right.toList.length true=_\n  rw [Vector.length_toList]\n/-- Every original local occurrence physically pushes one marker; repeated owners remain separate. -/\ntheorem occurrence_count (net:Net.Network) (hw:Net.WellFormed net) :\n    (originalDone net).data (aux .occurrences)=List.replicate net.rows.flatten.length true :=by\n  change List.replicate (occurrences net.right.toList) true=_\n  rw [occurrences,SemiprimeD1StackNetworkRowsOrder.occurrence_count net hw]\n/-- Original right-record suffix remains exactly intact in the included index bank. -/\ntheorem factors_retained (net:Net.Network) :\n    (originalDone net).data (indexStack .reader)=SemiprimeD1StackVertexProduct.records net.right.toList :=by\n  rw [index_retained]\n  simpa only [SemiprimeD1StackNetworkOwnerIndexExecution.done] using\n    SemiprimeD1StackNetworkOwnerIndexExecution.suffix_retained net.left.toList\n      (SemiprimeD1StackVertexProduct.records net.right.toList)\n/-- All private fibre roles, including the allocated unused query shadow, are EMPTY at whole halt. -/\ntheorem fibre_clear (net:Net.Network) (k:F.Stack) :\n    (originalDone net).data (.inr (.inl k))=[] :=rfl\n/-- Whole original-family source pays the fixed physical-input polynomial and returns exact old rows/n/F/M. -/\ntheorem source_original (net:Net.Network) (hw:Net.WellFormed net) :\n    ∃q≤10000000000*((SemiprimeD1StackVertexProduct.records (Net.vertices net)).length+net.leftCount+1)^3,\n      SemiprimeD1StackCalls.run program q\n        (initial (SemiprimeD1StackVertexProduct.records (Net.vertices net)) (List.replicate net.leftCount true))=\n          some (originalDone net) ∧\n      (originalDone net).data (aux .output)=originalTape net ∧\n      (originalDone net).data (indexStack .leftCount)=List.replicate net.leftCount true ∧\n      (originalDone net).data (aux .factors)=List.replicate net.rows.length true ∧\n      (originalDone net).data (aux .occurrences)=List.replicate net.rows.flatten.length true :=by\n  obtain ⟨q,hq,hr⟩:=source_run_bounded net.left.toList net.right.toList (ownerAt net) (original_contract net hw)\n  refine ⟨q,?_,?_,output_original net hw,left_count net,factor_count net,occurrence_count net hw⟩\n  · simpa only [polynomial,inputSize,inputTape,SemiprimeD1StackNetworkOwnerIndexOriginal.input_original,\n      Vector.length_toList] using hq\n  · simpa only [initial_original,originalDone] using hr\n/-- Genuine compiled finite-machine time certificate for ALL original well-formed network tapes. -/\nnoncomputable def originalInTime (net:Net.Network) (hw:Net.WellFormed net) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackVertexProduct.records (Net.vertices net)) (List.replicate net.leftCount true)))\n      (some (SemiprimeD1StackCalls.configuration (originalDone net)))\n      (polynomial net.left.toList net.right.toList) :=by\n  rw [←initial_original]\n  exact rowsInTime _ _ _ (original_contract net hw)\n/-- Actual-cache ready source gives the SAMEoriginal output/n/F/M and retains every index word, without rerunning Index17. -/\ntheorem ready_original (net:Net.Network) (hw:Net.WellFormed net) :\n    ∃q ≤ polynomial net.left.toList net.right.toList,\n      SemiprimeD1StackCalls.run program q (ready net.left.toList net.right.toList)=some (originalDone net) ∧\n      (originalDone net).data (aux .output)=originalTape net ∧\n      (originalDone net).data (indexStack .leftCount)=List.replicate net.leftCount true ∧\n      (originalDone net).data (aux .factors)=List.replicate net.rows.length true ∧\n      (originalDone net).data (aux .occurrences)=List.replicate net.rows.flatten.length true :=by\n  obtain ⟨q,hq,hr⟩:=ready_run_bounded net.left.toList net.right.toList (ownerAt net) (original_contract net hw)\n  exact ⟨q,hq,hr,output_original net hw,left_count net,factor_count net,occurrence_count net hw⟩\nend RiemannGaussian.SemiprimeD1StackNetworkRowsOriginal\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseFinalCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseCleanup\n/-! # Actual complete54-word final sweep: retain only three inputs and chronological output -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseFinalCleanup\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseInventory SemiprimeD1StackNormalizedInverseCalls\nopen SemiprimeD1StackNormalizedInverseCleanup SemiprimeD1StackProcedureTrace\n/-- Precisely the physical original array/q/W words and the actually emitted output survive. -/\ndef retained (k : Stack) : Prop := k=template ∨ k=aux .denominator ∨ k=aux .originalQ ∨ k=aux .output\n/-- Exact endpoint of the actual fixed literal54-word sweep. -/\nnoncomputable def cleanStore (data : Stack→List Bool) : Stack→List Bool := by\n  classical\n  exact fun k=>if retained k then data k else []\n/-- No uncounted field or shadow is omitted from the real successful cleanup. -/\ntheorem work_mem_iff (k : Stack) : k∈roles workRole ↔ ¬retained k := by\n  constructor\n  · intro h\n    obtain ⟨i,_,hi⟩:=List.mem_map.mp h\n    intro hk\n    rcases hk with hk|hk|hk|hk\n    · exact workRole_not_template i (hi.trans hk)\n    · exact workRole_not_denominator i (hi.trans hk)\n    · exact workRole_not_q i (hi.trans hk)\n    · exact workRole_not_output i (hi.trans hk)\n  · intro h\n    have ht : k≠template := fun he=>h (Or.inl he)\n    have ha : k≠aux .denominator := fun he=>h (Or.inr (Or.inl he))\n    have hq : k≠aux .originalQ := fun he=>h (Or.inr (Or.inr (Or.inl he)))\n    have ho : k≠aux .output := fun he=>h (Or.inr (Or.inr (Or.inr he)))\n    obtain ⟨i,hi⟩:=workRole_complete k ht ha hq ho\n    exact List.mem_map.mpr ⟨i,List.mem_finRange i,hi⟩\n/-- Mathematical equality specifies the endpoint of THIS actual sweep; no execution clock is transported. -/\ntheorem final_cleared (data : Stack→List Bool) : cleared workRole data 54=cleanStore data := by\n  classical\n  funext k\n  rw [cleared_full,work_mem_iff]\n  by_cases h:retained k <;> simp only [cleanStore,h,not_true_eq_false,not_false_eq_true,ite_true,ite_false]\n/-- ALL54 real drain loops execute through actual EOF before the single final halt. -/\ntheorem final_run (data : Stack→List Bool) :\n    ∃q≤54*(mass data+1),Runs program q (ctl (.clearFinal 0)) data (ctl .done) (cleanStore data) := by\n  have hc : ∀i:Fin 54,program (ctl (.clearFinal i))=.base\n      (.pop (workRole i) (next (fun j=>ctl (.clearFinal j)) (ctl .done) i)\n        (ctl (.clearFinal i)) (ctl (.clearFinal i))) := by\n    intro i\n    have hh:i.val+1<54 ↔ i.val<54-1 := by omega\n    simp only [program,ctl,finalNext,next,hh]\n  obtain ⟨q,hq,hr⟩:=sweep (by decide:0<54) workRole (fun j=>ctl (.clearFinal j)) (ctl .done) hc 53 0 rfl data\n  refine ⟨q,by omega,?_⟩\n  simpa only [cleared_zero,final_cleared,show (⟨0,by decide⟩:Fin 54)=0 from Fin.ext rfl] using hr\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseFinalCleanup\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseFinishLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseFinishRow\n/-! # Whole actual newest-first to chronological rational-array reversal -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseFinishLoop\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInversePrimitives SemiprimeD1StackNormalizedInverseFinishBuffers\nopen SemiprimeD1StackNormalizedInverseFinishRow SemiprimeD1StackProcedureTrace\n/-- Actual row-cap sum plus the final FALSE pop and real empty-word peek. -/\ndef finishTime : List SemiprimeRationalBits.RationalWord→ℕ\n  | []=>2\n  | word::words=>15*((signed word).length+word.denominator.length)+30+finishTime words\n/-- Proof codec of the exact chronological output acquired by the actual prepend loop. -/\ndef outputRows (words : List SemiprimeRationalBits.RationalWord) (out : List Bool) : List Bool :=\n  words.foldl (fun tail word=>row word tail) out\n/-- The loop retains ALL raw coefficient fields and reverses only their row order. -/\ntheorem outputRows_reverse (words : List SemiprimeRationalBits.RationalWord) (out : List Bool) :\n    outputRows words out=words.reverse.foldr row out := by\n  rw [outputRows,List.foldl_eq_foldr_reverse]\n/-- Complete actual final row loop, including empty array and real EOF validation. -/\ntheorem finish_run (w : Words) (words : List SemiprimeRationalBits.RationalWord) (out : List Bool)\n    (hn : w.registers (.left,false)=[]) (hd : w.registers (.left,true)=[])\n    (hs : w.auxiliary .fieldFrameScratch=[]) (hv : w.auxiliary .valid=[]) :\n    Runs program (finishTime words) (ctl .finalTag) (store (finishBuffers w (tape words) out))\n      (ctl (.clearFinal 0)) (store (finishBuffers w [] (outputRows words out))) := by\n  induction words generalizing out with\n  | nil=>\n    have h0:=pop_run (ctl .finalTag) (ctl (.abort 0)) (ctl .finalEnd) (ctl (.finalField false)) (aux .prefixReverse)\n      (store (finishBuffers w [false] out)) [false] rfl rfl\n    simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n    rw [update_prefix] at h0\n    have h1:=peek_run (ctl .finalEnd) (ctl (.clearFinal 0)) (ctl (.abort 0)) (ctl (.abort 0)) (aux .prefixReverse)\n      (store (finishBuffers w [] out)) [] rfl rfl\n    have h:=join h0 h1\n    convert h using 1 <;> rfl\n  | cons word words ih=>\n    have h0:=row_run w word (tape words) out hn hd hs hv\n    have h1:=ih (row word out)\n    have h:=join h0 h1\n    convert h using 1 <;> rfl\n/-- This SAME whole physical reversal has a linear cap in its actual input array bytes. -/\ntheorem finishTime_le (words : List SemiprimeRationalBits.RationalWord) :\n    finishTime words≤20*(tape words).length := by\n  induction words with\n  | nil=>decide\n  | cons word words ih=>\n    change 15*((signed word).length+word.denominator.length)+30+finishTime words≤20*(row word (tape words)).length\n    rw [row_length]\n    omega\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseFinishLoop\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseWidths":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseRecurrence\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseView\n/-! # Actual coefficient and encoded-prefix byte bounds, including W=0 and missing ZERO -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseWidths\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseSpec SemiprimeD1StackNormalizedInverseRecurrence\nopen SemiprimeRationalBits SemiprimeJetBits\n/-- Both real cache fields are counted, including the actual signed prefix. -/\ndef bytes (word : RationalWord) : ℕ := (signed word).length+word.denominator.length\n/-- EVERY operation returns exactly both actual fitted widths and its physical sign, without validity/Fits advice. -/\ntheorem execute_bytes (op : Operation) (x y : RationalWord) (width : List Bool) :\n    bytes (executeOperation op x y width).word=2*width.length+1 := by\n  have h:=fitRationalBits_width (rawOperation op x y).word width\n  change (signed (fitRationalBits (rawOperation op x y).word width).word).length+\n    (fitRationalBits (rawOperation op x y).word width).word.denominator.length=_\n  rw [signed,List.length_cons,h.1,h.2]\n  omega\n/-- The exact product-first/suffix-second result has fitted width even for zero denominators and W=0. -/\ntheorem combine_bytes (width : List Bool) (pair : RationalWord×RationalWord) (acc : RationalWord) :\n    bytes (combine width pair acc)=2*width.length+1 := execute_bytes .add _ _ width\n/-- The original ONE has its literal three physical cache bytes, independently of W. -/\ntheorem one_bytes : bytes oneWord=3 := rfl\n/-- The default/initial ZERO is literal and unfitted, even when W=0. -/\ntheorem zero_bytes : bytes zeroWord=2 := rfl\n/-- Every decreasing-loop accumulator remains physically bounded by W or its actual initial fields. -/\ntheorem dotLoop_bytes (width : List Bool) (a : Array RationalWord) (reversed : List RationalWord) (n : ℕ)\n    (acc : RationalWord) (hacc : bytes acc≤2*width.length+3) :\n    bytes (dotLoop width a reversed n acc)≤2*width.length+3 := by\n  induction n generalizing acc with\n  | zero=>exact hacc\n  | succ n ih=>\n    rw [dotLoop]\n    exact ih _ (by rw [combine_bytes];omega)\n/-- A typed physical row contains both entire coefficient fields, delimiters and its tag. -/\ntheorem row_bytes (word : RationalWord) (tail : List Bool) :\n    (row word tail).length=2*bytes word+tail.length+3 := by\n  rw [row_length]\n  unfold bytes\n  omega\n/-- Any zero-extended physical read is paid by the actual array bytes, including its default ZERO. -/\ntheorem read_bytes (words : List RationalWord) (n : ℕ) : bytes (readWord words n)≤(tape words).length+2 := by\n  induction words generalizing n with\n  | nil=>simp only [readWord,List.getElem?_nil,Option.getD_none,zero_bytes,tape,List.foldr_nil,List.length_cons,List.length_nil];omega\n  | cons word words ih=>\n    cases n with\n    | zero=>\n      change bytes word≤(row word (tape words)).length+2\n      rw [row_bytes]\n      omega\n    | succ n=>\n      have h:=ih n\n      change bytes (readWord words n)≤(row word (tape words)).length+2\n      rw [row_bytes]\n      omega\n/-- Encoded-array storage is charged coefficient-by-coefficient, preserving all raw padding. -/\ntheorem tape_bytes (words : List RationalWord) (cap : ℕ) (hc : ∀word∈words,bytes word≤cap) :\n    (tape words).length≤words.length*(2*cap+3)+1 := by\n  induction words with\n  | nil=>simp only [tape,List.foldr_nil,List.length_cons,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons word words ih=>\n    have hw:=hc word List.mem_cons_self\n    have hh:=ih (fun w h=>hc w (List.mem_cons_of_mem word h))\n    change (row word (tape words)).length≤(words.length+1)*(2*cap+3)+1\n    rw [row_bytes,Nat.add_mul]\n    omega\n/-- ALL native cached inverse coefficients have the actual fitted width or the literal initial ONE width. -/\ntheorem build_bytes (width : List Bool) (a : Array RationalWord) (n : ℕ) :\n    ∀word∈(SemiprimeNormalizedInverseBits.build width a n).words.toList,bytes word≤2*width.length+3 := by\n  induction n with\n  | zero=>intro word h;exact (List.not_mem_nil h).elim\n  | succ n ih=>\n    intro word hw\n    by_cases hz:n=0\n    · subst n\n      change word∈[oneWord] at hw\n      have he:=List.mem_singleton.mp hw\n      rw [he,one_bytes]\n      omega\n    · simp only [SemiprimeNormalizedInverseBits.build,SemiprimeNormalizedInverseBits.extend,hz,ite_false,\n        Array.toList_push,List.mem_append,List.mem_singleton] at hw\n      rcases hw with hw|hw\n      · exact ih word hw\n      · rw [hw,execute_bytes]\n        omega\n/-- Complete physical inverse-prefix storage is quadratic in acquired q/W bytes, even for arbitrary invalid denominator words. -/\ntheorem build_tape_bytes (width : List Bool) (a : Array RationalWord) (n : ℕ) :\n    (tape (SemiprimeNormalizedInverseBits.build width a n).words.toList.reverse).length≤n*(4*width.length+9)+1 := by\n  have h:=tape_bytes (SemiprimeNormalizedInverseBits.build width a n).words.toList.reverse (2*width.length+3)\n    (by intro word hw;exact build_bytes width a n word (List.mem_reverse.mp hw))\n  simpa only [List.length_reverse,Array.length_toList,SemiprimeNormalizedInverseBits.build_size,\n    show 2*(2*width.length+3)+3=4*width.length+9 by omega] using h\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseWidths\n","RiemannGaussian.SemiprimeD1StackOldVertexStreamOperands":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOldVertexStreamView\n/-! # Exact physical operands of the included whole vertex source\nOnly three parsed fields and one physically popped activity bit enter the raw\nwork bank. Four actual caller headers are shared through immutable aliases.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOldVertexStreamOperands\nopen SemiprimeD1StackOldVertexStream SemiprimeD1StackOldVertexStreamRoles\nopen SemiprimeD1StackOldVertexStreamView\n/-- Exactly the three parsed source fields and acquired singleton activity. -/\ndef sparse (parent order scope bit : List Bool) : ChoiceStack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (fun _=>[]) parentRole parent)\n    orderRole order) scopeRole scope) X.activity bit\n/-- The materialized actual header aliases plus these four work words are the ENTIRE real169 source entry. -/\ntheorem initial_sparse (i : Inputs) (parent order scope bit : List Bool) :\n    materialize i (sparse parent order scope bit)=\n      (SemiprimeD1StackChildVertexChoice.initial parent order i.oldAxes i.oldPrecision i.newAxes i.newPrecision scope bit).data:=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rcases k with k|k\n          · rcases k with k|k\n            · rfl\n            · rcases k with k|k\n              · rfl\n              · fin_cases k <;> rfl\n          · rcases k with k|k\n            · rcases k with k|k\n              · rfl\n              · rcases k with k|k\n                · rfl\n                · fin_cases k <;> rfl\n            · rcases k with k|k\n              · cases k <;> rfl\n              · rcases k with k|k\n                · cases k <;> rfl\n                · rcases k with k|k\n                  · cases k <;> rfl\n                  · cases k <;> rfl\n        · rcases k with k|k\n          · cases k <;> rfl\n          · cases k <;> rfl\n    · cases k <;> rfl\n  · rcases k with k|k\n    · change []=(if _ then [] else [])\n      split <;> rfl\n    · cases k;rfl\n/-- A complete native stopped source whose four headers survive is read through the SAME aliases. -/\ntheorem materialize_eq (i : Inputs) (source : ChoiceStack→List Bool)\n    (h0 : source (axesRole false)=i.oldAxes) (h1 : source (precisionRole false)=i.oldPrecision)\n    (h2 : source (axesRole true)=i.newAxes) (h3 : source (precisionRole true)=i.newPrecision) :\n    materialize i source=source:=by\n  funext k\n  unfold materialize\n  split_ifs with ha hp hb hq\n  · subst k;exact h0.symm\n  · subst k;exact h1.symm\n  · subst k;exact h2.symm\n  · subst k;exact h3.symm\n  · rfl\n/-- Complete empty work remains empty even at every displaced header role. -/\ntheorem mask_empty : mask (fun _=>[])=fun _=>[]:=by\n  funext k\n  unfold mask\n  split <;> rfl\nend RiemannGaussian.SemiprimeD1StackOldVertexStreamOperands\n","RiemannGaussian.SemiprimeD1StackOrdinalBankMachine":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOrdinalBankLoop\n/-! # Actual tally-only ordinal-bank machine and every-prefix storage -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackOrdinalBankMachine\nopen SemiprimeD1StackOrdinalBank SemiprimeD1StackOrdinalBankLoop\n\n/-- The ready supplier has ONLY its physically acquired marker tally as input. -/\ntheorem initial_eq (tally : List Bool) :\n    Turing.initList machine tally=SemiprimeD1StackCalls.configuration (initial tally) := by\n  have hs : initial tally=SemiprimeD1StackCalls.initial count (.inl .start) tally := by\n    unfold initial SemiprimeD1StackCalls.initial\n    congr 1\n    funext k\n    rcases k with k|k <;> cases k <;> simp [data,count,SemiprimeD1StackAssignmentLoop.data]\n  rw [hs]\n  exact (SemiprimeD1StackCalls.initial_correct count ids (.inl .start) program tally).symm\n\n/-- Real finite-alphabet execution, with no M/cardinality/width/ID answer input. -/\nnoncomputable def bankInTime (tally : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine tally)\n      (some (SemiprimeD1StackCalls.configuration (done tally))) (1000*(tally.length+1)^2) := by\n  rw [initial_eq tally]\n  apply SemiprimeD1StackCalls.evalsCorrect count ids (.inl .start) program\n  let cert:=source_run tally\n  let m:=Classical.choose cert\n  have hs:=Classical.choose_spec cert\n  exact ⟨⟨m,hs.2⟩,hs.1⟩\n\n/-- All actual prefixes are bounded by this program's own executed halt. -/\ntheorem prefix_fuel_le (tally : List Bool) (fuel : ℕ)\n    (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial tally)=some out) :\n    fuel≤1000*(tally.length+1)^2 := by\n  obtain ⟨time,ht,he⟩:=source_run tally\n  have hf : fuel≤time := by\n    by_contra hn\n    have h : fuel=time+(1+(fuel-(time+1))) := by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : SemiprimeD1StackCalls.run program 1 (done tally)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n\n/-- Every visited configuration counts all nine Boolean stacks and real returns. -/\ntheorem prefix_cells (tally : List Bool) (fuel : ℕ)\n    (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial tally)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤\n      10*(tally.length+1000*(tally.length+1)^2+1) := by\n  have hi : ∀k:Stack,((initial tally).data k).length≤tally.length := by\n    intro k\n    rcases k with k|k <;> cases k <;> simp [initial,data,SemiprimeD1StackAssignmentLoop.data]\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel tally.length _ out hi hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k:Stack,(out.data k).length)≤9*(tally.length+fuel) := by\n    calc\n      _≤∑_k:Stack,(tally.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by\n        have hcard : Fintype.card Stack=9 := by decide\n        simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul,hcard]\n  have ht:=prefix_fuel_le tally fuel out hr\n  omega\n\n/-- Same closed bound for all prefixes of the actual compiled FinTM2. -/\ntheorem machine_prefix_cells (tally : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine tally))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      10*(tally.length+1000*(tally.length+1)^2+1) := by\n  have he:=SemiprimeD1StackCalls.run_correct count ids (.inl .start) program fuel (initial tally)\n  change (SemiprimeD1StackCalls.run program fuel (initial tally)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial tally))) at he\n  have hh : (SemiprimeD1StackCalls.run program fuel (initial tally)).map SemiprimeD1StackCalls.configuration=some cfg :=\n    he.trans ((congrArg (fun start:machine.Cfg=>\n      (fun q:Option machine.Cfg=>q.bind machine.step)^[fuel] (some start)) (initial_eq tally).symm).trans hr)\n  cases hrun:SemiprimeD1StackCalls.run program fuel (initial tally) with\n  | none => rw [hrun] at hh; cases hh\n  | some out =>\n    rw [hrun] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells tally fuel out hrun\n\nend RiemannGaussian.SemiprimeD1StackOrdinalBankMachine\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeExecution\nimport RiemannGaussian.SemiprimeD1StackRootScopeBankBounds\nimport RiemannGaussian.SemiprimeD1StackOwnerEqualityKeyBounds\n/-! # Original-N forward endpoint/owner-ID catalogue source\nThis literal program runs original Edge13/count/M-bank acquisition once, parses\nactual six-field edge records, and consumes ONE actual ascending M-bit ID for\neach of the original E wires. Both endpoint keys share that same owner ID.\nArithmetic endpoints execute the complete physical recipe; equality endpoints\nexecute actual six-field framing and sentinel-copy. No permutation/key/count\nanswer or native edge enumeration is a runtime input. Execution proofs follow\nin separate modules; the program alone is not a completed acquisition theorem.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogue\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run step execute)\nend C\nnamespace S\nexport SemiprimeD1StackRootScopeBank (Stack Label program input originalInput edgeStack ids)\nend S\nnamespace R\nexport SemiprimeD1StackPortOwnerRecipe (Input Register Aux Stack Label program)\nend R\nnamespace Q\nexport SemiprimeD1StackOwnerEqualityKey (Stack Label program)\nend Q\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Exactly the47 actual arithmetic caches/scratch/output roles, excluding readonly inputs. -/\nabbrev RecipeWork := R.Register⊕R.Aux\n/-- Twelve fixed reader, parser, equality-key and output collector roles. -/\ninductive Aux where\n  | readerEdges | readerIds | copyScratch | fieldScratch | valid | record | equalityKey | equalityScratch\n  | frameBuffer | frameScratch | reversed | output\n  deriving DecidableEq\ninstance : Fintype Aux := Fintype.ofList [.readerEdges,.readerIds,.copyScratch,.fieldScratch,.valid,\n  .record,.equalityKey,.equalityScratch,.frameBuffer,.frameScratch,.reversed,.output]\n  (by intro k;cases k <;> simp)\n/-- Original acquisition plus actual recipe work, seven parsed fields and twelve fresh roles. -/\nabbrev Stack := S.Stack⊕(RecipeWork⊕(Fin 7⊕Aux))\n/-- Exact original source inclusion, retained across every actual endpoint emission. -/\ndef source (k:S.Stack) : Stack := .inl k\n/-- Private actual recipe work inclusion. -/\ndef work (k:RecipeWork) : Stack := .inr (.inl k)\n/-- The six original edge fields and seventh actual owner-ID field. -/\ndef cache (part:Fin 7) : Stack := .inr (.inr (.inl part))\n/-- Private physical caller work inclusion. -/\ndef aux (role:Aux) : Stack := .inr (.inr (.inr role))\n/-- Original binary N alone. -/\ndef originalInput : Stack := source S.originalInput\n/-- Actual preserved original E-wire record tape. -/\ndef edgeTape : Stack := source (S.edgeStack (SemiprimeD1StackEdgeCatalogue.aux .output))\n/-- Actual preserved acquired M-word bank, where M counts occurrences and not E wires. -/\ndef idBank : Stack := source S.ids\n/-- These are the actual retained unary r/t/digits metadata words of the N-only source. -/\ndef dimension (role:Fin 3) : Stack :=\n  source (S.edgeStack (SemiprimeD1StackEdgeCatalogue.catStack\n    (SemiprimeD1StackVertexCatalogue.roleStack\n      (if role=0 then .firstAxis else if role=1 then .secondAxis else .digits))))\n/-- Arithmetic evaluator inputs alias ONLY actual acquired metadata and actual parsed edge words. -/\ndef recipeStack : R.Stack→Stack\n  | .inl .r=>dimension 0 | .inl .t=>dimension 1 | .inl .digits=>dimension 2\n  | .inl .half=>cache 0 | .inl .tag=>cache 1 | .inl .a=>cache 2\n  | .inl .b=>cache 3 | .inl .c=>cache 4 | .inl .d=>cache 5\n  | .inr k=>work k\n/-- Three actual equality-key preserving sentinel-copy operands. -/\ndef equalityStack (k:Fin 3) : Stack :=\n  if k=0 then aux .record else if k=1 then aux .equalityKey else aux .equalityScratch\n/-- Whole original record/ID readers are made by actual preserving Copy calls. -/\ndef copyStack (ids:Bool) (k:Fin 3) : Stack :=\n  if k=0 then (if ids then idBank else edgeTape)\n  else if k=1 then (if ids then aux .readerIds else aux .readerEdges) else aux .copyScratch\n/-- Physical field parser: six edge fields, then one actual ID-vector payload. -/\ndef fieldStack (part:Fin 7) : F.Stack→Stack\n  | .inl .input=>if part=6 then aux .readerIds else aux .readerEdges\n  | .inl .scratch=>aux .fieldScratch | .inl .output=>cache part | .inr _=>aux .valid\n/-- Equality's exact six-field record is physically assembled from parsed fields, last first. -/\ndef recordStack (part:Fin 6) (k:Fin 3) : Stack :=\n  if k=0 then cache ⟨5-part.val,by omega⟩ else if k=1 then aux .record else aux .frameScratch\n/-- The actual newly computed arithmetic key or actually sentinel-copied equality key. -/\ndef keySource (host:Bool) : Stack := if host then aux .equalityKey else recipeStack (.inr (.inr .output))\n/-- Literal two-field map record: computed endpoint key, then the SAME acquired owner ID. -/\ndef pairStack (host value:Bool) (k:Fin 3) : Stack :=\n  if k=0 then (if value then cache 6 else keySource host)\n  else if k=1 then aux .frameBuffer else aux .frameScratch\n/-- Actual field or whole-map reversal; the final false vector delimiter is physically pushed. -/\ndef reverseStack (finish:Bool) (k:Fin 2) : Stack :=\n  if k=0 then (if finish then aux .reversed else aux .frameBuffer)\n  else if finish then aux .output else aux .reversed\n/-- Fixed complete inventory of recipe registers to physically clear after each wire. -/\ndef workRole (part:Fin 47) : RecipeWork :=\n  if h:part.val<10 then .inl (.mode ⟨part.val,h⟩)\n  else match part.val with\n    | 10=>.inl .rt\n    | 11=>.inl .width\n    | 12=>.inl .qa\n    | 13=>.inl .ma\n    | 14=>.inl .qb\n    | 15=>.inl .mb\n    | 16=>.inl .tc\n    | 17=>.inl .rc\n    | 18=>.inl .pbc\n    | 19=>.inl .aminus\n    | 20=>.inl .bminus\n    | 21=>.inl .dminus\n    | 22=>.inl .bplus\n    | 23=>.inl .slot10\n    | 24=>.inl .slot11\n    | 25=>.inl .slot12\n    | 26=>.inl .wd\n    | 27=>.inl .slot13f\n    | 28=>.inl .slot13t\n    | 29=>.inl .slot14t\n    | 30=>.inl .slot14f\n    | 31=>.inl .wb\n    | 32=>.inl .divInput\n    | 33=>.inl .testLeft\n    | 34=>.inl .testLimit\n    | 35=>.inl .smallA\n    | 36=>.inl .ltArt\n    | 37=>.inl .ltNext\n    | 38=>.inl .tagReader\n    | 39=>.inr .copyScratch\n    | 40=>.inr .multiplier\n    | 41=>.inr .productScratch\n    | 42=>.inr .maddScratch\n    | 43=>.inr .divCopy\n    | 44=>.inr .divScratch\n    | 45=>.inr .frameScratch\n    | 46=>.inr .output\n    | _=>.inr .output\n/-- Fixed finite payload-cache cleanup order, preserving both entire original source banks. -/\ndef clearSource (part:Fin 9) : Stack :=\n  if h:part.val<7 then cache ⟨part.val,h⟩ else if part=7 then aux .record else aux .equalityKey\n/-- All outer control positions, including actual malformed-input abort branches. -/\ninductive Control where\n  | main | copyEdges | copyIds | parse | bankTag | arithmetic | equality | emitTag (host:Bool)\n  | field (part:Fin 7) | valid (part:Fin 7) | record (part:Fin 6)\n  | emitField (host value:Bool) | emitReverse (host value:Bool)\n  | clearRecipe (part:Fin 47) | clearCache (part:Fin 9) | finalTag | finalReverse | halt | abort\n  deriving Fintype\n/-- Every source and every nested arithmetic/equality/parser call has a fixed finite label. -/\ninductive Label where\n  | local (pc:Control) | source (pc:S.Label) | recipe (pc:R.Label) | equality (pc:Q.Label)\n  | copy (ids:Bool) (pc:Fin 9) | field (part:Fin 7) (pc:F.Label)\n  | record (part:Fin 6) (pc:Fin 11) | pair (host value:Bool) (pc:Fin 11)\n  | reverse (finish:Bool) (pc:Fin 4)\n  deriving Fintype\n/-- Actual original-N source, actual E-record/M-ID zipper and both literal endpoint-key paths. -/\ndef program : Label→C.Instruction Stack Label\n  | .source pc=>SemiprimeD1StackValidationLink.instruction source Label.source (S.program pc)\n  | .recipe pc=>SemiprimeD1StackValidationLink.instruction recipeStack Label.recipe (R.program pc)\n  | .equality pc=>SemiprimeD1StackValidationLink.instruction equalityStack Label.equality (Q.program pc)\n  | .copy ids pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack ids) (Label.copy ids) (SemiprimeD1StackCopy.code pc)\n  | .field part pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack part) (Label.field part) (F.code pc)\n  | .record part pc=>SemiprimeD1StackMultiplierLink.instruction (recordStack part) (Label.record part) (SemiprimeD1StackFrame.code pc)\n  | .pair host value pc=>SemiprimeD1StackMultiplierLink.instruction (pairStack host value) (Label.pair host value) (SemiprimeD1StackFrame.code pc)\n  | .reverse finish pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack finish) (Label.reverse finish) (SemiprimeD1StackReverseWord.code pc)\n  | .local .main=>.call (.source (.inl .start)) (.local .copyEdges)\n  | .local .copyEdges=>.call (.copy false 0) (.local .copyIds)\n  | .local .copyIds=>.call (.copy true 0) (.local .parse)\n  | .local .parse=>.base (.peek (aux .readerEdges) (.local .finalTag) (.local (.field 0)) (.local (.field 0)))\n  | .local (.field part)=>.call (.field part (F.active .tagPop (none,false))) (.local (.valid part))\n  | .local (.valid part)=>\n      let next:Label:=if h:part.val<5 then .local (.field ⟨part.val+1,by omega⟩)\n        else if part=5 then .local .bankTag else .local (.record 0)\n      .base (.pop (aux .valid) (.local .abort) (.local .abort) next)\n  | .local .bankTag=>.base (.pop (aux .readerIds) (.local .abort) (.local .abort) (.local (.field 6)))\n  | .local (.record part)=>.call (.record part 0)\n      (if h:part.val<5 then .local (.record ⟨part.val+1,by omega⟩) else .local .equality)\n  | .local .equality=>.call (.equality (.inl 0)) (.local .arithmetic)\n  | .local .arithmetic=>.call (.recipe (.local .start)) (.local (.emitTag false))\n  | .local (.emitTag host)=>.base (.push (aux .reversed) true (.local (.emitField host false)))\n  | .local (.emitField host value)=>.call (.pair host value 0) (.local (.emitReverse host value))\n  | .local (.emitReverse host value)=>.call (.reverse false 0)\n      (if value then (if host then .local (.clearRecipe 0) else .local (.emitTag true))\n        else .local (.emitField host true))\n  | .local (.clearRecipe part)=>\n      let next:Label:=if h:part.val<46 then .local (.clearRecipe ⟨part.val+1,by omega⟩) else .local (.clearCache 0)\n      .base (.pop (work (workRole part)) next (.local (.clearRecipe part)) (.local (.clearRecipe part)))\n  | .local (.clearCache part)=>\n      let next:Label:=if h:part.val<8 then .local (.clearCache ⟨part.val+1,by omega⟩) else .local .parse\n      .base (.pop (clearSource part) next (.local (.clearCache part)) (.local (.clearCache part)))\n  | .local .finalTag=>.base (.push (aux .reversed) false (.local .finalReverse))\n  | .local .finalReverse=>.call (.reverse true 0) (.local .halt)\n  | .local .halt | .local .abort=>.base .halt\n/-- Original binary N is the only initially present data; every outer/recipe cache starts empty. -/\ndef input (bits:List Bool) : Stack→List Bool := Sum.elim (S.input bits) (fun _=>[])\n/-- Actual original-N entry of the fixed forward catalogue producer. -/\ndef initial (bits:List Bool) : C.State Stack Label := ⟨some (.local .main),none,none,input bits,[]⟩\n/-- One finite source for original-N forward endpoint/owner-ID acquisition. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine originalInput (aux .output) (.local .main) program\n/-- Every physical data/return alphabet is finite before every original input. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite originalInput (aux .output) (.local .main) program\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogue\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueCacheClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueClear\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueCacheClear\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeD1StackOwnerCatalogueFields SemiprimeD1StackOwnerCatalogueParse\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\n/-- Actual seven parsed payloads plus the two built keys retained for physical cleanup. -/\nabbrev Packet := Fin 9→List Bool\n/-- Literal physical store after arithmetic cleanup, retaining both actual tape suffixes. -/\ndef packet (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool) : Stack→List Bool :=\n  data s (fun _=>[]) (fun i=>p ⟨i.val,by omega⟩) (fun k=>match k with\n    | .readerEdges=>edges | .readerIds=>ids | .reversed=>collector\n    | .record=>p 7 | .equalityKey=>p 8 | _=>[])\n/-- The cleanup instruction reads the actual corresponding payload byte stack. -/\ntheorem packet_source (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool) (part:Fin 9) :\n    packet s p edges ids collector (clearSource part)=p part := by\n  fin_cases part <;> rfl\n/-- Updating a real cleanup role preserves the source banks, both readers and the collector. -/\ntheorem packet_update (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool)\n    (part:Fin 9) (word:List Bool) :\n    Function.update (packet s p edges ids collector) (clearSource part) word=\n      packet s (Function.update p part word) edges ids collector := by\n  funext k\n  rcases k with k|k\n  · have hn:(Sum.inl k:Stack)≠clearSource part:=by\n      fin_cases part <;> intro h <;> cases h\n    exact Function.update_of_ne hn _ _\n  · rcases k with k|k\n    · have hn:(work k)≠clearSource part:=by\n        fin_cases part <;> intro h <;> cases h\n      exact Function.update_of_ne hn _ _\n    · rcases k with k|k\n      · fin_cases part <;> fin_cases k <;> simp [packet,clearSource,data,cache,aux,Function.update_apply]\n      · fin_cases part <;> cases k <;> simp [packet,clearSource,data,cache,aux,Function.update_apply]\n/-- Mathematical view of the payloads after n actual drains. -/\ndef cleared (p:Packet) (n:Nat) (i:Fin 9) : List Bool := if i.val<n then [] else p i\n/-- The actual next role erasure advances the exact payload view. -/\ntheorem cleared_step (p:Packet) (part:Fin 9) :\n    Function.update (cleared p part.val) part []=cleared p (part.val+1) := by\n  funext i;fin_cases part <;> fin_cases i <;> rfl\n/-- All nine actual payloads have been physically removed at cleanup exit. -/\ntheorem cleared_end (p:Packet) : cleared p 9=fun _=>[] := by\n  funext i;exact ite_eq_left i.isLt\n/-- The static next position after one real cache drain. -/\ndef next (part:Fin 9) : Label :=\n  if h:part.val<8 then .local (.clearCache ⟨part.val+1,by omega⟩) else .local .parse\n/-- Every bit in a payload is actually popped, plus its EOF transition. -/\ntheorem cache_call (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool) (part:Fin 9) :\n    Runs program ((p part).length+1) (.local (.clearCache part))\n      (packet s (cleared p part.val) edges ids collector) (next part)\n      (packet s (cleared p (part.val+1)) edges ids collector) := by\n  let before:=packet s (cleared p part.val) edges ids collector\n  have hv:before (clearSource part)=p part:=by\n    simp only [before,packet_source,cleared,Nat.lt_irrefl,ite_false]\n  have hi:Function.update before (clearSource part) (p part)=before:=by\n    rw [←hv];exact Function.update_eq_self _ _\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (.local (.clearCache part)) (next part)\n    (clearSource part) rfl before (p part)\n  rw [hi] at h\n  simpa only [before,packet_update,cleared_step] using h\n/-- Static position in the complete nine-payload cleanup. -/\ndef cachePC (n:Nat) : Label :=\n  if h:n<9 then .local (.clearCache ⟨n,h⟩) else .local .parse\n/-- Chronological sum of actual payload pops and their EOF pops. -/\ndef cacheTime (p:Packet) : Nat→Nat\n  | 0=>0\n  | n+1=>cacheTime p n+(p ⟨n%9,Nat.mod_lt _ (by omega)⟩).length+1\n/-- One real cache drain advances the physically cleaned row view. -/\ntheorem cache_step (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool)\n    (n:Nat) (hn:n<9) :\n    Runs program ((p ⟨n,hn⟩).length+1) (cachePC n)\n      (packet s (cleared p n) edges ids collector) (cachePC (n+1))\n      (packet s (cleared p (n+1)) edges ids collector) := by\n  have h:=cache_call s p edges ids collector ⟨n,hn⟩\n  have hp:next ⟨n,hn⟩=cachePC (n+1):=by\n    unfold next cachePC\n    by_cases hn':n<8\n    · simp only [hn',show n+1<9 by omega,dite_eq_left]\n    · have he:n=8:=by omega\n      subst n;rfl\n  rw [hp] at h\n  simpa only [cachePC,dite_eq_left hn] using h\n/-- Exact trace of the first n real payload-drain loops. -/\ntheorem cache_prefix (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool)\n    (n:Nat) (hn:n≤9) :\n    Runs program (cacheTime p n) (cachePC 0) (packet s (cleared p 0) edges ids collector)\n      (cachePC n) (packet s (cleared p n) edges ids collector) := by\n  induction n with\n  | zero=>exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | succ n ih=>\n    have hlt:n<9:=by omega\n    have hm:n%9=n:=Nat.mod_eq_of_lt hlt\n    have h:=runs_trans program _ _ _ _ _ _ _ _ (ih (by omega)) (cache_step s p edges ids collector n hlt)\n    simpa only [cacheTime,hm,Nat.add_assoc] using h\n/-- Every row cache is erased by the actual source; readers and collector survive for the next edge. -/\ntheorem cache_run (s:S.Stack→List Bool) (p:Packet) (edges ids collector:List Bool) :\n    Runs program (cacheTime p 9) (.local (.clearCache 0)) (packet s p edges ids collector)\n      (.local .parse) (data s (fun _=>[]) (fun _=>[]) (rowAux edges ids collector)) := by\n  have h:=cache_prefix s p edges ids collector 9 (by omega)\n  have hz:cleared p 0=p:=by funext k;exact ite_eq_right (Nat.not_lt_zero _)\n  have hp0:cachePC 0=.local (.clearCache 0):=by simp [cachePC]\n  have hp9:cachePC 9=.local .parse:=by simp [cachePC]\n  have he:packet s (fun _=>[]) edges ids collector=\n      data s (fun _=>[]) (fun _=>[]) (rowAux edges ids collector):=by\n    funext k;rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n  simpa only [hz,hp0,hp9,cleared_end,he] using h\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueCacheClear\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueRecord":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueParse\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueRecord\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeD1StackOwnerCatalogueFields SemiprimeD1StackOwnerCatalogueParse\nopen SemiprimeD1StackProcedureTrace (Runs included_call runs_trans)\nopen SemiprimeD1StackPortOwnerRecipeCalls (update_rel)\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Rel\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend Rel\n/-- Every one of the six actual record framers uses three distinct physical roles. -/\ntheorem record_injective (part:Fin 6) : Function.Injective (recordStack part) := by\n  fin_cases part <;> decide\n/-- Actual next record-framing position. -/\ndef recordNext (part:Fin 6) : Label :=\n  if h:part.val<5 then .local (.record ⟨part.val+1,by omega⟩) else .local .equality\n/-- One original field is physically framed onto the actual equality-record suffix. -/\ntheorem record_call (part:Fin 6) (store:Stack→List Bool)\n    (hs:store (aux .frameScratch)=[]) :\n    Runs program (6*(store (cache ⟨5-part.val,by omega⟩)).length+5)\n      (.local (.record part)) store (recordNext part)\n      (Function.update store (aux .record)\n        (frame (store (cache ⟨5-part.val,by omega⟩)) (store (aux .record)))) := by\n  let word:=store (cache ⟨5-part.val,by omega⟩)\n  let tail:=store (aux .record)\n  let before:=SemiprimeD1StackFrame.state 0 none word tail []\n  let after:=SemiprimeD1StackFrame.done word (frame word tail)\n  have hi:Rel.DataRel (recordStack part) store before.store store:=by\n    constructor\n    · intro k;fin_cases k <;> simp [before,SemiprimeD1StackFrame.state,SemiprimeD1StackFrame.payload,\n        recordStack,word,tail,hs]\n    · intro k _;rfl\n  apply included_call program (recordStack part) (Label.record part) (record_injective part)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) (.local (.record part)) (recordNext part) rfl _ before after\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackFrame.frame_words word tail none\n  · exact hi\n  · have he:Function.update before.store (1:Fin 3) (frame word tail)=after.store:=by\n      funext k;fin_cases k <;> rfl\n    simpa only [he,recordStack,show ¬(1:Fin 3)=0 by decide,ite_false,ite_true] using\n      update_rel (recordStack part) (record_injective part) store before.store store hi 1 (frame word tail)\n/-- The actual built equality-record suffix after n real framing calls. -/\ndef recordTail (p:Fin 7→List Bool) (n:Nat) : List Bool := edgeRest p (6-n) []\n/-- Framing from the last parsed coordinate to the first produces the original record order. -/\ntheorem recordTail_step (p:Fin 7→List Bool) (n:Nat) (hn:n<6) :\n    frame (p ⟨5-n,by omega⟩) (recordTail p n)=recordTail p (n+1) := by\n  have h:=edgeRest_step p (5-n) (by omega) []\n  have ha:5-n+1=6-n:=by omega\n  have hb:6-(n+1)=5-n:=by omega\n  simpa only [recordTail,ha,hb] using h.symm\n/-- The physical record is empty before its first frame. -/\ntheorem recordTail_zero (p:Fin 7→List Bool) : recordTail p 0=[]:=edgeRest_end p []\n/-- Six physical frames reconstruct precisely the acquired original six-field record. -/\ntheorem recordTail_six (p:Fin 7→List Bool) : recordTail p 6=edgeRest p 0 []:=rfl\n/-- Actual outer store after n equality-record frames. -/\ndef recordStore (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (p:Fin 7→List Bool)\n    (n:Nat) (edges ids collector:List Bool) : Stack→List Bool :=\n  data s w p (Function.update (rowAux edges ids collector) .record (recordTail p n))\n/-- Static current record call, followed by equality-key acquisition after call six. -/\ndef recordPC (n:Nat) : Label :=\n  if h:n<6 then .local (.record ⟨n,h⟩) else .local .equality\n/-- Actual cost of n physical record-frame calls, in their physical last-first order. -/\ndef recordTime (p:Fin 7→List Bool) : Nat→Nat\n  | 0=>0\n  | n+1=>recordTime p n+(6*(p ⟨(5-n)%7,Nat.mod_lt _ (by omega)⟩).length+5)\n/-- Each real call prepends the next physically parsed field and clears its real scratch. -/\ntheorem record_step (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (p:Fin 7→List Bool)\n    (n:Nat) (hn:n<6) (edges ids collector:List Bool) :\n    Runs program (6*(p ⟨5-n,by omega⟩).length+5) (recordPC n)\n      (recordStore s w p n edges ids collector) (recordPC (n+1))\n      (recordStore s w p (n+1) edges ids collector) := by\n  let part:Fin 6:=⟨n,hn⟩\n  have hs:recordStore s w p n edges ids collector (aux .frameScratch)=[]:=by\n    simp only [recordStore,data_aux,Function.update_of_ne (by decide : Aux.frameScratch≠.record),rowAux]\n  have hr:=record_call part (recordStore s w p n edges ids collector) hs\n  have hout:Function.update (recordStore s w p n edges ids collector) (aux .record)\n      (frame ((recordStore s w p n edges ids collector) (cache ⟨5-part.val,by omega⟩))\n        ((recordStore s w p n edges ids collector) (aux .record)))=\n      recordStore s w p (n+1) edges ids collector:=by\n    simp only [recordStore,data_cache,data_aux,Function.update_same,update_aux,Function.update_idem]\n    rw [recordTail_step p n hn]\n  have hp:recordNext part=recordPC (n+1):=by\n    unfold recordNext recordPC\n    by_cases h:n<5\n    · simp only [part,h,dite_eq_left,show n+1<6 by omega]\n    · have he:n=5:=by omega\n      subst n;rfl\n  rw [hout,hp] at hr\n  simpa only [recordPC,dite_eq_left hn,recordStore,data_cache,part] using hr\n/-- The six literal calls rebuild the exact equality endpoint record from acquired words. -/\ntheorem record_prefix (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (p:Fin 7→List Bool)\n    (n:Nat) (hn:n≤6) (edges ids collector:List Bool) :\n    Runs program (recordTime p n) (recordPC 0) (recordStore s w p 0 edges ids collector)\n      (recordPC n) (recordStore s w p n edges ids collector) := by\n  induction n with\n  | zero=>exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | succ n ih=>\n    have hlt:n<6:=by omega\n    have hm:(5-n)%7=5-n:=Nat.mod_eq_of_lt (by omega)\n    have ht:=runs_trans program _ _ _ _ _ _ _ _ (ih (by omega))\n      (record_step s w p n hlt edges ids collector)\n    simpa only [recordTime,hm] using ht\n/-- The exact acquired record is rebuilt by six actual calls, ready for sentinel-copy. -/\ntheorem record_run (s:S.Stack→List Bool) (w:RecipeWork→List Bool) (p:Fin 7→List Bool)\n    (edges ids collector:List Bool) :\n    Runs program (recordTime p 6) (.local (.record 0)) (data s w p (rowAux edges ids collector))\n      (.local .equality) (data s w p (Function.update (rowAux edges ids collector)\n        .record (edgeRest p 0 []))) := by\n  have h:=record_prefix s w p 6 (by omega) edges ids collector\n  have hzero:recordStore s w p 0 edges ids collector=data s w p (rowAux edges ids collector):=by\n    simp only [recordStore,recordTail_zero]\n    rw [show ([]:List Bool)=rowAux edges ids collector .record by rfl,Function.update_eq_self]\n  rw [hzero] at h\n  have hp0:recordPC 0=.local (.record 0):=by simp [recordPC]\n  have hp6:recordPC 6=.local .equality:=by simp [recordPC]\n  rw [hp0,hp6] at h\n  simpa only [recordStore,recordTail_six] using h\n\n/-- Actual six-call frame time is linear in a bound on the acquired payload lengths. -/\ntheorem recordTime_bound (p:Fin 7→List Bool) (cap n:Nat) (hp:∀i,(p i).length≤cap) :\n    recordTime p n≤n*(6*cap+5) := by\n  induction n with\n  | zero=>simp only [recordTime,Nat.zero_mul,Nat.le_refl]\n  | succ n ih=>\n    have h:=hp ⟨(5-n)%7,Nat.mod_lt _ (by omega)⟩\n    simp only [recordTime]\n    nlinarith\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueRecord\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueBounds\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueResources\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueBounds\nopen SemiprimeBitArithmetic (bitValue)\n/-- All 149 physical Boolean roles, including retained source/ID banks and actual work. -/\ntheorem stack_card : Fintype.card Stack=149 := by decide\n/-- Initial data consists only of original binary N, before any tape/dimension/ID acquisition. -/\ntheorem initial_length (bits:List Bool) (k:Stack) : (input bits k).length≤bits.length := by\n  rcases k with k|k\n  · exact SemiprimeD1StackOwnerCatalogueOriginalBounds.source_input_length bits k\n  · exact Nat.zero_le _\n/-- Actual successful source prefixes cannot pass this SAME N-only source's proved halt. -/\ntheorem prefix_fuel (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:C.run program fuel (initial bits)=some out) :\n    fuel≤polynomial bits.length := by\n  obtain ⟨time,ht,he⟩:=source_run_polynomial bits hc hN\n  have hf:fuel≤time:=by\n    by_contra hn\n    have hh:fuel=time+(1+(fuel-(time+1))):=by omega\n    rw [hh,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run program 1 (SemiprimeD1StackOwnerCatalogueExecution.done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- EVERY actual source prefix counts all 149 Boolean words and all real return frames. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:C.run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤150*(bits.length+polynomial bits.length) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ _ (initial_length bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤149*(bits.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(bits.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel bits hc hN fuel out hr\n  omega\n/-- The actual source's initial tape equals the ordinary single-input finite-machine convention. -/\ntheorem input_single (bits:List Bool) : input bits=fun k=>if k=originalInput then bits else [] := by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · change SemiprimeD1StackVertexCatalogue.input bits k=_\n        rw [SemiprimeD1StackEdgeCatalogueExecution.cat_input]\n        simp only [originalInput,source,S.originalInput,S.edgeStack,SemiprimeD1StackEdgeCatalogue.catStack,\n          Sum.inl.injEq]\n      · rfl\n    · rcases k with k|k <;> rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k <;> rfl\n/-- The genuine compiled machine starts from binary N alone. -/\ntheorem initial_eq (bits:List Bool) :\n    Turing.initList machine bits=SemiprimeD1StackCalls.configuration (initial bits) := by\n  have he:initial bits=SemiprimeD1StackCalls.initial originalInput (.local .main) bits:=by\n    unfold initial SemiprimeD1StackCalls.initial\n    rw [input_single]\n  rw [he]\n  exact (SemiprimeD1StackCalls.initial_correct originalInput (aux .output) (.local .main) program bits).symm\n/-- SAME actual polynomial source clock as a genuine finite-machine execution certificate. -/\nnoncomputable def catalogueInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (SemiprimeD1StackOwnerCatalogueExecution.done bits)))\n      (polynomial bits.length) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput (aux .output) (.local .main) program\n  let cert:=source_run_polynomial bits hc hN\n  exact ⟨⟨Classical.choose cert,(Classical.choose_spec cert).2⟩,(Classical.choose_spec cert).1⟩\n/-- EVERY genuine compiled-machine prefix retains the SAME all-role and return-cell bound. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤150*(bits.length+polynomial bits.length) := by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput (aux .output) (.local .main) program fuel (initial bits)\n  change (C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial bits))) at he\n  have hh:(C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=some cfg:=\n    he.trans ((congrArg (fun start:machine.Cfg=>\n      (fun q:Option machine.Cfg=>q.bind machine.step)^[fuel] (some start)) (initial_eq bits).symm).trans hr)\n  cases hout:C.run program fuel (initial bits) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hout\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueResources\n","RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueView\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueClear\nopen SemiprimeD1StackOwnerFibreCatalogue SemiprimeD1StackOwnerFibreCatalogueSource\nopen SemiprimeD1StackOwnerFibreCatalogueView\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\n/-- Fixed inverse to the actual fourteen-role filter cleanup order. -/\ndef rank :V.Stack→Fin 14\n  | .inl .left=>0 | .inl .right=>1 | .inl .scratch=>2 | .inl .output=>3\n  | .inr .query=>4 | .inr .reader=>5 | .inr .fieldScratch=>6 | .inr .valid=>7\n  | .inr .copyScratch=>8 | .inr .payload=>9 | .inr .output=>10\n  | .inr .frameBuffer=>11 | .inr .frameScratch=>12 | .inr .reversed=>13\n/-- Every real filter role is visited exactly once by actual source cleanup. -/\ntheorem role_rank (k:V.Stack) :fibreRole (rank k)=k:=by rcases k with k|k <;> cases k <;> decide\n/-- The proof-side rank agrees with every actual static drain call. -/\ntheorem rank_role (i:Fin 14) :rank (fibreRole i)=i:=by fin_cases i <;> decide\n/-- Actual filter store after n physically drained payload roles. -/\ndef cleared (f:V.Stack→List Bool) (n:Nat) (k:V.Stack) :List Bool:=if (rank k).val<n then [] else f k\n/-- An actual payload drain advances exactly the ordered cleanup view. -/\ntheorem cleared_step (f:V.Stack→List Bool) (i:Fin 14) :\n    Function.update (cleared f i.val) (fibreRole i) []=cleared f (i.val+1):=by\n  funext k;by_cases hk:k=fibreRole i\n  · subst k;simp only [Function.update_same,cleared,rank_role,Nat.lt_succ_self,ite_true]\n  · have hn:(rank k).val≠i.val:=by\n      intro h;have he:rank k=i:=Fin.ext h\n      have hr:=role_rank k;rw [he] at hr\n      exact hk hr.symm\n    simp only [Function.update_of_ne hk,cleared]\n    split <;> split <;> simp_all <;> omega\n/-- All filter payloads have been physically erased at cleanup exit. -/\ntheorem cleared_end (f:V.Stack→List Bool) :cleared f 14=fun _=>[]:=by funext k;exact ite_eq_left (rank k).isLt\n/-- Actual next drain label, or the original E-loop after role fourteen. -/\ndef next (i:Fin 14) :Label:=\n  if h:i.val<13 then .local (.clearFibre ⟨i.val+1,by omega⟩) else .local .loop\n/-- Every real filter word is popped cell by cell, including its actual EOF transition. -/\ntheorem role_clear (s:R.Stack→List Bool) (f:V.Stack→List Bool) (a:Aux→List Bool) (i:Fin 14) :\n    Runs program ((f (fibreRole i)).length+1) (.local (.clearFibre i))\n      (data s (cleared f i.val) a) (next i) (data s (cleared f (i.val+1)) a):=by\n  let before:=data s (cleared f i.val) a\n  have hv:before (fibreStack (fibreRole i))=f (fibreRole i):=by\n    simp only [before,data_fibre,cleared,rank_role,Nat.lt_irrefl,ite_false]\n  have hi:Function.update before (fibreStack (fibreRole i)) (f (fibreRole i))=before:=by\n    rw [←hv];exact Function.update_eq_self _ _\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (.local (.clearFibre i)) (next i)\n    (fibreStack (fibreRole i)) rfl before (f (fibreRole i))\n  rw [hi] at h\n  simpa only [before,update_fibre,cleared_step] using h\n/-- Static real source position within the complete filter cleanup. -/\ndef pc (n:Nat) :Label:=if h:n<14 then .local (.clearFibre ⟨n,h⟩) else .local .loop\n/-- Chronological sum of all actual discarded payload lengths and EOF pops. -/\ndef time (f:V.Stack→List Bool) :Nat→Nat\n  | 0=>0\n  | n+1=>time f n+(f (fibreRole ⟨n%14,Nat.mod_lt _ (by omega)⟩)).length+1\n/-- One actual static drain advances the exact physical role inventory. -/\ntheorem step (s:R.Stack→List Bool) (f:V.Stack→List Bool) (a:Aux→List Bool) (n:Nat) (hn:n<14) :\n    Runs program ((f (fibreRole ⟨n,hn⟩)).length+1) (pc n) (data s (cleared f n) a)\n      (pc (n+1)) (data s (cleared f (n+1)) a):=by\n  have h:=role_clear s f a ⟨n,hn⟩\n  have hp:next ⟨n,hn⟩=pc (n+1):=by\n    unfold next pc\n    by_cases h:n<13\n    · simp only [h,show n+1<14 by omega,dite_eq_left]\n    · have he:n=13:=by omega\n      subst n;rfl\n  rw [hp] at h\n  simpa only [pc,dite_eq_left hn] using h\n/-- Exact source trace through the first n physically erased filter roles. -/\ntheorem clear_prefix (s:R.Stack→List Bool) (f:V.Stack→List Bool) (a:Aux→List Bool) (n:Nat) (hn:n≤14) :\n    Runs program (time f n) (pc 0) (data s (cleared f 0) a) (pc n) (data s (cleared f n) a):=by\n  induction n with\n  | zero=>exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | succ n ih=>\n    have hlt:n<14:=by omega\n    have hm:n%14=n:=Nat.mod_eq_of_lt hlt\n    have h:=runs_trans program _ _ _ _ _ _ _ _ (ih (by omega)) (step s f a n hlt)\n    simpa only [time,hm,Nat.add_assoc] using h\n/-- COMPLETE physical cleanup leaves the next owner iteration with fresh filter work, preserving E/IDs/history. -/\ntheorem clear_run (s:R.Stack→List Bool) (f:V.Stack→List Bool) (a:Aux→List Bool) :\n    Runs program (time f 14) (.local (.clearFibre 0)) (data s f a) (.local .loop) (data s (fun _=>[]) a):=by\n  have h:=clear_prefix s f a 14 (by omega)\n  have hz:cleared f 0=f:=by funext k;exact ite_eq_right (Nat.not_lt_zero _)\n  have hp0:pc 0=.local (.clearFibre 0):=by simp [pc]\n  have hp14:pc 14=.local .loop:=by simp [pc]\n  simpa only [hz,hp0,hp14,cleared_end] using h\nend RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueClear\n","RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueRow\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueLoop\nopen SemiprimeD1StackOwnerFibreCatalogue SemiprimeD1StackOwnerFibreCatalogueSource\nopen SemiprimeD1StackOwnerFibreCatalogueView\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Exact acquired owner-bank prefix followed by the ACTUAL untouched M-E suffix. -/\ndef idTape (queries:List (List Bool)) (tail:List Bool) :List Bool:=\n  queries.foldr (fun q rest=>true::frame q rest) tail\n/-- Physically emitted owner/fibre row bytes in original wire ordinal order. -/\ndef bytes (queries:List (List Bool)) (rows:List (List Bool×List Bool)) :List Bool:=\n  queries.flatMap (fun q=>SemiprimeD1StackOwnerFibreCatalogueRow.row q rows)\n/-- Sum of the SAME actual E-loop iteration clocks. -/\ndef budget (queries:List (List Bool)) (rows:List (List Bool×List Bool)) :Nat:=\n  (queries.map (fun q=>SemiprimeD1StackOwnerFibreCatalogueRow.budget q rows)).sum\n/-- COMPLETE real owner iterator. It uses the actual unary E counter and leaves the acquired\nM-E bank suffix present; every owner query invokes the actual routed-tape filter and all14 drains. -/\ntheorem loop_run (s:R.Stack→List Bool) (rows:List (List Bool×List Bool))\n    (hm:s (SemiprimeD1StackPortOwnerRouting.aux .output)=SemiprimeD1StackOwnerFibre.records rows [])\n    (queries:List (List Bool)) (tail raw:List Bool) :\n    ∃time≤budget queries rows,Runs program time (.local .loop)\n      (data s (fun _=>[]) (rowAux (List.replicate queries.length true) (idTape queries tail) raw))\n      (.local .loop) (data s (fun _=>[]) (rowAux [] tail ((bytes queries rows).reverse++raw))) := by\n  induction queries generalizing raw with\n  | nil=>refine ⟨0,by simp [budget],SemiprimeD1StackProcedureTrace.runs_refl program _ _⟩\n  | cons q qs ih=>\n    obtain ⟨a,ha,har⟩:=SemiprimeD1StackOwnerFibreCatalogueRow.row_run s rows hm q\n      (List.replicate qs.length true) (idTape qs tail) raw\n    obtain ⟨b,hb,hbr⟩:=ih ((SemiprimeD1StackOwnerFibreCatalogueRow.row q rows).reverse++raw)\n    have h:=runs_trans program _ _ _ _ _ _ _ _ har hbr\n    refine ⟨a+b,?_,?_⟩\n    · simp only [budget,List.map_cons,List.sum_cons] at *;omega\n    · simpa only [List.length_cons,List.replicate_succ,idTape,List.foldr_cons,bytes,List.flatMap_cons,\n        List.reverse_append,List.append_assoc] using h\n/-- Literal record frame appends its actual catalogue suffix. -/\ntheorem row_append (owner scopes tail:List Bool) :\n    SemiprimeD1StackOwnerFibreCatalogueEmit.row owner scopes++tail=\n      true::frame owner (frame scopes tail):=\n  SemiprimeD1StackOwnerCatalogueOriginalMap.row_append owner scopes tail\n/-- The actual owner/fibre output uses the old two-field record parser grammar. -/\ntheorem bytes_records (queries:List (List Bool)) (rows:List (List Bool×List Bool)) (tail:List Bool) :\n    bytes queries rows++false::tail=SemiprimeD1StackOwnerLookup.records\n      (queries.map (fun q=>(q,SemiprimeD1StackOwnerFibreCatalogueRow.scopes q rows))) tail:=by\n  induction queries with\n  | nil=>rfl\n  | cons q qs ih=>\n    change (SemiprimeD1StackOwnerFibreCatalogueRow.row q rows++bytes qs rows)++false::tail=_\n    rw [List.append_assoc,ih]\n    unfold SemiprimeD1StackOwnerFibreCatalogueRow.row\n    rw [row_append]\n    rfl\nend RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueLoop\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsLog":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsEmit\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsLog\nopen SemiprimeD1StackOwnerRecords SemiprimeD1StackOwnerRecordsView\nopen SemiprimeD1StackProcedureTrace (Runs)\n/-- Real logger operand alias map is injective, including the34-role wrapper. -/\ntheorem log_injective : Function.Injective logStack :=\n  record_injective.comp SemiprimeD1StackOwnerRecord.recordStack_injective\n/-- Actual logger bytecode call on the complete physical source store. -/\ntheorem log_call (s:S.Stack→List Bool) (a:Aux→List Bool) (entry:L.Label) (pc next:Label)\n    (hc:program pc=.call (.log entry) next) (time:Nat) (hist out hist' out':List Bool)\n    (hr:SemiprimeD1StackBytecode.run L.code time ⟨some entry,none,L.data [] [] hist out⟩=\n      some ⟨none,none,L.data [] [] hist' out'⟩) :\n    Runs program (time+1) pc (data s (payload [] [] [] hist out) a)\n      next (data s (payload [] [] [] hist' out') a):=by\n  apply SemiprimeD1StackVertexRecordStreamExecution.call program logStack Label.log log_injective\n    entry (fun _=>rfl) pc next hc time (L.data [] [] hist out) (L.data [] [] hist' out')\n  · exact hr\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · fin_cases k <;> first | rfl | (exfalso;revert hk;decide)\n        · rfl\n/-- The ONE final list sentinel is physically pushed onto OUTPUT, never history. -/\ntheorem initialize_call (s:S.Stack→List Bool) (a:Aux→List Bool) :\n    Runs program 3 (.local .initialize) (data s (payload [] [] [] [] []) a)\n      (.local .loop) (data s (payload [] [] [] [] [false]) a):=by\n  exact log_call s a .initialize (.local .initialize) (.local .loop) rfl 2 [] [] [] [false]\n    (SemiprimeD1StackVertexRecordStream.initialize_run [] [] [] [] none)\n/-- A real single final reversal emits the catalogue's original forward row order. -/\ntheorem reverse_call (s:S.Stack→List Bool) (a:Aux→List Bool) (hist out:List Bool) :\n    Runs program (2*hist.length+3) (.local .reverse) (data s (payload [] [] [] hist out) a)\n      (.local .halt) (data s (payload [] [] [] [] (hist.reverse++out)) a):=by\n  exact log_call s a .reverse (.local .reverse) (.local .halt) rfl (2*hist.length+2)\n    hist out [] (hist.reverse++out) (SemiprimeD1StackVertexRecordStream.reverse_run hist [] [] out none)\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsLog\n","RiemannGaussian.SemiprimeD1StackPackedMomentReadoutStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedMomentReadoutCost\n/-! # Every actual readout prefix pays all22 words and genuine saved returns\nThe scalar is an actual second physical input, separately charged by its byte\nlength. These are prepared-machine certificates; N-only scalar acquisition is\nstill a separate caller obligation.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedMomentReadoutStorage\nopen scoped BigOperators\nopen SemiprimeD1StackPackedMomentReadout SemiprimeD1StackPackedMomentReadoutEncoding\nopen SemiprimeD1StackPackedMomentReadoutExecution SemiprimeD1StackPackedMomentReadoutCost\nopen SemiprimeD1StackCalls (run configuration)\n/-- Actual two-word input bytes bound every initially allocated word. -/\ntheorem initial_length (bits scalar : List Bool) (k : Stack) :\n    ((initial bits scalar).data k).length ≤ 3*(bits.length+scalar.length+1) := by\n  rcases k with k|k|k\n  · have h:=SemiprimeD1StackPackedRootMetadataStorage.initial_length bits k\n    change (M.input bits k).length ≤ _\n    exact h.trans (by omega)\n  · exact Nat.zero_le _\n  · cases k with\n    | scalar => change scalar.length ≤ _;omega\n    | count | sum => exact Nat.zero_le _\n/-- Each actually acquired metadata word has a semantic linear physical-byte\nbound; no polynomial of a previous runtime is raised in this cache invariant. -/\ntheorem metadata_length (bits : List Bool) (k : M.Stack) : (metadataResult bits k).length ≤ 3*(bits.length+1) := by\n  rcases k with k|k|k\n  · cases k with\n    | input =>\n      change bits.length ≤ 3*(bits.length+1)\n      omega\n    | reverse => exact Nat.zero_le _\n    | width =>\n      change (List.replicate bits.length true).length ≤ 3*(bits.length+1)\n      simp only [List.length_replicate]\n      omega\n    | nonzero =>\n      change 1 ≤ 3*(bits.length+1)\n      omega\n  · exact Nat.zero_le _\n  · cases k with\n    | reader | copyScratch => exact Nat.zero_le _\n    | precision => exact (SemiprimeD1StackPackedRootMetadataEncoding.precision_length bits.length).trans (by omega)\n    | base =>\n      change (SemiprimeD1StackPackedRootMetadataEncoding.baseWord bits.length).length ≤ 3*(bits.length+1)\n      rw [SemiprimeD1StackPackedRootMetadataEncoding.base_length]\n      omega\n    | template =>\n      change (List.replicate (2*bits.length) false).length ≤ 3*(bits.length+1)\n      simp only [List.length_replicate]\n      omega\n/-- SAME actually acquired metadata cache has a semantic byte bound, with scalar charged separately. -/\ntheorem ready_length (bits scalar : List Bool) (k : Stack) :\n    ((ready bits scalar).data k).length ≤ 3*(bits.length+scalar.length+1) := by\n  rcases k with k|k|k\n  · exact (metadata_length bits k).trans (by omega)\n  · exact Nat.zero_le _\n  · cases k with\n    | scalar => change scalar.length ≤ _;omega\n    | count | sum => exact Nat.zero_le _\n/-- Every one of22 actual allocations is included in total data storage. -/\ntheorem word_sum (d : Stack→List Bool) (cap : ℕ) (h : ∀k,(d k).length ≤ cap) :\n    (∑k : Stack,(d k).length) ≤ 22*cap := by\n  calc\n    _ ≤ ∑_k : Stack,cap := Finset.sum_le_sum (fun k _ => h k)\n    _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n/-- SAME actual program halt bounds every prefix and its actual saved-return cells. -/\ntheorem prefix_cost (before out final : C.State Stack Label) (fuel cap clock : ℕ)\n    (hw : ∀k,(before.data k).length ≤ cap) (hf : before.frames=[])\n    (hs : ∃t ≤ clock,run program t before=some final) (hh : run program 1 final=none)\n    (hr : run program fuel before=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤ 22*(cap+clock)+clock := by\n  obtain ⟨t,ht,hstop⟩:=hs\n  have hft : fuel ≤ t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel cap before out hw hr\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel before out hr\n  rw [hf,List.length_nil] at hframes\n  have hsum:=word_sum out.data (cap+fuel) hd\n  omega\n/-- Whole prepared input has fixed quadratic all22-data and real-return prefix storage. -/\ntheorem prefix_cells (bits scalar : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : run program fuel (initial bits scalar)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤ 100000000*(bits.length+scalar.length+1)^2 := by\n  have h:=prefix_cost (initial bits scalar) out (done bits scalar) fuel\n    (3*(bits.length+scalar.length+1)) (polynomial bits scalar)\n    (initial_length bits scalar) rfl (source_run_bounded bits scalar) rfl hr\n  have h2 : bits.length+scalar.length+1 ≤ (bits.length+scalar.length+1)^2 := Nat.le_pow (by decide : 0<(2:ℕ))\n  unfold polynomial at h\n  omega\n/-- SAME actual metadata-ready continuation has linear all22-word and real-return prefix storage. -/\ntheorem ready_prefix_cells (bits scalar : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : run program fuel (ready bits scalar)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤ 10000*(bits.length+scalar.length+1) := by\n  have h:=prefix_cost (ready bits scalar) out (done bits scalar) fuel\n    (3*(bits.length+scalar.length+1)) (readyPolynomial bits scalar)\n    (ready_length bits scalar) rfl (ready_run_bounded bits scalar) rfl hr\n  unfold readyPolynomial at h\n  omega\n/-- Exact compiler projection retains all actual data and return words. -/\ntheorem machine_cells_at (before : C.State Stack Label) (fuel bound : ℕ) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel] (some (configuration before))=some cfg)\n    (hc : ∀out,run program fuel before=some out→\n      (∑k : Stack,(out.data k).length)+out.frames.length ≤ bound) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ bound := by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput (aux .sum) (ctl .start) program fuel before\n  have hh:=he.trans hp\n  cases hout : run program fuel before with\n  | none => rw [hout] at hh;cases hh\n  | some out =>\n    rw [hout] at hh\n    have hcfg : configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact hc out hout\n/-- Genuine compiled prepared-machine prefixes count all22 words and actual saved returns. -/\ntheorem machine_prefix_cells (bits scalar : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel] (some (configuration (initial bits scalar)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 100000000*(bits.length+scalar.length+1)^2 :=\n  machine_cells_at (initial bits scalar) fuel _ cfg hp (fun out hr => prefix_cells bits scalar fuel out hr)\n/-- SAME compiled ready continuation has the actual linear cache-space bound. -/\ntheorem machine_ready_prefix_cells (bits scalar : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel] (some (configuration (ready bits scalar)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 10000*(bits.length+scalar.length+1) :=\n  machine_cells_at (ready bits scalar) fuel _ cfg hp (fun out hr => ready_prefix_cells bits scalar fuel out hr)\nend RiemannGaussian.SemiprimeD1StackPackedMomentReadoutStorage\n","RiemannGaussian.SemiprimeD1StackPacketInventoryEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketInventory\nimport RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyMeaning\nimport RiemannGaussian.SemiprimeD1PacketInventory\n/-! # Exact physical sparse-inventory overrides and placement-output ABI\nAll lists, maps and original row/index interpretations are semantic proof data.\nThe fixed source receives only its selected-key vector and acquired catalogue.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryEncoding\nopen SemiprimeD1StackPacketInventory\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Dict\nexport SemiprimeD1StackSourceKeyFrequencyEncoding (Rows dictionary read encoded)\nexport SemiprimeD1StackSourceKeyFrequencyMeaning (read_cons)\nend Dict\nnamespace Counter\nexport SemiprimeD1StackSourceEnvironmentEncoding (successor successor_value successor_compact)\nend Counter\nnamespace Native\nexport SemiprimeD1PacketInventory (Placement)\nend Native\n/-- Literal physical six-field placement payload, in original source/padding/packet/slot/edge/valid order. -/\ndef placementBytes (p:Native.Placement):List Bool:=\n  frame p.source (frame p.padding (frame p.packet (frame p.slot (frame p.edge (frame [p.valid] [])))))\n/-- Mathematical interpretation of the actual physically acquired sparse cache, retaining every obsolete map override. -/\nstructure Summary where\n  /-- Actual newest-first raw-key/count rows; stored comparison keys are sentinel-encoded only by dictionary. -/\n  classes:Dict.Rows\n  /-- Actual newest-first raw-packet/true marker rows. -/\n  seen:Dict.Rows\n  /-- Actual newest-first raw-packet-slot/positive-edge rows. -/\n  slots:Dict.Rows\n  /-- Actual newest-first first-discovery packet list. -/\n  packets:List (List Bool)\n  /-- Actual compact last-positive-occurrence word. -/\n  edge:List Bool\n  /-- Actual placements in original chronological occurrence order. -/\n  placements:List Native.Placement\n/-- Exactly the four physically seeded false terminators and zero edge before reading any occurrence. -/\ndef empty:Summary:=⟨[],[],[],[],[],[]⟩\n/-- Proof-side original row/orientation interpretation, naming bytes obtained by the actual Reader19 and Orientation19 calls. -/\ndef step (a:Nat) (s:Summary) (key:List Bool):Summary:=\n  let old:=Dict.read s.classes key\n  let rows:=SemiprimeD1PacketRows.read (SemiprimeSourceHistogramRows.acquire 64 a) a key\n  let out:=SemiprimeD1OrientationBits.acquire rows.left rows.right old\n  let next:=Counter.successor s.edge\n  let placement:Native.Placement:=⟨key,old,out.key,out.slots,next,rows.valid && out.valid⟩\n  ⟨(key,Counter.successor old)::s.classes,(out.key,[true])::s.seen,\n    (frame out.key out.slots,next)::s.slots,\n    if (Dict.read s.seen out.key).isEmpty then out.key::s.packets else s.packets,\n    next,s.placements++[placement]⟩\n/-- Actual forward source-vector order, including all repeated and parallel keys. -/\ndef acquire (a:Nat) (keys:List (List Bool)):Summary:=keys.foldl (step a) empty\n/-- Exactly the stopped physical catalogue of the actual frozen alphabet producer. -/\ndef alphabet (a:Nat):List Bool:=SemiprimeD1StackPacketRowsOriginal.catalogue a\n/-- Complete final59-word physical bank, retaining all maps/history records and no hidden work roles. -/\ndef result (keys alphabet:List Bool) (s:Summary):Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update\n    (input keys alphabet) classes (Dict.dictionary s.classes)) seen (Dict.dictionary s.seen)) slots (Dict.dictionary s.slots))\n    packets (vectorBits s.packets)) output (vectorBits (s.placements.map placementBytes))) edge s.edge) success [true]\n/-- Whole actual successful halt, with both transient flags and all real nested return frames clear. -/\ndef done (keys alphabet:List Bool) (s:Summary):C.State Stack Label:=⟨none,none,none,result keys alphabet s,[]⟩\n/-- Runtime source carries actual encoded keys and catalogue only. Width and key list here are proof indices. -/\ndef source (a:Nat) (keys:List (List Bool)):C.State Stack Label:=initial (vectorBits keys) (alphabet a)\n/-- Every placement retains precisely its actual original key and its input order. -/\ntheorem acquire_sources (a:Nat) (keys:List (List Bool)):\n    ((acquire a keys).placements.map (fun p=>p.source))=keys :=by\n  have h:∀(keys:List (List Bool)) (s:Summary),((keys.foldl (step a) s).placements.map (fun p=>p.source))=\n      s.placements.map (fun p=>p.source)++keys:=by\n    intro keys\n    induction keys with\n    | nil=>intro s;simp only [List.foldl_nil,List.append_nil]\n    | cons k ks ih=>\n      intro s\n      rw [List.foldl_cons,ih]\n      simp only [step,List.map_append,List.map_cons,List.map_nil,List.append_assoc,List.singleton_append]\n  exact h keys empty\n/-- One actual byte-key override exactly matches a literal trie put at every raw query, including all high-zero prefixes. -/\ntheorem override_read (rows:Dict.Rows) (key value q:List Bool):\n    Dict.read ((key,value)::rows) q=if key=q then value else Dict.read rows q:=Dict.read_cons key value rows q\n/-- Compact positive edge is incremented exactly once per physical occurrence. -/\ntheorem step_edge (a:Nat) (s:Summary) (key:List Bool):\n    SemiprimeBitArithmetic.bitValue (step a s key).edge=SemiprimeBitArithmetic.bitValue s.edge+1:=Counter.successor_value _\nend RiemannGaussian.SemiprimeD1StackPacketInventoryEncoding\n","RiemannGaussian.SemiprimeD1StackPacketModeAcquireDouble":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketModeAcquireEncoding\nimport RiemannGaussian.SemiprimeD1StackPacketModeAcquirePrimitives\n/-! # Physically consumed tile words and two actual marker pushes per byte\nDoubling never inserts a computed natural result. It consumes the old real\ntile word into a real reverse cursor and pushes two true markers for each byte.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketModeAcquireDouble\nopen SemiprimeD1StackPacketModeAcquire SemiprimeD1StackPacketModeAcquireEncoding\nopen SemiprimeD1StackPacketModeAcquirePrimitives SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\"=>Label.local\n/-- Actual whole44-role tile-loop boundary, with the untouched original fields retained. -/\ndef words (original order precision packets todo tiles scan:List Bool):Words:=\n  {modes:=M.input packets tiles precision,packets:=original,order:=order,todo:=todo,tileScan:=scan}\n/-- One actual true push changes exactly the next source's physical tile input. -/\ntheorem push_tile (pc next:Control) (hc:program (ctl pc)=.base (.push tileCount true (ctl next)))\n    (original order precision packets todo scan:List Bool) (tiles:Nat) :\n    Runs program 1 (ctl pc)\n      (bank (words original order precision packets todo (List.replicate tiles true) scan)) (ctl next)\n      (bank (words original order precision packets todo (List.replicate (tiles+1) true) scan)) :=by\n  have h:=push_run pc (ctl next) tileCount true\n    (bank (words original order precision packets todo (List.replicate tiles true) scan)) hc\n  rw [show tileCount=modeStack tileRole from rfl,update_mode] at h\n  dsimp only [words] at h\n  rw [input_tile] at h\n  exact h\n/-- Every actual old tile byte is consumed and replaced by two true markers; EOF is charged too. -/\ntheorem fill_run (original order precision packets todo:List Bool) (count current:Nat) :\n    Runs program (3*count+1) (ctl .tilePop)\n      (bank (words original order precision packets todo (List.replicate current true) (List.replicate count true)))\n      (ctl .orderLoop)\n      (bank (words original order precision packets todo (List.replicate (current+2*count) true) [])) :=by\n  induction count generalizing current with\n  | zero=>\n    have h:=pop_run .tilePop (ctl .orderLoop) (ctl .abort) (ctl .tilePushOne) (aux .tileScan)\n      (bank (words original order precision packets todo (List.replicate current true) [])) [] rfl rfl\n    rw [update_tileScan] at h\n    exact h\n  | succ count ih=>\n    have h0:=pop_run .tilePop (ctl .orderLoop) (ctl .abort) (ctl .tilePushOne) (aux .tileScan)\n      (bank (words original order precision packets todo (List.replicate current true) (List.replicate (count+1) true)))\n      (true::List.replicate count true) rfl rfl\n    simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n    rw [update_tileScan] at h0\n    have h1:=push_tile .tilePushOne .tilePushTwo rfl original order precision packets todo\n      (List.replicate count true) current\n    have h2:=push_tile .tilePushTwo .tilePop rfl original order precision packets todo\n      (List.replicate count true) (current+1)\n    have h3:=ih (current+2)\n    have h:=join (join (join h0 h1) h2) h3\n    have he:current+2+2*count=current+2*(count+1):=by omega\n    rw [he] at h\n    convert h using 1\n    omega\n/-- A whole actual doubling includes reversal, its genuine call/return and every byte-loop transition. -/\ntheorem double_run (original order precision packets todo:List Bool) (tiles:Nat) :\n    Runs program (5*tiles+4) (ctl .reverseTiles)\n      (bank (words original order precision packets todo (List.replicate tiles true) [])) (ctl .orderLoop)\n      (bank (words original order precision packets todo (List.replicate (2*tiles) true) [])) :=by\n  have h0:=reverse_call .reverseTiles .tilePop rfl\n    (bank (words original order precision packets todo (List.replicate tiles true) []))\n    (List.replicate tiles true) [] rfl rfl\n  simp only [List.length_replicate,List.reverse_replicate,List.append_nil] at h0\n  change Runs program (2*tiles+3) _ _ _ (Function.update (Function.update\n    (bank (words original order precision packets todo (List.replicate tiles true) [])) tileCount [])\n      (aux .tileScan) (List.replicate tiles true)) at h0\n  rw [show tileCount=modeStack tileRole from rfl,update_mode] at h0\n  dsimp only [words] at h0\n  rw [input_tile,update_tileScan] at h0\n  have h1:=fill_run original order precision packets todo tiles 0\n  simp only [Nat.zero_add] at h1\n  have h:=join h0 h1\n  change Runs program _ (ctl .reverseTiles)\n    (bank (words original order precision packets todo (List.replicate tiles true) [])) (ctl .orderLoop)\n    (bank (words original order precision packets todo (List.replicate (2*tiles) true) [])) at h\n  convert h using 1\n  omega\nend RiemannGaussian.SemiprimeD1StackPacketModeAcquireDouble\n","RiemannGaussian.SemiprimeD1StackPacketRowsEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRows\nimport RiemannGaussian.SemiprimeD1PacketRows\n/-! # Physical row-stream, lookup-presence and chronological logger identities\nAll definitions below describe actual bytes. No row, presence verdict, decoded\nID, coordinate count or list operation is an operand of the literal source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsEncoding\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace Map\nexport SemiprimeD1StackOwnerLookup (records result initial done program)\nend Map\n/-- Proof-side interpretation of the actual numeric dictionary match, including empty zero IDs. -/\ndef present (query:List Bool) :List (List Bool×List Bool)→Bool\n  | []=>false\n  | (key,_)::rows=>if bitValue key=bitValue query then true else present query rows\n/-- Even an empty remaining record list has one real false terminator. -/\ntheorem records_nonempty (rows:List (List Bool×List Bool)) :Map.records rows []≠[] :=by\n  cases rows <;> intro h <;> cases h\n/-- Actual successful lookup retains a nonempty unread suffix; absence consumes its false terminator. -/\ntheorem result_presence (query:List Bool) (rows:List (List Bool×List Bool)) :\n    (Map.result query rows []).2≠[] ↔ present query rows=true :=by\n  induction rows with\n  | nil=>simp only [Map.result,present,Bool.false_eq_true,ne_eq,not_true_eq_false]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    by_cases h:bitValue key=bitValue query\n    · simp only [Map.result,present,h,ite_true]\n      constructor\n      · intro _;trivial\n      · intro _;exact records_nonempty rows\n    · simpa only [Map.result,present,h,ite_false] using ih\n/-- The presence test is tied to the actual complete11-role source trace, not a supplied lookup answer. -/\ntheorem actual_lookup_presence (query:List Bool) (rows:List (List Bool×List Bool)) :\n    SemiprimeD1StackCalls.run Map.program\n        (SemiprimeD1StackOwnerLookupExecution.loopTime query rows+1)\n        (Map.initial query (Map.records rows []))=some (Map.done query rows []) ∧\n      ((Map.done query rows []).data (.inr .reader)≠[] ↔ present query rows=true) :=\n  ⟨SemiprimeD1StackOwnerLookupExecution.source_run query rows [],result_presence query rows⟩\n/-- Found zero-dimensional payload stays empty, while its unread false terminator witnesses actual presence. -/\ntheorem empty_payload_found (query:List Bool) (rows:List (List Bool×List Bool)) :\n    (Map.done query ((query,[])::rows) []).data (.inr .output)=[] ∧\n      (Map.done query ((query,[])::rows) []).data (.inr .reader)=Map.records rows [] ∧\n      (Map.done query ((query,[])::rows) []).data (.inr .reader)≠[] :=by\n  constructor\n  · simp [Map.done,SemiprimeD1StackOwnerLookup.data,Map.result]\n  · constructor\n    · simp [Map.done,SemiprimeD1StackOwnerLookup.data,Map.result]\n    · simpa only [Map.done,SemiprimeD1StackOwnerLookup.data,Map.result,ite_true] using records_nonempty rows\n/-- Every field is nonempty as a byte stream, even when its colour word itself is empty zero. -/\ntheorem frame_nonempty (word tail:List Bool) :frame word tail≠[] :=by\n  cases word <;> intro h <;> cases h\n/-- Only actual EOF ends a raw colour stream; a leading false byte still denotes an empty field. -/\ntheorem serialize_cons_nonempty (word:List Bool) (words:List (List Bool)) :\n    SemiprimeD1PacketRows.serialize (word::words)≠[] :=frame_nonempty _ _\n/-- Exact per-colour chronological vector-row bytes emitted by the actual frame/reverse logger. -/\ndef row (word:List Bool) :List Bool :=true::frame word []\n/-- Chronological rowsPrefix without a vector terminator, used only in trace specifications. -/\ndef rowsPrefix (words:List (List Bool)) :List Bool :=words.flatMap row\n/-- Literal frame concatenation leaves its supplied physical tail intact. -/\ntheorem frame_append (word tail suffix:List Bool) :frame word tail++suffix=frame word (tail++suffix) :=by\n  induction word with\n  | nil=>rfl\n  | cons b word ih=>simp only [frame,List.cons_append,ih]\n/-- All physical row fragments form the exact old vector codec, including empty colour fields. -/\ntheorem prefix_vector (words:List (List Bool)) :rowsPrefix words++[false]=vectorBits words :=by\n  induction words with\n  | nil=>rfl\n  | cons word words ih=>\n    change (row word++rowsPrefix words)++[false]=true::frame word (vectorBits words)\n    rw [List.append_assoc,ih]\n    simp only [row,List.cons_append,frame_append,List.nil_append]\n/-- One actual reverse-row append extends the complete reverse chronological history exactly. -/\ntheorem history_succ (old:List (List Bool)) (word:List Bool) :\n    (row word).reverse++(rowsPrefix old).reverse=(rowsPrefix (old++[word])).reverse :=by\n  simp only [rowsPrefix,List.flatMap_append,List.flatMap_cons,List.flatMap_nil,List.append_nil,List.reverse_append]\n/-- One literal logged field pays every raw word byte and both actual tags. -/\ntheorem row_length (word:List Bool) :(row word).length=2*word.length+2 :=by\n  simp only [row,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\nend RiemannGaussian.SemiprimeD1StackPacketRowsEncoding\n","RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseChildContextFresh\n/-! # Exact fresh dense-index words and literal framed coefficient bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 8192\nset_option maxRecDepth 32768\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshArithmetic\nopen SemiprimeD1StackPhaseChildContextFresh\n/-- A reduced scalar unit is empty at precision zero and the literal bit one otherwise. -/\ndef unit (positive : Bool) : List Bool :=if positive then [true] else []\n/-- Dense-index allocator interpretation; these natural indices never occur in runtime control. -/\ndef words : Nat→Nat→Bool→List (List Bool)\n  | 0,_,_=>[]\n  | n+1,0,b=>unit b::List.replicate n []\n  | n+1,r+1,b=>[]::words n r b\n/-- Every physically allocated coefficient gets exactly one original vector constructor/field. -/\ndef chunk (w : List Bool) : List Bool :=true::SemiprimeSourceHistogramKeyBits.frame w []\n/-- All coefficient bytes except the final vector terminator. -/\ndef bytes (ws : List (List Bool)) : List Bool :=(ws.map chunk).flatten\n/-- Empty coefficient allocation emits exactly two literal codec bits. -/\ntheorem chunk_zero : chunk []=[true,false] :=rfl\n/-- Nonzero reduced unit emits exactly four literal codec bits. -/\ntheorem chunk_one : chunk [true]=[true,true,true,false] :=rfl\n/-- Flattened coefficient chunks are in the EXACT existing vector order. -/\ntheorem bytes_vector (ws : List (List Bool)) : bytes ws++[false]=SemiprimeD1TensorTapeCodec.vectorBits ws :=by\n  induction ws with\n  | nil=>rfl\n  | cons w ws ih=>\n    change (chunk w++bytes ws)++[false]=_\n    rw [List.append_assoc,ih]\n    change (true::SemiprimeSourceHistogramKeyBits.frame w [])++SemiprimeD1TensorTapeCodec.vectorBits ws=_\n    simp only [List.cons_append,SemiprimeD1TensorTapeCodec.frame_append,List.nil_append]\n    rfl\n/-- The allocation shape is the actual new-rank counter length, including the q=1 all-zero case. -/\ntheorem words_length (n r : Nat) (b : Bool) : (words n r b).length=n :=by\n  induction n generalizing r with\n  | zero=>rfl\n  | succ n ih=>cases r <;> simp only [words,List.length_cons,List.length_replicate,ih]\n/-- Original dense index is exactly oldrank; the one-cell-axis edge case needs no exception. -/\ntheorem words_range (n r : Nat) (b : Bool) :\n    words n r b=(List.range n).map (fun i=>if i=r then unit b else []) :=by\n  induction n generalizing r with\n  | zero=>rfl\n  | succ n ih=>\n    cases r with\n    | zero=>\n      rw [List.range_succ_eq_map,List.map_cons,List.map_map]\n      simp only [words,ite_false,Nat.reduceEqDiff,ite_true,Function.comp_def]\n      rw [List.map_const',List.length_range]\n    | succ r=>\n      rw [List.range_succ_eq_map,List.map_cons,List.map_map]\n      have hz : ¬0=r+1:=by omega\n      simp only [words,hz,ite_false,Nat.succ.injEq,Function.comp_def,ih]\n/-- At most one four-byte unit occurs; every other allocated coefficient has two bytes. -/\ntheorem bytes_length (n r : Nat) (b : Bool) : (bytes (words n r b)).length≤2*n+2 :=by\n  have hz:∀n,(bytes (List.replicate n [])).length=2*n:=by\n    intro n\n    induction n with\n    | zero=>rfl\n    | succ n ih=>simp only [List.replicate_succ,bytes,List.map_cons,List.flatten_cons,List.length_append,chunk_zero,List.length_cons,List.length_nil] at *;omega\n  induction n generalizing r with\n  | zero=>simp only [words,bytes,List.map_nil,List.flatten_nil,List.length_nil];omega\n  | succ n ih=>\n    cases r with\n    | zero=>\n      have hu:(chunk (unit b)).length≤4:=by cases b <;> decide\n      change (chunk (unit b)++bytes (List.replicate n [])).length≤_\n      rw [List.length_append,hz]\n      omega\n    | succ r=>\n      change (chunk []++bytes (words n r b)).length≤_\n      rw [List.length_append,chunk_zero]\n      have h:=ih r\n      change 2+(bytes (words n r b)).length≤_\n      omega\n/-- Source reduction of the literal scalar unit agrees with the actual width-empty peek. -/\ntheorem unit_reduce (p : Nat) :\n    (SemiprimeD1JetScalarBits.reduce p [true]).bits=unit (decide (0<p)) :=by\n  cases p with\n  | zero=>rfl\n  | succ p=>\n    change (SemiprimeSourceCompactBits.trim (SemiprimeD1JetScalarBits.takeBits (p+1) [true]).bits).bits=_\n    rw [SemiprimeD1JetScalarBits.takeBits_bits]\n    simp [unit,SemiprimeSourceCompactBits.trim]\n/-- Exact original FreshJetBits.acquireFresh coefficient list, before its literal vector codec. -/\ntheorem words_original (old : SemiprimeD1JetAxes.Context) (q p : Nat) :\n    words (q*old.rank) old.rank (decide (0<p))=(SemiprimeD1FreshJetBits.acquireFresh old q p).words :=by\n  rw [words_range]\n  simp only [SemiprimeD1FreshJetBits.acquireFresh,unit_reduce]\nend RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshArithmetic\n","RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionArithmetic\n/-! # Exact real binary increment/copy/adder calls and physical boundary views -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionPrimitives\nopen SemiprimeD1StackPhaseWorkingPrecision SemiprimeD1StackPhaseWorkingPrecisionArithmetic\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact binary stage view; both actual scratch words are empty at every boundary. -/\ndef data (old : M.Stack→List Bool) (left right output counter next todo zeros shifts power : List Bool) : Stack→List Bool :=\n  store old (words left right [] output counter next todo zeros shifts [] power)\n/-- Chronological actual instruction composition retains every real outer frame. -/\ntheorem join {m n : Nat} {pc mid next : Label} {d e f : Stack→List Bool}\n    (h : Runs program m pc d mid e) (g : Runs program n mid e next f) :\n    Runs program (m+n) pc d next f :=runs_trans program m n pc mid next d e f h g\n/-- One physically executed literal binary write. -/\ntheorem push (pc next : Label) (key : Stack) (bit : Bool) (d : Stack→List Bool)\n    (hc : program pc=.base (.push key bit next)) :\n    Runs program 1 pc d next (Function.update d key (bit::d key)) :=by\n  apply one_base program pc next (.push key bit next) _ _ hc <;> rfl\n/-- Actual preserving copy into a clear physical destination, with both real loops paid. -/\ntheorem copy_call (kind : Fin 10) (pc next : Label) (hc : program pc=.call (.copy kind 0) next)\n    (d : Stack→List Bool) (hs : d (aux .copyScratch)=[]) (ht : d (copyTarget kind)=[]) :\n    Runs program (5*(d (copySource kind)).length+4) pc d next\n      (Function.update d (copyTarget kind) (d (copySource kind))) :=by\n  let xs:=d (copySource kind)\n  have hi:Link.DataRel (copyStack kind) d (SemiprimeD1StackCopy.state 0 none xs [] []).store d:=by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · exact ht\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack kind) (copy_injective kind) _ _ _ hi (1:Fin 3) xs\n  have he:Function.update (SemiprimeD1StackCopy.state 0 none xs [] []).store 1 xs=\n      (SemiprimeD1StackCopy.done xs xs).store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  have hr:=SemiprimeD1StackCopy.copy_words xs [] none\n  rw [List.append_nil] at hr\n  exact included_call program (copyStack kind) (Label.copy kind) (copy_injective kind)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc (5*xs.length+3)\n    (SemiprimeD1StackCopy.state 0 none xs [] []) (SemiprimeD1StackCopy.done xs xs) d _ rfl rfl hr hi ho\n/-- Actual frozen increment consumes the counter and writes its REAL carry-prefix/wrapped bits. -/\ntheorem increment_call (second : Bool) (old : M.Stack→List Bool) (l r out word todo power : List Bool) :\n    ∃q≤10*word.length+16,Runs program q (.increment second)\n      (data old l r out word [] todo [] [] power) (.popOverflow second)\n      (data old l r out [] (SemiprimeD1StackIncrement.overflow word::I.wrapped word) todo [] [] power) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackIncrementBytecode.increment_run word []\n  simp only [List.append_nil] at hr\n  refine ⟨q+1,by omega,?_⟩\n  apply included_call program incrementStack Label.counter increment_injective Inc.code Inc.entry (fun _=>rfl)\n    (.increment second) (.popOverflow second) rfl q\n    ⟨some Inc.entry,none,Inc.contents word [] []⟩\n    ⟨none,none,Inc.contents [] [] (SemiprimeD1StackIncrement.overflow word::I.wrapped word)⟩ _ _ rfl rfl hr\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk;rcases k with k|k\n      · rfl\n      · cases k <;> first\n        | rfl\n        | exact (hk .input rfl).elim\n        | exact (hk .scratch rfl).elim\n        | exact (hk .output rfl).elim\n/-- One REAL consuming ripple addition; original metadata and binary D remain retained. -/\ntheorem adder_call (second : Bool) (old : M.Stack→List Bool) (l r power : List Bool) :\n    Runs program (3*(max l.length r.length+1)+2*(SemiprimeBitArithmetic.addBits l r false).bits.length+3)\n      (.add second) (data old l r [] [] [] [] [] [] power)\n      (if second then .done else .copyZero true)\n      (data old [] [] (SemiprimeBitArithmetic.addBits l r false).bits [] [] [] [] [] power) :=by\n  apply included_call program adderStack Label.adder adder_injective Add.code (.start false) (fun _=>rfl)\n    (.add second) (if second then .done else .copyZero true) rfl\n    (3*(max l.length r.length+1)+2*(SemiprimeBitArithmetic.addBits l r false).bits.length+2)\n    (Add.state (some (.start false)) none l r [] [])\n    (Add.state none none [] [] [] (SemiprimeBitArithmetic.addBits l r false).bits) _ _ rfl rfl\n    (SemiprimeD1StackAdderExecution.source_run l r false)\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk;rcases k with k|k\n      · rfl\n      · cases k <;> first\n        | rfl\n        | exact (hk .left rfl).elim\n        | exact (hk .right rfl).elim\n        | exact (hk .scratch rfl).elim\n        | exact (hk .output rfl).elim\n/-- Literal ripple time is linear in the ACTUAL physical binary operand widths. -/\ntheorem adder_time_le (l r : List Bool) :\n    3*(max l.length r.length+1)+2*(SemiprimeBitArithmetic.addBits l r false).bits.length+3≤5*(l.length+r.length)+8 :=by\n  have hh:=(SemiprimeBitArithmetic.addBits_counts l r false).2.2.2.2\n  have hm:max l.length r.length≤ l.length+r.length:=max_le (by omega) (by omega)\n  omega\nend RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionPrimitives\n","RiemannGaussian.SemiprimeD1StackPortOwnerRecipeModes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeCalls\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRecipeModes\nopen SemiprimeD1StackPortOwnerRecipe SemiprimeD1StackPortOwnerRecipeSpec SemiprimeD1StackPortOwnerRecipeCalls\nopen SemiprimeD1StackProcedureTrace (Runs one_base runs_refl runs_trans)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Actual source starts every literal mode cache empty, including mode zero. -/\ntheorem mode_initial (p:Counters) : input (words p)=atMode p 0 := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · cases k with\n      | mode j=>\n        by_cases h:j.val=0\n        · simp [input,atMode,h,unary]\n        · have hj:j≠0:=by intro he;exact h (congrArg Fin.val he)\n          simp [input,atMode,hj]\n      | _=>rfl\n    · rfl\n/-- A physically pushed next marker installs precisely the next literal mode word. -/\ntheorem mode_update (p:Counters) (j:Fin 9) :\n    Function.update (atMode p j.val) (reg (.mode ⟨j.val+1,by omega⟩)) (unary (j.val+1))=\n      atMode p (j.val+1) := by\n  funext k\n  rcases k with k|k\n  · simp [atMode,reg,Function.update]\n  · rcases k with k|k\n    · cases k with\n      | mode i=>\n        by_cases he:i=⟨j.val+1,by omega⟩\n        · subst i\n          simp [atMode,reg,Function.update]\n        · have hv:i.val≠j.val+1:=by intro h;exact he (Fin.ext h)\n          have hc:i.val≤j.val+1 ↔ i.val≤j.val:=by omega\n          simp [atMode,reg,Function.update,he,hc]\n      | _=>simp [atMode,reg,Function.update]\n    · simp [atMode,reg,Function.update]\n/-- All literal mode tags have been physically acquired before any coordinate arithmetic. -/\ntheorem modes_ready (p:Counters) : atMode p 9=atStage p 0 := by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · cases k with\n      | mode j=>\n        have hj:j.val≤9:=by omega\n        simp [atMode,atStage,cached,hj]\n      | _=>rfl\n    · rfl\n/-- Static continuation of the literal mode-word builder. -/\ndef nextMode (j:Fin 9) : Label :=\n  if h:j.val<8 then .local (.modeCopy ⟨j.val+1,by omega⟩) else .local (.prepare 0)\n/-- Real preserving copy followed by its real one-marker push. -/\ntheorem mode_step (p:Counters) (j:Fin 9) :\n    Runs program (5*j.val+5) (.local (.modeCopy j)) (atMode p j.val)\n      (nextMode j) (atMode p (j.val+1)) := by\n  have hc:=copy_call (.mode j) (atMode p j.val) (.local (.modeCopy j)) (.local (.modePush j)) rfl rfl\n  have hsource:(atMode p j.val) (copyOperands (.mode j)).1=unary j.val:=by\n    simp [atMode,copyOperands,reg]\n  have hdest:(atMode p j.val) (copyOperands (.mode j)).2=[]:=by\n    simp [atMode,copyOperands,reg]\n  rw [hsource,hdest,List.append_nil] at hc\n  let copied:=Function.update (atMode p j.val) (reg (.mode ⟨j.val+1,by omega⟩)) (unary j.val)\n  change Runs program (5*(unary j.val).length+4) (.local (.modeCopy j)) (atMode p j.val)\n    (.local (.modePush j)) copied at hc\n  have hp:Runs program 1 (.local (.modePush j)) copied (nextMode j) (atMode p (j.val+1)):=by\n    apply one_base program (.local (.modePush j)) (nextMode j)\n      (.push (reg (.mode ⟨j.val+1,by omega⟩)) true (nextMode j)) copied _ rfl rfl\n    change Function.update copied (reg (.mode ⟨j.val+1,by omega⟩))\n      (true::copied (reg (.mode ⟨j.val+1,by omega⟩)))=_\n    dsimp [copied]\n    rw [Function.update_self,Function.update_idem]\n    rw [show true::unary j.val=unary (j.val+1) from (SemiprimeD1StackUnaryDivmod.unary_succ j.val).symm]\n    exact mode_update p j\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hc hp\n  simpa only [unary,List.length_replicate,show 5*j.val+4+1=5*j.val+5 by omega] using h\n/-- Proof-side label for the remaining literal mode constructor suffix. -/\ndef modeEntry (n:ℕ) : Label :=\n  if h:n<9 then .local (.modeCopy ⟨n,h⟩) else .local (.prepare 0)\n/-- All nine real mode copies/pushes execute, without a supplied literal-tag bank. -/\ntheorem modes_suffix (p:Counters) (fuel count:ℕ) (hc:count+fuel=9) :\n    ∃time≤45*fuel,Runs program time (modeEntry count) (atMode p count)\n      (.local (.prepare 0)) (atMode p 9) := by\n  induction fuel generalizing count with\n  | zero=>\n    have he:count=9:=by omega\n    subst count\n    exact ⟨0,le_rfl,runs_refl program _ _⟩\n  | succ fuel ih=>\n    have hcount:count<9:=by omega\n    have hn:count+1+fuel=9:=by omega\n    obtain ⟨time,ht,hr⟩:=ih (count+1) hn\n    let j:Fin 9:=⟨count,hcount⟩\n    have hstep:=mode_step p j\n    have hnext:nextMode j=modeEntry (count+1):=by\n      by_cases hh:count<8\n      · have hsucc:count+1<9:=by omega\n        simp [nextMode,modeEntry,j,hh,hsucc]\n      · have he:count=8:=by omega\n        subst count\n        rfl\n    rw [hnext] at hstep\n    have h:=runs_trans program _ _ _ _ _ _ _ _ hstep hr\n    refine ⟨(5*count+5)+time,by omega,?_⟩\n    have hentry:modeEntry count=.local (.modeCopy j):=by simp [modeEntry,hcount,j]\n    rw [hentry]\n    exact h\n/-- Literal first jump plus all physical tag construction, ending at preparation stage zero. -/\ntheorem modes_run (p:Counters) :\n    ∃time≤406,Runs program time (.local .start) (input (words p)) (.local (.prepare 0)) (atStage p 0) := by\n  obtain ⟨time,ht,hr⟩:=modes_suffix p 9 0 rfl\n  have hz:Runs program 1 (.local .start) (input (words p)) (.local (.modeCopy 0)) (input (words p)):=by\n    apply one_base program _ _ (.jump (.local (.modeCopy 0))) _ _ rfl rfl\n    rfl\n  rw [mode_initial] at hz\n  change Runs program time (.local (.modeCopy 0)) (atMode p 0) (.local (.prepare 0)) (atMode p 9) at hr\n  rw [modes_ready] at hr\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hz hr\n  rw [←mode_initial] at h\n  exact ⟨1+time,by omega,h⟩\nend RiemannGaussian.SemiprimeD1StackPortOwnerRecipeModes\n","RiemannGaussian.SemiprimeD1StackProductCheckReject":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductCheckGuard\n\n/-! # Whole actual rejecting product-checker path\nInvalid raw words are rejected by the computed guard. Every vector/count byte\nis physically drained; only original input/modulus/suffix and false verdict\nremain. No positivity, canonicality or intended arithmetic answer is supplied.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackProductCheckReject\nopen SemiprimeD1StackProductCheck SemiprimeD1StackProductCheckAcquisition\nopen SemiprimeD1StackProductCheckGuard SemiprimeD1StackProcedureTrace\n\n/-- Exact final physical payload with original input/cache/suffix and one verdict. -/\ndef finalData (raw cached : List Bool) (bit : Bool) : Stack→List Bool :=\n  Function.update (Function.update (input raw cached) readerRole (raw.drop (3*cached.length))) output [bit]\n/-- Exact whole checker halt, with no parser/operand/source work or return frames. -/\ndef done (raw cached : List Bool) (bit : Bool) : C.State Stack Label :=\n  ⟨none,none,none,finalData raw cached bit,[]⟩\n\n/-- The computed rejecting branch physically writes its singleton false result. -/\ntheorem reject_push (raw cached : List Bool) :\n    Runs program 1 .reject (afterAcquire raw cached) (.clearVector false)\n      (Function.update (afterAcquire raw cached) output [false]) := by\n  apply one_base program .reject (.clearVector false) (.push output false (.clearVector false)) _ _ rfl\n  · rfl\n  · rfl\n\n/-- Actual complete vector cleanup works for either literal continuation. -/\ntheorem clear_vector (compute : Bool) (data : Stack→List Bool) :\n    Runs program ((data vectorRole).length+1) (.clearVector compute) data\n      (if compute then .multiply else .clearCount) (Function.update data vectorRole []) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program (.clearVector compute)\n    (if compute then .multiply else .clearCount) vectorRole rfl data (data vectorRole)\n  rw [Function.update_eq_self] at h\n  exact h\n/-- Every literal count-cache byte is actually erased before the final halt. -/\ntheorem clear_count (data : Stack→List Bool) :\n    Runs program ((data countRole).length+1) .clearCount data .done (Function.update data countRole []) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program .clearCount .done countRole rfl data (data countRole)\n  rw [Function.update_eq_self] at h\n  exact h\n\n/-- Complete rejection cleanup is exactly the promised retained-input payload. -/\ntheorem cleanup_data (raw cached : List Bool) :\n    Function.update (Function.update (Function.update (afterAcquire raw cached) output [false]) vectorRole []) countRole []=\n      finalData raw cached false := by\n  funext k\n  by_cases hc:k=countRole\n  · subst k;rfl\n  by_cases hv:k=vectorRole\n  · subst k;rfl\n  by_cases hr:k=readerRole\n  · subst k;rfl\n  by_cases ho:k=output\n  · subst k;rfl\n  simp only [Function.update_of_ne hc,Function.update_of_ne hv,Function.update_of_ne hr,Function.update_of_ne ho,\n    finalData,afterAcquire,beforeAcquire]\n\n/-- Own complete rejecting-path budget includes actual acquisition/guard and\nevery unneeded vector/count byte, plus branch, write and caller halt. -/\ndef rejectBudget (raw cached : List Bool) : ℕ :=\n  (3+SemiprimeD1StackWordVectorExecution.timeBound raw cached countWord+1)+\n    (SemiprimeD1StackVectorCanonicalExecution.timeBound (words raw cached) cached+1)+\n    (SemiprimeD1StackWordVectorExecution.result raw cached countWord).length+8\n\n/-- COMPLETE actual rejection for every raw assignment/modulus, including zero\nmodulus. The sole premise names the ACTUALLY computed guard outcome. -/\ntheorem source_run (raw cached : List Bool) (ha : accepted raw cached=false) :\n    ∃t ≤ rejectBudget raw cached,C.run program t (initial raw cached)=some (done raw cached false) := by\n  obtain ⟨a,haTime,h0⟩:=checked_prefix raw cached\n  have h1:=branch_run raw cached\n  simp only [ha,Bool.false_eq_true,ite_false] at h1\n  have h2:=reject_push raw cached\n  let data1:=Function.update (afterAcquire raw cached) output [false]\n  let data2:=Function.update data1 vectorRole []\n  have h3:=clear_vector false data1\n  have h4:=clear_count data2\n  change Runs program ((SemiprimeD1StackWordVectorExecution.result raw cached countWord).length+1)\n    (.clearVector false) data1 .clearCount data2 at h3\n  change Runs program 4 .clearCount data2 .done (Function.update data2 countRole []) at h4\n  have h:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4\n  have hd : Function.update data2 countRole []=finalData raw cached false := cleanup_data raw cached\n  rw [hd] at h\n  obtain ⟨finish,hr,ho⟩:=h [] (initial raw cached) ⟨rfl,rfl,rfl⟩\n  have he:=halt_run program .done rfl (finalData raw cached false) [] finish ho\n  refine ⟨(((a+1)+1)+((SemiprimeD1StackWordVectorExecution.result raw cached countWord).length+1))+4+1,?_,?_⟩\n  · unfold rejectBudget\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,he]\n    rfl\n\nend RiemannGaussian.SemiprimeD1StackProductCheckReject\n","RiemannGaussian.SemiprimeD1StackProductTableLeafCode":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableLeafCalls\n/-! # Every actual literal product-table scalar code push\nOnly the already physically computed singleton checker bit selects the fixed\nzero/one branch. These are integral local entries before any network product.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductTableLeafCode\nopen SemiprimeD1StackProductTable SemiprimeD1StackProductTableState\nopen SemiprimeD1StackProductTableLeafCalls SemiprimeD1StackProcedureTrace\nopen SemiprimeD1BooleanTreeStream (leafBytes)\n/-- Next literal zero-code label, fixed before N. -/\ndef zeroNext (pos : Fin 4) : Label :=\n  if h:pos.val<3 then .zero ⟨pos.val+1,by omega⟩ else .leafCleanup\n/-- Next literal one-code label, fixed before N. -/\ndef oneNext (pos : Fin 6) : Label :=\n  if h:pos.val<5 then .one ⟨pos.val+1,by omega⟩ else .leafCleanup\n/-- One actual zero-leaf push preserves the full still-live checker store. -/\ntheorem zero_step (pos : Fin 4) (checker : P.Stack→List Bool) (bits front hist : List Bool) :\n    Runs program 1 (.zero pos) (withChecker (data bits 0 front hist) checker) (zeroNext pos)\n      (withChecker (data bits 0 front (zeroBits pos::hist)) checker) := by\n  apply one_base program (.zero pos) (zeroNext pos) (.push (.inr .reversed) (zeroBits pos) (zeroNext pos)) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- One actual accepted-leaf push preserves every still-live checker byte. -/\ntheorem one_step (pos : Fin 6) (checker : P.Stack→List Bool) (bits front hist : List Bool) :\n    Runs program 1 (.one pos) (withChecker (data bits 0 front hist) checker) (oneNext pos)\n      (withChecker (data bits 0 front (oneBits pos::hist)) checker) := by\n  apply one_base program (.one pos) (oneNext pos) (.push (.inr .reversed) (oneBits pos) (oneNext pos)) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- Complete scalar/tree/vector/word/end framing, with every bit actually\nwritten. No coefficient getter or already-reduced aggregate is substituted. -/\ntheorem emit_run (b : Bool) (checker : P.Stack→List Bool) (bits front hist : List Bool) :\n    Runs program (leafBytes b).length (emitStart b) (withChecker (data bits 0 front hist) checker) .leafCleanup\n      (withChecker (data bits 0 front ((leafBytes b).reverse++hist)) checker) := by\n  cases b with\n  | false=>\n    have h0:=zero_step 0 checker bits front hist\n    have h1:=zero_step 1 checker bits front (false::hist)\n    have h2:=zero_step 2 checker bits front (true::false::hist)\n    have h3:=zero_step 3 checker bits front (false::true::false::hist)\n    exact runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3\n  | true=>\n    have h0:=one_step 0 checker bits front hist\n    have h1:=one_step 1 checker bits front (false::hist)\n    have h2:=one_step 2 checker bits front (true::false::hist)\n    have h3:=one_step 3 checker bits front (true::true::false::hist)\n    have h4:=one_step 4 checker bits front (true::true::true::false::hist)\n    have h5:=one_step 5 checker bits front (false::true::true::true::false::hist)\n    exact runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _\n        (runs_trans program _ _ _ _ _ _ _ _\n          (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4) h5\nend RiemannGaussian.SemiprimeD1StackProductTableLeafCode\n","RiemannGaussian.SemiprimeD1StackPublicCarryRecordClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicCarryRecordBounds\nimport RiemannGaussian.SemiprimeD1StackStaticRecordClock\n/-! # Closed concrete actual carry-record clock from physical scope metadata -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 100000\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicCarryRecordClock\nopen SemiprimeD1StackPublicCarryRecord SemiprimeD1StackPublicCarryRecordExecution\n/-- Fixed quadratic polynomial per physically acquired scalar, plus paid\nbinary-to-unary ordinal conversion and every original tensor framing byte. -/\ndef runBound (bits indexWord : List Bool) (words : List (List Bool)) (M : Nat) : Nat :=\n  SemiprimeD1StackPublicCarryTableBounds.runBound bits indexWord words+\n    110*(words.length+1)*(M+1)+21*2^words.length+20\n/-- The complete actual own source clock, without native report transport. -/\ntheorem timeBound_le (bits indexWord : List Bool) (words : List (List Bool)) (M : Nat)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound bits indexWord words≤runBound bits indexWord words M := by\n  have h:=SemiprimeD1StackStaticRecordClock.timeBound_le I.static (I.inputTemplate bits indexWord)\n    words (T.answer bits indexWord) (T.budget bits indexWord) M hl hv\n  have ht:=SemiprimeD1StackPublicCarryTableBounds.timeBound_le bits indexWord words\n  change SemiprimeD1StackStaticTableBounds.runBound I.static (I.inputTemplate bits indexWord)\n    words (T.budget bits indexWord)≤_ at ht\n  change timeBound bits indexWord words≤_ at h\n  unfold runBound\n  omega\n/-- Every real static-table/scoping/logging transition obeys this closed bound. -/\ntheorem source_run_bounded (bits indexWord : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (M : Nat) (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M)\n    (hist out : List Bool) :\n    ∃t≤runBound bits indexWord words M,SemiprimeD1StackCalls.run program t\n      (initial bits indexWord (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)=\n      some (done bits indexWord words hist out) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits indexWord hb words hist out\n  exact ⟨t,ht.trans (timeBound_le bits indexWord words M hl hv),hr⟩\nend RiemannGaussian.SemiprimeD1StackPublicCarryRecordClock\n","RiemannGaussian.SemiprimeD1StackPublicInputRecordOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputRecordBounds\nimport RiemannGaussian.SemiprimeD1StackPublicInputTableOriginal\nimport RiemannGaussian.SemiprimeD1StackBooleanRecordOriginal\n/-! # Entire original input tensor and chronological old record bytes\nThe caller acquires the actual ordered numeric scope and descriptor index.\nNo assignment, table, native evaluator or verdict is supplied to the source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputRecordOriginal\nopen SemiprimeD1StackPublicInputRecord SemiprimeD1StackPublicInputRecordExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (idAt)\nend Bank\nnamespace Log\nexport SemiprimeD1StackVertexRecordStreamExecution (rows history)\nend Log\n/-- The read-only template is ONLY original N and descriptor index bytes;\nall raw assignments, metadata, caches, results and clock fields start empty. -/\ntheorem initial_template_only (bits indexWord bank hist out : List Bool) (k : SemiprimeD1StackPublicInput.Stack) :\n    (initial bits indexWord bank hist out).data (G.tableStack (SemiprimeD1StackStaticTable.template k))=\n      if k=.inl SemiprimeD1StackPublicInput.H.original then bits\n      else if k=SemiprimeD1StackPublicInput.index then indexWord else [] :=\n  SemiprimeD1StackPublicInputTableTrace.template_only bits indexWord k\n/-- Same proof-side original input vertex with the caller's ordered numeric scope. -/\nabbrev vertex :=SemiprimeD1StackBooleanRecordOriginal.vertex\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (side : Fin 2) (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n  (indexWord : List Bool) (hi : indexWord.length=i.val) (M : Nat) (ports : List Nat)\n  (hp : ∀j∈ports,j<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.input side i):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hi hp\n/-- Exactly the complete original input table and unchanged unary port order. -/\ntheorem row_original :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicInputTableExecution.table bits indexWord (ports.map (Bank.idAt M)))=\n      SemiprimeD1StackVertexRecordStream.row\n        (SemiprimeD1StackVertexReadExecution.portTape (vertex (bitValue bits) hN (.inl (.input side i)) ports hlen).ports)\n        (SemiprimeD1TensorTapeCodec.tape (vertex (bitValue bits) hN (.inl (.input side i)) ports hlen).table) := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape M ports hp\n  have ht:=SemiprimeD1StackPublicInputTableOriginal.table_original bits hc hN side i indexWord hi\n    (ports.map (Bank.idAt M)) (by simpa only [List.length_map] using hlen)\n  rw [hs,ht]\n  exact congrArg (SemiprimeD1StackVertexRecordStream.row (SemiprimeD1StackVertexReadExecution.portTape ports))\n    (SemiprimeD1StackBooleanRecordOriginal.tape_cast hlen.symm\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.input side i)))).symm\n/-- Literal actual row prepends exactly the unchanged old product-reader record. -/\ntheorem record_bytes_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicInputTableExecution.table bits indexWord (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.input side i)) ports hlen::rest) := by\n  rw [row_original bits hc hN side i indexWord hi M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStream.row_records _ rest\n/-- Appending one actual input row retains the chronological order of all old rows. -/\ntheorem history_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous old) out).data G.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen]) old := by\n  rw [history_row,row_original bits hc hN side i indexWord hi M ports hp hlen]\n  simp only [Log.history,SemiprimeD1StackVertexRecordStreamExecution.rows_append,Log.rows,\n    List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final actual logger reversal emits the exact forward old records and\none final false tag, without copying the accumulated tail at every node. -/\ntheorem reverse_original (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous []) (false::out)).data G.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen])++out)⟩ := by\n  rw [history_original bits hc hN side i indexWord hi M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- The actual source execution and exact old chronological record hold together. -/\ntheorem source_run_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound bits indexWord (ports.map (Bank.idAt M)),∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial bits indexWord (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M)))\n          (Log.history previous old) out)=some finish ∧\n      finish=done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data G.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.input side i)) ports hlen]) old := by\n  have hb:bits≠[]:=by intro he;subst bits;exact (Nat.not_lt_zero _ hN).elim\n  obtain ⟨t,ht,hr⟩:=source_run bits indexWord hb (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_original bits hc hN side i indexWord hi M ports hp hlen previous old out⟩\nomit hp in\n/-- Each individual acquired coefficient is the exact original integer0/1. -/\ntheorem literal_original_coefficient\n    (input : Fin (SemiprimeMacroGraph.arity (.input side i : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal []\n        (SemiprimeD1StackStaticTableSpec.leafWords (T.answer bits indexWord) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.input side i) input).accepted\n        then 1 else 0 :=\n  SemiprimeD1StackPublicInputTableOriginal.literal_original_coefficient bits hc hN side i indexWord hi input\nend RiemannGaussian.SemiprimeD1StackPublicInputRecordOriginal\n","RiemannGaussian.SemiprimeD1StackPublicScale":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSourceBounds\nimport RiemannGaussian.SemiprimeD1StackInputDotBounds\nimport RiemannGaussian.SemiprimeD1StackWordEqualBounds\n/-! # Closed physical public scale caller\nOriginal binary N, raw assignment, physical j/k marker caches and a singleton\nforward/inverse selector are the only initial data. Root source acquisition,\nzero-word padding, dot acquisition/guard/evaluation and output equality are\nliteral included procedures, not supplied truth or evaluator callbacks.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackPublicScale\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace R\nexport SemiprimeD1StackRootSources (Stack Label program input initial modulusKey)\nend R\nnamespace I\nexport SemiprimeD1StackInputDotEvaluate (Stack Label Args program initial output status rawRole suffixRole)\nend I\nnamespace W\nexport SemiprimeD1StackWordBlock (Stack Label program initial)\nend W\nnamespace E\nexport SemiprimeD1StackWordEqual (Label code)\nend E\n/-- Seven physical original-input, padding, output and scratch roles. -/\ninductive Aux where\n  | raw | selector | padding | scratch | count | word | output\n  deriving DecidableEq,Repr\ninstance : Fintype Aux := Fintype.ofList [.raw,.selector,.padding,.scratch,.count,.word,.output]\n  (by intro k;cases k <;> simp)\n/-- Original root bank, full executed dot backend and private finite work roles. -/\nabbrev Stack := R.Stack⊕(I.Stack⊕Aux)\n/-- Literal auxiliary role embedding. -/\ndef auxRole (k : Aux) : Stack := .inr (.inr k)\n/-- Acquired original binary modulus word; no separate prepared modulus input. -/\ndef modulusRole : Stack := .inl (.inl R.modulusKey)\n/-- Actual dot base/stride/frequency/count physical cache roles. -/\ndef baseRole : I.Stack := .inl (.inl (.inl .base))\n/-- Actual shared source/word-vector count cache. -/\ndef countRole : I.Stack := .inl SemiprimeD1StackInputDotEvaluate.countRole\n/-- Literal whole-dot role embedding; its modulus is acquired by a real preserving copy. -/\ndef dotStack (k : I.Stack) : Stack := .inr (.inl k)\n/-- Five real preserving copies: original raw, modulus-width, forward/inverse code, and actual dot modulus. -/\ndef copyStack (site : Fin 5) (k : Fin 3) : Stack :=\n  if k=0 then\n    if site=0 then auxRole .raw else if site=1 ∨ site=4 then modulusRole\n    else .inl (.inr (if site=2 then .forwardRoot else .root))\n  else if k=1 then\n    if site=0 then dotStack I.rawRole else if site=1 then auxRole .padding\n    else if site=4 then dotStack (.inl SemiprimeD1StackInputDotEvaluate.modulusRole) else dotStack baseRole\n  else auxRole .scratch\n/-- Output block is read from the actual unread raw suffix using actual M width. -/\ndef blockStack (k : Fin 5) : Stack :=\n  if k=0 then dotStack I.suffixRole else if k=1 then modulusRole else if k=2 then auxRole .count\n  else if k=3 then auxRole .scratch else auxRole .word\n/-- Direct physical equality consumes the actual numerical result and output word. -/\ndef equalStack : SemiprimeD1StackAdder.Stack→Stack\n  | .left=>dotStack I.output\n  | .right=>auxRole .word\n  | .scratch=>auxRole .scratch\n  | .output=>auxRole .output\n/-- Fixed labels; selector and every unbounded operand live only on Bool stacks. -/\ninductive Label where\n  | start | select | chooseForward | chooseInverse | copyModulus | copyRaw | copyWidth | zeroPop | zeroPush\n  | seed (position : Fin 2) | compute | branch | readOutput | equal | reject | done | bad\n  | roots (pc : R.Label) | copy (site : Fin 5) (pc : Fin 9) | dot (pc : I.Label)\n  | block (pc : W.Label) | compare (pc : E.Label)\n  deriving Fintype\n/-- ONE fixed actual public scale instruction table. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call (.roots .start) .select\n  | .select=>.base (.pop (auxRole .selector) .bad .chooseForward .chooseInverse)\n  | .chooseForward=>.call (.copy 2 0) .copyModulus\n  | .chooseInverse=>.call (.copy 3 0) .copyModulus\n  | .copyModulus=>.call (.copy 4 0) .copyRaw\n  | .copyRaw=>.call (.copy 0 0) .copyWidth\n  | .copyWidth=>.call (.copy 1 0) .zeroPop\n  | .zeroPop=>.base (.pop (auxRole .padding) (.seed 0) .zeroPush .zeroPush)\n  | .zeroPush=>.base (.push (dotStack I.rawRole) false .zeroPop)\n  | .seed pos=>.base (.push (dotStack countRole) true (if pos=0 then .seed 1 else .compute))\n  | .compute=>.call (.dot .start) .branch\n  | .branch=>.base (.pop (dotStack I.status) .bad .reject .readOutput)\n  | .readOutput=>.call (.block .start) .equal\n  | .equal=>.call (.compare .loop) .done\n  | .reject=>.base (.push (auxRole .output) false .done)\n  | .done | .bad=>.base .halt\n  | .roots pc=>SemiprimeD1StackValidationLink.instruction Sum.inl Label.roots (R.program pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n  | .dot pc=>SemiprimeD1StackValidationLink.instruction dotStack Label.dot (I.program pc)\n  | .block pc=>SemiprimeD1StackValidationLink.instruction blockStack Label.block (W.program pc)\n  | .compare pc=>SemiprimeD1StackMultiplierLink.instruction equalStack Label.compare (E.code pc)\n/-- Literal seven-role private store. -/\ndef aux (raw selector padding scratch count word output : List Bool) : Aux→List Bool\n  | .raw=>raw | .selector=>selector | .padding=>padding | .scratch=>scratch\n  | .count=>count | .word=>word | .output=>output\n/-- Physical combined data, a specification view rather than a runtime supplier. -/\ndef store (roots : R.Stack→List Bool) (dot : I.Stack→List Bool)\n    (raw selector padding scratch count word output : List Bool) : Stack→List Bool :=\n  Sum.elim roots (Sum.elim dot (aux raw selector padding scratch count word output))\n/-- Original N/raw assignment and physical descriptor fields ONLY. No root,\nmodulus, input/output word, vector, guard or expected verdict is initially supplied. -/\ndef initial (bits raw stride frequency : List Bool) (inverse : Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,store (R.input bits)\n    (I.initial [] ⟨[],stride,frequency,[]⟩ [] []).data raw [inverse] [] [] [] [] [],[]⟩\n/-- Whole real dot-component role embedding is injective despite shared modulus. -/\ntheorem dot_injective : Function.Injective dotStack := by\n  intro i j h;exact Sum.inl_injective (Sum.inr_injective h)\n/-- Every actual copy's roles are physically disjoint. -/\ntheorem copy_injective (site : Fin 5) : Function.Injective (copyStack site) := by fin_cases site <;> decide\n/-- Full output read has five distinct physical roles. -/\ntheorem block_injective : Function.Injective blockStack := by decide\n/-- Numeric equality has four distinct physical roles. -/\ntheorem equal_injective : Function.Injective equalStack := by decide\n/-- One fixed whole scale machine, with descriptor inputs explicitly physical. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine\n  (.inl (.inl (SemiprimeD1BinaryPublicAcquisition.digitStack (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input))))\n  (auxRole .output) .start program\n/-- Every stack alphabet is finite before N, j/k and the assignment. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) := SemiprimeD1StackCalls.all_alphabets_finite _ _ Label.start program\n/-- Control contains finite flags only, never native N/words/expressions/counts. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackCalls.control_finite _ _ Label.start program\n/-- Every physical data role, including private unused shadows, is counted. -/\ntheorem stack_card : Fintype.card Stack=160 := by decide\nend RiemannGaussian.SemiprimeD1StackPublicScale\n","RiemannGaussian.SemiprimeD1StackPublicScaleInputs":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicScaleState\nimport RiemannGaussian.SemiprimeD1StackPublicScaleMeaning\nimport RiemannGaussian.SemiprimeD1StackRootSourceOriginal\n/-! # Derived original scale source and input-vector interfaces -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackPublicScaleInputs\nopen SemiprimeD1StackPublicScale SemiprimeD1StackPublicScaleState\nopen SemiprimeMacroEntryBitPrimitives SemiprimeBitArithmetic SemiprimeMacroParameters\n/-- Equal-width literal Boolean representations are determined by integer value. -/\ntheorem words_eq {xs ys : List Bool} (hl : xs.length=ys.length) (hv : bitValue xs=bitValue ys) : xs=ys := by\n  induction xs generalizing ys with\n  | nil=>cases ys <;> simp_all\n  | cons b xs ih=>\n    cases ys with\n    | nil=>simp at hl\n    | cons c ys=>\n      have ht : xs.length=ys.length := by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hl\n      cases b <;> cases c <;> simp only [bitValue,bitNat,Bool.false_eq_true,ite_false,ite_true] at hv\n      · exact congrArg (List.cons false) (ih ht (by omega))\n      · omega\n      · omega\n      · exact congrArg (List.cons true) (ih ht (by omega))\n/-- Physical selector representation of the original transform direction.\nBoth forward sides use the same literal root as the original checker. -/\ndef transform (inverse : Bool) : SemiprimeMacroGraph.Transform := if inverse then .inr () else .inl 0\n/-- Computable expression specification of the actually acquired root code. -/\ndef expression (bits : List Bool) (inverse : Bool) : Expr :=\n  if inverse then powerExpr SemiprimeMacroEntryBitCheck.fourExpr (transformLength bits.length-1)\n  else SemiprimeMacroEntryBitCheck.fourExpr\n/-- Actual source bytes agree with their computable original expression for ALL\nbinary inputs; no prepared AST/source is an executing argument. -/\ntheorem source_code (bits : List Bool) (inverse : Bool) :\n    baseCode bits inverse=SemiprimeD1StackExprCodec.encode (expression bits inverse) [] := by\n  cases inverse\n  · rfl\n  · change SemiprimeD1StackExprPowerSpec.result _\n      (SemiprimeD1StackExprCodec.encode SemiprimeMacroEntryBitCheck.fourExpr []) []=_\n    rw [SemiprimeD1StackExprPowerSpec.result_original]\n    have hp:=(SemiprimeD1StackRootSourceOriginal.marker_lengths bits).1\n    change (SemiprimeD1StackRootSourceExecution.rootMarkers\n      (SemiprimeD1BinaryPublicAcquisitionComponents.result bits)).length=transformLength bits.length-1 at hp\n    rw [hp]\n    rfl\n/-- Original geometry identifies the acquired expression with the exact old root. -/\ntheorem expression_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (inverse : Bool) :\n    expression bits inverse=SemiprimeMacroEntryBitCheck.rootExpr\n      (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (transform inverse) := by\n  have hp:=(SemiprimeD1StackRootSourceOriginal.original_parameters bits hc hN).1\n  cases inverse\n  · rfl\n  · simp only [expression,transform,ite_true,SemiprimeMacroEntryBitCheck.rootExpr,hp]\n/-- Actual root-source bytes are exactly the ORIGINAL selected expression bytes. -/\ntheorem original_code (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (inverse : Bool) :\n    baseCode bits inverse=SemiprimeD1StackExprCodec.encode\n      (SemiprimeMacroEntryBitCheck.rootExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (transform inverse)) [] := by\n  cases inverse\n  · exact SemiprimeD1StackRootSourceOriginal.forward_root bits hN 0\n  · exact SemiprimeD1StackRootSourceOriginal.inverse_root bits hc hN\n/-- Acquired original M has EXACT old physical modulus bytes, not just a supplied\nring interpretation. The equality follows from actual width and value proofs. -/\ntheorem original_modulus (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    cached bits=SemiprimeMacroEntryBitCheck.modulus (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) := by\n  let p:=SemiprimePublicFactorCount.publicConfig (bitValue bits) hN\n  have hp:=(SemiprimeD1StackRootSourceOriginal.original_parameters bits hc hN).1\n  apply words_eq\n  · change (SemiprimeD1StackRootSourceOriginal.actualCache bits R.modulusKey).length=_\n    rw [SemiprimeD1StackRootSourceOriginal.modulus_length,SemiprimeMacroEntryBitCheck.modulus_length,hp]\n  · change bitValue (SemiprimeD1StackFermatWords.modulusWord (transformLength bits.length))=_\n    rw [SemiprimeD1StackFermatWords.modulus_value _ (by unfold transformLength;positivity),\n      SemiprimeMacroEntryBitCheck.modulus_value,hp,(SemiprimePublicFactorCount.publicConfig _ hN).shape]\n/-- Original positivity and base validity are derived from the ACTUAL original\nacquisition. They are not canonicality, modulus or whole-source advice inputs. -/\ntheorem original_valid (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) (inverse : Bool) :\n    1<bitValue (cached bits) ∧ Valid (cached bits)\n      (SemiprimeMacroEntryBitCheck.rootExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (transform inverse)) := by\n  rw [original_modulus bits hc hN]\n  exact ⟨by have h:=SemiprimeMacroEntryBitCheck.modulus_gt_four (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN);omega,\n    SemiprimeMacroEntryBitCheck.rootExpr_valid _ _⟩\n/-- Fitting a complete front returns exactly those original literal bytes. -/\ntheorem block_prefix (cached front raw : List Bool) (hl : front.length=cached.length) :\n    SemiprimeD1StackWordBlockExecution.result (front++raw) cached=front := by\n  induction cached generalizing front with\n  | nil=>cases front <;> simp_all [SemiprimeD1StackWordBlockExecution.result,SemiprimeBitDivision.fitBits]\n  | cons b cached ih=>\n    cases front with\n    | nil=>simp at hl\n    | cons c front=>\n      rw [List.cons_append,SemiprimeD1StackWordBlockExecution.fit_cons]\n      simp only [List.head?_cons,Option.getD_some,List.tail_cons]\n      rw [ih front (by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hl)]\n/-- The ACTUALLY ACQUIRED two-word vector is literal zero/input in that order;\nmissing source cells remain physically false-padded, not ignored. -/\ntheorem acquired_words (bits raw : List Bool) :\n    SemiprimeD1StackInputDotExecution.words (paddedRaw bits raw)\n      ⟨[],[],[],[true,true]⟩ (cached bits)=\n      [SemiprimeD1StackPublicScaleMeaning.zeroWord (cached bits),SemiprimeD1StackWordBlockExecution.result raw (cached bits)] := by\n  have h0:=block_prefix (cached bits) (List.replicate (cached bits).length false) raw (by simp)\n  have hd : (paddedRaw bits raw).drop (cached bits).length=raw := by\n    simp [paddedRaw]\n  change [SemiprimeD1StackWordBlockExecution.result (paddedRaw bits raw) (cached bits),\n    SemiprimeD1StackWordBlockExecution.result ((paddedRaw bits raw).drop (cached bits).length) (cached bits)]=_\n  change SemiprimeD1StackWordBlockExecution.result (paddedRaw bits raw) (cached bits)=\n    SemiprimeD1StackPublicScaleMeaning.zeroWord (cached bits) at h0\n  rw [h0,hd]\nend RiemannGaussian.SemiprimeD1StackPublicScaleInputs\n","RiemannGaussian.SemiprimeD1StackPublicScaleTableBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicScaleTableExecution\n/-! # Concrete scale-family whole bit clock and full332-role prefix cells -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicScaleTableBounds\nopen SemiprimeD1StackPublicScaleTable SemiprimeD1StackPublicScaleTableTrace\nopen SemiprimeD1StackPublicScaleTableExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace S\nexport SemiprimeD1StackStaticTableSpec (inputBytes)\nend S\n/-- Only original input/j/k/selector bytes populate the actual160-role template bank. -/\ntheorem template_bytes (bits stride frequency : List Bool) (inverse : Bool) :\n    S.inputBytes (inputTemplate bits stride frequency inverse)≤160*(bits.length+stride.length+frequency.length+1) := by\n  change (∑k:P.Stack,(inputTemplate bits stride frequency inverse k).length)≤_\n  calc\n    _≤∑_k:P.Stack,(bits.length+stride.length+frequency.length+1):=Finset.sum_le_sum (fun k _=>template_cell_le bits stride frequency inverse k)\n    _= _:=by simp only [Finset.sum_const,Finset.card_univ,SemiprimeD1StackPublicScale.stack_card,smul_eq_mul]\n/-- Honest actual original input inventory; scope IDs and padding are fully paid. -/\ndef inventory (bits stride frequency : List Bool) (words : List (List Bool)) : Nat :=\n  bits.length+stride.length+frequency.length+(vectorBits words).length+2\n/-- One fixed whole-source polynomial per actually materialized scalar leaf. -/\ndef runBound (bits stride frequency : List Bool) (words : List (List Bool)) : Nat :=\n  10^80*(inventory bits stride frequency words)^16*2^words.length\n/-- Fixed natural arithmetic for the160-role source; the lemma keeps the\nkernel's closed role inventory separate from polynomial normalization. -/\ntheorem arithmetic_weight_bound (T n B scope I : Nat)\n    (hT:T≤160*I^16) (hn:n≤I^16) (hB:B≤10^70*I^16) (hs:scope≤I^16) (hOne:1≤I^16) :\n    11*scope+(160*(6*T+5)+7*n+B+160*(160*(T+n+B)+1)+20+20)+30≤\n      10^80*I^16 := by omega\n/-- Own complete scale-family bit time is polynomial in actual supplied input\nBYTES times2^physicallyCountedArity. The native checker report is never substituted. -/\ntheorem timeBound_le (bits stride frequency : List Bool) (inverse : Bool) (words : List (List Bool)) :\n    timeBound bits stride frequency inverse words≤ runBound bits stride frequency words := by\n  let I:=inventory bits stride frequency words\n  have hI:1≤ I:=by dsimp [I,inventory];omega\n  have hI2:I≤ I^16:=by simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1≤16)\n  have hn:=SemiprimeD1StackStaticTableBounds.scope_count_le words\n  have hRaw:bits.length+words.length+stride.length+frequency.length+2≤ I:=by dsimp [I,inventory];omega\n  have hbudget:budget bits stride frequency words.length≤10^70*I^16:=\n    Nat.mul_le_mul_left _ (Nat.pow_le_pow_left hRaw 16)\n  have hT:=template_bytes bits stride frequency inverse\n  have hT2:S.inputBytes (inputTemplate bits stride frequency inverse)≤160*I^16:=\n    hT.trans (Nat.mul_le_mul_left _ (by dsimp [I,inventory] at *;omega))\n  have hn2:words.length≤ I^16:=by dsimp [I,inventory] at *;omega\n  have hb2:(vectorBits words).length≤ I^16:=by dsimp [I,inventory] at *;omega\n  have hOne:1≤I^16:=by omega\n  have hw:=arithmetic_weight_bound (S.inputBytes (inputTemplate bits stride frequency inverse)) words.length\n    (budget bits stride frequency words.length) (vectorBits words).length I hT2 hn2 hbudget hb2 hOne\n  unfold timeBound SemiprimeD1StackStaticTableBounds.runBound\n    SemiprimeD1StackStaticTableDFS.weight SemiprimeD1StackStaticTableLeaf.leafBound\n  have hroles:static.roles.length=160:=roles_length\n  rw [SemiprimeD1StackPublicScale.stack_card,hroles]\n  exact Nat.mul_le_mul_right (2^words.length) hw\n/-- Full actual original-N/index/scope execution with the closed same-source clock. -/\ntheorem source_run_bounded (bits stride frequency : List Bool) (inverse : Bool) (hj : stride=SemiprimeD1StackUnaryDivmod.unary stride.length)\n    (hk : frequency=SemiprimeD1StackUnaryDivmod.unary frequency.length)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) (words : List (List Bool)) :\n    ∃t≤ runBound bits stride frequency words,SemiprimeD1StackCalls.run program t\n      (initial bits stride frequency inverse (vectorBits words))=some (done bits stride frequency inverse words) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits stride frequency inverse hj hk hc hN words\n  exact ⟨t,ht.trans (timeBound_le bits stride frequency inverse words),hr⟩\n/-- The genuine fixed332-role finite machine, with the same complete source clock. -/\nnoncomputable def machineTable (bits stride frequency : List Bool) (inverse : Bool) (hj : stride=SemiprimeD1StackUnaryDivmod.unary stride.length)\n    (hk : frequency=SemiprimeD1StackUnaryDivmod.unary frequency.length)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) (words : List (List Bool)) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits stride frequency inverse (vectorBits words)))\n      (some (SemiprimeD1StackCalls.configuration (done bits stride frequency inverse words))) (runBound bits stride frequency words) := by\n  let h:=tableInTime bits stride frequency inverse hj hk hc hN words\n  exact ⟨h.toEvalsTo,h.steps_le_m.trans (timeBound_le bits stride frequency inverse words)⟩\n/-- All332 source roles and every actual nested return cell at EVERY prefix. -/\ntheorem prefix_cells (bits stride frequency : List Bool) (inverse : Bool) (hj : stride=SemiprimeD1StackUnaryDivmod.unary stride.length)\n    (hk : frequency=SemiprimeD1StackUnaryDivmod.unary frequency.length)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) (words : List (List Bool))\n    (fuel : Nat) (finish : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial bits stride frequency inverse (vectorBits words))=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n      333*(160*(bits.length+stride.length+frequency.length+1)+(vectorBits words).length+runBound bits stride frequency words+1) := by\n  have hs:=SemiprimeD1StackStaticTableBounds.prefix_cells static (inputTemplate bits stride frequency inverse)\n    (template_raw bits stride frequency inverse) (answer bits stride frequency inverse) (budget bits stride frequency)\n    (actual_trace bits stride frequency inverse hj hk hc hN) words fuel finish hr\n  rw [SemiprimeD1StackPublicScale.stack_card] at hs\n  change (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n    333*(S.inputBytes (inputTemplate bits stride frequency inverse)+(vectorBits words).length+timeBound bits stride frequency inverse words+1) at hs\n  have hT:=template_bytes bits stride frequency inverse\n  have ht:=timeBound_le bits stride frequency inverse words\n  change timeBound bits stride frequency inverse words≤_ at ht\n  omega\n/-- Same full332-role and actual-return prefix certificate on the ACTUAL compiled machine. -/\ntheorem machine_prefix_cells (bits stride frequency : List Bool) (inverse : Bool) (hj : stride=SemiprimeD1StackUnaryDivmod.unary stride.length)\n    (hk : frequency=SemiprimeD1StackUnaryDivmod.unary frequency.length)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) (words : List (List Bool))\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits stride frequency inverse (vectorBits words))))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      333*(160*(bits.length+stride.length+frequency.length+1)+(vectorBits words).length+runBound bits stride frequency words+1) := by\n  have hs:=SemiprimeD1StackStaticTableBounds.machine_prefix_cells static (inputTemplate bits stride frequency inverse)\n    (template_raw bits stride frequency inverse) (answer bits stride frequency inverse) (budget bits stride frequency)\n    (actual_trace bits stride frequency inverse hj hk hc hN) words fuel cfg hr\n  rw [SemiprimeD1StackPublicScale.stack_card] at hs\n  change (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n    333*(S.inputBytes (inputTemplate bits stride frequency inverse)+(vectorBits words).length+timeBound bits stride frequency inverse words+1) at hs\n  have hT:=template_bytes bits stride frequency inverse\n  have ht:=timeBound_le bits stride frequency inverse words\n  change timeBound bits stride frequency inverse words≤_ at ht\n  omega\nend RiemannGaussian.SemiprimeD1StackPublicScaleTableBounds\n","RiemannGaussian.SemiprimeD1StackRationalOperationRaw":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalOperationSetup\nimport RiemannGaussian.SemiprimeD1StackRationalOperationProduct\nimport RiemannGaussian.SemiprimeD1StackRationalOperationAdd\n/-! # Whole literal raw rational add/multiply/negate/invert acquisition -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalOperationRaw\nopen SemiprimeD1StackRationalOperation SemiprimeD1StackRationalOperationEncoding\nopen SemiprimeD1StackRationalOperationCalls SemiprimeD1StackRationalOperationSetup\nopen SemiprimeD1StackRationalOperationProduct SemiprimeD1StackRationalOperationAdd\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (mulBits)\n/-- Proof-side exact raw output; no such object is a runtime operand or instruction. -/\ndef rawWord (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd:List Bool) :SemiprimeRationalBits.RationalWord:=\n  match op with\n  | .add=>⟨(SemiprimeBitIndexClipping.addSignedBits ⟨sx,(mulBits xn yd).bits⟩ ⟨sy,(mulBits yn xd).bits⟩).word,(mulBits xd yd).bits⟩\n  | .mul=>⟨⟨Bool.xor sx sy,(mulBits xn yn).bits⟩,(mulBits xd yd).bits⟩\n  | .neg=>⟨⟨!sx,xn⟩,xd⟩ | .inv=>⟨⟨sx,xd⟩,xn⟩\n/-- Every raw byte agrees with legacy operation orientation/sign/padding, including signed cancellation zeros. -/\ntheorem rawWord_legacy (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd:List Bool) :\n    rawWord op sx xn xd sy yn yd=(SemiprimeRationalBits.rawOperation (operation op) ⟨⟨sx,xn⟩,xd⟩ ⟨⟨sy,yn⟩,yd⟩).word:=by\n  cases op <;> simp only [rawWord,operation,SemiprimeRationalBits.rawOperation,SemiprimeRationalBits.rawAddBits,\n    SemiprimeRationalBits.rawMulBits,SemiprimeRationalBits.rawNegBits,SemiprimeRationalBits.rawInvBits,\n    SemiprimeBitIndexClipping.mulSignedBits,SemiprimeBitIndexClipping.negateWord,Bool.xor_false]\n/-- Whole acquired raw bank retains original inputs/magnitudes and actual cross-products until the following paid drains. -/\ndef rawResult (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :Words:=\n  let raw:=rawWord op sx xn xd sy yn yd\n  {ready op sx xn xd sy yn yd template with\n    originalSigned:=raw.numerator.negative::raw.numerator.magnitude,originalRight:=raw.denominator,\n    originalLeft:=if op=.add then (mulBits xn yd).bits else [],\n    output:=if op=.add then (mulBits yn xd).bits else []}\n/-- Exact elapsed raw stage clock comes only from the actual calls, actual sign push and actual drains. -/\ndef rawTime (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd:List Bool) :Nat:=match op with\n  | .add=>productTime xn yd+productTime yn xd+\n      sumTime sx (mulBits xn yd).bits sy (mulBits yn xd).bits+1+productTime xd yd\n  | .mul=>productTime xn yn+1+productTime xd yd\n  | .neg=>(5*xn.length+4)+(5*xd.length+4)+1\n  | .inv=>(5*xd.length+4)+(5*xn.length+4)+1\n/-- Actual add computes both oriented cross-products, borrow-driven signed sum and exact denominator product. -/\ntheorem add_run (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    Runs program (rawTime .add sx xn xd sy yn yd) (localLabel .dispatch .add sx sy)\n      (bank (ready .add sx xn xd sy yn yd template)) (localLabel .clearMagnitudeLeft .add sx sy)\n      (bank (rawResult .add sx xn xd sy yn yd template)):=by\n  let w0:=ready .add sx xn xd sy yn yd template\n  let w1:Words:={w0 with originalLeft:=(mulBits xn yd).bits}\n  let w2:Words:={w1 with output:=(mulBits yn xd).bits}\n  let sum:SemiprimeBitIndexClipping.SignedWord:=\n    (SemiprimeBitIndexClipping.addSignedBits ⟨sx,(mulBits xn yd).bits⟩ ⟨sy,(mulBits yn xd).bits⟩).word\n  let w3:Words:={w2 with originalSigned:=sum.magnitude}\n  let w4:Words:={w3 with originalSigned:=sum.negative::sum.magnitude}\n  have h0:=product_run .crossLeft .add sx sy w0 (localLabel .dispatch .add sx sy) rfl rfl rfl\n  change Runs program (productTime xn yd) _ (bank w0) _ (bank w1) at h0\n  have h1:=product_run .crossRight .add sx sy w1 (localLabel (.productLeft .crossRight) .add sx sy) rfl rfl rfl\n  change Runs program (productTime yn xd) _ (bank w1) _ (bank w2) at h1\n  have h2:=sum_run .add sx sy w2 rfl rfl\n  change Runs program (sumTime sx (mulBits xn yd).bits sy (mulBits yn xd).bits) _ (bank w2) _ (bank w3) at h2\n  have h3:=P.push_run (localLabel (.rawSign sum.negative) .add sx sy) (localLabel (.productLeft .denominator) .add sx sy)\n    rawSigned sum.negative (bank w3) rfl\n  change Runs _ _ _ _ _ (Function.update (bank w3) (normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)) (sum.negative::sum.magnitude)) at h3\n  rw [update_originalSigned] at h3\n  have h4:=product_run .denominator .add sx sy w4 (localLabel (.productLeft .denominator) .add sx sy) rfl rfl rfl\n  change Runs program (productTime xd yd) _ (bank w4) _ (bank (rawResult .add sx xn xd sy yn yd template)) at h4\n  exact P.join (P.join (P.join (P.join h0 h1) h2) h3) h4\n/-- Actual multiply computes both oriented full products and pushes the XOR of the two parsed signs. -/\ntheorem mul_run (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    Runs program (rawTime .mul sx xn xd sy yn yd) (localLabel .dispatch .mul sx sy)\n      (bank (ready .mul sx xn xd sy yn yd template)) (localLabel .clearMagnitudeLeft .mul sx sy)\n      (bank (rawResult .mul sx xn xd sy yn yd template)):=by\n  let w0:=ready .mul sx xn xd sy yn yd template\n  let w1:Words:={w0 with originalSigned:=(mulBits xn yn).bits}\n  let w2:Words:={w1 with originalSigned:=(Bool.xor sx sy)::(mulBits xn yn).bits}\n  have h0:=product_run .numerator .mul sx sy w0 (localLabel .dispatch .mul sx sy) rfl rfl rfl\n  change Runs program (productTime xn yn) _ (bank w0) _ (bank w1) at h0\n  have h1:=P.push_run (localLabel (.rawSign (Bool.xor sx sy)) .mul sx sy) (localLabel (.productLeft .denominator) .mul sx sy)\n    rawSigned (Bool.xor sx sy) (bank w1) rfl\n  change Runs _ _ _ _ _ (Function.update (bank w1) (normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)) ((Bool.xor sx sy)::(mulBits xn yn).bits)) at h1\n  rw [update_originalSigned] at h1\n  have h2:=product_run .denominator .mul sx sy w2 (localLabel (.productLeft .denominator) .mul sx sy) rfl rfl rfl\n  change Runs program (productTime xd yd) _ (bank w2) _ (bank (rawResult .mul sx xn xd sy yn yd template)) at h2\n  exact P.join (P.join h0 h1) h2\n/-- Actual unary operation copies the physical magnitude/denominator in the selected swap orientation. -/\ntheorem unary_run (inv:Bool) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    let op:=if inv then Op.inv else .neg\n    Runs program (rawTime op sx xn xd sy yn yd) (localLabel .dispatch op sx false)\n      (bank (ready op sx xn xd sy yn yd template)) (localLabel .clearMagnitudeLeft op sx false)\n      (bank (rawResult op sx xn xd sy yn yd template)):=by\n  dsimp only\n  let op:=if inv then Op.inv else .neg\n  let num:=if inv then xd else xn\n  let den:=if inv then xn else xd\n  let neg:=if inv then sx else !sx\n  let w0:=ready op sx xn xd sy yn yd template\n  let w1:Words:={w0 with originalSigned:=num}\n  let w2:Words:={w1 with originalRight:=den}\n  have hc0:program (localLabel .dispatch op sx false)=.call (.copier (.unaryNumerator inv) 0) (localLabel .unaryDenominator op sx false):=by cases inv <;> rfl\n  have hx:bank w0 (copyStack (.unaryNumerator inv) 0)=num:=by cases inv <;> rfl\n  have h0:=P.copy_call (.unaryNumerator inv) (localLabel .dispatch op sx false) (localLabel .unaryDenominator op sx false)\n    hc0 (bank w0) num [] hx rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank w0) (normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)) (num++[])) at h0\n  rw [List.append_nil,update_originalSigned] at h0\n  have hc1:program (localLabel .unaryDenominator op sx false)=.call (.copier (.unaryDenominator inv) 0) (localLabel (.rawSign neg) op sx false):=by cases inv <;> rfl\n  have hy:bank w1 (copyStack (.unaryDenominator inv) 0)=den:=by cases inv <;> rfl\n  have h1:=P.copy_call (.unaryDenominator inv) (localLabel .unaryDenominator op sx false) (localLabel (.rawSign neg) op sx false)\n    hc1 (bank w1) den [] hy rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank w1) (normalizeStack SemiprimeD1StackRationalNormalize.denominator) (den++[])) at h1\n  rw [List.append_nil,update_originalRight] at h1\n  have hc2:program (localLabel (.rawSign neg) op sx false)=.base (.push rawSigned neg (localLabel .clearMagnitudeLeft op sx false)):=by cases inv <;> rfl\n  have h2:=P.push_run (localLabel (.rawSign neg) op sx false) (localLabel .clearMagnitudeLeft op sx false) rawSigned neg (bank w2) hc2\n  change Runs _ _ _ _ _ (Function.update (bank w2) (normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)) (neg::num)) at h2\n  rw [update_originalSigned] at h2\n  have h:=P.join (P.join h0 h1) h2\n  cases inv <;> exact h\n/-- One fixed actual raw-operation stage, with no raw-answer/evaluator operand. -/\ntheorem raw_run (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    Runs program (rawTime op sx xn xd sy yn yd)\n      (localLabel .dispatch op sx (if binary op then sy else false))\n      (bank (ready op sx xn xd sy yn yd template))\n      (localLabel .clearMagnitudeLeft op sx (if binary op then sy else false))\n      (bank (rawResult op sx xn xd sy yn yd template)):=by\n  cases op with\n  | add=>exact add_run sx xn xd sy yn yd template\n  | mul=>exact mul_run sx xn xd sy yn yd template\n  | neg=>exact unary_run false sx xn xd sy yn yd template\n  | inv=>exact unary_run true sx xn xd sy yn yd template\nend RiemannGaussian.SemiprimeD1StackRationalOperationRaw\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineArrayMove":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffinePrimitives\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineView\n/-! # Actual old-array drain and two paid reversals move the complete next array -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineArrayMove\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView SemiprimeD1StackProcedureTrace\nnamespace T\nexport SemiprimeD1StackRecoveryAffinePrimitives (join drain_loop reverse_call)\nend T\n/-- Exactly two actual added array words change; every original104 word is restored. -/\ndef result (w:Words) (bytes:List Bool):Words:=\n  {w with added:=Function.update (Function.update w.added .array bytes) .nextArray []}\n/-- Every old byte, both real reversal EOF/caller returns and all new bytes are paid. -/\ndef runBound (old bytes:List Bool):Nat:=old.length+4*bytes.length+7\n/-- No host append/move replaces actual I/O: the fixed source drains old then executes both real reversals. -/\ntheorem source_run (w:Words) (old bytes:List Bool)\n    (ho:w.added .array=old) (hn:w.added .nextArray=bytes) (hc:w.auxiliary .copyScratch=[]):\n    Runs program (runBound old bytes) (.local .clearArray) (bank w)\n      (.local (.clearSlope true false)) (bank (result w bytes)):=by\n  let w0:Words:={w with added:=Function.update w.added .array []}\n  let w1:Words:={w0 with added:=Function.update w0.added .nextArray []}\n  let w2:Words:={w1 with auxiliary:=Function.update w1.auxiliary .copyScratch bytes.reverse}\n  let w3:Words:={w2 with auxiliary:=Function.update w2.auxiliary .copyScratch []}\n  have h0:=T.drain_loop (.local .clearArray) (.local (.move false)) (aux .array) rfl (bank w) old ho\n  rw [update_added] at h0\n  change Runs program _ _ _ _ (bank w0) at h0\n  have h1:=T.reverse_call false (.local (.move false)) (.local (.move true)) rfl (bank w0) bytes [] hn hc\n  change Runs program _ _ _ _ (Function.update (Function.update (bank w0) (aux .nextArray) [])\n    (oldAux .copyScratch) (bytes.reverse++[])) at h1\n  rw [List.append_nil,update_added,update_oldAux] at h1\n  change Runs program _ _ _ _ (bank w2) at h1\n  have hsource:bank w2 (reverseStack true 0)=bytes.reverse:=by\n    change Function.update w1.auxiliary .copyScratch bytes.reverse .copyScratch=bytes.reverse\n    exact Function.update_self _ _ _\n  have hdest:bank w2 (reverseStack true 1)=[]:=by\n    change Function.update (Function.update w.added .array []) .nextArray [] .array=[]\n    simp only [Function.update_of_ne (show Aux.array≠.nextArray from by decide),Function.update_self]\n  have h2:=T.reverse_call true (.local (.move true)) (.local (.clearSlope true false)) rfl (bank w2) bytes.reverse []\n    hsource hdest\n  change Runs program _ _ _ _ (Function.update (Function.update (bank w2) (oldAux .copyScratch) [])\n    (aux .array) (bytes.reverse.reverse++[])) at h2\n  rw [List.reverse_reverse,List.append_nil,update_oldAux,update_added] at h2\n  have hclear:Function.update w.auxiliary .copyScratch []=w.auxiliary:=by rw [←hc,Function.update_eq_self]\n  have he:{w3 with added:=Function.update w3.added .array bytes}=result w bytes:=by\n    dsimp only [w3,w2,w1,w0,result]\n    simp only [Function.update_idem,hclear]\n    congr 1\n    funext slot\n    cases slot <;> simp\n  change Runs program _ _ _ _ (bank {w3 with added:=Function.update w3.added .array bytes}) at h2\n  rw [he] at h2\n  have h:=T.join (T.join h0 h1) h2\n  convert h using 1\n  simp only [runBound,List.length_reverse]\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineArrayMove\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineConvolution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffinePairMeaning\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineReadLoop\n/-! # Exact descending evaluation of the original ordered raw-byte convolution -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineConvolution\nopen SemiprimeD1StackRecoveryAffine\nopen SemiprimeRationalBits (RationalWord)\nopen SemiprimeD1StackRecoveryAffinePairMeaning (step)\n/-- Proof interpretation of the same descending finite-class/current-k physical loop. -/\ndef descend (width:List Bool) (xs:List RationalWord) (c:RationalWord) (part:Part):Nat→RationalWord→RationalWord\n  | 0,suffix=>step width (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs 0)\n      (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix\n  | n+1,suffix=>descend width xs c (nextPart part) n\n      (step width (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs (n+1))\n        (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix)\n/-- Every ordered pair is retained, including factor-zero extensions and diagonal terms. -/\ndef pairs (xs:List RationalWord) (c:RationalWord) (part:Part):Nat→List (RationalWord×RationalWord)\n  | 0=>[(SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs 0,SemiprimeD1StackRecoveryAffineFactor.value part c)]\n  | n+1=>pairs xs c (nextPart part) n++\n      [(SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs (n+1),SemiprimeD1StackRecoveryAffineFactor.value part c)]\n/-- The descending actual fold computes the exact ascending-pair right fold, with no omitted zero operations. -/\ntheorem descend_fold (width:List Bool) (xs:List RationalWord) (c:RationalWord) (part:Part) (n:Nat) (suffix:RationalWord):\n    descend width xs c part n suffix=\n      (pairs xs c part n).foldr (fun p tail=>step width p.1 p.2 tail) suffix:=by\n  induction n generalizing part suffix with\n  | zero=>rfl\n  | succ n ih=>\n    simp only [descend,pairs,List.foldr_append,List.foldr_cons,List.foldr_nil]\n    exact ih (nextPart part) _\n/-- Native dot recursion retains exactly the same product-FIRST/suffix-SECOND byte operations. -/\ntheorem dot_fold (width:List Bool) (ps:List (RationalWord×RationalWord)):\n    (SemiprimeDotBits.dotBits width ps).word=\n      ps.foldr (fun p tail=>step width p.1 p.2 tail) SemiprimeRationalBits.zeroWord:=by\n  induction ps with\n  | nil=>rfl\n  | cons p ps ih=>\n    change step width p.1 p.2 (SemiprimeDotBits.dotBits width ps).word=_\n    rw [ih]\n    rfl\n/-- Exact bytes, rather than only rational values, agree with the authoritative native dot. -/\ntheorem descend_dot (width:List Bool) (xs:List RationalWord) (c:RationalWord) (part:Part) (n:Nat):\n    descend width xs c part n SemiprimeRationalBits.zeroWord=\n      (SemiprimeDotBits.dotBits width (pairs xs c part n)).word:=by\n  rw [descend_fold,dot_fold]\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineConvolution\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerStep":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineArrayRead\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffinePairMeaning\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineCache\n/-! # One complete actual coefficient-read/factor/product/sum/cleanup iteration -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerStep\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\nopen SemiprimeD1StackRecoveryAffineRegisters SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryAffineReadCount (unary)\nopen SemiprimeD1StackRecoveryAffineOperationInput (emptyRational)\n/-- The actual loader writes suffix, reached coefficient, then finite-class factor into distinct physical roles. -/\ndef acquired (w:Words) (x y suffix:SemiprimeRationalBits.RationalWord):Words:=\n  putReg (putReg (putReg w .denPower suffix) .numBase x) .denBase y\n/-- All actual loader writes commute only because their physical role pairs are disjoint. -/\ntheorem acquired_eq (w:Words) (x y suffix:SemiprimeRationalBits.RationalWord):\n    acquired w x y suffix=SemiprimeD1StackRecoveryAffinePairMeaning.loaded w x y suffix:=by\n  unfold acquired SemiprimeD1StackRecoveryAffinePairMeaning.loaded\n  rw [SemiprimeD1StackRecoveryAffineCache.putReg_comm w .denPower .numBase suffix x (by decide),\n    SemiprimeD1StackRecoveryAffineCache.putReg_comm (putReg w .numBase x) .denPower .denBase suffix y (by decide)]\n/-- Own clocks of both real source acquisitions and the complete actual scalar pair. -/\ndef runBound (part:Part) (w:Words) (xs:List SemiprimeRationalBits.RationalWord) (n:Nat)\n    (c suffix:SemiprimeRationalBits.RationalWord) (width:List Bool):Nat:=\n  SemiprimeD1StackRecoveryAffineArrayRead.runBound xs n+\n    SemiprimeD1StackRecoveryAffineFactor.runBound part c+\n    SemiprimeD1StackRecoveryAffinePair.runBound\n      (acquired w (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs n) (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix) width\n/-- Whole actual iteration executes all zero terms and restores every transient field before its real k pop. -/\ntheorem source_run (part:Part) (w:Words) (xs:List SemiprimeRationalBits.RationalWord) (n:Nat)\n    (c suffix:SemiprimeRationalBits.RationalWord) (width:List Bool)\n    (ha:w.added .array=vector xs) (hk:w.added .k=unary n)\n    (hrd:w.added .reader=[]) (ht:w.added .readTodo=[])\n    (hx:∀b,w.registers (.numBase,b)=[]) (hy:∀b,w.registers (.denBase,b)=[]) (hp:∀b,w.registers (.numPower,b)=[])\n    (hc:w.auxiliary .copyScratch=[]) (hf:w.auxiliary .frameScratch=[]) (hv:w.auxiliary .scan=[])\n    (hr:w.rational=emptyRational width)\n    (hs:w.registers (.slope,false)=signed c) (hd:w.registers (.slope,true)=c.denominator):\n    ∃q≤runBound part w xs n c suffix width,Runs program q (.local (.inner part)) (bank (putReg w .denPower suffix))\n      (.local (.innerNext part))\n      (bank (putReg w .denPower (SemiprimeD1StackRecoveryAffinePairMeaning.step width\n        (SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs n) (SemiprimeD1StackRecoveryAffineFactor.value part c) suffix))):=by\n  let x:=SemiprimeD1StackRecoveryAffineReadLoop.wordAt xs n\n  let y:=SemiprimeD1StackRecoveryAffineFactor.value part c\n  let base:=putReg w .denPower suffix\n  let first:=putReg base .numBase x\n  let second:=putReg first .denBase y\n  have hbase:∀b,base.registers (.numBase,b)=[]:=by\n    intro b\n    rw [putReg_other w .denPower .numBase suffix b (by decide)]\n    exact hx b\n  have h0:=SemiprimeD1StackRecoveryAffineArrayRead.source_run part base xs n ha hk hrd ht (hbase false) (hbase true) hc hf hv\n  have hden:∀b,first.registers (.denBase,b)=[]:=by\n    intro b\n    rw [putReg_other base .numBase .denBase x b (by decide),putReg_other w .denPower .denBase suffix b (by decide)]\n    exact hy b\n  have hs':first.registers (.slope,false)=signed c:=by\n    rw [putReg_other base .numBase .slope x false (by decide),putReg_other w .denPower .slope suffix false (by decide)]\n    exact hs\n  have hd':first.registers (.slope,true)=c.denominator:=by\n    rw [putReg_other base .numBase .slope x true (by decide),putReg_other w .denPower .slope suffix true (by decide)]\n    exact hd\n  have h1:=SemiprimeD1StackRecoveryAffineFactor.factor_run part first c (hden false) (hden true) hc hs' hd'\n  have hxn:second.registers (.numBase,false)≠[]:=by\n    rw [putReg_other first .denBase .numBase y false (by decide),(putReg_fields base .numBase x).1]\n    exact List.cons_ne_nil _ _\n  have hyn:second.registers (.denBase,false)≠[]:=by\n    rw [(putReg_fields first .denBase y).1]\n    exact List.cons_ne_nil _ _\n  have han:second.registers (.denPower,false)≠[]:=by\n    rw [putReg_other first .denBase .denPower y false (by decide),putReg_other base .numBase .denPower x false (by decide),\n      (putReg_fields w .denPower suffix).1]\n    exact List.cons_ne_nil _ _\n  obtain ⟨q,hq,h2⟩:=SemiprimeD1StackRecoveryAffinePair.source_run part second width hr hc hxn hyn han\n  have he:second=SemiprimeD1StackRecoveryAffinePairMeaning.loaded w x y suffix:=acquired_eq w x y suffix\n  rw [he,SemiprimeD1StackRecoveryAffinePairMeaning.result_exact w x y suffix width hx hy hp] at h2\n  rw [←he] at h2\n  refine ⟨SemiprimeD1StackRecoveryAffineArrayRead.runBound xs n+SemiprimeD1StackRecoveryAffineFactor.runBound part c+q,\n    ?_,SemiprimeD1StackRecoveryAffinePrimitives.join (SemiprimeD1StackRecoveryAffinePrimitives.join h0 h1) h2⟩\n  exact Nat.add_le_add_left hq _\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerStep\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineResource\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopesBounds\n/-! # Fixed paid-VALUE polynomial for the SAME entire original affine-array traversal -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopClock\nopen SemiprimeD1StackRecoveryAffineView\nnamespace R\nexport SemiprimeD1StackRecoveryGridResource (resource resource_pos cacheWidth dataWidth cache_le cache_data width_cache)\nend R\nnamespace E\nexport SemiprimeD1StackRecoveryAffineEncoding (retained)\nend E\nnamespace A\nexport SemiprimeD1StackRecoveryAffineOriginalInput (slopes)\nend A\nopen SemiprimeD1StackRecoveryAffineSource (counted)\n/-- Original true geometry, complete original slopes and all physical fitted operands pay every actual nested-loop instruction. -/\ntheorem whole_le (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val):\n    SemiprimeD1StackRecoveryAffineLoop.runBound (counted a M u selected t width) width (E.retained a M u selected)\n      (A.slopes a M u selected width).reverse [SemiprimeJetBits.oneWord]≤ 10^60*(R.resource a M u t width)^10:=by\n  let r:=R.resource a M u t width\n  let B:=R.cacheWidth a width\n  let L:=R.dataWidth a M u t width\n  let q:=E.retained a M u selected\n  have hr:1≤ r:=R.resource_pos a M u t width\n  have hB:B≤ 2*r:=R.cache_le a M u t width\n  have hBL:B≤ L:=R.cache_data a M u t width\n  have hW:width.length+2≤ B:=R.width_cache a width\n  obtain ⟨hregs,hdata⟩:=SemiprimeD1StackRecoveryAffineResource.counted_caps a M u selected t width ht\n  have hq:q≤ 3*r:=SemiprimeD1StackRecoveryAffineResource.q_le a M u selected t width\n  have hqL:q≤ L:=by\n    have h:=SemiprimeD1StackRecoveryGridResource.counts_data a M u t width\n    omega\n  have hbudget:(q+1)*(4*width.length+9)+1≤ L:=SemiprimeD1StackRecoveryAffineResource.array_budget a M u selected t width\n  have hs:∀x∈(A.slopes a M u selected width).reverse,SemiprimeD1StackRecoveryAffineByteCaps.Small width x:=by\n    intro x hx\n    exact SemiprimeD1StackRecoveryAffineByteCaps.slopes_small a M u selected width x (List.mem_reverse.mp hx)\n  have hbytes:(vector (A.slopes a M u selected width).reverse).length≤ L:=by\n    rw [SemiprimeD1StackRecoveryAffineSlopesBounds.vector_reverse_length]\n    exact SemiprimeD1StackRecoveryAffineResource.slopes_bytes a M u selected t width\n  have h:=SemiprimeD1StackRecoveryAffineLoopBounds.source_le (counted a M u selected t width) width q\n    (A.slopes a M u selected width).reverse [SemiprimeJetBits.oneWord] B L hW hBL hregs hdata\n    (by intro x hx;rcases List.mem_singleton.mp hx with rfl;exact SemiprimeD1StackRecoveryAffineByteCaps.one_small width)\n    (by simp only [List.length_singleton];omega) hs hbytes hqL hbudget\n  have hlen:(A.slopes a M u selected width).length≤ 3*r^2:=SemiprimeD1StackRecoveryAffineResource.slopes_le a M u selected t width\n  have hsl:(A.slopes a M u selected width).reverse.length+1≤ 4*r^2:=by\n    rw [List.length_reverse]\n    have h1:1≤ r^2:=Nat.one_le_pow _ _ hr\n    omega\n  have hq':q+1≤ 4*r:=by omega\n  have hq2:(q+1)^2≤ 16*r^2:=by\n    have hh:=Nat.pow_le_pow_left hq' 2\n    nlinarith\n  have hB6:B^6≤ 64*r^6:=by\n    have hh:=Nat.pow_le_pow_left hB 6\n    rw [mul_pow] at hh\n    norm_num1 at hh\n    exact hh\n  have h36:r^3≤ r^6:=Nat.pow_le_pow_right hr (by decide:3≤6)\n  have h06:1≤ r^6:=Nat.one_le_pow _ _ hr\n  have hres:112*L+B^6+1≤ 10^12*r^6:=by\n    change 112*(10^9*r^3)+B^6+1≤ 10^12*r^6\n    omega\n  have hcap:SemiprimeD1StackRecoveryAffineLoopBounds.cap B L≤ 10^57*r^6:=by\n    unfold SemiprimeD1StackRecoveryAffineLoopBounds.cap\n    calc\n      _≤ 10^45*(10^12*r^6):=Nat.mul_le_mul_left _ hres\n      _=_:=by ring\n  calc\n    _≤ (4*r^2)*(16*r^2)*(10^57*r^6):=h.trans (Nat.mul_le_mul (Nat.mul_le_mul hsl hq2) hcap)\n    _≤ 10^60*r^10:=by rw [show (4*r^2)*(16*r^2)*(10^57*r^6)=64*10^57*r^10 by ring];omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopClock\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinatePrimitives\n/-! # Real binary reader call on each actual parsed block\nThe raw binary coordinate is retained. Numeric equality handles padding and\nphysical EOF bounds every scan, without any unary decoded address acquisition.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCalls\nopen SemiprimeD1StackRecoveryCoordinate SemiprimeD1StackRecoveryCoordinateState\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace X\nexport SemiprimeD1StackRecoveryEntriesIndexedExecution (source_run timeBound done result_bank)\nend X\n/-- Initial actual full12-role reader bank, derived from this21-role caller's real fields. -/\ntheorem initial_projection (key:List Bool) (w:Role→List Bool) (he:w .value=[]):\n    (data key w) ∘ indexed=(I.initial (w .cache) key).data:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k with\n    | value=>exact he\n    | cache|query|counter|reader|parser|valid|copy=>rfl\n/-- Each actual block lookup includes all12 real reader roles and its genuine call/return. -/\ntheorem index_call (key:List Bool) (w:Role→List Bool) (words:List (List Bool))\n    (hc:w .cache=vectorBits words) (he:w .value=[]):\n    Runs program (X.timeBound words key+1) (.local .lookup) (data key w) (.local .coefficientFrame)\n      (data key (Function.update w .value ((words[SemiprimeBitArithmetic.bitValue key]?).getD []))):=by\n  let answer:=(words[SemiprimeBitArithmetic.bitValue key]?).getD []\n  have hin:SemiprimeD1StackMultiplierLink.DataRel indexed (data key w)\n      (I.initial (vectorBits words) key).data (data key w):=by\n    constructor\n    · intro k\n      have h:=congrFun (initial_projection key w he) k\n      rw [hc] at h\n      exact h\n    · intro k _;rfl\n  have ho:=SemiprimeD1StackMultiplierLink.data_update indexed indexed_injective\n    (data key w) (I.initial (vectorBits words) key).data (data key w) hin (I.aux .value) answer\n  have hfinal:Function.update (I.initial (vectorBits words) key).data (I.aux .value) answer=(X.done words key).data:=\n    (X.result_bank words key).symm\n  rw [hfinal] at ho\n  change SemiprimeD1StackMultiplierLink.DataRel indexed (data key w)\n    (X.done words key).data (Function.update (data key w) (address .value) answer) at ho\n  rw [←data_update] at ho\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program indexed Label.indexed indexed_injective I.program\n    (.local .start) (fun _=>rfl) (.local .lookup) (.local .coefficientFrame) rfl\n    (X.timeBound words key) (I.initial (vectorBits words) key) (X.done words key)\n    _ _ rfl rfl rfl rfl (X.source_run words key) hin ho\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCalls\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinate\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedState\n/-! # Full physical21-role source boundaries\nEleven mathematical field names describe actual retained/parser/logger words.\nThe actual binary coordinate and all nine private reader roles are represented.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateState\nopen SemiprimeD1StackRecoveryCoordinate\nnamespace IX\nexport SemiprimeD1StackRecoveryEntriesIndexedState (view)\nend IX\n/-- Proof-only names for11 actual non-query boundary words, never runtime operands. -/\ninductive Role where\n  | cache | value | phases | reader | blocks | valid | rowHistory | rowOutput | history | buffer | output\n  deriving DecidableEq,Repr\ninstance :Fintype Role:=Fintype.ofList [.cache,.value,.phases,.reader,.blocks,.valid,.rowHistory,.rowOutput,.history,.buffer,.output]\n  (by intro k;cases k <;> simp)\n/-- Literal physical address of each mathematical boundary field. -/\ndef address:Role→Stack\n  | .cache=>block | .value=>selected | .phases=>aux .phases | .reader=>aux .reader | .blocks=>aux .blocks\n  | .valid=>aux .valid | .rowHistory=>aux .rowHistory | .rowOutput=>aux .rowOutput\n  | .history=>aux .history | .buffer=>aux .buffer | .output=>output\n/-- Auxiliary role conversion is fixed and has no data-dependent address operation. -/\ndef external:Aux→Role\n  | .phases=>.phases | .reader=>.reader | .blocks=>.blocks | .valid=>.valid\n  | .rowHistory=>.rowHistory | .rowOutput=>.rowOutput | .history=>.history | .buffer=>.buffer | .output=>.output\n/-- Full physical bank: raw binary query retained, all actual private reader roles empty. -/\ndef data (key:List Bool) (w:Role→List Bool):Stack→List Bool:=\n  Sum.elim (IX.view (w .cache) key [] [] (w .value)) (fun a=>w (external a))\n/-- Every named actual boundary word is literal. -/\ntheorem data_get (key:List Bool) (w:Role→List Bool) (r:Role):data key w (address r)=w r:=by cases r <;> rfl\n/-- The original binary coordinate, including all high-zero padding, is retained. -/\ntheorem data_coordinate (key:List Bool) (w:Role→List Bool):data key w coordinate=key:=rfl\n/-- The genuine shared copy/parser scratch is empty between component calls. -/\ntheorem data_scratch (key:List Bool) (w:Role→List Bool):data key w scratch=[]:=rfl\n/-- Logical single-field updates coincide exactly with the actual physical21-role bank. -/\ntheorem data_update (key:List Bool) (w:Role→List Bool) (r:Role) (word:List Bool):\n    data key (Function.update w r word)=Function.update (data key w) (address r) word:=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · cases k <;> cases r <;> rfl\n    · cases k <;> cases r <;> rfl\n  · cases k <;> cases r <;> rfl\n/-- All mathematical boundary names refer to distinct actual tapes. -/\ntheorem address_injective:Function.Injective address:=by decide\n/-- Proof-side full boundary record, never a runtime object. -/\nstructure Words where\n  /-- Actual cache boundary payload. -/\n  cache:List Bool:=[]\n  /-- Actual value boundary payload. -/\n  value:List Bool:=[]\n  /-- Actual phases boundary payload. -/\n  phases:List Bool:=[]\n  /-- Actual reader boundary payload. -/\n  reader:List Bool:=[]\n  /-- Actual blocks boundary payload. -/\n  blocks:List Bool:=[]\n  /-- Actual valid boundary payload. -/\n  valid:List Bool:=[]\n  /-- Actual rowHistory boundary payload. -/\n  rowHistory:List Bool:=[]\n  /-- Actual rowOutput boundary payload. -/\n  rowOutput:List Bool:=[]\n  /-- Actual history boundary payload. -/\n  history:List Bool:=[]\n  /-- Actual buffer boundary payload. -/\n  buffer:List Bool:=[]\n  /-- Actual output boundary payload. -/\n  output:List Bool:=[]\n/-- Literal11-word projection into the all21-role bank. -/\ndef words (v:Words):Role→List Bool\n  | .cache=>v.cache | .value=>v.value | .phases=>v.phases | .reader=>v.reader | .blocks=>v.blocks\n  | .valid=>v.valid | .rowHistory=>v.rowHistory | .rowOutput=>v.rowOutput | .history=>v.history\n  | .buffer=>v.buffer | .output=>v.output\n/-- Literal record update describes a real single physical word replacement. -/\ndef setWord (v:Words) (r:Role) (word:List Bool):Words:=match r with\n  | .cache=>{v with cache:=word} | .value=>{v with value:=word} | .phases=>{v with phases:=word}\n  | .reader=>{v with reader:=word} | .blocks=>{v with blocks:=word} | .valid=>{v with valid:=word}\n  | .rowHistory=>{v with rowHistory:=word} | .rowOutput=>{v with rowOutput:=word}\n  | .history=>{v with history:=word} | .buffer=>{v with buffer:=word} | .output=>{v with output:=word}\n/-- Every real physical update is exactly its11-word mathematical view. -/\ntheorem words_update (v:Words) (r:Role) (word:List Bool):Function.update (words v) r word=words (setWord v r word):=by\n  funext k;cases r <;> cases k <;> rfl\n/-- The actual two-input source boundary contains no prepared coordinate cache. -/\ntheorem initial_data (phases key:List Bool):(initial phases key).data=data key (words {phases:=phases}):=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateState\n","RiemannGaussian.SemiprimeD1StackRecoveryDenominatorOperators":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryDenominatorPrimitives\n/-! # Real whole multiplier and final width-fit component calls\nBoth traces are the frozen physical source traces with actual call/return cells.\nAll caller words and allocated shadows outside each actual image are preserved.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryDenominatorOperators\nopen SemiprimeD1StackRecoveryDenominator SemiprimeD1StackRecoveryDenominatorState\nopen SemiprimeD1StackProcedureTrace\nnamespace ME\nexport SemiprimeD1StackMultiplierExecution (source_run loopClock source_time timeBound)\nend ME\nnamespace FE\nexport SemiprimeD1StackWordFitExecution (source_run totalTime done result)\nend FE\n/-- Exact wholesale actual multiplier bank replacement, retaining all foreign words. -/\ndef replaceMul (v:Values) (bank:M.Stack → List Bool):Values\n  | .mul k=>bank k | .template=>v .template | .counter=>v .counter\n  | .fitScratch=>v .fitScratch | .aux k=>v (.aux k)\n/-- Complete actual full-product result, with all nine multiplier work words cleared. -/\ndef multiplied (v:Values) (xs ys:List Bool):Values:=\n  replaceMul v (M.payload [] [] [] [] (SemiprimeBitArithmetic.mulBits xs ys).bits [] [] [] [])\n/-- Every full-product caller tape outside the actual multiplier image is unchanged. -/\ntheorem replace_foreign (v:Values) (bank:M.Stack → List Bool) (k:Stack)\n    (hk:∀m,k≠main m):data (replaceMul v bank) k=data v k:=by\n  rcases k with k|k\n  · exact (hk k rfl).elim\n  · rcases k with k|k\n    · fin_cases k <;> rfl\n    · cases k <;> rfl\n/-- SAME actual full multiplier elapsed count, including the real outer call/return. -/\ndef multiplyTime (xs ys:List Bool):Nat:=2*xs.length+1+ME.loopClock ys xs.reverse []+1\n/-- Current denominator FIRST, running product SECOND: actual whole9-role source call. -/\ntheorem multiply_call (v:Values) (xs ys:List Bool)\n    (hv:∀k,v (.mul k)=M.payload xs ys [] [] [] [] [] [] [] k):\n    Runs program (multiplyTime xs ys) (.local .multiply) (data v) (.local (.loop true)) (data (multiplied v xs ys)):=by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program main Label.multiply (Sum.inl_injective) M.code (.control .start)\n    (fun _=>rfl) (.local .multiply) (.local (.loop true)) rfl\n    (2*xs.length+1+ME.loopClock ys xs.reverse [])\n    (SemiprimeD1StackMultiplier.state (some (.control .start)) none none xs ys [] [] [] [] [] [] [])\n    (SemiprimeD1StackMultiplier.state none none none [] [] [] [] (SemiprimeBitArithmetic.mulBits xs ys).bits [] [] [] [])\n    _ _ rfl rfl rfl rfl (ME.source_run xs ys)\n  · constructor\n    · intro k;exact hv k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      exact replace_foreign v _ k (by simpa only [ne_eq,eq_comm] using hk)\n/-- Exact final width-fit result writes only the real consumed accumulator and actual output. -/\ndef fitted (v:Values):Values:=Function.update (Function.update v (.mul (.inl .right)) []) (.aux .output)\n  (FE.result (v (.mul (.inl .right))) (v .template))\n/-- Actual final fit call preserves the physical template and both unused fit shadows. -/\ntheorem fit_call (v:Values) (hc:v .counter=[]) (hs:v .fitScratch=[]) (ho:v (.aux .output)=[]):\n    Runs program (FE.totalTime (v (.mul (.inl .right))) (v .template)+1)\n      (.local .fit) (data v) (.local .done) (data (fitted v)):=by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program fitStack Label.fit fit_injective Fit.program .start (fun _=>rfl)\n    (.local .fit) (.local .done) rfl (FE.totalTime (v (.mul (.inl .right))) (v .template))\n    (SemiprimeD1StackWordFit.initial (v (.mul (.inl .right))) (v .template))\n    (FE.done (v (.mul (.inl .right))) (v .template)) _ _ rfl rfl rfl rfl (FE.source_run _ _)\n  · constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact (data_get v .counter).trans hc\n      · exact (data_get v .fitScratch).trans hs\n      · exact (data_get v (.aux .output)).trans ho\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact (data_get (fitted v) .counter).trans hc\n      · exact (data_get (fitted v) .fitScratch).trans hs\n      · rfl\n    · intro k hk\n      have ha:k≠address (.mul (.inl .right)):=fun h=>hk 0 (by exact h.symm)\n      have ho':k≠address (.aux .output):=fun h=>hk 4 (by exact h.symm)\n      simp only [fitted,data_update,Function.update_of_ne ho',Function.update_of_ne ha]\nend RiemannGaussian.SemiprimeD1StackRecoveryDenominatorOperators\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesChildCaps":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesEncoding\n/-! # Semantic child-cache byte caps independent of recursive child runtime\nOnly actual child count/rank/precision and actual coefficient-word length caps\nenter these estimates. No polynomial of a subtree clock is substituted.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesChildCaps\nopen SemiprimeD1StackRecoveryEntriesEncoding\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Actual coefficient bytes are bounded by physical coefficient count and semantic precision. -/\ntheorem payload_sum (words:List (List Bool)) (P:Nat) (hp:∀word∈words,word.length ≤P):\n    (words.map List.length).sum ≤words.length*P:=by\n  induction words with\n  | nil=>simp only [List.map_nil,List.sum_nil,List.length_nil,Nat.zero_mul,Nat.le_refl]\n  | cons word words ih=>\n    have h:=hp word (List.mem_cons_self)\n    have ht:=ih (fun w hw=>hp w (List.mem_cons_of_mem word hw))\n    simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n/-- Actual encoded child row has a count/rank/precision cap, without any child-clock premise. -/\ntheorem vector_length (words:List (List Bool)) (R P:Nat) (hr:words.length ≤R)\n    (hp:∀word∈words,word.length ≤P):(vectorBits words).length ≤2*R*(P+1)+1:=by\n  have h:=payload_sum words P hp\n  have hm:=Nat.mul_le_mul_right P hr\n  rw [SemiprimeD1TensorTapeCodec.vectorBits_length]\n  nlinarith only [h,hm,hr]\n/-- Whole nested physical child tape has a fixed polynomial semantic bound in count, old rank and working precision. -/\ntheorem child_tape_length (children:List (List (List Bool))) (Q R P:Nat) (hq:children.length ≤Q)\n    (hr:∀row∈children,row.length ≤R) (hp:∀row∈children,∀word∈row,word.length ≤P):\n    (childTape children).length ≤4*Q*R*(P+1)+4*Q+1:=by\n  have h:=vector_length (children.map vectorBits) Q (2*R*(P+1)+1) (by simpa only [List.length_map] using hq) (by\n    intro encoded he\n    obtain ⟨row,hrow,rfl⟩:=List.mem_map.mp he\n    exact vector_length row R P (hr row hrow) (hp row hrow))\n  change (childTape children).length ≤_ at h\n  nlinarith only [h]\n/-- Every actual selected/default coefficient derives its width only from the semantic child precision cap. -/\ntheorem selected_child_length (children:List (List (List Bool))) (node index:List Bool) (P:Nat)\n    (hp:∀row∈children,∀word∈row,word.length ≤P):\n    (selectedChild children node index).length ≤P:=by\n  unfold selectedChild\n  cases hn:children[SemiprimeBitArithmetic.bitValue node]? with\n  | none=>simp\n  | some row=>\n    simp only [Option.getD_some]\n    cases hi:row[SemiprimeBitArithmetic.bitValue index]? with\n    | none=>simp\n    | some word=>exact hp row (List.mem_of_getElem? hn) word (List.mem_of_getElem? hi)\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesChildCaps\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesOriginalRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesChildCaps\nimport RiemannGaussian.SemiprimeD1StackRecoveryDenominatorOriginal\n/-! # Exact original recovery-entry bytes and semantic count/precision caps\nThe legacy canonical rows specify the actual five-field source tape in proofs;\nthey are not runtime inputs or a claimed canonical-row producer. Child caps\nuse actual coefficient widths only, never recursive child execution budgets.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesOriginalRows\nopen SemiprimeD1StackRecoveryEntriesEncoding\nnamespace D\nexport SemiprimeD1StackRecoveryDenominatorOriginal (encodeRow originalRows)\nend D\nnamespace Up\nexport SemiprimeD1RecoveryPhysicalRun (entries entries_child_length)\nend Up\nnamespace R\nexport SemiprimeD1RecoveryRowsBits (Row acquire acquire_length acquire_good)\nend R\nnamespace I\nexport SemiprimeD1RecoveryIntegerBits (Entry)\nend I\n/-- Exact four-field old entry payload, retaining raw numerator sign/padding and child padding. -/\ndef encodeEntry (e:I.Entry):Entry:=![[e.numerator.negative],e.numerator.magnitude,e.denominator,e.child]\n/-- A canonical source row's actual child field equals the original physical two-level cache read. -/\ntheorem entry_row (children:List (List (List Bool))) (r:R.Row):\n    entry children (D.encodeRow r)=encodeEntry ⟨r.word.numerator,r.word.denominator,\n      (SemiprimeD1RecoveryChildBits.read children\n        (SemiprimeEncodedRowSelection.digits (r.node+1) r.node).bits\n        (SemiprimeEncodedRowSelection.digits (r.index+1) r.index).bits).bits⟩:=by\n  funext part;fin_cases part\n  · rfl\n  · rfl\n  · rfl\n  · exact (SemiprimeD1RecoveryChildBits.read_bits children _ _).symm\n/-- Every old recovery row, including repeats, zeros and missing-cache defaults, occurs in exactly original order. -/\ntheorem entries_rows (children:List (List (List Bool))) (rows:List R.Row):\n    (rows.map D.encodeRow).map (entry children)=(Up.entries children rows).entries.map encodeEntry:=by\n  induction rows with\n  | nil=>rfl\n  | cons r rows ih=>\n    simp only [List.map_cons,Up.entries]\n    rw [entry_row,ih]\n/-- The actual output byte tape is EXACT the old physical entries payload, not merely its values. -/\ntheorem output_rows (children:List (List (List Bool))) (rows:List R.Row):\n    outputTape (rows.map D.encodeRow) children=records ((Up.entries children rows).entries.map encodeEntry):=by\n  unfold outputTape\n  rw [entries_rows]\n/-- Original actual entry count derives from the canonical acquired row inventory. -/\ntheorem original_count (a M u:Nat) (hM:u ≤M):\n    (D.originalRows a M u).length ≤SemiprimeD1WireKernelOriginal.size a*(4*M):=by\n  simpa only [D.originalRows,List.length_map] using R.acquire_length a M u hM\n/-- Actual output child widths derive only from literal input coefficient precision. -/\ntheorem original_child_precision (a M u P:Nat) (children:List (List (List Bool)))\n    (hp:∀row∈children,∀word∈row,word.length ≤P):\n    ∀e∈(Up.entries children (R.acquire a M u).rows).entries,e.child.length ≤P:=\n  Up.entries_child_length children _ P hp\n/-- Every original row numerator/denominator payload has its acquired canonical-node width, without a child-clock bound. -/\ntheorem original_payload_width (a M u:Nat) (hM:u ≤M):\n    ∀r∈(R.acquire a M u).rows,\n      r.word.numerator.magnitude.length ≤SemiprimeD1RecoveryNodeBits.width a M ∧\n      r.word.denominator.length ≤SemiprimeD1RecoveryNodeBits.width a M:=\n  (R.acquire_good a M u hM).2\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesOriginalRows\n","RiemannGaussian.SemiprimeD1StackRecoveryFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetScalarMulExecution\nimport RiemannGaussian.SemiprimeD1StackJetScalarAddExecution\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nimport RiemannGaussian.SemiprimeD1RecoveryStripBits\n/-! # Literal signed dyadic stripping and precision-round scalar recovery\nThe only physical inputs are sign::binary magnitude, a positive binary\n denominator and an actual unary precision cache. Lost low one bits trigger a\nREAL raw increment for negative nonintegral floor division. A literal Newton\nloop executes three real modular products and one real modular sum per actual\nprecision marker. Neither quotient, valuation, inverse nor answer enters control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinish\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace M\nexport SemiprimeD1StackJetScalarMul (Stack Label program store reduceStack)\nend M\nnamespace A\nexport SemiprimeD1StackJetScalarAdd (Stack Label program store)\nend A\nnamespace Raw\nexport SemiprimeD1StackAdder (Stack Label code)\nend Raw\nnamespace R\nexport SemiprimeD1StackReduce (Label code)\nend R\n/-- Three original/saved-sign fields and fifteen actual work/cache words. -/\ninductive Aux where\n  | numerator | denominator | sign | numeratorWork | denominatorWork | content | lost | todo\n  | inverseInput | negative | two | current | numeratorResidue | signedResidue | product | opposite | correction | copyScratch\n  deriving DecidableEq,Repr\ninstance :Fintype Aux:=Fintype.ofList\n  [.numerator,.denominator,.sign,.numeratorWork,.denominatorWork,.content,.lost,.todo,.inverseInput,\n    .negative,.two,.current,.numeratorResidue,.signedResidue,.product,.opposite,.correction,.copyScratch]\n  (by intro k;cases k <;> simp)\n/-- All35 allocated roles include the unused private scalar-add width shadow. -/\nabbrev Stack:=M.Stack⊕(A.Stack⊕Aux)\n/-- Literal whole11-role modular multiplier inclusion. -/\ndef main:M.Stack→Stack:=Sum.inl\n/-- Literal allocated six-role modular-adder shadow bank. -/\ndef addWork (k:A.Stack):Stack:=.inr (.inl k)\n/-- Actual original/cache/work address. -/\ndef aux (k:Aux):Stack:=.inr (.inr k)\n/-- The actual unary WIDTH is shared by the real modular arithmetic operators. -/\ndef width:Stack:=main (.inr false)\n/-- The actual final compact residue, kept in the real multiplier's output role. -/\ndef output:Stack:=main (M.reduceStack .output)\n/-- Actual first multiplier input address. -/\ndef mulLeft:Stack:=main (.inl SemiprimeD1StackMultiplier.input)\n/-- Actual second multiplier input address. -/\ndef mulRight:Stack:=main (.inl SemiprimeD1StackMultiplier.factor)\n/-- Scalar-add WIDTH aliases actual multiplier WIDTH; its allocated shadow stays counted. -/\ndef addStack (k:A.Stack):Stack:=if k=.inr false then width else addWork k\n/-- The existing multiplier's four reducer fields are reused before scalar multiplication begins. -/\ndef reduceStack (k:Raw.Stack):Stack:=main (M.reduceStack k)\n/-- The existing scalar-adder's four binary fields perform the full floor-rounding increment. -/\ndef rawStack (k:Raw.Stack):Stack:=addStack (.inl k)\n/-- Five fixed product call sites, independent of every operand and precision value. -/\ninductive MulSite where | product | opposite | update | signed | final deriving DecidableEq,Repr\ninstance:Fintype MulSite:=Fintype.ofList [.product,.opposite,.update,.signed,.final] (by intro k;cases k <;> simp)\n/-- Twelve actual consuming transfers; both raw and modular output words are physically drained. -/\ninductive MoveSite where\n  | plain | roundingInput | rounded | residue | inverseInput | two | one | product | opposite | update | signed | correction\n  deriving DecidableEq,Repr\ninstance:Fintype MoveSite:=Fintype.ofList\n  [.plain,.roundingInput,.rounded,.residue,.inverseInput,.two,.one,.product,.opposite,.update,.signed,.correction]\n  (by intro k;cases k <;> simp)\n/-- Fixed physical transfer source. -/\ndef moveSource:MoveSite→Stack\n  | .plain|.roundingInput=>aux .numeratorWork\n  | .rounded|.correction=>rawStack .output\n  | _=>output\n/-- Fixed physical transfer destination. -/\ndef moveTarget:MoveSite→Stack\n  | .plain|.rounded=>reduceStack .left\n  | .roundingInput=>rawStack .left\n  | .residue=>aux .numeratorResidue\n  | .inverseInput=>aux .inverseInput\n  | .two=>aux .two\n  | .one|.update=>aux .current\n  | .product=>aux .product\n  | .opposite=>aux .opposite\n  | .signed=>aux .signedResidue\n  | .correction=>aux .correction\n/-- The actual cached left operand of each literal modular-product site. -/\ndef multiplyLeft:MulSite→Stack\n  | .product=>aux .inverseInput\n  | .opposite|.signed=>aux .negative\n  | .update=>aux .current\n  | .final=>aux .signedResidue\n/-- The actual cached right operand of each literal modular-product site. -/\ndef multiplyRight:MulSite→Stack\n  | .product|.final=>aux .current\n  | .opposite=>aux .product\n  | .update=>aux .correction\n  | .signed=>aux .numeratorResidue\n/-- Every nonfinal product replaces one physically cleared cache; the final result stays in multiplier output. -/\ndef multiplyTarget:MulSite→Stack\n  | .product=>aux .product\n  | .opposite=>aux .opposite\n  | .update=>aux .current\n  | .signed=>aux .signedResidue\n  | .final=>output\n/-- The fixed consuming move used after each nonfinal modular product. -/\ndef multiplyMove:MulSite→MoveSite\n  | .product=>.product | .opposite=>.opposite | .update=>.update | .signed=>.signed | .final=>.signed\n/-- All actual preserving-copy sites are fixed before the three input words. -/\ninductive Copy where\n  | numerator | denominator | width | negative | todo | odd | addLeft | addRight | positive\n  | mulLeft (site:MulSite) | mulRight (site:MulSite) | move (site:MoveSite)\n  deriving DecidableEq,Fintype\n/-- Fixed physical source of each actual preserving copy. -/\ndef copySource:Copy→Stack\n  | .numerator=>aux .numerator | .denominator=>aux .denominator\n  | .width|.negative|.todo=>width | .odd=>aux .denominatorWork\n  | .addLeft=>aux .two | .addRight=>aux .opposite | .positive=>aux .numeratorResidue\n  | .mulLeft site=>multiplyLeft site | .mulRight site=>multiplyRight site | .move site=>moveSource site\n/-- Fixed physical destination of each actual preserving copy. -/\ndef copyTarget:Copy→Stack\n  | .numerator=>aux .numeratorWork | .denominator=>aux .denominatorWork\n  | .width=>reduceStack .right | .negative=>aux .negative | .todo=>aux .todo | .odd=>reduceStack .left\n  | .addLeft=>rawStack .left | .addRight=>rawStack .right | .positive=>aux .signedResidue\n  | .mulLeft _=>mulLeft | .mulRight _=>mulRight | .move site=>moveTarget site\n/-- Real three-role preserving-copy map. -/\ndef copyStack (site:Copy) (k:Fin 3):Stack:=\n  if k=0 then copySource site else if k=1 then copyTarget site else aux .copyScratch\n/-- Every one of the sixteen actual helper/cache words is drained at the end. -/\ndef cleanup:List Aux:=[.sign,.numeratorWork,.denominatorWork,.content,.lost,.todo,.inverseInput,\n  .negative,.two,.current,.numeratorResidue,.signedResidue,.product,.opposite,.correction,.copyScratch]\n/-- Fixed finite cleanup address; no input-derived index occurs in runtime control. -/\ndef cleanupRole (part:Fin 16):Stack:=aux (cleanup.get part)\n/-- Literal finite recovery, low-bit/lost-bit, Newton and final cleanup control. -/\ninductive Control where\n  | start | sign | signFalse | signTrue | content | copyDen\n  | strip (lost:Bool) | zero (lost:Bool) | shift (lost:Bool) | odd (lost:Bool) | saveLost (lost:Bool)\n  | signFloor | negativeFloor | plain | increment | rawOne | rawAdd | rounded\n  | qWidth | qReduce | saveQ | oddInput | aWidth | aReduce | saveA | negativeWord\n  | twoHigh | twoLow | twoWidth | twoReduce | saveTwo | one | oneWidth | oneReduce | saveOne | copyTodo\n  | loop | roundProduct | roundOpposite | addLeft | addRight | add | clearCorrection | saveCorrection | roundUpdate\n  | signChoice | positive | signed | final | clear (part:Fin 16) | done | abort | returning\n  deriving DecidableEq,Fintype\n/-- Only fixed finite roles/sites and actual finite return symbols inhabit control. -/\ninductive Label where\n  | local (pc:Control) | multiply (pc:M.Label) | add (pc:A.Label) | rawAdd (pc:Raw.Label) | reduce (pc:R.Label)\n  | copy (site:Copy) (pc:Fin 9) | move (site:MoveSite) (clear:Bool) | mul (site:MulSite) (part:Fin 6) | drain (role:Stack)\n  deriving DecidableEq,Fintype\nlocal notation \"ctl\"=>Label.local\n/-- One literal finite source; numeric operands and loop counters remain on actual Boolean tapes. -/\ndef program:Label→C.Instruction Stack Label\n  | .local .start=>.call (.copy .numerator 0) (ctl .sign)\n  | .local .sign=>.base (.pop (aux .numeratorWork) (ctl .abort) (ctl .signFalse) (ctl .signTrue))\n  | .local .signFalse=>.base (.push (aux .sign) false (ctl .content))\n  | .local .signTrue=>.base (.push (aux .sign) true (ctl .content))\n  | .local .content=>.base (.push (aux .content) true (ctl .copyDen))\n  | .local .copyDen=>.call (.copy .denominator 0) (ctl (.strip false))\n  | .local (.strip lost)=>.base (.pop (aux .denominatorWork) (ctl .abort) (ctl (.zero lost)) (ctl (.odd lost)))\n  | .local (.zero lost)=>.base (.push (aux .content) false (ctl (.shift lost)))\n  | .local (.shift lost)=>.base (.pop (aux .numeratorWork) (ctl (.strip lost)) (ctl (.strip lost)) (ctl (.strip true)))\n  | .local (.odd lost)=>.base (.push (aux .denominatorWork) true (ctl (.saveLost lost)))\n  | .local (.saveLost lost)=>.base (.push (aux .lost) lost (ctl .signFloor))\n  | .local .signFloor=>.base (.peek (aux .sign) (ctl .abort) (ctl .plain) (ctl .negativeFloor))\n  | .local .negativeFloor=>.base (.peek (aux .lost) (ctl .abort) (ctl .plain) (ctl .increment))\n  | .local .plain=>.call (.move .plain false) (ctl .qWidth)\n  | .local .increment=>.call (.move .roundingInput false) (ctl .rawOne)\n  | .local .rawOne=>.base (.push (rawStack .right) true (ctl .rawAdd))\n  | .local .rawAdd=>.call (.rawAdd (.start false)) (ctl .rounded)\n  | .local .rounded=>.call (.move .rounded false) (ctl .qWidth)\n  | .local .qWidth=>.call (.copy .width 0) (ctl .qReduce)\n  | .local .qReduce=>.call (.reduce .take) (ctl .saveQ)\n  | .local .saveQ=>.call (.move .residue false) (ctl .oddInput)\n  | .local .oddInput=>.call (.copy .odd 0) (ctl .aWidth)\n  | .local .aWidth=>.call (.copy .width 0) (ctl .aReduce)\n  | .local .aReduce=>.call (.reduce .take) (ctl .saveA)\n  | .local .saveA=>.call (.move .inverseInput false) (ctl .negativeWord)\n  | .local .negativeWord=>.call (.copy .negative 0) (ctl .twoHigh)\n  | .local .twoHigh=>.base (.push (reduceStack .left) true (ctl .twoLow))\n  | .local .twoLow=>.base (.push (reduceStack .left) false (ctl .twoWidth))\n  | .local .twoWidth=>.call (.copy .width 0) (ctl .twoReduce)\n  | .local .twoReduce=>.call (.reduce .take) (ctl .saveTwo)\n  | .local .saveTwo=>.call (.move .two false) (ctl .one)\n  | .local .one=>.base (.push (reduceStack .left) true (ctl .oneWidth))\n  | .local .oneWidth=>.call (.copy .width 0) (ctl .oneReduce)\n  | .local .oneReduce=>.call (.reduce .take) (ctl .saveOne)\n  | .local .saveOne=>.call (.move .one false) (ctl .copyTodo)\n  | .local .copyTodo=>.call (.copy .todo 0) (ctl .loop)\n  | .local .loop=>.base (.pop (aux .todo) (ctl .signChoice) (ctl .abort) (ctl .roundProduct))\n  | .local .roundProduct=>.call (.mul .product 0) (ctl .roundOpposite)\n  | .local .roundOpposite=>.call (.mul .opposite 0) (ctl .addLeft)\n  | .local .addLeft=>.call (.copy .addLeft 0) (ctl .addRight)\n  | .local .addRight=>.call (.copy .addRight 0) (ctl .add)\n  | .local .add=>.call (.add .start) (ctl .clearCorrection)\n  | .local .clearCorrection=>.call (.drain (aux .correction)) (ctl .saveCorrection)\n  | .local .saveCorrection=>.call (.move .correction false) (ctl .roundUpdate)\n  | .local .roundUpdate=>.call (.mul .update 0) (ctl .loop)\n  | .local .signChoice=>.base (.peek (aux .sign) (ctl .abort) (ctl .positive) (ctl .signed))\n  | .local .positive=>.call (.copy .positive 0) (ctl .final)\n  | .local .signed=>.call (.mul .signed 0) (ctl .final)\n  | .local .final=>.call (.mul .final 0) (ctl (.clear 0))\n  | .local (.clear part)=>.call (.drain (cleanupRole part))\n      (if h:part.val<15 then ctl (.clear ⟨part.val+1,by omega⟩) else ctl .done)\n  | .local .done|.local .abort=>.base .halt\n  | .local .returning=>.ret\n  | .move site false=>.call (.copy (.move site) 0) (.move site true)\n  | .move site true=>.base (.pop (moveSource site) (ctl .returning) (.move site true) (.move site true))\n  | .drain role=>.base (.pop role (ctl .returning) (.drain role) (.drain role))\n  | .mul site part=>\n    if part=0 then .call (.copy (.mulLeft site) 0) (.mul site 1)\n    else if part=1 then .call (.copy (.mulRight site) 0) (.mul site 2)\n    else if part=2 then .call (.multiply .start) (.mul site 3)\n    else if part=3 then if site=.final then .ret else .call (.drain (multiplyTarget site)) (.mul site 4)\n    else if part=4 then .call (.move (multiplyMove site) false) (.mul site 5)\n    else .ret\n  | .multiply pc=>SemiprimeD1StackValidationLink.instruction main Label.multiply (M.program pc)\n  | .add pc=>SemiprimeD1StackValidationLink.instruction addStack Label.add (A.program pc)\n  | .rawAdd pc=>SemiprimeD1StackMultiplierLink.instruction rawStack Label.rawAdd (Raw.code pc)\n  | .reduce pc=>SemiprimeD1StackMultiplierLink.instruction reduceStack Label.reduce (R.code pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n/-- Exactly three actual input words; binary magnitudes and denominators are never expanded into unary. -/\ndef input (numerator denominator widthWord:List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update (fun _=>[]) (aux .numerator) numerator) (aux .denominator) denominator) width widthWord\n/-- Actual three-word entry has every private/shadow/cache/result role empty. -/\ndef initial (numerator denominator widthWord:List Bool):C.State Stack Label:=\n  ⟨some (ctl .start),none,none,input numerator denominator widthWord,[]⟩\n/-- One fixed finite source, with honest prepared signed/binary/unary input configuration. -/\ndef machine:Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .numerator) output (ctl .start) program\n/-- All35 actual roles include every alias shadow. -/\ntheorem stack_card:Fintype.card Stack=35:=by decide\n/-- Real scalar-add mapping preserves every distinct underlying role. -/\ntheorem add_injective:Function.Injective addStack:=by decide\n/-- Real raw increment uses four distinct scalar-add roles. -/\ntheorem raw_injective:Function.Injective rawStack:=by decide\n/-- Real direct modular reductions use four distinct multiplier roles. -/\ntheorem reduce_injective:Function.Injective reduceStack:=by decide\n/-- Every declared preserving-copy site has three distinct actual operands. -/\ntheorem copy_injective (site:Copy):Function.Injective (copyStack site):=by\n  cases site with\n  | mulLeft site=>cases site <;> decide\n  | mulRight site=>cases site <;> decide\n  | move site=>cases site <;> decide\n  | _=>decide\n/-- Actual source control is fixed finite before every original integer or precision word. -/\ntheorem control_finite:Finite machine.σ:=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every data and real-return alphabet is fixed finite before all operands. -/\ntheorem alphabets_finite:∀k,Finite (machine.Γ k):=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRecoveryFinish\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishMultiply":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishMoves\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishOperators\n/-! # Full actual cached-product subprocedures of the fixed recovery source\nEach literal site copies both actual operands, calls the real modular multiplier,\nclears its actual destination after the product is acquired, transfers/drains the\nreal output, and returns through the actual finite hardware return stack.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishMultiply\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives SemiprimeD1StackRecoveryFinishMoves\nopen SemiprimeD1StackRecoveryFinishProjection SemiprimeD1StackRecoveryFinishOperators SemiprimeD1StackProcedureTrace\n/-- Actual whole multiplier bank is clean before a cached-product invocation. -/\nstructure Clean (v:Values):Prop where\n  /-- Actual first operand is empty before its paid copy. -/\n  left:v .mulLeft=[]\n  /-- Actual second operand is empty before its paid copy. -/\n  right:v .mulRight=[]\n  /-- Actual temporary reducer counter is empty. -/\n  counter:v .reduceWidth=[]\n  /-- Actual temporary product/reducer accumulator is empty. -/\n  accumulator:v .reduceInput=[]\n  /-- Actual product output is empty before the real source call. -/\n  output:v .output=[]\n/-- Exact actual destination of each fixed product procedure. -/\ndef target:MulSite→Slot\n  | .product=>.aux .product | .opposite=>.aux .opposite | .update=>.aux .current\n  | .signed=>.aux .signedResidue | .final=>.output\n/-- Literal canonical word acquired by each real product procedure. -/\ndef word (v:Values) (site:MulSite):List Bool:=\n  (SemiprimeD1JetScalarBits.mul (v .width).length (v (multiplyFromLeft site)) (v (multiplyFromRight site))).bits\n/-- Exact all-live-word procedure result; every other source/cache word is preserved. -/\ndef result (v:Values) (site:MulSite):Values:=Function.update v (target site) (word v site)\n/-- Actual loader and multiplier-call source clock, with both paid operand copies. -/\ndef loadTime (v:Values) (site:MulSite):Nat:=\n  (5*(v (multiplyFromLeft site)).length+4)+(5*(v (multiplyFromRight site)).length+4)+\n    (ME.totalTime (v (multiplyFromLeft site)) (v (multiplyFromRight site)) (v .width)+1)\n/-- Real final return label, before the actual hardware return is popped. -/\ndef returnSite (site:MulSite):Label:=if site=.final then .mul site 3 else .mul site 5\n/-- Own actual callee clock, including destination drain/output movement at nonfinal sites. -/\ndef bodyTime (v:Values) (site:MulSite):Nat:=\n  loadTime v site+(if site=.final then 0 else (v (target site)).length+3+(6*(word v site).length+7))\n/-- Complete actual nested invocation includes the actual call and actual final return. -/\ndef time (v:Values) (site:MulSite):Nat:=bodyTime v site+2\n/-- An actual arbitrary finite return label is popped only after the real callee trace reaches it. -/\ntheorem call_return (pc entry finish next:Label) (before after:Stack→List Bool) (t:Nat)\n    (hc:program pc=.call entry next) (hret:program finish=.ret)\n    (hr:Runs program t entry before finish after):Runs program (t+2) pc before next after:=by\n  intro frames start h\n  rcases h with ⟨hp,hd,hf⟩\n  let mid:=SemiprimeD1StackCalls.execute (.call entry next) start\n  have hm:SemiprimeD1StackCalls.run program 1 start=some mid:=by\n    change SemiprimeD1StackCalls.step program start=some mid\n    simp only [SemiprimeD1StackCalls.step,hp,Option.map_some,hc,mid]\n  obtain ⟨out,hrun,hat⟩:=hr (next::frames) mid (by\n    simp only [At,mid,SemiprimeD1StackCalls.execute,hd,hf,and_self])\n  let last:=SemiprimeD1StackCalls.execute .ret out\n  have hl:SemiprimeD1StackCalls.run program 1 out=some last:=by\n    change SemiprimeD1StackCalls.step program out=some last\n    simp only [SemiprimeD1StackCalls.step,hat.1,Option.map_some,hret,last]\n  refine ⟨last,?_,?_,?_,?_⟩\n  · rw [show t+2=1+(t+1) by omega,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hrun,Option.bind_some]\n    exact hl\n  · simp only [last,SemiprimeD1StackCalls.execute,hat.2.2]\n  · simpa only [last,SemiprimeD1StackCalls.execute,hat.2.2] using hat.2.1\n  · simp only [last,SemiprimeD1StackCalls.execute,hat.2.2]\n/-- Exact real two-copy loader and modular-product source, retaining every original operand cache until the result exists. -/\ntheorem loaded_run (site:MulSite) (v:Values) (hc:Clean v) (hs:v (.aux .copyScratch)=[]):\n    Runs program (loadTime v site) (.mul site 0) (data v) (.mul site 3)\n      (data (Function.update v .output (word v site))):=by\n  let a:=v (multiplyFromLeft site)\n  let b:=v (multiplyFromRight site)\n  let v1:=Function.update v .mulLeft a\n  let v2:=Function.update v1 .mulRight b\n  have h0:=copy_view (.mulLeft site) (.mul site 0) (.mul site 1) v rfl hs\n  simp only [copyFrom,copyTo,hc.left,List.append_nil] at h0\n  change Runs program (5*a.length+4) _ _ _ (data v1) at h0\n  have hs1:v1 (.aux .copyScratch)=[]:=by simp [v1,hs]\n  have h1:=copy_view (.mulRight site) (.mul site 1) (.mul site 2) v1 rfl hs1\n  have hb:v1 (multiplyFromRight site)=b:=by cases site <;> rfl\n  have hright:v1 .mulRight=[]:=by simp [v1,hc.right]\n  simp only [copyFrom,copyTo,hb,hright,List.append_nil] at h1\n  change Runs program (5*b.length+4) _ _ _ (data v2) at h1\n  have h2:=multiply_call (.mul site 2) (.mul site 3) v2 rfl\n    (by simp [v2,v1,hc.counter]) (by simp [v2,v1,hc.accumulator]) (by simp [v2,v1,hc.output])\n  have hword:multiplyWord v2=word v site:=by simp [multiplyWord,ME.result,word,v2,v1,a,b]\n  have htime:multiplyTime v2=ME.totalTime a b (v .width)+1:=by simp [multiplyTime,v2,v1]\n  rw [hword,htime] at h2\n  have he:multiplied v2 (word v site)=Function.update v .output (word v site):=by\n    funext s\n    cases s with\n    | mulLeft=>simp [multiplied,v2,v1,hc.left]\n    | mulRight=>simp [multiplied,v2,v1,hc.right]\n    | _=>rfl\n  rw [he] at h2\n  exact join (join h0 h1) h2\n/-- Whole actual nonfinal callee includes real destination clearing and actual source-consuming output transfer. -/\ntheorem nonfinal_run (site:MulSite) (hn:site≠.final) (v:Values) (hc:Clean v) (hs:v (.aux .copyScratch)=[]):\n    Runs program (bodyTime v site) (.mul site 0) (data v) (.mul site 5) (data (result v site)):=by\n  let v3:=Function.update v .output (word v site)\n  let v4:=Function.update v3 (target site) []\n  have h0:=loaded_run site v hc hs\n  have hc1:program (.mul site 3)=.call (.drain (address (target site))) (.mul site 4):=by\n    cases site with\n    | final=>exact (hn rfl).elim\n    | _=>rfl\n  have h1:=drain_call (.mul site 3) (.mul site 4) (target site) v3 hc1\n  have hv3:v3 (target site)=v (target site):=by\n    cases site with\n    | final=>exact (hn rfl).elim\n    | _=>rfl\n  rw [hv3] at h1\n  have hs4:v4 (.aux .copyScratch)=[]:=by cases site <;> simp [v4,v3,target,hs]\n  have hc2:program (.mul site 4)=.call (.move (multiplyMove site) false) (.mul site 5):=by rfl\n  have h2:=move_call (multiplyMove site) (.mul site 4) (.mul site 5) v4 hc2 hs4\n  have hfrom:moveFrom (multiplyMove site)=.output:=by cases site <;> rfl\n  have hout:v4 .output=word v site:=by\n    cases site with\n    | final=>exact (hn rfl).elim\n    | _=>simp [v4,v3,target]\n  rw [hfrom,hout] at h2\n  have he:moved v4 (multiplyMove site)=result v site:=by\n    cases site with\n    | final=>exact (hn rfl).elim\n    | _=>\n      funext s\n      cases s with\n      | aux a=>cases a <;> simp [moved,v4,v3,target,multiplyMove,moveFrom,moveTo,result]\n      | _=>simp [moved,v4,v3,target,multiplyMove,moveFrom,moveTo,result,hc.output]\n  rw [he] at h2\n  have h:=join (join h0 h1) h2\n  simpa only [bodyTime,ite_eq_right hn,Nat.add_assoc] using h\n/-- Full actual product subprocedure, through its literal final return label. -/\ntheorem body_run (site:MulSite) (v:Values) (hc:Clean v) (hs:v (.aux .copyScratch)=[]):\n    Runs program (bodyTime v site) (.mul site 0) (data v) (returnSite site) (data (result v site)):=by\n  by_cases h:site=.final\n  · subst site\n    simpa only [bodyTime,returnSite,ite_true,Nat.add_zero,result,target] using loaded_run .final v hc hs\n  · simpa only [returnSite,ite_eq_right h] using nonfinal_run site h v hc hs\n/-- One whole actual nested cached-product call, with its own physical copies/drains/real-return clock. -/\ntheorem source_call (site:MulSite) (pc next:Label) (v:Values) (hc:Clean v) (hs:v (.aux .copyScratch)=[])\n    (hcode:program pc=.call (.mul site 0) next):\n    Runs program (time v site) pc (data v) next (data (result v site)):=by\n  apply call_return pc (.mul site 0) (returnSite site) next _ _ _ hcode\n  · cases site <;> rfl\n  · exact body_run site v hc hs\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishMultiply\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinish\n/-! # Exact live-word boundaries for all35 physical recovery roles\nTwenty-seven original/cache/operand words may be live at real-call boundaries.\nThe remaining eight allocated private/shadow words are explicitly empty there;\nall35 remain counted during every actual component execution.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinish\n/-- Finite proof-side names of the actual live source/cache/operand roles. -/\ninductive Slot where\n  | width | mulLeft | mulRight | reduceWidth | reduceInput | output | addLeft | addRight | addOutput | aux (k:Aux)\n  deriving DecidableEq,Fintype\n/-- Literal actual address of each live word. -/\ndef address:Slot→Stack\n  | .width=>width | .mulLeft=>mulLeft | .mulRight=>mulRight | .reduceWidth=>reduceStack .right\n  | .reduceInput=>reduceStack .left | .output=>output\n  | .addLeft=>rawStack .left | .addRight=>rawStack .right | .addOutput=>rawStack .output | .aux k=>aux k\n/-- All27 live addresses are distinct; the allocated shadow/private roles remain separate. -/\ntheorem address_injective:Function.Injective address:=by decide\n/-- Proof notation for physical source words only, never a runtime operand. -/\nabbrev Values:=Slot→List Bool\n/-- Exact all35-role bank at an actual source-call boundary. -/\ndef data (v:Values) (k:Stack):List Bool:=\n  if k=address .width then v .width else if k=address .mulLeft then v .mulLeft else\n  if k=address .mulRight then v .mulRight else if k=address .reduceWidth then v .reduceWidth else\n  if k=address .reduceInput then v .reduceInput else if k=address .output then v .output else\n  if k=address .addLeft then v .addLeft else if k=address .addRight then v .addRight else\n  if k=address .addOutput then v .addOutput else\n  match k with | .inr (.inr a)=>v (.aux a) | _=>[]\n/-- Every live address reads its exact physical word. -/\ntheorem data_get (v:Values) (s:Slot):data v (address s)=v s:=by\n  cases s <;> rfl\n/-- Every unlisted allocated private/shadow role is physically empty at a boundary. -/\ntheorem data_other (v:Values) (k:Stack) (hk:∀s,k≠address s):data v k=[]:=by\n  simp only [data,ite_eq_right (hk .width),ite_eq_right (hk .mulLeft),ite_eq_right (hk .mulRight),\n    ite_eq_right (hk .reduceWidth),ite_eq_right (hk .reduceInput),ite_eq_right (hk .output),ite_eq_right (hk .addLeft),\n    ite_eq_right (hk .addRight),ite_eq_right (hk .addOutput)]\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · exact (hk (.aux k) rfl).elim\n/-- A live-word update is exactly the corresponding physical data-store update. -/\ntheorem data_update (v:Values) (s:Slot) (word:List Bool):\n    data (Function.update v s word)=Function.update (data v) (address s) word:=by\n  funext k\n  by_cases hex:∃t,k=address t\n  · obtain ⟨t,rfl⟩:=hex\n    rw [data_get]\n    by_cases he:t=s\n    · subst t;simp\n    · have hn:address t≠address s:=fun h=>he (address_injective h)\n      simp only [Function.update_of_ne he,Function.update_of_ne hn,data_get]\n  · have hk:∀s,k≠address s:=by simpa only [not_exists] using hex\n    rw [data_other _ _ hk,Function.update_of_ne (hk s),data_other _ _ hk]\n/-- Empty proof bank is the actual all35-role empty store. -/\ntheorem data_zero:data (fun _=>[])=fun _=>[]:=by\n  funext k\n  by_cases hex:∃s,k=address s\n  · obtain ⟨s,rfl⟩:=hex\n    exact data_get (fun _=>[]) s\n  · exact data_other (fun _=>[]) k (by simpa only [not_exists] using hex)\n/-- The actual three source operands occupy only their literal physical roles. -/\ndef initialValues (numerator denominator widthWord:List Bool):Values:=\n  Function.update (Function.update (Function.update (fun _=>[]) (.aux .numerator) numerator) (.aux .denominator) denominator) .width widthWord\n/-- No intermediate, quotient, inverse or answer is supplied by initial bank notation. -/\ntheorem initial_data (numerator denominator widthWord:List Bool):\n    (initial numerator denominator widthWord).data=data (initialValues numerator denominator widthWord):=by\n  simp only [initialValues,data_update,data_zero,initial,input,address]\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishState\n","RiemannGaussian.SemiprimeD1StackRecoveryGridEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridView\n/-! # Exact original-grid output bank and physical rational/slope codecs\nThese are proof-side boundary specifications for the already literal source,\nnot supplied geometry, multiplicity, rational output or operation-stream inputs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridEncoding\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\n/-- Actual original grid size, used only in semantic statements and own resource bounds. -/\ndef gridSize (a:Nat) :Nat:=2^(a+1)\n/-- Exact legacy register-word specification; inactive work registers are actually empty. -/\ndef registerWord (a t:Nat) (old:SemiprimeD1RecoveryGridBits.Report) :Reg→Option SemiprimeRationalBits.RationalWord\n  | .two=>some SemiprimeD1RecoveryGridBits.twoWord\n  | .center=>some old.center | .alpha=>some old.alpha\n  | .node=>some (SemiprimeD1RecoveryGridBits.index a t).word\n  | .gridNum=>some old.grid.numerator | .gridDen=>some old.grid.denominator\n  | .scalar=>some old.scalar | .argument=>some old.argument | _=>none\n/-- Every actual stopped register word, including all16 physically cleared transient words. -/\ndef registerBank (a t:Nat) (old:SemiprimeD1RecoveryGridBits.Report) (k:Reg×Bool) :List Bool:=\n  match registerWord a t old k.1 with\n  | none=>[] | some word=>if k.2 then word.denominator else signed word\n/-- Exact complete source stop retains originals, actual h, actual a+2 template and all original grid rational bytes. -/\ndef resultWords (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :Words:=\n  let old:=SemiprimeD1RecoveryGridBits.acquire width a M u t\n  {originals (List.replicate a true) (List.replicate M true) (List.replicate u true) tword width with division:=SemiprimeD1StackUnaryDivmod.contents [] [] [] [] (List.replicate (SemiprimeD1TaperedLoss.height M u) true) [], registers:=registerBank a t.val old, auxiliary:=Function.update (Function.update (originalAux (List.replicate a true) (List.replicate M true) (List.replicate u true) tword) .indexTemplate (List.replicate (a+2) false)) .slopes (slopeTape old.grid.slopes)}\n/-- All104 literal output words are specified, including every empty shadow and every physically cleared helper. -/\ndef result (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :Stack→List Bool:=bank (resultWords a M u t tword width)\n/-- Whole true halt has both flags and actual internal returns clear. -/\ndef done (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :C.State Stack Label:=⟨none,none,none,result a M u t tword width,[]⟩\n/-- Proof-side interpretation of two actual rational words; every sign and high-zero byte is retained. -/\ndef outputWord (data:Stack→List Bool) (r:Reg) :SemiprimeRationalBits.RationalWord:=\n  ⟨⟨(data (reg r false)).head?.getD false,(data (reg r false)).tail⟩,data (reg r true)⟩\n/-- Exact original grid numerator word, including legacy width and sign. -/\ntheorem numerator_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .gridNum=(SemiprimeD1RecoveryGridBits.acquire width a M u t).grid.numerator:=rfl\n/-- Exact original grid denominator word, including legacy width and sign. -/\ntheorem denominator_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .gridDen=(SemiprimeD1RecoveryGridBits.acquire width a M u t).grid.denominator:=rfl\n/-- Exact original Ezero normalized and fitted byte word. -/\ntheorem scalar_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .scalar=(SemiprimeD1RecoveryGridBits.acquire width a M u t).scalar:=rfl\n/-- Exact original local argument normalized and fitted byte word. -/\ntheorem argument_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .argument=(SemiprimeD1RecoveryGridBits.acquire width a M u t).argument:=rfl\n/-- Exact original centre word includes the literal oneWord a0 case, even W0. -/\ntheorem center_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .center=(SemiprimeD1RecoveryGridBits.acquire width a M u t).center:=rfl\n/-- Exact original alpha byte word is distinct from the independent true geometric binary alpha. -/\ntheorem alpha_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    outputWord (result a M u t tword width) .alpha=(SemiprimeD1RecoveryGridBits.acquire width a M u t).alpha:=rfl\n/-- Every repeated slope word appears in original forward q order, with no occurrence discarded. -/\ntheorem slopes_original (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    result a M u t tword width (aux .slopes)=slopeTape (SemiprimeD1RecoveryGridBits.acquire width a M u t).grid.slopes:=rfl\n/-- Original metadata/index words and actual W are retained literally at the whole-grid boundary. -/\ntheorem originals_retained (a M u:Nat) (t:Fin (gridSize a)) (tword width:List Bool) :\n    result a M u t tword width (aux .originalA)=List.replicate a true ∧\n    result a M u t tword width (aux .originalM)=List.replicate M true ∧\n    result a M u t tword width (aux .originalU)=List.replicate u true ∧\n    result a M u t tword width (aux .originalT)=tword ∧ result a M u t tword width template=width:=⟨rfl,rfl,rfl,rfl,rfl⟩\n/-- All true grid and width values are explicitly paid by actual materialized dimensions and metadata. -/\ndef resource (a M u:Nat) (tword width:List Bool) :Nat:=a+M+u+tword.length+width.length+gridSize a+1\nend RiemannGaussian.SemiprimeD1StackRecoveryGridEncoding\n","RiemannGaussian.SemiprimeD1StackRecoveryGridPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridInventory\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual preserving copies and paid byte scans/drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridPrimitives\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridInventory SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Label)\n    (hc:program pc=.call (.copier what 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) pc before next\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes only the actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Every actual source peek preserves the entire acquired word. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every quotient/remainder/GCD/magnitude cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- Both real preserving Frame calls retain their actual source and prefix the existing physical buffer/tail. -/\ntheorem frame_call (part:Bool) (pc next:Label)\n    (hc:program pc=.call (.frame part 0) next) (before:Stack→List Bool) (word buffer:List Bool)\n    (hw:before (frameStack part 0)=word) (hb:before (frameStack part 1)=buffer) (hs:before (frameStack part 2)=[]) :\n    Runs program (6*word.length+5) pc before next\n      (Function.update before (frameStack part 1) (SemiprimeSourceHistogramKeyBits.frame word buffer)) :=by\n  let start:=SemiprimeD1StackFrame.state 0 none word buffer []\n  let stop:=SemiprimeD1StackFrame.done word (SemiprimeSourceHistogramKeyBits.frame word buffer)\n  have hi:Link.DataRel (frameStack part) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hw\n      · exact hb\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (frameStack part) (frame_injective part) before start.store before hi (1:Fin 3)\n    (SemiprimeSourceHistogramKeyBits.frame word buffer)\n  have he:Function.update start.store 1 (SemiprimeSourceHistogramKeyBits.frame word buffer)=stop.store:=by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack part) (Label.frame part) (frame_injective part) SemiprimeD1StackFrame.code 0\n    (fun _=>rfl) pc next hc (6*word.length+4) start stop before _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words word buffer none) hi ho\n/-- A literal same-program local call executes its ACTUALreturn instruction and preserves every outer return cell. -/\ntheorem local_call (pc entry stopped next:Label)\n    (hc:program pc=.call entry next)\n    (hret:program stopped=.ret) (q:Nat) (before after:Stack→List Bool)\n    (hr:Runs program q entry before stopped after) :\n    Runs program (q+2) pc before next after :=by\n  intro frames target h\n  let mid:=SemiprimeD1StackCalls.execute (.call entry next) target\n  have hm:SemiprimeD1StackCalls.run program 1 target=some mid:=by\n    change SemiprimeD1StackCalls.step program target=some mid\n    simp only [SemiprimeD1StackCalls.step,h.1,Option.map_some,hc,mid]\n  have hat:At entry before (next::frames) mid:=by\n    exact ⟨rfl,h.2.1,by simpa only [mid,SemiprimeD1StackCalls.execute] using congrArg (List.cons next) h.2.2⟩\n  obtain ⟨finish,hf,hfAt⟩:=hr (next::frames) mid hat\n  let last:SemiprimeD1StackCalls.State Stack Label:=⟨some next,finish.flag,some next,after,frames⟩\n  have hl:SemiprimeD1StackCalls.run program 1 finish=some last:=by\n    change SemiprimeD1StackCalls.step program finish=some last\n    simp only [SemiprimeD1StackCalls.step,hfAt.1,Option.map_some,hret,SemiprimeD1StackCalls.execute,hfAt.2.1,hfAt.2.2]\n    rfl\n  refine ⟨last,?_,rfl,rfl,rfl⟩\n  have he:q+2=1+(q+1):=by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hl\nend RiemannGaussian.SemiprimeD1StackRecoveryGridPrimitives\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeInputs":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineOriginalResources\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOriginal\nimport RiemannGaussian.SemiprimeD1StackRecoveryPowersOriginalResources\n/-! # One literal140-role local-node input source\nThe whole actual affine source calls Grid104 ONCE. Its acquired denominator/q\nand retained grid argument/W then feed the entire real inverse and powers\nsources through direct physical aliases. No coefficient, q, inverse, power,\nscalar, normalizer, clock or evaluator answer is an initial operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeInputs\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace A\nexport SemiprimeD1StackRecoveryAffine (Stack Label program input initial grid rational aux oldAux)\nend A\nnamespace I\nexport SemiprimeD1StackNormalizedInverse (Stack Label Reg Aux program input initial rational reg aux ctl)\nend I\nnamespace P\nexport SemiprimeD1StackRecoveryPowers (Stack Label Aux program input initial rational aux)\nend P\nnamespace Q\nexport SemiprimeD1StackRecoveryGrid (reg)\nend Q\n/-- Eight inverse-cache fields and twelve inverse-private controller/output words. -/\nabbrev InversePrivate := (I.Reg×Bool)⊕Fin 12\n/-- Entire112 acquired source words plus exactly28 new actual words; no duplicate alias bank. -/\nabbrev Stack := A.Stack⊕(InversePrivate⊕Fin 8)\n/-- Literal inclusion of the entire affine/Grid bank, retaining every old shadow. -/\ndef affine : A.Stack→Stack := Sum.inl\n/-- Exact inverse private cache address. -/\ndef inverseReg (k : I.Reg×Bool) : Stack := .inr (.inl (.inl k))\n/-- Literal fixed inverse-private controller word. -/\ndef inverseWork (k : Fin 12) : Stack := .inr (.inl (.inr k))\n/-- Literal fixed powers-private controller word. -/\ndef powersWork (k : Fin 8) : Stack := .inr (.inr k)\n/-- ENTIRE inverse58 inclusion shares actual R36, acquired denominator and acquired q directly. -/\ndef inverse : I.Stack→Stack\n  | .inl k=>affine (A.rational k)\n  | .inr (.inl k)=>inverseReg k\n  | .inr (.inr k)=>match k with\n    | .denominator=>affine (A.aux .array)\n    | .originalQ=>affine (A.aux .retainedQ)\n    | .remaining=>inverseWork 0 | .built=>inverseWork 1\n    | .aIndex=>inverseWork 2 | .bIndex=>inverseWork 3 | .terms=>inverseWork 4\n    | .reader=>inverseWork 5 | .readTodo=>inverseWork 6 | .fieldFrameScratch=>inverseWork 7\n    | .valid=>inverseWork 8 | .copyScratch=>inverseWork 9 | .prefixReverse=>inverseWork 10\n    | .output=>inverseWork 11\n/-- ENTIRE powers47 inclusion reads the actual retained Grid argument and acquired q, sharing only real R36. -/\ndef powers : P.Stack→Stack\n  | .inl k=>affine (A.rational k)\n  | .inr k=>match k with\n    | .argumentSigned=>affine (A.grid (Q.reg .argument false))\n    | .argumentDen=>affine (A.grid (Q.reg .argument true))\n    | .q=>affine (A.aux .retainedQ)\n    | .remaining=>powersWork 0 | .currentSigned=>powersWork 1 | .currentDen=>powersWork 2\n    | .row=>powersWork 3 | .frameScratch=>powersWork 4 | .copyScratch=>powersWork 5\n    | .history=>powersWork 6 | .output=>powersWork 7\n/-- Actual complete inverse array produced by its real call. -/\ndef inverseOutput : Stack := inverse (I.aux .output)\n/-- Actual complete power array produced by its real call. -/\ndef powersOutput : Stack := powers (P.aux .output)\n/-- The actual retained Ezero signed numerator, acquired by Grid104. -/\ndef scalarSigned : Stack := affine (A.grid (Q.reg .scalar false))\n/-- The actual retained Ezero binary denominator, acquired by Grid104. -/\ndef scalarDen : Stack := affine (A.grid (Q.reg .scalar true))\n/-- The actual acquired unary multiplicity, never an initial advice word. -/\ndef qWord : Stack := affine (A.aux .retainedQ)\n/-- The physical shared width template retains its exact original bits. -/\ndef widthWord : Stack := affine (A.rational (SemiprimeD1StackRationalOperation.aux .template))\n/-- Only finite literal call/return stages; readyGrid reuses an ACTUAL already acquired Grid bank. -/\ninductive Control where | start | readyGrid | inverse | powers | done deriving DecidableEq,Repr\n/-- All five literal stages precede every phase and width. -/\ninstance controlFintype : Fintype Control := Fintype.ofList [.start,.readyGrid,.inverse,.powers,.done] (by intro k;cases k <;> simp)\n/-- Static included labels carry no input-dependent index, q, value or evaluator. -/\nabbrev Label := Control⊕(A.Label⊕(I.Label⊕P.Label))\n/-- Literal caller stage. -/\ndef ctl : Control→Label := Sum.inl\n/-- Actual affine source label inclusion. -/\ndef affineLabel (pc : A.Label) : Label := .inr (.inl pc)\n/-- Actual inverse source label inclusion. -/\ndef inverseLabel (pc : I.Label) : Label := .inr (.inr (.inl pc))\n/-- Actual powers source label inclusion. -/\ndef powersLabel (pc : P.Label) : Label := .inr (.inr (.inr pc))\n/-- ONE fixed literal program: actual Grid/affine once, then real inverse, then real powers, then halt. -/\ndef program : Label→C.Instruction Stack Label\n  | .inl .start=>.call (affineLabel (.local .start)) (ctl .inverse)\n  | .inl .readyGrid=>.call (affineLabel (.local .ready)) (ctl .inverse)\n  | .inl .inverse=>.call (inverseLabel (I.ctl .start)) (ctl .powers)\n  | .inl .powers=>.call (powersLabel (.local .start)) (ctl .done)\n  | .inl .done=>.base .halt\n  | .inr (.inl pc)=>SemiprimeD1StackValidationLink.instruction affine affineLabel (A.program pc)\n  | .inr (.inr (.inl pc))=>SemiprimeD1StackValidationLink.instruction inverse inverseLabel (I.program pc)\n  | .inr (.inr (.inr pc))=>SemiprimeD1StackValidationLink.instruction powers powersLabel (P.program pc)\n/-- Exact complete physical bank with every old112 and new28 role present. -/\ndef bank (old : A.Stack→List Bool) (inv : InversePrivate→List Bool) (pow : Fin 8→List Bool) : Stack→List Bool :=\n  Sum.elim old (Sum.elim inv pow)\n/-- Only the original five phase words are initially present; arrays/q/scalars/powers are actually acquired. -/\ndef input (a M u t width : List Bool) : Stack→List Bool := bank (A.input a M u t width) (fun _=>[]) (fun _=>[])\n/-- Honest whole entry begins BEFORE Grid104 and all actual denominator/inverse/power acquisition. -/\ndef initial (a M u t width : List Bool) : C.State Stack Label := ⟨some (ctl .start),none,none,input a M u t width,[]⟩\n/-- The one fixed finite prepared five-word source; no N-only scalar counter is claimed here. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (affine (A.oldAux .originalA)) inverseOutput (ctl .start) program\n/-- Every allocated word and physical alias shadow is counted. -/\ntheorem stack_card : Fintype.card Stack=140 := by\n  change Fintype.card (A.Stack⊕(InversePrivate⊕Fin 8))=140\n  rw [Fintype.card_sum,SemiprimeD1StackRecoveryAffine.stack_card,Fintype.card_sum,Fintype.card_sum,Fintype.card_prod]\n  have h : Fintype.card I.Reg=4 := by decide\n  rw [h,Fintype.card_bool,Fintype.card_fin,Fintype.card_fin]\n/-- All actual Boolean and saved-return tape alphabets are finite before every input. -/\ntheorem alphabets_finite : ∀k,Finite (machine.Γ k) := SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\n/-- No numerical coefficient, index, q or clock inhabits runtime internal control. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackCalls.control_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeInputs\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsView\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCodec\n/-! # Actual affine/Grid cache lineage and exact140-word inverse/power stop specification\nAll native expressions in this module are theorem-side word specifications.\nThe program remains parameterless and reads only its five original words.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsEncoding\nopen SemiprimeD1StackRecoveryNodeInputs SemiprimeD1StackRecoveryNodeInputsCodec\nnamespace E\nexport SemiprimeD1StackRecoveryAffineEncoding (retained array result original)\nend E\nnamespace V\nexport SemiprimeD1StackRecoveryNodeInputsView (empty afterInverse result)\nend V\n/-- Exact actual retained local argument; its sign/denominator are physical Grid outputs. -/\ndef argument (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : SemiprimeRationalBits.RationalWord :=\n  (SemiprimeD1RecoveryGridBits.acquire width a M u selected).argument\n/-- Exact actual Ezero retained by the same original Grid source. -/\ndef scalar (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : SemiprimeRationalBits.RationalWord :=\n  (SemiprimeD1RecoveryGridBits.acquire width a M u selected).scalar\n/-- Proof specification of the inverse array obtained from the ACTUAL acquired affine array/q/W. -/\ndef inverseWords (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : List SemiprimeRationalBits.RationalWord :=\n  SemiprimeD1StackNormalizedInverseEncoding.outputWords (E.array a M u selected width) (E.retained a M u selected) width\n/-- Exact physical chronological inverse array. -/\ndef inverseTape (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : List Bool :=\n  SemiprimeD1StackNormalizedInverse.tape (inverseWords a M u selected width)\n/-- Exact actual sequential powers from the acquired original argument, not supplied coefficients. -/\ndef powerWords (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : List SemiprimeRationalBits.RationalWord :=\n  SemiprimeD1StackRecoveryPowersSpec.array width (argument a M u selected width) (E.retained a M u selected)\n/-- Exact physical chronological powers array, with no value-only codec conversion. -/\ndef powerTape (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) : List Bool :=\n  SemiprimeD1StackRecoveryPowersSpec.vector (powerWords a M u selected width)\n/-- Real complete affine source endpoint, with ALL28 new words still EMPTY. -/\ndef afterAffine (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) : Stack→List Bool :=\n  V.empty (E.result a M u selected t width)\n/-- Actual complete inverse endpoint; all112 acquired words are retained. -/\ndef afterInverse (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) : Stack→List Bool :=\n  V.afterInverse (E.result a M u selected t width) (inverseTape a M u selected width)\n/-- Every140 final role: ALL112 retained actual affine/Grid words plus exact acquired inverse and powers. -/\ndef result (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) : Stack→List Bool :=\n  V.result (E.result a M u selected t width) (inverseTape a M u selected width) (powerTape a M u selected width)\n/-- Actual true halt with no transient flags or internal saved returns. -/\ndef done (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,result a M u selected t width,[]⟩\n/-- SAME-program ready entry accepts the ACTUAL entire Grid cache, with no acquired q/affine/inverse/power advice. -/\ndef gridReady (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) : C.State Stack Label :=\n  ⟨some (ctl .readyGrid),none,none,V.empty (SemiprimeD1StackRecoveryAffineView.bank (E.original a M u selected t width)),[]⟩\n/-- All35 old private R36 words really are empty at the actual affine boundary, with the exact W preserved. -/\ntheorem rational_image (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool)\n    (k : SemiprimeD1StackRationalOperation.Stack) :\n    E.result a M u selected t width (A.rational k)=\n      (if k=SemiprimeD1StackRationalOperation.aux .template then width else []) := by\n  change Function.update (fun _=>[]) (SemiprimeD1StackRationalOperation.aux .template) width k=_\n  simp only [Function.update_apply]\n/-- Direct aliasing supplies the ACTUAL whole affine array with the exact inverse input codec. -/\ntheorem denominator_image (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    E.result a M u selected t width (A.aux .array)=SemiprimeD1StackNormalizedInverse.tape (E.array a M u selected width) :=\n  affine_tape _\n/-- The actual real affine multiplicity output is a retained unary word. -/\ntheorem q_image (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    E.result a M u selected t width (A.aux .retainedQ)=List.replicate (E.retained a M u selected) true := rfl\n/-- Argument sign/magnitude bytes are acquired by Grid, not reacquired or replaced by a power answer. -/\ntheorem argument_signed (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    E.result a M u selected t width (A.grid (Q.reg .argument false))=\n      SemiprimeD1StackRecoveryPowersSpec.signed (argument a M u selected width) := rfl\n/-- Argument denominator bytes are the exact ACTUAL retained Grid bytes. -/\ntheorem argument_den (a M u : ℕ) (selected : Fin (2^(a+1))) (t width : List Bool) :\n    E.result a M u selected t width (A.grid (Q.reg .argument true))=(argument a M u selected width).denominator := rfl\n/-- The physical power tape is EXACTLY the shared two-field array ABI, including W0 and every high zero. -/\ntheorem power_tape (a M u : ℕ) (selected : Fin (2^(a+1))) (width : List Bool) :\n    powerTape a M u selected width=SemiprimeD1StackNormalizedInverse.tape (powerWords a M u selected width) := powers_tape _\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsEncoding\n","RiemannGaussian.SemiprimeD1StackRecoveryPowersEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryPowersOperation\nimport RiemannGaussian.SemiprimeD1StackRecoveryPowersRow\n/-! # Exact complete-array physical loop and stopped-bank specifications -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryPowersEncoding\nopen SemiprimeD1StackRecoveryPowers\nopen SemiprimeD1StackRecoveryPowersView hiding Stack\nopen SemiprimeD1StackRecoveryPowersSpec (signed row next array vector suffix)\nopen SemiprimeRationalBits (RationalWord)\n/-- Payload has no terminal until the one final reversal. -/\ndef payload (xs:List RationalWord):List Bool:=xs.flatMap row\n/-- Two-field vector codec is exactly payload followed by the actual FALSE sentinel. -/\ntheorem vector_payload (xs:List RationalWord):vector xs=payload xs++[false]:=by\n  induction xs with\n  | nil=>rfl\n  | cons x xs ih=>simp only [vector,payload,List.flatMap_cons,ih,List.append_assoc]\n/-- Exact full47-word loop invariant; all parser/helper/shadow work is empty. -/\ndef loopWords (argument:RationalWord) (q:Nat) (width:List Bool) (current:RationalWord) (remaining:Nat) (history:List Bool):Words:=\n  ⟨emptyRational width,fun k=>match k with\n    | .argumentSigned=>signed argument | .argumentDen=>argument.denominator | .q=>List.replicate q true\n    | .remaining=>List.replicate remaining true | .currentSigned=>signed current | .currentDen=>current.denominator\n    | .history=>history | _=>[]⟩\n/-- All retained originals survive the source; only the exact complete chronological output is added. -/\ndef result (argument:RationalWord) (q:Nat) (width:List Bool):Stack→List Bool:=\n  Function.update (input (signed argument) argument.denominator (List.replicate q true) width)\n    (aux .output) (vector (array width argument q))\n/-- Exact actual whole halt has no transient flags or genuine saved returns. -/\ndef done (argument:RationalWord) (q:Nat) (width:List Bool):C.State Stack Label:=\n  ⟨none,none,none,result argument q width,[]⟩\n/-- Exact input resource pays numeric words by bytes and unary metadata/template by their actual physical values. -/\ndef resource (argument:RationalWord) (q:Nat) (width:List Bool):Nat:=\n  (signed argument).length+argument.denominator.length+q+width.length+1\n/-- All four real source tapes have a positive total-byte budget. -/\ntheorem resource_pos (argument:RationalWord) (q:Nat) (width:List Bool):1≤resource argument q width:=by\n  unfold resource;omega\n/-- Updating consumed remaining markers agrees literally with the actual loop state. -/\ntheorem loop_remaining (argument:RationalWord) (q:Nat) (width:List Bool) (current:RationalWord) (n m:Nat) (hist:List Bool):\n    put (loopWords argument q width current n hist) .remaining (List.replicate m true)=loopWords argument q width current m hist:=by\n  unfold put loopWords\n  congr 1\n  funext k\n  cases k <;> rfl\n/-- One reversed row is logged without altering current rational or any original byte. -/\ntheorem loop_history (argument:RationalWord) (q:Nat) (width:List Bool) (current:RationalWord) (n:Nat) (hist newHist:List Bool):\n    put (loopWords argument q width current n hist) .history newHist=loopWords argument q width current n newHist:=by\n  unfold put loopWords\n  congr 1\n  funext k\n  cases k <;> rfl\n/-- Real output/sign acquisition updates exactly the two current fields. -/\ntheorem loop_current (argument:RationalWord) (q:Nat) (width:List Bool) (current out:RationalWord) (n:Nat) (hist:List Bool):\n    SemiprimeD1StackRecoveryPowersOperationOutput.putCurrent (loopWords argument q width current n hist) out=\n      loopWords argument q width out n hist:=by\n  unfold SemiprimeD1StackRecoveryPowersOperationOutput.putCurrent loopWords\n  congr 1\n  funext k\n  cases k <;> rfl\n/-- True loop endpoint clears both current fields and every remaining marker. -/\ndef stoppedWords (argument:RationalWord) (q:Nat) (width hist:List Bool):Words:=\n  put (originals (signed argument) argument.denominator (List.replicate q true) width) .history hist\n/-- Exact recursive OWN source budget, with actual reached words in every included operation. -/\ndef loopBound (argument:RationalWord) (q:Nat) (width:List Bool) (current:RationalWord) (hist:List Bool):Nat→Nat\n  | 0=>SemiprimeD1StackRecoveryPowersRow.timeBound current+1+(signed current).length+1+current.denominator.length+1\n  | n+1=>\n    let logged:Words:=loopWords argument q width current n ((row current).reverse++hist)\n    SemiprimeD1StackRecoveryPowersRow.timeBound current+1+\n      SemiprimeD1StackRecoveryPowersOperation.timeBound logged current.numerator.negative current.numerator.magnitude current.denominator\n        argument.numerator.negative argument.numerator.magnitude argument.denominator width+\n      loopBound argument q width (next width argument current) ((row current).reverse++hist) n\nend RiemannGaussian.SemiprimeD1StackRecoveryPowersEncoding\n","RiemannGaussian.SemiprimeD1StackRecoveryPowersStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryPowersBounds\n/-! # ALL47 data roles and actual return cells at every genuine compiled source prefix\nThis prepared source has exactly four physical input words; it makes no N-only\ninitialization claim. Every scratch/shadow and retained input is included.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryPowersStorage\nopen SemiprimeD1StackRecoveryPowers SemiprimeD1StackRecoveryPowersBounds\nopen SemiprimeD1StackRecoveryPowersEncoding\nopen SemiprimeD1StackRecoveryPowersSpec (signed)\nopen SemiprimeRationalBits (RationalWord)\n/-- All four initialized input words are bounded by their actual total byte resource. -/\ntheorem initial_role_bound (argument:RationalWord) (q:Nat) (width:List Bool) (slot:Stack):\n    ((initial (signed argument) argument.denominator (List.replicate q true) width).data slot).length ≤ resource argument q width:=by\n  rcases slot with slot|slot\n  · change (if slot=SemiprimeD1StackRationalOperation.aux .template then width else []).length ≤ resource argument q width\n    split\n    · unfold resource;omega\n    · simp only [List.length_nil];omega\n  · cases slot <;> simp only [initial,input,Sum.elim_inr,List.length_replicate,List.length_nil] <;> unfold resource <;> omega\n/-- Every genuine actual source prefix stops before the SAME program's own proved whole halt. -/\ntheorem prefix_fuel (argument:RationalWord) (q:Nat) (width:List Bool) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel\n      (initial (signed argument) argument.denominator (List.replicate q true) width)=some out):\n    fuel≤ polynomial argument q width:=by\n  obtain ⟨s,hs,hstop⟩:=source_run_bounded argument q width\n  have hbefore:fuel≤ s:=by\n    by_contra hn\n    have he:fuel=s+(1+(fuel-(s+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hh:SemiprimeD1StackCalls.run program 1 (done argument q width)=none:=rfl\n    rw [hh,Option.bind_none] at hr\n    cases hr\n  exact hbefore.trans hs\n/-- Whole47-role mass counts every retained Grid word, every actual array/count buffer and every displaced shadow. -/\ntheorem word_sum (data:Stack→List Bool) (cap:Nat) (h:∀slot,(data slot).length≤ cap):\n    (∑slot:Stack,(data slot).length)≤ 47*cap:=SemiprimeD1StackRecoveryPowersOperation.word_sum data cap h\n/-- Every actual data cell and every saved real return at the SAME whole-program prefix is paid. -/\ntheorem prefix_cells (argument:RationalWord) (q:Nat) (width:List Bool) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel\n      (initial (signed argument) argument.denominator (List.replicate q true) width)=some out):\n    (∑slot:Stack,(out.data slot).length)+out.frames.length≤ 48*(resource argument q width+polynomial argument q width):=by\n  have hf:=prefix_fuel argument q width fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (resource argument q width)\n    (initial (signed argument) argument.denominator (List.replicate q true) width) out (initial_role_bound argument q width) hr\n  have hm:=word_sum out.data (resource argument q width+fuel) hd\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel\n    (initial (signed argument) argument.denominator (List.replicate q true) width) out hr\n  change out.frames.length≤ 0+fuel at hframes\n  omega\n/-- Fixed whole physical-storage polynomial precedes every actual input and every selected node. -/\ndef spacePolynomial (argument:RationalWord) (q:Nat) (width:List Bool):Nat:=10^43*(resource argument q width)^10\n/-- Same source clock and actual input word mass give a fixed complete47-plus-return cap. -/\ntheorem cells_le (argument:RationalWord) (q:Nat) (width:List Bool):\n    48*(resource argument q width+polynomial argument q width)≤ spacePolynomial argument q width:=by\n  have hp:resource argument q width≤ (resource argument q width)^10:=Nat.le_pow (by decide:0<10)\n  unfold polynomial spacePolynomial\n  omega\n/-- All47 Boolean roles plus the actual finite return-cell alphabet are counted at EVERY genuine compiled prefix. -/\ntheorem machine_prefix_cells (argument:RationalWord) (q:Nat) (width:List Bool) (fuel:Nat) (cfg:machine.Cfg)\n    (hp:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (signed argument) argument.denominator (List.replicate q true) width)))=some cfg):\n    (∑slot:Stack,(cfg.stk (some slot)).length)+(cfg.stk none).length≤ spacePolynomial argument q width:=by\n  have he:=SemiprimeD1StackCalls.run_correct (aux .argumentSigned) (aux .output) (.local .start) program fuel\n    (initial (signed argument) argument.denominator (List.replicate q true) width)\n  have hh:=he.trans hp\n  cases hout:SemiprimeD1StackCalls.run program fuel\n      (initial (signed argument) argument.denominator (List.replicate q true) width) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:cfg=SemiprimeD1StackCalls.configuration out:=(Option.some.inj hh).symm\n    subst cfg\n    exact (prefix_cells argument q width fuel out hout).trans (cells_le argument q width)\nend RiemannGaussian.SemiprimeD1StackRecoveryPowersStorage\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsCalls\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsInventory\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseRegisterClear\n/-! # Actual dedicated finite cleanup sweeps on THIS60-role program\nOld cleared-store/list identities are mathematical only. Every pop/EOF and its\nclock below executes THIS fixed program, retaining the immutable power tape.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsCleanup\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeD1StackRecoveryWeightsCalls SemiprimeD1StackProcedureTrace\nnamespace Old\nexport SemiprimeD1StackNormalizedInverseView (store)\nexport SemiprimeD1StackNormalizedInverseCleanup (mass cleared cleared_zero cleared_succ cleared_le)\nend Old\n/-- Exact mathematical actual-old-store view after fixed literal cleanup positions. -/\nnoncomputable def cleared {n:Nat} (slot:Fin n→I.Stack) (w:Words) (position:Nat):Stack→List Bool:=\n  Sum.elim (Old.cleared slot (SemiprimeD1StackNormalizedInverseView.store w.toWords) position) w.scalarInputs\n/-- An actual original-word write preserves every added caller tape. -/\ntheorem update_lift (before:I.Stack→List Bool) (added:Scalar→List Bool) (slot:I.Stack) (xs:List Bool) :\n    Function.update (Sum.elim before added) (helper slot) xs=Sum.elim (Function.update before slot xs) added:=by\n  funext role\n  rcases role with role|role\n  · simp only [helper,Function.update_apply,Sum.elim_inl,Sum.inl.injEq]\n  · rfl\n/-- Before real cleanup, the entire60-word bank is unchanged. -/\ntheorem cleared_zero {n:Nat} (slot:Fin n→I.Stack) (w:Words):cleared slot w 0=bank w:=by\n  unfold cleared\n  rw [Old.cleared_zero]\n  rfl\n/-- One real old-role EOF drain advances the literal position and preserves all59 other words. -/\ntheorem cleared_succ {n:Nat} (slot:Fin n→I.Stack) (w:Words) (i:Fin n):\n    Function.update (cleared slot w i.val) (helper (slot i)) []=cleared slot w (i.val+1):=by\n  unfold cleared\n  rw [update_lift,Old.cleared_succ]\n/-- Any actual word being drained has its own existing physical-cell mass cap. -/\ntheorem word_le {n:Nat} (slot:Fin n→I.Stack) (w:Words) (position:Nat) (i:Fin n):\n    (cleared slot w position (helper (slot i))).length≤ Old.mass (Old.store w.toWords):=\n  Old.cleared_le slot _ position (slot i)\n/-- The next static finite cleanup label, before all original dimensions. -/\ndef next {n:Nat} (pc:Fin n→Label) (stopped:Label) (i:Fin n):Label:=\n  if h:i.val<n-1 then pc ⟨i.val+1,by omega⟩ else stopped\n/-- Every literal cleanup loop is executed on THIS60-role program, with all bytes and empty branches paid. -/\ntheorem sweep {n:Nat} (hn:0<n) (slot:Fin n→I.Stack) (pc:Fin n→Label) (stopped:Label)\n    (hc:∀i,program (pc i)=.base (.pop (helper (slot i)) (next pc stopped i) (pc i) (pc i)))\n    (remaining position:Nat) (hp:position+remaining=n-1) (w:Words):\n    ∃q≤(remaining+1)*(Old.mass (Old.store w.toWords)+1),\n      Runs program q (pc ⟨position,by omega⟩) (cleared slot w position) stopped (cleared slot w n):=by\n  induction remaining generalizing position with\n  | zero=>\n    have hpos:position=n-1:=by omega\n    let i:Fin n:=⟨position,by omega⟩\n    have hnext:next pc stopped i=stopped:=by simp only [next,i,hpos,Nat.lt_irrefl,dite_false]\n    have h0:=P.drain_loop (pc i) stopped (helper (slot i)) (by rw [hc,hnext])\n      (cleared slot w position) ((cleared slot w position) (helper (slot i))) rfl\n    have he:=cleared_succ slot w i\n    change Function.update (cleared slot w position) (helper (slot i)) []=cleared slot w (position+1) at he\n    rw [he,show position+1=n by omega] at h0\n    refine ⟨_,?_,h0⟩\n    have hw:=word_le slot w position i\n    omega\n  | succ remaining ih=>\n    have hpos:position<n-1:=by omega\n    let i:Fin n:=⟨position,by omega⟩\n    have hnext:next pc stopped i=pc ⟨position+1,by omega⟩:=by simp only [next,i,dite_eq_left hpos]\n    have h0:=P.drain_loop (pc i) (pc ⟨position+1,by omega⟩) (helper (slot i)) (by rw [hc,hnext])\n      (cleared slot w position) ((cleared slot w position) (helper (slot i))) rfl\n    have he:=cleared_succ slot w i\n    change Function.update (cleared slot w position) (helper (slot i)) []=cleared slot w (position+1) at he\n    rw [he] at h0\n    obtain ⟨q,hq,h1⟩:=ih (position+1) (by omega)\n    refine ⟨_,?_,P.join h0 h1⟩\n    have hw:=word_le slot w position i\n    nlinarith\n/-- Six actual parsed/product field drains, retaining the entire old suffix and all six inputs. -/\ntheorem pair_run (w:Words):\n    ∃time ≤ 6*(Old.mass (Old.store w.toWords)+1),\n      Runs program time (.local (.clearPair 0)) (bank w) (.local .decrementA)\n        (bank (replace w (SemiprimeD1StackNormalizedInverseRegisterClear.pairClear w.toWords))):=by\n  let slot:Fin 6→I.Stack:=SemiprimeD1StackNormalizedInverseRegisterClear.pairSlot\n  have hc:∀i:Fin 6,program (.local (.clearPair i))=.base (.pop (helper (slot i))\n      (next (fun j=>Label.local (.clearPair j)) (.local .decrementA) i) (.local (.clearPair i)) (.local (.clearPair i))):=by\n    intro i;rfl\n  obtain ⟨time,ht,hr⟩:=sweep (by decide:0<6) slot (fun i=>Label.local (.clearPair i)) (.local .decrementA) hc 5 0 rfl w\n  refine ⟨time,by omega,?_⟩\n  simpa only [cleared_zero,cleared,Old.cleared_zero,slot,SemiprimeD1StackNormalizedInverseRegisterClear.pair_cleared,\n    show (⟨0,by decide⟩:Fin 6)=0 from Fin.ext rfl,bank,replace] using hr\n/-- All8 actual cache fields are drained after the output row has been framed. -/\ntheorem registers_run (w:Words):\n    ∃time ≤ 8*(Old.mass (Old.store w.toWords)+1),\n      Runs program time (.local (.clearCoefficient 0)) (bank w) (.local .outer)\n        (bank {w with registers:=fun _=>[]}):=by\n  have hc:∀i:Fin 8,program (.local (.clearCoefficient i))=.base (.pop (helper (SemiprimeD1StackNormalizedInverse.regRole i))\n      (next (fun j=>Label.local (.clearCoefficient j)) (.local .outer) i) (.local (.clearCoefficient i)) (.local (.clearCoefficient i))):=by\n    intro i;rfl\n  obtain ⟨time,ht,hr⟩:=sweep (by decide:0<8) SemiprimeD1StackNormalizedInverse.regRole\n    (fun i=>Label.local (.clearCoefficient i)) (.local .outer) hc 7 0 rfl w\n  refine ⟨time,by omega,?_⟩\n  simpa only [cleared_zero,cleared,Old.cleared_zero,SemiprimeD1StackNormalizedInverseRegisterClear.registers_cleared,\n    show (⟨0,by decide⟩:Fin 8)=0 from Fin.ext rfl,bank] using hr\n/-- Final output and five actual helper inputs are retained; all other helper roles are empty. -/\nnoncomputable def cleanStore (w:Words):Stack→List Bool:=by\n  classical\n  exact Sum.elim (fun k=>if SemiprimeD1StackRecoveryWeightsInventory.kept k then Old.store w.toWords k else []) w.scalarInputs\n/-- THIS cleanup image excludes immutable powers while including every other private helper/shadow. -/\ntheorem work_mem_iff (k:I.Stack):\n    k∈SemiprimeD1StackNormalizedInverseCleanup.roles (fun i:Fin 53=>SemiprimeD1StackNormalizedInverse.workRole ⟨i.val,by omega⟩) ↔\n      ¬SemiprimeD1StackRecoveryWeightsInventory.kept k:=by\n  constructor\n  · intro h\n    obtain ⟨i,_,rfl⟩:=List.mem_map.mp h\n    exact SemiprimeD1StackRecoveryWeightsInventory.work_not_kept i\n  · intro hk\n    obtain ⟨i,hi⟩:=SemiprimeD1StackRecoveryWeightsInventory.work_complete k hk\n    exact List.mem_map.mpr ⟨i,List.mem_finRange i,hi⟩\n/-- Exact endpoint of THIS program's53 actual physical drains, not the inverse whole-source54 sweep. -/\ntheorem final_cleared (w:Words):\n    cleared (fun i:Fin 53=>SemiprimeD1StackNormalizedInverse.workRole ⟨i.val,by omega⟩) w 53=cleanStore w:=by\n  classical\n  funext role\n  rcases role with role|role\n  · change SemiprimeD1StackNormalizedInverseCleanup.cleared _ (Old.store w.toWords) 53 role=_\n    rw [SemiprimeD1StackNormalizedInverseCleanup.cleared_full,work_mem_iff]\n    by_cases h:SemiprimeD1StackRecoveryWeightsInventory.kept role <;> simp only [cleanStore,h,not_true_eq_false,not_false_eq_true,ite_true,ite_false,Sum.elim_inl]\n  · rfl\n/-- All53 actual drains and EOF branches execute before final halt, retaining all six inputs and the output. -/\ntheorem final_run (w:Words):\n    ∃time ≤ 53*(Old.mass (Old.store w.toWords)+1),\n      Runs program time (.local (.clean false 0)) (bank w) (.local .done) (cleanStore w):=by\n  have hc:∀i:Fin 53,program (.local (.clean false i))=.base\n      (.pop (helper (SemiprimeD1StackNormalizedInverse.workRole ⟨i.val,by omega⟩))\n        (next (fun j=>Label.local (.clean false j)) (.local .done) i)\n        (.local (.clean false i)) (.local (.clean false i))):=by intro i;rfl\n  obtain ⟨time,ht,hr⟩:=sweep (by decide:0<53) (fun i:Fin 53=>SemiprimeD1StackNormalizedInverse.workRole ⟨i.val,by omega⟩)\n    (fun i=>Label.local (.clean false i)) (.local .done) hc 52 0 rfl w\n  refine ⟨time,by omega,?_⟩\n  simpa only [cleared_zero,final_cleared,show (⟨0,by decide⟩:Fin 53)=0 from Fin.ext rfl] using hr\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsCleanup\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsOuterBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsCoefficientBounds\n/-! # Complete chronological output tail and every actual outer iteration are paid by the same loop clock -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsOuterBounds\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeD1StackRecoveryWeightsWidths\nopen SemiprimeRationalBits (RationalWord)\n/-- SAME actual outer-source budget, including every decreasing coefficient and the final EOF. -/\ntheorem outer_bound (inverse powers:List RationalWord) (scalar:RationalWord) (q:Nat) (width:List Bool) (r:Nat) (out:List Bool) (s:Nat)\n    (hs:1 ≤ s) (hw:width.length ≤ s)\n    (hi:(SemiprimeD1StackNormalizedInverse.tape inverse).length ≤ s)\n    (hp:(SemiprimeD1StackNormalizedInverse.tape powers).length ≤ s)\n    (hscalar:B.bytes scalar ≤ s) (hq:q ≤ s) (hr:r ≤ q)\n    (ho:out.length+r*(4*width.length+5) ≤ 14*s^2):\n    SemiprimeD1StackRecoveryWeightsOuter.timeBound inverse powers scalar q width r out ≤ (r+1)*(10^41*s^7):=by\n  induction r generalizing out with\n  | zero=>\n    have h17:1 ≤ s^7:=Nat.one_le_pow _ _ hs\n    change 1 ≤ 1*(10^41*s^7)\n    omega\n  | succ r ih=>\n    have hqeq:r+(q-(r+1)+1)=q:=by omega\n    have hc:=SemiprimeD1StackRecoveryWeightsCoefficientBounds.coefficient_bound inverse powers scalar r (q-(r+1)) width out s hs hw hi hp hscalar (by omega) (by omega)\n    have hrow:(SemiprimeD1StackNormalizedInverse.row (Spec.weight width q r scalar inverse powers) out).length=4*width.length+out.length+5:=by\n      rw [B.row_bytes,weight_bytes]\n      omega\n    have ho':(SemiprimeD1StackNormalizedInverse.row (Spec.weight width q r scalar inverse powers) out).length+r*(4*width.length+5) ≤ 14*s^2:=by\n      rw [hrow]\n      rw [Nat.add_mul] at ho\n      omega\n    have ht:=ih _ (by omega) ho'\n    have h17:1 ≤ s^7:=Nat.one_le_pow _ _ hs\n    change 1+SemiprimeD1StackRecoveryWeightsCoefficient.timeBound inverse powers scalar r (q-(r+1)) width out+_ ≤ _\n    nlinarith only [hc,ht,h17]\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsOuterBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryWidthBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidthExecution\n/-! # Own fixed polynomial in a+M+2^(a+1)+1, paying N and W by VALUE -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWidthBounds\nopen SemiprimeD1StackRecoveryWidth SemiprimeD1StackRecoveryWidthEncoding\nopen SemiprimeD1StackRecoveryWidthSetup SemiprimeD1StackRecoveryWidthLoop\nopen SemiprimeD1StackRecoveryWidthFinish SemiprimeD1StackRecoveryWidthExecution\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Every actual intermediate doubling is paid at its literal current grid VALUE, with no supplied N operand. -/\ntheorem powerTime_le (remaining current cap:Nat) (hp:2^remaining*current≤ cap) :\n    powerTime remaining current≤(remaining+1)*(7*cap+7):=by\n  induction remaining generalizing current with\n  | zero=>simp only [powerTime];omega\n  | succ remaining ih=>\n    have hchild:2^remaining*(2*current)≤ cap:=by\n      convert hp using 1\n      rw [pow_succ]\n      ring\n    have hi:=ih (2*current) hchild\n    have hone:1≤2^(remaining+1):=Nat.one_le_pow _ _ (by decide:1≤2)\n    have hcurrent:current≤ cap:=by\n      have hm:=Nat.mul_le_mul_right current hone\n      simp only [Nat.one_mul] at hm\n      exact hm.trans hp\n    simp only [powerTime]\n    nlinarith only [hi,hcurrent]\n/-- All original unary metadata and the actual retained N value belong to the resource, which is always positive. -/\ntheorem envelope_parts (a M:Nat) :1≤ inputEnvelope a M ∧ a+1≤ inputEnvelope a M ∧ M≤ inputEnvelope a M ∧\n    gridSize a≤ inputEnvelope a M:=by\n  unfold inputEnvelope V.envelope\n  omega\n/-- Physically copied a markers and every growing N-word doubling have a fixed quadratic VALUE bound. -/\ntheorem setupTime_le (a M:Nat) :setupTime a≤100*(inputEnvelope a M)^2:=by\n  have ⟨hR,ha,_,hN⟩:=envelope_parts a M\n  have hp:2^a*2≤ gridSize a:=by rw [gridSize,pow_succ]\n  have ht:=powerTime_le a 2 (gridSize a) hp\n  have hm:(a+1)*(7*gridSize a+7)≤ inputEnvelope a M*(7*inputEnvelope a M+7):=\n    Nat.mul_le_mul ha (by omega)\n  unfold setupTime\n  nlinarith only [hR,ha,ht,hm]\n/-- Exact coefficient and degree are fixed before every acquired metadata pair. -/\ndef polynomial (a M:Nat) :Nat:=100000000000000000000*(inputEnvelope a M)^12\n/-- The SAME complete source pays all64 gate words/copies/products, actual W output cells, all old registers and halt. -/\ntheorem runBound_le (a M:Nat) :runBound a M≤ polynomial a M:=by\n  let R:=inputEnvelope a M\n  have hR:1≤ R:=(envelope_parts a M).1\n  have hsetup:=setupTime_le a M\n  have hW:=SemiprimeD1StackRecoveryWidthPolynomial.value_bound 63 a M (gridSize a)\n  have h5:1≤ R^5:=Nat.one_le_pow _ _ hR\n  have hH:wordCap a M (gridSize a)+1≤2001*R^5:=by\n    change 2000*R^5+1≤2001*R^5\n    omega\n  have hsquare:=Nat.pow_le_pow_left hH 2\n  have he:(2001*R^5)^2=4004001*R^10:=by ring\n  rw [he] at hsquare\n  have hgate:64*gateCap a M (gridSize a)≤25625606400*R^10:=by\n    unfold gateCap\n    nlinarith only [hsquare]\n  have hfinish:finishBound a M (gridSize a)≤132065*R^5:=by\n    change V.value 63 a M (gridSize a)≤2000*R^5 at hW\n    unfold finishBound wordCap\n    change 2*V.value 63 a M (gridSize a)+1+64*(2000*R^5+1)≤132065*R^5\n    omega\n  have h2:R^2≤ R^12:=Nat.pow_le_pow_right hR (by decide:2≤12)\n  have h512:R^5≤ R^12:=Nat.pow_le_pow_right hR (by decide:5≤12)\n  have h10:R^10≤ R^12:=Nat.pow_le_pow_right hR (by decide:10≤12)\n  have h12:1≤ R^12:=Nat.one_le_pow _ _ hR\n  change runBound a M≤100000000000000000000*R^12\n  unfold runBound\n  change setupTime a≤100*R^2 at hsetup\n  nlinarith only [hsetup,hgate,hfinish,h2,h512,h10,h12]\n/-- Exact authoritative FALSE template is acquired from the original two unary words within the own fixed polynomial. -/\ntheorem source_run_bounded (a M:Nat) :\n    ∃q≤ polynomial a M,SemiprimeD1StackCalls.run program q (initial (unary a) (unary M))=some (done a M):=by\n  obtain ⟨q,hq,hr⟩:=source_run a M\n  exact ⟨q,hq.trans (runBound_le a M),hr⟩\n/-- SAME actual fixed finite72-role machine, with paired acquired unary metadata and all internally acquired values paid. -/\nnoncomputable def machineSource (a M:Nat) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial (unary a) (unary M)))\n      (some (SemiprimeD1StackCalls.configuration (done a M))) (polynomial a M):=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .a) (aux .output) .start program\n  let h:=source_run_bounded a M\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackRecoveryWidthBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryWidthExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidthSetup\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidthFinish\n/-! # Whole actual two-metadata-word recovery-width template source\nNo grid size, width, gate value, polynomial evaluator or template is supplied.\nThe SAME fixed program acquires N by physical doubling, executes all64 gates,\nemits every template cell and physically clears every arithmetic register.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWidthExecution\nopen SemiprimeD1StackRecoveryWidth SemiprimeD1StackRecoveryWidthEncoding\nopen SemiprimeD1StackRecoveryWidthPrimitives SemiprimeD1StackRecoveryWidthSetup\nopen SemiprimeD1StackRecoveryWidthLoop SemiprimeD1StackRecoveryWidthFinish SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Own whole source cap includes actual N acquisition, every real gate, W-value output, all64 drains and final halt. -/\ndef runBound (a M:Nat) :Nat:=setupTime a+64*gateCap a M (gridSize a)+finishBound a M (gridSize a)+1\n/-- Actual empty front door has only acquired unary a and M, with N and ALL64 outputs generated inside. -/\ntheorem source_trace (a M:Nat) :\n    ∃q≤runBound a M-1,Runs program q .start (input (unary a) (unary M)) .done (result a M) :=by\n  have h0:=setup_run a M\n  obtain ⟨q,hq,h1⟩:=gates_loop a M (gridSize a) 64 0 rfl\n  obtain ⟨p,hp,h2⟩:=finish_run a M (gridSize a)\n  have hwidth:V.value 63 a M (gridSize a)=SemiprimeD1RecoveryNodeBits.width a M:=\n    SemiprimeD1StackRecoveryWidthPolynomial.last_original a M\n  rw [hwidth] at h2\n  refine ⟨_,?_,join (join h0 h1) h2⟩\n  unfold runBound\n  omega\n/-- Actual whole halt clears flags and all real return cells within this SAME program's physically paid clock. -/\ntheorem source_run (a M:Nat) :\n    ∃q≤runBound a M,SemiprimeD1StackCalls.run program q (initial (unary a) (unary M))=some (done a M) :=by\n  obtain ⟨q,hq,h⟩:=source_trace a M\n  obtain ⟨finish,hfin,hAt⟩:=h [] (initial (unary a) (unary M)) ⟨rfl,rfl,rfl⟩\n  have hp:0<runBound a M:=by unfold runBound;omega\n  refine ⟨q+1,by omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hfin,Option.bind_some]\n  exact halt_run program .done rfl (result a M) [] finish hAt\n/-- The genuine fixed72-role machine has the same complete VALUE-paid source execution certificate. -/\nnoncomputable def widthInTime (a M:Nat) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial (unary a) (unary M)))\n      (some (SemiprimeD1StackCalls.configuration (done a M))) (runBound a M):=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .a) (aux .output) .start program\n  let h:=source_run a M\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every returned FALSE cell equals the authoritative old original-dimension template, byte for byte. -/\ntheorem output_original (a M:Nat) :(done a M).data (aux .output)=\n    List.replicate (SemiprimeD1RecoveryNodeBits.width a M) false:=rfl\n/-- Grid cardinality was physically generated and remains paid/retained by VALUE. -/\ntheorem grid_acquired (a M:Nat) :(done a M).data (aux .grid)=unary (2^(a+1)):=rfl\n/-- Both already acquired original metadata words survive the actual width computation. -/\ntheorem inputs_retained (a M:Nat) :(done a M).data (aux .a)=unary a ∧ (done a M).data (aux .m)=unary M:=⟨rfl,rfl⟩\n/-- Every64-gate intermediate is physically cleared before the real source halt. -/\ntheorem registers_clear (a M:Nat) (g:W.Gate) :(done a M).data (reg g)=[]:=rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryWidthExecution\n","RiemannGaussian.SemiprimeD1StackRecoveryWidthSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidthEncoding\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidthPrimitives\n/-! # Actual a-driven unary doubling creates and pays N=2^(a+1) -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWidthSetup\nopen SemiprimeD1StackRecoveryWidth SemiprimeD1StackRecoveryWidthEncoding\nopen SemiprimeD1StackRecoveryWidthPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackUnaryDivmod (unary unary_add)\n/-- Each actual copied grid marker is popped and replaced by one real true push on the retained grid stack. -/\ntheorem double_move (w:Words) (xs:List Bool) :\n    Runs program (2*xs.length+1) .doubleMove (bank {w with multiplier:=xs}) .power\n      (bank {w with multiplier:=[],grid:=unary xs.length++w.grid}) :=by\n  induction xs generalizing w with\n  | nil=>\n    have h:=pop_run .doubleMove .power .doublePush .doublePush (aux .multiplier)\n      (bank {w with multiplier:=[]}) [] rfl rfl\n    rw [update_multiplier] at h\n    exact h\n  | cons b xs ih=>\n    have h0:=pop_run .doubleMove .power .doublePush .doublePush (aux .multiplier)\n      (bank {w with multiplier:=b::xs}) (b::xs) rfl rfl\n    rw [update_multiplier] at h0\n    have he:SemiprimeD1StackBytecode.choose Label.power .doublePush .doublePush (b::xs).head?=.doublePush:=by cases b <;> rfl\n    rw [he] at h0\n    have h1:=push_run .doublePush .doubleMove (aux .grid) true (bank {w with multiplier:=xs}) rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (aux .grid) (true::w.grid)) at h1\n    rw [update_grid] at h1\n    have h2:=ih {w with grid:=true::w.grid}\n    have h:=join (join h0 h1) h2\n    have heq:unary xs.length++true::w.grid=unary (b::xs).length++w.grid:=by\n      simp only [List.length_cons,SemiprimeD1StackUnaryDivmod.unary_succ,SemiprimeD1StackUnaryDivmod.unary_bump,List.cons_append]\n    change Runs _ _ _ _ _ (bank {w with multiplier:=[],grid:=unary xs.length++true::w.grid}) at h\n    rw [heq] at h\n    convert h using 1\n    simp only [List.length_cons]\n    omega\n/-- Exact real scan/copy/doubling clock, before any arithmetic gate or template is supplied. -/\ndef powerTime :Nat→Nat→Nat\n  | 0,_=>1\n  | n+1,current=>1+(5*current+4)+(2*current+1)+powerTime n (2*current)\n/-- Actual copied a markers drive all doublings; all existing grid markers are physically copied and moved each time. -/\ntheorem power_run (a M remaining current:Nat) :\n    Runs program (powerTime remaining current) .power\n      (bank {a:=unary a,m:=unary M,todo:=unary remaining,grid:=unary current}) (.gate 0)\n      (bank {a:=unary a,m:=unary M,grid:=unary (2^remaining*current)}) :=by\n  induction remaining generalizing current with\n  | zero=>\n    have h:=pop_run .power (.gate 0) .doubleCopy .doubleCopy (aux .todo)\n      (bank {a:=unary a,m:=unary M,todo:=[],grid:=unary current}) [] rfl rfl\n    rw [update_todo] at h\n    change Runs program 1 .power (bank {a:=unary a,m:=unary M,grid:=unary current}) (.gate 0)\n      (bank {a:=unary a,m:=unary M,grid:=unary current}) at h\n    simpa only [powerTime,pow_zero,Nat.one_mul,unary,List.replicate_zero] using h\n  | succ remaining ih=>\n    have h0:=pop_run .power (.gate 0) .doubleCopy .doubleCopy (aux .todo)\n      (bank {a:=unary a,m:=unary M,todo:=unary (remaining+1),grid:=unary current})\n      (true::unary remaining) rfl rfl\n    rw [update_todo] at h0\n    have h1:=copy_call .double .doubleCopy .doubleMove rfl\n      (bank {a:=unary a,m:=unary M,todo:=unary remaining,grid:=unary current}) (unary current) [] rfl rfl rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (aux .multiplier) (unary current++[])) at h1\n    rw [List.append_nil,update_multiplier] at h1\n    have h2:=double_move {a:=unary a,m:=unary M,todo:=unary remaining,grid:=unary current} (unary current)\n    simp only [unary,List.length_replicate] at h1 h2\n    have h3:=ih (2*current)\n    have hgrid:List.replicate current true++List.replicate current true=unary (2*current):=by\n      rw [←List.replicate_add]\n      congr 1\n      omega\n    rw [hgrid] at h2\n    have h:=join (join (join h0 h1) h2) h3\n    have hp:2^remaining*(2*current)=2^(remaining+1)*current:=by rw [pow_succ];ring\n    rw [hp] at h\n    exact h\n/-- Paid preserving a-copy, two literal seed markers and all actual grid-doubling transitions. -/\ndef setupTime (a:Nat) :Nat:=(5*a+4)+1+1+powerTime a 2\n/-- The actual source front door acquires its own N by VALUE and arrives at the empty first gate bank. -/\ntheorem setup_run (a M:Nat) :\n    Runs program (setupTime a) .start (input (unary a) (unary M)) (.gate 0)\n      (bank (atGate 0 a M (gridSize a))) :=by\n  rw [initial_bank]\n  have h0:=copy_call .acquireA .start .seedOne rfl (bank {a:=unary a,m:=unary M}) (unary a) [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .todo) (unary a++[])) at h0\n  rw [List.append_nil,update_todo] at h0\n  have h1:=push_run .seedOne .seedTwo (aux .grid) true (bank {a:=unary a,m:=unary M,todo:=unary a}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .grid) [true]) at h1\n  rw [update_grid] at h1\n  have h2:=push_run .seedTwo .power (aux .grid) true (bank {a:=unary a,m:=unary M,todo:=unary a,grid:=[true]}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .grid) [true,true]) at h2\n  rw [update_grid] at h2\n  have h3:=power_run a M a 2\n  have he:2^a*2=gridSize a:=by rw [gridSize,pow_succ]\n  rw [he] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  simp only [unary,List.length_replicate] at h\n  change Runs _ _ _ _ _ (bank {a:=unary a,m:=unary M,grid:=unary (gridSize a)}) at h\n  unfold atGate\n  rw [zero_registers]\n  exact h\nend RiemannGaussian.SemiprimeD1StackRecoveryWidthSetup\n","RiemannGaussian.SemiprimeD1StackRecursiveCallTrace":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\n/-! # Actual recursive calls from a trace ending at a literal return\nThis helper preserves the dynamic physical return stack. It does not introduce\nan evaluator or procedure opcode: both the call and the return are real steps.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackRecursiveCallTrace\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nopen SemiprimeD1StackProcedureTrace (At Runs)\n/-- A real call, proved recursive body and real return, preserving all outer frames. -/\ntheorem invoke {K L : Type} [DecidableEq K] (program : L→C.Instruction K L)\n    (pc entry returnPC next : L) (hcall : program pc=.call entry next)\n    (hret : program returnPC=.ret) (time : ℕ) (input output : K→List Bool)\n    (body : Runs program time entry input returnPC output) :\n    Runs program (time+2) pc input next output := by\n  intro frames target h\n  rcases h with ⟨hpc,hdata,hframes⟩\n  let called := C.execute (.call entry next) target\n  have hfirst : C.run program 1 target=some called := by\n    change C.step program target=some called\n    simp only [C.step,SemiprimeD1StackCalls.step,hpc,Option.map_some,hcall,called]\n  have hcalled : At entry input (next::frames) called := by\n    exact ⟨rfl,hdata,by simp only [called,C.execute,hframes]⟩\n  obtain ⟨between,hbody,hbetween⟩ := body (next::frames) called hcalled\n  let finish := C.execute .ret between\n  have hlast : C.run program 1 between=some finish := by\n    change C.step program between=some finish\n    simp only [C.step,SemiprimeD1StackCalls.step,hbetween.1,Option.map_some,hret,finish]\n  have hout : At next output frames finish := by\n    exact ⟨by simp only [finish,C.execute,hbetween.2.2],\n      by simpa only [finish,C.execute,hbetween.2.2] using hbetween.2.1,\n      by simp only [finish,C.execute,hbetween.2.2]⟩\n  refine ⟨finish,?_,hout⟩\n  rw [show time+2=1+(time+1) by omega,SemiprimeD1StackReturnLink.run_add,hfirst,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add,hbody,Option.bind_some,hlast]\nend RiemannGaussian.SemiprimeD1StackRecursiveCallTrace\n","RiemannGaussian.SemiprimeD1StackReduce":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAdder\nimport RiemannGaussian.SemiprimeD1JetScalarBits\n\n/-! # Fixed finite-stack low-prefix reduction and canonical trimming\nThe width is a physical counter word whose LENGTH is the precision. Unbounded\ninput/counter/output words live on four Boolean stacks, never in control. All\ninput leftovers and counter leftovers are physically consumed. The following\nexecution module proves the actual transition bound and old-reducer bytes.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackReduce\nopen SemiprimeD1StackBytecode\nopen SemiprimeD1StackAdder (Stack store store_left store_right store_scratch store_output)\n\n/-- Fixed control labels, independent of the input word and requested width. -/\ninductive Label where\n  | take | read | save (bit : Bool) | clearInput | clearWidth\n  | trim | found | move | copy (bit : Bool) | done\n  deriving DecidableEq,Fintype,Repr\n\n/-- Actual bytecode: consume low prefix, clear leftovers, strip high zeros,\nthen reverse the remaining prefix onto the physical output stack. -/\ndef code : Label→Instruction Stack Label\n  | .take => .pop .right .clearInput .read .read\n  | .read => .pop .left .clearWidth (.save false) (.save true)\n  | .save b => .push .scratch b .take\n  | .clearInput => .pop .left .trim .clearInput .clearInput\n  | .clearWidth => .pop .right .trim .clearWidth .clearWidth\n  | .trim => .pop .scratch .done .trim .found\n  | .found => .push .output true .move\n  | .move => .pop .scratch .done (.copy false) (.copy true)\n  | .copy b => .push .output b .move\n  | .done => .halt\n\n/-- Literal data-only state; width markers are supplied on the second stack. -/\ndef state (pc : Option Label) (flag : Option Bool) (word width scratch output : List Bool) : State Stack Label :=\n  ⟨pc,flag,store word width scratch output⟩\n\n/-- Actual fixed finite machine, with Boolean alphabet on ALL four stacks. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackBytecode.machine Stack.left Stack.output Label.take code\n\n/-- All alphabets are Boolean, beyond FinTM2's input-alphabet requirement. -/\ntheorem all_alphabets : ∀k,machine.Γ k=Bool := by intro k;rfl\n\n/-- No unbounded numeric/word operand is hidden in the internal control. -/\ntheorem control_finite : Finite machine.σ := inferInstanceAs (Finite (Option Bool))\n\n/-- Source iterations concatenate without an assumed cost contract. -/\ntheorem run_append (m n : ℕ) (a b c : State Stack Label)\n    (hm:run code m a=some b) (hn:run code n b=some c) : run code (n+m) a=some c := by\n  unfold run at hm hn ⊢\n  rw [Function.iterate_add_apply,hm,hn]\n\n/-- Two literal executed instructions compose. -/\ntheorem two_steps {a b c : State Stack Label} (h0:step code a=some b) (h1:step code b=some c) :\n    run code 2 a=some c := by\n  change (step code a).bind (step code)=some c\n  rw [h0]\n  exact h1\n\n/-- Three literal executed instructions compose. -/\ntheorem three_steps {a b c d : State Stack Label}\n    (h0:step code a=some b) (h1:step code b=some c) (h2:step code c=some d) : run code 3 a=some d := by\n  change ((step code a).bind (step code)).bind (step code)=some d\n  rw [h0]\n  simp only [Option.bind_some]\n  rw [h1]\n  exact h2\n\n/-- Each remaining input bit is actually consumed after the width is exhausted. -/\ntheorem clear_input_run (word acc out : List Bool) (flag : Option Bool) :\n    run code (word.length+1) (state (some .clearInput) flag word [] acc out)=\n      some (state (some .trim) none [] [] acc out) := by\n  induction word generalizing flag with\n  | nil =>\n    simp only [List.length_nil,Nat.zero_add,run,Function.iterate_one,Option.bind_some,\n      step,state,Option.map_some,code,execute,store,store_left,List.head?_nil,List.tail_nil,choose]\n  | cons b word ih =>\n    have hh:run code 1 (state (some .clearInput) flag (b::word) [] acc out)=\n        some (state (some .clearInput) (some b) word [] acc out):=by\n      cases b <;> simp only [run,Function.iterate_one,Option.bind_some,step,state,Option.map_some,\n        code,execute,store,store_left,List.head?_cons,List.tail_cons,choose]\n    have h:=run_append 1 (word.length+1) _ _ _ hh (ih (some b))\n    simpa only [List.length_cons,Nat.add_assoc] using h\n\n/-- Every unused physical precision marker is also consumed after input EOF. -/\ntheorem clear_width_run (width acc out : List Bool) (flag : Option Bool) :\n    run code (width.length+1) (state (some .clearWidth) flag [] width acc out)=\n      some (state (some .trim) none [] [] acc out) := by\n  induction width generalizing flag with\n  | nil =>\n    simp only [List.length_nil,Nat.zero_add,run,Function.iterate_one,Option.bind_some,\n      step,state,Option.map_some,code,execute,store,store_right,List.head?_nil,List.tail_nil,choose]\n  | cons b width ih =>\n    have hh:run code 1 (state (some .clearWidth) flag [] (b::width) acc out)=\n        some (state (some .clearWidth) (some b) [] width acc out):=by\n      cases b <;> simp only [run,Function.iterate_one,Option.bind_some,step,state,Option.map_some,\n        code,execute,store,store_right,List.head?_cons,List.tail_cons,choose]\n    have h:=run_append 1 (width.length+1) _ _ _ hh (ih (some b))\n    simpa only [List.length_cons,Nat.add_assoc] using h\n\nend RiemannGaussian.SemiprimeD1StackReduce\n","RiemannGaussian.SemiprimeD1StackRootOwnerIndexBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRecordsResources\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexBounds\nimport RiemannGaussian.SemiprimeD1StackRootOwnerIndexExecution\n/-! # Own whole-root/index source clock from actual acquired input bytes\nThe root source pays both retained input words to the physical index. Its\nown bound is squared after the actual root/output/count trace is charged.\nNo native graph report or supplied owner/count answer enters these bounds.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootOwnerIndexBounds\nnamespace RC\nexport SemiprimeD1StackRootNetworkRecords (Stack program initialPrefix output)\nend RC\nnamespace RE\nexport SemiprimeD1StackRootNetworkRecordsExecution (done timeBound source_run_prefix)\nexport SemiprimeD1StackRootNetworkRecordsAcquisition (prescription)\nend RE\nnamespace RB\nexport SemiprimeD1StackRootNetworkRecordsBounds (prefixPolynomial runBoundPrefix timeBound_le_prefix)\nend RB\nnamespace RR\nexport SemiprimeD1StackRootNetworkRecordsResources (initial_prefix_length)\nend RR\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (wireCount)\n/-- The same successful source trace pays both physical index input words. -/\ntheorem index_input_cap (bytes count cap:Nat) (hb:bytes ≤cap) (hc:count ≤cap) :\n    10000*(bytes+count+1)^2 ≤10000*(2*cap+1)^2:=by\n  exact Nat.mul_le_mul_left 10000 (Nat.pow_le_pow_left (by omega) 2)\n/-- One quadratic cap includes the actual root call, index call and final halt. -/\ntheorem combined_cap (n P rootTime rootCap indexTime:Nat) (ht:rootTime ≤rootCap)\n    (hi:indexTime ≤10000*(2*(n+P+rootTime)+1)^2) :\n    rootTime+indexTime+4 ≤50000*(n+P+rootCap+1)^2:=by\n  let S:=n+P+rootCap+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hlin:2*(n+P+rootTime)+1 ≤2*S:=by dsimp [S];omega\n  have hpow:=Nat.pow_le_pow_left hlin 2\n  have hindex:indexTime ≤40000*S^2:=by\n    have h:=hi.trans (Nat.mul_le_mul_left 10000 hpow)\n    convert h using 1;ring\n  have hsq:1 ≤S^2:=Nat.one_le_pow _ _ hs\n  have hself:S ≤S^2:=Nat.le_pow (by decide:0<(2:Nat))\n  have htime:rootTime ≤S^2:=by\n    have h:rootTime ≤S:=by dsimp [S];omega\n    exact h.trans hself\n  change _ ≤50000*S^2\n  omega\n/-- A single actual exponential factor is squared only after the whole physical source cost is bounded. -/\ntheorem quadratic_rate (n P r E:Nat) (he:1 ≤E):\n    50000*(n+P+r*E+1)^2 ≤50000*(n+P+r+1)^2*E^2:=by\n  have h: n+P+1 ≤(n+P+1)*E:=by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left (n+P+1) he\n  have hlin:n+P+r*E+1 ≤(n+P+r+1)*E:=by nlinarith only [h]\n  have hp:=Nat.mul_le_mul_left 50000 (Nat.pow_le_pow_left hlin 2)\n  convert hp using 1;ring\n/-- Fixed base-two arithmetic identifies the squared actual root-source exponent. -/\ntheorem scope_square (B:Nat):(2^(19*B))^2=2^(38*B):=by\n  rw [←pow_mul]\n  congr 1\n  omega\n/-- A fixed quadratic transform preserves fixed monomial witnesses in total actual input bytes. -/\ntheorem quadratic_monomial {f:Nat→Nat→Nat}\n    (hf:∃a d:Nat,∀n P,f n P ≤a*(n+P+1)^d):\n    ∃a d:Nat,∀n P,50000*(n+P+f n P+1)^2 ≤a*(n+P+1)^d:=by\n  obtain ⟨a,d,hf⟩:=hf\n  refine ⟨50000*(1+a)^2,2*(d+1),?_⟩\n  intro n P\n  let S:=n+P+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hd:S^d ≤S^(d+1):=Nat.pow_le_pow_right hs (by omega)\n  have hself:S ≤S^(d+1):=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hs (by omega:1 ≤d+1)\n  have hpoly:f n P ≤a*S^(d+1):=(hf n P).trans (Nat.mul_le_mul_left a hd)\n  have hlin:n+P+f n P+1 ≤(1+a)*S^(d+1):=by\n    have he:n+P+f n P+1=S+f n P:=by dsimp [S];omega\n    rw [he]\n    nlinarith only [hself,hpoly]\n  have h:=Nat.mul_le_mul_left 50000 (Nat.pow_le_pow_left hlin 2)\n  change _ ≤(50000*(1+a)^2)*S^(2*(d+1))\n  calc\n    _ ≤50000*((1+a)*S^(d+1))^2:=h\n    _= _:=by rw [mul_pow,←pow_mul,Nat.mul_comm (d+1) 2];ring\n/-- Every actually acquired root data word is bounded by the SAME successful source trace. -/\ntheorem root_word_length (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) (k:RC.Stack):\n    ((RE.done bits hN fixed tail).data k).length ≤\n      bits.length+(RE.prescription bits fixed tail).length+RE.timeBound bits hN fixed tail:=by\n  obtain ⟨time,ht,hr⟩:=RE.source_run_prefix bits hc hN fixed tail\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound RC.program time\n    (bits.length+(RE.prescription bits fixed tail).length) _ _\n    (RR.initial_prefix_length bits (RE.prescription bits fixed tail)) hr k\n  exact hd.trans (Nat.add_le_add_left ht _)\n/-- Conservative quadratic cap for the two actual source calls and actual caller halt. -/\ndef runCapPrefix (bits:List Bool) (P:Nat):Nat:=\n  50000*(bits.length+P+RB.runBoundPrefix bits P+1)^2\n/-- A fixed physical input/prefix polynomial before every original input. -/\ndef prefixPolynomial (n P:Nat):Nat:=50000*(n+P+RB.prefixPolynomial n P+1)^2\n/-- Same actual combined-program rate, with the squared original root-source exponent. -/\ndef runBoundPrefix (bits:List Bool) (P:Nat):Nat:=\n  prefixPolynomial bits.length P*2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits)\n/-- Standard N-only entry physically seeds its single false prescription marker. -/\ndef runBound (bits:List Bool):Nat:=runBoundPrefix bits 1\n/-- The full quadratic caller cap fits its own fixed original scope-rate envelope. -/\ntheorem runCapPrefix_le (bits:List Bool) (P:Nat):runCapPrefix bits P ≤runBoundPrefix bits P:=by\n  have he:1 ≤2^(19*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have h:=quadratic_rate bits.length P (RB.prefixPolynomial bits.length P)\n    (2^(19*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits)) he\n  simpa only [runCapPrefix,runBoundPrefix,RB.runBoundPrefix,prefixPolynomial,scope_square] using h\n/-- The caller-prefix polynomial has fixed witnesses before both N and all physical prefix bytes. -/\ntheorem prefix_polynomial_monomial:∃coef degree:Nat,∀n P,prefixPolynomial n P ≤coef*(n+P+1)^degree:=\n  quadratic_monomial SemiprimeD1StackRootNetworkRecordsResources.prefix_polynomial_monomial\n/-- N-only polynomial witnesses use the original positive width argument n+1. -/\ntheorem polynomial_monomial:∃coef degree:Nat,∀n,prefixPolynomial n 1 ≤coef*(n+1)^degree:=by\n  obtain ⟨coef,degree,h⟩:=prefix_polynomial_monomial\n  refine ⟨coef*2^degree,degree,?_⟩\n  intro n\n  have hs:n+1+1 ≤2*(n+1):=by omega\n  have hp:=Nat.pow_le_pow_left hs degree\n  have hh:prefixPolynomial n 1 ≤coef*(2*(n+1))^degree:=(h n 1).trans (Nat.mul_le_mul_left coef hp)\n  simpa only [mul_pow,Nat.mul_assoc] using hh\nnamespace X\nexport SemiprimeD1StackRootOwnerIndexExecution (timeBound done source_run source_run_prefix)\nend X\nnamespace Q\nexport SemiprimeD1StackRootOwnerIndexComponents (rootowners rootSuffix indexSource root_output root_left\n  indexSource_vertices indexSource_leftCount)\nend Q\nnamespace IE\nexport SemiprimeD1StackNetworkOwnerIndexExecution (timeBound)\nend IE\nopen SemiprimeD1StackRootOwnerIndex\nattribute [local irreducible] Q.rootowners Q.rootSuffix IE.timeBound RE.timeBound\n/-- The actual index source's own quadratic budget is paid by its two physically shared root words. -/\ntheorem index_timeBound_physical (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    IE.timeBound (Q.rootowners bits hN fixed) (Q.rootSuffix bits hN fixed) ≤10000*\n      (((RE.done bits hN fixed tail).data RC.output).length+\n        ((RE.done bits hN fixed tail).data SemiprimeD1StackRootOwnerIndexCoordinates.leftCount).length+1)^2:=by\n  rw [Q.root_output bits hc hN fixed tail,Q.indexSource_vertices,Q.root_left bits hN fixed tail,\n    Q.indexSource_leftCount,List.length_replicate]\n  exact SemiprimeD1StackNetworkOwnerIndexBounds.timeBound_le _ _\n/-- Both physical input lengths are charged to the SAME successful whole root source execution. -/\ntheorem index_timeBound_cap (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    IE.timeBound (Q.rootowners bits hN fixed) (Q.rootSuffix bits hN fixed) ≤10000*\n      (2*(bits.length+(RE.prescription bits fixed tail).length+RE.timeBound bits hN fixed tail)+1)^2:=by\n  have hv:=root_word_length bits hc hN fixed tail RC.output\n  have hn:=root_word_length bits hc hN fixed tail SemiprimeD1StackRootOwnerIndexCoordinates.leftCount\n  exact (index_timeBound_physical bits hc hN fixed tail).trans (index_input_cap _ _ _ hv hn)\n/-- The same whole caller budget includes both actual source calls, the N-only seed, and the final halt. -/\ntheorem timeBound_cap (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    X.timeBound bits hN fixed tail ≤runCapPrefix bits (RE.prescription bits fixed tail).length:=by\n  have hr:RE.timeBound bits hN fixed tail ≤RB.runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n    (Nat.le_succ _).trans (RB.timeBound_le_prefix bits hc hN fixed tail)\n  have hi:=index_timeBound_cap bits hc hN fixed tail\n  unfold X.timeBound runCapPrefix\n  exact combined_cap _ _ _ _ _ hr hi\n/-- Actual caller-prefix time fits one fixed polynomial and the squared actual table exponent. -/\ntheorem timeBound_le_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    X.timeBound bits hN fixed tail ≤runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n  (timeBound_cap bits hc hN fixed tail).trans (runCapPrefix_le _ _)\n/-- Standard N-only source clock includes the physically seeded false prefix marker. -/\ntheorem timeBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    X.timeBound bits hN [] [] ≤runBound bits:=by\n  have h:=timeBound_le_prefix bits hc hN [] []\n  simpa only [SemiprimeD1StackRootNetworkRecordsAcquisition.prescription_empty,List.length_singleton,runBound] using h\n/-- Actual N-only finite-program source trace with its own whole acquired-index clock. -/\ntheorem source_run_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    ∃time ≤runBound bits,SemiprimeD1StackCalls.run program time (initial bits)=some (X.done bits hN [] []):=by\n  obtain ⟨time,ht,hr⟩:=X.source_run bits hc hN\n  exact ⟨time,ht.trans (timeBound_le bits hc hN),hr⟩\n/-- Every repeated/conflicting actual caller-prefix and retained tail follows the same bounded source. -/\ntheorem source_run_prefix_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    ∃time ≤runBoundPrefix bits (RE.prescription bits fixed tail).length,\n      SemiprimeD1StackCalls.run program time (initialPrefix bits (RE.prescription bits fixed tail))=\n        some (X.done bits hN fixed tail):=by\n  obtain ⟨time,ht,hr⟩:=X.source_run_prefix bits hc hN fixed tail\n  exact ⟨time,ht.trans (timeBound_le_prefix bits hc hN fixed tail),hr⟩\nend RiemannGaussian.SemiprimeD1StackRootOwnerIndexBounds\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCleanView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCleanup\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsView\n/-! # Exact cleanup return retains immutable input heap/counter and literal root header -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCleanView\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsCleanup SemiprimeD1StackRootPhaseFreshRecordsView\n/-- Full physical cleanup predicate after all145 literal drain sites. -/\ntheorem cleared_full (bank:Stack→List Bool) (k:Stack) :\n    cleared bank 145 k=(@ite (List Bool) (k∈roles) (Classical.propDecidable _) [] (bank k)) :=by\n  classical\n  change (if k∈roles.take 145 then [] else bank k)=_\n  rw [List.take_of_length_le (show roles.length ≤ 145 by rw [roles_length])]\n/-- Actual complete cleanup retains sourceheap/counter/header and every caller\nword except pointer/currentrecord/newref. All private roles and shadows are EMPTY. -/\ntheorem cleared_view (root:R.Stack→List Bool) (q:Q.Stack→List Bool)\n    (reader currentRecord hp cn ref hist out:List Bool) :\n    cleared (view root q (work reader currentRecord hp cn ref hist out)) 145=\n      view root (SemiprimeD1StackPhaseCacheFresh.input (q I.sourceHeap) (q I.sourceCounter) [] (q I.oldHeader))\n        (work reader [] hp cn [] hist out) :=by\n  classical\n  funext k\n  rw [cleared_full]\n  rcases k with k|k\n  · change (if rootStack k∈roles then [] else view root q (work reader currentRecord hp cn ref hist out) (rootStack k))=_\n    rw [ite_eq_right (root_not_mem k)]\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  · rcases k with k|k\n    · by_cases hk:k=I.oldHeader\n      · subst k\n        rw [ite_eq_right (by intro h;exact ((private_mem _).mp h) rfl)]\n        rfl\n      · change (if cachePrivate k∈roles then [] else view root q (work reader currentRecord hp cn ref hist out) (cachePrivate k))=_\n        rw [ite_eq_left ((private_mem k).mpr hk)]\n        change []=privateCache (SemiprimeD1StackPhaseCacheFresh.input (q I.sourceHeap) (q I.sourceCounter) [] (q I.oldHeader)) k\n        rw [private_input]\n        simp only [hk,ite_false]\n    · change (if aux k∈roles then [] else auxView q (work reader currentRecord hp cn ref hist out) k)=_\n      simp only [aux_mem]\n      cases k <;> simp [view,data,auxView,work,SemiprimeD1StackPhaseCacheFresh.input,\n        SemiprimeD1StackPhaseCacheFresh.data,SemiprimeD1StackHeapRead.input,\n        SemiprimeD1StackRootPhaseFreshRecordsInventory.sourceReference,\n        SemiprimeD1StackPhaseCacheFresh.restoreStack,SemiprimeD1StackPhaseBankRestore.heapStack]\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCleanView\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsBinding\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsFinish\n/-! # Whole N-only phase-cache acquisition, chronological Fresh sweep and real halt -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsExecution\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsPrimitives SemiprimeD1StackRootPhaseFreshRecordsSource\nopen SemiprimeD1StackRootPhaseFreshRecordsBinding SemiprimeD1StackRootPhaseFreshRecordsLoop\nopen SemiprimeD1StackRootPhaseFreshRecordsFinish SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\n/-- Own whole-source clock includes one acquired source, one reference copy,\nevery real cached Fresh row and one final chronological reference reversal. -/\ndef runBound (bits:List Bool) :Nat :=\n  SemiprimeD1StackRootPhaseParametersExecution.runBound bits+\n  5*(O.result bits R.output).length+\n  sweepBound (O.result bits) (banks (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits))\n    (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits)\n    (entries (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)) []+\n  2*(A.stream (A.references (O.phases bits).length)).length+12\n/-- One original binary N acquires all source banks ONCE, copies actual issued\nreferences ONCE and executes every actual cache restore/Fresh/85-word heap row. -/\ntheorem source_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q,q+1 ≤ runBound bits ∧ Runs program q .start (input bits) .done (result bits) :=by\n  let root:=O.result bits\n  let bs:=banks (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)\n  let es:=entries (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)\n  let rs:=records (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)\n  obtain ⟨g,hg,h0⟩:=root_call bits hc hN\n  rw [afterRoot_view] at h0\n  have h1:=copy_refs root\n  have h2:=seed_header root (root R.output)\n  have hreader:root R.output=tape es:=source_reader bits\n  rw [hreader] at h1 h2\n  obtain ⟨r,hr,h3⟩:=rows_run root bs (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) es []\n    (source_heap bits) (source_counter bits) (entries_bank _ _ _ _)\n  dsimp only [es] at h3\n  rw [entries_cached] at h3\n  simp only [List.nil_append] at h3\n  change Runs program r .header (loop root (tape es) [] 0 []) .finishSeed\n    (loop root [] (SemiprimeD1StackHeapAllocate.heapBytes rs) rs.length (A.stream (A.references rs.length)).reverse) at h3\n  have h4:=finish_run root rs\n  have hall:=compose (compose (compose (compose h0 h1) h2) h3) h4\n  refine ⟨_,?_,hall⟩\n  have hlen:rs.length=(O.phases bits).length:=by simp only [rs,records,List.length_map]\n  change (g+1)+(5*(tape es).length+4)+1+r+(2*(A.stream (A.references rs.length)).length+4)+1 ≤ runBound bits\n  rw [hlen]\n  unfold runBound\n  rw [source_reader]\n  change r ≤ sweepBound (O.result bits) _ _ _ _ _ [] at hr\n  dsimp only [es,bs] at hr ⊢\n  omega\n/-- Genuine whole original-N-only source includes the actual final halt and leaves all finite flags/returns clear. -/\ntheorem source_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q ≤ runBound bits,SemiprimeD1StackCalls.run program q (initial bits)=some (done bits) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace bits hc hN\n  obtain ⟨finish,hf,hAt⟩:=hr [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result bits) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Fixed finite compiled source certificate for this SAME N-only program and its own actual clock. -/\nnoncomputable def freshRecordsInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial bits))\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (runBound bits) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output .start program\n  let h:=source_run bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsExecution\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsRows\n/-! # Actual chronological issued-reference sweep, with no source replay -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsLoop\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsRows SemiprimeD1StackRootPhaseFreshRecordsPrimitives\nopen SemiprimeD1StackRootPhaseFreshRecordsView SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace A\nexport SemiprimeD1StackRootPhaseParametersEncoding (stream references references_succ stream_append)\nexport SemiprimeD1StackRootPhaseParametersLoop (rowTape rowTape_vector)\nend A\n/-- Proof-side indexed phase list; indices identify literal issued words, not runtime getters. -/\nabbrev Entry (bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool)) :=Fin bs.length×List Bool\n/-- Literal actual issued-reference bytes in the original producer order. -/\ndef tape {bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool)} (es:List (Entry bs)) :List Bool :=\n  A.rowTape (es.map (fun e=>List.replicate e.1.val true)) [false]\n/-- One exact full85-word record per phase, including false/rejected phase banks. -/\ndef cached {bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool)} (a u edges:Nat) (es:List (Entry bs)) :List (List Bool) :=\n  es.map (fun e=>record a u edges e.2)\n/-- Chronological stable ordinal log advances after every real heap allocation. -/\ntheorem nextHistory_references (n:Nat) :\n    nextHistory n (A.stream (A.references n)).reverse=(A.stream (A.references (n+1))).reverse :=by\n  rw [A.references_succ,A.stream_append,List.reverse_append]\n  rfl\n/-- Recursive budget contains the SAME executed row clocks and physical accumulated heap/history lengths. -/\ndef sweepBound (root:R.Stack→List Bool) (bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool))\n    (a u edges:Nat) (es:List (Entry bs)) (prior:List (List Bool)) :Nat :=\n  match es with\n  | []=>1\n  | e::rest=>rowBound root bs e.1 a u edges e.2 (tape rest)\n      (SemiprimeD1StackHeapAllocate.heapBytes prior) prior.length (A.stream (A.references prior.length)).reverse+\n      sweepBound root bs a u edges rest (prior++[record a u edges e.2])\n/-- The final actual vector sentinel is physically removed before output reversal. -/\ntheorem header_end (root:R.Stack→List Bool) (hp:List Bool) (n:Nat) (hist:List Bool) :\n    Runs program 1 .header (loop root [false] hp n hist) .finishSeed (loop root [] hp n hist) :=by\n  apply one_base program _ _ (.pop (aux .reader) .finishSeed .finishSeed .parse) _ _ rfl\n  · rfl\n  · exact update_reader _ _ _ _ _ _ _ _ _ _\n/-- Whole literal pointer sweep dereferences exactly once per actual issued row,\npreserves all188 source cells and allocates complete Fresh caches in original order. -/\ntheorem rows_run (root:R.Stack→List Bool) (bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool))\n    (a u edges:Nat) (es:List (Entry bs)) (prior:List (List Bool))\n    (hh:root R.heap=E.heap bs) (hc:root (R.aux .counter)=List.replicate bs.length true)\n    (hb:∀e∈es,bs[e.1.val]=SemiprimeD1StackPhaseCacheFreshComponents.phase a u edges e.2 [false,true]) :\n    ∃q ≤ sweepBound root bs a u edges es prior,\n      Runs program q .header\n        (loop root (tape es) (SemiprimeD1StackHeapAllocate.heapBytes prior)\n          prior.length (A.stream (A.references prior.length)).reverse) .finishSeed\n        (loop root [] (SemiprimeD1StackHeapAllocate.heapBytes (prior++cached a u edges es))\n          (prior++cached a u edges es).length (A.stream (A.references (prior++cached a u edges es).length)).reverse) :=by\n  induction es generalizing prior with\n  | nil=>\n    refine ⟨1,by rfl,?_⟩\n    simpa only [cached,List.map_nil,List.append_nil,tape,A.rowTape,List.foldr_nil] using\n      header_end root (SemiprimeD1StackHeapAllocate.heapBytes prior) prior.length\n        (A.stream (A.references prior.length)).reverse\n  | cons e rest ih=>\n    obtain ⟨r,hr,h0⟩:=row_run root bs e.1 a u edges e.2 (tape rest)\n      (SemiprimeD1StackHeapAllocate.heapBytes prior) prior.length (A.stream (A.references prior.length)).reverse hh hc\n      (hb e (List.mem_cons_self))\n    obtain ⟨s,hs,h1⟩:=ih (prior++[record a u edges e.2]) (fun x hx=>hb x (List.mem_cons_of_mem _ hx))\n    have hheap:SemiprimeD1StackHeapAllocate.heapBytes (prior++[record a u edges e.2])=\n        frame (record a u edges e.2) (SemiprimeD1StackHeapAllocate.heapBytes prior):=\n      SemiprimeD1StackHeapAllocate.heapBytes_append prior (record a u edges e.2)\n    have hlen:(prior++[record a u edges e.2]).length=prior.length+1:=by\n      simp only [List.length_append,List.length_singleton]\n    rw [nextHistory_references] at h0\n    rw [hheap,hlen] at h1\n    have he:(prior++[record a u edges e.2])++cached a u edges rest=prior++cached a u edges (e::rest):=by\n      simp only [cached,List.map_cons,List.append_assoc,List.singleton_append]\n    rw [he] at h1\n    refine ⟨r+s,?_,?_⟩\n    · change r+s ≤ rowBound _ _ _ _ _ _ _ _ _ _ _+sweepBound _ _ _ _ _ _ _\n      omega\n    · exact compose h0 h1\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsLoop\n","RiemannGaussian.SemiprimeD1StackRootPhaseParameters":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseGridOriginal\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersInventory\nimport RiemannGaussian.SemiprimeD1StackHeapAllocate\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackVertexRecordStream\n/-! # N-only chronological heap of complete actual per-phase working banks\nOne whole original-input root/grid call is retained. Each actual framed binary\nphase index supplies a real working-precision call. Forty-eight paid frames cache\nits entire stopped bank, including rejected phases. A real unary heap ordinal is\nlogged and all private phase words are physically drained before the next row.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParameters\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace G\nexport SemiprimeD1StackRootPhaseGrid (Stack Label program input initial originalInput output exponent rootStack)\nend G\nnamespace P\nexport SemiprimeD1StackPhaseWorkingPrecision (Stack Label program input initial metadataStack aux)\nend P\nnamespace I\nexport SemiprimeD1StackRootPhaseParametersInventory (roles role)\nend I\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\nnamespace B\nexport SemiprimeD1StackAssignmentBody (Stack Label code entry)\nend B\nnamespace V\nexport SemiprimeD1StackVertexRecordStream (Stack Label code)\nend V\n/-- Fourteen actual reader, record, heap, ordinal and chronological-reference roles. -/\ninductive Aux where\n  | reader | index | fieldScratch | valid | copyScratch | record | recordScratch\n  | heap | counter | reference | counterScratch | refsHistory | refsOutput | refScratch\n  deriving DecidableEq,Repr\ninstance : Fintype Aux :=Fintype.ofList\n  [.reader,.index,.fieldScratch,.valid,.copyScratch,.record,.recordScratch,.heap,.counter,.reference,.counterScratch,.refsHistory,.refsOutput,.refScratch]\n  (by intro k;cases k <;> simp)\n/-- All retained126 root/grid cells, actual48 phase cells and fourteen new fields. -/\nabbrev Stack :=G.Stack⊕(P.Stack⊕Aux)\n/-- Literal retention of every actual original-input root and phase-grid cell. -/\ndef gridStack : G.Stack→Stack :=Sum.inl\n/-- Actual forty-eight-word working-precision bank; no stopped result is supplied. -/\ndef phaseStack (k:P.Stack) : Stack :=.inr (.inl k)\n/-- Fourteen disjoint new physical words. -/\ndef aux (k:Aux) : Stack :=.inr (.inr k)\n/-- Only original binary N is present at the whole front door. -/\ndef originalInput : Stack :=gridStack G.originalInput\n/-- Chronological vector of stable actual heap ordinal references. -/\ndef output : Stack :=aux .refsOutput\n/-- Retained actual heap bytes, newest framing first, logical addresses oldest first. -/\ndef heap : Stack :=aux .heap\n/-- Actual parent u0, acquired by the root source rather than its successor. -/\ndef levels : Stack :=gridStack (G.rootStack (SemiprimeD1StackRootRecursiveControl.sourceStack SemiprimeD1StackRootParameters.levels))\n/-- Actual root occurrence count M=2E, physically acquired and retained. -/\ndef edges : Stack :=gridStack (G.rootStack (SemiprimeD1StackRootRecursiveControl.sourceStack SemiprimeD1StackRootParameters.edges))\n/-- Actual phase-source exponent input. -/\ndef phaseExponent : Stack :=phaseStack (P.metadataStack (SemiprimeD1StackPhaseWorkingPrecisionMetadata.guardStack\n  (SemiprimeD1StackPhaseGeometryGuard.geometryStack (SemiprimeD1StackPhaseGeometry.aux .exponent))))\n/-- Actual phase-source parent-u input. -/\ndef phaseLevels : Stack :=phaseStack (P.metadataStack (SemiprimeD1StackPhaseWorkingPrecisionMetadata.guardStack\n  (SemiprimeD1StackPhaseGeometryGuard.aux .levels)))\n/-- Actual phase-source root-M input. -/\ndef phaseEdges : Stack :=phaseStack (P.metadataStack (SemiprimeD1StackPhaseWorkingPrecisionMetadata.aux .edges))\n/-- Actual phase-source retained binary index input. -/\ndef phaseIndex : Stack :=phaseStack (P.metadataStack (SemiprimeD1StackPhaseWorkingPrecisionMetadata.guardStack\n  (SemiprimeD1StackPhaseGeometryGuard.geometryStack (SemiprimeD1StackPhaseGeometry.aux .index))))\n/-- Actual binary root precision input; two literal writes produce [false,true]. -/\ndef phasePrecision : Stack :=phaseStack (P.metadataStack (SemiprimeD1StackPhaseWorkingPrecisionMetadata.aux .precision))\n/-- Paid copy sources are actual retained grid/root words or the physically parsed t. -/\ndef copySource (site:Fin 5) : Stack :=\n  if site=0 then gridStack G.output else if site=1 then gridStack G.exponent\n  else if site=2 then levels else if site=3 then edges else aux .index\n/-- Paid copy destinations have physically cleared prior contents. -/\ndef copyTarget (site:Fin 5) : Stack :=\n  if site=0 then aux .reader else if site=1 then phaseExponent\n  else if site=2 then phaseLevels else if site=3 then phaseEdges else phaseIndex\n/-- Each actual preserving copy uses three distinct operands. -/\ndef copyStack (site:Fin 5) (i:Fin 3) : Stack :=\n  if i=0 then copySource site else if i=1 then copyTarget site else aux .copyScratch\n/-- Actual four-stack parser consumes one field and writes its physical validity bit. -/\ndef fieldStack : F.Stack→Stack\n  | .inl .input=>aux .reader | .inl .scratch=>aux .fieldScratch\n  | .inl .output=>aux .index | .inr _=>aux .valid\n/-- Actual frame input is one finite selected stopped phase role, never a getter opcode. -/\ndef frameStack (i:Fin 48) (k:Fin 3) : Stack :=\n  if k=0 then phaseStack (I.role i) else if k=1 then aux .record else aux .copyScratch\n/-- Actual allocator receives record/heap/two scratch words/counter/reference. -/\ndef heapStack (k:Fin 6) : Stack :=\n  if k=0 then aux .record else if k=1 then aux .heap else if k=2 then aux .recordScratch\n  else if k=3 then aux .counter else if k=4 then aux .reference else aux .counterScratch\n/-- Actual restoring reference logger reads the physically acquired heap ordinal. -/\ndef bodyStack : B.Stack→Stack\n  | .word=>aux .reference | .scratch=>aux .refScratch | .history=>aux .refsHistory\n/-- One final actual reference-history reversal; both spare fields remain counted. -/\ndef reverseStack : V.Stack→Stack\n  | .ports=>aux .recordScratch | .table=>aux .refScratch\n  | .history=>aux .refsHistory | .output=>aux .refsOutput\n/-- All finite source stages and real component return labels are fixed before N. -/\ninductive Label where\n  | start | copySite (site:Fin 5) | header | parse | check | pHigh | pLow | phaseCall\n  | serialize (position:Fin 49) | allocate | logReference | clear (position:Fin 52)\n  | finishSeed | reverseCall | done | abort\n  | grid (pc:G.Label) | phase (pc:P.Label) | copy (site:Fin 5) (pc:Fin 9)\n  | field (pc:F.Label) | frame (i:Fin 48) (pc:Fin 11) | allocator (pc:Fin 22)\n  | body (pc:B.Label) | reverse (pc:V.Label)\n  deriving Fintype\n/-- Fixed stage following each of the five paid source copies. -/\ndef afterCopy (site:Fin 5) : Label :=\n  if site=0 then .header else if h:site.val<4 then .copySite ⟨site.val+1,by omega⟩ else .pHigh\n/-- Fixed drained phase role, or one of the three row-local fields. -/\ndef clearStack (i:Fin 51) : Stack :=\n  if h:i.val<48 then phaseStack (I.role ⟨i.val,h⟩)\n  else if i.val=48 then aux .index else if i.val=49 then aux .record else aux .reference\n/-- One fixed original-N program with actual parsing, acquisition, framing,\nallocation, stable-reference logging, physical cleanup and final reversal. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call (.grid (.inl .start)) (.copySite 0)\n  | .copySite site=>.call (.copy site 0) (afterCopy site)\n  | .header=>.base (.pop (aux .reader) .finishSeed .finishSeed .parse)\n  | .parse=>.call (.field (F.active .tagPop (none,false))) .check\n  | .check=>.base (.pop (aux .valid) .abort .abort (.copySite 1))\n  | .pHigh=>.base (.push phasePrecision true .pLow)\n  | .pLow=>.base (.push phasePrecision false .phaseCall)\n  | .phaseCall=>.call (.phase .start) (.serialize 0)\n  | .serialize i=>if h:i.val<48 then\n      .call (.frame ⟨47-i.val,by omega⟩ 0) (.serialize ⟨i.val+1,by omega⟩)\n      else .base (.jump .allocate)\n  | .allocate=>.call (.allocator 0) .logReference\n  | .logReference=>.call (.body B.entry) (.clear 0)\n  | .clear i=>if h:i.val<51 then\n      .base (.pop (clearStack ⟨i.val,h⟩) (.clear ⟨i.val+1,by omega⟩) (.clear i) (.clear i))\n      else .base (.jump .header)\n  | .finishSeed=>.base (.push output false .reverseCall)\n  | .reverseCall=>.call (.reverse .reverse) .done\n  | .done=>.base .halt\n  | .abort=>.base .halt\n  | .grid pc=>SemiprimeD1StackValidationLink.instruction gridStack Label.grid (G.program pc)\n  | .phase pc=>SemiprimeD1StackValidationLink.instruction phaseStack Label.phase (P.program pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (F.code pc)\n  | .frame i pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack i) (Label.frame i) (SemiprimeD1StackFrame.code pc)\n  | .allocator pc=>SemiprimeD1StackMultiplierLink.instruction heapStack Label.allocator (SemiprimeD1StackHeapAllocate.code pc)\n  | .body pc=>SemiprimeD1StackMultiplierLink.instruction bodyStack Label.body (B.code pc)\n  | .reverse pc=>SemiprimeD1StackMultiplierLink.instruction reverseStack Label.reverse (V.code pc)\n/-- Complete188-role physical bank, with no runtime list/numeric/cache instruction. -/\ndef data (root:G.Stack→List Bool) (phase:P.Stack→List Bool) (work:Aux→List Bool) : Stack→List Bool :=\n  Sum.elim root (Sum.elim phase work)\n/-- Original binary N alone; all sixty-two new roles are initially empty. -/\ndef input (bits:List Bool) : Stack→List Bool :=data (G.input bits) (fun _=>[]) (fun _=>[])\n/-- Whole N-only initial state before any root, phase or heap acquisition. -/\ndef initial (bits:List Bool) : C.State Stack Label :=⟨some .start,none,none,input bits,[]⟩\n/-- One genuine fixed finite binary machine with actual finite return cells. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine originalInput output .start program\n/-- All retained126, actual48 and fourteen private physical roles are counted. -/\ntheorem stack_card : Fintype.card Stack=188 :=by\n  rw [Fintype.card_sum,SemiprimeD1StackRootPhaseGrid.stack_card,Fintype.card_sum,SemiprimeD1StackPhaseWorkingPrecision.stack_card]\n  decide\n/-- Actual grid call retains every component role injectively. -/\ntheorem grid_injective : Function.Injective gridStack :=Sum.inl_injective\n/-- Actual phase call uses a distinct literal forty-eight-role bank. -/\ntheorem phase_injective : Function.Injective phaseStack :=by intro i j h;exact Sum.inl.inj (Sum.inr.inj h)\n/-- All five actual source copies have disjoint source/destination/scratch. -/\ntheorem copy_injective (site:Fin 5) : Function.Injective (copyStack site) :=by fin_cases site <;> decide\n/-- The actual parser's four physical operands are distinct. -/\ntheorem field_injective : Function.Injective fieldStack :=by decide\n/-- Each paid stopped-word frame has three distinct physical operands. -/\ntheorem frame_injective (i:Fin 48) : Function.Injective (frameStack i) :=by\n  intro j k h;fin_cases j <;> fin_cases k <;> simp [frameStack,aux,phaseStack] at h ⊢\n/-- All six actual allocator operands are distinct. -/\ntheorem heap_injective : Function.Injective heapStack :=by decide\n/-- Actual reference logging restores the ordinal via distinct scratch. -/\ntheorem body_injective : Function.Injective bodyStack :=by decide\n/-- The one final reference reversal has four distinct counted operands. -/\ntheorem reverse_injective : Function.Injective reverseStack :=by decide\n/-- Actual Boolean and real-return alphabets are fixed finite before N. -/\ntheorem alphabets_finite (k:machine.K) : Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _ k\n/-- Internal control contains only finite labels and flags, never numeric operands. -/\ntheorem control_finite : Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRootPhaseParameters\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersPrimitives\n/-! # Literal complete private-bank drains between chronological phase allocations -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersCleanup\nopen SemiprimeD1StackRootPhaseParameters SemiprimeD1StackRootPhaseParametersEncoding\nopen SemiprimeD1StackRootPhaseParametersPrimitives SemiprimeD1StackProcedureTrace\n/-- All actual phase roles plus the three restored row-local payloads. -/\ndef clearRoles : List Stack :=I.roles.map phaseStack++[aux .index,aux .record,aux .reference]\n/-- Exactly fifty-one physical EOF-checked drain sites. -/\ntheorem clearRoles_length : clearRoles.length=51 :=by simp only [clearRoles,List.length_append,List.length_map,SemiprimeD1StackRootPhaseParametersInventory.roles_length];rfl\n/-- The fixed cleanup instruction's role is exactly its inventory position. -/\ntheorem clearRoles_get (i:Fin 51) : clearRoles[i.val]=clearStack i :=by fin_cases i <;> rfl\n/-- Full actual data-cell mass, including all retained root and heap words. -/\ndef mass (bank:Stack→List Bool) : Nat :=∑k,(bank k).length\n/-- An actual private word is charged to the full physical data mass. -/\ntheorem word_le_mass (bank:Stack→List Bool) (k:Stack) : (bank k).length≤ mass bank :=\n  Finset.single_le_sum (f:=fun k:Stack=>(bank k).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n/-- Proof-side state after a literal finite prefix of actual private drain loops. -/\nnoncomputable def cleared (bank:Stack→List Bool) (n:Nat) : Stack→List Bool :=by\n  classical\n  exact fun k=>if k∈clearRoles.take n then [] else bank k\n/-- Before the first actual drain, no payload has changed. -/\ntheorem cleared_zero (bank:Stack→List Bool) : cleared bank 0=bank :=by funext k;simp [cleared]\n/-- Each physical EOF-checked drain advances precisely one fixed inventory position. -/\ntheorem cleared_succ (bank:Stack→List Bool) (i:Fin 51) :\n    Function.update (cleared bank i.val) (clearStack i) []=cleared bank (i.val+1) :=by\n  classical\n  have hn:i.val<clearRoles.length:=by simpa only [clearRoles_length] using i.isLt\n  have ht:=List.take_succ_eq_append_getElem hn\n  rw [clearRoles_get] at ht\n  funext k\n  by_cases he:k=clearStack i\n  · subst k\n    simp only [Function.update_same,cleared,ht,List.mem_append,List.mem_singleton,or_true,ite_true]\n  · rw [Function.update_of_ne he]\n    change (if k∈clearRoles.take i.val then [] else bank k)=(if k∈clearRoles.take (i.val+1) then [] else bank k)\n    rw [ht]\n    simp only [List.mem_append,List.mem_singleton,he,or_false]\n/-- Physical clearing cannot increase any retained or private word. -/\ntheorem cleared_le (bank:Stack→List Bool) (n:Nat) (k:Stack) : ((cleared bank n) k).length≤ mass bank :=by\n  simp only [cleared]\n  split\n  · exact Nat.zero_le _\n  · exact word_le_mass bank k\n/-- After the fixed inventory length, membership is in the whole physical drain list. -/\ntheorem cleared_full (bank:Stack→List Bool) (k:Stack) :\n    cleared bank 51 k=(@ite (List Bool) (k∈clearRoles) (Classical.propDecidable _) [] (bank k)) :=by\n  classical\n  change (if k∈clearRoles.take 51 then [] else bank k)=_\n  rw [List.take_of_length_le (show clearRoles.length≤51 by rw [clearRoles_length])]\n/-- Only the three named row-local auxiliary words are physically drained. -/\ntheorem aux_mem_iff (k:Aux) : aux k∈clearRoles ↔ k=.index ∨ k=.record ∨ k=.reference :=by\n  simp [clearRoles,phaseStack,aux]\n/-- Actual cleanup preserves all126 root cells, heap/counter/reference-history,\nreader suffix and output while clearing every phase field and row-local payload. -/\ntheorem cleared_all (root:G.Stack→List Bool) (phase:P.Stack→List Bool)\n    (reader index record heap counter reference history output:List Bool) :\n    cleared (view root phase reader index record heap counter reference history output) 51=\n      view root (fun _=>[]) reader [] [] heap counter [] history output :=by\n  classical\n  funext k\n  rw [cleared_full]\n  rcases k with k|k\n  · have hn:(Sum.inl k:Stack)∉clearRoles:=by\n      intro h\n      rcases List.mem_append.mp h with h|h\n      · obtain ⟨p,_,he⟩:=List.mem_map.mp h\n        cases he\n      · simp [aux] at h\n    rw [ite_eq_right hn]\n    rfl\n  · rcases k with k|k\n    · have hm:(phaseStack k)∈clearRoles:=\n        List.mem_append_left _ (List.mem_map.mpr ⟨k,SemiprimeD1StackRootPhaseParametersInventory.roles_complete k,rfl⟩)\n      change (if phaseStack k∈clearRoles then [] else _)=[]\n      rw [ite_eq_left hm]\n    · change (if aux k∈clearRoles then [] else work reader index record heap counter reference history output k)=_\n      simp only [aux_mem_iff]\n      cases k <;> simp [view,data,work]\n/-- Every actual word byte and every empty-field EOF is paid by this same program. -/\ntheorem sweep (remaining position:Nat) (hp:position+remaining=51) (bank:Stack→List Bool) :\n    ∃t≤remaining*(mass bank+1)+1,Runs program t (.clear ⟨position,by omega⟩) (cleared bank position)\n      .header (cleared bank 51) :=by\n  induction remaining generalizing position with\n  | zero=>\n    have he:position=51:=by omega\n    subst position\n    refine ⟨1,by omega,?_⟩\n    exact cleanup_end (cleared bank 51)\n  | succ remaining ih=>\n    have hlt:position<51:=by omega\n    let i:Fin 52:=⟨position,by omega⟩\n    have h0:=clear_call i hlt (cleared bank position)\n    have hs:=cleared_succ bank ⟨position,hlt⟩\n    rw [hs] at h0\n    obtain ⟨t,ht,h1⟩:=ih (position+1) (by omega)\n    refine ⟨((cleared bank position) (clearStack ⟨position,hlt⟩)).length+1+t,?_,compose h0 h1⟩\n    have hw:=cleared_le bank position (clearStack ⟨position,hlt⟩)\n    nlinarith\n/-- Complete literal private cleanup preserves the exact source and accumulated heap/order. -/\ntheorem cleanup_run (root:G.Stack→List Bool) (phase:P.Stack→List Bool)\n    (reader index record heap counter reference history output:List Bool) :\n    ∃t≤51*(mass (view root phase reader index record heap counter reference history output)+1)+1,\n      Runs program t (.clear 0) (view root phase reader index record heap counter reference history output)\n        .header (view root (fun _=>[]) reader [] [] heap counter [] history output) :=by\n  have hz:(⟨0,by omega⟩:Fin 52)=0:=Fin.ext rfl\n  simpa only [cleared_zero,cleared_all,hz] using\n    sweep 51 0 rfl (view root phase reader index record heap counter reference history output)\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersCleanup\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersView\n/-! # One final paid reversal emits chronological stable heap references -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersFinish\nopen SemiprimeD1StackRootPhaseParameters SemiprimeD1StackRootPhaseParametersEncoding\nopen SemiprimeD1StackRootPhaseParametersPrimitives SemiprimeD1StackRootPhaseParametersView\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- One actual final reversal consumes the whole history and retains all other roles. -/\ntheorem reverse_call (bank:Stack→List Bool) (hp:bank (aux .recordScratch)=[])\n    (ht:bank (aux .refScratch)=[]) :\n    Runs program (2*(bank (aux .refsHistory)).length+3) .reverseCall bank .done\n      (Function.update (Function.update bank (aux .refsHistory) []) (aux .refsOutput)\n        ((bank (aux .refsHistory)).reverse++bank (aux .refsOutput))) :=by\n  let before:SemiprimeD1StackBytecode.State V.Stack V.Label:=\n    ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] [] (bank (aux .refsHistory)) (bank (aux .refsOutput))⟩\n  let after:SemiprimeD1StackBytecode.State V.Stack V.Label:=\n    ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] [] ((bank (aux .refsHistory)).reverse++bank (aux .refsOutput))⟩\n  have hin:Link.DataRel reverseStack bank before.store bank:=by\n    constructor\n    · intro k;cases k\n      · exact hp\n      · exact ht\n      · rfl\n      · rfl\n    · intro k _;rfl\n  apply included_call program reverseStack Label.reverse reverse_injective V.code .reverse (fun _=>rfl)\n    .reverseCall .done rfl (2*(bank (aux .refsHistory)).length+2) before after _ _ rfl rfl\n    (SemiprimeD1StackVertexRecordStream.reverse_run _ [] [] _ none) hin\n  have h0:=Link.data_update reverseStack reverse_injective bank before.store bank hin .history []\n  have h1:=Link.data_update reverseStack reverse_injective bank _ _ h0 .output\n    ((bank (aux .refsHistory)).reverse++bank (aux .refsOutput))\n  have he:Function.update (Function.update before.store .history []) .output\n      ((bank (aux .refsHistory)).reverse++bank (aux .refsOutput))=after.store:=by\n    funext k;cases k <;> rfl\n  simpa only [he,reverseStack] using h1\n/-- Final real output seed and ONE actual reverse restore original allocation\norder. Every phase word and row-local scratch stays physically clear. -/\ntheorem finish_run (root:G.Stack→List Bool) (cached:List (List Bool)) :\n    Runs program (2*(stream (references cached.length)).length+4) .finishSeed\n      (loop root [] (SemiprimeD1StackHeapAllocate.heapBytes cached) cached.length (stream (references cached.length)).reverse)\n      .done (finished root cached) :=by\n  let bank:=loop root [] (SemiprimeD1StackHeapAllocate.heapBytes cached) cached.length (stream (references cached.length)).reverse\n  let seeded:=view root (fun _=>[]) [] [] [] (SemiprimeD1StackHeapAllocate.heapBytes cached)\n    (List.replicate cached.length true) [] (stream (references cached.length)).reverse [false]\n  have h0:Runs program 1 .finishSeed bank .reverseCall seeded:=by\n    apply one_base program _ _ (.push output false .reverseCall) _ _ rfl\n    · rfl\n    · exact update_output _ _ _ _ _ _ _ _ _ _ _\n  have h1:=reverse_call seeded rfl rfl\n  have he:Function.update (Function.update seeded (aux .refsHistory) []) (aux .refsOutput)\n      ((seeded (aux .refsHistory)).reverse++seeded (aux .refsOutput))=finished root cached:=by\n    dsimp only [seeded]\n    rw [update_history,update_output]\n    change view root (fun _=>[]) [] [] [] (SemiprimeD1StackHeapAllocate.heapBytes cached)\n      (List.replicate cached.length true) [] [] ((stream (references cached.length)).reverse.reverse++[false])=finished root cached\n    rw [List.reverse_reverse,←vector_stream]\n    rfl\n  rw [he] at h1\n  have hh:=compose h0 h1\n  change Runs program (1+(2*(stream (references cached.length)).reverse.length+3)) .finishSeed bank .done (finished root cached) at hh\n  simpa only [List.length_reverse,show 1+(2*(stream (references cached.length)).length+3)=2*(stream (references cached.length)).length+4 by omega] using hh\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersFinish\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersEncoding\n/-! # Real copied operands, complete stopped-bank frames and literal private cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersPrimitives\nopen SemiprimeD1StackRootPhaseParameters SemiprimeD1StackRootPhaseParametersEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Composition executes fragments of this same fixed188-role source program. -/\ntheorem compose {m n:Nat} {pc mid next:Label} {before middle after:Stack→List Bool}\n    (h:Runs program m pc before mid middle) (g:Runs program n mid middle next after) :\n    Runs program (m+n) pc before next after :=runs_trans program _ _ _ _ _ _ _ _ h g\n/-- The actual source and destination differ at every paid copy site. -/\ntheorem copy_target_ne_source (site:Fin 5) : copyTarget site≠copySource site :=by fin_cases site <;> decide\n/-- Each actual paid source-copy destination differs from its restoration scratch. -/\ntheorem copy_target_ne_scratch (site:Fin 5) : copyTarget site≠aux .copyScratch :=by fin_cases site <;> decide\n/-- Actual paid source copies retain all other188 data words and outer return cells. -/\ntheorem copy_call (site:Fin 5) (bank:Stack→List Bool)\n    (hd:bank (copyTarget site)=[]) (hs:bank (aux .copyScratch)=[]) :\n    Runs program (5*(bank (copySource site)).length+4) (.copySite site) bank (afterCopy site)\n      (Function.update bank (copyTarget site) (bank (copySource site))) :=by\n  apply included_call program (copyStack site) (Label.copy site) (copy_injective site)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (.copySite site) (afterCopy site) rfl\n    (5*(bank (copySource site)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (bank (copySource site)) [] [])\n    (SemiprimeD1StackCopy.done (bank (copySource site)) (bank (copySource site)++[]))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words _ [] none\n  · constructor\n    · intro i;fin_cases i\n      · rfl\n      · exact hd\n      · exact hs\n    · intro k _;rfl\n  · constructor\n    · intro i;fin_cases i\n      · change Function.update bank (copyTarget site) (bank (copySource site)) (copySource site)=_\n        simp only [Function.update_of_ne (Ne.symm (copy_target_ne_source site))]\n        rfl\n      · change Function.update bank (copyTarget site) (bank (copySource site)) (copyTarget site)=_\n        simp only [Function.update_same,List.append_nil]\n        rfl\n      · change Function.update bank (copyTarget site) (bank (copySource site)) (aux .copyScratch)=[]\n        rw [Function.update_of_ne (Ne.symm (copy_target_ne_scratch site)),hs]\n    · intro k hk\n      apply Function.update_of_ne\n      intro h\n      exact hk 1 h.symm\n/-- One physically paid stopped-word frame changes only the actual record stack. -/\ntheorem frame_call (position:Fin 49) (h:position.val<48) (bank:Stack→List Bool)\n    (hs:bank (aux .copyScratch)=[]) :\n    let i:Fin 48:=⟨47-position.val,by omega⟩\n    Runs program (6*(bank (phaseStack (I.role i))).length+5) (.serialize position) bank\n      (.serialize ⟨position.val+1,by omega⟩)\n      (Function.update bank (aux .record) (frame (bank (phaseStack (I.role i))) (bank (aux .record)))) :=by\n  dsimp only\n  let i:Fin 48:=⟨47-position.val,by omega⟩\n  apply included_call program (frameStack i) (Label.frame i) (frame_injective i)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) (.serialize position)\n    (.serialize ⟨position.val+1,by omega⟩) (by simp only [program,dite_eq_left h];rfl)\n    (6*(bank (phaseStack (I.role i))).length+4)\n    (SemiprimeD1StackFrame.state 0 none (bank (phaseStack (I.role i))) (bank (aux .record)) [])\n    (SemiprimeD1StackFrame.done (bank (phaseStack (I.role i)))\n      (frame (bank (phaseStack (I.role i))) (bank (aux .record))))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackFrame.frame_words _ _ none\n  · constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact hs\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update bank (aux .record) _ (phaseStack (I.role i))=bank (phaseStack (I.role i))\n        exact Function.update_of_ne (by simp [phaseStack,aux]) _ _\n      · change Function.update bank (aux .record) _ (aux .record)=_\n        exact Function.update_same _ _ _\n      · change Function.update bank (aux .record) _ (aux .copyScratch)=[]\n        rw [Function.update_of_ne (by decide : aux .copyScratch≠aux .record),hs]\n    · intro k hk\n      apply Function.update_of_ne\n      intro he\n      exact hk 1 he.symm\n/-- The finite serialization sentinel is one actual jump, not a count oracle. -/\ntheorem serialization_end (bank:Stack→List Bool) : Runs program 1 (.serialize 48) bank .allocate bank :=by\n  apply one_base program _ _ (.jump .allocate) _ _ rfl\n  · rfl\n  · rfl\n/-- Every private cleanup loop physically visits and consumes its complete word. -/\ntheorem clear_call (position:Fin 52) (h:position.val<51) (bank:Stack→List Bool) :\n    Runs program ((bank (clearStack ⟨position.val,h⟩)).length+1) (.clear position) bank\n      (.clear ⟨position.val+1,by omega⟩) (Function.update bank (clearStack ⟨position.val,h⟩) []) :=by\n  have hd:=SemiprimeD1StackPhysicalLoops.drain program (.clear position) (.clear ⟨position.val+1,by omega⟩)\n    (clearStack ⟨position.val,h⟩) (by simp only [program,dite_eq_left h]) bank (bank (clearStack ⟨position.val,h⟩))\n  simpa only [Function.update_eq_self] using hd\n/-- The fixed cleanup sentinel returns to the physical vector-header reader. -/\ntheorem cleanup_end (bank:Stack→List Bool) : Runs program 1 (.clear 51) bank .header bank :=by\n  apply one_base program _ _ (.jump .header) _ _ rfl\n  · rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersPrimitives\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersSerialize":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersPrimitives\n/-! # All forty-eight actual stopped words are framed in the original fixed order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersSerialize\nopen SemiprimeD1StackRootPhaseParameters SemiprimeD1StackRootPhaseParametersEncoding\nopen SemiprimeD1StackRootPhaseParametersPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Total physical cell mass of the actual forty-eight stopped phase words. -/\ndef phaseMass (bank:Stack→List Bool) : Nat :=∑k:P.Stack,(bank (phaseStack k)).length\n/-- Every framed input word is charged to the actual stopped-bank cell mass. -/\ntheorem word_le_mass (bank:Stack→List Bool) (k:P.Stack) : (bank (phaseStack k)).length≤phaseMass bank :=by\n  exact Finset.single_le_sum (f:=fun k:P.Stack=>(bank (phaseStack k)).length)\n    (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n/-- Writing record bytes cannot change any actual stopped phase word. -/\ntheorem record_phase (bank:Stack→List Bool) (word:List Bool) (k:P.Stack) :\n    Function.update bank (aux .record) word (phaseStack k)=bank (phaseStack k) :=\n  Function.update_of_ne (by simp [phaseStack,aux]) _ _\n/-- Record framing retains exactly the same stopped-bank mass. -/\ntheorem phaseMass_update (bank:Stack→List Bool) (word:List Bool) :\n    phaseMass (Function.update bank (aux .record) word)=phaseMass bank :=by\n  rfl\n/-- Proof-side finite framedPrefix of the declared complete physical record order. -/\ndef framedPrefix (n:Nat) (bank:Stack→List Bool) (tail:List Bool) : List Bool :=\n  (I.roles.take n).foldr (fun k rest=>frame (bank (phaseStack k)) rest) tail\n/-- One further finite role contributes its frame at the end of that framedPrefix. -/\ntheorem prefix_succ (n:Nat) (hn:n<48) (bank:Stack→List Bool) (tail:List Bool) :\n    framedPrefix (n+1) bank tail=framedPrefix n bank (frame (bank (phaseStack (I.role ⟨n,hn⟩))) tail) :=by\n  have hlen:n<I.roles.length:=by simpa only [SemiprimeD1StackRootPhaseParametersInventory.roles_length] using hn\n  unfold framedPrefix\n  rw [List.take_succ_eq_append_getElem hlen,List.foldr_append]\n  rfl\n/-- A paid record write retains all words used by the remaining fixed frame sites. -/\ntheorem prefix_update (n:Nat) (bank:Stack→List Bool) (word tail:List Bool) :\n    framedPrefix n (Function.update bank (aux .record) word) tail=framedPrefix n bank tail :=by\n  rfl\n/-- Exact actual reverse-position framing loop. Each source word is physically\ncopied/restored by Frame; there is one real call/return per role and one final jump. -/\ntheorem prefix_run (n:Nat) (hn:n≤48) (bank:Stack→List Bool) (hs:bank (aux .copyScratch)=[]) :\n    ∃t≤n*(6*phaseMass bank+5)+1,\n      Runs program t (.serialize ⟨48-n,by omega⟩) bank .allocate\n        (Function.update bank (aux .record) (framedPrefix n bank (bank (aux .record)))) :=by\n  induction n generalizing bank with\n  | zero=>\n    refine ⟨1,by omega,?_⟩\n    have hz:(⟨48-0,by omega⟩:Fin 49)=48:=Fin.ext rfl\n    simpa only [hz,framedPrefix,List.take_zero,List.foldr_nil,Function.update_eq_self] using serialization_end bank\n  | succ n ih=>\n    have hlt:n<48:=by omega\n    let position:Fin 49:=⟨48-(n+1),by omega⟩\n    let i:Fin 48:=⟨n,hlt⟩\n    let word:=frame (bank (phaseStack (I.role i))) (bank (aux .record))\n    let next:=Function.update bank (aux .record) word\n    have hc:=frame_call position (by dsimp [position];omega) bank hs\n    have hi:(⟨47-position.val,by dsimp [position];omega⟩:Fin 48)=i:=by apply Fin.ext;dsimp [position,i];omega\n    have hp:(⟨position.val+1,by dsimp [position];omega⟩:Fin 49)=⟨48-n,by omega⟩:=by apply Fin.ext;dsimp [position];omega\n    dsimp only at hc\n    rw [hi,hp] at hc\n    change Runs program (6*(bank (phaseStack (I.role i))).length+5) (.serialize position) bank\n      (.serialize ⟨48-n,by omega⟩) next at hc\n    have hs':next (aux .copyScratch)=[]:=by dsimp [next];rw [Function.update_of_ne (by decide : aux .copyScratch≠aux .record),hs]\n    obtain ⟨t,ht,hr⟩:=ih (by omega) next hs'\n    have hm:phaseMass next=phaseMass bank:=phaseMass_update bank word\n    rw [hm] at ht\n    have he:Function.update next (aux .record) (framedPrefix n next (next (aux .record)))=\n        Function.update bank (aux .record) (framedPrefix (n+1) bank (bank (aux .record))):=by\n      dsimp only [next]\n      rw [Function.update_same,prefix_update,Function.update_idem,prefix_succ n hlt]\n    rw [he] at hr\n    refine ⟨(6*(bank (phaseStack (I.role i))).length+5)+t,?_,compose hc hr⟩\n    have hw:=word_le_mass bank (I.role i)\n    nlinarith\n/-- Actual complete serialization has EXACTLY the entire stopped bank in the\nfixed forward role order, including all empty and rejected output fields. -/\ntheorem serialize_run (bank:Stack→List Bool) (hs:bank (aux .copyScratch)=[]) (hr:bank (aux .record)=[]) :\n    ∃t≤48*(6*phaseMass bank+5)+1,Runs program t (.serialize 0) bank .allocate\n      (Function.update bank (aux .record) (phaseRecord (fun k=>bank (phaseStack k)))) :=by\n  have h:=prefix_run 48 (by omega) bank hs\n  have hz:(⟨48-48,by omega⟩:Fin 49)=0:=Fin.ext rfl\n  simpa only [hz,framedPrefix,hr,List.take_of_length_le (by rw [SemiprimeD1StackRootPhaseParametersInventory.roles_length]),\n    phaseRecord] using h\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersSerialize\n","RiemannGaussian.SemiprimeD1StackRootRecoveryWidthPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecoveryWidthView\n/-! # Actual acquired exponent and incidence-count copies with their own physical calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootRecoveryWidthPrimitives\nopen SemiprimeD1StackRootRecoveryWidth SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Every cache/input handoff is a real preserving copy, not a semantic operand assignment. -/\ntheorem copy_call (site:Copy) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hs:before copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl (.copy site)) before (copyNext site)\n      (Function.update before (copyTarget site) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl (.copy site)) (copyNext site) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\nend RiemannGaussian.SemiprimeD1StackRootRecoveryWidthPrimitives\n","RiemannGaussian.SemiprimeD1StackRootRecursiveControlOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecursiveControlBounds\n\n/-! # Exact original root branch and child schedule from binary N alone\nOne actual finite program acquires the root operands and executes the guard\nand conditional successor. The original root network is covered for every\nfixed prefix. Recursive phases and factor recovery remain caller obligations.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackRootRecursiveControlOriginal\nopen SemiprimeD1StackRootRecursiveControl SemiprimeD1StackRootRecursiveControlEncoding\nopen SemiprimeD1StackRootRecursiveControlExecution SemiprimeD1StackRootRecursiveControlBounds\nopen SemiprimeBitArithmetic (bitValue)\nnamespace GO\nexport SemiprimeD1StackRecursiveScheduleOriginal\n  (verdict_original child_levels_original child_exponent_original)\nend GO\n/-- Every one of the108 acquired original source roles is retained literally. -/\ntheorem source_preserved (bits:List Bool) (k:P.Stack) : result bits (sourceStack k)=P.result bits k := rfl\n/-- The same original binary N survives both calls and the conditional branch. -/\ntheorem input_preserved (bits:List Bool) : result bits originalInput=bits :=\n  SemiprimeD1StackRootParametersOriginal.input_preserved bits\n/-- Actual physical root verdict agrees with the original recursive counter. -/\ntheorem verdict_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits output=[SemiprimeD1RecursiveCounter.activeTest\n      (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits)] := by\n  exact (result_projection bits hc (.inl .output)).trans\n    (GO.verdict_original (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits))\n/-- The actual conditional child valuation count is computed, or remains empty. -/\ntheorem child_levels_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits nextLevels=(if SemiprimeD1RecursiveCounter.activeTest\n      (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits) then\n        List.replicate (SemiprimeD1Schedule.levels (lambdaValue bits) 1) true else []) := by\n  exact (result_projection bits hc (.inr .nextLevels)).trans\n    (GO.child_levels_original (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits))\n/-- The actual conditional child cumulative exponent is computed, or remains empty. -/\ntheorem child_exponent_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits nextExponent=(if SemiprimeD1RecursiveCounter.activeTest\n      (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits) then\n        List.replicate (SemiprimeD1Schedule.exponent (lambdaValue bits) 1) true else []) := by\n  exact (result_projection bits hc (.inr .nextExponent)).trans\n    (GO.child_exponent_original (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits))\n/-- The acquired M equals the original incidence count at every prescribed fixed prefix. -/\ntheorem edgeValue_original (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :\n    edgeValue bits=SemiprimeD1TensorNetwork.edgeCount\n      (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed) :=\n  SemiprimeD1StackRootScopeBankOriginal.occurrence_count bits hN fixed\n/-- Every original prescribed root prefix has exactly the acquired physical branch bit. -/\ntheorem verdict_all_prefixes (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :\n    result bits output=[SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0\n      (SemiprimeD1TensorNetwork.edgeCount (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed))] := by\n  exact (verdict_original bits hc).trans (congrArg\n    (fun M=>[SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0 M])\n      (edgeValue_original bits hN fixed))\n/-- Conditional child levels agree for every original prescribed root prefix. -/\ntheorem child_levels_all_prefixes (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :\n    result bits nextLevels=(if SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0\n      (SemiprimeD1TensorNetwork.edgeCount (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) then\n        List.replicate (SemiprimeD1Schedule.levels (lambdaValue bits) 1) true else []) := by\n  exact (child_levels_original bits hc).trans (congrArg\n    (fun M=>if SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0 M then\n      List.replicate (SemiprimeD1Schedule.levels (lambdaValue bits) 1) true else [])\n      (edgeValue_original bits hN fixed))\n/-- Conditional child exponents agree for every original prescribed root prefix. -/\ntheorem child_exponent_all_prefixes (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :\n    result bits nextExponent=(if SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0\n      (SemiprimeD1TensorNetwork.edgeCount (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) then\n        List.replicate (SemiprimeD1Schedule.exponent (lambdaValue bits) 1) true else []) := by\n  exact (child_exponent_original bits hc).trans (congrArg\n    (fun M=>if SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0 M then\n      List.replicate (SemiprimeD1Schedule.exponent (lambdaValue bits) 1) true else [])\n      (edgeValue_original bits hN fixed))\n/-- One actual original-input run contains acquisition, branch, conditional schedule and real halt. -/\ntheorem source_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤10^55*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10,\n      SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) ∧\n      (∀fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool),\n        result bits output=[SemiprimeD1RecursiveCounter.activeTest (scaleValue bits) (lambdaValue bits) 0\n          (SemiprimeD1TensorNetwork.edgeCount (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed))]) ∧\n      result bits nextLevels=(if SemiprimeD1RecursiveCounter.activeTest\n        (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits) then\n          List.replicate (SemiprimeD1Schedule.levels (lambdaValue bits) 1) true else []) ∧\n      result bits nextExponent=(if SemiprimeD1RecursiveCounter.activeTest\n        (scaleValue bits) (lambdaValue bits) 0 (edgeValue bits) then\n          List.replicate (SemiprimeD1Schedule.exponent (lambdaValue bits) 1) true else []) ∧\n      result bits originalInput=bits := by\n  obtain ⟨t,ht,hr⟩:=source_run_polynomial bits hc hN\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  refine ⟨t,?_,hr,verdict_all_prefixes bits hc hN,child_levels_original bits hc,\n    child_exponent_original bits hc,input_preserved bits⟩\n  simpa only [hw] using ht\n/-- Genuine finite-machine certificate with the same complete original-input polynomial clock. -/\nnoncomputable def originalInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits)))\n      (10^55*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10) := by\n  have h:=controlInTime bits hc hN\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simpa only [hw] using h\n/-- Every original-input prefix includes all119 data roles and all actual return cells. -/\ntheorem original_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      10^58*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10 := by\n  have h:=(machine_prefix_cells bits hc hN fuel cfg hr).trans (polynomial_space bits hc hN)\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simpa only [hw] using h\nend RiemannGaussian.SemiprimeD1StackRootRecursiveControlOriginal\n","RiemannGaussian.SemiprimeD1StackRootScaleLeafArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScheduleArithmetic\nimport Mathlib.Data.Nat.Sqrt\n/-! # Exact odd-subtraction invariant and original leaf threshold specifications -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackRootScaleLeafArithmetic\n/-- The next physical odd block after k actual successful subtraction rounds. -/\ndef odd (k : Nat) : Nat :=2*k+1\n/-- The fixed scale materialized by exactly twenty actual doublings. -/\ndef scale (ell : Nat) : Nat :=2^20*ell\n/-- Exact acquired integer square root of the original acquired lambda. -/\ndef root (ell : Nat) : Nat :=Nat.sqrt (SemiprimeD1StackRootScheduleArithmetic.lambda ell)\n/-- Exact original root leaf threshold; never a runtime answer supplier. -/\ndef leaf (ell : Nat) : Nat :=scale ell/(root ell+1)+1\n/-- One successful odd subtraction preserves the complete original square invariant. -/\ntheorem subtract_invariant (n k : Nat) (h : odd k≤ n) :\n    (n-odd k)+(k+1)^2=n+k^2 :=by\n  have hn: n-odd k+odd k=n:=Nat.sub_add_cancel h\n  unfold odd at *\n  nlinarith\n/-- An actual failed odd subtraction locates the UNIQUE exact integer square root. -/\ntheorem stop_exact (n k : Nat) (h : n<odd k) : Nat.sqrt (n+k^2)=k :=by\n  have hlo:k≤ Nat.sqrt (n+k^2):=Nat.le_sqrt'.mpr (by omega)\n  have hhi:Nat.sqrt (n+k^2)<k+1:=Nat.sqrt_lt'.mpr (by unfold odd at h;nlinarith)\n  omega\n/-- The remaining physical input strictly decreases at every successful iteration. -/\ntheorem subtract_lt (n k : Nat) (h : odd k≤ n) : n-odd k<n :=by unfold odd at h ⊢;omega\n/-- A physical potential used ONLY to account for executed loop transitions. -/\ntheorem potential_decreases (n k : Nat) (h : odd k≤ n) :\n    2*(n-odd k)+(k+1)+1<2*n+k+1 :=by\n  have hn:n-odd k+odd k=n:=Nat.sub_add_cancel h\n  unfold odd at *\n  omega\n/-- Exact integer threshold equals the same old literal Schedule.leafSize. -/\ntheorem leaf_original (ell : Nat) :\n    leaf ell=SemiprimeD1Schedule.leafSize (SemiprimeD1PublicPackingReady.scale ell)\n      (SemiprimeD1StackRootScheduleArithmetic.lambda ell) :=rfl\n/-- Materialized metadata scale has the same original literal constant. -/\ntheorem scale_original (ell : Nat) : scale ell=SemiprimeD1PublicPackingReady.scale ell :=rfl\nend RiemannGaussian.SemiprimeD1StackRootScaleLeafArithmetic\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquireInputBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireEncoding\n/-! # Every selection operand is paid by the actual original-input producers\nThe row/count/dimension word bounds come from the SAME actual producer runs.\nThe complete alphabet cardinality is bounded by the exact original schedule.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquireInputBounds\nopen SemiprimeD1StackRootSelectionAcquire SemiprimeD1StackRootSelectionAcquireEncoding\nopen SemiprimeBitArithmetic (bitValue)\nnamespace B\nexport SemiprimeD1StackSourceSelectionAcquireBounds (inputSize polynomial)\nend B\n/-- Actual complete parameter-source allowance in only the original binary input length. -/\ndef parameterBound (bits:List Bool) :Nat :=10^51*(bits.length+1)^10\n/-- Only paid original-input bytes and actual whole-source clock allowances form this envelope. -/\ndef envelope (bits:List Bool) :Nat :=\n  bits.length+SemiprimeD1StackRootNetworkRowsBounds.runBound bits+parameterBound bits+1\n/-- The physical envelope is nonzero and pays each actual producer allowance. -/\ntheorem envelope_parts (bits:List Bool) :\n    1 ≤envelope bits ∧ bits.length ≤envelope bits ∧\n      SemiprimeD1StackRootNetworkRowsBounds.runBound bits ≤envelope bits ∧ parameterBound bits ≤envelope bits :=by\n  unfold envelope\n  omega\n/-- Each actual row-source result word is paid by its SAME actual source trace. -/\ntheorem root_word_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (k:R.Stack) :((rootDone bits hN).data k).length ≤envelope bits :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootNetworkRowsBounds.source_run_bounded bits hc hN\n  have h:=SemiprimeD1StackReturnLink.run_data_bound R.program t bits.length _ _\n    (SemiprimeD1StackRootNetworkRowsResources.initial_length bits) hr k\n  change ((rootDone bits hN).data k).length ≤bits.length+t at h\n  unfold envelope\n  omega\n/-- Each actual parameter result word is paid by its SAME actual source trace. -/\ntheorem parameter_word_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (k:P.Stack) :((parameterDone bits).data k).length ≤envelope bits :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootParametersBounds.source_run_polynomial bits hc hN\n  have h:=SemiprimeD1StackReturnLink.run_data_bound P.program t bits.length _ _\n    (SemiprimeD1StackRootParametersBounds.initial_role_bound bits) hr k\n  change ((parameterDone bits).data k).length ≤bits.length+t at h\n  unfold envelope parameterBound\n  omega\n/-- The actual original root alphabet cardinality is paid by the fixed original-input parameter allowance. -/\ntheorem alphabet_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    64^(dimension bits) ≤parameterBound bits :=by\n  have h:=SemiprimeD1StackRootSelectionAcquireRate.alphabet_le (bitValue bits)\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  rw [←hw] at h\n  have hp:(bits.length+1)^6 ≤(bits.length+1)^10:=Nat.pow_le_pow_right (by omega) (by decide)\n  change 64^(dimension bits) ≤10^42*(bits.length+1)^6 at h\n  exact h.trans (Nat.mul_le_mul (by norm_num: (10^42:Nat) ≤10^51) hp)\n/-- All row/count/dimension bytes and every genuinely enumerated alphabet entry are paid. -/\ntheorem selection_input_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :B.inputSize (net bits hN) (dimension bits) ≤5*envelope bits :=by\n  have hrows:(SemiprimeD1StackSourceOccurrencesEncoding.inputTape\n      (SemiprimeD1StackSourceOccurrencesEncoding.originalRows (net bits hN))).length ≤envelope bits:=by\n    have hr:(rootDone bits hN).data R.output=\n        SemiprimeD1StackSourceOccurrencesEncoding.inputTape\n          (SemiprimeD1StackSourceOccurrencesEncoding.originalRows (net bits hN)):=\n      (SemiprimeD1StackRootNetworkRowsOriginal.output_original bits hc hN [] []).trans\n        (SemiprimeD1StackSourceOccurrencesEncoding.original_input (net bits hN)).symm\n    rw [←hr]\n    exact root_word_bound bits hc hN R.output\n  have hn:=root_word_bound bits hc hN R.leftCount\n  have hnw:(rootDone bits hN).data R.leftCount=List.replicate (net bits hN).leftCount true:=\n    SemiprimeD1StackRootNetworkRowsOriginal.left_count bits hc hN [] []\n  rw [hnw,List.length_replicate] at hn\n  have ha:=parameter_word_bound bits hc hN P.exponent\n  have haw:(parameterDone bits).data P.exponent=List.replicate (dimension bits) true:=\n    SemiprimeD1StackRootParametersOriginal.exponent_original bits hc\n  rw [haw,List.length_replicate] at ha\n  change dimension bits ≤envelope bits at ha\n  have hl:64^(dimension bits) ≤envelope bits:=(alphabet_bound bits hc).trans (envelope_parts bits).2.2.2\n  have hpos:1 ≤envelope bits:=(envelope_parts bits).1\n  change (SemiprimeD1StackSourceOccurrencesEncoding.inputTape\n    (SemiprimeD1StackSourceOccurrencesEncoding.originalRows (net bits hN))).length+\n      (net bits hN).leftCount+dimension bits+64^(dimension bits)+1 ≤5*envelope bits\n  omega\n/-- The actual three-copy handoff has only the already paid producer-word lengths as costs. -/\ntheorem acquisition_copy_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :\n    SemiprimeD1StackRootSelectionAcquireInput.acquisitionCopyTime (rootDone bits hN).data (parameterDone bits).data ≤\n      27*envelope bits :=by\n  have h0:=root_word_bound bits hc hN R.output\n  have h1:=root_word_bound bits hc hN R.leftCount\n  have h2:=parameter_word_bound bits hc hN P.exponent\n  have hpos:1 ≤envelope bits:=(envelope_parts bits).1\n  unfold SemiprimeD1StackRootSelectionAcquireInput.acquisitionCopyTime\n  omega\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquireInputBounds\n","RiemannGaussian.SemiprimeD1StackScheduleActiveBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackScheduleActiveExecution\n\n/-! # Own elapsed time and complete prefix storage of the active-call decision -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackScheduleActiveBounds\nopen SemiprimeD1StackScheduleActive SemiprimeD1StackScheduleActiveExecution\n/-- Complete actual time bound, in actual retained bounded-metadata bytes. -/\ndef runBound (v:Param→Nat) : Nat := 200*(volume v+1)\n/-- Same actual program executes within its own proved input-dependent bound. -/\nnoncomputable def guardInTime (v:Param→Nat) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (start v))\n      (some (SemiprimeD1StackCalls.configuration (done v))) (runBound v) := by\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.leaf Stack.output (.inl (.left .leaf)) program\n  let h:=source_run v\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\n/-- Every retained parameter word is already paid by the physical input inventory. -/\ntheorem parameter_le (v:Param→Nat) (k:Param) : v k ≤ volume v := by\n  cases k <;> unfold volume <;> omega\n/-- A successful prefix cannot continue after the same actual final halt. -/\ntheorem prefix_fuel_le (v:Param→Nat) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (start v)=some out) : fuel ≤ runBound v := by\n  obtain ⟨t,ht,he⟩:=source_run v\n  have hf:fuel ≤ t := by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done v)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All ten physical roles, including copy/comparator work, and every real return cell. -/\ntheorem prefix_cells (v:Param→Nat) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (start v)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤ 11*(volume v+runBound v) := by\n  have hi:∀k:Stack,((start v).data k).length ≤ volume v := by\n    intro k;cases k <;> simp only [start,data,unaryWords,List.length_replicate,List.length_nil]\n    all_goals first | exact parameter_le v _ | exact Nat.zero_le _\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (volume v) (start v) out hi hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (start v) out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤ 10*(volume v+fuel) := by\n    calc\n      _ ≤ ∑_k:Stack,(volume v+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le v fuel out hr\n  omega\n/-- Same complete storage inventory at every actual compiled-machine prefix. -/\ntheorem machine_prefix_cells (v:Param→Nat) (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (start v)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 11*(volume v+runBound v) := by\n  have he:=SemiprimeD1StackCalls.run_correct Stack.leaf Stack.output\n    (.inl (.left .leaf)) program fuel (start v)\n  change (SemiprimeD1StackCalls.run program fuel (start v)).map\n    SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (start v))) at he\n  rw [hr] at he\n  cases hrun:SemiprimeD1StackCalls.run program fuel (start v) with\n  | none => rw [hrun] at he;cases he\n  | some out =>\n    rw [hrun] at he\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj he\n    subst cfg\n    exact prefix_cells v fuel out hrun\n/-- Each compiled transition uses at most four literal fundamental commands. -/\ntheorem compile_depth (pc:Label) :\n    SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤ 4 :=\n  SemiprimeD1StackCalls.compile_depth (.inl (.left .leaf):Label) (program pc)\nend RiemannGaussian.SemiprimeD1StackScheduleActiveBounds\n","RiemannGaussian.SemiprimeD1StackScheduleSuccessorExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackScheduleSuccessor\n\n/-! # Exact six-stack schedule execution with real calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 600000\nnamespace RiemannGaussian.SemiprimeD1StackScheduleSuccessorExecution\nopen SemiprimeD1StackScheduleSuccessor SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\nlocal notation \"cpy\" => (fun kind pc=>Sum.inr (kind,pc):CopyKind→Fin 9→Label)\n/-- Concatenate actual traces of this one fixed schedule program. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=\n  runs_trans program m n pc mid next before between after h g\n/-- Actual number of pairwise scan instructions, including the final empty pop. -/\ndef halfTime : List Bool→Nat\n  | [] => 1 | [_] => 2 | _::_::rest => 3+halfTime rest\n/-- Complete clock of the actual program, including all four calls and halt. -/\ndef runTime (a u:List Bool) : Nat :=\n  5*u.length+5*a.length+10*(u.length/2)+halfTime u+17\n/-- Actual halt retains both parent words and both acquired child words. -/\ndef done (a u:List Bool) : C.State Stack Label :=\n  ⟨none,none,none,result a u,[]⟩\n/-- A real preserving-copy call, with every other stack retained literally. -/\ntheorem copy_call (kind:CopyKind) (pc next:Control)\n    (hc:program (ctl pc)=.call (cpy kind 0) (ctl next))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource kind)=xs) (hy:before (copyTarget kind)=ys)\n    (hz:before .scratch=[]) :\n    Runs program (5*xs.length+4) (ctl pc) before (ctl next)\n      (Function.update before (copyTarget kind) (xs++ys)) := by\n  apply included_call program (copyStack kind) (cpy kind) (copyStack_injective kind)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc\n    (5*xs.length+3) (SemiprimeD1StackCopy.state 0 none xs ys [])\n    (SemiprimeD1StackCopy.done xs (xs++ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hz\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update before (copyTarget kind) (xs++ys) (copySource kind)=xs\n        rw [Function.update_of_ne (by cases kind <;> decide),hx]\n      · exact Function.update_self _ _ _\n      · change Function.update before (copyTarget kind) (xs++ys) .scratch=[]\n        rw [Function.update_of_ne (by cases kind <;> decide),hz]\n    · intro k hk\n      exact Function.update_of_ne (fun h=>hk 1 h.symm) _ _\n/-- Identical emitted markers commute past an already accumulated unary block. -/\ntheorem marker_bump (n:Nat) (tail:List Bool) :\n    List.replicate n true++true::tail=true::(List.replicate n true++tail) := by\n  induction n with\n  | zero => rfl\n  | succ n ih => simp only [List.replicate_succ,List.cons_append,ih]\n/-- The literal scan consumes two physical cells for every child marker.\nThe input marker bits may be arbitrary; no decoded length is consulted. -/\ntheorem half_run (reader a u q out:List Bool) :\n    Runs program (halfTime reader) (ctl .half) (data a u reader [] q out)\n      (ctl .exponent) (data a u [] [] (halfWord reader++q) out) := by\n  induction reader using List.twoStepInduction generalizing q with\n  | nil =>\n    apply one_base program (ctl .half) (ctl .exponent)\n      (.pop .reader (ctl .exponent) (ctl .second) (ctl .second)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | singleton b =>\n    have h0 : Runs program 1 (ctl .half) (data a u [b] [] q out)\n        (ctl .second) (data a u [] [] q out) := by\n      apply one_base program (ctl .half) (ctl .second)\n        (.pop .reader (ctl .exponent) (ctl .second) (ctl .second)) _ _ rfl\n      · cases b <;> rfl\n      · funext k;cases k <;> rfl\n    have h1 : Runs program 1 (ctl .second) (data a u [] [] q out)\n        (ctl .exponent) (data a u [] [] q out) := by\n      apply one_base program (ctl .second) (ctl .exponent)\n        (.pop .reader (ctl .exponent) (ctl .emit) (ctl .emit)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> rfl\n    simpa [halfTime,halfWord] using join h0 h1\n  | cons_cons b c reader ih _ =>\n    have h0 : Runs program 1 (ctl .half) (data a u (b::c::reader) [] q out)\n        (ctl .second) (data a u (c::reader) [] q out) := by\n      apply one_base program (ctl .half) (ctl .second)\n        (.pop .reader (ctl .exponent) (ctl .second) (ctl .second)) _ _ rfl\n      · cases b <;> rfl\n      · funext k;cases k <;> rfl\n    have h1 : Runs program 1 (ctl .second) (data a u (c::reader) [] q out)\n        (ctl .emit) (data a u reader [] q out) := by\n      apply one_base program (ctl .second) (ctl .emit)\n        (.pop .reader (ctl .exponent) (ctl .emit) (ctl .emit)) _ _ rfl\n      · cases c <;> rfl\n      · funext k;cases k <;> rfl\n    have h2 : Runs program 1 (ctl .emit) (data a u reader [] q out)\n        (ctl .half) (data a u reader [] (true::q) out) := by\n      apply one_base program (ctl .emit) (ctl .half)\n        (.push .nextLevels true (ctl .half)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> rfl\n    have h:=join (join (join h0 h1) h2) (ih (true::q))\n    have hn:(b::c::reader).length/2=reader.length/2+1 := by\n      simp only [List.length_cons];omega\n    simpa only [halfTime,halfWord,hn,List.replicate_succ,List.cons_append,\n      marker_bump] using h\n/-- All four real copy invocations and the scan reach the literal final halt. -/\ntheorem source_trace (a u:List Bool) :\n    Runs program (runTime a u-1) (ctl .start) (data a u [] [] [] [])\n      (ctl .done) (result a u) := by\n  have h0:=copy_call .levels .start .half rfl (data a u [] [] [] []) u [] rfl rfl rfl\n  have he0:Function.update (data a u [] [] [] []) Stack.reader (u++[])=\n      data a u u [] [] [] := by funext k;cases k <;> simp [data,Function.update]\n  simp only [copyTarget] at h0\n  rw [he0] at h0\n  have h1:=half_run u a u [] []\n  simp only [List.append_nil] at h1\n  have h2:=copy_call .exponent .exponent .first rfl\n    (data a u [] [] (halfWord u) []) a [] rfl rfl rfl\n  have he2:Function.update (data a u [] [] (halfWord u) []) Stack.nextExponent (a++[])=\n      data a u [] [] (halfWord u) a := by funext k;cases k <;> simp [data,Function.update]\n  simp only [copyTarget] at h2\n  rw [he2] at h2\n  have h3:=copy_call .nextLevels .first .last rfl\n    (data a u [] [] (halfWord u) a) (halfWord u) a rfl rfl rfl\n  have he3:Function.update (data a u [] [] (halfWord u) a) Stack.nextExponent (halfWord u++a)=\n      data a u [] [] (halfWord u) (halfWord u++a) := by funext k;cases k <;> rfl\n  simp only [copyTarget] at h3\n  rw [he3] at h3\n  have h4:=copy_call .nextLevels .last .done rfl\n    (data a u [] [] (halfWord u) (halfWord u++a)) (halfWord u) (halfWord u++a) rfl rfl rfl\n  have he4:Function.update (data a u [] [] (halfWord u) (halfWord u++a)) Stack.nextExponent\n      (halfWord u++(halfWord u++a))=result a u := by\n    funext k;cases k <;> simp [Function.update,data,result,List.append_assoc]\n  simp only [copyTarget] at h4\n  rw [he4] at h4\n  have ht:=join (join (join (join h0 h1) h2) h3) h4\n  have hc:(((5*u.length+4+halfTime u)+(5*a.length+4))+\n      (5*(halfWord u).length+4))+(5*(halfWord u).length+4)=runTime a u-1 := by\n    simp only [halfWord,List.length_replicate,runTime];omega\n  rw [hc] at ht\n  exact ht\n/-- The same fixed program halts after its own exact acquired-input clock. -/\ntheorem source_run (a u:List Bool) :\n    SemiprimeD1StackCalls.run program (runTime a u) (initial a u)=some (done a u) := by\n  obtain ⟨finish,hf,hs⟩:=source_trace a u [] (initial a u) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result a u) [] finish hs\n  have ht:runTime a u=(runTime a u-1)+1 := by unfold runTime;omega\n  rw [ht,SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\nend RiemannGaussian.SemiprimeD1StackScheduleSuccessorExecution\n","RiemannGaussian.SemiprimeD1StackScopeLeafReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafMachine\n/-! # Actual frozen leaf entry after physically acquiring the scope count\nThis corollary executes the literal makeZero entry, not binary width conversion.\nThe count is physically present in the counter register; the final scope caller\nacquires it by parsing every actual scope-bank record.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeD1StackScopeLeafReady\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState\nopen SemiprimeD1StackLeafEnumeration\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- All remaining actual leaf stages after acquiring a unary scope count. -/\ndef budget (M : ℕ) (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values) : ℕ :=\n  (2*M+1)+1+(100*(M+1)*2^M+11)+SemiprimeD1StackLeafLoop.loopBudget ctx vertices p\n    (SemiprimeD1StackAssignmentOrder.assignments (2^M) (List.replicate M false)) []+1\n\n/-- The actual acquired markers drive zero construction, complete enumeration,\nliteral tensor products and sums. No binary M word is read or supplied. -/\ntheorem ready_run (M : ℕ) (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values) (v : Values)\n    (hvertices : p .vertices=SemiprimeD1StackVertexProduct.records vertices)\n    (hreader : p .reader=[]) (hleft : p .left=[]) (hprod : p .product=[])\n    (hports : p .ports=[]) (htable : p .table=[]) (hvalid : p .valid=[]) (hout : p .result=[])\n    (hassignment : p .assignment=[]) (hc : v .counter=[]) (hz : v .zero=[])\n    (hcat : v .catalogue=[]) (hsum : v .sum=[]) (hsout : v .sumResult=[]) (hflag : v .valid=[])\n    (haxes : p .axes=vectorBits (ctx.axes.map SemiprimeD1StackUnaryDivmod.unary))\n    (hw : (p .width).length=ctx.precision) (hr : p .rank=SemiprimeD1StackUnaryDivmod.unary ctx.rank) :\n    ∃ m ≤ budget M ctx vertices p,\n      SemiprimeD1StackCalls.run program m\n        (⟨some .makeZero,none,none,data p (Function.update v .counter (List.replicate M true)),[]⟩:\n          SemiprimeD1StackCalls.State Stack Label)=\n      some (⟨none,none,none,data p (Function.update v .sum\n        (vectorBits (SemiprimeD1TensorTapeLeaf.run M ctx vertices).words)),[]⟩:\n          SemiprimeD1StackCalls.State Stack Label) := by\n  let v1:=Function.update v .zero (List.replicate M false)\n  let v2:=Function.update v1 .sum [false]\n  let catalogue:=SemiprimeD1StackAssignmentOrder.assignments (2^M) (List.replicate M false)\n  let v3:=Function.update (Function.update v2 .zero []) .catalogue (vectorBits catalogue)\n  have h1 : Runs program (2*M+1) .makeZero\n      (data p (Function.update v .counter (List.replicate M true))) .initializeSum (data p v1) := by\n    simpa [v1,hz] using zero_run p v M hc\n  have h2 : Runs program 1 .initializeSum (data p v1) .enumerate (data p v2) := by\n    simpa [v2,v1,hsum] using initialize_sum p v1\n  obtain ⟨m3,hm3,h3⟩:=enumeration_call p v2 M (by simp [v2,v1]) (by simpa [v2,v1] using hcat)\n  obtain ⟨m4,hm4,h4⟩:=SemiprimeD1StackLeafLoop.loop_run ctx hp vertices catalogue p v3 []\n    (by simp [v3]) hvertices hreader hleft hprod hports htable hvalid hout hassignment\n    (by simpa [v3,v2,v1] using hflag) (by simp [v3,v2,vectorBits])\n    (by simpa [v3,v2,v1] using hsout) haxes hw hr\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ h1 h2\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ hh h3\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ hh h4\n  obtain ⟨finish,hfinish,hfinishAt⟩:=hh []\n    (⟨some .makeZero,none,none,data p (Function.update v .counter (List.replicate M true)),[]⟩:\n      SemiprimeD1StackCalls.State Stack Label) ⟨rfl,rfl,rfl⟩\n  have hd : data p (Function.update (Function.update v3 .catalogue []) .sum\n      (vectorBits (SemiprimeD1StackLeafLoop.summed ctx vertices catalogue [])))=\n      data p (Function.update v .sum (vectorBits (SemiprimeD1TensorTapeLeaf.run M ctx vertices).words)) := by\n    apply congrArg (data p)\n    funext s\n    cases s <;> simp_all [v3,v2,v1,catalogue,SemiprimeD1StackLeafValue.summed_original M ctx hp]\n  rw [hd] at hfinishAt\n  have hhalt:=SemiprimeD1StackProcedureTrace.halt_run program .done rfl _ [] finish hfinishAt\n  refine ⟨(2*M+1)+1+m3+m4+1,?_,?_⟩\n  · unfold budget\n    change _≤(2*M+1)+1+(100*(M+1)*2^M+11)+SemiprimeD1StackLeafLoop.loopBudget ctx vertices p catalogue []+1\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some,hhalt]\n\n/-- A numerical majorant only: skipped binary-width acquisition has nonnegative\ncost. No equality or transfer of actual old/new execution clocks is asserted. -/\ntheorem budget_le_enumerated (M : ℕ) (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values) (v : Values) :\n    budget M ctx vertices p≤SemiprimeD1StackLeafSetup.enumeratedBudget M ctx vertices p v+1 := by\n  unfold budget SemiprimeD1StackLeafSetup.enumeratedBudget\n  omega\n\nend RiemannGaussian.SemiprimeD1StackScopeLeafReady\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Acquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Setup\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Calls\n/-! # Whole actual unary-marker acquisition of6a-bit counter and binary powers -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Acquisition\nopen SemiprimeD1StackSourceAlphabet64 SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64Primitives SemiprimeD1StackSourceAlphabet64Setup\nopen SemiprimeD1StackProcedureTrace\n/-- Literal saturated head exponent, including a0's actual binary ONE. -/\ndef headZeros (first:Bool) (n:Nat) :Nat :=if first then 6*(4*n-1) else 24*n\n/-- Complete marker-loop physical writes; all unrelated cells remain literal. -/\ndef fillResult (bank:Stack→List Bool) (first:Bool) (n:Nat) :Stack→List Bool :=\n  Function.update (zeros (zeros (zeros (zeros (zeros bank (enumStack .word) (6*n))\n    (aux .square) (12*n)) (aux .cube) (18*n)) (aux .fourth) (24*n))\n    (aux .head) (headZeros first n)) (aux .todo) []\n/-- The first actual marker accounts for the six-bit saturated subtraction. -/\ntheorem headZeros_succ (first:Bool) (n:Nat) :\n    headZeros first (n+1)=24*n+(if first then 18 else 24) :=by\n  cases first <;> simp only [headZeros,Bool.false_eq_true,ite_false,ite_true] <;> omega\n/-- Actual zero-push blocks combine literally; no numeric payload is re-encoded. -/\ntheorem fillResult_step (bank:Stack→List Bool) (first:Bool) (n:Nat) (tail:List Bool) :\n    fillResult (block (Function.update bank (aux .todo) tail) first) false n=fillResult bank first (n+1) :=by\n  funext k\n  cases first <;> rcases k with k|k <;> cases k <;>\n    simp [fillResult,block,zeros,enumStack,aux,headZeros,Nat.mul_add,List.replicate_add,List.append_assoc]\n  all_goals rw [show 6*(4*n)=24*n by omega]\n/-- Every actual source marker is physically consumed; all original/root width\nbytes remain retained, and every binary zero/power write is charged. -/\ntheorem fill_run (bank:Stack→List Bool) (first:Bool) (n:Nat)\n    (ht:bank (aux .todo)=List.replicate n true) :\n    ∃q ≤ 90*n+1,Runs program q (.fill first) bank .enumerate (fillResult bank first n) :=by\n  induction n generalizing bank first with\n  | zero=>\n    have he:fillResult bank first 0=Function.update bank (aux .todo) []:=by\n      cases first <;> simp [fillResult,headZeros,zeros_zero]\n    refine ⟨1,by omega,?_⟩\n    rw [he]\n    apply one_base program _ _ (.pop (aux .todo) .enumerate .abort (.pushes first .word 0)) _ _ rfl\n    · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,ht]\n    · simp [SemiprimeD1StackBytecode.execute,ht]\n  | succ n ih=>\n    let next:=Function.update bank (aux .todo) (List.replicate n true)\n    have h0:Runs program 1 (.fill first) bank (.pushes first .word 0) next:=by\n      apply one_base program _ _ (.pop (aux .todo) .enumerate .abort (.pushes first .word 0)) _ _ rfl\n      · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,ht,List.replicate_succ]\n      · simp [SemiprimeD1StackBytecode.execute,ht,List.replicate_succ,next]\n    have h1:=block_run next first\n    have htodo:block next first (aux .todo)=List.replicate n true:=by\n      simp [block,zeros,next,aux,enumStack]\n    obtain ⟨q,hq,h2⟩:=ih (block next first) false htodo\n    rw [show fillResult (block next first) false n=fillResult bank first (n+1) from fillResult_step bank first n _] at h2\n    have h:=compose (compose h0 h1) h2\n    refine ⟨_,?_,h⟩\n    cases first <;> simp only [Bool.false_eq_true,ite_false,ite_true] at * <;> omega\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Acquisition\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Source":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Acquisition\n/-! # Whole actual source prefix: retained unary width, all binary powers and real enumeration -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Source\nopen SemiprimeD1StackSourceAlphabet64 SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64Primitives SemiprimeD1StackSourceAlphabet64Setup\nopen SemiprimeD1StackSourceAlphabet64Acquisition SemiprimeD1StackSourceAlphabet64Calls\nopen SemiprimeD1StackProcedureTrace\n/-- Exact literal four-ONE seed boundary, with actual copied source markers. -/\ndef seedBank (a i:Nat) :Stack→List Bool :=Sum.elim (fun _=>[]) (fun k=>match k with\n  | .source|.todo=>List.replicate a true | .square=>if 0 < i then [true] else []\n  | .cube=>if 1 < i then [true] else [] | .fourth=>if 2 < i then [true] else []\n  | .head=>if 3 < i then [true] else [] | _=>[])\n/-- The seed table executes its four literal binary ONE pushes and last real jump. -/\ntheorem seed_run (a:Nat) :Runs program 5 (.seed 0) (seedBank a 0) (.fill true) (seedBank a 4) :=by\n  have h0:Runs program 1 (.seed 0) (seedBank a 0) (.seed 1) (seedBank a 1):=by\n    apply one_base program _ _ (.push (aux .square) true (.seed 1)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h1:Runs program 1 (.seed 1) (seedBank a 1) (.seed 2) (seedBank a 2):=by\n    apply one_base program _ _ (.push (aux .cube) true (.seed 2)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h2:Runs program 1 (.seed 2) (seedBank a 2) (.seed 3) (seedBank a 3):=by\n    apply one_base program _ _ (.push (aux .fourth) true (.seed 3)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h3:Runs program 1 (.seed 3) (seedBank a 3) (.seed 4) (seedBank a 4):=by\n    apply one_base program _ _ (.push (aux .head) true (.seed 4)) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  have h4:Runs program 1 (.seed 4) (seedBank a 4) (.fill true) (seedBank a 4):=by\n    apply one_base program _ _ (.jump (.fill true)) _ _ rfl\n    · rfl\n    · rfl\n  exact compose (compose (compose (compose h0 h1) h2) h3) h4\n/-- Exact retained actual source and acquired binary-power fields; every other auxiliary is empty. -/\ndef readyAux (a:Nat) :Aux→List Bool\n  | .source=>List.replicate a true | .square=>power (12*a) | .cube=>power (18*a)\n  | .fourth=>power (24*a) | .head=>power (6*(4*a-1)) | _=>[]\n/-- Actual6a-bit zero word is now physically present, with all scratch empty. -/\ndef ready (a:Nat) :Stack→List Bool :=Sum.elim\n  (SemiprimeD1StackAssignmentLoop.data (List.replicate (6*a) false) [] [] [] []) (readyAux a)\n/-- All source-marker and literal push stages execute from the single actual unary input word. -/\ntheorem setup_run (a:Nat) :∃q ≤ 95*a+10,\n    Runs program q .start (input (List.replicate a true)) .enumerate (ready a) :=by\n  have h0:=copy_call .width .start (.seed 0) rfl (input (List.replicate a true)) rfl rfl\n  have he:Function.update (input (List.replicate a true)) (copyStack .width 1)\n      (input (List.replicate a true) (copyStack .width 0))=seedBank a 0:=by\n    funext k;rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n  rw [he] at h0\n  have h1:=seed_run a\n  obtain ⟨q,hq,h2⟩:=fill_run (seedBank a 4) true a rfl\n  have hready:fillResult (seedBank a 4) true a=ready a:=by\n    funext k\n    rcases k with k|k\n    · cases k <;> first | rfl | exact List.append_nil _\n    · cases k <;> rfl\n  rw [hready] at h2\n  have hall:=compose (compose h0 h1) h2\n  refine ⟨_,?_,hall⟩\n  change (5*(List.replicate a true).length+4)+5+q ≤ _\n  rw [List.length_replicate]\n  omega\n/-- Exact raw-vector acquisition boundary retains the actual powers/width and empties enumerator work. -/\ndef enumerated (a:Nat) :Stack→List Bool :=Sum.elim\n  (SemiprimeD1StackAssignmentLoop.data [] [] [] [] (SemiprimeD1TensorTapeCodec.vectorBits (words a))) (readyAux a)\n/-- One literal whole unary-width source prefix REAL-calls the whole binary enumerator ONCE. -/\ntheorem prefix_run (a:Nat) :∃q ≤ 95*a+100*(6*a+1)*2^(6*a)+21,\n    Runs program q .start (input (List.replicate a true)) .copyStream (enumerated a) :=by\n  obtain ⟨q,hq,h0⟩:=setup_run a\n  obtain ⟨e,he,h1⟩:=enumerate_call (6*a) (readyAux a)\n  refine ⟨q+(e+1),by omega,compose h0 h1⟩\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Source\n","RiemannGaussian.SemiprimeD1StackSourceEnvironmentEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironment\nimport RiemannGaussian.SemiprimeSourceHistogramPrefix\nimport RiemannGaussian.SemiprimeSourceWordIdEnvironment\n/-! # Exact compact prefix-key and marked candidate-ID semantics\nAll functions in this module specify actual source-produced words. They are not\nruntime opcodes, source operands, environment getters or transported clocks.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceEnvironmentEncoding\nopen SemiprimeD1StackSourceEnvironment\nopen SemiprimeBitArithmetic (bitValue bitNat)\nopen SemiprimeSourceCompactBits (Compact)\nopen SemiprimeD1StackReduceExecution (trimReverse)\n/-- Literal output of the actual reverse/high-zero-trim sequence. -/\ndef normalize (word:List Bool) :List Bool :=trimReverse word.reverse\n/-- Actual normalization retains the exact candidate number, including padded zero. -/\ntheorem normalize_value (word:List Bool) :bitValue (normalize word)=bitValue word :=by\n  rw [normalize,SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse]\n/-- Actual normalized candidate IDs are compact. -/\ntheorem normalize_compact (word:List Bool) :Compact (normalize word) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- High-zero stripping never allocates more cells than the supplied reversed word. -/\ntheorem trimReverse_length (word:List Bool) :(trimReverse word).length≤word.length :=by\n  induction word with\n  | nil=>rfl\n  | cons b word ih=>cases b <;> simp only [trimReverse,List.length_cons,List.length_reverse] <;> omega\n/-- Padded input bytes are fully charged and their normalized output cannot grow. -/\ntheorem normalize_length (word:List Bool) :(normalize word).length≤word.length :=by\n  simpa only [normalize,List.length_reverse] using trimReverse_length word.reverse\n/-- Actual normalization agrees with the frozen original compact-prefix codec. -/\ntheorem normalize_trim (word:List Bool) :normalize word=(SemiprimeSourceCompactBits.trim word).bits :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ (normalize_compact word)\n    (SemiprimeSourceCompactBits.trim_compact word)\n  rw [normalize_value,SemiprimeSourceCompactBits.trim_value]\n/-- Actual acquired compact IDs retain their exact selected bytes. -/\ntheorem normalize_of_compact (word:List Bool) (hc:Compact word) :normalize word=word :=\n  SemiprimeSourceCompactWordIds.compact_value_injective _ _ (normalize_compact word) hc (normalize_value word)\n/-- Reversed wrapped bits receive one literal high carry bit only after the actual overflow pop. -/\ndef successorScratch (word:List Bool) :List Bool :=\n  if SemiprimeD1StackIncrement.overflow word then true::(SemiprimeD1StackIncrement.wrapped word).reverse\n  else (SemiprimeD1StackIncrement.wrapped word).reverse\n/-- Actual output of overflow/reverse/carry/trim, not an arithmetic instruction. -/\ndef successor (word:List Bool) :List Bool :=trimReverse (successorScratch word)\n/-- The physically appended high true bit has its exact binary positional value. -/\ntheorem append_true_value (word:List Bool) :bitValue (word++[true])=bitValue word+2^word.length :=by\n  induction word with\n  | nil=>simp [bitValue,bitNat]\n  | cons b word ih=>cases b <;> simp only [List.cons_append,bitValue,bitNat,ite_true,Bool.false_eq_true,ite_false,\n      ih,List.length_cons,pow_succ] <;> omega\n/-- Full actual compact successor has no numeric overflow, including the empty initial key. -/\ntheorem successor_value (word:List Bool) :bitValue (successor word)=bitValue word+1 :=by\n  have h:=SemiprimeD1StackIncrement.value_balance word\n  rw [successor,SemiprimeD1StackReduceExecution.trimReverse_value]\n  unfold successorScratch\n  cases ho:SemiprimeD1StackIncrement.overflow word with\n  | false=>simpa only [ho,Bool.false_eq_true,ite_false,List.reverse_reverse,bitNat,ite_false,Nat.mul_zero,Nat.add_zero] using h\n  | true=>\n    simp only [ite_true,List.reverse_cons,List.reverse_reverse,append_true_value,\n      SemiprimeD1StackIncrement.wrapped_length]\n    simpa only [ho,bitNat,ite_true,Nat.mul_one] using h\n/-- Every actual next key is compact, even after an all-true carry. -/\ntheorem successor_compact (word:List Bool) :Compact (successor word) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- Actual next-key storage grows by at most one physical bit. -/\ntheorem successor_length (word:List Bool) :(successor word).length≤word.length+1 :=by\n  have h:=trimReverse_length (successorScratch word)\n  unfold successor successorScratch\n  unfold successorScratch at h\n  cases ho:SemiprimeD1StackIncrement.overflow word <;>\n    simp only [ho,Bool.false_eq_true,ite_false,ite_true,List.length_cons,List.length_reverse,\n      SemiprimeD1StackIncrement.wrapped_length] at h ⊢ <;> omega\n/-- Actual prefix counter word after k paid compact increment rounds, used only in specifications. -/\ndef variableKey (k:Nat) :List Bool :=(successor^[k]) []\n/-- No key is supplied at initialization. -/\ntheorem variableKey_zero :variableKey 0=[] :=rfl\n/-- Every successive variable key comes from the same actual paid compact successor fragment. -/\ntheorem variableKey_succ (k:Nat) :variableKey (k+1)=successor (variableKey k) :=\n  Function.iterate_succ_apply' _ _ _\n/-- Actual generated key denotes its original prefix position. -/\ntheorem variableKey_value (k:Nat) :bitValue (variableKey k)=k :=by\n  induction k with\n  | zero=>rfl\n  | succ k ih=>rw [variableKey_succ,successor_value,ih]\n/-- All generated original-variable keys are compact. -/\ntheorem variableKey_compact (k:Nat) :Compact (variableKey k) :=by\n  cases k with\n  | zero=>trivial\n  | succ k=>rw [variableKey_succ];exact successor_compact _\n/-- A coarse physical-width bound is paid by the number of actual parsed prefix fields. -/\ntheorem variableKey_length (k:Nat) :(variableKey k).length≤k :=by\n  induction k with\n  | zero=>rfl\n  | succ k ih=>rw [variableKey_succ];exact (successor_length _).trans (by omega)\n/-- Compact binary variable keys cannot alias distinct original positions. -/\ntheorem variableKey_injective :Function.Injective variableKey :=by\n  intro a b h\n  have hv:=congrArg bitValue h\n  simpa only [variableKey_value] using hv\n/-- Physical true marker distinguishes a selected zero ID from a missing key. -/\ndef marked (id:List Bool) :List Bool :=true::normalize id\n/-- Newest-first selected prefix has newest-first physical dictionary rows with oldest key zero. -/\ndef prefixRows :List (List Bool)→List (List Bool×List Bool)\n  | []=>[]\n  | id::ids=>(variableKey ids.length,marked id)::prefixRows ids\n/-- The exact actual whole dictionary uses the existing first-match record codec. -/\ndef dictionary (ids:List (List Bool)) :List Bool :=L.records (prefixRows ids) []\n/-- A parsed chosen ID prepends one real row at the current physically acquired next key. -/\ntheorem dictionary_cons (id:List Bool) (ids:List (List Bool)) :\n    dictionary (id::ids)=true::SemiprimeSourceHistogramKeyBits.frame (variableKey ids.length)\n      (SemiprimeSourceHistogramKeyBits.frame (marked id) (dictionary ids)) :=rfl\n/-- Original reverse-prefix positions have the same compact next-key word as the actual source. -/\ntheorem original_nextKey (ids:List (List Bool)) :\n    variableKey ids.length=(SemiprimeSourceHistogramPrefix.acquire ids).nextKey :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ (variableKey_compact _)\n    (SemiprimeSourceHistogramPrefix.next_compact ids)\n  rw [variableKey_value,SemiprimeSourceHistogramPrefix.next_value]\nend RiemannGaussian.SemiprimeD1StackSourceEnvironmentEncoding\n","RiemannGaussian.SemiprimeD1StackSourceEnvironmentExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentPrefix\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentLookup\n/-! # Complete physical prefix acquisition and retained-cache operation entries -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceEnvironmentExecution\nopen SemiprimeD1StackSourceEnvironment SemiprimeD1StackSourceEnvironmentPrimitives\nopen SemiprimeD1StackSourceEnvironmentEncoding SemiprimeD1StackSourceEnvironmentView\nopen SemiprimeD1StackSourceEnvironmentReverse SemiprimeD1StackSourceEnvironmentPrefix\nopen SemiprimeD1StackSourceEnvironmentLookup SemiprimeD1StackSourceEnvironmentExtend\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => Label.local\n/-- Literal one-word source; the retained encoded selected prefix is newest first. -/\ndef source (ids:List (List Bool)) :C.State Stack Label :=initial (vectorBits ids)\n/-- All25words after physical whole-prefix acquisition, including the retained unnormalized input vector. -/\ndef result (ids:List (List Bool)) :Stack→List Bool :=\n  view (dictionary ids) (variableKey ids.length) [] [] (vectorBits ids) [] [] [] [] []\n/-- Complete actual clean halt, without supplied prefix count/key/dictionary/environment. -/\ndef done (ids:List (List Bool)) :C.State Stack Label :=⟨none,none,none,result ids,[]⟩\n/-- Own actual sum of initialization, realcopy, field-order reversal/transfer, real extension returns and final halt. -/\ndef timeBound (ids:List (List Bool)) :Nat :=\n  5*(vectorBits ids).length+8+reverseClock ids+\n    (4*(vectorBits ids.reverse).length+6)+oldClock 0 ids.reverse+1\n/-- Actual initialize call/return, preserving prefix copy and reversed-vector false seed. -/\ntheorem prepare_trace (pfx:List Bool) :\n    Runs program (5*pfx.length+8) (ctl .acquire) (initial pfx).data\n      (ctl .readNew) (view [false] [] [] [] pfx pfx [false] [] [] []) :=by\n  change Runs program _ _ (input pfx) _ _\n  rw [input_eq]\n  have h0:=push_run .initialize (ctl .resume) (aux .dictionary) false (view [] [] [] [] pfx [] [] [] [] []) rfl\n  change Runs program 1 _ _ _ (Function.update (view [] [] [] [] pfx [] [] [] [] []) (aux .dictionary) [false]) at h0\n  rw [view_dictionary] at h0\n  have h1:=local_call .acquire .initialize .copyPrefix rfl 1 _ _ h0\n  have h2:=copy_call .prefix .copyPrefix .seedReverse rfl (view [false] [] [] [] pfx [] [] [] [] []) pfx [] rfl rfl rfl\n  simp only [List.append_nil] at h2\n  change Runs program _ _ _ _ (Function.update (view [false] [] [] [] pfx [] [] [] [] []) (aux .reader) pfx) at h2\n  rw [view_reader] at h2\n  have h3:=push_run .seedReverse (ctl .readNew) (aux .reversedPrefix) false (view [false] [] [] [] pfx pfx [] [] [] []) rfl\n  change Runs program 1 _ _ _ (Function.update (view [false] [] [] [] pfx pfx [] [] [] []) (aux .reversedPrefix) [false]) at h3\n  rw [view_reversedPrefix] at h3\n  have h:=join (join h1 h2) h3\n  have he:(1+2)+(5*pfx.length+4)+1=5*pfx.length+8:=by omega\n  simpa only [he] using h\n/-- The complete actual source interprets a newest-first prefix by physically processing its fields oldest first. -/\ntheorem source_trace (ids:List (List Bool)) :\n    ∃q,q+1≤timeBound ids ∧ Runs program q (ctl .acquire) (source ids).data (ctl .done) (result ids) :=by\n  have h0:=prepare_trace (vectorBits ids)\n  have h1:=reverse_loop [false] [] [] (vectorBits ids) [] [] [] ids []\n  simp only [List.append_nil] at h1\n  have h2:=transfer_stream [false] [] [] (vectorBits ids) (vectorBits ids.reverse) [] [] []\n  obtain ⟨q,hq,h3⟩:=old_loop [] ids.reverse [] (vectorBits ids) [] [] []\n  simp only [List.reverse_reverse,List.append_nil] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  refine ⟨_,?_,h⟩\n  change q≤oldClock 0 ids.reverse at hq\n  unfold timeBound\n  omega\n/-- Whole physical source includes its actual final halt and clears all flags/return frames. -/\ntheorem source_run (ids:List (List Bool)) :\n    ∃q≤timeBound ids,SemiprimeD1StackCalls.run program q (source ids)=some (done ids) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace ids\n  obtain ⟨finish,hf,hAt⟩:=hr [] (source ids) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result ids) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Exact retained-cache lookup source; no computed answer/found flag is loaded. -/\ndef lookupReady (ids:List (List Bool)) (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨some (ctl .lookup),none,none,view (dictionary ids) (variableKey ids.length) chosen q pfx [] [] [] [] [],[]⟩\n/-- Exact physical lookup result, with presence separate from the compact ID and with the unread scan fully cleared. -/\ndef lookupDone (ids:List (List Bool)) (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,view (dictionary ids) (variableKey ids.length) chosen q pfx [] []\n    [decide (SemiprimeBitArithmetic.bitValue q < ids.length)] []\n    (if SemiprimeBitArithmetic.bitValue q < ids.length then SemiprimeSourceHistogramPrefix.expected ids (SemiprimeBitArithmetic.bitValue q) else []),[]⟩\n/-- Same-program preserving query source has its own paid copy/scan/drain/marker/final-halt budget. -/\ntheorem lookup_run (ids:List (List Bool)) (chosen q pfx:List Bool) :\n    ∃t≤201*(q.length+1)*((dictionary ids).length+1),\n      SemiprimeD1StackCalls.run program t (lookupReady ids chosen q pfx)=some (lookupDone ids chosen q pfx) :=by\n  obtain ⟨t,ht,hr⟩:=lookup_trace ids chosen q pfx\n  obtain ⟨finish,hf,hAt⟩:=hr [] (lookupReady ids chosen q pfx) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl _ [] finish hAt\n  refine ⟨t+1,?_,?_⟩\n  · nlinarith\n  · rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n    exact hh\n/-- The actual return instruction cleanly halts an operation whose own real caller-frame stack is empty. -/\ntheorem return_run (data:Stack→List Bool) (target:C.State Stack Label) (h:At (ctl .resume) data [] target) :\n    SemiprimeD1StackCalls.run program 1 target=some (⟨none,none,none,data,[]⟩:C.State Stack Label) :=by\n  change SemiprimeD1StackCalls.step program target=some _\n  simp only [SemiprimeD1StackCalls.step,h.1,Option.map_some,program,SemiprimeD1StackCalls.execute,h.2.1,h.2.2]\n/-- Literal extension entry reuses the acquired cache and the actual caller's selected ID. -/\ndef extendReady (ids:List (List Bool)) (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨some (ctl .extend),none,none,view (dictionary ids) (variableKey ids.length) chosen q pfx [] [] [] [] [],[]⟩\n/-- Whole retained cache after one actual chosen-ID extension, preserving the original chosen/query/prefix words. -/\ndef extendDone (ids:List (List Bool)) (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,view (dictionary (chosen::ids)) (variableKey (chosen::ids).length) chosen q pfx [] [] [] [] [],[]⟩\n/-- Same literal extension entry acquires its key from the actual compact counter and pays the real return/halt. -/\ntheorem extend_run (ids:List (List Bool)) (chosen q pfx:List Bool) :\n    ∃t≤101*(chosen.length+(variableKey ids.length).length+1),\n      SemiprimeD1StackCalls.run program t (extendReady ids chosen q pfx)=some (extendDone ids chosen q pfx) :=by\n  obtain ⟨t,ht,hr⟩:=extend_trace (extendReady ids chosen q pfx).data (dictionary ids) (variableKey ids.length)\n    chosen rfl rfl rfl (view_clear _ _ _ _ _ _ _ _ _ _)\n  dsimp only [extendReady] at hr\n  rw [view_dictionary,view_nextKey,←dictionary_cons,←variableKey_succ] at hr\n  obtain ⟨finish,hf,hAt⟩:=hr [] (extendReady ids chosen q pfx) ⟨rfl,rfl,rfl⟩\n  have hh:=return_run _ finish hAt\n  refine ⟨t+1,by omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\n/-- Literal empty-cache initialization entry, preserving the caller's actual selected/query/prefix words. -/\ndef initializeReady (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨some (ctl .initialize),none,none,view [] [] chosen q pfx [] [] [] [] [],[]⟩\n/-- Actual one-false dictionary and empty compact next key acquired by initialization. -/\ndef initializeDone (chosen q pfx:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,view [false] [] chosen q pfx [] [] [] [] [],[]⟩\n/-- Initialization physically writes the empty dictionary terminal and executes its actual return. -/\ntheorem initialize_run (chosen q pfx:List Bool) :\n    SemiprimeD1StackCalls.run program 2 (initializeReady chosen q pfx)=some (initializeDone chosen q pfx) :=by\n  have h0:=push_run .initialize (ctl .resume) (aux .dictionary) false (initializeReady chosen q pfx).data rfl\n  change Runs program 1 _ _ _ (Function.update (view [] [] chosen q pfx [] [] [] [] []) (aux .dictionary) [false]) at h0\n  rw [view_dictionary] at h0\n  obtain ⟨finish,hf,hAt⟩:=h0 [] (initializeReady chosen q pfx) ⟨rfl,rfl,rfl⟩\n  have hh:=return_run _ finish hAt\n  change SemiprimeD1StackCalls.run program (1+1) _=_\n  rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\nend RiemannGaussian.SemiprimeD1StackSourceEnvironmentExecution\n","RiemannGaussian.SemiprimeD1StackSourceEnvironmentExtend":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentCounter\n/-! # Actual chosen-ID extension of the retained prefix dictionary\nEvery payload copy, canonicalization, marker/key Frame, compact successor and\ncleanup is executed by the same finite program. No chosen index/key/count is\nsupplied to the source beyond its actual retained words.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceEnvironmentExtend\nopen SemiprimeD1StackSourceEnvironment SemiprimeD1StackSourceEnvironmentPrimitives\nopen SemiprimeD1StackSourceEnvironmentEncoding SemiprimeD1StackSourceEnvironmentCounter\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Exactly the physical temporary words required clear before an extension. -/\ndef ExtendClear (before:Stack→List Bool) :Prop :=\n  ∀k∈[Aux.markedValue,.copyWork,.copyScratch,.trimScratch,.frameScratch,.incNext,.incScratch],before (aux k)=[]\n/-- One actual extension retains all caller words except its dictionary and actual next-key counter. -/\ntheorem extend_trace (before:Stack→List Bool) (dict word chosen:List Bool)\n    (hd:before (aux .dictionary)=dict) (hw:before (aux .nextKey)=word)\n    (hc:before (aux .chosenID)=chosen) (hs:ExtendClear before) :\n    ∃q≤100*(chosen.length+word.length+1),Runs program q (ctl .extend) before (ctl .resume)\n      (Function.update (Function.update before (aux .dictionary)\n        (true::frame word (frame (marked chosen) dict))) (aux .nextKey) (successor word)) :=by\n  have hm:=hs .markedValue (by simp)\n  have hcopy:=hs .copyWork (by simp)\n  have hcs:=hs .copyScratch (by simp)\n  have ht:=hs .trimScratch (by simp)\n  have hf:=hs .frameScratch (by simp)\n  have hn:=hs .incNext (by simp)\n  have hi:=hs .incScratch (by simp)\n  let b1:=Function.update before (aux .copyWork) chosen\n  let b2:=Function.update before (aux .trimScratch) chosen.reverse\n  let b3:=Function.update before (aux .markedValue) (normalize chosen)\n  let b4:=Function.update before (aux .markedValue) (marked chosen)\n  let b5:=Function.update b4 (aux .dictionary) (frame (marked chosen) dict)\n  let b6:=Function.update b4 (aux .dictionary) (frame word (frame (marked chosen) dict))\n  let b7:=Function.update b4 (aux .dictionary) (true::frame word (frame (marked chosen) dict))\n  have h1:=copy_call .chosen .extend .reverseChosen rfl before chosen [] hc hcopy hcs\n  simp only [List.append_nil] at h1\n  change Runs program _ _ _ _ b1 at h1\n  have h2:=reverse_call .chosen .reverseChosen .trimChosen rfl b1 chosen [] rfl\n    (by simpa [b1,reverseStack,aux,Function.update] using ht)\n  simp only [List.append_nil] at h2\n  have he2:Function.update (Function.update b1 (reverseStack .chosen 0) []) (reverseStack .chosen 1) chosen.reverse=b2:=by\n    funext k\n    rcases k with k|k\n    · rfl\n    · cases k <;> simp [b1,b2,reverseStack,aux,Function.update]\n      all_goals exact hcopy\n  rw [he2] at h2\n  have h3:=trim_call .chosen .trimChosen .tagMarked rfl b2 chosen.reverse []\n    (by simpa [b2,trimStack,aux,Function.update] using hcopy)\n    (by simpa [b2,trimStack,aux,Function.update] using hf) rfl\n    (by simpa [b2,trimStack,aux,Function.update] using hm)\n  simp only [List.append_nil] at h3\n  have he3:Function.update (Function.update b2 (trimStack .chosen .scratch) []) (trimStack .chosen .output)\n      (SemiprimeD1StackReduceExecution.trimReverse chosen.reverse)=b3:=by\n    funext k\n    rcases k with k|k\n    · rfl\n    · cases k <;> simp [b2,b3,trimStack,aux,Function.update,SemiprimeD1StackSourceEnvironmentEncoding.normalize]\n      all_goals exact ht\n  rw [he3] at h3\n  have h4:=push_run .tagMarked (ctl .frameValue) (aux .markedValue) true b3 rfl\n  change Runs program 1 _ _ _ (Function.update b3 (aux .markedValue) (marked chosen)) at h4\n  simp only [b3,Function.update_idem] at h4\n  change Runs program 1 _ _ _ b4 at h4\n  have h5:=frame_call .value .frameValue .frameKey rfl b4 (marked chosen) dict rfl\n    (by simpa [b4,frameStack,aux,Function.update] using hd)\n    (by simpa [b4,frameStack,aux,Function.update] using hf)\n  change Runs program _ _ _ _ b5 at h5\n  have h6:=frame_call .key .frameKey .rowTag rfl b5 word (frame (marked chosen) dict)\n    (by simpa [b5,b4,frameStack,aux,Function.update] using hw) rfl\n    (by simpa [b5,b4,frameStack,aux,Function.update] using hf)\n  change Runs program _ _ _ _ (Function.update b5 (aux .dictionary) (frame word (frame (marked chosen) dict))) at h6\n  simp only [b5,Function.update_idem] at h6\n  change Runs program _ _ _ _ b6 at h6\n  have h7:=push_run .rowTag (ctl .increment) (aux .dictionary) true b6 rfl\n  change Runs program 1 _ _ _ (Function.update b6 (aux .dictionary) (true::frame word (frame (marked chosen) dict))) at h7\n  simp only [b6,Function.update_idem] at h7\n  change Runs program 1 _ _ _ b7 at h7\n  obtain ⟨q,hq,h8⟩:=counter_run b7 word\n    (by simpa [b7,b4,aux,Function.update] using hw)\n    (by simpa [b7,b4,aux,Function.update] using hn)\n    (by simpa [b7,b4,aux,Function.update] using hi)\n    (by simpa [b7,b4,aux,Function.update] using ht)\n    (by simpa [b7,b4,aux,Function.update] using hcopy)\n    (by simpa [b7,b4,aux,Function.update] using hf)\n  have h9:=drain_loop .clearMarked (ctl .resume) (aux .markedValue) rfl\n    (Function.update b7 (aux .nextKey) (successor word)) (marked chosen)\n    (by simp [b7,b4,aux,Function.update])\n  have he9:Function.update (Function.update b7 (aux .nextKey) (successor word)) (aux .markedValue) []=\n      Function.update (Function.update before (aux .dictionary) (true::frame word (frame (marked chosen) dict)))\n        (aux .nextKey) (successor word):=by\n    funext k\n    rcases k with k|k\n    · rfl\n    · cases k <;> simp [b7,b4,aux,Function.update]\n      all_goals exact hm\n  rw [he9] at h9\n  have h:=join (join (join (join (join (join (join (join h1 h2) h3) h4) h5) h6) h7) h8) h9\n  refine ⟨_,?_,h⟩\n  have htrim:=SemiprimeD1StackReduceExecution.trimTime_le chosen.reverse\n  have hnorm:=normalize_length chosen\n  simp only [List.length_reverse] at htrim\n  simp only [marked,List.length_cons] at *\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceEnvironmentExtend\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCandidate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectParse\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectEvaluate\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectIncumbent\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectRestore\n/-! # One complete actual temporary candidate step\nThe fixed program parses both actual catalogue fields, extends the actual old\ndictionary, calls the closed incidence source, retains only strict improvement,\nand physically removes its temporary head and restores the acquired saved key.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCandidate\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackSourceIncidenceSelectView SemiprimeD1StackProcedureTrace\nnamespace E\nexport SemiprimeD1StackSourceEnvironmentEncoding (variableKey)\nend E\nlocal notation \"ctl\" => Label.local\n/-- Exact word emitted by the real closed query after installing this actual candidate. -/\ndef scoreWord (ids:List (List Bool)) (id:List Bool) (rows:List (List Bool×List Bool))\n    (square cube fourth:List Bool) :List Bool :=\n  SemiprimeD1StackSourceIncidenceSpec.total (id::ids) square cube fourth rows\n/-- Finite first-candidate control and actual strict improvement determine the retained word pair. -/\ndef nextBest (first:Bool) (oldID oldScore id newScore:List Bool) :List Bool×List Bool :=\n  if first then (id,newScore) else SemiprimeD1StackSourceIncidenceSelectSpec.scoredPick (oldID,oldScore) (id,newScore)\n/-- Own actual primitive/call cap, including complete47-role query and both physical rollback fields. -/\ndef candidateBound (ids:List (List Bool)) (id colour pfx:List Bool) (rows:List (List Bool×List Bool))\n    (square cube fourth oldID oldScore:List Bool) :Nat :=\n  (8*id.length+9*colour.length+18)+\n    (101*(id.length+(E.variableKey ids.length).length+1)+\n      SemiprimeD1StackSourceIncidenceExecution.runBound\n        (SemiprimeD1StackSourceIncidenceSelectEvaluate.scoreInputs ids id pfx rows square cube fourth)+2)+\n    100*(id.length+(scoreWord ids id rows square cube fourth).length+oldID.length+oldScore.length+1)+\n    50*((E.variableKey ids.length).length+id.length+1)\n/-- Complete candidate step preserves the exact old dictionary/key/prefix and physically retains the exact best pair. -/\ntheorem candidate_run (first:Bool) (ids:List (List Bool))\n    (pfx:List Bool) (rows:List (List Bool×List Bool))\n    (square cube fourth catalogue owners factors todo oldID oldScore id colour:List Bool)\n    (tail:List (List Bool×List Bool)) (hfirst:first=true → oldID=[] ∧ oldScore=[]) :\n    ∃t ≤ candidateBound ids id colour pfx rows square cube fourth oldID oldScore,\n      Runs program t (ctl (.header first))\n        (clean ids [] pfx (SemiprimeD1StackOwnerLookup.records rows []) square cube fourth catalogue owners factors todo\n          (SemiprimeD1StackOwnerLookup.records ((id,colour)::tail) []) (E.variableKey ids.length) oldID oldScore [])\n        (ctl (.header false))\n        (clean ids [] pfx (SemiprimeD1StackOwnerLookup.records rows []) square cube fourth catalogue owners factors todo\n          (SemiprimeD1StackOwnerLookup.records tail []) (E.variableKey ids.length)\n          (nextBest first oldID oldScore id (scoreWord ids id rows square cube fourth)).1\n          (nextBest first oldID oldScore id (scoreWord ids id rows square cube fourth)).2 []) :=by\n  let stream:=SemiprimeD1StackOwnerLookup.records rows []\n  let reader:=SemiprimeD1StackOwnerLookup.records tail []\n  let key:=E.variableKey ids.length\n  let newScore:=scoreWord ids id rows square cube fourth\n  have h0:=SemiprimeD1StackSourceIncidenceSelectParse.candidate_run first ids pfx stream square cube fourth catalogue owners factors\n    todo key oldID oldScore id colour tail\n  obtain ⟨t1,ht1,h1⟩:=SemiprimeD1StackSourceIncidenceSelectEvaluate.evaluate_run first ids id pfx rows square cube fourth\n    catalogue owners factors todo reader key oldID oldScore\n  have hi:∃t ≤ 100*(id.length+newScore.length+oldID.length+oldScore.length+1),\n      Runs program t (ctl (.acquired first))\n        (clean (id::ids) id pfx stream square cube fourth catalogue owners factors todo reader key oldID oldScore newScore)\n        (ctl .rollbackTag)\n        (clean (id::ids) id pfx stream square cube fourth catalogue owners factors todo reader key\n          (nextBest first oldID oldScore id newScore).1 (nextBest first oldID oldScore id newScore).2 []):=by\n    cases first with\n    | false=>\n      exact SemiprimeD1StackSourceIncidenceSelectIncumbent.later_run (id::ids) id pfx stream square cube fourth\n        catalogue owners factors todo reader key oldID oldScore newScore\n    | true=>\n      obtain ⟨rfl,rfl⟩:=hfirst rfl\n      exact ⟨_,by omega,SemiprimeD1StackSourceIncidenceSelectIncumbent.first_run (id::ids) id pfx stream square cube fourth\n        catalogue owners factors todo reader key newScore⟩\n  obtain ⟨t2,ht2,h2⟩:=hi\n  obtain ⟨t3,ht3,h3⟩:=SemiprimeD1StackSourceIncidenceSelectRestore.restore_run ids id pfx stream square cube fourth catalogue owners factors\n    todo reader (nextBest first oldID oldScore id newScore).1 (nextBest first oldID oldScore id newScore).2\n  have h:=join (join (join h0 h1) h2) h3\n  refine ⟨_,?_,h⟩\n  unfold candidateBound\n  dsimp only [newScore,key] at ht2 ht3\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCandidate\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCompare":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectPrimitives\n/-! # Real paid strict comparison of the acquired and retained score words\nOnly actual preserving copies feed the real five-role WordLess source. Its\ncomputed Boolean is physically popped; the whole other bank, including both\nactual candidate/score words and every caller return, survives this fragment.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCompare\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Complete63-role comparison bank; all other60 words retain their actual prior values. -/\ndef view (retained:Stack→List Bool) (left right result:List Bool) :Stack→List Bool :=\n  fun k=>if k=aux .compareLeft then left else if k=aux .compareRight then right\n    else if k=aux .compareOutput then result else retained k\n/-- One actual left comparison update preserves every other physical stack. -/\ntheorem update_left (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) (aux .compareLeft) word=view retained word right result :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual right comparison update preserves every other physical stack. -/\ntheorem update_right (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) (aux .compareRight) word=view retained left word result :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual result comparison update preserves every other physical stack. -/\ntheorem update_result (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) (aux .compareOutput) word=view retained left right word :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- A later candidate is compared ONLY by actual source words, with no supplied score-order Boolean. -/\ntheorem compare_run (retained:Stack→List Bool) (newScore oldScore:List Bool)\n    (hn:retained score=newScore) (ho:retained (aux .bestScore)=oldScore)\n    (hc:retained (aux .copyScratch)=[]) (hs:retained (aux .compareScratch)=[])\n    (hd:retained (aux .discard)=[]) :\n    Runs program (5*newScore.length+5*oldScore.length+\n        SemiprimeD1StackWordLessExecution.totalTime newScore oldScore+10)\n      (ctl (.acquired false)) (view retained [] [] [])\n      (ctl (if SemiprimeD1StackWordLessExecution.answer newScore oldScore then .clearBestID else .clearScore))\n      (view retained [] [] []) :=by\n  have h0:=copy_call .scoreOperand (.acquired false) .copyBestOperand rfl\n    (view retained [] [] []) newScore [] hn rfl hc\n  change Runs program _ _ _ _\n    (Function.update (view retained [] [] []) (aux .compareLeft) (newScore++[])) at h0\n  rw [List.append_nil,update_left] at h0\n  have h1:=copy_call .bestOperand .copyBestOperand .compare rfl\n    (view retained newScore [] []) oldScore [] ho rfl hc\n  change Runs program _ _ _ _\n    (Function.update (view retained newScore [] []) (aux .compareRight) (oldScore++[])) at h1\n  rw [List.append_nil,update_right] at h1\n  have h2:=less_call (view retained newScore oldScore []) newScore oldScore rfl rfl hs hd rfl\n  rw [update_left,update_right,update_result] at h2\n  have h3:=pop_run .compared (ctl .abort) (ctl .clearScore) (ctl .clearBestID) (aux .compareOutput)\n    (view retained [] [] [SemiprimeD1StackWordLessExecution.answer newScore oldScore])\n    [SemiprimeD1StackWordLessExecution.answer newScore oldScore] rfl rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view retained [] [] [SemiprimeD1StackWordLessExecution.answer newScore oldScore]) (aux .compareOutput) []) at h3\n  rw [update_result] at h3\n  have hp:SemiprimeD1StackBytecode.choose (ctl .abort) (ctl .clearScore) (ctl .clearBestID)\n      [SemiprimeD1StackWordLessExecution.answer newScore oldScore].head?=\n      ctl (if SemiprimeD1StackWordLessExecution.answer newScore oldScore then .clearBestID else .clearScore):=by\n    cases SemiprimeD1StackWordLessExecution.answer newScore oldScore <;> rfl\n  rw [hp] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  have ht:(5*newScore.length+4)+(5*oldScore.length+4)+\n      (SemiprimeD1StackWordLessExecution.totalTime newScore oldScore+1)+1=\n      5*newScore.length+5*oldScore.length+SemiprimeD1StackWordLessExecution.totalTime newScore oldScore+10:=by omega\n  simpa only [ht] using h\n/-- The actual paid comparison costs a fixed linear function of physical score byte widths. -/\ntheorem compare_time_le (newScore oldScore:List Bool) :\n    5*newScore.length+5*oldScore.length+SemiprimeD1StackWordLessExecution.totalTime newScore oldScore+10 ≤\n      22*(newScore.length+oldScore.length+1) :=by\n  have h:=SemiprimeD1StackWordLessExecution.totalTime_le newScore oldScore\n  omega\n/-- A clean comparison view restores exactly the original complete caller bank. -/\ntheorem view_empty (retained:Stack→List Bool) (hl:retained (aux .compareLeft)=[])\n    (hr:retained (aux .compareRight)=[]) (ho:retained (aux .compareOutput)=[]) :\n    view retained [] [] []=retained :=by\n  funext k\n  by_cases h0:k=aux .compareLeft\n  · subst k\n    simp only [view,ite_true]\n    exact hl.symm\n  · by_cases h1:k=aux .compareRight\n    · subst k\n      simp only [view,h0,ite_false,ite_true]\n      exact hr.symm\n    · by_cases h2:k=aux .compareOutput\n      · subst k\n        simp only [view,h0,h1,ite_false,ite_true]\n        exact ho.symm\n      · simp only [view,h0,h1,h2,ite_false]\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCompare\n","RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyCounterEntry":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyCounter\n/-! # Reusable actual binary increment entry with a genuine final return -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyCounterEntry\nopen SemiprimeD1StackSourceKeyFrequency SemiprimeD1StackSourceKeyFrequencyCounter\nopen SemiprimeD1StackProcedureTrace\n/-- Only the actual input word and fresh seven counter operands constrain this real-ret entry; all other physical words are retained. -/\ntheorem source_run (before:Stack→List Bool) (word:List Bool)\n    (hw:before oldCount=word) (hn:before (aux .incNext)=[])\n    (hi:before (aux .incScratch)=[]) (ht:before (aux .trimScratch)=[])\n    (ho:before (aux .count)=[]) (hc:before (lookupStack (.inl .left))=[]) (hf:before (lookupStack (.inl .right))=[]) :\n    ∃q≤40*(word.length+1)+1,SemiprimeD1StackCalls.run program q\n      (⟨some .increment,none,none,before,[]⟩:C.State Stack Label)=some\n      ⟨none,none,none,Function.update (Function.update before oldCount []) (aux .count)\n        (SemiprimeD1StackSourceEnvironmentEncoding.successor word),[]⟩ :=by\n  obtain ⟨q,hq,hr⟩:=counter_run before word hw hn hi ht ho hc hf\n  obtain ⟨finish,hfin,hAt⟩:=hr [] ⟨some .increment,none,none,before,[]⟩ ⟨rfl,rfl,rfl⟩\n  refine ⟨q+1,by omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hfin,Option.bind_some]\n  change SemiprimeD1StackCalls.step program finish=_\n  simp only [SemiprimeD1StackCalls.step,hAt.1,Option.map_some,program,SemiprimeD1StackCalls.execute,hAt.2.1,hAt.2.2]\nend RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyCounterEntry\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireCalls\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireSelectorInput\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireKeyInput\n/-! # Original typed-row family of the actual three-input source\nNetworks, lists, counts and original native runs below are proof descriptions\nof the physical input/output banks. None is accepted by the literal program.\nThe caller must acquire the original row/n/a bytes; this source pays all later\noccurrence, factor-count, alphabet, selection and selected-key construction.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireEncoding\nopen SemiprimeD1StackSourceSelectionAcquire SemiprimeD1StackSourceSelectionAcquireSelectorInput\nopen SemiprimeD1StackSourceSelectionAcquireKeyInput\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace N\nexport SemiprimeD1TensorNetwork (Network arity owner)\nend N\nattribute [local irreducible] SemiprimeD1IncidenceSearch.run SemiprimeD1IncidenceAcquisition.acquire\n/-- Exact original physical binary-owner rows, with all original local-slot occurrences preserved. -/\ndef originalRows (net:N.Network) :List (List (List Bool)) :=SemiprimeD1StackSourceOccurrencesEncoding.originalRows net\n/-- Actual complete21-role acquired occurrence/F/M result. -/\ndef occurrenceDone (net:N.Network) :C.State Occ.Stack Occ.Label :=\n  SemiprimeD1StackSourceOccurrencesExecution.done net.leftCount (originalRows net)\n/-- Actual acquired30-role original alphabet/power result. -/\ndef alphabetDone (a:Nat) :C.State Alpha.Stack Alpha.Label :=SemiprimeD1StackSourceAlphabet64Encoding.done a\n/-- Actual original63-role selector entry from the original occurrence and acquired alphabet ABIs. -/\ndef selectorSource (net:N.Network) (a:Nat) :C.State Select.Stack Select.Label :=\n  SemiprimeD1StackSourceIncidenceSelectOriginal.acquiredSource net.leftCount net.rows.length a\n    (N.arity net.rows) (N.owner net.rows)\n/-- Exact actual stopped63-role source, preserving its complete selected cache. -/\ndef selectorDone (net:N.Network) (a:Nat) :C.State Select.Stack Select.Label :=\n  SemiprimeD1StackSourceIncidenceSelectOriginal.acquiredDone net.leftCount net.rows.length a\n    (N.arity net.rows) (N.owner net.rows)\n/-- Exact original newest-first IDs, used only to specify the reached cache/prefix. -/\ndef selectedIDs (net:N.Network) (a:Nat) :List (List Bool) :=\n  (SemiprimeD1IncidenceSearch.run net.leftCount net.rows.length 64 a (N.arity net.rows) (N.owner net.rows)).value\n/-- Proof interpretation of the actual stopped cache and actual original occurrence bytes. -/\ndef keyInput (net:N.Network) (a:Nat) :SemiprimeD1StackSourceSelectedKeysEncoding.Inputs :=\n  SemiprimeD1StackSourceSelectedKeysOriginal.originalInput net.leftCount net.rows.length 64 a\n    (N.arity net.rows) (N.owner net.rows) [] [] (vectorBits (selectedIDs net a))\n/-- The entire actual39-role selected-key source stop, including every retained cache word. -/\ndef keyDone (net:N.Network) (a:Nat) :C.State Keys.Stack Keys.Label :=\n  SemiprimeD1StackSourceSelectedKeysEncoding.done (keyInput net a)\n/-- Actual initial configuration contains ONLYthe original nested row, unary n and unary a words. -/\ndef source (net:N.Network) (a:Nat) :C.State Stack Label :=\n  initial (SemiprimeD1StackSourceOccurrencesEncoding.inputTape (originalRows net))\n    (List.replicate net.leftCount true) (List.replicate a true)\n/-- All154 actual acquired/cache/selected/output/shadow fields at the complete whole source stop. -/\ndef result (net:N.Network) (a:Nat) :Stack→List Bool :=\n  data (occurrenceDone net).data (alphabetDone a).data (selectorDone net a).data (keyDone net a).data []\n/-- Genuine final halt; no source/work/return word is silently reset. -/\ndef done (net:N.Network) (a:Nat) :C.State Stack Label :=⟨none,none,none,result net a,[]⟩\n/-- Own original selector allowance in ONLYits actual acquired physical input bytes. -/\ndef selectorBound (net:N.Network) (a:Nat) :Nat :=\n  10^30*(SemiprimeD1StackSourceIncidenceSelectOriginal.acquiredSize net.leftCount net.rows.length a\n    (N.arity net.rows) (N.owner net.rows)+1)^16\n/-- Own whole source clock retains every one of the four actual producer/consumer clocks and all eleven copies. -/\ndef timeBound (net:N.Network) (a:Nat) :Nat :=\n  SemiprimeD1StackSourceOccurrencesExecution.timeBound net.leftCount (originalRows net)+\n    10000*(a+1)*(64^a+1)+selectorCopyTime (occurrenceDone net).data (alphabetDone a).data+\n    selectorBound net a+keyCopyTime (selectorDone net a).data+\n    SemiprimeD1StackSourceSelectedKeysBounds.polynomial (keyInput net a)+5\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireEncoding\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireExecution\n/-! # Entire original selected-key acquisition and retained actual source banks\nThe expected native runs below are mathematical meanings only. Every actual\noccurrence, factor counter, alphabet/power, selector/cache and key has already\nbeen constructed by the SAME literal three-input program in source_run.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireOriginal\nopen SemiprimeD1StackSourceSelectionAcquire SemiprimeD1StackSourceSelectionAcquireEncoding\nopen SemiprimeD1StackSourceSelectionAcquireExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nattribute [local irreducible] SemiprimeD1IncidenceSearch.run SemiprimeD1IncidenceAcquisition.acquire\n/-- The whole acquired output is EXACTthe original incidence acquisition key vector, in its original occurrence order. -/\ntheorem output_original (net:N.Network) (a:Nat) :\n    result net a (keyStack (Keys.aux .output))=\n      vectorBits (SemiprimeD1IncidenceAcquisition.acquire net.leftCount net.rows.length 64 a\n        (N.arity net.rows) (N.owner net.rows)).keys :=\n  SemiprimeD1StackSourceSelectedKeysOriginal.output_original net.leftCount net.rows.length 64 a\n    (N.arity net.rows) (N.owner net.rows) [] [] (vectorBits (selectedIDs net a))\n/-- Every21-role original row/count/key/helper field remains physically retained. -/\ntheorem occurrence_retained (net:N.Network) (a:Nat) (k:Occ.Stack) :\n    result net a (occurrenceStack k)=(occurrenceDone net).data k :=rfl\n/-- Every30-role original alphabet, colour row and binary power field remains physically retained. -/\ntheorem alphabet_retained (net:N.Network) (a:Nat) (k:Alpha.Stack) :\n    result net a (alphabetStack k)=(alphabetDone a).data k :=rfl\n/-- Every63-role selected/query/cache field remains retained for subsequent real packet construction. -/\ntheorem selector_retained (net:N.Network) (a:Nat) (k:Select.Stack) :\n    result net a (selectorStack k)=(selectorDone net a).data k :=rfl\n/-- Every39-role selected-key source/cache/helper field has its exact whole-source value. -/\ntheorem key_retained (net:N.Network) (a:Nat) (k:Keys.Stack) :\n    result net a (keyStack k)=(keyDone net a).data k :=rfl\n/-- The original factor count, including every empty factor, is acquired internally by the actual prescan. -/\ntheorem factor_count (net:N.Network) (a:Nat) :\n    result net a (occurrenceStack .factors)=List.replicate net.rows.length true :=\n  SemiprimeD1StackSourceOccurrencesOriginal.factor_count net\n/-- Actual original unary n is retained rather than supplied as a decoded runtime counter. -/\ntheorem number_retained (net:N.Network) (a:Nat) :\n    result net a (occurrenceStack .number)=List.replicate net.leftCount true :=rfl\n/-- The actual unary alphabet dimension remains available for a paid packet-padding source. -/\ntheorem dimension_retained (net:N.Network) (a:Nat) :\n    result net a (alphabetStack (Alpha.aux .source))=List.replicate a true :=rfl\n/-- Complete selected Env25 is exactly the reached original full-selection dictionary/key/prefix state. -/\ntheorem environment_original (net:N.Network) (a:Nat) (k:Env.Stack) :\n    result net a (selectorStack (SemiprimeD1StackSourceIncidenceSelect.environmentStack k))=\n      SemiprimeD1StackSourceEnvironmentExecution.result (selectedIDs net a) k :=\n  SemiprimeD1StackSourceIncidenceSelectOriginal.acquired_environment net.leftCount net.rows.length a\n    (N.arity net.rows) (N.owner net.rows) k\n/-- Physical input ABI is the upstream original row output plus actual unary n/a, with no F or derived cache. -/\ntheorem input_rows (net:N.Network) (a:Nat) :\n    (source net a).data (occurrenceStack .rows)=SemiprimeD1StackNetworkRowsEncoding.originalTape net :=\n  SemiprimeD1StackSourceOccurrencesEncoding.original_input net\n/-- Whole exact original acquisition has its own actual complete-source clock, never an old transported report. -/\ntheorem source_original (net:N.Network) (a:Nat) :\n    ∃t ≤ timeBound net a,SemiprimeD1StackCalls.run program t (source net a)=some (done net a) ∧\n      (done net a).data (keyStack (Keys.aux .output))=\n        vectorBits (SemiprimeD1IncidenceAcquisition.acquire net.leftCount net.rows.length 64 a\n          (N.arity net.rows) (N.owner net.rows)).keys :=by\n  obtain ⟨t,ht,he⟩:=source_run net a\n  exact ⟨t,ht,he,output_original net a⟩\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireOriginal\n","RiemannGaussian.SemiprimeD1StackStaticTableEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticTableSpec\n/-! # Every actual literal static-checker scalar code push\nOnly the already physically computed singleton checker bit selects the fixed\nzero/one branch. These are integral local entries before any network product.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticTableEmit\nopen SemiprimeD1StackStaticTable SemiprimeD1StackStaticTableSpec SemiprimeD1StackProcedureTrace\nopen SemiprimeD1BooleanTreeStream (leafBytes)\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- The actual output bit selects a fixed finite scalar-code branch. -/\ndef emitStart (b : Bool) : Label L s.roles.length := if b then .one 0 else .zero 0\n/-- Next literal zero-code label, fixed before N. -/\ndef zeroNext (pos : Fin 4) : Label L s.roles.length :=\n  if h:pos.val<3 then .zero ⟨pos.val+1,by omega⟩ else .leafCleanup\n/-- Next literal one-code label, fixed before N. -/\ndef oneNext (pos : Fin 6) : Label L s.roles.length :=\n  if h:pos.val<5 then .one ⟨pos.val+1,by omega⟩ else .leafCleanup\n/-- One actual zero-leaf push preserves the full still-live checker store. -/\ntheorem zero_step (pos : Fin 4) (live : K→List Bool) (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) 1 (.zero pos) (withChecker (data original bank 0 front hist) live) (zeroNext s pos)\n      (withChecker (data original bank 0 front (zeroBits pos::hist)) live) := by\n  apply one_base (program s) (.zero pos) (zeroNext s pos) (.push (aux .reversed) (zeroBits pos) (zeroNext s pos)) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n/-- One actual accepted-leaf push preserves every still-live checker byte. -/\ntheorem one_step (pos : Fin 6) (live : K→List Bool) (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) 1 (.one pos) (withChecker (data original bank 0 front hist) live) (oneNext s pos)\n      (withChecker (data original bank 0 front (oneBits pos::hist)) live) := by\n  apply one_base (program s) (.one pos) (oneNext s pos) (.push (aux .reversed) (oneBits pos) (oneNext s pos)) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n/-- Complete scalar/tree/vector/word/end framing, with every bit actually\nwritten. No coefficient getter or already-reduced aggregate is substituted. -/\ntheorem emit_run (b : Bool) (live : K→List Bool) (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) (leafBytes b).length (emitStart s b) (withChecker (data original bank 0 front hist) live) .leafCleanup\n      (withChecker (data original bank 0 front ((leafBytes b).reverse++hist)) live) := by\n  cases b with\n  | false=>\n    have h0:=zero_step s 0 live original bank front hist\n    have h1:=zero_step s 1 live original bank front (false::hist)\n    have h2:=zero_step s 2 live original bank front (true::false::hist)\n    have h3:=zero_step s 3 live original bank front (false::true::false::hist)\n    exact runs_trans (program s) _ _ _ _ _ _ _ _\n      (runs_trans (program s) _ _ _ _ _ _ _ _ (runs_trans (program s) _ _ _ _ _ _ _ _ h0 h1) h2) h3\n  | true=>\n    have h0:=one_step s 0 live original bank front hist\n    have h1:=one_step s 1 live original bank front (false::hist)\n    have h2:=one_step s 2 live original bank front (true::false::hist)\n    have h3:=one_step s 3 live original bank front (true::true::false::hist)\n    have h4:=one_step s 4 live original bank front (true::true::true::false::hist)\n    have h5:=one_step s 5 live original bank front (false::true::true::true::false::hist)\n    exact runs_trans (program s) _ _ _ _ _ _ _ _\n      (runs_trans (program s) _ _ _ _ _ _ _ _\n        (runs_trans (program s) _ _ _ _ _ _ _ _\n          (runs_trans (program s) _ _ _ _ _ _ _ _ (runs_trans (program s) _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4) h5\nend RiemannGaussian.SemiprimeD1StackStaticTableEmit\n","RiemannGaussian.SemiprimeD1StackStaticWordTableDFS":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableLeaf\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableDFSParts\n/-! # Complete actual static-checker truth-table DFS and every leaf's own bit clock\nBoth real recursive calls restore depth/prefix physically. Every scalar comes\nfrom the fixed embedded checker, then ALL of its physical roles are drained.\nThe resulting tape has EXACT old first-port-outermost, false-first order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableDFS\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTableLeaf SemiprimeD1StackStaticWordTableDFSParts\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nopen SemiprimeD1TensorTapeCodec (tape)\nopen SemiprimeD1StackStaticWordTableEmit (leaf_bytes)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\nomit [Fintype K] in\n/-- Prepend a literal body trace to a proved physical caller-frame return. -/\ntheorem returns_after {m n : ℕ} {pc mid : Label L s.roles.length} {input middle output : Stack K→List Bool}\n    (h : Runs (program s) m pc input mid middle) (g : Returns (program s) n mid middle output) :\n    Returns (program s) (m+n) pc input output := by\n  intro next frames before hb\n  obtain ⟨between,hr,hm⟩:=h (next::frames) before hb\n  obtain ⟨finish,hfinish,hout⟩:=g next frames between hm\n  refine ⟨finish,?_,hout⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,hfinish]\n/-- All leaves in a subtree have the SAME total physical assignment width. -/\ndef weight (original : K→List Bool) (budget : Nat→Nat) (width : Nat) : Nat :=\n  leafBound s original budget width+20\n/-- COMPLETE actual recursive visit, not an assumed evaluator/callback.\nThe same closed fixed code executes one actual public checker per real leaf,\nboth finite-label calls per fork, and all byte writes/restores/cleanup/returns. -/\ntheorem visit_returns (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (bank : List Bool) (n : Nat) (front hist : List Bool) :\n    ∃t,t+10≤ weight s original budget (front.length+n)*2^n ∧ Returns (program s) t .visit\n      (data original bank n front hist)\n      (data original bank n front ((tape (tree answer front.reverse n)).reverse++hist)) := by\n  induction n generalizing front hist with\n  | zero=>\n    obtain ⟨t,ht,hret⟩:=leaf_returns s original hraw answer budget hc bank front hist\n    rw [leaf_bytes] at hret\n    have h:=returns_after s (visit_zero s original bank front hist) hret\n    refine ⟨1+t,?_,h⟩\n    simp only [Nat.add_zero,pow_zero,Nat.mul_one,weight]\n    omega\n  | succ n ih=>\n    let lowBytes:=tape (tree answer (front.reverse++[false]) n)\n    let highBytes:=tape (tree answer (front.reverse++[true]) n)\n    obtain ⟨tl,hl,hleft⟩:=ih (false::front) (true::hist)\n    obtain ⟨tr,hr,hright⟩:=ih (true::front) (lowBytes.reverse++true::hist)\n    simp only [List.reverse_cons] at hleft hright\n    have h0:=visit_succ s original bank n front hist\n    have h1:=fork_push s original bank n front hist\n    have h2:=low_push s original bank n front (true::hist)\n    have h3:=SemiprimeD1StackProcedureReturns.call (program s) tl .high .visit .afterLow\n      _ _ rfl hleft\n    have h4:=low_pop s original bank n front (lowBytes.reverse++true::hist)\n    have h5:=high_push s original bank n front (lowBytes.reverse++true::hist)\n    have h6:=SemiprimeD1StackProcedureReturns.call (program s) tr .afterHigh .visit .restore\n      _ _ rfl hright\n    have h7:=high_pop s original bank n front (highBytes.reverse++(lowBytes.reverse++true::hist))\n    have h8:=depth_restore s original bank n front (highBytes.reverse++(lowBytes.reverse++true::hist))\n    have h:=runs_trans (program s) _ _ _ _ _ _ _ _ h0\n      (runs_trans (program s) _ _ _ _ _ _ _ _ h1\n        (runs_trans (program s) _ _ _ _ _ _ _ _ h2\n          (runs_trans (program s) _ _ _ _ _ _ _ _ h3\n            (runs_trans (program s) _ _ _ _ _ _ _ _ h4\n              (runs_trans (program s) _ _ _ _ _ _ _ _ h5\n                (runs_trans (program s) _ _ _ _ _ _ _ _ h6\n                  (runs_trans (program s) _ _ _ _ _ _ _ _ h7 h8)))))))\n    have hlog:highBytes.reverse++(lowBytes.reverse++true::hist)=\n        (tape (tree answer front.reverse (n+1))).reverse++hist := by\n      change highBytes.reverse++(lowBytes.reverse++true::hist)=(true::(lowBytes++highBytes)).reverse++hist\n      simp only [List.reverse_cons,List.reverse_append,List.append_assoc,List.singleton_append]\n    rw [hlog] at h\n    have hret:=of_runs (program s) _ .visit .leafReturn _ _ h rfl\n    refine ⟨_,?_,hret⟩\n    have hw:(false::front).length+n=front.length+(n+1) := by simp only [List.length_cons];omega\n    have hw':(true::front).length+n=front.length+(n+1) := by simp only [List.length_cons];omega\n    rw [hw] at hl\n    rw [hw'] at hr\n    rw [pow_succ,←Nat.mul_assoc]\n    omega\nend RiemannGaussian.SemiprimeD1StackStaticWordTableDFS\n","RiemannGaussian.SemiprimeD1StackStaticWordTableEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableSpec\nimport RiemannGaussian.SemiprimeD1StackStaticWordTablePrimitives\n/-! # Actual binary coefficient Frame, vector/tree tags and history reversal -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableEmit\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTablePrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\nomit [DecidableEq K] in\n/-- Static Frame operands never alias, for any fixed physical checker. -/\ntheorem frame_injective : Function.Injective (frameStack s) := by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> simp_all [frameStack,checker,aux]\nomit [DecidableEq K] in\n/-- The private record buffer is distinct from the accumulated DFS history. -/\ntheorem recordReverse_injective : Function.Injective (recordReverseStack (K:=K)) := by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> simp_all [recordReverseStack,aux]\n/-- Real preserving Frame pays each coefficient bit and its real caller/return. -/\ntheorem frame_call (d : Stack K → List Bool) (hs : d (aux .scratch)=[]) :\n    Runs (program s) (6*(d (checker s.output)).length+5) .emitFrame d .emitTag\n      (Function.update d (aux .work) (frame (d (checker s.output)) (d (aux .work)))) := by\n  let start := SemiprimeD1StackFrame.state 0 none (d (checker s.output)) (d (aux .work)) []\n  let stop := SemiprimeD1StackFrame.done (d (checker s.output))\n    (frame (d (checker s.output)) (d (aux .work)))\n  have hi : Link.DataRel (frameStack s) d start.store d := by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact hs\n    · intro k _;rfl\n  have ho := Link.data_update (frameStack s) (frame_injective s) d start.store d hi (1:Fin 3)\n    (frame (d (checker s.output)) (d (aux .work)))\n  have he : Function.update start.store 1 (frame (d (checker s.output)) (d (aux .work)))=stop.store := by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call (program s) (frameStack s) Label.frame (frame_injective s)\n    SemiprimeD1StackFrame.code 0 (fun _ => rfl) .emitFrame .emitTag rfl _\n    start stop d _ rfl rfl (SemiprimeD1StackFrame.frame_words _ _ none) hi ho\n/-- Actual consuming reversal appends exactly this record's reversed bytes to history. -/\ntheorem recordReverse_call (d : Stack K → List Bool) :\n    Runs (program s) (2*(d (aux .work)).length+3) .emitReverse d .leafCleanup\n      (Function.update (Function.update d (aux .work) []) (aux .reversed)\n        ((d (aux .work)).reverse++d (aux .reversed))) := by\n  let xs := d (aux .work)\n  let ys := d (aux .reversed)\n  let start := SemiprimeD1StackReverseWord.state none xs ys\n  let stop := SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi : Link.DataRel recordReverseStack d start.store d := by\n    constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  have h0 := Link.data_update recordReverseStack recordReverse_injective d start.store d hi (0:Fin 2) []\n  have ho := Link.data_update recordReverseStack recordReverse_injective d _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he : Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store := by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call (program s) recordReverseStack Label.recordReverse recordReverse_injective\n    SemiprimeD1StackReverseWord.code 0 (fun _ => rfl) .emitReverse .leafCleanup rfl _\n    start stop d _ rfl rfl (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi ho\nomit [DecidableEq K] in\n/-- Literal one-coefficient tree leaf, including all framing and terminators. -/\ndef leafBytes (word : List Bool) : List Bool := false::SemiprimeD1TensorTapeCodec.vectorBits [word]\nomit [DecidableEq K] in\n/-- Every coefficient bit is retained in the physical prefix-free leaf. -/\ntheorem leafBytes_length (word : List Bool) : (leafBytes word).length=2*word.length+4 := by\n  simp only [leafBytes,SemiprimeD1TensorTapeCodec.vectorBits,List.length_cons,\n    SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n/-- Proof-only view of the actual temporary framing buffer. -/\ndef emitData (live original : K → List Bool) (bank front hist buffer : List Bool) : Stack K → List Bool :=\n  store live original (D.data bank [] [] [] [] [] []) front buffer [] hist []\n/-- A physical buffer update preserves all checker, template and scanner words. -/\ntheorem update_buffer (live original : K → List Bool) (bank front hist buffer fresh : List Bool) :\n    Function.update (emitData live original bank front hist buffer) (aux .work) fresh=\n      emitData live original bank front hist fresh := by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n/-- A physical history update preserves every other acquired word and empty helper. -/\ntheorem update_history (live original : K → List Bool) (bank front hist buffer fresh : List Bool) :\n    Function.update (emitData live original bank front hist buffer) (aux .reversed) fresh=\n      emitData live original bank front fresh buffer := by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n/-- COMPLETE actual coefficient serialization. Its cost pays Frame, each tag,\nthe whole leaf reversal, and every real call and return. -/\ntheorem emit_run (live original : K → List Bool) (bank front hist : List Bool) :\n    Runs (program s) (10*(live s.output).length+19) .emitSentinel\n      (withChecker (data original bank 0 front hist) live) .leafCleanup\n      (withChecker (data original bank 0 front ((leafBytes (live s.output)).reverse++hist)) live) := by\n  let d := emitData live original bank front hist\n  have h0 := push s .emitSentinel .emitFrame (aux .work) false rfl (d [])\n  change Runs (program s) 1 .emitSentinel (d []) .emitFrame (Function.update (d []) (aux .work) [false]) at h0\n  rw [update_buffer] at h0\n  have h1 := frame_call s (d [false]) rfl\n  change Runs (program s) (6*(live s.output).length+5) .emitFrame (d [false]) .emitTag\n    (Function.update (d [false]) (aux .work) (frame (live s.output) [false])) at h1\n  rw [update_buffer] at h1\n  have h2 := push s .emitTag .emitLeaf (aux .work) true rfl (d (frame (live s.output) [false]))\n  change Runs (program s) 1 .emitTag (d (frame (live s.output) [false])) .emitLeaf\n    (Function.update (d (frame (live s.output) [false])) (aux .work) (true::frame (live s.output) [false])) at h2\n  rw [update_buffer] at h2\n  have h3 := push s .emitLeaf .emitReverse (aux .work) false rfl (d (true::frame (live s.output) [false]))\n  change Runs (program s) 1 .emitLeaf (d (true::frame (live s.output) [false])) .emitReverse\n    (Function.update (d (true::frame (live s.output) [false])) (aux .work) (leafBytes (live s.output))) at h3\n  rw [update_buffer] at h3\n  have h4 := recordReverse_call s (d (leafBytes (live s.output)))\n  change Runs (program s) (2*(leafBytes (live s.output)).length+3) .emitReverse\n    (d (leafBytes (live s.output))) .leafCleanup\n    (Function.update (Function.update (d (leafBytes (live s.output))) (aux .work) []) (aux .reversed)\n      ((leafBytes (live s.output)).reverse++hist)) at h4\n  rw [update_buffer,update_history] at h4\n  have hh := runs_trans (program s) _ _ _ _ _ _ _ _\n    (runs_trans (program s) _ _ _ _ _ _ _ _\n      (runs_trans (program s) _ _ _ _ _ _ _ _ (runs_trans (program s) _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4\n  convert hh using 1\n  · rw [leafBytes_length];omega\n  · funext k;cases k <;> rfl\n  · funext k;cases k <;> rfl\n/-- Exact literal leaf bytes in the entire false-first table specification. -/\ntheorem leaf_bytes (answer : List Bool → List Bool) (raw : List Bool) :\n    leafBytes (answer raw)=SemiprimeD1TensorTapeCodec.tape (tree answer raw 0) := rfl\nend RiemannGaussian.SemiprimeD1StackStaticWordTableEmit\n\n","RiemannGaussian.SemiprimeD1StackStaticWordTableLeafCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableLoad\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableEmit\n/-! # Every actual static checker leaf copy, reversal and real call -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableLeafCalls\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTablePrimitives SemiprimeD1StackStaticWordTableCleanup\nopen SemiprimeD1StackStaticWordTableLoad SemiprimeD1StackStaticWordTableEmit\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Updating one real checker role commutes with the complete caller-bank view. -/\ntheorem withChecker_update (base : Stack K→List Bool) (live : K→List Bool) (key : K) (word : List Bool) :\n    Function.update (withChecker base live) (checker key) word=\n      withChecker base (Function.update live key word) := by\n  funext k\n  cases k with\n  | inl k=>\n    by_cases h:k=key\n    · subst k\n      change Function.update (withChecker base live) (Sum.inl key) word (Sum.inl key)=\n        Function.update live key word key\n      rw [Function.update_self,Function.update_self]\n    · have hn:(Sum.inl k : Stack K)≠checker key:=by intro he;exact h (Sum.inl.inj he)\n      rw [Function.update_of_ne hn]\n      change live k=Function.update live key word k\n      rw [Function.update_of_ne h]\n  | inr k=>rw [Function.update_of_ne (by intro h;cases h)];rfl\n/-- A literal full-bank load enters every physical original input field. -/\ntheorem load_call [Fintype K] (original : K→List Bool) (bank front hist : List Bool) :\n    ∃t≤ s.roles.length*(6*inputBytes original+5)+2,Runs (program s) t .leaf\n      (data original bank 0 front hist) .prefixCopy (loadedData original bank front hist) := by\n  obtain ⟨t,ht,hr⟩:=load_returns s (data original bank 0 front hist) rfl\n  have h:=SemiprimeD1StackProcedureReturns.call (program s) t .leaf (.load 0) .prefixCopy _ _ rfl hr\n  have he:loaded (data original bank 0 front hist)=loadedData original bank front hist:=by\n    funext k;cases k <;> rfl\n  rw [he] at h\n  refine ⟨1+t,?_,h⟩\n  have hi:inventory (data original bank 0 front hist)=0 := by simp [inventory,data,store,checker]\n  have hT:templateInventory (data original bank 0 front hist)=inputBytes original := rfl\n  unfold loadUnit at ht\n  rw [hi,hT] at ht\n  simp only [Nat.zero_add] at ht\n  omega\n/-- Current reverse-prefix copying retains the actual prefix and original template. -/\ntheorem copy_prefix (original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) (5*front.length+4) .prefixCopy (loadedData original bank front hist) .reversePrefix\n      (Function.update (loadedData original bank front hist) (aux .work) front) :=\n  copy_call s none .prefixCopy .reversePrefix rfl (loadedData original bank front hist) rfl rfl\n/-- The real consuming reversal supplies the raw operand directly; the template\nraw field is empty, as proved by each concrete original-input client. -/\ntheorem reverse_prefix (original : K→List Bool) (hraw : original s.raw=[])\n    (bank front hist : List Bool) :\n    Runs (program s) (2*front.length+3) .reversePrefix\n      (Function.update (loadedData original bank front hist) (aux .work) front) .check\n      (withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse)) := by\n  let d:=loadedData original bank front hist\n  have hr:=reverse_call s false .reversePrefix .check rfl (Function.update d (aux .work) front)\n  have h0:(Function.update d (aux .work) front) (reverseStack s false 0)=front :=\n    Function.update_self _ _ _\n  have h1:(Function.update d (aux .work) front) (reverseStack s false 1)=[] := by\n    change Function.update d (aux .work) front (checker s.raw)=[]\n    rw [Function.update_of_ne (by intro h;cases h)]\n    exact hraw\n  rw [h0,h1,List.append_nil] at hr\n  have he:Function.update (Function.update (Function.update d (aux .work) front) (aux .work) [])\n      (checker s.raw) front.reverse=Function.update d (checker s.raw) front.reverse := by\n    funext k\n    by_cases hc:k=checker s.raw\n    · subst k;rw [Function.update_self,Function.update_self]\n    · rw [Function.update_of_ne hc,Function.update_of_ne hc]\n      by_cases hw:k=aux .work\n      · subst k;rw [Function.update_self];rfl\n      · rw [Function.update_of_ne hw,Function.update_of_ne hw]\n  change Runs (program s) (2*front.length+3) .reversePrefix (Function.update d (aux .work) front) .check\n    (Function.update (Function.update (Function.update d (aux .work) front) (aux .work) [])\n      (checker s.raw) front.reverse) at hr\n  have hd:Function.update d (checker s.raw) front.reverse=\n      withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse):=\n    withChecker_update (data original bank 0 front hist) original s.raw front.reverse\n  rw [he,hd] at hr\n  exact hr\n/-- A concrete proved checker trace is included as a REAL call; its original\nprogram executes, rather than a predicate/callback/evaluator opcode. -/\ntheorem checker_call (original : K→List Bool) (answer : List Bool→List Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s original answer budget) (bank front hist : List Bool) :\n    ∃t≤ budget front.length,∃finish:C.State K L,\n      C.run s.code t (checkerInitial s original front.reverse)=some finish ∧\n      finish.data s.output=answer front.reverse ∧\n      Runs (program s) (t+1) .check\n        (withChecker (data original bank 0 front hist) (Function.update original s.raw front.reverse)) .emitSentinel\n        (withChecker (data original bank 0 front hist) finish.data) := by\n  obtain ⟨t,ht,finish,hpc,hframes,hr,hvalue⟩:=hc front.reverse\n  refine ⟨t,by simpa only [List.length_reverse] using ht,finish,hr,hvalue,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call (program s) checker Label.checker\n    Sum.inl_injective s.code s.entry (fun _=>rfl) .check .emitSentinel rfl t\n    (checkerInitial s original front.reverse) finish\n  · rfl\n  · rfl\n  · exact hpc\n  · exact hframes\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>rfl\nend RiemannGaussian.SemiprimeD1StackStaticWordTableLeafCalls\n","RiemannGaussian.SemiprimeD1StackStaticWordTableSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTable\n/-! # Proof-only actual checker trace contract and whole table specification\nNo definition in this module is an operand of the compiler program. Concrete\nclients prove the contract from their already kernel-checked literal checker.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTable\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Exact ordinary checker initialization, after actual physical template copy\nand assignment reversal. It is a theorem-side state view only. -/\ndef checkerInitial (original : K→List Bool) (raw : List Bool) : C.State K L :=\n  ⟨some s.entry,none,none,Function.update original s.raw raw,[]⟩\n/-- A PROVED actual trace of the fixed checker, for every raw word. The budget\nand postcondition are proof arguments; neither is carried in runtime state. -/\ndef CheckerTrace (original : K→List Bool) (answer : List Bool→List Bool) (budget : Nat→Nat) : Prop :=\n  ∀raw,∃t≤ budget raw.length,∃finish:C.State K L,\n    finish.pc=none ∧ finish.frames=[] ∧\n    C.run s.code t (checkerInitial s original raw)=some finish ∧ finish.data s.output=answer raw\n/-- All actual original-template input bytes, including empty private fields. -/\ndef inputBytes [Fintype K] (original : K→List Bool) : Nat :=∑k:K,(original k).length\n/-- Literal individual binary coefficient vector. -/\ndef leafWords (answer : List Bool→List Bool) (raw : List Bool) : List (List Bool) :=\n  [answer raw]\n/-- Exact original false-first/first-port-outermost tree; a specification only. -/\ndef tree (answer : List Bool→List Bool) (front : List Bool) : (n : Nat)→SemiprimeD1TensorTables.Table n\n  | 0=>.leaf (leafWords answer front)\n  | n+1=>.fork (tree answer (front++[false]) n) (tree answer (front++[true]) n)\n/-- Proof view of replacing the actual checker bank, leaving all other cells alone. -/\ndef withChecker (base : Stack K→List Bool) (live : K→List Bool) : Stack K→List Bool :=\n  Sum.elim live (fun k=>base (.inr k))\n/-- Actual whole template copy retains every template, scanner and caller byte. -/\ndef loadedData (original : K→List Bool) (bank front hist : List Bool) : Stack K→List Bool :=\n  withChecker (data original bank 0 front hist) original\n/-- Every ordinary checker input field is paid by actual original and raw bytes. -/\ntheorem initial_cell_le [Fintype K] (original : K→List Bool) (raw : List Bool) (k : K) :\n    ((checkerInitial s original raw).data k).length≤ inputBytes original+raw.length := by\n  by_cases h:k=s.raw\n  · subst k\n    change (Function.update original s.raw raw s.raw).length≤_\n    rw [Function.update_self]\n    omega\n  · change (Function.update original s.raw raw k).length≤_\n    rw [Function.update_of_ne h]\n    have hs:(original k).length≤∑j:K,(original j).length:=\n      Finset.single_le_sum (f:=fun j:K=>(original j).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n    unfold inputBytes\n    omega\n/-- Every actual checker output field has its own executed-step byte bound. -/\ntheorem output_cell_le [Fintype K] (original : K→List Bool) (raw : List Bool)\n    (t : Nat) (finish : C.State K L)\n    (hr : C.run s.code t (checkerInitial s original raw)=some finish) (k : K) :\n    (finish.data k).length≤ inputBytes original+raw.length+t :=\n  SemiprimeD1StackReturnLink.run_data_bound s.code t (inputBytes original+raw.length)\n    _ finish (initial_cell_le s original raw) hr k\n/-- The generic tree visits every finite assignment in its original local order. -/\ntheorem tree_entry (answer : List Bool→List Bool) (front : List Bool) (n : Nat) (input : Fin n→Bool) :\n    SemiprimeD1TensorTables.valueAt (tree answer front n) input=leafWords answer (front++List.ofFn input) := by\n  induction n generalizing front with\n  | zero=>simp only [tree,SemiprimeD1TensorTables.valueAt,List.ofFn_zero,List.append_nil]\n  | succ n ih=>\n    cases h:input 0\n    · simp only [tree,SemiprimeD1TensorTables.valueAt,h,Bool.false_eq_true,ite_false]\n      simpa only [List.ofFn_succ,h,List.append_assoc,List.singleton_append] using\n        ih (front++[false]) (fun j=>input j.succ)\n    · simp only [tree,SemiprimeD1TensorTables.valueAt,h,ite_true]\n      simpa only [List.ofFn_succ,h,List.append_assoc,List.singleton_append] using\n        ih (front++[true]) (fun j=>input j.succ)\nend RiemannGaussian.SemiprimeD1StackStaticWordTableSpec\n","RiemannGaussian.SemiprimeD1StackTransform":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BinaryBootstrap\nimport RiemannGaussian.SemiprimeD1StackProcedureFragments\n\n/-! # Original-input physical transform/radix acquisition\nThe original binary input is retained by the actual included bootstrap. Only\nits small unary WIDTH is scaled/compared. R and its square are doubled and\nquadrupled by literal marker writes; no native logarithm, power or division is\nexecuted. The actual radix is acquired by consuming four R markers per output.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackTransform\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (instruction DataRel data_unique Rel run_rel)\nend Link\nnamespace Boot\nexport SemiprimeD1BinaryBootstrap (Stack Label code state done seenOne)\nend Boot\n\n/-- Eleven fixed Boolean data stacks; N remains on input in binary. -/\ninductive Stack where\n  | input | width | nonzero | threshold | radius | square | exponent\n  | squareWork | thresholdWork | temporary | radix\n  deriving DecidableEq,Repr\n/-- Fixed literal stack catalogue. -/\ninstance : Fintype Stack where\n  elems:={.input,.width,.nonzero,.threshold,.radius,.square,.exponent,\n    .squareWork,.thresholdWork,.temporary,.radix}\n  complete:=by intro k;cases k <;> simp\n\n/-- Fixed local control for comparison, scaling and four-marker radix extraction. -/\ninductive Local where\n  | start | initSquare | copySquare | copyThreshold | compareThreshold | compareSquare\n  | clearSuccess | clearFailure | radiusPop | radiusPush1 | radiusPush2\n  | radiusRestore | radiusRestorePush | squarePop | squarePush1 | squarePush2\n  | squarePush3 | squarePush4 | squareRestore | squareRestorePush | incExponent\n  | radixStart | radixPop0 | radixPop1 | radixPop2 | radixPop3 | radixPush | halt\n  deriving DecidableEq,Repr\n/-- Fixed finite local instruction catalogue. -/\ninstance : Fintype Local where\n  elems:={.start,.initSquare,.copySquare,.copyThreshold,.compareThreshold,.compareSquare,\n    .clearSuccess,.clearFailure,.radiusPop,.radiusPush1,.radiusPush2,.radiusRestore,.radiusRestorePush,\n    .squarePop,.squarePush1,.squarePush2,.squarePush3,.squarePush4,.squareRestore,.squareRestorePush,\n    .incExponent,.radixStart,.radixPop0,.radixPop1,.radixPop2,.radixPop3,.radixPush,.halt}\n  complete:=by intro k;cases k <;> simp\n\n/-- All labels are fixed: local code, sixteen literal copies, bootstrap and four Copy instances. -/\nabbrev Label := Local⊕(Fin 17⊕(Boot.Label⊕(Fin 4×Fin 9)))\n\n/-- Fixed bootstrap operand inclusion. -/\ndef bootStack : Boot.Stack→Stack\n  | .input => .input\n  | .reverse => .temporary\n  | .width => .width\n  | .nonzero => .nonzero\n/-- Fixed bootstrap code inclusion. -/\ndef bootLabel (pc:Boot.Label) : Label := .inr (.inr (.inl pc))\n/-- Fixed sixteen-copy setup label, never an input-dependent loop counter in control. -/\ndef setupLabel (pc:Fin 17) : Label := .inr (.inl pc)\n/-- Fixed Copy source operand. -/\ndef copyInput (mode:Fin 4) : Stack :=\n  if mode=0 then .width else if mode=1 then .square else if mode=2 then .threshold else .radius\n/-- Fixed Copy destination operand. -/\ndef copyOutput (mode:Fin 4) : Stack :=\n  if mode=0 then .threshold else if mode=2 then .thresholdWork else .squareWork\n/-- Literal three-stack Copy inclusion. -/\ndef copyStack (mode:Fin 4) (k:Fin 3) : Stack :=\n  if k=0 then copyInput mode else if k=1 then copyOutput mode else .temporary\n/-- Fixed Copy instruction inclusion. -/\ndef copyLabel (mode:Fin 4) (pc:Fin 9) : Label := .inr (.inr (.inr (mode,pc)))\n\n/-- Complete actual instruction table; all tests inspect physical stack tops or fixed labels. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inr (.inl pc)) => Link.instruction bootStack bootLabel (Boot.code pc)\n  | .inr (.inr (.inr (mode,pc))) =>\n      Link.instruction (copyStack mode) (copyLabel mode) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inl index) =>\n      if h:index.val<16 then\n        .call (copyLabel 0 0) (setupLabel ⟨index.val+1,by omega⟩)\n      else .base (.push .radius true (.inl .initSquare))\n  | .inl .start => .call (bootLabel (.scan,false)) (setupLabel 0)\n  | .inl .initSquare => .base (.push .square true (.inl .copySquare))\n  | .inl .copySquare => .call (copyLabel 1 0) (.inl .copyThreshold)\n  | .inl .copyThreshold => .call (copyLabel 2 0) (.inl .compareThreshold)\n  | .inl .compareThreshold => .base (.pop .thresholdWork (.inl .clearSuccess) (.inl .compareSquare) (.inl .compareSquare))\n  | .inl .compareSquare => .base (.pop .squareWork (.inl .clearFailure) (.inl .compareThreshold) (.inl .compareThreshold))\n  | .inl .clearSuccess => .base (.pop .squareWork (.inl .radixStart) (.inl .clearSuccess) (.inl .clearSuccess))\n  | .inl .clearFailure => .base (.pop .thresholdWork (.inl .radiusPop) (.inl .clearFailure) (.inl .clearFailure))\n  | .inl .radiusPop => .base (.pop .radius (.inl .radiusRestore) (.inl .radiusPush1) (.inl .radiusPush1))\n  | .inl .radiusPush1 => .base (.push .temporary true (.inl .radiusPush2))\n  | .inl .radiusPush2 => .base (.push .temporary true (.inl .radiusPop))\n  | .inl .radiusRestore => .base (.pop .temporary (.inl .squarePop) (.inl .radiusRestorePush) (.inl .radiusRestorePush))\n  | .inl .radiusRestorePush => .base (.push .radius true (.inl .radiusRestore))\n  | .inl .squarePop => .base (.pop .square (.inl .squareRestore) (.inl .squarePush1) (.inl .squarePush1))\n  | .inl .squarePush1 => .base (.push .temporary true (.inl .squarePush2))\n  | .inl .squarePush2 => .base (.push .temporary true (.inl .squarePush3))\n  | .inl .squarePush3 => .base (.push .temporary true (.inl .squarePush4))\n  | .inl .squarePush4 => .base (.push .temporary true (.inl .squarePop))\n  | .inl .squareRestore => .base (.pop .temporary (.inl .incExponent) (.inl .squareRestorePush) (.inl .squareRestorePush))\n  | .inl .squareRestorePush => .base (.push .square true (.inl .squareRestore))\n  | .inl .incExponent => .base (.push .exponent true (.inl .copySquare))\n  | .inl .radixStart => .call (copyLabel 3 0) (.inl .radixPop0)\n  | .inl .radixPop0 => .base (.pop .squareWork (.inl .halt) (.inl .radixPop1) (.inl .radixPop1))\n  | .inl .radixPop1 => .base (.pop .squareWork (.inl .halt) (.inl .radixPop2) (.inl .radixPop2))\n  | .inl .radixPop2 => .base (.pop .squareWork (.inl .halt) (.inl .radixPop3) (.inl .radixPop3))\n  | .inl .radixPop3 => .base (.pop .squareWork (.inl .halt) (.inl .radixPush) (.inl .radixPush))\n  | .inl .radixPush => .base (.push .radix true (.inl .radixPop0))\n  | .inl .halt => .base .halt\n\n/-- One fixed actual finite machine whose ONLY initial input is binary N. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.input Stack.radix (.inl .start) program\n\n/-- Actual original-input initial data; no dimension/counter answer is supplied. -/\ndef input (bits:List Bool) : Stack→List Bool\n  | .input => bits\n  | _ => []\n/-- Actual start before executing the bootstrap call. -/\ndef initial (bits:List Bool) : C.State Stack Label := ⟨some (.inl .start),none,none,input bits,[]⟩\n\n/-- Bootstrap uses four distinct actual stack operands. -/\ntheorem bootStack_injective : Function.Injective bootStack := by decide\n/-- Every Copy instance has three distinct actual operands. -/\ntheorem copyStack_injective (mode:Fin 4) : Function.Injective (copyStack mode) := by\n  fin_cases mode <;> decide\n/-- The fixed program has eleven Boolean data-stack names. -/\ntheorem stack_card : Fintype.card Stack=11 := by decide\n/-- Every local/setup/component label totals 99 before every input. -/\ntheorem label_card : Fintype.card Label=99 := by decide\n/-- Every data/return alphabet is finite, not merely the input alphabet. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite Stack.input Stack.radix (.inl .start) program\nend RiemannGaussian.SemiprimeD1StackTransform\n","RiemannGaussian.SemiprimeD1StackTransformComparison":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackTransformSetup\n\n/-! # Actual physical transform stopping comparison\nBoth operands are copied by the real included Copy loop. Paired marker pops\ndecide the order and all residual work is physically cleared; no scalar order\npredicate is passed to the runtime program.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackTransformComparison\nopen SemiprimeD1StackTransform SemiprimeD1StackTransformComponents\nopen SemiprimeD1StackProcedureFragments (At Runs one_base)\n\n/-- Any literal clear loop physically consumes every current stack symbol. -/\ntheorem clear_loop (pc next:Label) (stack:Stack) (store:Stack→List Bool)\n    (hcode:program pc=.base (.pop stack next pc pc)) :\n    Runs program ((store stack).length+1) pc store next (Function.update store stack []) := by\n  generalize hw:store stack=word\n  induction word generalizing store with\n  | nil =>\n    apply one_base program _ _ (.pop stack next pc pc) _ _ hcode\n    · simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n    · simp [B.execute,hw]\n  | cons bit word ih =>\n    have h0:Runs program 1 pc store pc (Function.update store stack word):=by\n      apply one_base program _ _ (.pop stack next pc pc) _ _ hcode\n      · cases bit <;> simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n      · simp [B.execute,hw]\n    have h1:=ih (Function.update store stack word) (by simp)\n    have hd:Function.update (Function.update store stack word) stack []=Function.update store stack []:=by\n      funext k\n      by_cases hk:k=stack\n      · subst k; simp\n      · simp [Function.update,hk]\n    rw [hd] at h1\n    have h:=h0.trans h1\n    convert h using 1\n    simp only [List.length_cons]\n    omega\n\n/-- Actual comparison consumes one threshold and one square marker. -/\ntheorem compare_pair (bits threshold radius square exponent sw tw radix:List Bool) :\n    Runs program 2 (.inl .compareThreshold) (data bits threshold radius square exponent (true::sw) (true::tw) [] radix)\n      (.inl .compareThreshold) (data bits threshold radius square exponent sw tw [] radix) := by\n  have h0:Runs program 1 (.inl .compareThreshold) (data bits threshold radius square exponent (true::sw) (true::tw) [] radix)\n      (.inl .compareSquare) (data bits threshold radius square exponent (true::sw) tw [] radix):=by\n    apply one_base program _ _ (.pop .thresholdWork (.inl .clearSuccess) (.inl .compareSquare) (.inl .compareSquare)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .compareSquare) (data bits threshold radius square exponent (true::sw) tw [] radix)\n      (.inl .compareThreshold) (data bits threshold radius square exponent sw tw [] radix):=by\n    apply one_base program _ _ (.pop .squareWork (.inl .clearFailure) (.inl .compareThreshold) (.inl .compareThreshold)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  exact h0.trans h1\n\n/-- Threshold exhaustion is the actual successful stopping branch. -/\ntheorem pairs_success (t extra:ℕ) (bits threshold radius square exponent radix:List Bool) :\n    Runs program (2*t+1) (.inl .compareThreshold)\n      (data bits threshold radius square exponent (List.replicate (t+extra) true) (List.replicate t true) [] radix)\n      (.inl .clearSuccess) (data bits threshold radius square exponent (List.replicate extra true) [] [] radix) := by\n  induction t with\n  | zero =>\n    apply one_base program _ _ (.pop .thresholdWork (.inl .clearSuccess) (.inl .compareSquare) (.inl .compareSquare)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  | succ t ih =>\n    have h:=compare_pair bits threshold radius square exponent (List.replicate (t+extra) true) (List.replicate t true) radix\n    have hh:=h.trans ih\n    simpa only [Nat.succ_add,List.replicate_succ,show 2+(2*t+1)=2*(t+1)+1 by omega] using hh\n\n/-- Square exhaustion is the actual failed stopping branch, including its physical underflow test. -/\ntheorem pairs_failure (s extra:ℕ) (bits threshold radius square exponent radix:List Bool) :\n    Runs program (2*s+2) (.inl .compareThreshold)\n      (data bits threshold radius square exponent (List.replicate s true) (List.replicate (s+extra+1) true) [] radix)\n      (.inl .clearFailure) (data bits threshold radius square exponent [] (List.replicate extra true) [] radix) := by\n  induction s with\n  | zero =>\n    have h0:Runs program 1 (.inl .compareThreshold)\n        (data bits threshold radius square exponent [] (true::List.replicate extra true) [] radix)\n        (.inl .compareSquare) (data bits threshold radius square exponent [] (List.replicate extra true) [] radix):=by\n      apply one_base program _ _ (.pop .thresholdWork (.inl .clearSuccess) (.inl .compareSquare) (.inl .compareSquare)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> simp [B.execute,data,Function.update]\n    have h1:Runs program 1 (.inl .compareSquare)\n        (data bits threshold radius square exponent [] (List.replicate extra true) [] radix)\n        (.inl .clearFailure) (data bits threshold radius square exponent [] (List.replicate extra true) [] radix):=by\n      apply one_base program _ _ (.pop .squareWork (.inl .clearFailure) (.inl .compareThreshold) (.inl .compareThreshold)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> simp [B.execute,data,Function.update]\n    simpa only [Nat.mul_zero,Nat.zero_add,List.replicate_zero,List.replicate_succ] using h0.trans h1\n  | succ s ih =>\n    have h:=compare_pair bits threshold radius square exponent (List.replicate s true) (List.replicate (s+extra+1) true) radix\n    have hh:=h.trans ih\n    simpa only [Nat.succ_add,List.replicate_succ,show 2+(2*s+2)=2*(s+1)+2 by omega] using hh\n\n/-- Both comparison operands are acquired from actual retained counters by real Copy calls. -/\ntheorem prepare_compare (bits threshold radius square exponent radix:List Bool) :\n    Runs program (5*square.length+5*threshold.length+8) (.inl .copySquare)\n      (data bits threshold radius square exponent [] [] [] radix) (.inl .compareThreshold)\n      (data bits threshold radius square exponent square threshold [] radix) := by\n  have h0:=copy_call 1 (data bits threshold radius square exponent [] [] [] radix) rfl\n    (.inl .copySquare) (.inl .copyThreshold) rfl\n  have hd0:Function.update (data bits threshold radius square exponent [] [] [] radix) Stack.squareWork square=\n      data bits threshold radius square exponent square [] [] radix:=by funext k;cases k <;> simp [data,Function.update]\n  simp only [copyInput,copyOutput,data,show ¬((1:Fin 4)=0) by decide,\n    show ¬((1:Fin 4)=2) by decide,ite_false,ite_true,List.append_nil] at h0\n  rw [hd0] at h0\n  have h1:=copy_call 2 (data bits threshold radius square exponent square [] [] radix) rfl\n    (.inl .copyThreshold) (.inl .compareThreshold) rfl\n  have hd1:Function.update (data bits threshold radius square exponent square [] [] radix) Stack.thresholdWork threshold=\n      data bits threshold radius square exponent square threshold [] radix:=by funext k;cases k <;> simp [data,Function.update]\n  simp only [copyInput,copyOutput,data,show ¬((2:Fin 4)=0) by decide,\n    show ¬((2:Fin 4)=1) by decide,ite_false,ite_true,List.append_nil] at h1\n  rw [hd1] at h1\n  have h:=h0.trans h1\n  convert h using 1\n  omega\n\n/-- Actual success path, including all copied operands and leftover square clearing. -/\ntheorem compare_success (s t:ℕ) (hs:t≤s) (bits radius exponent radix:List Bool) :\n    Runs program (6*(s+t)+10) (.inl .copySquare)\n      (data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix)\n      (.inl .radixStart) (data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix) := by\n  have h0:=prepare_compare bits (List.replicate t true) radius (List.replicate s true) exponent radix\n  have h1:=pairs_success t (s-t) bits (List.replicate t true) radius (List.replicate s true) exponent radix\n  rw [Nat.add_sub_of_le hs] at h1\n  have h2:=clear_loop (.inl .clearSuccess) (.inl .radixStart) .squareWork\n    (data bits (List.replicate t true) radius (List.replicate s true) exponent (List.replicate (s-t) true) [] [] radix) rfl\n  have hd:Function.update (data bits (List.replicate t true) radius (List.replicate s true) exponent\n        (List.replicate (s-t) true) [] [] radix) Stack.squareWork []=\n      data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix:=by\n    funext k;cases k <;> simp [data,Function.update]\n  rw [hd] at h2\n  have h:=h0.trans (h1.trans h2)\n  simp only [data,List.length_replicate] at h\n  convert h using 1\n  omega\n\n/-- Actual failure path, including all copied operands and residual threshold clearing. -/\ntheorem compare_failure (s t:ℕ) (hs:s<t) (bits radius exponent radix:List Bool) :\n    Runs program (6*(s+t)+10) (.inl .copySquare)\n      (data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix)\n      (.inl .radiusPop) (data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix) := by\n  let extra:=t-s-1\n  have ht:s+extra+1=t:=by omega\n  have h0:=prepare_compare bits (List.replicate t true) radius (List.replicate s true) exponent radix\n  have h1:=pairs_failure s extra bits (List.replicate t true) radius (List.replicate s true) exponent radix\n  rw [ht] at h1\n  have h2:=clear_loop (.inl .clearFailure) (.inl .radiusPop) .thresholdWork\n    (data bits (List.replicate t true) radius (List.replicate s true) exponent [] (List.replicate extra true) [] radix) rfl\n  have hd:Function.update (data bits (List.replicate t true) radius (List.replicate s true) exponent\n        [] (List.replicate extra true) [] radix) Stack.thresholdWork []=\n      data bits (List.replicate t true) radius (List.replicate s true) exponent [] [] [] radix:=by\n    funext k;cases k <;> simp [data,Function.update]\n  rw [hd] at h2\n  have h:=h0.trans (h1.trans h2)\n  simp only [data,List.length_replicate] at h\n  convert h using 1\n  omega\nend RiemannGaussian.SemiprimeD1StackTransformComparison\n","RiemannGaussian.SemiprimeD1StackUnarySumLess":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackUnaryProduct\n/-! # Physical strict sum comparison for mixed-radix digits\nThe machine consumes three unary counters, emits one Boolean, and clears every\noperand. Its control and Boolean stack alphabets are fixed before all inputs.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackUnarySumLess\nopen Turing Turing.TM2 Turing.TM2.Stmt\nopen SemiprimeD1StackUnaryDivmod (unary unary_succ unary_bump)\nopen SemiprimeD1StackFiniteControlPaths (SourcePath)\n/-- Four fixed physical operand/result stacks. -/\ninductive Stack | left | right | limit | valid deriving DecidableEq,Inhabited,Repr\ninstance : Fintype Stack where\n  elems := {.left,.right,.limit,.valid}\n  complete := by intro k; cases k <;> simp\n/-- Eight fixed join, comparison and cleanup phases. -/\ninductive PC | join | compare | consume | test | clear | reject | fail | accept\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype PC where\n  elems := {.join,.compare,.consume,.test,.clear,.reject,.fail,.accept}\n  complete := by intro k; cases k <;> simp\n/-- Every unbounded tape symbol is Boolean. -/\nabbrev Alphabet (_ : Stack) := Bool\n/-- Every comparison step pops literal data cells; no numerical predicate is executed. -/\ndef program : PC → Stmt Alphabet PC (Option Bool)\n  | .join => .pop .right (fun _ b=>b) (.branch Option.isSome\n      (.push .left (fun _=>true) (.goto (fun _=>.join))) (.goto (fun _=>.compare)))\n  | .compare => .pop .left (fun _ b=>b) (.branch Option.isSome\n      (.goto (fun _=>.consume)) (.goto (fun _=>.test)))\n  | .consume => .pop .limit (fun _ b=>b) (.branch Option.isSome\n      (.goto (fun _=>.compare)) (.goto (fun _=>.reject)))\n  | .test => .peek .limit (fun _ b=>b) (.branch Option.isSome\n      (.goto (fun _=>.clear)) (.goto (fun _=>.fail)))\n  | .clear => .pop .limit (fun _ b=>b) (.branch Option.isSome\n      (.goto (fun _=>.clear)) (.goto (fun _=>.accept)))\n  | .reject => .pop .left (fun _ b=>b) (.branch Option.isSome\n      (.goto (fun _=>.reject)) (.goto (fun _=>.fail)))\n  | .fail => .push .valid (fun _=>false) .halt\n  | .accept => .push .valid (fun _=>true) .halt\n\n/-- Literal physical stack bank. -/\ndef contents (left right limit valid : List Bool) : Stack→List Bool\n  | .left=>left | .right=>right | .limit=>limit | .valid=>valid\n\n/-- Explicit finite-control configuration. -/\ndef cfg (pc : Option PC) (flag : Option Bool) (left right limit valid : List Bool) :\n    Cfg Alphabet PC (Option Bool) := ⟨pc,flag,contents left right limit valid⟩\n/-- Actual source transition paths for the fixed comparison code. -/\nabbrev Executes := SourcePath program\n@[simp] theorem update_contents (left right limit valid xs : List Bool) (k : Stack) :\n    Function.update (contents left right limit valid) k xs=\n      contents (if k=.left then xs else left) (if k=.right then xs else right)\n        (if k=.limit then xs else limit) (if k=.valid then xs else valid) := by\n  funext j; cases k <;> cases j <;> simp [contents]\n\n/-- Actual input concatenation pays one pop/push transition for every right operand token. -/\ntheorem join_exec (m n d : ℕ) (flag : Option Bool) :\n    Executes (n+1) (cfg (some .join) flag (unary m) (unary n) (unary d) [])\n      (cfg (some .compare) none (unary (n+m)) [] (unary d) []) := by\n  induction n generalizing m flag with\n  | zero =>\n    apply SourcePath.next ?_ (.refl _)\n    simp [program,cfg,contents,unary,TM2.step,TM2.stepAux]\n  | succ n ih =>\n    have hs : TM2.step program (cfg (some .join) flag (unary m) (unary (n+1)) (unary d) [])=\n        some (cfg (some .join) (some true) (unary (m+1)) (unary n) (unary d) []) := by\n      simp [program,cfg,contents,unary_succ,TM2.step,TM2.stepAux]\n    have ht := SourcePath.next hs (ih (m+1) (some true))\n    simpa only [Nat.add_assoc,Nat.add_left_comm,Nat.add_comm] using ht\n\nend RiemannGaussian.SemiprimeD1StackUnarySumLess\n","RiemannGaussian.SemiprimeD1StackVectorTableCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTablePrimitives\n/-! # Actual complete static checker-bank draining -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableCleanup\nopen SemiprimeD1StackVectorTable SemiprimeD1StackVectorTablePrimitives\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Proof view of exactly the physically cleared prefix of the static inventory. -/\ndef cleanPrefix (d : Stack K→List Bool) (n : Nat) : Stack K→List Bool\n  | .inl k=>if k∈s.roles.take n then [] else d (.inl k)\n  | .inr k=>d (.inr k)\n/-- Whole clear checker bank with every template/count/private role preserved. -/\ndef clean (d : Stack K→List Bool) : Stack K→List Bool\n  | .inl _=>[] | .inr k=>d (.inr k)\n/-- Empty visited prefix has changed no physical cell. -/\ntheorem cleanPrefix_zero (d : Stack K→List Bool) : cleanPrefix s d 0=d := by\n  funext k;cases k <;> simp only [cleanPrefix,List.take_zero,List.not_mem_nil,ite_false]\n/-- Complete literal inventory covers every physical checker role. -/\ntheorem cleanPrefix_full (d : Stack K→List Bool) : cleanPrefix s d s.roles.length=clean d := by\n  funext k\n  cases k with\n  | inl k=>simp only [cleanPrefix,List.take_length,s.complete k,ite_true,clean]\n  | inr k=>rfl\n/-- Exact one-role physical reset advances the visited inventory prefix. -/\ntheorem cleanPrefix_step (d : Stack K→List Bool) (p : Fin s.roles.length) :\n    Function.update (cleanPrefix s d p.val) (checker (role s p)) []=cleanPrefix s d (p.val+1) := by\n  funext k\n  cases k with\n  | inl k=>\n    by_cases he:k=s.roles[p.val]\n    · subst k\n      change Function.update (cleanPrefix s d p.val) (Sum.inl s.roles[p.val]) [] (Sum.inl s.roles[p.val])=_\n      rw [Function.update_self]\n      simp only [cleanPrefix,List.take_succ_eq_append_getElem p.isLt,List.mem_append,List.mem_cons,\n        List.not_mem_nil,or_false,or_true,ite_true]\n    · rw [Function.update_of_ne (by intro h;exact he (Sum.inl.inj h))]\n      simp only [cleanPrefix,List.take_succ_eq_append_getElem p.isLt,List.mem_append,List.mem_cons,\n        List.not_mem_nil,or_false,he,or_false]\n  | inr k=>rw [Function.update_of_ne (by intro h;cases h)];rfl\n/-- Every actual clear can only shorten a payload. -/\ntheorem cleanPrefix_length (d : Stack K→List Bool) (n : Nat) (k : Stack K) :\n    (cleanPrefix s d n k).length≤(d k).length := by\n  cases k with\n  | inl k=>change (if k∈s.roles.take n then [] else d (.inl k)).length≤_;split <;> simp\n  | inr k=>exact le_rfl\n/-- Actual total checker payload, used only to bound physical drains. -/\ndef inventory [Fintype K] (d : Stack K→List Bool) : Nat := ∑k:K,(d (checker k)).length\nomit [DecidableEq K] in\n/-- Actual checker payload at one role belongs to its complete inventory. -/\ntheorem cell_le_inventory [Fintype K] (d : Stack K→List Bool) (k : K) :\n    (d (checker k)).length≤ inventory d := by\n  change (d (checker k)).length≤∑j:K,(d (checker j)).length\n  exact Finset.single_le_sum (f:=fun j:K=>(d (checker j)).length)\n    (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n/-- Every static role is physically drained; each payload bit, EOF and fixed\nrole advance is paid. Neither a wholesale reset nor a host getter executes. -/\ntheorem clear_runs [Fintype K] (d : Stack K→List Bool) (n left : Nat) (h : n+left=s.roles.length) :\n    ∃t≤ left*(inventory d+1),Runs (program s) t (.clear ⟨n,by omega⟩)\n      (cleanPrefix s d n) (.clear ⟨s.roles.length,by omega⟩) (clean d) := by\n  induction left generalizing n with\n  | zero=>\n    have hn:n=s.roles.length:=by omega\n    subst n\n    rw [cleanPrefix_full]\n    exact ⟨0,by omega,runs_refl (program s) _ _⟩\n  | succ left ih=>\n    have hn:n<s.roles.length:=by omega\n    let p : Fin s.roles.length:=⟨n,hn⟩\n    have hd:=drain s (.clear ⟨n,by omega⟩) (.clear ⟨n+1,by omega⟩) (checker (role s p))\n      (by simp only [program,SemiprimeD1StackStaticWordTable.program,dite_eq_left hn];rfl) (cleanPrefix s d n)\n    have he:Function.update (cleanPrefix s d n) (checker (role s p)) []=cleanPrefix s d (n+1):=\n      cleanPrefix_step s d p\n    rw [he] at hd\n    obtain ⟨t,ht,hr⟩:=ih (n+1) (by omega)\n    have hb: (cleanPrefix s d n (checker (role s p))).length≤ inventory d:=\n      (cleanPrefix_length s d n _).trans (cell_le_inventory d (role s p))\n    have hout:=runs_trans (program s) _ _ _ _ _ _ _ _ hd hr\n    refine ⟨_,?_,hout⟩\n    rw [Nat.succ_mul];omega\n/-- The final actual return pops the real caller frame after ALL roles clear. -/\ntheorem clear_returns [Fintype K] (d : Stack K→List Bool) :\n    ∃t≤ s.roles.length*(inventory d+1)+1,Returns (program s) t (.clear 0) d (clean d) := by\n  obtain ⟨t,ht,hr⟩:=clear_runs s d 0 s.roles.length (by omega)\n  rw [cleanPrefix_zero] at hr\n  refine ⟨t+1,by omega,?_⟩\n  exact of_runs (program s) t (.clear 0) (.clear ⟨s.roles.length,by omega⟩) _ _ hr\n    (by simp only [program,SemiprimeD1StackStaticWordTable.program,dite_eq_right (Nat.lt_irrefl _)])\nend RiemannGaussian.SemiprimeD1StackVectorTableCleanup\n","RiemannGaussian.SemiprimeD1StackVectorTableEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTableSpec\nimport RiemannGaussian.SemiprimeD1StackVectorTablePrimitives\n/-! # Actual complete-vector preserving copy, tree tag and history reversal -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableEmit\nopen SemiprimeD1StackVectorTable SemiprimeD1StackVectorTableSpec\nopen SemiprimeD1StackVectorTablePrimitives SemiprimeD1StackProcedureTrace\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Actual preserving-copy output, buffer and restoration scratch remain distinct. -/\ntheorem vectorCopy_call (d : Stack K→List Bool) (hw : d (aux .work)=[]) (hs : d (aux .scratch)=[]) :\n    Runs (program s) (5*(d (checker s.output)).length+4) .emitSentinel d .emitLeaf\n      (Function.update d (aux .work) (d (checker s.output))) := by\n  let word := d (checker s.output)\n  let start := SemiprimeD1StackCopy.state 0 none word [] []\n  let stop := SemiprimeD1StackCopy.done word word\n  have hi : Link.DataRel (vectorCopyStack s) d start.store d := by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · exact hw\n      · exact hs\n    · intro k _;rfl\n  have ho := Link.data_update (vectorCopyStack s) (vectorCopy_injective s) d start.store d hi (1:Fin 3) word\n  have he : Function.update start.store 1 word=stop.store := by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call (program s) (vectorCopyStack s) (vectorCopyLabel s) (vectorCopy_injective s)\n    SemiprimeD1StackCopy.code 0 (vectorCopy_program s) .emitSentinel .emitLeaf rfl _\n    start stop d _ rfl rfl (by simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words word [] none) hi ho\nomit [DecidableEq K] in\n/-- The private record buffer is distinct from accumulated DFS history. -/\ntheorem recordReverse_injective : Function.Injective (recordReverseStack (K:=K)) := by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> simp_all [recordReverseStack,aux]\n/-- Actual consuming reversal appends exactly this record's reversed bytes to history. -/\ntheorem recordReverse_call (d : Stack K → List Bool) :\n    Runs (program s) (2*(d (aux .work)).length+3) .emitReverse d .leafCleanup\n      (Function.update (Function.update d (aux .work) []) (aux .reversed)\n        ((d (aux .work)).reverse++d (aux .reversed))) := by\n  let xs := d (aux .work)\n  let ys := d (aux .reversed)\n  let start := SemiprimeD1StackReverseWord.state none xs ys\n  let stop := SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi : Link.DataRel recordReverseStack d start.store d := by\n    constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  have h0 := Link.data_update recordReverseStack recordReverse_injective d start.store d hi (0:Fin 2) []\n  have ho := Link.data_update recordReverseStack recordReverse_injective d _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he : Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store := by\n    funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call (program s) recordReverseStack _root_.RiemannGaussian.SemiprimeD1StackStaticWordTable.Label.recordReverse recordReverse_injective\n    SemiprimeD1StackReverseWord.code 0 (fun _ => rfl) .emitReverse .leafCleanup rfl _\n    start stop d _ rfl rfl (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi ho\nomit [DecidableEq K] in\n/-- The complete ACTUAL vector payload receives exactly one tree-leaf FALSE tag. -/\ndef leafBytes (payload : List Bool) : List Bool := false::payload\nomit [DecidableEq K] in\n/-- No source vector framing is duplicated or interpreted by the compiler. -/\ntheorem leafBytes_length (payload : List Bool) : (leafBytes payload).length=payload.length+1 := rfl\n/-- Proof-only view of the actual temporary framing buffer. -/\ndef emitData (live original : K → List Bool) (bank front hist buffer : List Bool) : Stack K → List Bool :=\n  store live original (D.data bank [] [] [] [] [] []) front buffer [] hist []\n/-- A physical buffer update preserves all checker, template and scanner words. -/\ntheorem update_buffer (live original : K → List Bool) (bank front hist buffer fresh : List Bool) :\n    Function.update (emitData live original bank front hist buffer) (aux .work) fresh=\n      emitData live original bank front hist fresh := by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n/-- A physical history update preserves every other acquired word and empty helper. -/\ntheorem update_history (live original : K → List Bool) (bank front hist buffer fresh : List Bool) :\n    Function.update (emitData live original bank front hist buffer) (aux .reversed) fresh=\n      emitData live original bank front fresh buffer := by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n/-- Complete actual vector copying, tree-leaf tagging and consuming reversal, with every call/return charged. -/\ntheorem emit_run (live original : K→List Bool) (bank front hist : List Bool) :\n    Runs (program s) (7*(live s.output).length+8) .emitSentinel\n      (withChecker (data original bank 0 front hist) live) .leafCleanup\n      (withChecker (data original bank 0 front ((leafBytes (live s.output)).reverse++hist)) live) := by\n  let payload := live s.output\n  have h0 := vectorCopy_call s (emitData live original bank front hist []) rfl rfl\n  change Runs (program s) (5*payload.length+4) .emitSentinel\n    (emitData live original bank front hist []) .emitLeaf\n    (Function.update (emitData live original bank front hist []) (aux .work) payload) at h0\n  rw [update_buffer] at h0\n  have h1 := push s .emitLeaf .emitReverse (aux .reversed) false rfl\n    (emitData live original bank front hist payload)\n  change Runs (program s) 1 .emitLeaf (emitData live original bank front hist payload) .emitReverse\n    (Function.update (emitData live original bank front hist payload) (aux .reversed) (false::hist)) at h1\n  rw [update_history] at h1\n  have h2 := recordReverse_call s (emitData live original bank front (false::hist) payload)\n  change Runs (program s) (2*payload.length+3) .emitReverse\n    (emitData live original bank front (false::hist) payload) .leafCleanup\n    (Function.update (Function.update (emitData live original bank front (false::hist) payload)\n      (aux .work) []) (aux .reversed) (payload.reverse++false::hist)) at h2\n  rw [update_buffer,update_history] at h2\n  have he : payload.reverse++false::hist=(leafBytes payload).reverse++hist := by\n    simp only [leafBytes,List.reverse_cons,List.append_assoc,List.singleton_append]\n  rw [he] at h2\n  have hh := runs_trans (program s) _ _ _ _ _ _ _ _ (runs_trans (program s) _ _ _ _ _ _ _ _ h0 h1) h2\n  convert hh using 1\n  · dsimp only [payload];omega\n  · funext k;cases k <;> rfl\n  · funext k;cases k <;> rfl\n/-- Exact literal leaf bytes in the entire false-first table specification. -/\ntheorem leaf_bytes (answer : List Bool→List (List Bool)) (raw : List Bool) :\n    leafBytes (SemiprimeD1TensorTapeCodec.vectorBits (answer raw))=SemiprimeD1TensorTapeCodec.tape (tree answer raw 0) := rfl\nend RiemannGaussian.SemiprimeD1StackVectorTableEmit\n\n","RiemannGaussian.SemiprimeD1StackVertexArity":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueBounds\nimport RiemannGaussian.SemiprimeD1StackUnaryProduct\nimport RiemannGaussian.SemiprimeD1StackUnarySumLessBytecode\n\n/-! # Physical original-vertex arity from the actual cached counters\nThis internal procedure reads a physically parsed tag/index and shared source\nmetadata. The original-N port caller will acquire all of these inputs itself.\nNo native graph arity, comparison verdict or product answer is executed.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexArity\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (instruction DataRel data_unique Rel run_rel)\nend Link\nnamespace Product\nexport SemiprimeD1StackUnaryProduct (Stack Label code entry contents product_run)\nend Product\nnamespace Compare\nexport SemiprimeD1StackUnarySumLess (Stack contents)\nexport SemiprimeD1StackUnarySumLessBytecode (Label code entry compare_run)\nend Compare\n/-- Six actual readonly words; the index is the input constructor's second coordinate. -/\ninductive Source where\n  | tag | index | radiusSucc | firstAxis | secondAxis | digits\n  deriving DecidableEq,Repr\ninstance : Fintype Source where\n  elems:={.tag,.index,.radiusSucc,.firstAxis,.secondAxis,.digits}\n  complete:=by intro k;cases k <;> simp\n/-- Nine actual arity/copy/product/comparison work stacks. -/\ninductive Aux where\n  | arity | tagReader | copyScratch | multiplier | mulScratch\n  | compareLeft | compareRight | compareLimit | compareResult\n  deriving DecidableEq,Repr\ninstance : Fintype Aux where\n  elems:={.arity,.tagReader,.copyScratch,.multiplier,.mulScratch,.compareLeft,.compareRight,.compareLimit,.compareResult}\n  complete:=by intro k;cases k <;> simp\n/-- All fifteen physical data stacks have Boolean alphabets. -/\nabbrev Stack := Source⊕Aux\ninstance : DecidableEq Stack := inferInstanceAs (DecidableEq (Source⊕Aux))\ninstance : Fintype Stack := inferInstanceAs (Fintype (Source⊕Aux))\n/-- Static source-cache inclusion. -/\ndef source (key:Source) : Stack := .inl key\n/-- Static work/result inclusion. -/\ndef aux (key:Aux) : Stack := .inr key\n/-- The six actual source-preserving copy operations. -/\ninductive CopyKind | tag | radius | first | second | index | digits\n  deriving DecidableEq\ninstance : Fintype CopyKind where\n  elems:={.tag,.radius,.first,.second,.index,.digits}\n  complete:=by intro k;cases k <;> simp\n/-- Literal fixed finite arity control. -/\ninductive Control where\n  | main | decode (count:Fin 18) | invalidClear\n  | inputRadius | inputIndex | inputDigits | compare | verdict | inputFlag\n  | oneRadius | twoRadius (stage:Fin 2) | threeRadius (stage:Fin 3)\n  | multiplyFirst (stage:Fin 2) | multiplySecond (stage:Fin 2)\n  | product | literal (remaining:Fin 3) | halt\n  deriving DecidableEq,Fintype\n/-- Product/compare finite locations are fixed, not indexed by their operand values.\nThey require only Fintype, never label equality or Repr. -/\nabbrev Label := Control⊕((CopyKind×Fin 9)⊕(Product.Label⊕Compare.Label))\ninstance : Fintype Label := inferInstanceAs (Fintype (Control⊕((CopyKind×Fin 9)⊕(Product.Label⊕Compare.Label))))\n/-- Actual readonly copy supplier for each static case. -/\ndef copySource : CopyKind→Source\n  | .tag => .tag\n  | .radius => .radiusSucc\n  | .first => .firstAxis\n  | .second => .secondAxis\n  | .index => .index\n  | .digits => .digits\n/-- Actual destination for each static copy. -/\ndef copyTarget : CopyKind→Aux\n  | .tag => .tagReader\n  | .radius => .arity\n  | .first | .second => .multiplier\n  | .index => .compareRight\n  | .digits => .compareLimit\n/-- Literal three-stack Copy inclusion. -/\ndef copyStack (kind:CopyKind) (k:Fin 3) : Stack :=\n  if k=0 then source (copySource kind) else if k=1 then aux (copyTarget kind) else aux .copyScratch\n/-- Static included copy labels. -/\ndef copyLabel (kind:CopyKind) (pc:Fin 9) : Label := .inr (.inl (kind,pc))\n/-- Multiplicand aliases the actual readonly R+1 source, not an advised product. -/\ndef productStack : Product.Stack→Stack\n  | .multiplier => aux .multiplier\n  | .multiplicand => source .radiusSucc\n  | .scratch => aux .mulScratch\n  | .product => aux .arity\n/-- Static included product labels. -/\ndef productLabel (pc:Product.Label) : Label := .inr (.inr (.inl pc))\n/-- Actual compare operands: zero+copied index versus copied digit count. -/\ndef compareStack : Compare.Stack→Stack\n  | .left => aux .compareLeft\n  | .right => aux .compareRight\n  | .limit => aux .compareLimit\n  | .valid => aux .compareResult\n/-- Static included compare labels. -/\ndef compareLabel (pc:Compare.Label) : Label := .inr (.inr (.inr pc))\n/-- Only a static finite tag position chooses a literal original arity recipe. -/\ndef recipe (count:Fin 18) : Label :=\n  if count.val=0 then .inl .inputRadius\n  else if count.val=1 then .inl (.multiplySecond 0)\n  else if count.val=2 then .inl (.twoRadius 0)\n  else if count.val=3 then .inl (.multiplyFirst 0)\n  else if count.val=4 then .inl (.threeRadius 0)\n  else if count.val=5 then .inl .oneRadius\n  else if count.val=6 then .inl (.threeRadius 0)\n  else if count.val=7 then .inl .oneRadius\n  else if count.val=8 then .inl (.literal 2)\n  else if count.val=9 then .inl (.literal 0)\n  else .inl (.literal 1)\n/-- One fixed finite arity program; every multiply/compare/copy is an actual real call. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inl (kind,pc)) => Link.instruction (copyStack kind) (copyLabel kind) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr (.inl pc)) => Link.instruction productStack productLabel (Product.code pc)\n  | .inr (.inr (.inr pc)) => Link.instruction compareStack compareLabel (Compare.code pc)\n  | .inl .main => .call (copyLabel .tag 0) (.inl (.decode 0))\n  | .inl (.decode count) =>\n      let next:Label:=if h:count.val<17 then .inl (.decode ⟨count.val+1,by omega⟩) else .inl .invalidClear\n      .base (.pop (aux .tagReader) (recipe count) next next)\n  | .inl .invalidClear => .base (.pop (aux .tagReader) (.inl .halt) (.inl .invalidClear) (.inl .invalidClear))\n  | .inl .inputRadius => .call (copyLabel .radius 0) (.inl .inputIndex)\n  | .inl .inputIndex => .call (copyLabel .index 0) (.inl .inputDigits)\n  | .inl .inputDigits => .call (copyLabel .digits 0) (.inl .compare)\n  | .inl .compare => .call (compareLabel Compare.entry) (.inl .verdict)\n  | .inl .verdict => .base (.pop (aux .compareResult) (.inl .halt) (.inl .halt) (.inl .inputFlag))\n  | .inl .inputFlag => .base (.push (aux .arity) true (.inl .halt))\n  | .inl .oneRadius => .call (copyLabel .radius 0) (.inl .halt)\n  | .inl (.twoRadius stage) => .call (copyLabel .radius 0)\n      (if stage.val=0 then .inl (.twoRadius 1) else .inl .halt)\n  | .inl (.threeRadius stage) => .call (copyLabel .radius 0)\n      (if h:stage.val<2 then .inl (.threeRadius ⟨stage.val+1,by omega⟩) else .inl .halt)\n  | .inl (.multiplyFirst stage) => .call (copyLabel .first 0)\n      (if stage.val=0 then .inl (.multiplyFirst 1) else .inl .product)\n  | .inl (.multiplySecond stage) => .call (copyLabel .second 0)\n      (if stage.val=0 then .inl (.multiplySecond 1) else .inl .product)\n  | .inl .product => .call (productLabel Product.entry) (.inl .halt)\n  | .inl (.literal count) => .base (.push (aux .arity) true\n      (if count.val=0 then .inl .halt else .inl (.literal ⟨count.val-1,by omega⟩)))\n  | .inl .halt => .base .halt\n/-- Fixed internal finite machine for physical shared-metadata arity construction.\nThe public port caller supplies these words by its own original-N acquisition. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (source .tag) (aux .arity) (.inl .main) program\n/-- Literal source/working data, used only to describe actual configurations. -/\ndef data (header:Source→List Bool) (work:Aux→List Bool) : Stack→List Bool := Sum.elim header work\n/-- Every alphabet, including every product/compare/call location, is finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (source .tag) (aux .arity) (.inl .main) program\n/-- Fifteen actual Boolean data roles, independent of graph dimensions. -/\ntheorem stack_card : Fintype.card Stack=15 := by decide\nend RiemannGaussian.SemiprimeD1StackVertexArity\n","RiemannGaussian.SemiprimeD1StackVertexRecordStreamExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexRecordStream\n\n/-! # Literal calls, forward-order invariant and complete physical prefix cells -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexRecordStreamExecution\nopen SemiprimeD1StackVertexRecordStream\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (instruction DataRel)\nend Link\n/-- Forward rows without the single final list tag; proof notation only. -/\ndef rows : List SemiprimeD1LeafCounter.Vertex → List Bool\n  | [] => []\n  | v::vs => row (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (SemiprimeD1TensorTapeCodec.tape v.table) ++ rows vs\n/-- The physically seeded output terminator recovers the exact frozen stream. -/\ntheorem rows_records (vs : List SemiprimeD1LeafCounter.Vertex) :\n    rows vs ++ [false] = SemiprimeD1StackVertexProduct.records vs := by\n  induction vs with\n  | nil => rfl\n  | cons v vs ih =>\n    rw [rows,List.append_assoc,ih,row_records]\n/-- New acquired rows append in original forward order. -/\ntheorem rows_append (xs ys : List SemiprimeD1LeafCounter.Vertex) : rows (xs++ys)=rows xs++rows ys := by\n  induction xs with\n  | nil => rfl\n  | cons v vs ih => simp only [List.cons_append,rows,ih,List.append_assoc]\n/-- Physical state invariant after each forward acquisition/log call. -/\ndef history (vs : List SemiprimeD1LeafCounter.Vertex) (old : List Bool) : List Bool :=\n  (rows vs).reverse ++ old\n/-- Each paid source run advances the whole forward-order history invariant. -/\ntheorem record_forward (previous : List SemiprimeD1LeafCounter.Vertex)\n    (v : SemiprimeD1LeafCounter.Vertex) (old out : List Bool) (flag : Option Bool) :\n    B.run code (recordTime (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (SemiprimeD1TensorTapeCodec.tape v.table))\n      ⟨some .record,flag,data (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n        (SemiprimeD1TensorTapeCodec.tape v.table) (history previous old) out⟩ =\n      some ⟨none,none,data [] [] (history (previous++[v]) old) out⟩ := by\n  rw [record_run]\n  simp only [history,rows_append,rows,List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final reversal yields the exact original vertex list and retained outer suffix. -/\ntheorem reverse_original (vs : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    B.run code (2*(rows vs).length+2)\n      ⟨some .reverse,none,data [] [] (history vs []) (false::out)⟩ =\n      some ⟨none,none,data [] [] [] (SemiprimeD1StackVertexProduct.records vs++out)⟩ := by\n  have h:=reverse_run (rows vs).reverse [] [] (false::out) none\n  rw [←rows_records vs]\n  simpa only [history,List.append_nil,List.length_reverse,List.reverse_reverse,\n    List.append_assoc,List.singleton_append] using h\n\n/-- One real caller instruction enters the same fixed logger; its halt becomes a\nreal return pop. All four roles and every outer return cell are preserved exactly. -/\ntheorem call {K G : Type} [DecidableEq K]\n    (program : G → C.Instruction K G) (stack : Stack → K) (label : Label → G)\n    (hinj : Function.Injective stack) (entry : Label)\n    (hcode : ∀l,program (label l)=Link.instruction stack label (code l))\n    (pc next : G) (hcall : program pc=.call (label entry) next)\n    (time : Nat) (source result : Stack → List Bool) (outer target : K → List Bool)\n    (hr : B.run code time ⟨some entry,none,source⟩=some ⟨none,none,result⟩)\n    (hin : Link.DataRel stack outer source outer)\n    (hout : Link.DataRel stack outer result target) :\n    Runs program (time+1) pc outer next target := by\n  exact included_call program stack label hinj code entry hcode pc next hcall time\n    ⟨some entry,none,source⟩ ⟨none,none,result⟩ outer target rfl rfl hr hin hout\n\n/-- Actual compiled caller, logger and return, then caller halt; no data getter. -/\ndef recordInTime (ports table hist out : List Bool) :\n    StateTransition.EvalsToInTime (machine .record).step\n      (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.initial (L:=Label) (data ports table hist out)))\n      (some (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.final (L:=Label)\n          (data [] [] ((row ports table).reverse++hist) out)))) (recordTime ports table+2) := by\n  exact SemiprimeD1StackReturnLink.linkedInTime .record code Stack.ports Stack.output\n    (recordTime ports table) _ _ (record_run ports table hist out none)\n/-- Compiled initialization includes actual call, return and caller halt. -/\ndef initializeInTime (ports table hist out : List Bool) :\n    StateTransition.EvalsToInTime (machine .initialize).step\n      (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.initial (L:=Label) (data ports table hist out)))\n      (some (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.final (L:=Label) (data ports table hist (false::out))))) 4 := by\n  exact SemiprimeD1StackReturnLink.linkedInTime .initialize code Stack.ports Stack.output\n    2 _ _ (initialize_run ports table hist out none)\n/-- Compiled final reversal includes actual call, return and caller halt. -/\ndef reverseInTime (ports table hist out : List Bool) :\n    StateTransition.EvalsToInTime (machine .reverse).step\n      (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.initial (L:=Label) (data ports table hist out)))\n      (some (SemiprimeD1StackCalls.configuration\n        (SemiprimeD1StackReturnLink.final (L:=Label) (data ports table [] (hist.reverse++out)))))\n      (2*hist.length+4) := by\n  exact SemiprimeD1StackReturnLink.linkedInTime .reverse code Stack.ports Stack.output\n    (2*hist.length+2) _ _ (reverse_run hist ports table out none)\n\n/-- Every source prefix counts all four Boolean roles and actual finite-label\nreturn cells. It applies independently of entry, flags, data values or input size. -/\ntheorem prefix_cells (entry : Label) (ports table hist out : List Bool) (fuel : Nat)\n    (finish : SemiprimeD1StackCalls.State Stack (Label⊕Bool))\n    (hr : SemiprimeD1StackCalls.run (SemiprimeD1StackReturnLink.code entry code) fuel\n      (SemiprimeD1StackReturnLink.initial (L:=Label) (data ports table hist out))=some finish) :\n    (finish.data .ports).length+(finish.data .table).length+\n      (finish.data .history).length+(finish.data .output).length+finish.frames.length ≤\n      5*(ports.length+table.length+hist.length+out.length+fuel) := by\n  have h:=SemiprimeD1StackReturnLink.run_data_bound\n    (SemiprimeD1StackReturnLink.code entry code) fuel\n    (ports.length+table.length+hist.length+out.length) _ finish (by\n      intro k;cases k <;> simp only [SemiprimeD1StackReturnLink.initial,data] <;> omega) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound _ fuel _ finish hr\n  change finish.frames.length ≤ 0+fuel at hf\n  have hp:=h .ports\n  have ht:=h .table\n  have hh:=h .history\n  have ho:=h .output\n  omega\n/-- The actual compiled prefix has exactly the same complete payload, including\nflags and return cells, at the same source transition count. -/\ntheorem compiled_prefix (entry : Label) (fuel : Nat)\n    (start : SemiprimeD1StackCalls.State Stack (Label⊕Bool)) :\n    (SemiprimeD1StackCalls.run (SemiprimeD1StackReturnLink.code entry code) fuel start).map\n      SemiprimeD1StackCalls.configuration =\n      (fun cfg=>cfg.bind (machine entry).step)^[fuel]\n        (some (SemiprimeD1StackCalls.configuration start)) := by\n  exact SemiprimeD1StackCalls.run_correct Stack.ports Stack.output (.inr false)\n    (SemiprimeD1StackReturnLink.code entry code) fuel start\nend RiemannGaussian.SemiprimeD1StackVertexRecordStreamExecution\n","RiemannGaussian.SemiprimeD1StackWeightedModeOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeView\n/-! # Original feasible-branch order for the real subtraction controller\nNatural division occurs ONLY in these mathematical target lists. The executed\nsource decides continuation by physically subtracting one positive weight.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeOrder\nopen SemiprimeD1WeightedTuples (tuples visits)\n/-- Remaining feasible branches when the current real exponent is e. -/\ndef branches (w:Nat) (ws:List Nat) (R e:Nat) :List (List Nat):=\n  (List.range (R/w+1)).flatMap fun k=>(tuples ws (R-w*k)).map ((e+k)::·)\n/-- Actual child-node count of those remaining feasible branches; never a runtime counter input. -/\ndef childVisits (w:Nat) (ws:List Nat) (R:Nat) :Nat:=\n  ((List.range (R/w+1)).map fun k=>visits ws (R-w*k)).sum\n/-- A successful actual subtraction creates exactly the next residual in the native target order. -/\ntheorem residual_succ (R w k:Nat) :R-w*(k+1)=(R-w)-w*k:=by\n  rw [Nat.mul_succ]\n  omega\n/-- Current exponent zero is exactly the original weighted tuple list. -/\ntheorem branches_zero (w:Nat) (ws:List Nat) (P:Nat) :branches w ws P 0=tuples (w::ws) P:=by\n  simp only [branches,SemiprimeD1WeightedTuples.tuples,Nat.zero_add]\n/-- The only failed subtraction leaves exactly the current zero-offset branch. -/\ntheorem branches_last (w:Nat) (ws:List Nat) (R e:Nat) (h:R < w) :\n    branches w ws R e=(tuples ws R).map (e::·):=by\n  simp only [branches,Nat.div_eq_of_lt h,Nat.zero_add,List.range_one,List.flatMap_cons,List.flatMap_nil,\n    List.append_nil,Nat.add_zero,Nat.mul_zero,Nat.sub_zero]\n/-- Successful subtraction follows the current complete child by the next feasible exponent block. -/\ntheorem branches_step (w:Nat) (ws:List Nat) (R e:Nat) (hw:0 < w) (hr:w ≤ R) :\n    branches w ws R e=(tuples ws R).map (e::·)++branches w ws (R-w) (e+1):=by\n  unfold branches\n  rw [Nat.div_eq_sub_div hw hr,List.range_succ_eq_map]\n  simp only [List.flatMap_cons,List.flatMap_map,Nat.mul_zero,Nat.sub_zero,Nat.add_zero]\n  apply congrArg (fun tail=>(tuples ws R).map (e::·)++tail)\n  apply congrArg (fun f=>List.flatMap f (List.range ((R-w)/w+1)))\n  funext k\n  change (tuples ws (R-w*(k+1))).map ((e+(k+1))::·)=_\n  rw [residual_succ]\n  have he:e+(k+1)=(e+1)+k:=by omega\n  rw [he]\n/-- Native visits are the exact feasible recursion node plus its actual child blocks. -/\ntheorem visits_cons (w:Nat) (ws:List Nat) (P:Nat) :visits (w::ws) P=1+childVisits w ws P:=rfl\n/-- The last physical subtraction failure contributes no further child visits. -/\ntheorem childVisits_last (w:Nat) (ws:List Nat) (R:Nat) (h:R < w) :childVisits w ws R=visits ws R:=by\n  simp only [childVisits,Nat.div_eq_of_lt h,Nat.zero_add,List.range_one,List.map_cons,List.map_nil,List.sum_cons,\n    List.sum_nil,Nat.add_zero,Nat.mul_zero,Nat.sub_zero]\n/-- Successful repeated subtraction partitions the SAME actual feasible children. -/\ntheorem childVisits_step (w:Nat) (ws:List Nat) (R:Nat) (hw:0 < w) (hr:w ≤ R) :\n    childVisits w ws R=visits ws R+childVisits w ws (R-w):=by\n  unfold childVisits\n  rw [Nat.div_eq_sub_div hw hr,List.range_succ_eq_map]\n  simp only [List.map_cons,List.sum_cons,List.map_map,Function.comp_def,Nat.mul_zero,Nat.sub_zero]\n  congr 1\n  apply congrArg List.sum\n  apply List.map_congr_left\n  intro k _\n  change visits ws (R-w*(k+1))=visits ws ((R-w)-w*k)\n  rw [residual_succ]\n/-- Every real branch has a zero completion, so branch overhead is charged to feasible nodes. -/\ntheorem branches_le_visits (w:Nat) (ws:List Nat) (R:Nat) :R/w+1 ≤ childVisits w ws R:=by\n  have h:=List.sum_le_sum (fun k (_:k∈List.range (R/w+1))=>\n    Nat.succ_le_of_lt (SemiprimeD1WeightedTuples.visits_positive ws (R-w*k)))\n  simpa [childVisits] using h\n/-- Each successful continuation has strictly smaller physical residual for a positive weight. -/\ntheorem residual_lt (R w:Nat) (hw:0 < w) (hr:w ≤ R) :R-w < R:=by omega\nend RiemannGaussian.SemiprimeD1StackWeightedModeOrder\n","RiemannGaussian.SemiprimeD1StackWordVector":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordBlockBounds\nimport RiemannGaussian.SemiprimeD1StackAssignmentBody\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n\n/-! # Physical word-vector acquisition from the actual assignment tape\nThe actual count cache drives closed word-block calls. Each actual fixed-width\nword is logged in reverse framed form; one physical reversal then gives the\noriginal word order. Original input, unread suffix and both caches are retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWordVector\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Block\nexport SemiprimeD1StackWordBlock (Stack Label program initial store)\nend Block\nnamespace Body\nexport SemiprimeD1StackAssignmentBody (Stack Label code entry contents body_run)\nend Body\n\n/-- Ten fixed Boolean roles: five block roles and five acquisition/cache roles. -/\nabbrev Stack := Block.Stack⊕Fin 5\n/-- Actual retained original binary assignment tape. -/\ndef original : Stack := .inr 4\n/-- Retained physical count-marker cache; only its byte LENGTH is used. -/\ndef countCache : Stack := .inr 0\n/-- Actual disposable count, acquired by a preserving copy. -/\ndef remaining : Stack := .inr 1\n/-- Real reverse-framed chronological word history. -/\ndef history : Stack := .inr 2\n/-- Final physically produced encoded vector. -/\ndef output : Stack := .inr 3\n/-- Real copy of either original input or retained physical count. -/\ndef copyStack (count : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if count then countCache else original) else\n  if k=1 then (if count then remaining else .inl 0) else .inl 3\n/-- Real reverse-entry logging shares only the restored block scratch. -/\ndef bodyStack : Body.Stack→Stack\n  | .word => .inl 4 | .scratch => .inl 3 | .history => history\n/-- Fixed literal source acquisition and reversal phases. -/\ninductive Control where\n  | start | copyCount | loop | blockCall | logCall | clearBlock | finish | reverse | emit (bit : Bool) | done\n  deriving DecidableEq,Fintype,Repr\n/-- All included component locations are finite before every assignment. -/\ninductive Label where\n  | control (pc : Control) | copy (count : Bool) (pc : Fin 9)\n  | block (pc : Block.Label) | body (pc : Body.Label)\n  deriving Fintype\nlocal notation \"ctl\" => SemiprimeD1StackWordVector.Label.control\n/-- ONE closed literal finite program, with no grouping or selected-word opcode. -/\ndef program : Label→C.Instruction Stack Label\n  | .control .start => .call (.copy false 0) (ctl .copyCount)\n  | .control .copyCount => .call (.copy true 0) (ctl .loop)\n  | .control .loop => .base (.pop remaining (ctl .finish) (ctl .blockCall) (ctl .blockCall))\n  | .control .blockCall => .call (.block .start) (ctl .logCall)\n  | .control .logCall => .call (.body Body.entry) (ctl .clearBlock)\n  | .control .clearBlock => .base (.pop (.inl 4) (ctl .loop) (ctl .clearBlock) (ctl .clearBlock))\n  | .control .finish => .base (.push output false (ctl .reverse))\n  | .control .reverse => .base (.pop history (ctl .done) (ctl (.emit false)) (ctl (.emit true)))\n  | .control (.emit b) => .base (.push output b (ctl .reverse))\n  | .control .done => .base .halt\n  | .copy count pc => SemiprimeD1StackMultiplierLink.instruction (copyStack count) (Label.copy count)\n      (SemiprimeD1StackCopy.code pc)\n  | .block pc => SemiprimeD1StackValidationLink.instruction Sum.inl Label.block (Block.program pc)\n  | .body pc => SemiprimeD1StackMultiplierLink.instruction bodyStack Label.body (Body.code pc)\n/-- Clean reached payload view; all block/restore scratch is empty here. -/\ndef store (word reader width count todo block hist out : List Bool) : Stack→List Bool :=\n  Sum.elim (Block.store reader width [] [] block)\n    (fun k=>if k=0 then count else if k=1 then todo else if k=2 then hist else if k=3 then out else word)\n/-- Only original raw assignment, physical width template and count cache enter. -/\ndef initial (word width count : List Bool) : C.State Stack Label :=\n  ⟨some (ctl .start),none,none,store word [] width count [] [] [] [],[]⟩\n/-- All actual copy roles are distinct. -/\ntheorem copyStack_injective (count : Bool) : Function.Injective (copyStack count) := by cases count <;> decide\n/-- Actual logger word/restoration/history are disjoint. -/\ntheorem bodyStack_injective : Function.Injective bodyStack := by\n  intro i j h;cases i <;> cases j <;> simp_all [bodyStack,history]\n/-- Genuine fixed finite bit machine, independent of every original assignment. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine original output (ctl .start) program\n/-- Actual Boolean and return-tag alphabets are fixed and finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite original output (ctl .start) program\n/-- No word, count, width, original value, list or grouping closure is in control. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite original output (ctl .start) program\n/-- Every physical data role is counted at all actual prefixes. -/\ntheorem stack_card : Fintype.card Stack=10 := by decide\n\nend RiemannGaussian.SemiprimeD1StackWordVector\n","RiemannGaussian.SemiprimeD1TensorTapeFieldBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldExecution\n\n/-! # Concrete finite-program and stack-cell bounds for tape field parsing\nNo unbounded object occurs in internal control or an alphabet symbol. Actual\nTM2 transition paths control both time and all three physical stack inventories.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1TensorTapeFieldBounds\nopen Turing Turing.TM2 SemiprimeD1TensorTapeFieldMachine\nopen SemiprimeD1TensorTapeFieldExecution SemiprimeSourceHistogramKeyBits\n\n/-- Static instruction depth counts real stack/control syntax nodes on a branch. -/\ndef instructionDepth : Stmt Alphabet PC Registers → ℕ\n  | .push _ _ q => 1+instructionDepth q\n  | .peek _ _ q => 1+instructionDepth q\n  | .pop _ _ q => 1+instructionDepth q\n  | .load _ q => 1+instructionDepth q\n  | .branch _ q r => 1+max (instructionDepth q) (instructionDepth r)\n  | .goto _ => 1\n  | .halt => 1\n\n/-- Each actual TM2 label executes at most two fixed stack/control instructions. -/\ntheorem program_depth (pc : PC) : instructionDepth (program pc)=2 := by\n  cases pc <;> rfl\n\n/-- Every actual jump stays inside the fixed finite label catalogue. -/\ntheorem program_supports : TM2.Supports program Finset.univ := by\n  constructor\n  · simp\n  · intro pc hpc\n    cases pc <;> simp [program,TM2.SupportsStmt]\n\n/-- The official FinTM2 initial configuration is the literal input-stack layout. -/\ntheorem init_eq (xs : List Bool) : Turing.initList machine xs=\n    config (some .tagPop) (none,false) xs [] [] := by\n  unfold Turing.initList config\n  dsimp only [machine]\n  congr 1\n  funext k\n  cases k <;> rfl\n\n/-- Actual bundled-machine time certificate with all stack alphabets equal to Bool. -/\ndef bundledInTime (xs : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine xs)\n      (some (final xs)) (4*xs.length+6) := by\n  rw [init_eq]\n  exact splitInTime xs\n\n/-- Actual valid-field transition count is independent of the unconsumed tail. -/\ntheorem fieldSteps_frame (word tail : List Bool) : fieldSteps (frame word tail)=8*word.length+4 := by\n  induction word with\n  | nil => rfl\n  | cons b bs ih =>\n    simp only [frame,fieldSteps,List.length_cons,ih]\n    omega\n\n/-- Exact machine certificate for a real serialized coefficient field: every\ncopied bit costs its actual scan/reversal transitions; the tail is preserved. -/\ndef framedInTime (word tail : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine (frame word tail))\n      (some (config none (none,true) tail [] word)) (8*word.length+4) := by\n  rw [init_eq]\n  have h:=parse_exec (frame word tail) (none,false) [] []\n  have hs:=split_frame word tail\n  simp only [List.length_nil,Nat.mul_zero,Nat.zero_add,List.reverse_nil,List.nil_append,List.append_nil,\n    fieldSteps_frame,hs.1,hs.2.1,hs.2.2] at h\n  exact h.inTime\n\n/-- ALL unbounded machine data are these three stacks of individual Boolean symbols. -/\ndef cells (c : Cfg Alphabet PC Registers) : ℕ :=\n  (c.stk Stack.input).length+(c.stk Stack.scratch).length+(c.stk Stack.output).length\n\n/-- A single actual finite instruction label allocates at most one stack symbol. -/\ntheorem step_cells (c d : Cfg Alphabet PC Registers)\n    (h : SemiprimeD1TensorTapeFieldMachine.step c=some d) : cells d ≤ cells c+1 := by\n  rcases c with ⟨pc,⟨flag,valid⟩,store⟩\n  cases pc with\n  | none => simp [SemiprimeD1TensorTapeFieldMachine.step,TM2.step] at h\n  | some pc =>\n    cases flag with\n    | none =>\n      cases pc <;>\n        simp only [SemiprimeD1TensorTapeFieldMachine.step,TM2.step,program,TM2.stepAux] at h <;>\n        cases h <;> simp [cells,Function.update] <;> omega\n    | some b =>\n      cases b <;> cases pc <;>\n        simp only [SemiprimeD1TensorTapeFieldMachine.step,TM2.step,program,TM2.stepAux] at h <;>\n        cases h <;> simp [cells,Function.update] <;> omega\n\n/-- All intermediate actual paths, not only the final output, have a linear cell cap. -/\ntheorem path_cells {n : ℕ} {c d : Cfg Alphabet PC Registers} (h : Executes n c d) :\n    cells d ≤ cells c+n := by\n  induction h with\n  | refl c => omega\n  | @next n c e d hs ht ih =>\n    have hh:=step_cells c e hs\n    omega\n\n/-- Every visited parsing configuration has a derived linear total stack footprint. -/\ntheorem parser_cells (xs : List Bool) (n : ℕ) (c : Cfg Alphabet PC Registers)\n    (h : Executes n (config (some .tagPop) (none,false) xs [] []) c)\n    (hn : n ≤ 4*xs.length+6) : cells c ≤ 5*xs.length+6 := by\n  have hh:=path_cells h\n  simp only [cells,config,contents,List.length_nil,Nat.add_zero] at hh\n  unfold cells\n  omega\n\nend RiemannGaussian.SemiprimeD1TensorTapeFieldBounds\n","RiemannGaussian.SemiprimeD1TensorTapeTreeExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeTreeMachine\n\n/-! # Exact execution of serialized table lookup\nNo supplied lookup result or tree-height register occurs in the machine. The\ninduction below verifies the fixed pending-task program on actual serialized data.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1TensorTapeTreeExecution\nopen Turing Turing.TM2\nopen SemiprimeD1TensorTapeTreeMachine\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1TensorTables (Table lookup)\n\n/-- The actual scan length of both subtrees, regardless of the selected path. -/\ndef scanSteps : {n : ℕ} → Table n → ℕ\n  | _,.leaf ws => (vectorBits ws).length+3\n  | _,.fork low high => 2+scanSteps low+scanSteps high\n\n/-- Pop one physical pending seek/skip bit. -/\ntheorem task_cons (mode : Bool) (xs tasks path rev out : List Bool) :\n    step (cfg (some .task) (none,false) xs (mode::tasks) path rev out)=\n      some (cfg (some .node) (some mode,mode) xs tasks path rev out) := by\n  simp [SemiprimeD1TensorTapeTreeMachine.step,program,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- A literal leaf tag enters the raw vector scanner. -/\ntheorem node_leaf (mode : Bool) (xs tasks path rev out : List Bool) :\n    step (cfg (some .node) (some mode,mode) (false::xs) tasks path rev out)=\n      some (cfg (some .marker) (some false,mode) xs tasks path rev out) := by\n  simp [SemiprimeD1TensorTapeTreeMachine.step,program,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- A completed vector resets only the finite flags and resumes pending tasks. -/\ntheorem resume_step (mode : Bool) (xs tasks path rev out : List Bool) :\n    step (cfg (some .resume) (some false,mode) xs tasks path rev out)=\n      some (cfg (some .task) (none,false) xs tasks path rev out) := by rfl\n\n/-- Skipping a fork schedules both actual subtrees without touching the query. -/\ntheorem node_skip (xs tasks path rev out : List Bool) :\n    step (cfg (some .node) (some false,false) (true::xs) tasks path rev out)=\n      some (cfg (some .task) (none,false) xs (false::false::tasks) path rev out) := by\n  simp [SemiprimeD1TensorTapeTreeMachine.step,program,forkTasks,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- Seeking a fork consumes one query cell; EOF selects the low branch. -/\ntheorem node_seek (xs tasks path rev out : List Bool) :\n    step (cfg (some .node) (some true,true) (true::xs) tasks path rev out)=\n      some (cfg (some .task) (none,false) xs\n        ((!(path.head?.getD false))::path.head?.getD false::tasks) path.tail rev out) := by\n  simp [SemiprimeD1TensorTapeTreeMachine.step,program,forkTasks,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- Each complete tree consumes exactly its encoding, selecting at most one vector. -/\ntheorem tree_scan {n : ℕ} (table : Table n) (tail tasks path rev out : List Bool) (mode : Bool) :\n    Executes (scanSteps table)\n      (cfg (some .task) (none,false) (tape table++tail) (mode::tasks) path rev out)\n      (cfg (some .task) (none,false) tail tasks (if mode then path.drop n else path)\n        (if mode then (vectorBits (lookup table path).words).reverse++rev else rev) out) := by\n  induction table generalizing tail tasks path rev mode with\n  | leaf ws =>\n    have he := Executes.next (task_cons mode _ tasks path rev out)\n      (Executes.next (node_leaf mode _ tasks path rev out)\n        ((vector_scan ws tail tasks path rev out mode (some false)).trans\n          (Executes.next (resume_step mode tail tasks path _ out) (Executes.refl _))))\n    convert he using 1 <;> simp [scanSteps,tape,lookup,SemiprimeD1JetAxes.copyVector_value,\n      List.cons_append,Nat.add_assoc]\n  | @fork n low high ihl ihh =>\n    cases mode with\n    | false =>\n      have hl := ihl (tape high++tail) (false::tasks) path rev false\n      have hh := ihh tail tasks path rev false\n      have he := Executes.next (task_cons false _ tasks path rev out)\n        (Executes.next (node_skip _ tasks path rev out) (hl.trans (by simpa using hh)))\n      convert he using 1 <;> simp [scanSteps,tape,List.cons_append,List.append_assoc,Nat.add_assoc]\n      all_goals omega\n    | true =>\n      by_cases hb : path.head?.getD false\n      · have hl := ihl (tape high++tail) (true::tasks) path.tail rev false\n        have hh := ihh tail tasks path.tail rev true\n        have he := Executes.next (task_cons true _ tasks path rev out)\n          (Executes.next (node_seek _ tasks path rev out)\n            (by simpa only [hb,Bool.not_true,Bool.false_eq_true,ite_false] using\n              hl.trans (by simpa using hh)))\n        convert he using 1 <;> simp [scanSteps,tape,lookup,hb,List.cons_append,List.append_assoc,\n          Nat.add_assoc]\n        all_goals omega\n      · have hl := ihl (tape high++tail) (false::tasks) path.tail rev true\n        have hh := ihh tail tasks (path.tail.drop n)\n          ((vectorBits (lookup low path.tail).words).reverse++rev) false\n        have he := Executes.next (task_cons true _ tasks path rev out)\n          (Executes.next (node_seek _ tasks path rev out)\n            (by simpa only [Bool.eq_false_iff.mpr hb,Bool.not_false,Bool.true_eq,ite_true] using\n              hl.trans (by simpa using hh)))\n        convert he using 1 <;> simp [scanSteps,tape,lookup,hb,List.cons_append,List.append_assoc,\n          Nat.add_assoc]\n        all_goals omega\n\n/-- Exhausting the physical task stack starts the final reversal. -/\ntheorem task_nil (xs path rev out : List Bool) :\n    step (cfg (some .task) (none,false) xs [] path rev out)=\n      some (cfg (some .reverse) (none,false) xs [] path rev out) := by\n  simp [SemiprimeD1TensorTapeTreeMachine.step,program,cfg,contents,TM2.step,TM2.stepAux]\n\n/-- Complete lookup has exact literal selected-vector output and exact suffix. -/\ntheorem lookup_exec {n : ℕ} (table : Table n) (path tail : List Bool) :\n    Executes (scanSteps table+(vectorBits (lookup table path).words).length+2)\n      (cfg (some .task) (none,false) (tape table++tail) [true] path [] [])\n      (cfg none (none,false) tail [] (path.drop n) []\n        (vectorBits (lookup table path).words)) := by\n  have hs := tree_scan table tail [] path [] [] true\n  have ht := Executes.next\n    (task_nil tail (path.drop n) ((vectorBits (lookup table path).words).reverse++[]) [])\n    (reverse_exec (none,false) tail [] (path.drop n)\n      ((vectorBits (lookup table path).words).reverse++[]) [])\n  have hh := hs.trans (by simpa using ht)\n  simpa [Nat.add_assoc] using hh\n\n/-- Skipping is genuine whole-tree traversal with exact suffix preservation. -/\ntheorem skip_exec {n : ℕ} (table : Table n) (path tail : List Bool) :\n    Executes (scanSteps table+2)\n      (cfg (some .task) (none,false) (tape table++tail) [false] path [] [])\n      (cfg none (none,false) tail [] path [] []) := by\n  have hs := tree_scan table tail [] path [] [] false\n  have ht := Executes.next (task_nil tail path [] [])\n    (reverse_exec (none,false) tail [] path [] [])\n  simpa using hs.trans (by simpa using ht)\n\nend RiemannGaussian.SemiprimeD1TensorTapeTreeExecution\n","RiemannGaussian.SemiprimeD1VertexDescriptorDecode":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1EdgeCatalogueEncoding\n/-! # Proof-side exact inverse for actual original vertex descriptors\nThis inverse licenses uniqueness of physical endpoint-key lookup. It is NOT\nexecuted as a native graph/owner oracle by the forthcoming finite machine.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1VertexDescriptorDecode\nopen SemiprimeMacroGraph\nopen SemiprimeD1EdgeCatalogueEncoding\n/-- Total proof-side bounded coordinate decoder. -/\ndef fin (n k:ℕ) : Option (Fin n) := if h:k<n then some ⟨k,h⟩ else none\n/-- Every actual finite coordinate decodes identically. -/\n@[simp] theorem fin_val {n:ℕ} (i:Fin n) : fin n i.val=some i := by simp [fin,i.isLt]\n/-- Total proof-side decoder of the actual three transform tags. -/\ndef transform (k:ℕ) : Option Transform :=\n  if h:k<2 then some (.inl ⟨k,h⟩) else if k=2 then some (.inr ()) else none\n/-- Each actual transform code is decoded without an ordering premise. -/\n@[simp] theorem transform_code (tr:Transform) :\n    transform (SemiprimeD1VertexCatalogueEncoding.transformCode tr)=some tr := by\n  cases tr with\n  | inl side => simp [transform,SemiprimeD1VertexCatalogueEncoding.transformCode,side.isLt]\n  | inr u => cases u;rfl\n/-- Literal finite constructor reconstruction, used only in semantic uniqueness proofs. -/\ndef numbers (r t digits code a b c d:ℕ) : Option (SubdividedVertex r t digits) :=\n  match code with\n  | 0 => do let s←fin 2 a;let i←fin (r*t) b;pure (.inl (.input s i))\n  | 1 => do let tr←transform a;let j←fin r b;pure (.inl (.first tr j))\n  | 2 => do let tr←transform a;let j←fin r b;let k←fin t c;pure (.inl (.scale tr j k))\n  | 3 => do let tr←transform a;let k←fin t b;pure (.inl (.second tr k))\n  | 4 => do let i←fin (r*t) a;pure (.inl (.product i))\n  | 5 => pure (.inl .carryInitial)\n  | 6 => do let i←fin (r*t) a;pure (.inl (.carry i))\n  | 7 => pure (.inl .carryTerminal)\n  | 8 => do let s←fin 2 a;let i←fin (digits-1) b;pure (.inl (.orGate s i))\n  | 9 => do let s←fin 2 a;pure (.inl (.inputCheck s))\n  | 10 => do let s←fin 2 a;let i←fin (r*t) b;let bit←fin (r*t+1) c;pure (.inr (.inl (.input s i,bit)))\n  | 11 => do let tr←transform a;let j←fin r b;let k←fin t c;let bit←fin (r*t+1) d;pure (.inr (.inl (.first tr j k,bit)))\n  | 12 => do let tr←transform a;let j←fin r b;let k←fin t c;let bit←fin (r*t+1) d;pure (.inr (.inl (.twiddle tr j k,bit)))\n  | 13 => do let tr←transform a;let k←fin t b;let j←fin r c;let bit←fin (r*t+1) d;pure (.inr (.inl (.second tr k j,bit)))\n  | 14 => do let i←fin (r*t) a;let bit←fin (r*t+1) b;pure (.inr (.inl (.product i,bit)))\n  | 15 => do let i←fin (r*t+1) a;let bit←fin (r*t+1) b;pure (.inr (.inl (.carry i,bit)))\n  | 16 => do let s←fin 2 a;let i←fin digits b;pure (.inr (.inr (.digit s i)))\n  | 17 => do let s←fin 2 a;let i←fin (digits-1) b;pure (.inr (.inr (.orOut s i)))\n  | _ => none\n/-- Physical descriptor words are interpreted by their actual unary lengths, for proofs only. -/\ndef decode (r t digits:ℕ) (words:Record) : Option (SubdividedVertex r t digits) :=\n  numbers r t digits (words 0).length (words 1).length (words 2).length (words 3).length (words 4).length\n/-- Every actual original vertex has exactly its literal tag/coordinate descriptor. -/\ntheorem decode_vertex {r t digits:ℕ} (v:SubdividedVertex r t digits) :\n    decode r t digits (vertex v)=some v := by\n  cases v with\n  | inl v => cases v <;> simp [decode,vertex,arithmetic,fields,numbers,SemiprimeD1VertexCatalogueModes.code]\n  | inr signal =>\n    cases signal with\n    | inl pair =>\n      rcases pair with ⟨word,b⟩\n      cases word <;> simp [decode,vertex,SemiprimeD1EdgeCatalogueEncoding.bit,fields,numbers,SemiprimeD1VertexCatalogueModes.code]\n    | inr flag => cases flag <;> simp [decode,vertex,SemiprimeD1EdgeCatalogueEncoding.bit,fields,numbers,SemiprimeD1VertexCatalogueModes.code]\n/-- Physical descriptor equality cannot alias two original vertices. -/\ntheorem vertex_injective (r t digits:ℕ) : Function.Injective (vertex (r:=r) (t:=t) (digits:=digits)) := by\n  intro v w h\n  have hd:=congrArg (decode r t digits) h\n  rw [decode_vertex,decode_vertex] at hd\n  exact Option.some.inj hd\nend RiemannGaussian.SemiprimeD1VertexDescriptorDecode\n","RiemannGaussian.SemiprimeD1WireKernel":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Original power-of-two grid content for the D.4 Cauchy wire kernel\nThe original grid is indexed by j<N, translated by -L with N=2L. Its derivative\nproduct is acquired directly from integer differences, not a supplied inverse or\ncoefficient table. Polynomial and p-adic interpretations are specifications.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1WireKernel\nopen scoped BigOperators\n\n/-- Integer derivative product at the j-th point of the actual consecutive grid. -/\ndef derivativeProduct (N j : ℕ) : ℤ :=\n  ∏ q∈Finset.range N, if q=j then 1 else (j:ℤ)-(q:ℤ)\n\n/-- Legendre's recurrence uses an actual integer quotient, not a digit oracle. -/\ntheorem factorial_valuation_rec (n : ℕ) :\n    padicValNat 2 n.factorial=padicValNat 2 (n/2).factorial+n/2 := by\n  rw [← padicValNat_mul_div_factorial (p:=2) n,padicValNat_factorial_mul]\n\n/-- Complementary factorials on a complete dyadic grid have the same total\n2-content at EVERY point, including the two grid endpoints. -/\ntheorem complementary_factorial_content (k j : ℕ) (hj : j<2^k) :\n    padicValNat 2 j.factorial+padicValNat 2 (2^k-1-j).factorial=\n      padicValNat 2 (2^k-1).factorial := by\n  induction k generalizing j with\n  | zero =>\n    have hj0 : j=0 := by simpa using hj\n    subst j\n    simp\n  | succ k ih =>\n    have hp : 0<2^k := by positivity\n    have hn : 2^(k+1)=2*2^k := by rw [pow_succ];omega\n    have hdiv : (2^(k+1)-1-j)/2=2^k-1-j/2 := by rw [hn] at *;omega\n    have htop : (2^(k+1)-1)/2=2^k-1 := by rw [hn];omega\n    have hsmall : j/2<2^k := by rw [hn] at hj;omega\n    have hsum : j/2+(2^(k+1)-1-j)/2=2^k-1 := by rw [hn] at *;omega\n    have hi := ih (j/2) hsmall\n    have h1 := factorial_valuation_rec j\n    have h2 := factorial_valuation_rec (2^(k+1)-1-j)\n    have h3 := factorial_valuation_rec (2^(k+1)-1)\n    rw [hdiv] at h2\n    rw [htop] at h3\n    omega\n\n/-- Product at the final point is the acquired factorial, with no negative factors. -/\ntheorem derivativeProduct_last (N : ℕ) : derivativeProduct (N+1) N=(N.factorial:ℤ) := by\n  simp only [derivativeProduct,Finset.prod_range_succ,ite_true,mul_one]\n  have he : (∏ q∈Finset.range N, if q=N then (1:ℤ) else (N:ℤ)-(q:ℤ))=\n      ∏ q∈Finset.range N, ((N:ℤ)-(q:ℤ)) := by\n    apply Finset.prod_congr rfl\n    intro q hq\n    simp only [ne_of_lt (Finset.mem_range.mp hq),ite_false]\n  rw [he,Finset.prod_range_natCast_sub,← Nat.descFactorial_eq_prod_range,Nat.descFactorial_self]\n\n/-- Exact signed derivative of the original complete consecutive grid. -/\ntheorem derivativeProduct_formula (N j : ℕ) (hj : j<N) :\n    derivativeProduct N j=(-1:ℤ)^(N-1-j)*(j.factorial:ℤ)*((N-1-j).factorial:ℤ) := by\n  induction N generalizing j with\n  | zero => omega\n  | succ N ih =>\n    by_cases he : j=N\n    · subst j\n      rw [derivativeProduct_last]\n      simp\n    · have hjN : j<N := by omega\n      have hi := ih j hjN\n      have hd : N-j=(N-1-j)+1 := by omega\n      have hz : (j:ℤ)-(N:ℤ)=-((N-1-j:ℕ)+1:ℤ) := by omega\n      have heN : N≠j := Ne.symm he\n      simp only [derivativeProduct,Finset.prod_range_succ,heN,ite_false] at hi ⊢\n      rw [hi]\n      simp only [Nat.add_sub_cancel_right]\n      rw [hd,Nat.factorial_succ,Nat.cast_mul,Nat.cast_add,Nat.cast_one,pow_succ,hz]\n      ring\n\n/-- Absolute derivative content is exactly the two acquired factorials. -/\ntheorem derivativeProduct_natAbs (N j : ℕ) (hj : j<N) :\n    (derivativeProduct N j).natAbs=j.factorial*(N-1-j).factorial := by\n  rw [derivativeProduct_formula N j hj]\n  simp [Int.natAbs_mul,Int.natAbs_pow]\n\n/-- The original grid derivative has constant 2-adic content, without assuming\nintegrality or an odd-binomial/normalizer oracle. -/\ntheorem derivativeProduct_content (k j : ℕ) (hj : j<2^k) :\n    padicValInt 2 (derivativeProduct (2^k) j)=\n      padicValNat 2 (2^k-1).factorial := by\n  rw [padicValInt,derivativeProduct_natAbs _ _ hj,\n    padicValNat.mul (Nat.factorial_ne_zero j) (Nat.factorial_ne_zero _)]\n  exact complementary_factorial_content k j hj\n\nend RiemannGaussian.SemiprimeD1WireKernel\n","RiemannGaussian.SemiprimeD1WireKernelEntry":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WireKernelFactors\n\n/-! # Original-input integer-factor wire-kernel acquisition\nThe runtime record is an ordered list of integer linear factors, an explicit\npower of two and an actually computed odd denominator. No rational answer or\ncoefficient/inverse table is supplied. Polynomials below specify those data.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1WireKernelEntry\nopen scoped BigOperators\nopen Polynomial SemiprimeD1WireKernel SemiprimeD1WireKernelFactors\n\n/-- Original common derivative content, computed from the actual dyadic grid. -/\ndef content (k : ℕ) : ℕ := padicValNat 2 (2^k-1).factorial\n\n/-- Original common derivative denominator after removing exactly its two-content. -/\ndef oddDenominator (k center : ℕ) : ℤ :=\n  derivativeProduct (2^k) center/(2:ℤ)^content k\n\n/-- The acquired normalizer reconstructs the actual original denominator. -/\ntheorem denominator_reconstruct (k center : ℕ) (hc : center<2^k) :\n    oddDenominator k center*(2:ℤ)^content k=derivativeProduct (2^k) center := by\n  apply Int.ediv_mul_cancel\n  have hd := padicValInt_dvd (p:=2) (derivativeProduct (2^k) center)\n  rw [derivativeProduct_content k center hc] at hd\n  simpa only [content,Nat.cast_ofNat] using hd\n\n/-- The original-derived denominator is genuinely odd; no unit hypothesis is input. -/\ntheorem denominator_not_two_dvd (k center : ℕ) (hc : center<2^k) :\n    ¬(2:ℤ) ∣ oddDenominator k center := by\n  intro h\n  obtain ⟨u,hu⟩ := h\n  have hrec := denominator_reconstruct k center hc\n  have hd : (2:ℤ)^(content k+1) ∣ derivativeProduct (2^k) center := by\n    refine ⟨u,?_⟩\n    rw [← hrec,hu,pow_succ]\n    ring\n  have hv := (padicValInt_dvd_iff (p:=2) (content k+1) (derivativeProduct (2^k) center)).mp hd\n  rcases hv with hz|hv\n  · exact derivativeProduct_ne_zero (2^k) center hc hz\n  · rw [derivativeProduct_content k center hc] at hv\n    change content k+1≤content k at hv\n    omega\n\n/-- Oddness includes negative original grid normalizers. -/\ntheorem denominator_odd (k center : ℕ) (hc : center<2^k) : Odd (oddDenominator k center) := by\n  apply Int.not_even_iff_odd.mp\n  rw [even_iff_two_dvd]\n  exact denominator_not_two_dvd k center hc\n\n/-- No division by zero is hidden in the acquired odd normalizer. -/\ntheorem denominator_ne_zero (k center : ℕ) (hc : center<2^k) : oddDenominator k center≠0 := by\n  intro hz\n  apply denominator_not_two_dvd k center hc\n  rw [hz]\n  exact dvd_zero _\n\n/-- Actual ordered original grid indices except the one D.7 cancelled factor. -/\ndef indices (k d : ℕ) : List ℕ := (List.range (2^k)).filter (fun q => decide (q≠d))\n\n/-- The acquired list has the exact original omitted-factor set. -/\ntheorem indices_toFinset (k d : ℕ) : (indices k d).toFinset=(Finset.range (2^k)).erase d := by\n  ext q\n  simp [indices,and_comm]\n\n/-- No repeated grid factor is inserted by acquisition. -/\ntheorem indices_nodup (k d : ℕ) : (indices k d).Nodup :=\n  (List.nodup_range : (List.range (2^k)).Nodup).filter _\n\n/-- Original finite factor acquisition is at most the actual grid cardinality. -/\ntheorem indices_length (k d : ℕ) : (indices k d).length≤2^k := by\n  exact (List.length_filter_le _ _).trans (by simp)\n\n/-- Original-derived executable integer-factor entry data. -/\nstructure Entry where\n  /-- Exact ordered linear factors, not requested polynomial coefficients. -/\n  factors : List Linear\n  /-- Explicit power remaining after original denominator cancellation. -/\n  power : ℕ\n  /-- Actually acquired original odd denominator. -/\n  denominator : ℤ\n\n/-- Acquire the full entry directly from original grid parameters and cancelled index. -/\ndef acquire (k center j d : ℕ) : Entry :=\n  ⟨(indices k d).map (normalizedFactor k j),excess k j d,oddDenominator k center⟩\n\n/-- Integer polynomial interpretation of a physically unexpanded linear factor. -/\nnoncomputable def linearPolynomial (f : Linear) : ℤ[X] := C f.constant+C f.slope*X\n\n/-- Integer polynomial interpreted from acquired data, not a runtime oracle. -/\nnoncomputable def numerator (entry : Entry) : ℤ[X] :=\n  C ((2:ℤ)^entry.power)*(entry.factors.map linearPolynomial).prod\n\n/-- Original unnormalized affine numerator after T=t+2^k*z. -/\nnoncomputable def rawPolynomial (k j d : ℕ) : ℤ[X] :=\n  ∏ q∈(Finset.range (2^k)).erase d,\n    (C (difference j q)+C ((2:ℤ)^k)*X)\n\n/-- Every original affine factor is reconstructed from the acquired integer pair. -/\ntheorem linear_reconstruct (k j q : ℕ) (hj : j<2^k) (hq : q<2^k) :\n    C ((2:ℤ)^factorOrder k j q)*linearPolynomial (normalizedFactor k j q)=\n      C (difference j q)+C ((2:ℤ)^k)*X := by\n  have hc := normalized_constant k j q\n  have hs := normalized_slope k j q hj hq\n  rw [← hc,← hs]\n  simp only [linearPolynomial,C_mul]\n  ring\n\n/-- Actual omitted-factor numerator content and acquired integer factor product. -/\ntheorem rawPolynomial_content (k j d : ℕ) (hj : j<2^k) :\n    rawPolynomial k j d=\n      C ((2:ℤ)^(∑ q∈(Finset.range (2^k)).erase d,factorOrder k j q))*\n        ∏ q∈(Finset.range (2^k)).erase d,linearPolynomial (normalizedFactor k j q) := by\n  unfold rawPolynomial\n  have he : (∏ q∈(Finset.range (2^k)).erase d,\n      (C (difference j q)+C ((2:ℤ)^k)*X))=\n      ∏ q∈(Finset.range (2^k)).erase d,\n        C ((2:ℤ)^factorOrder k j q)*linearPolynomial (normalizedFactor k j q) := by\n    apply Finset.prod_congr rfl\n    intro q hq\n    exact (linear_reconstruct k j q hj (Finset.mem_range.mp (Finset.mem_erase.mp hq).2)).symm\n  rw [he,Finset.prod_mul_distrib,← map_prod C,Finset.prod_pow_eq_pow_sum]\n\n/-- The ordered acquired data has exactly the original indexed factor product. -/\ntheorem acquired_product (k center j d : ℕ) :\n    ((acquire k center j d).factors.map linearPolynomial).prod=\n      ∏ q∈(Finset.range (2^k)).erase d,linearPolynomial (normalizedFactor k j q) := by\n  simp only [acquire,List.map_map]\n  rw [← List.prod_toFinset _ (indices_nodup k d),indices_toFinset]\n  rfl\n\n/-- COMPLETE original denominator cancellation: all remaining coefficients are\nintegers after multiplying only by the acquired ODD denominator. -/\ntheorem cancellation (k center j d : ℕ) (hc : center<2^k) (hj : j<2^k) (hd : d<2^k) :\n    C (oddDenominator k center)*rawPolynomial k j d=\n      C (derivativeProduct (2^k) center)*numerator (acquire k center j d) := by\n  have hs : (∑ q∈(Finset.range (2^k)).erase d,factorOrder k j q)=content k+excess k j d := by\n    have hle := omitted_content_ge k j d hj hd\n    unfold excess content\n    omega\n  rw [rawPolynomial_content k j d hj,hs,pow_add,C_mul]\n  unfold numerator\n  rw [acquired_product,← denominator_reconstruct k center hc]\n  simp only [acquire,C_mul]\n  ring\n\nend RiemannGaussian.SemiprimeD1WireKernelEntry\n","RiemannGaussian.SemiprimeD1WordPacketArithmeticClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordPacketEntryBits\nimport RiemannGaussian.SemiprimeD1JetWordKernelBounds\nimport RiemannGaussian.SemiprimeD1PacketEntryValue\nimport RiemannGaussian.SemiprimeD1JetModeBitsBounds\n\n/-! # Retained physical arithmetic in actual packet row construction\nCanonical input shape is an original acquired-vector condition. All outputs\nand arithmetic prefixes derive their own current width; no intermediate Fits\nor entry-clock answer is a premise. Original word acquisition and every physical report are included; the native\nsmall-index/digit and whole-address lowering boundaries remain explicit.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 140000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordPacketArithmeticClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1JetWordPacketEntryBits SemiprimeD1PacketEntryInputs\nopen SemiprimeD1PacketEntryBits (borrow multiply)\n\n/-- Actual fixed-width multijet multiplication budget. -/\ndef mulClock (ctx : Context) : ℕ :=\n  SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank ctx.precision ctx.precision\n\n/-- Actual fixed-width multijet addition budget. -/\ndef addClock (ctx : Context) : ℕ := addBudget ctx ctx.precision\n\n/-- Actual literal unit acquisition budget. -/\ndef oneClock (ctx : Context) : ℕ := 9*ctx.precision+3*ctx.rank+8\n\n/-- Both actual producer reports are retained by packet multiplication. -/\ntheorem multiply_clock (ctx : Context) (left right : JetRun)\n    (hl : Good ctx left.words) (hr : Good ctx right.words) :\n    (multiply ctx left right).clock ≤ left.clock+right.clock+mulClock ctx+3 := by\n  have h := SemiprimeD1JetRingBounds.mul_clock ctx left.words right.words ctx.precision\n    hl.1.le hr.1.le hl.2 hr.2\n  exact Nat.add_le_add_right (Nat.add_le_add_left h (left.clock+right.clock)) 3\n\n/-- Actual packet multiplication always produces canonical target shape/width. -/\ntheorem multiply_good (ctx : Context) (left right : JetRun) : Good ctx (multiply ctx left right).words :=\n  mul_good ctx left.words right.words\n\n/-- Sign cost includes the actual modular minus-one producer and copied positive case. -/\ndef signClock (ctx : Context) : ℕ := (12*ctx.precision*(ctx.precision+3)+13*ctx.precision+3*ctx.rank+27)+\n  mulClock ctx+ctx.rank*(3*ctx.precision+4)+10\n\n/-- Both physical sign branches preserve the actual acquired input shape. -/\ntheorem signed_good (ctx : Context) (negative : Bool) (value : JetRun) (hv : Good ctx value.words) :\n    Good ctx (signed ctx negative value).words := by\n  cases negative with\n  | false => simpa only [signed,Bool.false_eq_true,ite_false,copyVector_value] using hv\n  | true => exact multiply_good ctx _ _\n\n/-- Every sign application pays its actual source report exactly as executed. -/\ntheorem signed_clock (ctx : Context) (negative : Bool) (value : JetRun) (hv : Good ctx value.words) :\n    (signed ctx negative value).clock ≤ value.clock+signClock ctx := by\n  have hi := SemiprimeD1JetWordSourceBits.constant_clock ctx ⟨true,[true]⟩\n  simp only [List.length_cons,List.length_nil] at hi\n  change (SemiprimeD1JetWordSourceBits.constant ctx ⟨true,[true]⟩).clock ≤\n    12*ctx.precision*(ctx.precision+3)+13*ctx.precision+3*ctx.rank+27 at hi\n  have hc := copyVector_clock_le value.words ctx.precision hv.2\n  rw [hv.1] at hc\n  have hm := multiply_clock ctx (SemiprimeD1JetWordSourceBits.constant ctx ⟨true,[true]⟩) value\n    (SemiprimeD1JetWordSourceBits.constant_good _ _) hv\n  cases negative with\n  | false =>\n    change value.clock+(copyVector value.words).2+3 ≤ _\n    unfold signClock\n    omega\n  | true =>\n    change (multiply ctx (SemiprimeD1JetWordSourceBits.constant ctx ⟨true,[true]⟩) value).clock ≤ _\n    unfold signClock\n    omega\n\n/-- Original finite-grid base-entry bound at actual target precision. -/\ndef baseClock (ctx : Context) (a : ℕ) : ℕ :=\n  SemiprimeD1JetWordKernelBounds.budget ctx ctx.precision a+ctx.rank+1\n\n/-- Every actual real-row column contribution has intrinsic target shape. -/\ntheorem baseTerm_good (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) :\n    Good ctx (baseTerm ctx z a t row column).words := by\n  dsimp only [baseTerm]\n  split\n  · exact SemiprimeD1JetWordModeBounds.base_good ctx _ a t row.slot column.slot\n  · exact zero_good ctx\n\n/-- Borrowed fresh input is actually canonical; no repeated producer cost is\ninvented for borrowing, while the outer table retains the producer separately. -/\ntheorem baseTerm_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) :\n    (baseTerm ctx z a t row column).clock ≤ baseClock ctx a := by\n  have h := SemiprimeD1JetWordKernelBounds.acquireOriginal_clock ctx (borrow z) a t row.slot column.slot\n    ctx.precision le_rfl hz.1.le hz.2\n  dsimp only [baseTerm]\n  split\n  · change (SemiprimeD1JetWordKernelBits.acquireOriginal ctx (borrow z) a t row.slot column.slot).clock ≤ _\n    dsimp only [borrow] at h\n    simp only [Nat.zero_add] at h\n    exact h.trans (by\n      unfold baseClock\n      omega)\n  · change ctx.rank+1 ≤ _\n    unfold baseClock\n    omega\n\n/-- Full real-row constant acquisition, including false-bit one-minus-base. -/\ndef rowBaseClock (ctx : Context) (a columns : ℕ) : ℕ :=\n  columns*(baseClock ctx a+addClock ctx+3)+ctx.rank+1+\n    oneClock ctx+signClock ctx+addClock ctx+5\n\n/-- Row constants derive all intermediate shape/widths. -/\ntheorem rowBase_good (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) :\n    Good ctx (rowBase ctx z a t row columns).words := by\n  dsimp only [rowBase]\n  split\n  · exact sumRuns_good ctx _\n  · exact add_good ctx _ _\n\n/-- Every actual column callback, sum prefix, literal unit and physical sign is retained. -/\ntheorem rowBase_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) :\n    (rowBase ctx z a t row columns).clock ≤ rowBaseClock ctx a columns.length := by\n  let base := sumRuns ctx (columns.map (baseTerm ctx z a t row))\n  have hbase := sumRuns_clock ctx (columns.map (baseTerm ctx z a t row)) (by\n    intro x hx\n    obtain ⟨column,_,rfl⟩ := List.mem_map.mp hx\n    exact baseTerm_good ctx z a t row column)\n  have hcallbacks : ((columns.map (baseTerm ctx z a t row)).map (fun x => x.clock)).sum ≤\n      columns.length*baseClock ctx a := by\n    clear hbase base\n    induction columns with\n    | nil => simp\n    | cons c cs ih =>\n      have hh := baseTerm_clock ctx z hz a t row c\n      simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n  simp only [List.length_map] at hbase\n  have hb : base.clock ≤ columns.length*(baseClock ctx a+addClock ctx+3)+ctx.rank+1 := by\n    have hsum := Nat.add_le_add_right (Nat.add_le_add_right hcallbacks\n      (columns.length*(addBudget ctx ctx.precision+3))) (ctx.rank+1)\n    exact hbase.trans (by dsimp only [addClock];nlinarith)\n  have hu := SemiprimeD1JetPolynomialBitsBounds.one_clock ctx\n  have hs := signed_clock ctx true base (sumRuns_good ctx _)\n  have ha := SemiprimeD1JetRingBounds.add_clock ctx (one ctx).words (signed ctx true base).words\n    ctx.precision (one_good ctx).1.le (signed_good ctx true base (sumRuns_good ctx _)).1.le\n      (one_good ctx).2 (signed_good ctx true base (sumRuns_good ctx _)).2\n  have hu' : (one ctx).clock ≤ oneClock ctx := hu\n  have ha' : (SemiprimeD1JetRingBits.add ctx (one ctx).words (signed ctx true base).words).clock ≤ addClock ctx := ha\n  dsimp only [rowBase]\n  split\n  · change base.clock ≤ _\n    exact hb.trans (by unfold rowBaseClock;omega)\n  · change (one ctx).clock+(signed ctx true base).clock+\n      (SemiprimeD1JetRingBits.add ctx (one ctx).words (signed ctx true base).words).clock+5 ≤ _\n    calc\n      _ ≤ oneClock ctx+(base.clock+signClock ctx)+addClock ctx+5 :=\n        Nat.add_le_add (Nat.add_le_add (Nat.add_le_add hu' hs) ha') (le_refl 5)\n      _ ≤ oneClock ctx+((columns.length*(baseClock ctx a+addClock ctx+3)+ctx.rank+1)+signClock ctx)+addClock ctx+5 := by\n        exact Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add_left\n          (Nat.add_le_add_right hb (signClock ctx)) (oneClock ctx)) (addClock ctx)) 5\n      _ = _ := by unfold rowBaseClock;ring\n\nend RiemannGaussian.SemiprimeD1WordPacketArithmeticClock\n","RiemannGaussian.SemiprimeD1WordTapePhasePolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapeOriginalPhaseBudget\nimport RiemannGaussian.SemiprimeD1ChildWordOriginalPolynomial\nimport RiemannGaussian.SemiprimeD1PhysicalPhasePolynomial\n\n/-! # Actual word-only phase costs in original scalar resources\nEvery repeated source/header/menu producer is retained and paid. The squared\nmenu factor is bounded by the literal actual phase-child inventory.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1WordTapePhasePolynomial\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkRecursion SemiprimeD1RecursiveCallTree\nopen SemiprimeD1WordTapePhaseBudget SemiprimeD1WordTapeOriginalPhaseBudget\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- Uniform scalar factor before the actual squared branching and eager scales. -/\ndef phaseFactor (S a : ℕ) : ℕ :=\n  SemiprimeD1PhysicalPhasePolynomial.phaseFactor S (SemiprimeD1ChildWordOriginalPolynomial.factor S a)\n\n/-- All original phase coefficients have fixed monomial witnesses. -/\ntheorem phaseFactor_monomial : SemiprimeD1ChildPrefactorPolynomial.Bound phaseFactor := by\n  exact SemiprimeD1PhysicalPhasePolynomial.phaseFactor_monomial\n    SemiprimeD1ChildWordOriginalPolynomial.factor_monomial\n\n\n/-- Each actual mode creates all64 group children, counted without evaluating\nor changing any child constructor. -/\ntheorem groups_length {A B : Type} (xs : List A) (f : A → Fin 64 → B) :\n    (xs.flatMap (fun x => (List.finRange 64).map (f x))).length=64*xs.length := by\n  simp only [List.length_flatMap,List.length_map,List.length_finRange,List.map_const',List.sum_replicate,\n    nsmul_eq_mul,Nat.cast_id]\n  omega\n\n/-- Pure scalar control arithmetic is isolated before original records are substituted. -/\ntheorem control_bound (M a u i q L S I : ℕ) (hM : M ≤ S) (ha : a ≤ S)\n    (hu : u ≤ S) (hi : i ≤ S) (hq : q ≤ I) :\n    10*(M+a+u+i+q+L+1) ≤ (10*(4*S+I+2))*(L+1) := by\n  have hbase : M+a+u+i+q+L+1 ≤ (4*S+I+2)*(L+1) := by\n    nlinarith only [hM,ha,hu,hi,hq,Nat.zero_le ((4*S+I+1)*L)]\n  simpa only [Nat.mul_assoc] using Nat.mul_le_mul_left 10 hbase\n\n/-- The actual original word-only phase budget is polynomial per squared actual\nchild count. No clock, fit, shape or histogram answer is a premise. -/\ntheorem phase_budget_bound (parent : Call) (lam a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (S : ℕ)\n    (hw : WellFormed parent.net) (hg : Good parent.ctx parent.net)\n    (hlam : 1000 ≤ lam) (haSmall : a ≤ 4*(lam/131072))\n    (hMlog : edgeCount parent.net ≤ 2^lam)\n    (hd : DegreeBound parent.net (2^((9*lam+9)/10)))\n    (hsmall : 2*(64^(2*a))^2*(2^((9*lam+9)/10)) ≤ edgeCount parent.net)\n    (hsize : 64^(2*a)*2^a ≤ edgeCount parent.net)\n    (hu : 0 < u) (huM : u ≤ edgeCount parent.net)\n    (hprecision : ∀i : Fin a,i.val < u → parent.ctx.precision*u ≤ edgeCount parent.net*2^(a-i.val))\n    (hreserve : ∀i : Fin a,i.val < u → (a+1)*u ≤ 2^(a-i.val))\n    (hn : parent.net.leftCount ≤ S) (hF : parent.net.rows.length ≤ S)\n    (hM : edgeCount parent.net ≤ S) (ha : a ≤ S)\n    (hp : parent.ctx.precision ≤ S) (hrank : parent.ctx.rank ≤ S)\n    (haxes : parent.ctx.axes.length ≤ S)\n    (hN : 2^(a+1) ≤ S) (hL : 64^a ≤ S) (hD : 2^((9*lam+9)/10) ≤ S)\n    (hInventory : SemiprimeD1NetworkStateResources.inventory parent.net ≤ S) :\n    phaseBudget parent a u t ≤ phaseFactor S a*((phaseChildren parent a u t).length+1)^2*\n      2^(3*(2^((9*lam+9)/10))) := by\n  have hstart:=phaseBudget_le_original parent lam a u t hw hg hlam haSmall hMlog hd hsmall hsize\n    hu huM hprecision hreserve\n  apply hstart.trans\n  unfold originalPhaseBudget\n  dsimp only\n  split\n  · rename_i hi\n    let i : Fin a:=⟨_,hi.1⟩\n    let source:=SemiprimeD1ChildOriginalClock.source parent.net parent.ctx a u i\n    let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n    let L:=source.modes.values.length\n    let C:=SemiprimeD1ChildWordOriginalPolynomial.factor S a\n    let F:=SemiprimeD1PhysicalSourcePolynomial.sourceFactor\n      (SemiprimeD1PhysicalNetworkSourceBudget.inflation S)\n    have hc:=SemiprimeD1ChildWordOriginalPolynomial.child_budget_bound parent lam a u i S\n      hw hlam haSmall hMlog hd hsmall hsize hu huM (hprecision i hi.2.1) (hreserve i hi.2.1)\n      hn hF hM ha hp hrank haxes hN hL hD hInventory\n    change childBudget parent lam a u i ≤ C*(L+1)*2^(3*(2^((9*lam+9)/10))) at hc\n    have hs:=SemiprimeD1PhysicalNetworkSourceBudget.acquire_work parent.net hw _ a u i.val\n      parent.ctx.precision S hd hsmall hsize hu huM i.isLt.le hn hF hM ha hp hN hL\n    change source.work ≤ F*(L+1) at hs\n    have hprec:=SemiprimeD1PhysicalChildPolynomial.precision_bound parent a u i S hu huM hM ha hp hN\n    have hq:=SemiprimeD1PhysicalChildPolynomial.fresh_axis_bound parent a u i S huM hM\n    have hz : 9*source.precision+3*(q*parent.ctx.rank)+10 ≤ SemiprimeD1PhysicalChildPolynomial.freshBudget S := by\n      unfold SemiprimeD1PhysicalChildPolynomial.freshBudget\n      gcongr\n    have he : modeOverhead (current parent a u i) ≤ SemiprimeD1PhysicalPhasePolynomial.modeEnvelope S :=\n      SemiprimeD1PhysicalPhasePolynomial.modeOverhead_bound parent a u i S hu huM hM ha hp hrank haxes hN\n    have hv : (current parent a u i).rank ≤ SemiprimeD1PhysicalPhasePolynomial.vectorCap S :=\n      (SemiprimeD1PhysicalPhasePolynomial.current_fields parent a u i S hu huM hM ha hp hrank haxes hN).1\n    have hb:=SemiprimeD1PhysicalPhasePolynomial.block_bound parent a u i S hu huM hM ha hp hrank haxes hN\n    dsimp only at hb\n    have hG : (SemiprimeD1RecoveryWeightRun.geometry a t.val).work+\n        (SemiprimeD1RecoveryScalarRun.orderFuel (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n          (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs).work ≤ 8*S+11 := by\n      have ho:=SemiprimeD1RecoveryScalarRun.orderFuel_work\n        (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n        (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs\n      rw [SemiprimeD1RecoveryMetadataBudget.geometry_work]\n      simp only [SemiprimeD1RecoveryWeightRun.geometry_size] at ho ⊢\n      have hNs : SemiprimeD1WireKernelOriginal.size a ≤ S := hN\n      omega\n    have hcontrol : 10*(edgeCount parent.net+a+u+i.val+q+L+1) ≤\n        SemiprimeD1PhysicalPhasePolynomial.controlEnvelope S*(L+1) := by\n      have hui : u ≤ S := huM.trans hM\n      have hii : i.val ≤ S := i.isLt.le.trans ha\n      simpa only [SemiprimeD1PhysicalPhasePolynomial.controlEnvelope] using\n        control_bound (edgeCount parent.net) a u i.val q L S\n          (SemiprimeD1PhysicalChildPolynomial.inflation S) hM ha hui hii hq\n    have hnum:=SemiprimeD1PhasePolynomialArithmetic.phase_bound L (3*(2^((9*lam+9)/10)))\n      (8*S+11) F (SemiprimeD1PhysicalChildPolynomial.freshBudget S) C\n      (SemiprimeD1PhysicalPhasePolynomial.modeEnvelope S) (SemiprimeD1PhysicalPhasePolynomial.vectorCap S)\n      (SemiprimeD1PhysicalPhasePolynomial.blockEnvelope S) (SemiprimeD1PhysicalPhasePolynomial.controlEnvelope S)\n      _ _ _ _ _ _ _ _ _ hG hs hz hc he hv hb hcontrol\n    have hcoef:=SemiprimeD1PhysicalPhasePolynomial.coefficient_le S C\n    have hnum':=hnum.trans (Nat.mul_le_mul_right _ (Nat.mul_le_mul_right ((L+1)^2) hcoef))\n    have hlength : (phaseChildren parent a u t).length=64*L := by\n      unfold phaseChildren\n      dsimp only\n      rw [dite_eq_left hi]\n      exact groups_length _ _\n    apply hnum'.trans\n    change phaseFactor S a*(L+1)^2*2^(3*(2^((9*lam+9)/10))) ≤ _\n    apply Nat.mul_le_mul_right _\n    apply Nat.mul_le_mul_left _\n    apply Nat.pow_le_pow_left\n    omega\n  · have ho:=SemiprimeD1RecoveryScalarRun.orderFuel_work\n      (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n      (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs\n    have hv:=SemiprimeD1PhysicalPhasePolynomial.order_value_le\n      (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n      (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs\n    simp only [SemiprimeD1RecoveryWeightRun.geometry_size] at ho hv ⊢\n    rw [SemiprimeD1RecoveryMetadataBudget.geometry_work]\n    have hNs : SemiprimeD1WireKernelOriginal.size a ≤ S := hN\n    have hui : u ≤ S := huM.trans hM\n    have hg : 3*a+8+\n        (SemiprimeD1RecoveryScalarRun.orderFuel (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n          (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs).work+a+u+\n        (SemiprimeD1RecoveryScalarRun.orderFuel (SemiprimeD1RecoveryWeightRun.geometry a t.val).size\n          (SemiprimeD1RecoveryWeightRun.geometry a t.val).point.natAbs).value+8 ≤ 11*S+19 := by\n      simp only [SemiprimeD1RecoveryWeightRun.geometry_size]\n      omega\n    simp only [SemiprimeD1RecoveryWeightRun.geometry_size] at hg\n    have hf : 11*S+19 ≤ phaseFactor S a := by\n      unfold phaseFactor SemiprimeD1PhysicalPhasePolynomial.phaseFactor\n        SemiprimeD1PhysicalPhasePolynomial.arithmeticBase SemiprimeD1PhysicalPhasePolynomial.arithmeticOnly\n      omega\n    have h1 : 1 ≤ ((phaseChildren parent a u t).length+1)^2*2^(3*(2^((9*lam+9)/10))) :=\n      one_le_mul_of_one_le_of_one_le (Nat.one_le_pow _ _ (by omega)) Nat.one_le_two_pow\n    apply (hg.trans hf).trans\n    simpa only [Nat.mul_assoc,Nat.mul_one] using Nat.mul_le_mul_left (phaseFactor S a) h1\n\nend RiemannGaussian.SemiprimeD1WordTapePhasePolynomial\n","RiemannGaussian.SemiprimeD1WordTapePublicRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapePublicReport\nimport RiemannGaussian.SemiprimeD1OriginalInventoryScalar\n\n/-! # Quantitative public report composition for the actual word/tape caller\nEvery queried prefix retains its own root acquisition and recursion. Fixed\nrecovery work and the actual number of queries are paid at original input\nlength. The prefix-rate premise below is an internal theorem to discharge\nfrom the concrete counter, never an argument to the factoring algorithm.\nThis concerns retained reports, not a complete primitive-machine clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordTapePublicRate\nopen Filter SemiprimeD1OriginalCallRate SemiprimeD1OriginalEnvelopeRate\nopen SemiprimeD1OriginalStateResources SemiprimeD1PackingReady\nopen SemiprimeD1RootStateResources SemiprimeMacroParameters SemiprimePublicAcquiredExecution\nopen SemiprimeBitArithmetic\nopen scoped Topology\nnoncomputable section\nattribute [local irreducible] SemiprimeD1WordTapeBinaryFactorExecution.run\n  SemiprimeD1WordTapePublicCounter.prefixRun SemiprimeD1BinaryFactorExecution.run\n\n/-- Scalar-resource polynomial, with the original table/leaf factor retained. -/\ntheorem polynomial_le_local (A d n s : ℕ) (hn:n ≤ scalar s) :\n    A*(n+1)^d ≤ localEnvelope A d s := by\n  have hP:=Nat.pow_le_pow_left (Nat.add_le_add_right hn 1) d\n  have hE:1 ≤ 2^(A*degreeCap s+SemiprimeD1Schedule.leafSize s (logarithm s)):=Nat.one_le_two_pow\n  unfold localEnvelope\n  calc\n    _  ≤  A*(scalar s+1)^d := Nat.mul_le_mul_left A hP\n    _  ≤  _ := by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (A*(scalar s+1)^d) hE\n\n/-- Fixed original-input exponent constant for a concrete local envelope. -/\ndef localConstant (A d : ℕ) : ℕ := 1048576*(3*A+3*d+2)\n\n/-- Actual local envelope at the requested original-length scale. -/\ntheorem original_local_rate (A d ell : ℕ)\n    (hmain:1 ≤ mainScale (SemiprimeD1PublicPackingReady.scale ell))\n    (haux:((degreeCap (SemiprimeD1PublicPackingReady.scale ell)+\n      (logarithm (SemiprimeD1PublicPackingReady.scale ell)+1)^3:ℕ):ℝ) ≤\n        2*mainScale (SemiprimeD1PublicPackingReady.scale ell))\n    (hleaf:(SemiprimeD1Schedule.leafSize (SemiprimeD1PublicPackingReady.scale ell)\n      (logarithm (SemiprimeD1PublicPackingReady.scale ell)):ℝ) ≤\n        mainScale (SemiprimeD1PublicPackingReady.scale ell)+1) :\n    (localEnvelope A d (SemiprimeD1PublicPackingReady.scale ell):ℝ) ≤\n      (2:ℝ)^((localConstant A d:ℝ)*inputScale ell) := by\n  apply (localEnvelope_rate A d _ haux hleaf hmain).trans\n  apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1 ≤ (2:ℝ))\n  have hs:=mainScale_public ell\n  unfold localConstant\n  push_cast\n  nlinarith [show (0:ℝ) ≤ 3*(A:ℝ)+3*(d:ℝ)+2 by positivity]\n\n/-- A real prefix budget can be used in the actual natural report sum, with a\nceiling appearing in the proof only. The executed program receives no budget. -/\ntheorem work_real (input : List Bool) (hc:SemiprimeSourceCompactBits.Compact input)\n    (hN:0<bitValue input) (R : ℝ) (hR:0 ≤ R)\n    (hprefix:∀fixed:List (Fin (wireCount (bitValue input))×Bool),fixed.length ≤ wireCount (bitValue input)→\n      ((SemiprimeD1WordTapePublicCounter.prefixRun (bitValue input) hN fixed).clock:ℝ) ≤ R) :\n    (SemiprimeD1WordTapePublicReport.work input:ℝ) ≤\n      (wireCount (bitValue input)+1:ℕ)*(R+1)+\n        SemiprimeD1PublicRecoveryBudget.localBudget (wireCount (bitValue input)) := by\n  have hnat:∀fixed:List (Fin (wireCount (bitValue input))×Bool),fixed.length ≤ wireCount (bitValue input)→\n      (SemiprimeD1WordTapePublicCounter.prefixRun (bitValue input) hN fixed).clock ≤ ⌈R⌉₊:=by\n    intro fixed hf\n    exact_mod_cast (hprefix fixed hf).trans (Nat.le_ceil R)\n  have hwork:=SemiprimeD1WordTapePublicReport.work_le input hc hN ⌈R⌉₊ hnat\n  have hcast:(SemiprimeD1WordTapePublicReport.work input:ℝ) ≤\n      (wireCount (bitValue input)+1:ℕ)*(⌈R⌉₊:ℝ)+\n        SemiprimeD1PublicRecoveryBudget.localBudget (wireCount (bitValue input)):=by exact_mod_cast hwork\n  apply hcast.trans\n  have hceil: (⌈R⌉₊:ℝ) ≤ R+1:=(Nat.ceil_lt_add_one hR).le\n  gcongr\n\n/-- Sum of two nonnegative-rate powers costs one further scale unit. -/\ntheorem add_rate (A D : ℕ) (B : ℝ) (hB:1 ≤ B) :\n    (2:ℝ)^((A:ℝ)*B)+(2:ℝ)^((D:ℝ)*B) ≤ (2:ℝ)^(((A+D+1:ℕ):ℝ)*B) := by\n  have hA:(1:ℝ) ≤ (2:ℝ)^((A:ℝ)*B):=Real.one_le_rpow (by norm_num) (by positivity)\n  have hD:(1:ℝ) ≤ (2:ℝ)^((D:ℝ)*B):=Real.one_le_rpow (by norm_num) (by positivity)\n  have hm1:=mul_le_mul_of_nonneg_left hD (show 0≤(2:ℝ)^((A:ℝ)*B) by positivity)\n  have hm2:=mul_le_mul_of_nonneg_right hA (show 0≤(2:ℝ)^((D:ℝ)*B) by positivity)\n  calc\n    _  ≤  2*((2:ℝ)^((A:ℝ)*B)*(2:ℝ)^((D:ℝ)*B)) := by nlinarith\n    _ = (2:ℝ)^((A:ℝ)*B+(D:ℝ)*B+1) := by\n      rw [Real.rpow_add (by norm_num:0<(2:ℝ)),Real.rpow_one,\n        Real.rpow_add (by norm_num:0<(2:ℝ))]\n      ring\n    _  ≤  _ := by apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1 ≤ (2:ℝ));push_cast;nlinarith\n\n/-- Internal whole-public transfer from an actual uniform prefix-rate theorem.\nAll prefix acquisitions and local physical recovery remain on the left. -/\ntheorem eventually_from_prefix (C : ℕ)\n    (hprefix:∀ᶠ ell:ℕ in atTop,∀(N:ℕ)(hN:0<N),bitLength N=ell→\n      ∀fixed:List (Fin (wireCount N)×Bool),fixed.length ≤ wireCount N→\n        ((SemiprimeD1WordTapePublicCounter.prefixRun N hN fixed).clock:ℝ) ≤\n          (2:ℝ)^((C:ℝ)*inputScale ell)) :\n    ∃D:ℕ,∀ᶠ ell:ℕ in atTop,∀input:List Bool,SemiprimeSourceCompactBits.Compact input→\n      ∀_hN:0<bitValue input,bitLength (bitValue input)=ell→\n        (SemiprimeD1WordTapePublicReport.work input:ℝ) ≤ (2:ℝ)^((D:ℝ)*inputScale ell) := by\n  obtain ⟨A,d,hlocal⟩:=SemiprimeD1PublicRecoveryBudget.exists_original_local_work\n  refine ⟨localConstant 1 1+C+1+localConstant A d+1,?_⟩\n  have ht:Tendsto logarithm atTop atTop:=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  filter_upwards [hprefix,scale_tendsto.eventually SemiprimeD1AuxiliaryRate.eventually_auxiliary_rate,\n    scale_tendsto.eventually eventually_mainScale_ge_one,\n    (ht.comp scale_tendsto).eventually (eventually_ge_atTop (1000:ℕ)),\n    eventually_ge_atTop (2:ℕ)] with ell hp haux hmain hl hell\n  intro input hc hN hEll\n  let N:=bitValue input\n  let s:=SemiprimeD1PublicPackingReady.scale ell\n  let B:=inputScale ell\n  have hB:1 ≤ B:=inputScale_ge_one ell hell\n  change 1000 ≤ logarithm s at hl\n  have hbase:=SemiprimeD1OriginalScalarResources.base_caps s hl\n  have haux':((degreeCap s+(logarithm s+1)^3:ℕ):ℝ) ≤ 2*mainScale s:=by\n    simpa only [mainScale,mul_div_assoc] using haux\n  have hleaf:(SemiprimeD1Schedule.leafSize s (logarithm s):ℝ) ≤ mainScale s+1:=by\n    simpa only [mainScale] using SemiprimeD1LeafRate.leafSize_real s (logarithm s) (by omega)\n  have he:ell ≤ s:=by dsimp only [s];unfold SemiprimeD1PublicPackingReady.scale;norm_num;omega\n  have hn:wireCount N ≤ s:=by\n    have h:=root_edges_le_scale N hN []\n    rw [root_edges,hEll] at h\n    change 2*wireCount N ≤ s at h\n    omega\n  have hw0:wireCount N+1 ≤ localEnvelope 1 1 s:=by\n    simpa only [Nat.one_mul,pow_one] using polynomial_le_local 1 1 (wireCount N) s (hn.trans hbase.1)\n  have hw:(wireCount N+1:ℕ) ≤ (2:ℝ)^((localConstant 1 1:ℝ)*B):=\n    (show (wireCount N+1:ℕ) ≤ (localEnvelope 1 1 s:ℝ) by exact_mod_cast hw0).trans\n      (original_local_rate 1 1 ell hmain haux' hleaf)\n  have hrec:((SemiprimeD1WordTapeBinaryFactorExecution.run input).arithmeticClock+\n      (SemiprimeD1WordTapeBinaryFactorExecution.run input).metadataWork:ℕ) ≤\n        (2:ℝ)^((localConstant A d:ℝ)*B):=by\n    have h:=hlocal input hc hN\n    rw [←SemiprimeD1WordTapePublicReport.run_local_eq input,hEll] at h\n    apply (show ((SemiprimeD1WordTapeBinaryFactorExecution.run input).arithmeticClock+\n      (SemiprimeD1WordTapeBinaryFactorExecution.run input).metadataWork:ℕ) ≤\n        (localEnvelope A d s:ℝ) by exact_mod_cast h.trans (polynomial_le_local A d ell s (he.trans hbase.1))).trans\n    exact original_local_rate A d ell hmain haux' hleaf\n  let R:ℝ:=(2:ℝ)^((C:ℝ)*B)\n  have hR:1 ≤ R:=Real.one_le_rpow (by norm_num) (by positivity)\n  have hpNat:∀fixed:List (Fin (wireCount N)×Bool),fixed.length ≤ wireCount N→\n      (SemiprimeD1WordTapePublicCounter.prefixRun N hN fixed).clock ≤ ⌈R⌉₊:=by\n    intro fixed hf\n    exact_mod_cast (hp N hN hEll fixed hf).trans (Nat.le_ceil R)\n  have hq:=SemiprimeD1WordTapePublicReport.run_queryWork input hN ⌈R⌉₊ hpNat\n  have hceil:(⌈R⌉₊:ℝ) ≤ (2:ℝ)^(((C+1:ℕ):ℝ)*B):=by\n    apply (Nat.ceil_lt_add_one (by positivity:0 ≤ R)).le.trans\n    calc\n      R+1  ≤  R*2 := by linarith\n      _ = (2:ℝ)^((C:ℝ)*B+1) := by dsimp only [R];rw [Real.rpow_add (by norm_num:0<(2:ℝ)),Real.rpow_one]\n      _  ≤  _ := by\n        apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1 ≤ (2:ℝ))\n        push_cast\n        nlinarith only [hB]\n  have hqR:((SemiprimeD1WordTapeBinaryFactorExecution.run input).queryWork:ℝ) ≤\n      (2:ℝ)^(((localConstant 1 1+C+1:ℕ):ℝ)*B):=by\n    have hq':((SemiprimeD1WordTapeBinaryFactorExecution.run input).queryWork:ℝ) ≤\n        (wireCount N+1:ℕ)*(⌈R⌉₊:ℝ):=by exact_mod_cast hq\n    apply hq'.trans\n    apply (mul_le_mul hw hceil (by positivity) (by positivity)).trans_eq\n    rw [←Real.rpow_add (by norm_num:0<(2:ℝ))]\n    congr 1\n    push_cast\n    ring\n  have hsum:=add_rate (localConstant 1 1+C+1) (localConstant A d) B hB\n  have hwork:(SemiprimeD1WordTapePublicReport.work input:ℝ) ≤\n      (2:ℝ)^(((localConstant 1 1+C+1:ℕ):ℝ)*B)+(2:ℝ)^((localConstant A d:ℝ)*B):=by\n    unfold SemiprimeD1WordTapePublicReport.work\n    dsimp only\n    push_cast at hqR hrec ⊢\n    linarith only [hqR,hrec]\n  exact hwork.trans hsum\n\nend\nend RiemannGaussian.SemiprimeD1WordTapePublicRate\n","RiemannGaussian.SemiprimeFermatQuotientCatalog":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib.NumberTheory.Multiplicity\nimport Mathlib.FieldTheory.Finite.Basic\nimport Mathlib.Tactic\n\n/-!\n# Public residue coverage for a small Fermat-quotient factor\n\nThe catalog depends only on `N,m`. A factor with Fermat quotient zero modulo\n`m` has a Teichmuller residue modulo `m²`; reciprocating this public list also\ncovers the smaller factor when the other factor has that property. These are\narithmetic coverage and proper-leaf theorems, not a polynomial-evaluation bit\nbackend or a complete sixth-rate factoring theorem.\n-/\n\nnamespace RiemannGaussian.SemiprimeFermatQuotientCatalog\n\n/-- The publicly testable property on a supplied candidate integer. -/\ndef FermatQuotientZero (m p : ℕ) : Prop := p ^ (m - 1) ≡ 1 [MOD m ^ 2]\n\n/-- Raising congruent integers to the modulus lifts congruence by one power. -/\ntheorem pow_modulus_lift {m : ℕ} {x y : ℤ} (h : x ≡ y [ZMOD m]) :\n    x ^ m ≡ y ^ m [ZMOD m ^ 2] := by\n  have hd : (m : ℤ) ∣ y - x := h.dvd\n  have hs := dvd_geom_sum₂_self hd\n  have hh := mul_dvd_mul hs hd\n  rw [geom_sum₂_mul] at hh\n  exact Int.modEq_of_dvd (by simpa only [Nat.cast_pow, pow_two] using hh)\n\n/-- A zero Fermat quotient fixes the integer under the modulus power. -/\ntheorem pow_eq_self_mod_square {m p : ℕ} (hm : 0 < m)\n    (hp : FermatQuotientZero m p) : p ^ m ≡ p [MOD m ^ 2] := by\n  have h := hp.mul (Nat.ModEq.refl p)\n  have he : m - 1 + 1 = m := Nat.sub_add_cancel hm\n  simpa only [← pow_succ, he, one_mul] using h\n\n/-- The Teichmuller lift is the explicit public power of the low residue. -/\ntheorem teichmuller_residue {m p : ℕ} (hm : 0 < m)\n    (hp : FermatQuotientZero m p) : p ≡ (p % m) ^ m [MOD m ^ 2] := by\n  have hbase : (p : ℤ) ≡ (p % m : ℕ) [ZMOD m] := by\n    rw [Int.natCast_modEq_iff]\n    exact (Nat.mod_modEq p m).symm\n  have hlift := pow_modulus_lift hbase\n  have hnat : p ^ m ≡ (p % m) ^ m [MOD m ^ 2] := by\n    exact_mod_cast hlift\n  exact (pow_eq_self_mod_square hm hp).symm.trans hnat\n\n/-- At most `m-1` public Teichmuller candidates, with duplicates discarded. -/\ndef teichmullerResidues (m : ℕ) : Finset ℕ :=\n  ((Finset.range m).filter (fun j => j ≠ 0)).image (fun j => j ^ m % (m ^ 2))\n\n/-- Reciprocal completion is computed in the public ring modulo `m²`. -/\ndef reciprocalResidue (N m s : ℕ) : ℕ :=\n  ((N : ZMod (m ^ 2)) * (s : ZMod (m ^ 2))⁻¹).val\n\n/-- This complete residue catalog depends only on the supplied `N,m`. -/\ndef factorResidues (N m : ℕ) : Finset ℕ :=\n  teichmullerResidues m ∪ (teichmullerResidues m).image (reciprocalResidue N m)\n\n/-- The promised factor contributes its own low-square residue to the public list. -/\ntheorem residue_mem_teichmuller {m p : ℕ} (hm : 1 < m)\n    (hcop : p.Coprime m) (hp : FermatQuotientZero m p) :\n    p % (m ^ 2) ∈ teichmullerResidues m := by\n  have hj : p % m ≠ 0 := by\n    intro hz\n    have hg : Nat.gcd (p % m) m = 1 := by\n      rw [← Nat.gcd_rec]\n      exact hcop.symm\n    simp only [hz, Nat.gcd_zero_left] at hg\n    omega\n  apply Finset.mem_image.mpr\n  refine ⟨p % m, Finset.mem_filter.mpr ⟨Finset.mem_range.mpr (Nat.mod_lt p (by omega)), hj⟩, ?_⟩\n  exact (teichmuller_residue (by omega) hp).symm\n\n/-- A public reciprocal residue recovers the complementary factor residue. -/\ntheorem reciprocal_complement {m p q : ℕ} (hm : 0 < m) (hq : q.Coprime m) :\n    reciprocalResidue (p * q) m (q % (m ^ 2)) = p % (m ^ 2) := by\n  have : NeZero (m ^ 2) := ⟨pow_ne_zero 2 hm.ne'⟩\n  have hu : IsUnit (q : ZMod (m ^ 2)) :=\n    (ZMod.isUnit_iff_coprime q (m ^ 2)).mpr (hq.pow_right 2)\n  unfold reciprocalResidue\n  have hc : ((q % (m ^ 2) : ℕ) : ZMod (m ^ 2)) = (q : ZMod (m ^ 2)) := by simp\n  rw [hc, Nat.cast_mul, mul_assoc, ZMod.mul_inv_of_unit _ hu, mul_one,\n    ZMod.val_natCast]\n\n/-- Either factor's zero Fermat quotient covers the first factor, without advice\nin the catalog's construction. -/\ntheorem either_factor_residue_mem {m p q : ℕ} (hm : 1 < m)\n    (hp : p.Coprime m) (hq : q.Coprime m)\n    (hzero : FermatQuotientZero m p ∨ FermatQuotientZero m q) :\n    p % (m ^ 2) ∈ factorResidues (p * q) m := by\n  rcases hzero with h | h\n  · exact Finset.mem_union_left _ (residue_mem_teichmuller hm hp h)\n  · apply Finset.mem_union_right\n    apply Finset.mem_image.mpr\n    exact ⟨q % (m ^ 2), residue_mem_teichmuller hm hq h,\n      reciprocal_complement (by omega) hq⟩\n\n/-- The covered small factor has an index in the public interval `0,...,m`. -/\ntheorem public_index_coverage {m p q : ℕ} (hm : 1 < m)\n    (hp : p.Coprime m) (hq : q.Coprime m) (hsize : p ≤ m ^ 3)\n    (hzero : FermatQuotientZero m p ∨ FermatQuotientZero m q) :\n    ∃ s ∈ factorResidues (p * q) m, ∃ k ≤ m, p = s + m ^ 2 * k := by\n  refine ⟨p % (m ^ 2), either_factor_residue_mem hm hp hq hzero,\n    p / (m ^ 2), ?_, (Nat.mod_add_div p (m ^ 2)).symm⟩\n  apply Nat.div_le_of_le_mul\n  nlinarith [hsize]\n\n/-- The catalog is never larger than twice the raw tag range. -/\ntheorem factorResidues_card_le (N m : ℕ) : (factorResidues N m).card ≤ 2 * m := by\n  calc\n    (factorResidues N m).card ≤ (teichmullerResidues m).card +\n        ((teichmullerResidues m).image (reciprocalResidue N m)).card :=\n      Finset.card_union_le _ _\n    _ ≤ 2 * (teichmullerResidues m).card := by\n      have := Finset.card_image_le (s := teichmullerResidues m) (f := reciprocalResidue N m)\n      omega\n    _ ≤ 2 * m := by\n      have hi := Finset.card_image_le\n        (s := (Finset.range m).filter (fun j => j ≠ 0))\n        (f := fun j => j ^ m % (m ^ 2))\n      have hf := Finset.card_filter_le (s := Finset.range m) (p := fun j => j ≠ 0)\n      simp only [Finset.card_range] at hf\n      change 2 * (((Finset.range m).filter (fun j => j ≠ 0)).image\n        (fun j => j ^ m % (m ^ 2))).card ≤ 2 * m\n      omega\n\n/-- Every listed residue is reduced modulo the public square. -/\ntheorem factorResidues_lt {N m s : ℕ} (hm : 0 < m)\n    (hs : s ∈ factorResidues N m) : s < m ^ 2 := by\n  have : NeZero (m ^ 2) := ⟨pow_ne_zero 2 hm.ne'⟩\n  rcases Finset.mem_union.mp hs with hs | hs\n  · rcases Finset.mem_image.mp hs with ⟨j, _, rfl⟩\n    exact Nat.mod_lt _ (pow_pos hm _)\n  · rcases Finset.mem_image.mp hs with ⟨j, _, rfl⟩\n    exact ZMod.val_lt _\n\n/-- The covered factor residue is nonzero, so a zero candidate may safely be skipped. -/\ntheorem factor_residue_pos {m p : ℕ} (hm : 1 < m) (hp : p.Coprime m) :\n    0 < p % (m ^ 2) := by\n  have hc := hp.pow_right 2\n  have hg : Nat.gcd (p % (m ^ 2)) (m ^ 2) = 1 := by\n    rw [← Nat.gcd_rec]\n    exact hc.symm\n  apply Nat.pos_of_ne_zero\n  intro he\n  simp only [he, Nat.gcd_zero_left] at hg\n  nlinarith\n\n/-- Every retained nonzero candidate lies below the explicit public cubic cap. -/\ntheorem candidate_bounds {m s k : ℕ} (hs : 0 < s)\n    (hslt : s < m ^ 2) (hk : k ≤ m) :\n    0 < s + m ^ 2 * k ∧ s + m ^ 2 * k < m ^ 3 + m ^ 2 := by\n  constructor\n  · omega\n  · have hx := Nat.mul_le_mul_left (m ^ 2) hk\n    nlinarith\n\n/-- The strong-prefix product bound makes every such positive leaf smaller than N. -/\ntheorem candidate_lt_modulus {N m s k : ℕ} (hm : 1 < m) (hs : 0 < s)\n    (hslt : s < m ^ 2) (hk : k ≤ m) (hN : (16 * m ^ 2) ^ 2 < N) :\n    0 < s + m ^ 2 * k ∧ s + m ^ 2 * k < N := by\n  obtain ⟨hpos, hcap⟩ := candidate_bounds hs hslt hk\n  refine ⟨hpos, hcap.trans_le ?_⟩\n  have hm2 : 2 ≤ m := hm\n  have hsq : m ^ 2 ≤ m ^ 3 := by nlinarith [Nat.mul_le_mul_right (m ^ 2) (by omega : 1 ≤ m)]\n  have hfour : m ^ 3 ≤ m ^ 4 := by nlinarith [Nat.mul_le_mul_left (m ^ 3) (by omega : 1 ≤ m)]\n  nlinarith\n\n/-- A nonunit gcd at a positive bounded leaf is automatically a proper factor. -/\ntheorem proper_gcd_of_bounded_leaf {N c : ℕ} (hc : 0 < c) (hcN : c < N)\n    (hg : 1 < Nat.gcd c N) :\n    1 < Nat.gcd c N ∧ Nat.gcd c N < N := by\n  exact ⟨hg, (Nat.gcd_le_left N hc).trans_lt hcN⟩\n\n/-- Publicly discard the zero residue; this cannot remove a coprime factor. -/\ndef positiveFactorResidues (N m : ℕ) : Finset ℕ :=\n  (factorResidues N m).filter (fun s => 0 < s)\n\n/-- The positive catalog keeps the same linear cardinality bound. -/\ntheorem positiveFactorResidues_card_le (N m : ℕ) :\n    (positiveFactorResidues N m).card ≤ 2 * m :=\n  (Finset.card_filter_le _ _).trans (factorResidues_card_le N m)\n\n/-- Either hidden zero Fermat quotient has an actual bounded positive public leaf. -/\ntheorem positive_public_index_coverage {m p q : ℕ} (hm : 1 < m)\n    (hp : p.Coprime m) (hq : q.Coprime m) (hsize : p ≤ m ^ 3)\n    (hzero : FermatQuotientZero m p ∨ FermatQuotientZero m q) :\n    ∃ s ∈ positiveFactorResidues (p * q) m, ∃ k ≤ m,\n      p = s + m ^ 2 * k := by\n  refine ⟨p % (m ^ 2), ?_, p / (m ^ 2), ?_, (Nat.mod_add_div p (m ^ 2)).symm⟩\n  · exact Finset.mem_filter.mpr ⟨either_factor_residue_mem hm hp hq hzero,\n      factor_residue_pos hm hp⟩\n  · apply Nat.div_le_of_le_mul\n    nlinarith [hsize]\n\n/-- Every public positive leaf is strictly between zero and the modulus. -/\ntheorem all_public_leaves_bounded {N m s k : ℕ} (hm : 1 < m)\n    (hs : s ∈ positiveFactorResidues N m) (hk : k ≤ m)\n    (hN : (16 * m ^ 2) ^ 2 < N) :\n    0 < s + m ^ 2 * k ∧ s + m ^ 2 * k < N := by\n  obtain ⟨hmem, hpos⟩ := Finset.mem_filter.mp hs\n  exact candidate_lt_modulus hm hpos (factorResidues_lt (by omega) hmem) hk hN\n\n/-- A nonunit at any catalog leaf is already a proper factor, never a saturated leaf. -/\ntheorem public_leaf_proper_gcd {N m s k : ℕ} (hm : 1 < m)\n    (hs : s ∈ positiveFactorResidues N m) (hk : k ≤ m)\n    (hN : (16 * m ^ 2) ^ 2 < N) (hg : 1 < Nat.gcd (s + m ^ 2 * k) N) :\n    1 < Nat.gcd (s + m ^ 2 * k) N ∧ Nat.gcd (s + m ^ 2 * k) N < N := by\n  obtain ⟨hc, hcN⟩ := all_public_leaves_bounded hm hs hk hN\n  exact proper_gcd_of_bounded_leaf hc hcN hg\n\n/-- Sixth-root scale bounds the smaller factor by the public cube. -/\ntheorem smaller_factor_le_cube {m p q : ℕ} (hpq : p ≤ q)\n    (hsize : p * q ≤ m ^ 6) : p ≤ m ^ 3 := by\n  have hpp := Nat.mul_le_mul_left p hpq\n  have he : m ^ 6 = (m ^ 3) ^ 2 := by ring\n  rw [he] at hsize\n  by_contra! h\n  have hlt := Nat.mul_self_lt_mul_self h\n  have hle : p * p ≤ m ^ 3 * m ^ 3 := by\n    simpa only [pow_two] using hpp.trans hsize\n  exact (not_lt_of_ge hle) hlt\n\n/-- Complete public arithmetic coverage from the semiprime sixth-scale hypotheses. -/\ntheorem sixth_scale_public_index_coverage {m p q : ℕ} (hm : 1 < m)\n    (hp : p.Coprime m) (hq : q.Coprime m) (hpq : p ≤ q)\n    (hsize : p * q ≤ m ^ 6)\n    (hzero : FermatQuotientZero m p ∨ FermatQuotientZero m q) :\n    ∃ s ∈ positiveFactorResidues (p * q) m, ∃ k ≤ m,\n      p = s + m ^ 2 * k :=\n  positive_public_index_coverage hm hp hq (smaller_factor_le_cube hpq hsize) hzero\n\nend RiemannGaussian.SemiprimeFermatQuotientCatalog\n","RiemannGaussian.SemiprimeFullSetupPublicController":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidFactorDecoder\nimport RiemannGaussian.SemiprimeCachedSourcePublicExecution\nimport RiemannGaussian.SemiprimeFullSetupCounter\n\n/-!\n# Actual public counter reports survive prefixRun recovery and decoding\n\nEvery query executes FullSetupCounter ONCE and retains its full source/native\nreport. No count callback is a public runtime input. The budget theorem takes a\nbound on this ACTUAL counter report; setup reports are retained from the new full-setup counter. Literal machine\naddressing and a complete primitive bit clock remain distinct obligations.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeFullSetupPublicController\nopen scoped BigOperators\nopen SemiprimePaidPrefixController SemiprimePublicAcquiredExecution SemiprimeMacroParameters\nopen SemiprimeLocalArrayFrontend\n\n/-- Actual public restricted scalar counter, never a supplied count answer. -/\ndef counter (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (fixed : List (Fin (wireCount N) × Bool)) : SemiprimeAcquiredHermite.ScalarRun :=\n  SemiprimeFullSetupCounter.count (r := r) (Q := Q)\n    (indexedArity N) (indexedCoordinate N hN) eps R 2 J\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed)\n\n/-- One cached scalar report, an actual rational floor, and retained prefixRun metadata work. -/\ndef prefixRun (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (fixed : List (Fin (wireCount N) × Bool)) : Run ℕ :=\n  let result := counter N hN r Q eps R J fixed\n  ⟨Nat.floor result.value,result.work+fixed.length+3⟩\n\n/-- Numerical guards identify the newly acquired scalar with the previous exact public count. -/\ntheorem prefix_value (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    (prefixRun N hN r Q eps R J fixed).value=\n      SemiprimeCachedSourcePublicExecution.prefixCount N hN r Q eps R J fixed := by\n  apply congrArg Nat.floor\n  exact (SemiprimeFullSetupCounter.count_correct\n    (indexedArity N) (indexedCoordinate N hN) eps R 2 J\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed) (indexed_occurrences N hN) hQ hAQ hJ hprecision).trans\n    (SemiprimeCachedSourceCounter.count_correct\n      (indexedArity N) (indexedCoordinate N hN) eps R 2 J\n      (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n        (indexedEntry N hN) fixed) (indexed_occurrences N hN) hQ hAQ hJ hprecision).symm\n\n/-- Every restricted query counts exactly the original accepting assignments. -/\ntheorem prefix_correct (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    (prefixRun N hN r Q eps R J fixed).value =\n      SemiprimeCountRecovery.acceptedCount\n        (SemiprimeCountRecovery.restricted SemiprimeCounterSearch.assignmentBit (indexedPredicate N hN) fixed) := by\n  rw [prefix_value N hN r Q eps R J hQ hAQ hJ hprecision]\n  exact SemiprimeCachedSourcePublicExecution.prefixCount_correct N hN r Q eps R J hQ hAQ hJ hprecision fixed\n\n/-- No source/native work is discarded by floor or prefixRun recovery. -/\ntheorem prefix_work (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    (prefixRun N hN r Q eps R J fixed).work=\n      (counter N hN r Q eps R J fixed).work+fixed.length+3 := rfl\n\n/-- Actual paid original local checker plus a uniform all-reachable-prefixRun gate budget. -/\ndef entryBudget (N : ℕ) : ℕ :=\n  1048576*(64*bitLength N+2)^10+wireCount N*(3*scopeBound (bitLength N)+2)+1\n\n/-- The terminal callback budget is derived, not supplied as a unit-cost table. -/\ntheorem entry_work_le (N : ℕ) (hN : 0< N) (fixed : List (Fin (wireCount N) × Bool))\n    (hf : fixed.length≤ wireCount N) (e : Fin (factorCount N))\n    (input : Fin (indexedArity N e) → Bool) :\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed e input).arithmetic≤ entryBudget N ∧\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed e input).reads≤ entryBudget N := by\n  have hw := SemiprimeAcquiredPrefixSearch.entry_work (indexedArity N) (indexedCoordinate N hN)\n    (indexedEntry N hN) fixed e input\n  have hc := indexedEntry_clock N hN e input\n  have he := indexedArity_le N e\n  have hm := Nat.mul_le_mul hf (show 3*indexedArity N e+2≤3*scopeBound (bitLength N)+2 by omega)\n  rw [hw.1,hw.2]\n  constructor <;> unfold entryBudget <;> omega\n\n/-- Report-bearing search invokes the actual acquired counter at every query. -/\ndef search (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    SearchResult (Fin (wireCount N)) :=\n  let indices := finIndices (wireCount N)\n  let result := SemiprimePaidPrefixController.search (prefixRun N hN r Q eps R J) indices.value\n  ⟨result.values,result.queries,result.work+indices.work+1⟩\n\n/-- Exact selected list and query count are preserved under the numerical guards. -/\ntheorem search_result (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    :\n    (search N hN r Q eps R J).values=(SemiprimeCachedSourcePublicExecution.search N hN r Q eps R J).values ∧\n      (search N hN r Q eps R J).queries=(SemiprimeCachedSourcePublicExecution.search N hN r Q eps R J).queries := by\n  have hp : (fun fixed => (prefixRun N hN r Q eps R J fixed).value) =\n      SemiprimeCachedSourcePublicExecution.prefixCount N hN r Q eps R J := by\n    funext fixed\n    exact prefix_value N hN r Q eps R J hQ hAQ hJ hprecision fixed\n  simpa only [search,finIndices_value,hp,SemiprimeCachedSourcePublicExecution.search] using\n    SemiprimePaidPrefixController.search_result (prefixRun N hN r Q eps R J) (List.finRange (wireCount N))\n\n/-- Complete aggregate count-work bound at every reachable prefixRun length. -/\ntheorem search_work (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J B : ℕ)\n    (hb : ∀ fixed, fixed.length≤ wireCount N → (counter N hN r Q eps R J fixed).work≤ B) :\n    (search N hN r Q eps R J).work≤(wireCount N+1)*(B+wireCount N+11)+1+3*(wireCount N+1)^2+1 := by\n  have h := SemiprimePaidPrefixController.search_work (prefixRun N hN r Q eps R J)\n    (B+wireCount N+3) (List.finRange (wireCount N)) (by\n      intro fixed hf\n      simp only [List.length_finRange] at hf\n      have hc := hb fixed hf\n      rw [prefix_work]\n      omega)\n  simp only [List.length_finRange] at h\n  have he : B+wireCount N+3+8=B+wireCount N+11 := by omega\n  rw [he] at h\n  have ha := finIndices_work (wireCount N)\n  simp only [search,finIndices_value]\n  omega\n\n/-- Actual factor output with both all counter work and the physical decoder work. -/\nstructure FactorRun where\n  /-- Actual decoded integer, or no original accepted factor assignment. -/\n  value : Option ℕ\n  /-- Number of actual acquired counter calls. -/\n  queries : ℕ\n  /-- Complete retained lower reports and selected controller work. -/\n  work : ℕ\n\n/-- Search once, then decode once on its actual positive branch. -/\ndef factor (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) : FactorRun :=\n  let selected := search N hN r Q eps R J\n  match selected.values with\n  | none => ⟨none,selected.queries,selected.work+2⟩\n  | some values =>\n    let decoded := SemiprimePaidFactorDecoder.decode N values 0\n    ⟨some decoded.value,selected.queries,selected.work+decoded.work+2⟩\n\n/-- Under the numerical guards, every public output agrees exactly with the actual prior source-counter factorer. -/\ntheorem factor_value (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    (factor N hN r Q eps R J).value=SemiprimeCachedSourcePublicExecution.factor N hN r Q eps R J := by\n  have hs := (search_result N hN r Q eps R J hQ hAQ hJ hprecision).1\n  unfold SemiprimeCachedSourcePublicExecution.factor\n  rw [← hs]\n  unfold factor\n  cases he : (search N hN r Q eps R J).values <;>\n    simp only [he,SemiprimePaidFactorDecoder.decode_value,Option.map_none,Option.map_some]\n\n/-- Correct guarded public outputs are actual nontrivial integer divisors. -/\ntheorem factor_sound (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (p : ℕ) (hp : (factor N hN r Q eps R J).value=some p) : 2≤p ∧ p<N ∧ p∣N :=\n  SemiprimeCachedSourcePublicExecution.factor_sound N hN r Q eps R J hQ hAQ hJ hprecision p\n    ((factor_value N hN r Q eps R J hQ hAQ hJ hprecision).symm.trans hp)\n\n/-- Under the numerical guards, failure means there is no ordinary factor pair. -/\ntheorem factor_none_iff (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    : (factor N hN r Q eps R J).value=none ↔\n      ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [factor_value N hN r Q eps R J hQ hAQ hJ hprecision]\n  exact SemiprimeCachedSourcePublicExecution.factor_none_iff N hN r Q eps R J hQ hAQ hJ hprecision\n\n/-- At most one initial plus one acquired counter call per actual public wire. -/\ntheorem factor_queries (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    (factor N hN r Q eps R J).queries≤wireCount N+1 := by\n  have hs := SemiprimePaidPrefixController.search_queries (prefixRun N hN r Q eps R J)\n    (List.finRange (wireCount N))\n  simp only [List.length_finRange] at hs\n  unfold factor\n  cases he : (search N hN r Q eps R J).values <;> simp only [he] <;> simpa only [search,finIndices_value] using hs\n\n/-- Complete uniform factor-controller envelope, with explicit physical decoder dimensions. -/\ntheorem factor_work (N : ℕ) (hN : 0< N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J B : ℕ)\n    (hb : ∀ fixed, fixed.length≤ wireCount N → (counter N hN r Q eps R J fixed).work≤ B) :\n    (factor N hN r Q eps R J).work≤\n      (wireCount N+1)*(B+wireCount N+3*(wireCount N+1)^2+SemiprimePaidFactorDecoder.budget N (wireCount N)+16) := by\n  have hs := search_work N hN r Q eps R J B hb\n  have hlarge : (wireCount N+1)*(B+wireCount N+11)+1+3*(wireCount N+1)^2+1+\n      SemiprimePaidFactorDecoder.budget N (wireCount N)+2≤\n        (wireCount N+1)*(B+wireCount N+3*(wireCount N+1)^2+SemiprimePaidFactorDecoder.budget N (wireCount N)+16) := by\n    nlinarith [Nat.zero_le (wireCount N*SemiprimePaidFactorDecoder.budget N (wireCount N))]\n  unfold factor\n  cases he : (search N hN r Q eps R J).values with\n  | none =>\n    simp only [he]\n    calc\n      _ ≤ (wireCount N+1)*(B+wireCount N+11)+1+3*(wireCount N+1)^2+1+2 := Nat.add_le_add_right hs 2\n      _ ≤ (wireCount N+1)*(B+wireCount N+11)+1+3*(wireCount N+1)^2+1+SemiprimePaidFactorDecoder.budget N (wireCount N)+2 := by omega\n      _ ≤ _ := hlarge\n  | some values =>\n    have hl := SemiprimePaidPrefixController.search_length (prefixRun N hN r Q eps R J)\n      (List.finRange (wireCount N)) values (by simpa only [search,finIndices_value] using he)\n    simp only [List.length_finRange] at hl\n    have hd := SemiprimePaidFactorDecoder.decode_work N values 0\n    rw [hl] at hd\n    simp only [he]\n    exact (Nat.add_le_add_right (Nat.add_le_add hs hd) 2).trans hlarge\n\nend RiemannGaussian.SemiprimeFullSetupPublicController\n","RiemannGaussian.SemiprimeGlobalPhaseCancellation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeForcedRowSeparation\n\n/-!\n# Exact cancellation of all common global row hits\n\nCross-multiplying two verified global hits cancels the large N term.\nThe routed global order exceeds the entire remaining integer interval,\nso the congruence is an exact phase identity. At the prime row modulus\nits residue support has degree at most two. This classifies common global\nhits; acquiring a first hit and the complete bit budget remain separate.\n-/\n\nnamespace RiemannGaussian.SemiprimeGlobalPhaseCancellation\n\nopen SemiprimeQuotientRows SemiprimeDenseRowCoverage SemiprimeDenseRowCarries\nopen SemiprimeMergedIndexAcquisition SemiprimeForcedRowSeparation\nopen SemiprimeGroupSelection SemiprimeLocalOrderRouting SemiprimeWrapIndexRecovery\nopen SemiprimeCentreFreeCover SemiprimeWideWrapCoverage\nopen Polynomial\n\n/-- The small part of a seed exponent, computed from its cached data. -/\ndef cachedOffset {G : Type*} (m : ℕ) (s : ProgressionSeed G) : ℤ :=\n  (s.slope : ℤ)+(m : ℤ)*s.linear-2*(s.slope : ℤ)*s.residue\n\n/-- Public denominator-one offset, independent of any group or factor. -/\ndef seedOffset (N m j : ℕ) : ℤ :=\n  (representative N m j 1 : ℤ)+(m : ℤ)*(seedRow N m j).b-\n    2*(representative N m j 1 : ℤ)*j\n\n/-- Cached and public offsets are literally the same integer. -/\ntheorem cachedOffset_seed {G : Type*} [CommGroup G] (g : G) (N m j : ℕ) :\n    cachedOffset m (progressionSeed g N m j)=seedOffset N m j := rfl\n\n/-- All original positive-residue seed offsets lie in one short interval. -/\ntheorem seedOffset_bounds {N m j : ℕ} (hm : 1<m) (hj : 1≤j) (hjm : j<m) :\n    -3*(m : ℤ)^2≤seedOffset N m j ∧ seedOffset N m j≤(m : ℤ)^2 := by\n  have hA : (0 : ℤ)≤representative N m j 1 := by positivity\n  have hAm : (representative N m j 1 : ℤ)≤m := by\n    exact_mod_cast (Nat.mod_lt (quotientSlope N m j*1) (by omega : 0<m)).le\n  have hjz : (1 : ℤ)≤j := by exact_mod_cast hj\n  have hjmz : (j : ℤ)≤m := by exact_mod_cast hjm.le\n  have hmz : (0 : ℤ)≤m := by positivity\n  have hb := abs_le.mp (denseRow_b_bound (N:=N) (j:=j) (t:=1) hm false)\n  change -(m : ℤ)≤(seedRow N m j).b ∧ (seedRow N m j).b≤m at hb\n  have hbm0 := mul_le_mul_of_nonneg_left hb.1 hmz\n  have hbm1 := mul_le_mul_of_nonneg_left hb.2 hmz\n  have hprod := mul_le_mul hAm hjmz (by positivity : (0 : ℤ)≤j) hmz\n  have hprod0 := mul_nonneg hA (by omega : (0 : ℤ)≤2*(j : ℤ)-1)\n  unfold seedOffset\n  constructor <;> nlinarith only [hA,hbm0,hbm1,hprod,hprod0]\n\n/-- A literal public seed step has exponent N plus its short offset. -/\ntheorem seed_step_offset {G : Type*} [CommGroup G] (g : G) {N m j : ℕ}\n    (hm : 0<m) (hj : j.Coprime m) :\n    (progressionSeed g N m j).step=g^((N : ℤ)+seedOffset N m j) := by\n  have hr := denseRow_relation (N:=N) (j:=j) (t:=1) hm hj false\n  change quotientRelation N m j (seedRow N m j).a (seedRow N m j).b\n    (seedRow N m j).c (seedRow N m j).t at hr\n  have hden : (seedRow N m j).t=(1 : ℤ) := rfl\n  rw [hden] at hr\n  have he := giantExponent_eq hr\n  simp only [one_mul] at he\n  change g^giantExponent m j (seedRow N m j).a (seedRow N m j).b\n    (seedRow N m j).c=_\n  rw [he]\n  congr 1\n  have ha : (seedRow N m j).a=(representative N m j 1 : ℤ) := rfl\n  rw [ha]\n  unfold seedOffset\n  ring\n\n/-- A verified common global row hit has this integer order residual. -/\ntheorem hit_residual_iff {G : Type*} [CommGroup G] (g : G) {N m j t : ℕ}\n    (hm : 0<m) (hj : j.Coprime m) (z : ℤ) :\n    (progressionSeed g N m j).step^t=(commonStep g m)^z ↔\n      (orderOf g : ℤ)∣(t : ℤ)*((N : ℤ)+seedOffset N m j)-(m : ℤ)*z := by\n  rw [seed_step_offset g hm hj]\n  simp only [commonStep,←zpow_natCast,←zpow_mul]\n  rw [←orderOf_dvd_sub_iff_zpow_eq_zpow]\n  rw [mul_comm ((N : ℤ)+seedOffset N m j) (t : ℤ)]\n\n/-- The CRT order is a product, large enough to forbid wraparound after\ncancelling the common N term between any two original global hits. -/\ntheorem long_global_order_bound {p q m : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) :\n    16*m^4<orderOf (projectedUnit g m) := by\n  rw [global_order_eq_lcm hp hq hpq,(hlong.2.2.2.2.1).lcm_eq_mul]\n  have hP : 4*m^2<orderOf (leftUnit (projectedUnit g m)) := by\n    have hh := hlong.2.2.2.1.1\n    nlinarith only [hh]\n  have hQ : 4*m^2<orderOf (rightUnit (projectedUnit g m)) := by\n    have hh := hlong.2.2.2.1.2\n    nlinarith only [hh]\n  have hmul₀ := mul_le_mul_of_nonneg_left hQ.le (Nat.zero_le (4*m^2))\n  have hmul₁ := mul_lt_mul_of_pos_right hP\n    (by omega : 0<orderOf (rightUnit (projectedUnit g m)))\n  nlinarith only [hmul₀,hmul₁]\n\n/-- Every cross residual, including those from false global row tags,\nfits strictly inside the routed global-order interval. -/\ntheorem cross_residual_bound {m t t₀ : ℕ} {δ δ₀ z z₀ : ℤ}\n    (ht : t≤m) (ht₀ : t₀≤m)\n    (hδ : -3*(m : ℤ)^2≤δ ∧ δ≤(m : ℤ)^2)\n    (hδ₀ : -3*(m : ℤ)^2≤δ₀ ∧ δ₀≤(m : ℤ)^2)\n    (hz : -4*(m : ℤ)^2≤z ∧ z≤2*(m : ℤ)^2)\n    (hz₀ : -4*(m : ℤ)^2≤z₀ ∧ z₀≤2*(m : ℤ)^2) :\n    |(t : ℤ)*t₀*(δ-δ₀)-(m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀)|≤\n      12*(m : ℤ)^4 := by\n  have htZ : (t : ℤ)≤m := by exact_mod_cast ht\n  have ht₀Z : (t₀ : ℤ)≤m := by exact_mod_cast ht₀\n  have hd : |δ-δ₀|≤4*(m : ℤ)^2 := abs_le.mpr (by constructor <;> omega)\n  have hzA : |z|≤4*(m : ℤ)^2 := abs_le.mpr (by constructor <;> nlinarith only [hz.1,hz.2,sq_nonneg (m : ℤ)])\n  have hz₀A : |z₀|≤4*(m : ℤ)^2 := abs_le.mpr (by constructor <;> nlinarith only [hz₀.1,hz₀.2,sq_nonneg (m : ℤ)])\n  have htt := mul_le_mul htZ ht₀Z (by positivity : (0 : ℤ)≤t₀) (by positivity : (0 : ℤ)≤m)\n  have hterm := mul_le_mul htt hd (abs_nonneg _) (by positivity : (0 : ℤ)≤(m : ℤ)*m)\n  have htZz := mul_le_mul ht₀Z hzA (abs_nonneg _) (by positivity : (0 : ℤ)≤m)\n  have htZz₀ := mul_le_mul htZ hz₀A (abs_nonneg _) (by positivity : (0 : ℤ)≤m)\n  have hinner : |(t₀ : ℤ)*z-(t : ℤ)*z₀|≤8*(m : ℤ)^3 := by\n    have hh := abs_sub ((t₀ : ℤ)*z) ((t : ℤ)*z₀)\n    simp only [abs_mul,abs_of_nonneg (by positivity : (0 : ℤ)≤t),\n      abs_of_nonneg (by positivity : (0 : ℤ)≤t₀)] at hh\n    nlinarith only [hh,htZz,htZz₀]\n  have houter := mul_le_mul_of_nonneg_left hinner (by positivity : (0 : ℤ)≤m)\n  have hh := abs_sub ((t : ℤ)*t₀*(δ-δ₀)) ((m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀))\n  simp only [abs_mul,abs_of_nonneg (by positivity : (0 : ℤ)≤t),\n    abs_of_nonneg (by positivity : (0 : ℤ)≤t₀),\n    abs_of_nonneg (by positivity : (0 : ℤ)≤m)] at hh\n  nlinarith only [hh,hterm,houter]\n\n/-- Removing N from two global-hit congruences gives an exact integer\nidentity whenever the global order has the routed lower bound. -/\ntheorem global_phase_identity {G : Type*} [CommGroup G] (g : G)\n    {N m j j₀ t t₀ : ℕ} {z z₀ : ℤ}\n    (hm : 1<m) (hj : 1≤j) (hjm : j<m) (hj₀ : 1≤j₀) (hj₀m : j₀<m)\n    (hcop : j.Coprime m) (hcop₀ : j₀.Coprime m)\n    (ht : t<m) (ht₀ : t₀<m)\n    (hz : -4*(m : ℤ)^2≤z ∧ z<2*(m : ℤ)^2)\n    (hz₀ : -4*(m : ℤ)^2≤z₀ ∧ z₀<2*(m : ℤ)^2)\n    (horder : 16*m^4<orderOf g)\n    (hhit : (progressionSeed g N m j).step^t=(commonStep g m)^z)\n    (hhit₀ : (progressionSeed g N m j₀).step^t₀=(commonStep g m)^z₀) :\n    (t : ℤ)*t₀*(seedOffset N m j-seedOffset N m j₀)=\n      (m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀) := by\n  have hdiv := (hit_residual_iff g (by omega) hcop z).mp hhit\n  have hdiv₀ := (hit_residual_iff g (by omega) hcop₀ z₀).mp hhit₀\n  have he : (t₀ : ℤ)*((t : ℤ)*((N : ℤ)+seedOffset N m j)-(m : ℤ)*z)-\n      (t : ℤ)*((t₀ : ℤ)*((N : ℤ)+seedOffset N m j₀)-(m : ℤ)*z₀)=\n      (t : ℤ)*t₀*(seedOffset N m j-seedOffset N m j₀)-\n        (m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀) := by ring\n  have hd := (dvd_mul_of_dvd_right hdiv (t₀ : ℤ)).sub\n    (dvd_mul_of_dvd_right hdiv₀ (t : ℤ))\n  rw [he] at hd\n  have hb := cross_residual_bound ht.le ht₀.le\n    (seedOffset_bounds (N:=N) hm hj hjm) (seedOffset_bounds (N:=N) hm hj₀ hj₀m)\n    ⟨hz.1,hz.2.le⟩ ⟨hz₀.1,hz₀.2.le⟩\n  have ho : 12*(m : ℤ)^4<(orderOf g : ℤ) := by\n    have hh : 12*m^4<orderOf g := by nlinarith only [horder]\n    exact_mod_cast hh\n  have hab := hb.trans_lt ho\n  rw [←Int.natCast_natAbs] at hab\n  have habN : ((t : ℤ)*t₀*(seedOffset N m j-seedOffset N m j₀)-\n      (m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀)).natAbs<(orderOf g : ℤ).natAbs := by\n    simpa only [Int.natAbs_natCast] using (show _<orderOf g by exact_mod_cast hab)\n  have heq := Int.eq_zero_of_dvd_of_natAbs_lt_natAbs hd habN\n  linarith only [heq]\n\n/-- A verified original global tag includes its public source bounds. -/\ndef GlobalHit {G : Type*} [CommGroup G] (g : G) (N m j t : ℕ) (z : ℤ) : Prop :=\n  0<t ∧ t<m ∧ 1≤j ∧ j<m ∧ -4*(m : ℤ)^2≤z ∧ z<2*(m : ℤ)^2 ∧\n    (progressionSeed g N m j).step^t=(commonStep g m)^z\n\n/-- A prime row modulus cancels both short positive denominators from\nthe exact phase identity, leaving equality of the offset residue classes. -/\ntheorem phase_offset_divisible {m t t₀ : ℕ} {δ δ₀ z z₀ : ℤ}\n    (hm : m.Prime) (ht : 0<t) (htm : t<m) (ht₀ : 0<t₀) (ht₀m : t₀<m)\n    (he : (t : ℤ)*t₀*(δ-δ₀)=(m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀)) :\n    (m : ℤ)∣δ-δ₀ := by\n  have hc : t.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt ht htm)).symm\n  have hc₀ : t₀.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt ht₀ ht₀m)).symm\n  have hd : (m : ℤ)∣(t : ℤ)*t₀*(δ-δ₀) := by\n    rw [he]\n    exact dvd_mul_right _ _\n  rw [mul_assoc] at hd\n  exact hc₀.isCoprime.symm.dvd_of_dvd_mul_left\n    (hc.isCoprime.symm.dvd_of_dvd_mul_left hd)\n\n/-- All verified global tags of the actual long base share one exact\nphase. No tag is assumed to be the private factor witness. -/\ntheorem long_global_phase {p q m j j₀ t t₀ : ℕ} {z z₀ : ℤ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hhit : GlobalHit (projectedUnit g m) (p*q) m j t z)\n    (hhit₀ : GlobalHit (projectedUnit g m) (p*q) m j₀ t₀ z₀) :\n    (t : ℤ)*t₀*(seedOffset (p*q) m j-seedOffset (p*q) m j₀)=\n      (m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀) := by\n  rcases hhit with ⟨_,ht,hj,hjm,hz,hzm,he⟩\n  rcases hhit₀ with ⟨_,ht₀,hj₀,hj₀m,hz₀,hz₀m,he₀⟩\n  have hc : j.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hjm)).symm\n  have hc₀ : j₀.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hj₀m)).symm\n  exact global_phase_identity (projectedUnit g m) hm.one_lt hj hjm hj₀ hj₀m\n    hc hc₀ ht ht₀ ⟨hz,hzm⟩ ⟨hz₀,hz₀m⟩ (long_global_order_bound hp hq hpq g hlong) he he₀\n\n/-- The quotient slope multiplied by the original residue square is N. -/\ntheorem slope_square_residue {N m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    (representative N m j 1 : ZMod m)*(j : ZMod m)^2=(N : ZMod m) := by\n  have hr := representative_congruence (N:=N) (j:=j) (t:=1) hm\n  simp only [Nat.cast_one,mul_one] at hr\n  have hi := ((publicInverse_correct hj).pow 2).mul_left (N : ℤ)\n  have hcross : (j : ℤ)^2*((N : ℤ)*(publicInverse m j)^2) ≡ (N : ℤ) [ZMOD m] := by\n    convert hi using 1 <;> first | rfl | ring\n  have hs := (hr.mul_left ((j : ℤ)^2)).trans hcross\n  have hz := (ZMod.intCast_eq_intCast_iff _ _ m).mpr hs\n  simpa only [Int.cast_mul,Int.cast_pow,Int.cast_natCast,mul_comm] using hz\n\n/-- The offset residue has a quadratic relation in the original public\nresidue. Centering disappears modulo m without discarding its integer carry. -/\ntheorem offset_square_residue {N m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    (seedOffset N m j : ZMod m)*(j : ZMod m)^2=\n      (N : ZMod m)*(1-2*(j : ZMod m)) := by\n  have hs := slope_square_residue (N:=N) hm hj\n  unfold seedOffset\n  push_cast\n  simp only [ZMod.natCast_self,zero_mul,add_zero]\n  calc\n    ((representative N m j 1 : ZMod m)-2*(representative N m j 1 : ZMod m)*j)*j^2=\n        ((representative N m j 1 : ZMod m)*j^2)*(1-2*(j : ZMod m)) := by ring\n    _=(N : ZMod m)*(1-2*(j : ZMod m)) := by rw [hs]\n\n/-- A phase class is a degree-at-most-two polynomial over the public\nprime row field. Its constant term is nonzero after the public prefix. -/\nnoncomputable def phasePolynomial (N m : ℕ) (δ : ℤ) : (ZMod m)[X] :=\n  C (δ : ZMod m)*X^2+C (2*(N : ZMod m))*X-C (N : ZMod m)\n\n/-- Public coprimality excludes the zero phase polynomial. -/\ntheorem phasePolynomial_ne_zero {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (δ : ℤ) : phasePolynomial N m δ≠0 := by\n  intro he\n  have hc := congrArg (fun P : (ZMod m)[X] => P.coeff 0) he\n  simp only [phasePolynomial,coeff_sub,coeff_add,coeff_C_mul_X_pow,\n    coeff_C_mul_X,coeff_C_zero,coeff_zero,show (0 : ℕ)≠2 by decide,\n    show (0 : ℕ)≠1 by decide,ite_false,zero_add,zero_sub,neg_eq_zero] at hc\n  have hd := (ZMod.natCast_eq_zero_iff N m).mp hc\n  have hdiv : m∣1 := by\n    simpa only [hN.gcd_eq_one] using Nat.dvd_gcd (dvd_refl m) hd\n  have hm1 := Nat.le_of_dvd (by decide : 0<1) hdiv\n  have hm2 := hm.two_le\n  omega\n\n/-- Every phase polynomial has degree at most two, even when its leading\ncoefficient vanishes. -/\ntheorem phasePolynomial_degree (N m : ℕ) (δ : ℤ) :\n    (phasePolynomial N m δ).natDegree≤2 := by\n  have ha : (C (δ : ZMod m)*X^2 : (ZMod m)[X]).natDegree≤2 :=\n    natDegree_mul_le.trans (add_le_add (le_of_eq (natDegree_C _)) (natDegree_X_pow_le 2))\n  have hb : (C (2*(N : ZMod m))*X : (ZMod m)[X]).natDegree≤1 :=\n    natDegree_mul_le.trans (add_le_add (le_of_eq (natDegree_C _)) natDegree_X_le)\n  have hab := (natDegree_add_le _ _).trans (max_le ha (hb.trans (by decide : 1≤2)))\n  exact (natDegree_sub_le _ _).trans\n    (max_le hab ((le_of_eq (natDegree_C _)).trans (by decide : 0≤2)))\n\n/-- A residue whose cached offset is in the phase class is a root of\nthe same public quadratic. -/\ntheorem phasePolynomial_root {N m j : ℕ} {δ : ℤ} (hm : 0<m)\n    (hj : j.Coprime m) (hd : (m : ℤ)∣seedOffset N m j-δ) :\n    (phasePolynomial N m δ).IsRoot (j : ZMod m) := by\n  have he := (ZMod.intCast_zmod_eq_zero_iff_dvd _ m).mpr hd\n  simp only [Int.cast_sub,sub_eq_zero] at he\n  have hs := offset_square_residue (N:=N) hm hj\n  rw [he] at hs\n  change (phasePolynomial N m δ).eval (j : ZMod m)=0\n  simp only [phasePolynomial,eval_sub,eval_add,eval_mul,eval_C,eval_pow,eval_X]\n  linear_combination hs\n\n/-- Public cached descriptors in one offset residue class. This does not\nquery either hidden local order or either prime factor. -/\ndef phaseSeeds {G : Type*} [CommGroup G] (g : G) (N m j₀ : ℕ) :\n    List (ProgressionSeed G) :=\n  (progressionSeeds g N m).filter fun s =>\n    (cachedOffset m s-seedOffset N m j₀)%(m : ℤ)==0\n\n/-- The phase menu contains at most TWO literal cached descriptors. -/\ntheorem phaseSeeds_length_le_two {G : Type*} [CommGroup G]\n    (g : G) {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N) (j₀ : ℕ) :\n    (phaseSeeds g N m j₀).length≤2 := by\n  classical\n  let : Fact m.Prime := ⟨hm⟩\n  let : NeZero m := ⟨hm.ne_zero⟩\n  let indices := (List.range (m-1)).filter fun r =>\n    (seedOffset N m (r+1)-seedOffset N m j₀)%(m : ℤ)==0\n  have hb {r : ℕ} (hr : r∈indices.toFinset) :\n      r+1<m ∧ (m : ℤ)∣seedOffset N m (r+1)-seedOffset N m j₀ := by\n    have hh := List.mem_filter.mp (List.mem_toFinset.mp hr)\n    have hbr := List.mem_range.mp hh.1\n    exact ⟨by omega,Int.dvd_of_emod_eq_zero (by simpa only [beq_iff_eq] using hh.2)⟩\n  have hlength : (phaseSeeds g N m j₀).length=indices.length := by\n    simp only [phaseSeeds,progressionSeeds,List.filter_map,List.length_map]\n    rfl\n  rw [hlength]\n  let P := phasePolynomial N m (seedOffset N m j₀)\n  have hP : P≠0 := phasePolynomial_ne_zero hm hN _\n  have hmapping : Set.MapsTo (fun r : ℕ => ((r+1 : ℕ) : ZMod m))\n      indices.toFinset P.roots.toFinset := by\n    intro r hr\n    have hbr := hb hr\n    have hcop : (r+1).Coprime m :=\n      (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hbr.1)).symm\n    exact Multiset.mem_toFinset.mpr ((Polynomial.mem_roots hP).mpr\n      (phasePolynomial_root hm.pos hcop hbr.2))\n  have hinj : (indices.toFinset : Set ℕ).InjOn\n      (fun r : ℕ => ((r+1 : ℕ) : ZMod m)) := by\n    intro r hr s hs he\n    have hv := congrArg ZMod.val he\n    simp only [ZMod.val_natCast,Nat.mod_eq_of_lt (hb hr).1,\n      Nat.mod_eq_of_lt (hb hs).1] at hv\n    omega\n  have hcard := Finset.card_le_card_of_injOn _ hmapping hinj\n  have hroots := Multiset.toFinset_card_le P.roots\n  have hdegree := (Polynomial.card_roots' P).trans (phasePolynomial_degree N m _)\n  have hnodup : indices.Nodup := (List.nodup_range (n:=m-1)).filter _\n  rw [List.toFinset_card_of_nodup hnodup] at hcard\n  omega\n\n/-- Exact signed index predicted from one verified phase anchor. Both\ndivisions have explicit integrality checks in the public tag emitter. -/\ndef phaseIndex (m t t₀ : ℕ) (δ δ₀ z₀ : ℤ) : ℤ :=\n  ((t : ℤ)*z₀)/(t₀ : ℤ)+(t : ℤ)*((δ-δ₀)/(m : ℤ))\n\n/-- The exact phase identity forces BOTH divisions used by the public\npredictor to be integral and gives the original signed index exactly. -/\ntheorem phase_index_exact {m t t₀ : ℕ} {δ δ₀ z z₀ : ℤ}\n    (hm : m.Prime) (ht : 0<t) (htm : t<m) (ht₀ : 0<t₀) (ht₀m : t₀<m)\n    (he : (t : ℤ)*t₀*(δ-δ₀)=(m : ℤ)*((t₀ : ℤ)*z-(t : ℤ)*z₀)) :\n    (m : ℤ)∣δ-δ₀ ∧ (t₀ : ℤ)∣(t : ℤ)*z₀ ∧ z=phaseIndex m t t₀ δ δ₀ z₀ := by\n  have hd := phase_offset_divisible hm ht htm ht₀ ht₀m he\n  have hm0 : (m : ℤ)≠0 := by exact_mod_cast hm.ne_zero\n  have ht₀0 : (t₀ : ℤ)≠0 := by exact_mod_cast ht₀.ne'\n  have hδ := Int.ediv_mul_cancel hd\n  rw [←hδ] at he\n  have hlinear : (t₀ : ℤ)*z-(t : ℤ)*z₀=\n      (t : ℤ)*t₀*((δ-δ₀)/(m : ℤ)) := by\n    apply mul_left_cancel₀ hm0\n    nlinarith only [he]\n  have hz : (t₀ : ℤ)∣(t : ℤ)*z₀ := by\n    refine ⟨z-(t : ℤ)*((δ-δ₀)/(m : ℤ)),?_⟩\n    nlinarith only [hlinear]\n  refine ⟨hd,hz,?_⟩\n  have hdivide := Int.ediv_mul_cancel hz\n  apply mul_left_cancel₀ ht₀0\n  unfold phaseIndex\n  nlinarith only [hlinear,hdivide]\n\n/-- Conversely, integral phase predictions preserve a verified global\norder residual. Roughness permits cancelling the anchor denominator. -/\ntheorem phase_prediction_residual {D m t t₀ N : ℕ} {δ δ₀ z₀ : ℤ}\n    (hc : D.Coprime t₀) (hd : (m : ℤ)∣δ-δ₀) (hz : (t₀ : ℤ)∣(t : ℤ)*z₀)\n    (hanchor : (D : ℤ)∣(t₀ : ℤ)*((N : ℤ)+δ₀)-(m : ℤ)*z₀) :\n    (D : ℤ)∣(t : ℤ)*((N : ℤ)+δ)-(m : ℤ)*phaseIndex m t t₀ δ δ₀ z₀ := by\n  have hδ := Int.ediv_mul_cancel hd\n  have hz₀ := Int.ediv_mul_cancel hz\n  have he : (t₀ : ℤ)*((t : ℤ)*((N : ℤ)+δ)-(m : ℤ)*phaseIndex m t t₀ δ δ₀ z₀)=\n      (t : ℤ)*((t₀ : ℤ)*((N : ℤ)+δ₀)-(m : ℤ)*z₀) := by\n    unfold phaseIndex\n    linear_combination -(t : ℤ)*t₀*hδ-(m : ℤ)*hz₀\n  apply hc.isCoprime.dvd_of_dvd_mul_left\n  rw [he]\n  exact dvd_mul_of_dvd_right hanchor (t : ℤ)\n\n/-- Every short positive denominator is coprime to the actual global\norder. This is proof-side cancellation, with no order query in the mask. -/\ntheorem long_global_coprime_small {p q m a : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) (ha : 0<a) (ham : a≤m) :\n    (orderOf (projectedUnit g m)).Coprime a := by\n  rw [global_order_eq_lcm hp hq hpq,(hlong.2.2.2.2.1).lcm_eq_mul]\n  exact (rough_coprime_small ha ham hlong.2.2.2.2.2.1).mul_left\n    (rough_coprime_small ha ham hlong.2.2.2.2.2.2)\n\n/-- Membership in a cached phase menu keeps the original source residue\nand the exact offset divisibility checked by the emitter. -/\ntheorem phaseSeeds_mem_iff {G : Type*} [CommGroup G] (g : G) (N m j₀ : ℕ)\n    (s : ProgressionSeed G) : s∈phaseSeeds g N m j₀ ↔\n      s∈progressionSeeds g N m ∧ (m : ℤ)∣cachedOffset m s-seedOffset N m j₀ := by\n  simp only [phaseSeeds,List.mem_filter,beq_iff_eq]\n  exact and_congr_right (fun _ => Int.dvd_iff_emod_eq_zero.symm)\n\n/-- The original residue of any cached public descriptor is canonical,\nand the whole descriptor is exactly the source seed at that residue. -/\ntheorem cached_seed_source {G : Type*} [CommGroup G] {g : G} {N m : ℕ}\n    {s : ProgressionSeed G} (hs : s∈progressionSeeds g N m) :\n    1≤s.residue ∧ s.residue<m ∧ s=progressionSeed g N m s.residue := by\n  obtain ⟨r,hr,he⟩ := List.mem_map.mp hs\n  have hb := List.mem_range.mp hr\n  subst s\n  exact ⟨by change 1≤r+1; omega,by change r+1<m; omega,rfl⟩\n\n/-- The arithmetic-only tag emitter checks integral phase and signed\nrange membership, without evaluating any further group powers. -/\ndef predictedTag {G : Type*} (m t₀ : ℕ) (δ₀ z₀ : ℤ)\n    (s : ProgressionSeed G) (r : ℕ) : Option (ℕ×ℕ×ℤ) :=\n  let t := r+1\n  let z := phaseIndex m t t₀ (cachedOffset m s) δ₀ z₀\n  if (t₀ : ℤ)∣(t : ℤ)*z₀ ∧ -4*(m : ℤ)^2≤z ∧ z<2*(m : ℤ)^2\n    then some (s.residue,t,z) else none\n\n/-- After one verified anchor, all predicted global tags are obtained\nfrom at most two cached seeds and one linear denominator stream. -/\ndef predictedGlobalTags {G : Type*} [CommGroup G] (g : G)\n    (N m j₀ t₀ : ℕ) (z₀ : ℤ) : List (ℕ×ℕ×ℤ) :=\n  (phaseSeeds g N m j₀).flatMap fun s =>\n    (List.range (m-1)).filterMap (predictedTag m t₀ (seedOffset N m j₀) z₀ s)\n\n/-- Exact arithmetic characterization of an emitted tag. -/\ntheorem predictedTag_eq_some_iff {G : Type*} (m t₀ : ℕ) (δ₀ z₀ : ℤ)\n    (s : ProgressionSeed G) (r j t : ℕ) (z : ℤ) :\n    predictedTag m t₀ δ₀ z₀ s r=some (j,t,z) ↔\n      j=s.residue ∧ t=r+1 ∧ z=phaseIndex m t t₀ (cachedOffset m s) δ₀ z₀ ∧\n      (t₀ : ℤ)∣(t : ℤ)*z₀ ∧ -4*(m : ℤ)^2≤z ∧ z<2*(m : ℤ)^2 := by\n  unfold predictedTag\n  dsimp only\n  split_ifs with h\n  · constructor\n    · intro he\n      have hp := Option.some.inj he\n      have hj := congrArg Prod.fst hp\n      have ht := congrArg (fun c : ℕ×ℕ×ℤ => c.2.1) hp\n      have hz := congrArg (fun c : ℕ×ℕ×ℤ => c.2.2) hp\n      dsimp only at hj ht hz\n      subst j\n      subst t\n      subst z\n      exact ⟨rfl,rfl,rfl,h.1,h.2⟩\n    · rintro ⟨rfl,rfl,rfl,_,_,_⟩\n      rfl\n  · constructor\n    · intro he\n      cases he\n    · rintro ⟨_,rfl,rfl,hd,hz,hzm⟩\n      exact False.elim (h ⟨hd,hz,hzm⟩)\n\n/-- The entire arithmetic mask has at most 2*(m-1) tags. This is an\ninput-count statement; it does not price anchor acquisition or bit costs. -/\ntheorem predictedGlobalTags_length_le {G : Type*} [CommGroup G] (g : G)\n    {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N) (j₀ t₀ : ℕ) (z₀ : ℤ) :\n    (predictedGlobalTags g N m j₀ t₀ z₀).length≤2*(m-1) := by\n  have hmenu := phaseSeeds_length_le_two g hm hN j₀\n  unfold predictedGlobalTags\n  rw [List.length_flatMap]\n  have hbound : ∀ s∈phaseSeeds g N m j₀,\n      ((List.range (m-1)).filterMap\n        (predictedTag m t₀ (seedOffset N m j₀) z₀ s)).length≤m-1 := by\n    intro s _\n    simpa only [List.length_range] using List.length_filterMap_le _ (List.range (m-1))\n  have hh := List.sum_le_length_nsmul\n    ((phaseSeeds g N m j₀).map fun s =>\n      ((List.range (m-1)).filterMap\n        (predictedTag m t₀ (seedOffset N m j₀) z₀ s)).length) (m-1)\n    (by intro n hn; obtain ⟨s,hs,rfl⟩ := List.mem_map.mp hn; exact hbound s hs)\n  simp only [List.length_map,smul_eq_mul] at hh\n  exact\n    hh.trans (Nat.mul_le_mul_right (m-1) hmenu)\n\n/-- Every arithmetic prediction is a genuine global hit for the routed\nbase. Soundness uses the verified anchor and rough-order cancellation. -/\ntheorem predictedGlobalTags_sound {p q m j₀ t₀ j t : ℕ} {z₀ z : ℤ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hanchor : GlobalHit (projectedUnit g m) (p*q) m j₀ t₀ z₀)\n    (hmem : (j,t,z)∈predictedGlobalTags (projectedUnit g m) (p*q) m j₀ t₀ z₀) :\n    GlobalHit (projectedUnit g m) (p*q) m j t z := by\n  obtain ⟨s,hs,htarget⟩ := List.mem_flatMap.mp hmem\n  obtain ⟨r,hr,he⟩ := List.mem_filterMap.mp htarget\n  have hrm := List.mem_range.mp hr\n  obtain ⟨hjs,htr,hindex,htz,hz,hzm⟩ :=\n    (predictedTag_eq_some_iff _ _ _ _ _ _ _ _ _).mp he\n  have hmenu := (phaseSeeds_mem_iff _ _ _ _ _).mp hs\n  obtain ⟨hsmin,hsm,hseed⟩ := cached_seed_source hmenu.1\n  have hoff : cachedOffset m s=seedOffset (p*q) m j := by\n    rw [hseed,←hjs,cachedOffset_seed]\n  rw [hoff] at hindex\n  have hdiv : (m : ℤ)∣seedOffset (p*q) m j-seedOffset (p*q) m j₀ := by\n    simpa only [hoff] using hmenu.2\n  rcases hanchor with ⟨ht₀,ht₀m,hj₀,hj₀m,_,_,hglobal₀⟩\n  have hc : j.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt\n      (by omega) (by omega : j<m))).symm\n  have hc₀ : j₀.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hj₀m)).symm\n  have hcop := long_global_coprime_small hp hq hpq g hlong ht₀ ht₀m.le\n  have hres := phase_prediction_residual hcop hdiv htz\n    ((hit_residual_iff (projectedUnit g m) hm.pos hc₀ z₀).mp hglobal₀)\n  rw [←hindex] at hres\n  exact ⟨by omega,by omega,by omega,by omega,hz,hzm,\n    (hit_residual_iff (projectedUnit g m) hm.pos hc z).mpr hres⟩\n\n/-- Every verified global hit occurs in the arithmetic mask. This uses\nthe exact short cross residual, including arbitrary false factor-row tags. -/\ntheorem predictedGlobalTags_complete {p q m j₀ t₀ j t : ℕ} {z₀ z : ℤ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hanchor : GlobalHit (projectedUnit g m) (p*q) m j₀ t₀ z₀)\n    (hhit : GlobalHit (projectedUnit g m) (p*q) m j t z) :\n    (j,t,z)∈predictedGlobalTags (projectedUnit g m) (p*q) m j₀ t₀ z₀ := by\n  have hphase := long_global_phase hp hq hpq hm g hlong hhit hanchor\n  rcases hanchor with ⟨ht₀,ht₀m,_,_,_,_,_⟩\n  rcases hhit with ⟨ht,htm,hj,hjm,hz,hzm,_⟩\n  obtain ⟨hdiv,htz,hindex⟩ := phase_index_exact hm ht htm ht₀ ht₀m hphase\n  let s := progressionSeed (projectedUnit g m) (p*q) m j\n  have hs : s∈phaseSeeds (projectedUnit g m) (p*q) m j₀ :=\n    (phaseSeeds_mem_iff _ _ _ _ _).mpr\n      ⟨progressionSeed_mem _ (by omega) hjm,by simpa only [s,cachedOffset_seed] using hdiv⟩\n  apply List.mem_flatMap.mpr\n  refine ⟨s,hs,List.mem_filterMap.mpr ⟨t-1,List.mem_range.mpr (by omega),?_⟩⟩\n  apply (predictedTag_eq_some_iff _ _ _ _ _ _ _ _ _).mpr\n  exact ⟨rfl,by omega,by simpa only [s,cachedOffset_seed] using hindex,htz,hz,hzm⟩\n\n/-- One verified public global tag determines exactly the entire common\nglobal-hit set. The two seed descriptors suffice; expansion is only linear. -/\ntheorem predictedGlobalTags_exact {p q m j₀ t₀ j t : ℕ} {z₀ z : ℤ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hanchor : GlobalHit (projectedUnit g m) (p*q) m j₀ t₀ z₀) :\n    (j,t,z)∈predictedGlobalTags (projectedUnit g m) (p*q) m j₀ t₀ z₀ ↔\n      GlobalHit (projectedUnit g m) (p*q) m j t z :=\n  ⟨predictedGlobalTags_sound hp hq hpq hm g hlong hanchor,\n    predictedGlobalTags_complete hp hq hpq hm g hlong hanchor⟩\n\n/-- A common index returned by the original public interval reader\nsupplies a verified phase anchor, with its exact original signed bounds. -/\ntheorem merged_reader_global_tag {N m j t r : ℕ} (g : (ZMod N)ˣ)\n    (upper : Bool) (ht : 0<t) (htm : t<m) (hj : 1≤j) (hjm : j<m)\n    (hread : recoverTaggedInterval (commonStep g m)\n      (mergedTarget g m t (progressionSeed g N m j) upper)\n      (mergedLength m) (2*m)=some (Sum.inr r)) :\n    GlobalHit g N m j t (mergedStart m upper+r) := by\n  obtain ⟨hr,hvalue⟩ := recoverTaggedInterval_index_sound _ _ hread\n  have hrZ : (r : ℤ)<3*(m : ℤ)^2 := by\n    exact_mod_cast hr\n  have hr₀ : (0 : ℤ)≤r := by positivity\n  have hx : mergedTarget g m t (progressionSeed g N m j) upper=(commonStep g m)^r := by\n    apply Units.ext\n    simpa only [Units.val_pow_eq_pow_val] using hvalue\n  have hglobal : (progressionSeed g N m j).step^t=\n      (commonStep g m)^(mergedStart m upper+r) := by\n    calc\n      (progressionSeed g N m j).step^t=\n          mergedTarget g m t (progressionSeed g N m j) upper*\n            (commonStep g m)^mergedStart m upper := by\n        simp only [mergedTarget,mul_assoc,←zpow_add,neg_add_cancel,zpow_zero,mul_one]\n      _=(commonStep g m)^r*(commonStep g m)^mergedStart m upper := by rw [hx]\n      _=(commonStep g m)^(mergedStart m upper+r) := by\n        rw [←zpow_natCast,←zpow_add]\n        congr 1\n        omega\n  refine ⟨ht,htm,hj,hjm,?_,?_,hglobal⟩\n  · cases upper <;> simp only [mergedStart,Bool.false_eq_true,ite_false,ite_true] <;>\n      nlinarith only [hr₀,sq_nonneg (m : ℤ)]\n  · cases upper <;> simp only [mergedStart,Bool.false_eq_true,ite_false,ite_true] <;>\n      nlinarith only [hrZ,sq_nonneg (m : ℤ)]\n\n/-- On the actual N-only matched-width long route, a public common index\nfrom the unchanged reader determines the exact linear arithmetic mask.\nNeither numerical local order nor a private factor-row tag is an input. -/\ntheorem long_public_route_reader_mask {p q a j₀ t₀ r₀ : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p<q)\n    (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q)\n      (SemiprimeEuclidRowBudget.publicRowModulus (p*q))=none)\n    (hroute : routeAtRowModulus (p*q)=.longBase a) (hc : a.Coprime (p*q))\n    (upper₀ : Bool)\n    (ht₀ : 0<t₀) (ht₀m : t₀<SemiprimeEuclidRowBudget.publicRowModulus (p*q))\n    (hj₀ : 1≤j₀) (hj₀m : j₀<SemiprimeEuclidRowBudget.publicRowModulus (p*q))\n    (hread : let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n      recoverTaggedInterval (commonStep h m)\n        (mergedTarget h m t₀ (progressionSeed h (p*q) m j₀) upper₀)\n        (mergedLength m) (2*m)=some (Sum.inr r₀)) :\n    let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n    let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n    let z₀ := mergedStart m upper₀+r₀\n    (∀ (j t : ℕ) (z : ℤ), (j,t,z)∈predictedGlobalTags h (p*q) m j₀ t₀ z₀ ↔\n      GlobalHit h (p*q) m j t z) ∧\n      (predictedGlobalTags h (p*q) m j₀ t₀ z₀).length≤2*(m-1) := by\n  have hd := routeAtRowModulus_semiprime hp hq hpq hB\n  rw [hroute] at hd\n  obtain ⟨_,hlong⟩ := hd\n  let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n  let g := ZMod.unitOfCoprime a hc\n  have hm := SemiprimeEuclidRowBudget.publicRowModulus_prime (p*q)\n  have hcover := public_modulus_prefix_below_input (Nat.mul_pos hp.pos hq.pos) hB\n  have hcop := SemiprimeStrassenPrefix.prefix_none_coprime_integer hcover hnone hm.pos\n    (by have hh := hm.two_le; nlinarith only [hh] : m≤m^2)\n  have hanchor := merged_reader_global_tag (projectedUnit g m) upper₀\n    ht₀ ht₀m hj₀ hj₀m hread\n  constructor\n  · intro j t z\n    exact predictedGlobalTags_exact hp hq hpq.ne hm g hlong hanchor\n  · exact predictedGlobalTags_length_le _ hm hcop.symm _ _ _\n\nend RiemannGaussian.SemiprimeGlobalPhaseCancellation\n","RiemannGaussian.SemiprimeGroupSelection":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRoughProjection\n\n/-!\n# Certified group selection over a finite menu\n\nSmall-to-large probes select the minimum successful scale in a fixed\ncurve menu, without local orders or factors as advice. The selected GCD\nis a proper divisor. Dyadic covers have a geometric total width bound,\nincluding a final truncated cap. Projective signals commute with ring\nreduction; a checked signal from the nominal 80-bit control is included.\n\nThe finite menu must contain a successful probe for a coverage guarantee.\nThese results do not assert a globally optimal elliptic curve, universal\none-sixth factoring, the full Montgomery group law, or the Python program's\nbit-complexity. This optional side-project module is outside the RH root.\n-/\n\nnamespace RiemannGaussian.SemiprimeGroupSelection\n\n/-- The check performed before returning a recovered divisor. -/\ndef ProperDivisor (n d : ℕ) : Prop := 1 < d ∧ d < n ∧ d ∣ n\n\n/-- A residue supplies a certified factor only when its GCD is proper. -/\ndef checkedSignal (n x : ℕ) : Option ℕ :=\n  if 1 < n.gcd x ∧ n.gcd x < n then some (n.gcd x) else none\n\ntheorem checkedSignal_sound {n x d : ℕ} (h : checkedSignal n x = some d) :\n    ProperDivisor n d := by\n  unfold checkedSignal at h\n  split_ifs at h with hd\n  · cases h\n    exact ⟨hd.1, hd.2, Nat.gcd_dvd_left n x⟩\n\n/-- Curve index, successful cover width, and the certified factor. -/\nstructure Selection where\n  /-- Public identifier of the successful group candidate. -/\n  group : ℕ\n  /-- First successful cover width in the ordered probe schedule. -/\n  width : ℕ\n  /-- Proper divisor certified by the selected residue. -/\n  factor : ℕ\n  deriving DecidableEq\n\n/-- Search the public ordered list of curve/width trials. -/\ndef search (probe : ℕ → ℕ → Option ℕ) : List (ℕ × ℕ) → Option Selection\n  | [] => none\n  | (g, w) :: tail =>\n    match probe g w with\n    | some d => some ⟨g, w, d⟩\n    | none => search probe tail\n\n/-- Cover width actually visited before the first successful probe. -/\ndef searchWidth (probe : ℕ → ℕ → Option ℕ) : List (ℕ × ℕ) → ℕ\n  | [] => 0\n  | (g, w) :: tail =>\n    w + match probe g w with\n    | some _ => 0\n    | none => searchWidth probe tail\n\ntheorem search_append_of_success (probe : ℕ → ℕ → Option ℕ)\n    {earlier : List (ℕ × ℕ)} {result : Selection}\n    (hs : search probe earlier = some result) (suffix : List (ℕ × ℕ)) :\n    search probe (earlier ++ suffix) = some result ∧\n      searchWidth probe (earlier ++ suffix) = searchWidth probe earlier := by\n  induction earlier with\n  | nil => simp [search] at hs\n  | cons head tail ih =>\n    rcases head with ⟨g, w⟩\n    cases hp : probe g w with\n    | some d =>\n      constructor\n      · simpa [search, hp] using hs\n      · simp [searchWidth, hp]\n    | none =>\n      obtain ⟨hsearch, hcost⟩ := ih (by simpa [search, hp] using hs)\n      simpa [search, searchWidth, hp, hcost] using hsearch\n\ntheorem search_sound (probe : ℕ → ℕ → Option ℕ)\n    (hprobe : ∀ g w d, probe g w = some d → ProperDivisor n d)\n    {trials : List (ℕ × ℕ)} {result : Selection}\n    (h : search probe trials = some result) : ProperDivisor n result.factor := by\n  induction trials with\n  | nil => simp [search] at h\n  | cons trial tail ih =>\n    rcases trial with ⟨g, w⟩\n    cases hp : probe g w with\n    | none => exact ih (by simpa [search, hp] using h)\n    | some d =>\n      have he : ({ group := g, width := w, factor := d } : Selection) = result := by\n        simpa [search, hp] using h\n      rw [← he]\n      exact hprobe g w d hp\n\ntheorem search_returns_trial (probe : ℕ → ℕ → Option ℕ)\n    {trials : List (ℕ × ℕ)} {result : Selection}\n    (h : search probe trials = some result) :\n    (result.group, result.width) ∈ trials ∧\n      probe result.group result.width = some result.factor := by\n  induction trials with\n  | nil => simp [search] at h\n  | cons trial tail ih =>\n    rcases trial with ⟨g, w⟩\n    cases hp : probe g w with\n    | none =>\n      obtain ⟨hm, hv⟩ := ih (by simpa [search, hp] using h)\n      exact ⟨List.mem_cons_of_mem _ hm, hv⟩\n    | some d =>\n      have he : ({ group := g, width := w, factor := d } : Selection) = result := by\n        simpa [search, hp] using h\n      rw [← he]\n      exact ⟨by simp, hp⟩\n\ntheorem search_none_iff (probe : ℕ → ℕ → Option ℕ) (trials : List (ℕ × ℕ)) :\n    search probe trials = none ↔ ∀ t ∈ trials, probe t.1 t.2 = none := by\n  induction trials with\n  | nil => simp [search]\n  | cons trial tail ih =>\n    rcases trial with ⟨g, w⟩\n    cases hp : probe g w <;> simp [search, hp, ih]\n\n/-- Coverage is relative to a successful trial in the explicit finite\nmenu. Existence of that trial is not inferred from semiprimality. -/\ntheorem search_succeeds_of_menu_hit (probe : ℕ → ℕ → Option ℕ)\n    {trials : List (ℕ × ℕ)} {g w d : ℕ} (hm : (g, w) ∈ trials)\n    (hh : probe g w = some d) : ∃ result, search probe trials = some result := by\n  cases hs : search probe trials with\n  | some result => exact ⟨result, rfl⟩\n  | none =>\n    have hn := (search_none_iff probe trials).mp hs (g, w) hm\n    rw [hh] at hn\n    contradiction\n\n/-- The first successful probe has minimum scale among all successful\ntrials, provided trials are sorted by scale. This is not minimum runtime\namong all possible curves. -/\ntheorem search_minimum_scale (probe : ℕ → ℕ → Option ℕ)\n    {trials : List (ℕ × ℕ)} {result : Selection}\n    (ho : trials.Pairwise (fun a b => a.2 ≤ b.2))\n    (hs : search probe trials = some result) {g w d : ℕ}\n    (hm : (g, w) ∈ trials) (hh : probe g w = some d) : result.width ≤ w := by\n  induction trials with\n  | nil => simp at hm\n  | cons trial tail ih =>\n    rcases trial with ⟨g₀, w₀⟩\n    obtain ⟨hhead, htail⟩ := List.pairwise_cons.mp ho\n    cases hp : probe g₀ w₀ with\n    | some d₀ =>\n      have he : ({ group := g₀, width := w₀, factor := d₀ } : Selection) = result := by\n        simpa [search, hp] using hs\n      rw [← he]\n      rcases List.mem_cons.mp hm with heq | hm\n      · cases heq\n        exact le_rfl\n      · exact hhead (g, w) hm\n    | none =>\n      have hmem : (g, w) ∈ tail := by\n        rcases List.mem_cons.mp hm with heq | hmem\n        · cases heq\n          rw [hh] at hp\n          contradiction\n        · exact hmem\n      exact ih htail (by simpa [search, hp] using hs) hmem\n\n/-- Every curve is probed at one width before advancing the width. -/\ndef trials (groups widths : List ℕ) : List (ℕ × ℕ) :=\n  widths.flatMap fun w => groups.map fun g => (g, w)\n\ntheorem mem_trials {groups widths : List ℕ} {g w : ℕ} :\n    (g, w) ∈ trials groups widths ↔ g ∈ groups ∧ w ∈ widths := by\n  simp only [trials, List.mem_flatMap, List.mem_map]\n  constructor\n  · rintro ⟨w', hw', g', hg', he⟩\n    cases he\n    exact ⟨hg', hw'⟩\n  · rintro ⟨hg, hw⟩\n    exact ⟨w, hw, g, hg, rfl⟩\n\ntheorem trials_ordered (groups : List ℕ) {widths : List ℕ}\n    (ho : widths.Pairwise (· ≤ ·)) :\n    (trials groups widths).Pairwise (fun a b => a.2 ≤ b.2) := by\n  induction widths with\n  | nil => simp [trials]\n  | cons w widths ih =>\n    obtain ⟨hfirst, hrest⟩ := List.pairwise_cons.mp ho\n    rw [trials, List.flatMap_cons]\n    apply List.pairwise_append.mpr\n    refine ⟨?_, ih hrest, ?_⟩\n    · exact List.pairwise_map.mpr (List.pairwise_of_forall (by simp))\n    · intro a ha b hb\n      obtain ⟨g, hg, rfl⟩ := List.mem_map.mp ha\n      have hmem := (mem_trials.mp hb).2\n      exact hfirst b.2 hmem\n\n/-- Exact total cover width; scalar-bit and polynomial-operation counters\nare separately charged by the implementation. -/\ndef coverWidth (ts : List (ℕ × ℕ)) : ℕ := (ts.map Prod.snd).sum\n\ntheorem searchWidth_le_coverWidth (probe : ℕ → ℕ → Option ℕ)\n    (ts : List (ℕ × ℕ)) : searchWidth probe ts ≤ coverWidth ts := by\n  induction ts with\n  | nil => simp [searchWidth, coverWidth]\n  | cons head tail ih =>\n    rcases head with ⟨g, w⟩\n    change searchWidth probe tail ≤ (tail.map Prod.snd).sum at ih\n    cases hp : probe g w with\n    | some d => simp [searchWidth, coverWidth, hp]\n    | none => simpa [searchWidth, coverWidth, hp] using ih\n\ntheorem coverWidth_trials (groups widths : List ℕ) :\n    coverWidth (trials groups widths) = groups.length * widths.sum := by\n  induction widths with\n  | nil => simp [coverWidth, trials]\n  | cons w widths ih =>\n    simp only [trials, List.flatMap_cons, coverWidth, List.map_append, List.sum_append] at *\n    rw [ih]\n    simp [List.map_map, Function.comp_def, Nat.mul_add, Nat.mul_comm]\n\n/-- Untruncated dyadic stages up to and including index k. -/\ndef dyadicWidths (b k : ℕ) : List ℕ :=\n  (List.range (k+1)).map fun i => b*2^i\n\ntheorem dyadicWidths_ordered (b k : ℕ) : (dyadicWidths b k).Pairwise (· ≤ ·) := by\n  apply List.pairwise_map.mpr\n  apply List.Pairwise.imp _ List.pairwise_lt_range\n  intro i j hij\n  exact Nat.mul_le_mul_left b (Nat.pow_le_pow_right (by decide) hij.le)\n\ntheorem dyadic_sum_exact (b k : ℕ) :\n    (dyadicWidths b k).sum + b = 2*(b*2^k) := by\n  induction k with\n  | zero => simp [dyadicWidths, two_mul]\n  | succ k ih =>\n    have he : dyadicWidths b (k+1) = dyadicWidths b k ++ [b*2^(k+1)] := by\n      simp [dyadicWidths, List.range_succ]\n    rw [he, List.sum_append]\n    simp only [List.sum_cons, List.sum_nil, add_zero]\n    rw [pow_succ]\n    nlinarith\n\ntheorem dyadic_coverWidth_bound (groups : List ℕ) (b k : ℕ) :\n    coverWidth (trials groups (dyadicWidths b k)) ≤\n      2*groups.length*(b*2^k) := by\n  rw [coverWidth_trials]\n  have hs := dyadic_sum_exact b k\n  nlinarith\n\n/-- The final exact cap may follow a smaller dyadic stage. Its entire\ncover-width cost is at most three menu sizes times that cap. -/\ntheorem capped_coverWidth_bound (groups : List ℕ) (b k cap : ℕ)\n    (hc : b*2^k ≤ cap) :\n    coverWidth (trials groups (dyadicWidths b k ++ [cap])) ≤\n      3*groups.length*cap := by\n  rw [coverWidth_trials, List.sum_append]\n  simp only [List.sum_cons, List.sum_nil, add_zero]\n  have hs := dyadic_sum_exact b k\n  have hsum : (dyadicWidths b k).sum + cap ≤ 3*cap := by omega\n  exact (Nat.mul_le_mul_left groups.length hsum).trans_eq (by ring)\n\n/-- Returning a GCD never needs to assume that either hidden group order\nis smooth. The signal itself certifies a proper divisor. -/\ntheorem tournament_sound (n : ℕ) (signal : ℕ → ℕ → ℕ)\n    {groups widths : List ℕ} {result : Selection}\n    (hs : search (fun g w => checkedSignal n (signal g w))\n      (trials groups widths) = some result) : ProperDivisor n result.factor :=\n  search_sound _ (fun _ _ _ h => checkedSignal_sound h) hs\n\n/-- If one candidate succeeds at a dyadic width, the full tournament\nreturns a certified factor without examining later stages. Its visited\ncover width is at most twice the menu size times that candidate's width.\nThe assumption is an actual GCD probe hit, not hidden smoothness advice. -/\ntheorem dyadic_tournament_guarantee (n : ℕ) (signal : ℕ → ℕ → ℕ)\n    (groups : List ℕ) (b k : ℕ) (suffix : List (ℕ × ℕ))\n    {g d : ℕ} (hg : g ∈ groups)\n    (hh : checkedSignal n (signal g (b*2^k)) = some d) :\n    ∃ result,\n      search (fun g w => checkedSignal n (signal g w))\n        (trials groups (dyadicWidths b k) ++ suffix) = some result ∧\n      ProperDivisor n result.factor ∧ result.width ≤ b*2^k ∧\n      searchWidth (fun g w => checkedSignal n (signal g w))\n        (trials groups (dyadicWidths b k) ++ suffix) ≤\n          2*groups.length*(b*2^k) := by\n  let probe := fun g w => checkedSignal n (signal g w)\n  have hm : (g, b*2^k) ∈ trials groups (dyadicWidths b k) := by\n    apply mem_trials.mpr\n    refine ⟨hg, ?_⟩\n    apply List.mem_map.mpr\n    exact ⟨k, List.mem_range.mpr (by omega), rfl⟩\n  obtain ⟨result, hs⟩ := search_succeeds_of_menu_hit probe hm hh\n  have happend := search_append_of_success probe hs suffix\n  refine ⟨result, happend.1, tournament_sound n signal hs, ?_, ?_⟩\n  · exact search_minimum_scale probe (trials_ordered groups (dyadicWidths_ordered b k))\n      hs hm hh\n  · rw [happend.2]\n    exact (searchWidth_le_coverWidth probe _).trans (dyadic_coverWidth_bound groups b k)\n\n/-- Cross multiplication retains a projective collision without affine\ndivision over the composite ring. -/\ndef projectiveSignal {R : Type*} [CommRing R] (a b : R × R) : R :=\n  a.1*b.2-b.1*a.2\n\ntheorem projectiveSignal_map {R S : Type*} [CommRing R] [CommRing S]\n    (f : R →+* S) (a b : R × R) :\n    f (projectiveSignal a b) =\n      projectiveSignal (f a.1, f a.2) (f b.1, f b.2) := by\n  simp [projectiveSignal]\n\n/-- Exact polynomial doubling formula used by the public curve probes. -/\ndef montgomeryDouble {R : Type*} [CommRing R] (a24 : R) (p : R × R) : R × R :=\n  let a := (p.1+p.2)^2\n  let b := (p.1-p.2)^2\n  let c := a-b\n  (a*b, c*(b+a24*c))\n\ntheorem montgomeryDouble_map {R S : Type*} [CommRing R] [CommRing S]\n    (f : R →+* S) (a24 : R) (p : R × R) :\n    (f (montgomeryDouble a24 p).1, f (montgomeryDouble a24 p).2) =\n      montgomeryDouble (f a24) (f p.1, f p.2) := by\n  simp [montgomeryDouble]\n\n/-- Differential addition is polynomial, with the difference point retained. -/\ndef montgomeryAdd {R : Type*} [CommRing R] (p q difference : R × R) : R × R :=\n  let a := (p.1+p.2)*(q.1-q.2)\n  let b := (p.1-p.2)*(q.1+q.2)\n  (difference.2*(a+b)^2, difference.1*(a-b)^2)\n\ntheorem montgomeryAdd_map {R S : Type*} [CommRing R] [CommRing S]\n    (f : R →+* S) (p q difference : R × R) :\n    (f (montgomeryAdd p q difference).1, f (montgomeryAdd p q difference).2) =\n      montgomeryAdd (f p.1, f p.2) (f q.1, f q.2) (f difference.1, f difference.2) := by\n  simp [montgomeryAdd]\n\ntheorem affine_eq_iff_projectiveSignal_zero {F : Type*} [Field F]\n    {a b : F × F} (ha : a.2 ≠ 0) (hb : b.2 ≠ 0) :\n    a.1/a.2 = b.1/b.2 ↔ projectiveSignal a b = 0 := by\n  rw [div_eq_div_iff ha hb]\n  exact sub_eq_zero.symm\n\n/-- Arithmetic certificate produced by the public adaptive run on the\nfour-rough control, at sigma=6 and cover width 256. This checks the GCD\nand factor, not an oracle-supplied curve-order assertion. -/\ntheorem four_rough_control_factor_certificate :\n    checkedSignal 477209897193541203289441 474427418761119040057631 =\n      some 661911275027 := by\n  norm_num [checkedSignal]\n\ntheorem four_rough_control_proper_divisor :\n    ProperDivisor 477209897193541203289441 661911275027 :=\n  checkedSignal_sound four_rough_control_factor_certificate\n\nend RiemannGaussian.SemiprimeGroupSelection\n","RiemannGaussian.SemiprimeIndexIntegrality":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePartnerRecoveryObstruction\nimport Mathlib.RingTheory.Int.Basic\n\n/-!\n# Exact residue information in the original row's integral index\n\nFor an actual public packet and prime auxiliary modulus, m² divides the\nfactor sum exactly when the factor has the packet's residue modulo m.\nEvery same-residue row therefore has the same bare index-integrality\ncondition, and rows of distinct residues cannot simultaneously have\nintegral indices for one factor orientation. The factor pair is integral\nand satisfies N=p*q throughout; this does not rule out using integrality\nto search for that pair, or using bounds on the actual index values.\n-/\n\nnamespace RiemannGaussian.SemiprimeIndexIntegrality\n\nopen SemiprimeQuotientRows SemiprimeQuotientCentering SemiprimeEuclidRowFamily\nopen SemiprimeCompanionRows SemiprimeCompanionCenterSpectrum SemiprimeAffineRowRoots\nopen SemiprimeCenteredOffsetExtractor SemiprimeQuadraticPointJets\nopen SemiprimeLiteralQuadraticRoots SemiprimePartnerRecoveryObstruction\n\n/-- The auxiliary leading unit descends from m² to the prime modulus m. -/\ntheorem publicPacket_leading_auxiliary_unit {N m : ℕ} (hm : m.Prime)\n    {w : FamilyPacket} (hw : w∈publicPackets N m) : IsUnit (w.original.a : ZMod m) := by\n  have hd : m∣m^2 := by rw [pow_two]; exact dvd_mul_right m m\n  simpa only [map_intCast] using\n    (publicPacket_auxiliary_leading_unit hm hw).map (ZMod.castHom hd (ZMod m))\n\n/-- The actual numerator cannot absorb a factor of the auxiliary prime. -/\ntheorem publicPacket_leading_not_auxiliary_dvd {N m : ℕ} (hm : m.Prime)\n    {w : FamilyPacket} (hw : w∈publicPackets N m) : ¬(m : ℤ)∣w.original.a := by\n  let : Fact m.Prime := ⟨hm⟩\n  intro hd\n  have hz := (ZMod.intCast_zmod_eq_zero_iff_dvd w.original.a m).mpr hd\n  exact (publicPacket_leading_auxiliary_unit hm hw).ne_zero hz\n\n/-- Keep the square displacement and the entire centered quadratic before\ntesting index integrality; N=p*q is used as an integer identity. -/\ntheorem publicPacket_factor_sum_square {p q m : ℕ} (hm : 0<m)\n    {w : FamilyPacket} (hw : w∈publicPackets (p*q) m) :\n    (p : ℤ)*factorSum m w p q=\n      w.original.a*((p : ℤ)-w.residue)^2+\n        (m : ℤ)*(centeredPacketRow m w).b*((p : ℤ)-w.residue)+\n          (m : ℤ)^2*(centeredPacketRow m w).c := by\n  have he := publicPacket_relation hm hw\n  simp only [quotientRelation,centeredPacketRow,shiftRow,Nat.cast_mul] at he\n  simp only [factorSum,packetOffset,centeredPacketRow,shiftRow]\n  linear_combination -he\n\n/-- The m² denominator supplies precisely the original m-residue condition\non integral factor pairs, rather than an additional residue digit. -/\ntheorem publicPacket_index_integrality_iff_residue {p q m : ℕ}\n    (hm : m.Prime) (hp : 0<p) {w : FamilyPacket}\n    (hw : w∈publicPackets (p*q) m) :\n    (m : ℤ)^2∣factorSum m w p q ↔ p%m=w.residue := by\n  constructor\n  · intro hd\n    obtain ⟨z,hz⟩ := hd\n    have he := publicPacket_factor_sum_square hm.pos hw\n    have hda : (m : ℤ)∣w.original.a*((p : ℤ)-w.residue)^2 := by\n      refine ⟨(m : ℤ)*p*z-(centeredPacketRow m w).b*((p : ℤ)-w.residue)-\n        (m : ℤ)*(centeredPacketRow m w).c,?_⟩\n      linear_combination -he+(p : ℤ)*hz\n    have hdp : (m : ℤ)∣(p : ℤ)-w.residue := by\n      rcases Int.Prime.dvd_mul' hm hda with ha|hsquare\n      · exact False.elim (publicPacket_leading_not_auxiliary_dvd hm hw ha)\n      · exact Int.Prime.dvd_pow' hm hsquare\n    have hmod : w.residue ≡ p [MOD m] :=\n      Int.natCast_modEq_iff.mp (Int.modEq_of_dvd hdp)\n    change w.residue%m=p%m at hmod\n    rw [Nat.mod_eq_of_lt (publicPacket_residue_lt hw)] at hmod\n    exact hmod.symm\n  · intro hj\n    obtain ⟨i,hi,_⟩ := publicPacket_factor_index hm.pos hp hw hj.symm\n    exact ⟨i,hi.symm⟩\n\n/-- An integral collision index exists exactly in the factor's residue class.\nNo index bound or public acquisition of the factor is asserted. -/\ntheorem publicPacket_integer_index_iff_residue {p q m : ℕ}\n    (hm : m.Prime) (hp : 0<p) {w : FamilyPacket}\n    (hw : w∈publicPackets (p*q) m) :\n    (∃ i : ℤ, (m : ℤ)^2*i=factorSum m w p q) ↔ p%m=w.residue := by\n  constructor\n  · rintro ⟨i,hi⟩\n    exact (publicPacket_index_integrality_iff_residue hm hp hw).mp ⟨i,hi.symm⟩\n  · intro hj\n    obtain ⟨i,hi,_⟩ := publicPacket_factor_index hm.pos hp hw hj.symm\n    exact ⟨i,hi⟩\n\n/-- Adding other original rows and centers at the same residue supplies\nthe same bare integrality test, independently of their coefficient values. -/\ntheorem publicPacket_same_residue_integrality_iff {p q m : ℕ}\n    (hm : m.Prime) (hp : 0<p) {u v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hres : u.residue=v.residue) :\n    (m : ℤ)^2∣factorSum m u p q ↔ (m : ℤ)^2∣factorSum m v p q := by\n  rw [publicPacket_index_integrality_iff_residue hm hp hu,\n    publicPacket_index_integrality_iff_residue hm hp hv,hres]\n\n/-- A useful cross-residue incidence cannot be explained by assigning\nintegral physical indices to both rows in this one factor orientation. -/\ntheorem publicPacket_distinct_residue_no_joint_integer_indices {p q m : ℕ}\n    (hm : m.Prime) (hp : 0<p) {u v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hres : u.residue≠v.residue) :\n    ¬∃ i k : ℤ, (m : ℤ)^2*i=factorSum m u p q ∧\n      (m : ℤ)^2*k=factorSum m v p q := by\n  rintro ⟨i,k,hi,hk⟩\n  have hju := (publicPacket_integer_index_iff_residue hm hp hu).mp ⟨i,hi⟩\n  have hjv := (publicPacket_integer_index_iff_residue hm hp hv).mp ⟨k,hk⟩\n  exact hres (hju.symm.trans hjv)\n\nend RiemannGaussian.SemiprimeIndexIntegrality\n","RiemannGaussian.SemiprimeLocalArrayFrontend":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeArrayOps\nimport RiemannGaussian.SemiprimeLocalPrefixHeight\n\n/-!\n# Executed local Taylor and multilinear frontend\n\nHorner composition uses cached jet operations rather than coefficient advice or\nan uncharged binomial supplier. The local evaluator is a depth-first traversal\nwith an explicit paid integer table callback at each leaf.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeLocalArrayFrontend\nopen scoped BigOperators\nopen Polynomial\nopen SemiprimeJetArray SemiprimeJetRecurrence SemiprimeJetArrayHeight\nopen SemiprimeArrayOps SemiprimeStreamingTensor\n\n/-- Actual integer-valued local predicate callback and its reported work. -/\nstructure EntryReport where\n  /-- Native integer table value. -/\n  value : ℤ\n  /-- Charged scalar/backend operations in the callback. -/\n  arithmetic : ℕ\n  /-- Charged callback reads. -/\n  reads : ℕ\n\n/-- Actual depth-first local interpolation. No truth-table list is an input. -/\ndef localEvaluate (J : ℕ) : (w : ℕ) → ((Fin w → Bool) → EntryReport) →\n    (Fin w → Array ℚ) → InverseReport\n  | 0, T, _ =>\n      let entry := T Fin.elim0\n      let out := scaleJet (oneJet J).coefficients (entry.value : ℚ) J\n      ⟨out.coefficients, entry.arithmetic + out.arithmetic, entry.reads + out.reads⟩\n  | w + 1, T, inputs =>\n      let lo := localEvaluate J w (fun eta => T (Fin.cons false eta)) (fun i => inputs i.succ)\n      let hi := localEvaluate J w (fun eta => T (Fin.cons true eta)) (fun i => inputs i.succ)\n      let neg := scaleJet (inputs 0) (-1) J\n      let no := addJet (oneJet J).coefficients neg.coefficients J\n      let left := multiply no.coefficients lo.coefficients J\n      let right := multiply (inputs 0) hi.coefficients J\n      let out := addJet left.coefficients right.coefficients J\n      ⟨out.coefficients, lo.arithmetic + hi.arithmetic + neg.arithmetic + no.arithmetic +\n        left.arithmetic + right.arithmetic + out.arithmetic,\n        lo.reads + hi.reads + neg.reads + no.reads + left.reads + right.reads + out.reads⟩\n\ntheorem oneJet_spec (J i : ℕ) (hi : i < J) :\n    coefficient (oneJet J).coefficients i = (1 : Polynomial ℚ).coeff i := by\n  rw [oneJet_coefficient J i hi]\n  simp only [coeff_one]\n\n/-- Actual local array value equals native multilinear interpolation under any\nlow-coefficient port specifications. -/\ntheorem localEvaluate_correct (J w : ℕ) (T : (Fin w → Bool) → EntryReport)\n    (inputs : Fin w → Array ℚ) (ports : Fin w → Polynomial ℚ)\n    (hinputs : ∀ v i, i < J → coefficient (inputs v) i = (ports v).coeff i) :\n    asPolynomial (localEvaluate J w T inputs).coefficients =\n      evaluate w (fun eta => C ((T eta).value : ℚ)) ports %ₘ X ^ J := by\n  induction w with\n  | zero =>\n    change asPolynomial (scaleJet (oneJet J).coefficients ((T Fin.elim0).value : ℚ) J).coefficients = _\n    simpa only [evaluate, mul_one] using\n      scaleJet_correct (oneJet J).coefficients ((T Fin.elim0).value : ℚ) J 1 (oneJet_spec J)\n  | succ w ih =>\n    let lo := localEvaluate J w (fun eta => T (Fin.cons false eta)) (fun i => inputs i.succ)\n    let hi := localEvaluate J w (fun eta => T (Fin.cons true eta)) (fun i => inputs i.succ)\n    let L := evaluate w (fun eta => C ((T (Fin.cons false eta)).value : ℚ)) (fun i => ports i.succ)\n    let H := evaluate w (fun eta => C ((T (Fin.cons true eta)).value : ℚ)) (fun i => ports i.succ)\n    have hlo : asPolynomial lo.coefficients = L %ₘ X ^ J :=\n      ih _ _ _ (fun v i h => hinputs v.succ i h)\n    have hhi : asPolynomial hi.coefficients = H %ₘ X ^ J :=\n      ih _ _ _ (fun v i h => hinputs v.succ i h)\n    let neg := scaleJet (inputs 0) (-1) J\n    let no := addJet (oneJet J).coefficients neg.coefficients J\n    have hneg : asPolynomial neg.coefficients = (C (-1) * ports 0) %ₘ X ^ J :=\n      scaleJet_correct _ _ _ _ (hinputs 0)\n    have hno : asPolynomial no.coefficients = (1 - ports 0) %ₘ X ^ J := by\n      have h := addJet_correct (oneJet J).coefficients neg.coefficients J 1 (C (-1) * ports 0)\n        (oneJet_spec J) (specification_of_asPolynomial _ _ _ hneg)\n      convert h using 1\n      congr 1\n      simp only [C_neg, C_1, neg_mul]\n      ring\n    let left := multiply no.coefficients lo.coefficients J\n    let right := multiply (inputs 0) hi.coefficients J\n    have hleft : asPolynomial left.coefficients = ((1 - ports 0) * L) %ₘ X ^ J :=\n      multiply_correct _ _ _ _ _ (specification_of_asPolynomial _ _ _ hno)\n        (specification_of_asPolynomial _ _ _ hlo)\n    have hright : asPolynomial right.coefficients = (ports 0 * H) %ₘ X ^ J :=\n      multiply_correct _ _ _ _ _ (hinputs 0) (specification_of_asPolynomial _ _ _ hhi)\n    change asPolynomial (addJet left.coefficients right.coefficients J).coefficients = _\n    exact addJet_correct _ _ _ _ _ (specification_of_asPolynomial _ _ _ hleft)\n      (specification_of_asPolynomial _ _ _ hright)\n\n/-- Per-node rational arithmetic/read overhead, before callback work. -/\ndef localOverhead (J : ℕ) : ℕ := 2 * (J * (J + 1)) + 5 * J\n\n/-- Callback work is charged at every actual leaf; no truth-table oracle cost is omitted. -/\ntheorem localEvaluate_work (J w A : ℕ) (T : (Fin w → Bool) → EntryReport)\n    (inputs : Fin w → Array ℚ)\n    (hT : ∀ eta, (T eta).arithmetic ≤ A ∧ (T eta).reads ≤ A) :\n    (localEvaluate J w T inputs).arithmetic ≤ 2 ^ w * (A + (w + 1) * localOverhead J + J) ∧\n      (localEvaluate J w T inputs).reads ≤ 2 ^ w * (A + (w + 1) * localOverhead J + J) := by\n  induction w with\n  | zero =>\n    have h := hT Fin.elim0\n    dsimp only [localEvaluate, scaleJet]\n    simp only [pow_zero, one_mul, Nat.zero_add]\n    constructor <;> omega\n  | succ w ih =>\n    have hl := ih (fun eta => T (Fin.cons false eta)) (fun i => inputs i.succ)\n      (fun eta => hT (Fin.cons false eta))\n    have hh := ih (fun eta => T (Fin.cons true eta)) (fun i => inputs i.succ)\n      (fun eta => hT (Fin.cons true eta))\n    dsimp only [localEvaluate]\n    simp only [scaleJet, addJet, multiply_work]\n    have hp : 1 ≤ 2 ^ w := Nat.one_le_pow _ _ (by decide)\n    have hs : localOverhead J ≤ 2 ^ w * 2 * localOverhead J := by\n      have h := Nat.mul_le_mul_right (localOverhead J) (show 1 ≤ 2 ^ w * 2 by omega)\n      simpa only [one_mul] using h\n    unfold localOverhead at hl hh hs ⊢\n    rw [pow_succ]\n    constructor <;> nlinarith [hl.1, hl.2, hh.1, hh.2, hs]\n\n/-- Source polynomial described by a finite coefficient-array tail. -/\nnoncomputable def sourceTail (a : Array ℚ) (start len : ℕ) : Polynomial ℚ :=\n  ∑ i ∈ Finset.range len, C (coefficient a (start + i)) * X ^ i\n\n/-- Executed Horner shift by the integer/rational node, with cached multiplication. -/\ndef shiftFrom (a : Array ℚ) (t : ℚ) (J : ℕ) : ℕ → ℕ → InverseReport\n  | _, 0 => zeroJet J\n  | start, len + 1 =>\n      let old := shiftFrom a t J (start + 1) len\n      let product := multiply old.coefficients #[t, 1] J\n      let constant := scaleJet (oneJet J).coefficients (coefficient a start) J\n      let out := addJet constant.coefficients product.coefficients J\n      ⟨out.coefficients, old.arithmetic + product.arithmetic + constant.arithmetic + out.arithmetic,\n        old.reads + product.reads + constant.reads + out.reads + 1⟩\n\ntheorem sourceTail_succ (a : Array ℚ) (start len : ℕ) :\n    sourceTail a start (len + 1) = C (coefficient a start) + X * sourceTail a (start + 1) len := by\n  unfold sourceTail\n  rw [Finset.sum_range_succ']\n  simp only [Nat.add_zero, pow_zero, mul_one, Finset.mul_sum]\n  rw [add_comm]\n  congr 1\n  apply Finset.sum_congr rfl\n  intro i _\n  rw [show start + (i + 1) = start + 1 + i by omega, pow_succ]\n  ring\n\ntheorem shiftLinear_polynomial (t : ℚ) : asPolynomial #[t, 1] = C t + X := by\n  simp [asPolynomial, jetPolynomial, coefficient, Finset.sum_range_succ]\n  rw [← C_mul_X_eq_monomial, C_1, one_mul]\n\n/-- Every actually computed Horner suffix is the finite shifted source tail. -/\ntheorem shiftFrom_correct (a : Array ℚ) (t : ℚ) (J start len : ℕ) :\n    asPolynomial (shiftFrom a t J start len).coefficients = taylor t (sourceTail a start len) %ₘ X ^ J := by\n  induction len generalizing start with\n  | zero => simp [shiftFrom, sourceTail, zeroJet_correct]\n  | succ len ih =>\n    let old := shiftFrom a t J (start + 1) len\n    let product := multiply old.coefficients #[t, 1] J\n    let constant := scaleJet (oneJet J).coefficients (coefficient a start) J\n    have ho : asPolynomial old.coefficients = taylor t (sourceTail a (start + 1) len) %ₘ X ^ J := ih _\n    have hp : asPolynomial product.coefficients =\n        (taylor t (sourceTail a (start + 1) len) * (C t + X)) %ₘ X ^ J := by\n      apply multiply_correct\n      · exact specification_of_asPolynomial _ _ _ ho\n      · intro i _\n        rw [← asPolynomial_coeff, shiftLinear_polynomial]\n    have hc : asPolynomial constant.coefficients = C (coefficient a start) %ₘ X ^ J := by\n      simpa only [mul_one] using scaleJet_correct (oneJet J).coefficients\n        (coefficient a start) J 1 (oneJet_spec J)\n    have he : taylor t (sourceTail a start (len + 1)) = C (coefficient a start) +\n        taylor t (sourceTail a (start + 1) len) * (C t + X) := by\n      rw [sourceTail_succ, map_add, taylor_C, taylor_mul, taylor_X]\n      ring\n    rw [he]\n    change asPolynomial (addJet constant.coefficients product.coefficients J).coefficients = _\n    exact addJet_correct _ _ _ _ _ (specification_of_asPolynomial _ _ _ hc)\n      (specification_of_asPolynomial _ _ _ hp)\n\ntheorem shiftFrom_work (a : Array ℚ) (t : ℚ) (J start len : ℕ) :\n    (shiftFrom a t J start len).arithmetic = len * (J * (J + 1) + 2 * J) ∧\n      (shiftFrom a t J start len).reads = len * (J * (J + 1) + 3 * J + 1) := by\n  induction len generalizing start with\n  | zero => simp [shiftFrom, zeroJet]\n  | succ len ih =>\n    simp only [shiftFrom, scaleJet, addJet, multiply_work, ih]\n    constructor <;> ring\n\n/-- The complete supplied source row is shifted, with no requested Taylor value assumed. -/\ntheorem sourceTail_eq (a : Array ℚ) (P : Polynomial ℚ) (R : ℕ)\n    (hP : P.natDegree ≤ R) (ha : ∀ i ≤ R, coefficient a i = P.coeff i) :\n    sourceTail a 0 (R + 1) = P := by\n  rw [sourceTail, P.as_sum_range' (R + 1) (by omega)]\n  apply Finset.sum_congr rfl\n  intro i hi\n  rw [Nat.zero_add, ha i (by have := Finset.mem_range.mp hi; omega), C_mul_X_pow_eq_monomial]\n\n/-- Executable row Taylor supplier from concrete source coefficient arrays. -/\ndef shiftRow (a : Array ℚ) (t : ℚ) (R J : ℕ) : InverseReport := shiftFrom a t J 0 (R + 1)\n\ntheorem shiftRow_correct (a : Array ℚ) (t : ℚ) (R J : ℕ) (P : Polynomial ℚ)\n    (hP : P.natDegree ≤ R) (ha : ∀ i ≤ R, coefficient a i = P.coeff i) :\n    asPolynomial (shiftRow a t R J).coefficients = taylor t P %ₘ X ^ J := by\n  rw [shiftRow, shiftFrom_correct, sourceTail_eq a P R hP ha]\n\n/-- Copy the degree-zero Boolean base and independent positive-degree correction. -/\ndef maskShift (a : Array ℚ) (base correction : Bool) (J : ℕ) : InverseReport :=\n  ⟨Array.ofFn (fun k : Fin J => if k.val = 0 then\n      if base then coefficient a 0 else 0 else if correction then coefficient a k.val else 0), 0, J⟩\n\ntheorem maskShift_coefficient (a : Array ℚ) (base correction : Bool) (J i : ℕ) (hi : i < J) :\n    coefficient (maskShift a base correction J).coefficients i =\n      if i = 0 then (if base then coefficient a 0 else 0) else\n        (if correction then coefficient a i else 0) := ofFn_coefficient _ _ hi\n\n/-- Streamed acquisition of a corrected input port, charging every row shift. -/\ndef acquireCorrected (source : ℕ → Array ℚ) (t : ℚ) (R J : ℕ)\n    (base correction : ℕ → Bool) : ℕ → InverseReport\n  | 0 => zeroJet J\n  | n + 1 =>\n      let old := acquireCorrected source t R J base correction n\n      let row := shiftRow (source n) t R J\n      let masked := maskShift row.coefficients (base n) (correction n) J\n      let out := addJet old.coefficients masked.coefficients J\n      ⟨out.coefficients, old.arithmetic + row.arithmetic + masked.arithmetic + out.arithmetic,\n        old.reads + row.reads + masked.reads + out.reads⟩\n\n/-- One row's independent Boolean base/correction contribution. -/\nnoncomputable def maskedPolynomial (P : Polynomial ℚ) (t : ℚ) (base correction : Bool) : Polynomial ℚ :=\n  C (if base then P.eval t else 0) + if correction then taylor t P - C (P.eval t) else 0\n\ntheorem maskedPolynomial_coefficient (P : Polynomial ℚ) (t : ℚ) (base correction : Bool) (i : ℕ) :\n    (maskedPolynomial P t base correction).coeff i =\n      if i = 0 then (if base then (taylor t P).coeff 0 else 0) else\n        (if correction then (taylor t P).coeff i else 0) := by\n  cases i with\n  | zero => cases base <;> cases correction <;> simp [maskedPolynomial, taylor_coeff_zero]\n  | succ i => cases base <;> cases correction <;> simp [maskedPolynomial]\n\ntheorem acquireCorrected_coefficient (source : ℕ → Array ℚ) (P : ℕ → Polynomial ℚ)\n    (t : ℚ) (R J n : ℕ) (base correction : ℕ → Bool)\n    (hP : ∀ v < n, (P v).natDegree ≤ R)\n    (hs : ∀ v < n, ∀ k ≤ R, coefficient (source v) k = (P v).coeff k)\n    (i : ℕ) (hi : i < J) :\n    coefficient (acquireCorrected source t R J base correction n).coefficients i =\n      if i = 0 then ∑ v ∈ Finset.range n, if base v then (taylor t (P v)).coeff 0 else 0\n      else ∑ v ∈ Finset.range n, if correction v then (taylor t (P v)).coeff i else 0 := by\n  induction n with\n  | zero => simp [acquireCorrected, zeroJet_coefficient]\n  | succ n ih =>\n    have hold := ih (fun v hv => hP v (by omega)) (fun v hv => hs v (by omega))\n    have hrow := shiftRow_correct (source n) t R J (P n) (hP n (by omega)) (hs n (by omega))\n    have hr (k : ℕ) (hk : k < J) := specification_of_asPolynomial _ _ _ hrow k hk\n    change coefficient (addJet (acquireCorrected source t R J base correction n).coefficients\n      (maskShift (shiftRow (source n) t R J).coefficients (base n) (correction n) J).coefficients J).coefficients i = _\n    rw [addJet_coefficient _ _ J i hi, hold, maskShift_coefficient _ _ _ J i hi,\n      hr i hi, hr 0 (by omega)]\n    by_cases hz : i = 0 <;> simp [hz, Finset.sum_range_succ]\n\n/-- Complete corrected-input acquisition from SOURCE coefficient arrays, not requested Taylor values. -/\ntheorem acquireCorrected_correct (source : ℕ → Array ℚ) (P : ℕ → Polynomial ℚ)\n    (t : ℚ) (R J n : ℕ) (base correction : ℕ → Bool)\n    (hP : ∀ v < n, (P v).natDegree ≤ R)\n    (hs : ∀ v < n, ∀ k ≤ R, coefficient (source v) k = (P v).coeff k) :\n    asPolynomial (acquireCorrected source t R J base correction n).coefficients =\n      (∑ v ∈ Finset.range n, maskedPolynomial (P v) t (base v) (correction v)) %ₘ X ^ J := by\n  have hsize : (acquireCorrected source t R J base correction n).coefficients.size = J := by\n    cases n <;> simp [acquireCorrected, zeroJet_size, addJet_size]\n  ext k\n  rw [asPolynomial_coeff, coeff_mod_X_pow]\n  by_cases hk : k < J\n  · rw [ite_eq_left hk, acquireCorrected_coefficient source P t R J n base correction hP hs k hk,\n      Polynomial.finsetSum_coeff]\n    by_cases hz : k = 0 <;> simp only [maskedPolynomial_coefficient, hz, ite_true, ite_false]\n  · rw [ite_eq_right hk, coefficient_zero (by omega)]\n\ntheorem acquireCorrected_work (source : ℕ → Array ℚ) (t : ℚ) (R J n : ℕ) (base correction : ℕ → Bool) :\n    (acquireCorrected source t R J base correction n).arithmetic =\n      n * ((R + 1) * (J * (J + 1) + 2 * J) + J) ∧\n    (acquireCorrected source t R J base correction n).reads =\n      n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J) := by\n  induction n with\n  | zero => simp [acquireCorrected, zeroJet]\n  | succ n ih =>\n    simp only [acquireCorrected, shiftRow, shiftFrom_work, maskShift, addJet, ih]\n    constructor <;> ring\n\n/-- The finite masked-row sum is the EXISTING native correctedPort. -/\ntheorem maskedSum_native {n : ℕ} (rows : Fin n → Polynomial ℚ) (t : ℚ) (R : ℕ)\n    (hrows : ∀ v, (rows v).natDegree ≤ R) (x U : Finset (Fin n)) :\n    (∑ v : Fin n, maskedPolynomial (rows v) t (decide (v ∈ x)) (decide (v ∈ U))) =\n      SemiprimeCounterPacketHeight.correctedPort rows t R x U := by\n  classical\n  ext k\n  rw [Polynomial.finsetSum_coeff]\n  simp only [SemiprimeCounterPacketHeight.correctedPort, SemiprimeCounterPacketHeight.packet_coeff]\n  cases k with\n  | zero =>\n    simp [maskedPolynomial_coefficient, SemiprimeBooleanDiagonal.indicator, taylor_coeff_zero]\n  | succ k =>\n    by_cases hk : k < R\n    · simp [maskedPolynomial_coefficient, hk, SemiprimeBooleanDiagonal.indicator]\n    · have hz (v : Fin n) : (taylor t (rows v)).coeff (k + 1) = 0 := by\n        apply coeff_eq_zero_of_natDegree_lt\n        rw [natDegree_taylor]\n        exact lt_of_le_of_lt (hrows v) (by omega)\n      simp [maskedPolynomial_coefficient, hk, hz]\n\n/-- Concrete finite-index source family supplied by the layout constructor. -/\ndef acquireCorrectedFin {n : ℕ} (source : Fin n → Array ℚ) (t : ℚ) (R J : ℕ)\n    (base correction : Fin n → Bool) : InverseReport :=\n  acquireCorrected (fun v => if h : v < n then source ⟨v, h⟩ else #[]) t R J\n    (fun v => if h : v < n then base ⟨v, h⟩ else false)\n    (fun v => if h : v < n then correction ⟨v, h⟩ else false) n\n\n/-- Actual acquired array is the native correctedPort used by the global counter. -/\ntheorem acquireCorrectedFin_native {n : ℕ} (source : Fin n → Array ℚ)\n    (rows : Fin n → Polynomial ℚ) (t : ℚ) (R J : ℕ)\n    (hrows : ∀ v, (rows v).natDegree ≤ R)\n    (hsource : ∀ v k, k ≤ R → coefficient (source v) k = (rows v).coeff k)\n    (x U : Finset (Fin n)) :\n    asPolynomial (acquireCorrectedFin source t R J (fun v => decide (v ∈ x))\n      (fun v => decide (v ∈ U))).coefficients =\n      SemiprimeCounterPacketHeight.correctedPort rows t R x U %ₘ X ^ J := by\n  let P : ℕ → Polynomial ℚ := fun v => if h : v < n then rows ⟨v, h⟩ else 0\n  have hs := acquireCorrected_correct\n    (fun v => if h : v < n then source ⟨v, h⟩ else #[]) P t R J n\n    (fun v => if h : v < n then decide (⟨v, h⟩ ∈ x) else false)\n    (fun v => if h : v < n then decide (⟨v, h⟩ ∈ U) else false)\n    (by intro v hv; simpa only [P, dite_eq_left hv] using hrows ⟨v, hv⟩)\n    (by intro v hv k hk; simpa only [P, dite_eq_left hv] using hsource ⟨v, hv⟩ k hk)\n  change asPolynomial (acquireCorrected _ _ _ _ _ _ _).coefficients = _\n  rw [hs]\n  congr 1\n  rw [← maskedSum_native rows t R hrows x U, Finset.sum_fin_eq_sum_range]\n  apply Finset.sum_congr rfl\n  intro v hv\n  have hv' := Finset.mem_range.mp hv\n  simp only [P, dite_eq_left hv']\n\n/-- Complete local native call: acquire each input port then evaluate its table. -/\ndef nativeLocal {n : ℕ} (w J R : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryReport) : InverseReport :=\n  let inputs := Array.ofFn (fun v : Fin w => acquireCorrectedFin (source v) t R J base correction)\n  let getInput := fun v : Fin w => inputs[v.val]'(by simp [inputs])\n  let out := localEvaluate J w T (fun v => (getInput v).coefficients)\n  ⟨out.coefficients, (∑ v, (getInput v).arithmetic) + out.arithmetic,\n    (∑ v, (getInput v).reads) + out.reads⟩\n\n/-- The actual full local frontend agrees with the EXISTING native polynomial evaluator. -/\ntheorem nativeLocal_correct {n : ℕ} (w J R : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (rows : Fin w → Fin n → Polynomial ℚ)\n    (hrows : ∀ v i, (rows v i).natDegree ≤ R)\n    (hsource : ∀ v i k, k ≤ R → coefficient (source v i) k = (rows v i).coeff k)\n    (x U : Finset (Fin n)) (T : (Fin w → Bool) → EntryReport) :\n    asPolynomial (nativeLocal w J R t source (fun v => decide (v ∈ x))\n      (fun v => decide (v ∈ U)) T).coefficients =\n      evaluate w (fun eta => C ((T eta).value : ℚ))\n        (fun v => SemiprimeCounterPacketHeight.correctedPort (rows v) t R x U) %ₘ X ^ J := by\n  apply localEvaluate_correct\n  intro v i hi\n  simpa only [Array.getElem_ofFn] using specification_of_asPolynomial _ _ _\n    (acquireCorrectedFin_native (source v) (rows v) t R J (hrows v) (hsource v) x U) i hi\n\ntheorem acquireCorrectedFin_work {n : ℕ} (source : Fin n → Array ℚ) (t : ℚ) (R J : ℕ)\n    (base correction : Fin n → Bool) :\n    (acquireCorrectedFin source t R J base correction).arithmetic =\n      n * ((R + 1) * (J * (J + 1) + 2 * J) + J) ∧\n    (acquireCorrectedFin source t R J base correction).reads =\n      n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J) :=\n  acquireCorrected_work _ _ _ _ _ _ _\n\n/-- Full local cost includes materialized corrected inputs and every table callback. -/\ntheorem nativeLocal_work {n : ℕ} (w J R A : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryReport)\n    (hT : ∀ eta, (T eta).arithmetic ≤ A ∧ (T eta).reads ≤ A) :\n    (nativeLocal w J R t source base correction T).arithmetic ≤\n      w * (n * ((R + 1) * (J * (J + 1) + 2 * J) + J)) +\n        2 ^ w * (A + (w + 1) * localOverhead J + J) ∧\n    (nativeLocal w J R t source base correction T).reads ≤\n      w * (n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J)) +\n        2 ^ w * (A + (w + 1) * localOverhead J + J) := by\n  let inputs := Array.ofFn (fun v : Fin w => acquireCorrectedFin (source v) t R J base correction)\n  let getInput := fun v : Fin w => inputs[v.val]'(by simp [inputs])\n  have hc (v : Fin w) : (getInput v).arithmetic = n * ((R + 1) * (J * (J + 1) + 2 * J) + J) ∧\n      (getInput v).reads = n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J) := by\n    simpa only [getInput, inputs, Array.getElem_ofFn] using\n      acquireCorrectedFin_work (source v) t R J base correction\n  have ha : (∑ v, (getInput v).arithmetic) = w * (n * ((R + 1) * (J * (J + 1) + 2 * J) + J)) := by\n    simp only [(hc _).1, Finset.sum_const, Finset.card_univ, Fintype.card_fin, nsmul_eq_mul, Nat.cast_id]\n  have hr : (∑ v, (getInput v).reads) = w * (n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J)) := by\n    simp only [(hc _).2, Finset.sum_const, Finset.card_univ, Fintype.card_fin, nsmul_eq_mul, Nat.cast_id]\n  have he := localEvaluate_work J w A T (fun v => (getInput v).coefficients) hT\n  change (∑ v, (getInput v).arithmetic) + _ ≤ _ ∧ (∑ v, (getInput v).reads) + _ ≤ _\n  rw [ha, hr]\n  exact ⟨Nat.add_le_add_left he.1 _, Nat.add_le_add_left he.2 _⟩\n\ntheorem representation_neg {q : ℚ} {d B : ℕ} (h : Representation q d B) :\n    Representation (-q) d B := by\n  obtain ⟨z, hz, hb⟩ := h\n  exact ⟨-z, by simpa only [Int.cast_neg, neg_div] using congrArg Neg.neg hz,\n    by simpa only [Int.natAbs_neg] using hb⟩\n\ntheorem oneJet_representation (J d : ℕ) (hd : 0 < d) (i : ℕ) (hi : i < J) :\n    Representation (coefficient (oneJet J).coefficients i) d d := by\n  rw [oneJet_coefficient J i hi]\n  split_ifs\n  · exact SemiprimeHermiteArrayHeight.representation_one d hd\n  · exact representation_mono (SemiprimeHermiteArrayHeight.representation_zero d) (by omega)\n\n/-- Uniform local tree height scale, based only on native input-port bounds. -/\ndef localBase (J d B : ℕ) : ℕ := 2 * J * (d + B)\n\n/-- Every recursive local subtree has an explicit shared power denominator;\nthis applies before any sum cancellation and charges no hidden normalization. -/\ntheorem localEvaluate_representation (J w d B : ℕ) (hd : 0 < d)\n    (T : (Fin w → Bool) → EntryReport) (inputs : Fin w → Array ℚ)\n    (hT : ∀ eta, (T eta).value.natAbs ≤ 1)\n    (hinputs : ∀ v i, i < J → Representation (coefficient (inputs v) i) d B)\n    (i : ℕ) (hi : i < J) :\n    Representation (coefficient (localEvaluate J w T inputs).coefficients i)\n      (d ^ w) (localBase J d B ^ w) := by\n  induction w generalizing i with\n  | zero =>\n    rw [pow_zero, pow_zero]\n    change Representation (coefficient (scaleJet (oneJet J).coefficients ((T Fin.elim0).value : ℚ) J).coefficients i) 1 1\n    rw [scaleJet_coefficient _ _ J i hi, oneJet_coefficient J i hi]\n    split_ifs\n    · rw [mul_one]\n      exact representation_mono (SemiprimeHermiteArrayHeight.representation_integer _) (hT _)\n    · rw [mul_zero]\n      exact representation_mono (SemiprimeHermiteArrayHeight.representation_zero 1) (by decide)\n  | succ w ih =>\n    let lo := localEvaluate J w (fun eta => T (Fin.cons false eta)) (fun v => inputs v.succ)\n    let hiTree := localEvaluate J w (fun eta => T (Fin.cons true eta)) (fun v => inputs v.succ)\n    have hlo (k : ℕ) (hk : k < J) : Representation (coefficient lo.coefficients k) (d ^ w) (localBase J d B ^ w) :=\n      ih _ _ (fun eta => hT (Fin.cons false eta)) (fun v => hinputs v.succ) k hk\n    have hhi (k : ℕ) (hk : k < J) : Representation (coefficient hiTree.coefficients k) (d ^ w) (localBase J d B ^ w) :=\n      ih _ _ (fun eta => hT (Fin.cons true eta)) (fun v => hinputs v.succ) k hk\n    let neg := scaleJet (inputs 0) (-1) J\n    let no := addJet (oneJet J).coefficients neg.coefficients J\n    have hneg (k : ℕ) (hk : k < J) : Representation (coefficient neg.coefficients k) d B := by\n      rw [scaleJet_coefficient _ _ J k hk, neg_one_mul]\n      exact representation_neg (hinputs 0 k hk)\n    have hno (k : ℕ) (hk : k < J) : Representation (coefficient no.coefficients k) d (d + B) :=\n      addJet_representation _ _ J d d B (oneJet_representation J d hd) hneg k hk\n    let left := multiply no.coefficients lo.coefficients J\n    let right := multiply (inputs 0) hiTree.coefficients J\n    have hl := multiply_representation no.coefficients lo.coefficients d (d ^ w) (d + B)\n      (localBase J d B ^ w) J hno hlo i hi\n    have hr := multiply_representation (inputs 0) hiTree.coefficients d (d ^ w) B\n      (localBase J d B ^ w) J (hinputs 0) hhi i hi\n    have hr' : Representation (coefficient right.coefficients i) (d * d ^ w)\n        (J * (d + B) * localBase J d B ^ w) := representation_mono hr (by gcongr; omega)\n    change Representation (coefficient (addJet left.coefficients right.coefficients J).coefficients i) _ _\n    rw [addJet_coefficient _ _ J i hi]\n    have hs := representation_add hl hr'\n    convert hs using 1\n    · rw [pow_succ']\n    · rw [pow_succ]\n      unfold localBase\n      ring\n\nend RiemannGaussian.SemiprimeLocalArrayFrontend\n","RiemannGaussian.SemiprimeMaterializedWords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFiniteEnumerations\n\n/-! # Explicit local-expectation search with its scalar and list-control trace\nThis executes every local completion, scalar sum/division, candidate comparison\nand sequential assignment. Terminal computations return their own work; this\nmodule does not turn an arbitrary terminal function into a constant-cost oracle.\nThe trace is a scalar/control trace, with bit refinement stated separately.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeMaterializedWords\nopen OAI.Algorithms.SubexponentialSAT\nopen LocalExpectation ConditionalExpectation\n\n/-- A produced value and the work of its executed producer. -/\nstructure Run (A : Type*) where\n  /-- Actual output. -/\n  value : A\n  /-- Executed scalar and finite-list control events. -/\n  work : ℕ\n\n/-- Sum actual child results, retaining every callback's work. -/\ndef sumRun {A : Type*} (f : A → Run ℚ) : List A → Run ℚ\n  | [] => ⟨0,1⟩\n  | a::as =>\n      let x := f a\n      let y := sumRun f as\n      ⟨x.value+y.value,x.work+y.work+3⟩\n\ntheorem sumRun_value {A : Type*} (f : A → Run ℚ) (xs : List A) :\n    (sumRun f xs).value=(xs.map (fun a => (f a).value)).sum := by\n  induction xs with\n  | nil => rfl\n  | cons a as ih => simp only [sumRun,List.map_cons,List.sum_cons,ih]\n\ntheorem sumRun_work {A : Type*} (f : A → Run ℚ) (xs : List A) (B : ℕ)\n    (hf : ∀ a ∈ xs, (f a).work≤B) :\n    (sumRun f xs).work≤xs.length*(B+3)+1 := by\n  induction xs with\n  | nil => simp [sumRun]\n  | cons a as ih =>\n      have hx := hf a (by simp)\n      have hy := ih (fun b hb => hf b (by simp [hb]))\n      simp only [sumRun,List.length_cons]\n      nlinarith\n\n/-- Finite averaging over the explicitly named, small support only. -/\ndef expectation {W : Type*} (alphabet : List W) (f : (ℕ → W) → Run ℚ) :\n    List ℕ → (ℕ → W) → Run ℚ\n  | [], omega =>\n      let x := f omega\n      ⟨x.value,x.work+1⟩\n  | i::remaining, omega =>\n      let x := sumRun (fun a => expectation alphabet f remaining (Function.update omega i a)) alphabet\n      ⟨x.value/(alphabet.length : ℚ),x.work+alphabet.length+3⟩\n\ntheorem expectation_value {W : Type*} (alphabet : List W) (f : (ℕ → W) → Run ℚ)\n    (remaining : List ℕ) (omega : ℕ → W) :\n    (expectation alphabet f remaining omega).value=\n      wordExpectation alphabet (fun x => (f x).value) remaining omega := by\n  induction remaining generalizing omega with\n  | nil => rfl\n  | cons i remaining ih =>\n      simp only [expectation,wordExpectation,mean,sumRun_value]\n      congr 2\n      apply List.map_congr_left\n      intro a _\n      exact ih _\n\n/-- A fixed support gives a fixed polynomial in the actual alphabet size.\nAll internal averages and list traversals are included, not only leaf calls. -/\ntheorem expectation_work {W : Type*} (alphabet : List W) (f : (ℕ → W) → Run ℚ)\n    (B : ℕ) (hf : ∀ omega, (f omega).work≤B) (remaining : List ℕ) (omega : ℕ → W) :\n    (expectation alphabet f remaining omega).work≤\n      (alphabet.length+1)^(remaining.length+1)*(B+10) := by\n  induction remaining generalizing omega with\n  | nil =>\n      have h := hf omega\n      simp only [expectation,List.length_nil,Nat.zero_add,pow_one]\n      nlinarith\n  | cons i remaining ih =>\n      let A := alphabet.length\n      let D := (A+1)^(remaining.length+1)*(B+10)\n      have hs := sumRun_work\n        (fun a => expectation alphabet f remaining (Function.update omega i a)) alphabet D\n        (fun a _ => ih _)\n      have hp : A+1≤(A+1)^(remaining.length+1) := by\n        simpa using Nat.pow_le_pow_right (by omega : 0<A+1) (by omega : 1≤remaining.length+1)\n      have hd : 4*A+4≤D := by dsimp [D]; nlinarith\n      change (sumRun _ alphabet).work+A+3≤_\n      simp only [List.length_cons,pow_succ]\n      change (sumRun _ alphabet).work+A+3≤(A+1)^(remaining.length+1)*(A+1)*(B+10)\n      dsimp [D] at hs hd\n      dsimp [A] at *\n      nlinarith\n\n/-- Actual finite index-membership scan. -/\ndef memberRun (i : ℕ) : List ℕ → Run Bool\n  | [] => ⟨false,1⟩\n  | j::js =>\n      if i=j then ⟨true,2⟩ else\n      let rest := memberRun i js\n      ⟨rest.value,rest.work+2⟩\n\ntheorem memberRun_value (i : ℕ) (xs : List ℕ) : (memberRun i xs).value=decide (i∈xs) := by\n  induction xs with\n  | nil => simp [memberRun]\n  | cons j js ih => by_cases h : i=j <;> simp [memberRun,h,ih]\n\ntheorem memberRun_work (i : ℕ) (xs : List ℕ) : (memberRun i xs).work≤2*xs.length+1 := by\n  induction xs with\n  | nil => simp [memberRun]\n  | cons j js ih => by_cases h : i=j <;> simp only [memberRun,h,ite_true,ite_false,List.length_cons] <;> omega\n\n/-- Filter remaining indices using the actual cached support-list scan. -/\ndef activeRun (support : List ℕ) : List ℕ → Run (List ℕ)\n  | [] => ⟨[],1⟩\n  | i::remaining =>\n      let test := memberRun i support\n      let rest := activeRun support remaining\n      ⟨if test.value then i::rest.value else rest.value,test.work+rest.work+3⟩\n\ntheorem activeRun_value (support remaining : List ℕ) :\n    (activeRun support remaining).value=active support.toFinset remaining := by\n  induction remaining with\n  | nil => rfl\n  | cons i remaining ih => simp [activeRun,active,List.filter_cons,memberRun_value,ih]\n\ntheorem activeRun_work (support remaining : List ℕ) :\n    (activeRun support remaining).work≤remaining.length*(2*support.length+4)+1 := by\n  induction remaining with\n  | nil => simp [activeRun]\n  | cons i remaining ih =>\n      have hm := memberRun_work i support\n      simp only [activeRun,List.length_cons]\n      nlinarith\n\n/-- One actual local expectation, including acquisition of its active support. -/\ndef localTerm {W : Type*} (alphabet : List W) (support : List ℕ)\n    (f : (ℕ → W) → Run ℚ) (remaining : List ℕ) (omega : ℕ → W) : Run ℚ :=\n  let selected := activeRun support remaining\n  let result := expectation alphabet f selected.value omega\n  ⟨result.value,selected.work+result.work+1⟩\n\ntheorem localTerm_value {W : Type*} (alphabet : List W) (support : List ℕ)\n    (f : (ℕ → W) → Run ℚ) (remaining : List ℕ) (omega : ℕ → W) :\n    (localTerm alphabet support f remaining omega).value=\n      wordExpectation alphabet (fun x => (f x).value) (active support.toFinset remaining) omega := by\n  simp only [localTerm,expectation_value,activeRun_value]\n\ntheorem localTerm_work {W : Type*} (alphabet : List W) (support : List ℕ)\n    (f : (ℕ → W) → Run ℚ) (B s : ℕ) (hf : ∀ omega, (f omega).work≤B)\n    (hs : support.length≤ s) (remaining : List ℕ) (hr : remaining.Nodup) (omega : ℕ → W) :\n    (localTerm alphabet support f remaining omega).work≤\n      remaining.length*(2*s+4)+(alphabet.length+1)^(s+1)*(B+10)+2 := by\n  have ha := activeRun_work support remaining\n  have hb := expectation_work alphabet f B hf (activeRun support remaining).value omega\n  have hl : (activeRun support remaining).value.length≤ s := by\n    rw [activeRun_value]\n    exact (active_length_le support.toFinset remaining hr).trans ((List.toFinset_card_le _).trans hs)\n  have hp := Nat.pow_le_pow_right (by omega : 0<alphabet.length+1) (Nat.add_le_add_right hl 1)\n  have hm := Nat.mul_le_mul_right (B+10) hp\n  have hc := Nat.mul_le_mul_left remaining.length (show 2*support.length+4≤2*s+4 by omega)\n  change (activeRun support remaining).work+(expectation alphabet f (activeRun support remaining).value omega).work+1≤_\n  omega\n\n/-- Actual scalar objective evaluation with all local completion work retained. -/\ndef evaluate {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (remaining : List ℕ) (omega : ℕ → W) : Run ℚ :=\n  let result := sumRun (fun j => localTerm alphabet (support j) (f j) remaining omega) terms\n  ⟨result.value-offset,result.work+2⟩\n\ntheorem evaluate_value {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (remaining : List ℕ) (omega : ℕ → W) :\n    (evaluate alphabet terms support f offset remaining omega).value=\n      localEvaluator alphabet terms (fun j => (support j).toFinset)\n        (fun j x => (f j x).value) offset remaining omega := by\n  simp only [evaluate,localEvaluator,sumRun_value,localTerm_value]\n\ntheorem evaluate_work {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (B s : ℕ) (hf : ∀ j omega, (f j omega).work≤B) (hs : ∀ j, (support j).length≤ s)\n    (remaining : List ℕ) (hr : remaining.Nodup) (omega : ℕ → W) :\n    (evaluate alphabet terms support f offset remaining omega).work≤\n      terms.length*(remaining.length*(2*s+4)+(alphabet.length+1)^(s+1)*(B+10)+5)+3 := by\n  have h := sumRun_work (fun j => localTerm alphabet (support j) (f j) remaining omega) terms\n    (remaining.length*(2*s+4)+(alphabet.length+1)^(s+1)*(B+10)+2)\n    (fun j _ => localTerm_work alphabet (support j) (f j) B s (hf j) (hs j) remaining hr omega)\n  change (sumRun _ terms).work+2≤_\n  nlinarith\n\n/-- Candidate comparison executes both score producers, including comparison control. -/\ndef choose {W : Type*} (score : W → Run ℚ) (a : W) : List W → Run W\n  | [] => ⟨a,1⟩\n  | b::bs =>\n      let next := choose score b bs\n      let left := score a\n      let right := score next.value\n      ⟨if left.value≤right.value then a else next.value,next.work+left.work+right.work+3⟩\n\ntheorem choose_value {W : Type*} (score : W → Run ℚ) (a : W) (tail : List W) :\n    (choose score a tail).value=chooseMin (fun w => (score w).value) a tail := by\n  induction tail generalizing a with\n  | nil => rfl\n  | cons b bs ih => simp only [choose,chooseMin,ih]\n\ntheorem choose_work {W : Type*} (score : W → Run ℚ) (a : W) (tail : List W)\n    (B : ℕ) (hf : ∀ w, (score w).work≤B) :\n    (choose score a tail).work≤tail.length*(2*B+3)+1 := by\n  induction tail generalizing a with\n  | nil => simp [choose]\n  | cons b bs ih =>\n      have ht := ih b\n      have hl := hf a\n      have hr := hf (choose score b bs).value\n      simp only [choose,List.length_cons]\n      nlinarith\n\n/-- All candidate evaluations and actual sequential updates are performed. -/\ndef assign {W : Type*} (a : W) (tail : List W)\n    (evaluator : ℕ → List W → Run ℚ) : ℕ → List W → Run (List W)\n  | 0, fixed => ⟨fixed,1⟩\n  | n+1, fixed =>\n      let next := choose (fun w => evaluator n (w::fixed)) a tail\n      let rest := assign a tail evaluator n (next.value::fixed)\n      ⟨rest.value,next.work+rest.work+3⟩\n\ntheorem assign_value {W : Type*} (a : W) (tail : List W)\n    (evaluator : ℕ → List W → Run ℚ) (n : ℕ) (fixed : List W) :\n    (assign a tail evaluator n fixed).value=\n      assignWithEvaluator a tail (fun n xs => (evaluator n xs).value) n fixed := by\n  induction n generalizing fixed with\n  | zero => rfl\n  | succ n ih => simp only [assign,assignWithEvaluator,ih,choose_value]\n\n/-- The evaluator bound is needed only on physically reachable list lengths. -/\ntheorem assign_work {W : Type*} (a : W) (tail : List W)\n    (evaluator : ℕ → List W → Run ℚ) (B N : ℕ)\n    (he : ∀ n fixed, n+fixed.length≤N → (evaluator n fixed).work≤B)\n    (n : ℕ) (fixed : List W) (hlen : n+fixed.length≤N) :\n    (assign a tail evaluator n fixed).work≤n*(tail.length*(2*B+3)+4)+1 := by\n  induction n generalizing fixed with\n  | zero => simp [assign]\n  | succ n ih =>\n      have hn : ∀ w, (evaluator n (w::fixed)).work≤B := by\n        intro w\n        apply he\n        simpa only [List.length_cons,Nat.add_assoc,Nat.add_comm 1] using hlen\n      have hc := choose_work (fun w => evaluator n (w::fixed)) a tail B hn\n      have ht := ih ((choose (fun w => evaluator n (w::fixed)) a tail).value::fixed) (by simp only [List.length_cons]; omega)\n      change (choose _ a tail).work+(assign a tail evaluator n _).work+3≤_\n      nlinarith\n\n/-- Actual numbered local evaluator, with range/list-length construction included. -/\ndef sequential {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (default : W) (n : ℕ) (fixed : List W) : Run ℚ :=\n  let result := evaluate alphabet terms support f offset\n    (List.range' fixed.length n) (decode default fixed)\n  ⟨result.value,result.work+fixed.length+n+2⟩\n\ntheorem sequential_value {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (default : W) (n : ℕ) (fixed : List W) :\n    (sequential alphabet terms support f offset default n fixed).value=\n      sequentialEvaluator alphabet terms (fun j => (support j).toFinset)\n        (fun j x => (f j x).value) offset default n fixed := by\n  exact evaluate_value alphabet terms support f offset _ _\n\n/-- Public uniform evaluator envelope on all reachable input-list lengths. -/\ndef evaluatorBudget (A T N B s : ℕ) : ℕ :=\n  T*(N*(2*s+4)+(A+1)^(s+1)*(B+10)+5)+N+5\n\ntheorem sequential_work {W J : Type*} (alphabet : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (B s N : ℕ) (hf : ∀ j omega, (f j omega).work≤B) (hs : ∀ j, (support j).length≤ s)\n    (default : W) (n : ℕ) (fixed : List W) (hlen : n+fixed.length≤N) :\n    (sequential alphabet terms support f offset default n fixed).work≤\n      evaluatorBudget alphabet.length terms.length N B s := by\n  have h := evaluate_work alphabet terms support f offset B s hf hs\n    (List.range' fixed.length n) (List.nodup_range') (decode default fixed)\n  simp only [List.length_range'] at h\n  have hn : n≤N := by omega\n  have hc := Nat.mul_le_mul_left terms.length\n    (Nat.add_le_add_right (Nat.add_le_add_right\n      (Nat.mul_le_mul_right (2*s+4) hn) ((alphabet.length+1)^(s+1)*(B+10))) 5)\n  change (evaluate _ _ _ _ _ _ _).work+fixed.length+n+2≤_\n  unfold evaluatorBudget\n  omega\n\n/-- Complete actual search from the empty prefix. All terminal computations\nand internal averages/comparisons are executed; no optimum is supplied. -/\ndef search {W J : Type*} (a : W) (tail : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ) (N : ℕ) :\n    Run (List W) := assign a tail (sequential (a::tail) terms support f offset a) N []\n\ntheorem search_value {W J : Type*} (a : W) (tail : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ) (N : ℕ) :\n    (search a tail terms support f offset N).value=\n      localAssign a tail terms (fun j => (support j).toFinset)\n        (fun j x => (f j x).value) offset a N := by\n  simp only [search,assign_value,localAssign,sequential_value]\n\n/-- Whole executed search, not only its number of terminal calls. The supplied\nB is the actual terminal producer budget; it is not silently set to one. -/\ntheorem search_work {W J : Type*} (a : W) (tail : List W) (terms : List J)\n    (support : J → List ℕ) (f : J → (ℕ → W) → Run ℚ) (offset : ℚ)\n    (B s N : ℕ) (hf : ∀ j omega, (f j omega).work≤B) (hs : ∀ j, (support j).length≤ s) :\n    (search a tail terms support f offset N).work≤\n      N*(tail.length*(2*evaluatorBudget (a::tail).length terms.length N B s+3)+4)+1 :=\n  assign_work a tail (sequential (a::tail) terms support f offset a)\n    (evaluatorBudget (a::tail).length terms.length N B s) N\n    (fun n fixed hn => sequential_work (a::tail) terms support f offset B s N hf hs a n fixed hn)\n    N [] (by simp)\n\nend RiemannGaussian.SemiprimeMaterializedWords\n","RiemannGaussian.SemiprimeNativeGroupExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeLocalArrayFrontend\nimport RiemannGaussian.SemiprimeFibreArrayExecution\n\n/-!\n# Actual native local factors supply the group callback\n\nGrouped Boolean bases are materialized once. Factors are traversed by their\nliteral Fin indices, with unassigned factors returning one. No groupValue or\nwhole-fibre answer is a runtime argument.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeNativeGroupExecution\nopen scoped BigOperators\nopen Polynomial\nopen SemiprimeJetArray SemiprimeArrayOps SemiprimeLocalArrayFrontend\nopen SemiprimeCounterCompose SemiprimeCounterPacketHeight SemiprimeFibreArrayExecution\n\n/-- Conservative finite control/allocation charge for the executed local frontend. -/\ndef localControl (n w R J : ℕ) : ℕ :=\n  (n + 1) * (w + 1) * (R + 1) * (J + 1) + 2 ^ (w + 1) * (w + J + 1)\n\n/-- Wrap the ACTUAL local evaluator, retaining all rational/read work. -/\ndef localRun {n : ℕ} (w J R : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryReport) : Run :=\n  let out := nativeLocal w J R t source base correction T\n  ⟨out, out.arithmetic + out.reads + localControl n w R J⟩\n\ntheorem localRun_spec {n : ℕ} (w J R : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (rows : Fin w → Fin n → Polynomial ℚ)\n    (hrows : ∀ v i, (rows v i).natDegree ≤ R)\n    (hsource : ∀ v i k, k ≤ R → coefficient (source v i) k = (rows v i).coeff k)\n    (x U : Finset (Fin n)) (T : (Fin w → Bool) → EntryReport) :\n    Spec J (localRun w J R t source (fun v => decide (v ∈ x)) (fun v => decide (v ∈ U)) T)\n      (SemiprimeStreamingTensor.evaluate w (fun eta => C ((T eta).value : ℚ))\n        (fun v => correctedPort (rows v) t R x U)) :=\n  specification_of_asPolynomial _ _ _ (nativeLocal_correct w J R t source rows hrows hsource x U T)\n\n/-- Polynomial factors multiplying the sole local 2^w truth traversal. -/\ndef localBudget (n w R J A : ℕ) : ℕ :=\n  2 * (w * (n * ((R + 1) * (J * (J + 1) + 2 * J) + J)) +\n    w * (n * ((R + 1) * (J * (J + 1) + 3 * J + 1) + 3 * J)) +\n    2 * (2 ^ w * (A + (w + 1) * localOverhead J + J))) + localControl n w R J\n\ntheorem localRun_work {n : ℕ} (w J R A : ℕ) (t : ℚ)\n    (source : Fin w → Fin n → Array ℚ) (base correction : Fin n → Bool)\n    (T : (Fin w → Bool) → EntryReport)\n    (hT : ∀ eta, (T eta).arithmetic ≤ A ∧ (T eta).reads ≤ A) :\n    (localRun w J R t source base correction T).work ≤ localBudget n w R J A := by\n  have h := nativeLocal_work w J R A t source base correction T hT\n  simp only [Run.work, localRun]\n  unfold localBudget\n  omega\n\nvariable {G : Type} [DecidableEq G] {L : G → Type}\n\n/-- Concrete original-coordinate Boolean base, read from grouped bits. -/\ndef baseBits {n : ℕ} (grouping : Fin n ≃ Sigma L) (a : (g : G) → L g → Bool) : Fin n → Bool :=\n  fun v => a (grouping v).1 (grouping v).2\n\n/-- Actual group callback: cache base bits and multiply gated native local calls. -/\ndef nativeGroup {n F : ℕ} (arity : Fin F → ℕ) (J R : ℕ) (t : ℚ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array ℚ)\n    (grouping : Fin n ≃ Sigma L) (assigned : Fin F → G)\n    (correction : Fin n → Bool) (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (g : G) (a : (g : G) → L g → Bool) : Run :=\n  let bits := Array.ofFn (baseBits grouping a)\n  let getBit := fun v : Fin n => bits[v.val]'(by simp [bits])\n  let result := productList J (List.ofFn (fun e : Fin F => e)) (fun e =>\n    if assigned e = g then localRun (arity e) J R t (source e) getBit correction (T e) else oneRun J)\n  ⟨result.jet, result.control + n + F + 2⟩\n\n/-- Native grouped polynomial rows, with no representative/value acquisition. -/\nnoncomputable def groupedSource {n F : ℕ} (arity : Fin F → ℕ)\n    (rows : (e : Fin F) → Fin (arity e) → Fin n → Polynomial ℚ)\n    (t : ℚ) (grouping : Fin n ≃ Sigma L) :\n    (e : Fin F) → Fin (arity e) → (g : G) → L g → ℚ :=\n  fun e i g v => (rows e i (grouping.symm ⟨g, v⟩)).eval t\n\nomit [DecidableEq G] in\n/-- Cached base bits and the proof-only finite-set base are extensionally identical. -/\ntheorem baseBits_set {n : ℕ} (grouping : Fin n ≃ Sigma L) (a : (g : G) → L g → Bool) :\n    (fun v : Fin n => decide (v ∈ (splitAssignment grouping).symm a)) = baseBits grouping a := by\n  funext v\n  simp [splitAssignment, baseBits]\n\n/-- The actual group callback computes a finite product of native corrected factors. -/\ntheorem nativeGroup_product_spec {n F : ℕ} (arity : Fin F → ℕ) (J R : ℕ) (t : ℚ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array ℚ)\n    (rows : (e : Fin F) → Fin (arity e) → Fin n → Polynomial ℚ)\n    (hrows : ∀ e i v, (rows e i v).natDegree ≤ R)\n    (hsource : ∀ e i v k, k ≤ R → coefficient (source e i v) k = (rows e i v).coeff k)\n    (grouping : Fin n ≃ Sigma L) (assigned : Fin F → G) (U : Finset (Fin n))\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (g : G) (a : (g : G) → L g → Bool) :\n    Spec J (nativeGroup arity J R t source grouping assigned (fun v => decide (v ∈ U)) T g a)\n      (∏ e ∈ Finset.univ.filter (fun e => assigned e = g),\n        SemiprimeStreamingTensor.evaluate (arity e) (fun eta => C ((T e eta).value : ℚ))\n          (fun i => correctedPort (rows e i) t R ((splitAssignment grouping).symm a) U)) := by\n  classical\n  let x := (splitAssignment grouping).symm a\n  let p := fun e : Fin F => SemiprimeStreamingTensor.evaluate (arity e)\n    (fun eta => C ((T e eta).value : ℚ)) (fun i => correctedPort (rows e i) t R x U)\n  let bits := Array.ofFn (baseBits grouping a)\n  let getBit := fun v : Fin n => bits[v.val]'(by simp [bits])\n  have hb : getBit = fun v => decide (v ∈ x) := by\n    funext v\n    simp only [getBit, bits, Array.getElem_ofFn]\n    exact (congrFun (baseBits_set grouping a) v).symm\n  have hf (e : Fin F) (_he : e ∈ List.ofFn (fun e : Fin F => e)) :\n      Spec J (if assigned e = g then localRun (arity e) J R t (source e) getBit\n        (fun v => decide (v ∈ U)) (T e) else oneRun J) (if assigned e = g then p e else 1) := by\n    by_cases he : assigned e = g\n    · simp only [ite_eq_left he]\n      rw [hb]\n      exact localRun_spec (arity e) J R t (source e) (rows e) (hrows e) (hsource e) x U (T e)\n    · simp only [ite_eq_right he]\n      exact oneRun_spec J\n  have hs := productList_spec J (List.ofFn (fun e : Fin F => e)) _\n    (fun e => if assigned e = g then p e else 1) hf\n  simp only [List.map_ofFn, List.prod_ofFn, Function.comp_apply] at hs\n  have hp : (∏ e : Fin F, if assigned e = g then p e else 1) =\n      ∏ e ∈ Finset.univ.filter (fun e => assigned e = g), p e := by\n    exact (Finset.prod_filter (fun e => assigned e = g) p).symm\n  rw [hp] at hs\n  exact hs\n\n/-- The supplied groupValue callback is eliminated for ANY actual node certificate. -/\ntheorem nativeGroup_node_spec {n F : ℕ} (arity : Fin F → ℕ) (J R : ℕ) (t : ℚ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array ℚ)\n    (rows : (e : Fin F) → Fin (arity e) → Fin n → Polynomial ℚ)\n    (hrows : ∀ e i v, (rows e i v).natDegree ≤ R)\n    (hsource : ∀ e i v k, k ≤ R → coefficient (source e i v) k = (rows e i v).coeff k)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t)) (U : Finset (Fin n))\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (g : d.Group) (a : (g : d.Group) → d.Local g → Bool) :\n    Spec J (nativeGroup arity J R t source d.grouping d.assigned\n      (fun v => decide (v ∈ U)) T g a)\n      (SemiprimeCounterSeparation.groupValue arity (fun e eta => ((T e eta).value : ℚ)) d.assigned\n        (groupedRows arity (fun e i v => (rows e i v).eval t) d)\n        (nativeCorrection arity rows t R U) g a) := by\n  let x := (splitAssignment d.grouping).symm a\n  have he := groupValue_corrected_product arity (fun e eta => (T e eta).value) rows t R d g x U\n  have ha : splitAssignment d.grouping x = a := (splitAssignment d.grouping).apply_symm_apply a\n  rw [ha] at he\n  rw [he]\n  exact nativeGroup_product_spec arity J R t source rows hrows hsource d.grouping d.assigned U T g a\n\n/-- Monotonicity of the explicit local ledger under an arity bound. -/\ntheorem localBudget_mono (n w W R J A : ℕ) (hw : w ≤ W) :\n    localBudget n w R J A ≤ localBudget n W R J A := by\n  unfold localBudget localControl\n  gcongr\n\n/-- Complete group callback work: only a polynomial factor-count multiplier is added. -/\ntheorem nativeGroup_work {n F : ℕ} (arity : Fin F → ℕ) (J R A W : ℕ) (t : ℚ)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array ℚ)\n    (grouping : Fin n ≃ Sigma L) (assigned : Fin F → G)\n    (correction : Fin n → Bool) (T : (e : Fin F) → (Fin (arity e) → Bool) → EntryReport)\n    (g : G) (a : (g : G) → L g → Bool)\n    (hW : ∀ e, arity e ≤ W)\n    (hT : ∀ e eta, (T e eta).arithmetic ≤ A ∧ (T e eta).reads ≤ A) :\n    (nativeGroup arity J R t source grouping assigned correction T g a).work ≤\n      F * (localBudget n W R J A + J + 1 + (2 * J * (J + 1) + J + 1)) +\n        (J + 1) + n + F + 2 := by\n  let bits := Array.ofFn (baseBits grouping a)\n  let getBit := fun v : Fin n => bits[v.val]'(by simp [bits])\n  let callback := fun e : Fin F => if assigned e = g then\n    localRun (arity e) J R t (source e) getBit correction (T e) else oneRun J\n  have hc (e : Fin F) (_he : e ∈ List.ofFn (fun e : Fin F => e)) :\n      (callback e).work ≤ localBudget n W R J A + J + 1 := by\n    by_cases he : assigned e = g\n    · simp only [callback, ite_eq_left he]\n      exact (localRun_work (arity e) J R A t (source e) getBit correction (T e) (hT e)).trans\n        ((localBudget_mono n (arity e) W R J A (hW e)).trans (by omega))\n    · simp only [callback, ite_eq_right he, Run.work, oneRun, SemiprimeArrayOps.oneJet]\n      omega\n  have hs := productList_work J (localBudget n W R J A + J + 1)\n    (List.ofFn (fun e : Fin F => e)) callback hc\n  simp only [List.length_ofFn] at hs\n  change (productList J _ callback).jet.arithmetic + (productList J _ callback).jet.reads +\n    ((productList J _ callback).control + n + F + 2) ≤ _\n  unfold Run.work at hs\n  omega\n\nend RiemannGaussian.SemiprimeNativeGroupExecution\n","RiemannGaussian.SemiprimeOffsetCarryObstruction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeNormCancellationObstruction\nimport Mathlib.Algebra.Polynomial.Splits\nimport Mathlib.Data.Multiset.Dedup\n\n/-!\n# The second carry separates the residue polynomial's paired roots\n\nFor each fixed lower input digit, distinct original row tags can have equal\nexact integer offsets at only one second carry. Summing the whole original\nfamily over all carries gives a linear duplicate-pair mass bound.\n\nThe literal exponential target carrier preserves exact offset surplus on\nLongData. Thus its monic squared divisors cannot recover the large square\nfactor of the lower-digit residue polynomial on the classical counterfamily\nrecorded in the investigation journal. Published analytic density, infinite\nfamilies and asymptotic counting are not additional Lean axioms here.\n-/\n\nnamespace RiemannGaussian.SemiprimeOffsetCarryObstruction\n\nopen scoped BigOperators\nopen Polynomial SemiprimeQuotientRows SemiprimeDenseRowCoverage\nopen SemiprimeDenseRowCarries SemiprimeGlobalPhaseCancellation\nopen SemiprimeSeedDetectorResidueObstruction SemiprimeScatteredColumnObstruction\nopen SemiprimeCauchyAcquisitionObstruction SemiprimeLocalOrderRouting\nopen SemiprimeCentreFreeCover SemiprimeSeedHermiteQuotient\nopen SemiprimeSeedPointRigidity\n\n/-- The original centered carry satisfies this exact second-digit identity. -/\ntheorem offset_lift_balance {N m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    (N : ℤ)+j*seedOffset N m j=\n      (representative N m j 1 : ℤ)*j*(1-j)+(m : ℤ)^2*(seedRow N m j).c := by\n  have hr := denseRow_relation (N:=N) (j:=j) (t:=1) hm hj false\n  change quotientRelation N m j (representative N m j 1)\n    (seedRow N m j).b (seedRow N m j).c 1 at hr\n  unfold quotientRelation at hr\n  unfold seedOffset\n  linear_combination -hr\n\n/-- The full offset determines the input modulo m squared once its leading residue is fixed. -/\ntheorem offset_lift_modEq {N m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    (j : ℤ)*seedOffset N m j ≡\n      (representative N m j 1 : ℤ)*j*(1-j)-N [ZMOD (m : ℤ)^2] := by\n  apply Int.modEq_iff_dvd.mpr\n  refine ⟨-(seedRow N m j).c,?_⟩\n  linear_combination -(offset_lift_balance (N:=N) hm hj)\n\n/-- Equal lower input digits leave a linear second-carry difference. -/\ntheorem offset_difference_modEq {N N₀ m j : ℕ} (hm : 0<m) (hj : j.Coprime m)\n    (hclass : (N : ℤ) ≡ (N₀ : ℤ) [ZMOD m]) :\n    (j : ℤ)*(seedOffset N m j-seedOffset N₀ m j) ≡\n      -((N : ℤ)-N₀) [ZMOD (m : ℤ)^2] := by\n  have ha := representative_eq_of_cofactor_modEq (p:=1) hm hj hclass\n  simp only [one_mul] at ha\n  have h := (offset_lift_modEq (N:=N) hm hj).sub (offset_lift_modEq (N:=N₀) hm hj)\n  rw [ha] at h\n  convert h using 1 <;> ring\n\n/-- All m second carries share the same lower input digit. -/\ntheorem carry_class {s m u v : ℕ} :\n    ((s+m*u : ℕ) : ℤ) ≡ ((s+m*v : ℕ) : ℤ) [ZMOD m] := by\n  apply Int.modEq_iff_dvd.mpr\n  exact ⟨(v : ℤ)-u,by push_cast; ring⟩\n\n/-- Two bounded second carries cannot represent the same input modulo m squared. -/\ntheorem equal_input_carry {s m u v : ℕ} (hm : 0<m) (hu : u<m) (hv : v<m)\n    (h : ((s+m*u : ℕ) : ℤ) ≡ ((s+m*v : ℕ) : ℤ) [ZMOD (m : ℤ)^2]) : u=v := by\n  have h' : (m : ℤ)*u ≡ (m : ℤ)*v [ZMOD (m : ℤ)*(m : ℤ)] := by\n    have h₀ : (s : ℤ)+(m : ℤ)*u ≡ (s : ℤ)+(m : ℤ)*v\n        [ZMOD (m : ℤ)*(m : ℤ)] := by\n      simpa only [Nat.cast_add,Nat.cast_mul,pow_two] using h\n    exact h₀.add_left_cancel' s\n  have h'' : (u : ℤ) ≡ (v : ℤ) [ZMOD m] :=\n    h'.mul_left_cancel' (by exact_mod_cast hm.ne')\n  have hn := Int.natCast_modEq_iff.mp h''\n  simpa only [Nat.ModEq,Nat.mod_eq_of_lt hu,Nat.mod_eq_of_lt hv] using hn\n\n/-- Every fixed literal row retains all m different second carries in its exact integer offset. -/\ntheorem offset_carry_injective {s m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    Function.Injective (fun u : Fin m => seedOffset (s+m*u.val) m j) := by\n  intro u v he\n  change seedOffset (s+m*u.val) m j=seedOffset (s+m*v.val) m j at he\n  have h := offset_difference_modEq hm hj (carry_class (s:=s) (u:=u.val) (v:=v.val))\n  rw [he,sub_self,mul_zero] at h\n  have h' : ((s+m*u.val : ℕ) : ℤ) ≡ ((s+m*v.val : ℕ) : ℤ) [ZMOD (m : ℤ)^2] := by\n    apply Int.modEq_iff_dvd.mpr\n    simpa only [sub_zero,neg_sub] using h.dvd\n  exact Fin.ext (equal_input_carry hm u.isLt v.isLt h')\n\n/-- A nonzero element modulo a prime also permits integer cancellation modulo its square. -/\ntheorem integer_coprime_square {m : ℕ} (hm : m.Prime) (a : ℤ)\n    (ha : (a : ZMod m)≠0) : IsCoprime ((m : ℤ)^2) a := by\n  apply IsCoprime.pow_left\n  apply Int.isCoprime_iff_nat_coprime.mpr\n  rw [Int.natAbs_natCast]\n  apply hm.coprime_iff_not_dvd.mpr\n  intro hd\n  exact ha ((ZMod.intCast_zmod_eq_zero_iff_dvd _ m).mpr (Int.natCast_dvd.mpr hd))\n\n/-- Two distinct original tags can have equal exact offsets at only one second carry. -/\ntheorem duplicate_pair_unique_carry {s m j k u v : ℕ} (hm : m.Prime)\n    (hj : 1≤j) (hjm : j<m) (hk : 1≤k) (hkm : k<m) (hjk : j≠k)\n    (hu : u<m) (hv : v<m)\n    (he : seedOffset (s+m*u) m j=seedOffset (s+m*u) m k)\n    (he₀ : seedOffset (s+m*v) m j=seedOffset (s+m*v) m k) : u=v := by\n  have hjcop : j.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hjm)).symm\n  have hkcop : k.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hkm)).symm\n  let D := seedOffset (s+m*u) m j-seedOffset (s+m*v) m j\n  have hJ := offset_difference_modEq hm.pos hjcop (carry_class (s:=s) (u:=u) (v:=v))\n  have hK := offset_difference_modEq hm.pos hkcop (carry_class (s:=s) (u:=u) (v:=v))\n  rw [←he,←he₀] at hK\n  change (j : ℤ)*D ≡ -(((s+m*u : ℕ) : ℤ)-(s+m*v : ℕ)) [ZMOD (m : ℤ)^2] at hJ\n  change (k : ℤ)*D ≡ -(((s+m*u : ℕ) : ℤ)-(s+m*v : ℕ)) [ZMOD (m : ℤ)^2] at hK\n  have hd : (m : ℤ)^2∣((j : ℤ)-k)*D := by\n    have h := (hJ.sub hK).symm.dvd\n    convert h using 1\n    ring\n  have hdiff : (((j : ℤ)-k : ℤ) : ZMod m)≠0 := by\n    intro heq\n    have heq' : (j : ZMod m)=(k : ZMod m) := by\n      simpa only [Int.cast_sub,Int.cast_natCast,sub_eq_zero] using heq\n    have hv' := congrArg ZMod.val heq'\n    simp only [ZMod.val_natCast,Nat.mod_eq_of_lt hjm,Nat.mod_eq_of_lt hkm] at hv'\n    exact hjk hv'\n  have hD := (integer_coprime_square hm ((j : ℤ)-k) hdiff).dvd_of_dvd_mul_left hd\n  have hDmod : D ≡ 0 [ZMOD (m : ℤ)^2] := Int.modEq_iff_dvd.mpr (by simpa using hD.neg_right)\n  have hN := (hDmod.mul_left (j : ℤ)).symm.trans hJ\n  have hclass : ((s+m*u : ℕ) : ℤ) ≡ ((s+m*v : ℕ) : ℤ) [ZMOD (m : ℤ)^2] := by\n    apply Int.modEq_iff_dvd.mpr\n    simpa only [mul_zero,sub_zero,neg_sub] using hN.dvd\n  exact equal_input_carry hm.pos hu hv hclass\n\n/-- The lower offset residue depends only on the lower input digit. -/\ntheorem offset_residue_of_input_modEq {N N₀ m j : ℕ} (hm : 0<m) (hj : j.Coprime m)\n    (hclass : (N : ℤ) ≡ (N₀ : ℤ) [ZMOD m]) :\n    seedOffset N m j ≡ seedOffset N₀ m j [ZMOD m] := by\n  have ha := representative_eq_of_cofactor_modEq (p:=1) hm hj hclass\n  simp only [one_mul] at ha\n  apply Int.modEq_iff_dvd.mpr\n  refine ⟨(seedRow N₀ m j).b-(seedRow N m j).b,?_⟩\n  unfold seedOffset\n  rw [ha]\n  ring\n\n/-- Each nonzero original tag has at most one distinct partner in its lower offset class. -/\ntheorem residue_partner_unique {N m j k l : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (hj : 1≤j) (hjm : j<m) (hk : 1≤k) (hkm : k<m) (hl : 1≤l) (hlm : l<m)\n    (hjk : j≠k) (hjl : j≠l)\n    (hek : (seedOffset N m j : ZMod m)=(seedOffset N m k : ZMod m))\n    (hel : (seedOffset N m j : ZMod m)=(seedOffset N m l : ZMod m)) : k=l := by\n  let : Fact m.Prime := ⟨hm⟩\n  have hdk : (m : ℤ)∣seedOffset N m j-seedOffset N m k :=\n    (ZMod.intCast_zmod_eq_zero_iff_dvd _ m).mp (by simpa using sub_eq_zero.mpr hek)\n  have hdl : (m : ℤ)∣seedOffset N m j-seedOffset N m l :=\n    (ZMod.intCast_zmod_eq_zero_iff_dvd _ m).mp (by simpa using sub_eq_zero.mpr hel)\n  have hpk := (offset_class_partner_relation hm hN hj hjm hk hkm hdk).resolve_left hjk\n  have hpl := (offset_class_partner_relation hm hN hj hjm hl hlm hdl).resolve_left hjl\n  have hjzero : (j : ZMod m)≠0 := by\n    apply (ZMod.isUnit_iff_coprime j m).mpr ?_ |>.ne_zero\n    exact (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hjm)).symm\n  have hc : 2*(j : ZMod m)-1≠0 := by\n    intro hz\n    apply hjzero\n    linear_combination hpk+(k : ZMod m)*hz\n  have hprod : (2*(j : ZMod m)-1)*((k : ZMod m)-l)=0 := by\n    linear_combination -hpk+hpl\n  have hkl := sub_eq_zero.mp ((mul_eq_zero.mp hprod).resolve_left hc)\n  have hv := congrArg ZMod.val hkl\n  simpa only [ZMod.val_natCast,Nat.mod_eq_of_lt hkm,Nat.mod_eq_of_lt hlm] using hv\n\n/-- Unordered pairs of distinct literal original row labels. -/\nnoncomputable def rowPairs (m : ℕ) : Finset (ℕ×ℕ) :=\n  ((Finset.range (m-1))×ˢ(Finset.range (m-1))).filter fun jk => jk.1<jk.2\n\n/-- Row pairs with equal lower-digit offset residues at the supplied input. -/\nnoncomputable def aliasPairs (s m : ℕ) : Finset (ℕ×ℕ) :=\n  (rowPairs m).filter fun jk =>\n    (seedOffset s m (jk.1+1) : ZMod m)=(seedOffset s m (jk.2+1) : ZMod m)\n\n/-- Row pairs with equal full integer offsets, including the centered carry. -/\nnoncomputable def duplicatePairs (N m : ℕ) : Finset (ℕ×ℕ) :=\n  (rowPairs m).filter fun jk => seedOffset N m (jk.1+1)=seedOffset N m (jk.2+1)\n\n/-- An unordered pair retains two literal positive row tags and their original bounds. -/\ntheorem rowPairs_mem {m j k : ℕ} : (j,k)∈rowPairs m ↔ j+1<m ∧ k+1<m ∧ j<k := by\n  simp only [rowPairs,Finset.mem_filter,Finset.mem_product,Finset.mem_range]\n  omega\n\n/-- A linear bound for all lower-digit alias pairs; no prime progression distribution is assumed. -/\ntheorem aliasPairs_card_le {s m : ℕ} (hm : m.Prime) (hs : m.Coprime s) :\n    (aliasPairs s m).card≤m-1 := by\n  have hmaps : Set.MapsTo Prod.fst (aliasPairs s m : Set (ℕ×ℕ))\n      (Finset.range (m-1) : Set ℕ) := by\n    intro jk hjk\n    have h := (rowPairs_mem.mp (Finset.mem_filter.mp hjk).1).1\n    exact Finset.mem_range.mpr (by omega)\n  have hinj : Set.InjOn Prod.fst (aliasPairs s m : Set (ℕ×ℕ)) := by\n    intro jk hjk jl hjl he\n    have h₁ := rowPairs_mem.mp (Finset.mem_filter.mp hjk).1\n    have h₂ := rowPairs_mem.mp (Finset.mem_filter.mp hjl).1\n    have hsecond : jk.2+1=jl.2+1 := by\n      apply residue_partner_unique hm hs (by omega) h₁.1 (by omega) h₁.2.1\n        (by omega) h₂.2.1 (by omega) (by omega)\n      · exact (Finset.mem_filter.mp hjk).2\n      · simpa only [he] using (Finset.mem_filter.mp hjl).2\n    exact Prod.ext he (by omega)\n  simpa only [Finset.card_range] using Finset.card_le_card_of_injOn _ hmaps hinj\n\n/-- Every exact duplicate is already a lower-digit alias, with no change of row labels. -/\ntheorem duplicatePairs_eq_alias_filter {s m u : ℕ} (hm : m.Prime) :\n    duplicatePairs (s+m*u) m=(aliasPairs s m).filter fun jk =>\n      seedOffset (s+m*u) m (jk.1+1)=seedOffset (s+m*u) m (jk.2+1) := by\n  ext jk\n  simp only [duplicatePairs,aliasPairs,Finset.mem_filter]\n  constructor\n  · rintro ⟨hr,he⟩\n    refine ⟨⟨hr,?_⟩,he⟩\n    have hb := rowPairs_mem.mp hr\n    have hj : (jk.1+1).Coprime m :=\n      (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hb.1)).symm\n    have hk : (jk.2+1).Coprime m :=\n      (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hb.2.1)).symm\n    have hJ := offset_residue_of_input_modEq hm.pos hj (carry_class (s:=s) (u:=u) (v:=0))\n    have hK := offset_residue_of_input_modEq hm.pos hk (carry_class (s:=s) (u:=u) (v:=0))\n    simp only [mul_zero,add_zero] at hJ hK\n    have hclass := hJ.symm.trans (by simpa only [he] using hK)\n    exact (ZMod.intCast_eq_intCast_iff _ _ m).mpr hclass\n  · exact fun h => ⟨h.1.1,h.2⟩\n\n/-- The whole-family duplicate-pair mass, summed across all second carries, is at most linear. -/\ntheorem duplicate_carry_mass_le {s m : ℕ} (hm : m.Prime) (hs : m.Coprime s) :\n    ∑ u∈Finset.range m,(duplicatePairs (s+m*u) m).card≤m-1 := by\n  classical\n  have hrewrite : (∑ u∈Finset.range m,(duplicatePairs (s+m*u) m).card)=\n      ∑ jk∈aliasPairs s m,((Finset.range m).filter fun u =>\n        seedOffset (s+m*u) m (jk.1+1)=seedOffset (s+m*u) m (jk.2+1)).card := by\n    simp_rw [duplicatePairs_eq_alias_filter hm,Finset.card_eq_sum_ones,Finset.sum_filter]\n    exact Finset.sum_comm\n  rw [hrewrite]\n  calc\n    _≤∑ _jk∈aliasPairs s m,1 := by\n      apply Finset.sum_le_sum\n      intro jk hjk\n      apply Finset.card_le_one.mpr\n      intro u hu v hv\n      have hb := rowPairs_mem.mp (Finset.mem_filter.mp hjk).1\n      exact duplicate_pair_unique_carry hm (by omega) hb.1 (by omega) hb.2.1\n        (by omega) (Finset.mem_range.mp (Finset.mem_filter.mp hu).1)\n        (Finset.mem_range.mp (Finset.mem_filter.mp hv).1)\n        (Finset.mem_filter.mp hu).2 (Finset.mem_filter.mp hv).2\n    _=(aliasPairs s m).card := by simp\n    _≤m-1 := aliasPairs_card_le hm hs\n\n/-- An exact finite Markov bound for second carries with many duplicate original targets. -/\ntheorem duplicate_carry_threshold_bound {s m B : ℕ} (hm : m.Prime)\n    (hs : m.Coprime s) :\n    B*((Finset.range m).filter fun u => B≤(duplicatePairs (s+m*u) m).card).card≤m-1 := by\n  classical\n  let bad := (Finset.range m).filter fun u => B≤(duplicatePairs (s+m*u) m).card\n  calc\n    B*bad.card=∑ _u∈bad,B := by simp only [Finset.sum_const,smul_eq_mul,mul_comm]\n    _≤∑ u∈bad,(duplicatePairs (s+m*u) m).card := by\n      apply Finset.sum_le_sum\n      exact fun _ hu => (Finset.mem_filter.mp hu).2\n    _≤∑ u∈Finset.range m,(duplicatePairs (s+m*u) m).card :=\n      Finset.sum_le_sum_of_subset_of_nonneg (Finset.filter_subset _ _) (by intros; omega)\n    _≤m-1 := duplicate_carry_mass_le hm hs\n\n/-- An exponent unit of order greater than m cannot be an additive character of ZMod m. -/\ntheorem no_residue_exponent_hom {G : Type*} [Group G] (g : G) {m : ℕ}\n    (hm : 0<m) (horder : m<orderOf g) :\n    ¬∃ f : ZMod m→+Additive G,f 1=Additive.ofMul g := by\n  rintro ⟨f,hf⟩\n  have hmzero : m • (1 : ZMod m)=0 := by simp only [nsmul_eq_mul,ZMod.natCast_self,mul_one]\n  have he := congrArg f hmzero\n  rw [map_nsmul,hf,map_zero] at he\n  have hg : g^m=1 := by\n    exact congrArg Additive.toMul he\n  exact (not_le_of_gt horder) (orderOf_le_of_pow_eq_one hm hg)\n\n\n/-- A squared monic divisor is bounded by the surplus of exact root occurrences. -/\ntheorem multiset_square_divisor_natDegree_le_surplus\n    {K : Type*} [Field K] [DecidableEq K] (s : Multiset K) {A : K[X]}\n    (hA : A.Monic) (hdvd : A^2 ∣ (s.map fun x => X-C x).prod) :\n    A.natDegree ≤ (s-s.dedup).card := by\n  classical\n  have hP : (s.map fun x => X-C x).prod.Monic := monic_multisetProd_X_sub_C s\n  have hsplits : ((s.map fun x => X-C x).prod).Splits := by\n    apply splits_iff_card_roots.mpr\n    rw [roots_multiset_prod_X_sub_C,natDegree_multiset_prod_X_sub_C_eq_card]\n  have hAdvd : A ∣ (s.map fun x => X-C x).prod :=\n    dvd_trans ⟨A,by rw [pow_two]⟩ hdvd\n  have hsplitA := hsplits.of_dvd hP.ne_zero hAdvd\n  have hpow : (A^2).roots=A.roots+A.roots := by\n    rw [pow_two,roots_mul (mul_ne_zero hA.ne_zero hA.ne_zero)]\n  have hle : A.roots+A.roots ≤ s := by\n    simpa only [hpow,roots_multiset_prod_X_sub_C] using\n      (Polynomial.roots.le_of_dvd hP.ne_zero hdvd)\n  have hrootle : A.roots ≤ s-s.dedup := by\n    apply Multiset.le_iff_count.mpr\n    intro x\n    have hc := Multiset.le_iff_count.mp hle x\n    simp only [Multiset.count_add] at hc\n    rw [Multiset.count_sub,Multiset.count_dedup]\n    by_cases hx : x∈s\n    · simp only [hx, ↓reduceIte]\n      have hpos := Multiset.count_pos.mpr hx\n      omega\n    · simp only [hx, ↓reduceIte]\n      have hz := Multiset.count_eq_zero.mpr hx\n      omega\n  rw [hsplitA.natDegree_eq_card_roots]\n  exact Multiset.card_le_card hrootle\n\n/-- Restricted injectivity preserves the surplus exactly, including all\noriginal repeated occurrences. Global injectivity is not required. -/\ntheorem mapped_surplus_eq\n    {α β : Type*} [DecidableEq α] [DecidableEq β]\n    (s : Multiset α) (f : α→β) (hinj : Set.InjOn f s.toFinset) :\n    (s.map f-(s.map f).dedup).card=(s-s.dedup).card := by\n  rw [Multiset.card_sub (Multiset.dedup_le _),Multiset.card_map,\n    Multiset.card_sub (Multiset.dedup_le _)]\n  congr 1\n  rw [←Multiset.card_toFinset,Multiset.toFinset_map,\n    Finset.card_image_of_injOn hinj,Multiset.card_toFinset]\n\n/-- A field root map injective on the supplied integer offsets preserves\nthe original offset-surplus bound for every squared monic divisor. -/\ntheorem list_square_divisor_natDegree_le_offset_surplus\n    {K : Type*} [Field K] (ds : List ℤ) (f : ℤ→K)\n    (hinj : Set.InjOn f ds.toFinset) {A : K[X]} (hA : A.Monic)\n    (hdvd : A^2 ∣ ((ds.map f).map fun x => X-C x).prod) :\n    A.natDegree≤((ds : Multiset ℤ)-(ds : Multiset ℤ).dedup).card := by\n  classical\n  have hdvd' : A^2 ∣ (((ds : Multiset ℤ).map f).map fun x => X-C x).prod := by\n    simpa using hdvd\n  have h := multiset_square_divisor_natDegree_le_surplus\n    ((ds : Multiset ℤ).map f) hA hdvd'\n  rw [mapped_surplus_eq (ds : Multiset ℤ) f (by simpa using hinj)] at h\n  exact h\n\n/-- The actual short offset window embeds into exponent targets whenever\nthe local order exceeds its width. The additive N phase cancels. -/\ntheorem exponent_targets_injOn_of_short_offsets\n    {R : Type*} [CommRing R] (u : Rˣ) (N m : ℕ) (ds : List ℤ)\n    (horder : 4*m^2<orderOf u)\n    (hbound : ∀ d∈ds,-3*(m : ℤ)^2≤d ∧ d≤(m : ℤ)^2) :\n    Set.InjOn (fun d : ℤ => ((u^((N : ℤ)+d) : Rˣ) : R)) ds.toFinset := by\n  intro a ha b hb he\n  have hba := hbound a (List.mem_toFinset.mp ha)\n  have hbb := hbound b (List.mem_toFinset.mp hb)\n  by_contra hab\n  have hexp : (N : ℤ)+a≠(N : ℤ)+b := by omega\n  have hgap : (((N : ℤ)+a)-((N : ℤ)+b)).natAbs≤4*m^2 := by\n    have h : |((N : ℤ)+a)-((N : ℤ)+b)|≤4*(m : ℤ)^2 := by\n      rw [abs_le]\n      constructor <;> omega\n    rw [←Int.natCast_natAbs] at h\n    exact_mod_cast h\n  have hnonzero := zpow_short_gap_ne_zero u ((N : ℤ)+a) ((N : ℤ)+b)\n    hexp (hgap.trans_lt horder)\n  exact hnonzero (sub_eq_zero.mpr he)\n\n/-- One hidden prime-field specialization of the exact offset count. -/\ntheorem long_left_exponent_square_divisor_le_offset_surplus\n    {p q m : ℕ} (hp : p.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (ds : List ℤ)\n    (hbound : ∀ d∈ds,-3*(m : ℤ)^2≤d ∧ d≤(m : ℤ)^2)\n    {A : (ZMod p)[X]} (hA : A.Monic)\n    (hdvd : A^2 ∣ ((ds.map fun d =>\n      (((leftUnit (projectedUnit g m))^(((p*q : ℕ) : ℤ)+d) : (ZMod p)ˣ) : ZMod p)).map\n        fun x => X-C x).prod) :\n    A.natDegree≤((ds : Multiset ℤ)-(ds : Multiset ℤ).dedup).card := by\n  let : Fact p.Prime := ⟨hp⟩\n  apply list_square_divisor_natDegree_le_offset_surplus ds _ _ hA hdvd\n  apply exponent_targets_injOn_of_short_offsets\n    (leftUnit (projectedUnit g m)) (p*q) m ds _ hbound\n  have h := hlong.2.2.2.1.1\n  nlinarith only [h]\n\n/-- Original row labels, with their integer offsets left untouched in\nthe surplus on the right. No deduplication of the source list is made. -/\ntheorem long_left_tag_square_divisor_le_offset_surplus\n    {p q m : ℕ} (hp : p.Prime) (hm : 4≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (tags : List ℕ) (htags : ∀ j∈tags,1≤j ∧ j<m)\n    {A : (ZMod p)[X]} (hA : A.Monic)\n    (hdvd : A^2 ∣ (tags.map fun j => X-C\n      (((leftUnit (projectedUnit g m))^(((p*q : ℕ) : ℤ)+seedOffset (p*q) m j) :\n        (ZMod p)ˣ) : ZMod p)).prod) :\n    A.natDegree≤\n      ((tags.map (seedOffset (p*q) m) : Multiset ℤ)-\n        (tags.map (seedOffset (p*q) m) : Multiset ℤ).dedup).card := by\n  apply long_left_exponent_square_divisor_le_offset_surplus hp g hlong\n    (tags.map (seedOffset (p*q) m)) _ hA\n      (by simpa only [List.map_map,Function.comp_def] using hdvd)\n  intro d hd\n  obtain ⟨j,hj,rfl⟩ := List.mem_map.mp hd\n  exact seedOffset_bounds (by omega : 1<m) (htags j hj).1 (htags j hj).2\n\n/-- The ORIGINAL modulus-N carrier, transported to one hidden field.\nIts degree and literal offset multiplicities are preserved; the field\nprojection is proof-side only. -/\ntheorem original_square_divisor_natDegree_le_offset_surplus\n    {p q m : ℕ} (hp : p.Prime) (hm : 4≤m) (hmprime : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    {A : (ZMod (p*q))[X]} (hA : A.Monic)\n    (hdvd : A^2 ∣ targetPolynomial (seedTargets (projectedUnit g m) m)) :\n    A.natDegree≤\n      (((List.range (m-1)).map fun r => seedOffset (p*q) m (r+1) : Multiset ℤ)-\n        ((List.range (m-1)).map fun r => seedOffset (p*q) m (r+1) :\n          Multiset ℤ).dedup).card := by\n  let : Fact p.Prime := ⟨hp⟩\n  let f := ZMod.castHom (dvd_mul_right p q) (ZMod p)\n  let h := projectedUnit g m\n  let ds := (List.range (m-1)).map fun r => seedOffset (p*q) m (r+1)\n  have hbound : ∀ d∈ds,-3*(m : ℤ)^2≤d ∧ d≤(m : ℤ)^2 := by\n    intro d hd\n    obtain ⟨r,hr,rfl⟩ := List.mem_map.mp hd\n    have hr' := List.mem_range.mp hr\n    exact seedOffset_bounds (by omega : 1<m) (by omega) (by omega)\n  have hstep (r : ℕ) (hr : r∈List.range (m-1)) :\n      f (((progressionSeed h (p*q) m (r+1)).step : (ZMod (p*q))ˣ) : ZMod (p*q))=\n        (((leftUnit h)^(((p*q : ℕ) : ℤ)+seedOffset (p*q) m (r+1)) :\n          (ZMod p)ˣ) : ZMod p) := by\n    have hr' := List.mem_range.mp hr\n    have hjcop : (r+1).Coprime m :=\n      (hmprime.coprime_iff_not_dvd.mpr\n        (Nat.not_dvd_of_pos_of_lt (by omega) (by omega))).symm\n    change (leftUnit ((progressionSeed h (p*q) m (r+1)).step) : ZMod p)=_\n    rw [seed_step_offset _ hmprime.pos hjcop]\n    simp only [leftUnit,map_zpow]\n  have hpoly : (targetPolynomial (seedTargets h m)).map f=\n      ((ds.map fun d =>\n        (((leftUnit h)^(((p*q : ℕ) : ℤ)+d) : (ZMod p)ˣ) : ZMod p)).map\n          fun x => X-C x).prod := by\n    unfold targetPolynomial seedTargets progressionSeeds\n    rw [Polynomial.map_list_prod]\n    simp only [ds,List.map_map,Function.comp_def,Polynomial.map_sub,\n      Polynomial.map_X,Polynomial.map_C]\n    congr 1\n    apply List.map_congr_left\n    intro r hr\n    rw [hstep r hr]\n  have hmapdvd : (A.map f)^2 ∣ (targetPolynomial (seedTargets h m)).map f := by\n    simpa only [Polynomial.map_pow] using Polynomial.map_dvd f hdvd\n  rw [hpoly] at hmapdvd\n  have hdegree := long_left_exponent_square_divisor_le_offset_surplus hp g hlong\n    ds hbound (hA.map f) hmapdvd\n  rw [hA.natDegree_map f] at hdegree\n  exact hdegree\n\n\nsection PairCount\n\nvariable {α : Type*} [DecidableEq α]\n\n/-- Equal-root pairs with increasing source indices. -/\nnoncomputable def indexedEqualPairs (f : ℕ→α) (n : ℕ) : Finset (ℕ×ℕ) :=\n  ((Finset.range n)×ˢ(Finset.range n)).filter fun ij =>\n    ij.1 < ij.2 ∧ f ij.1=f ij.2\n\n/-- Each surplus occurrence contributes at least one pair with an earlier equal value. -/\ntheorem range_surplus_le_equal_pairs (f : ℕ→α) (n : ℕ) :\n    n-((Finset.range n).image f).card≤(indexedEqualPairs f n).card := by\n  induction n with\n  | zero => simp [indexedEqualPairs]\n  | succ n ih =>\n    have hsubset : indexedEqualPairs f n⊆indexedEqualPairs f (n+1) := by\n      intro ij hij\n      simp only [indexedEqualPairs,Finset.mem_filter,Finset.mem_product,\n        Finset.mem_range] at hij ⊢\n      exact ⟨⟨by omega,by omega⟩,hij.2⟩\n    have hcard := Finset.card_le_card hsubset\n    have himage : ((Finset.range n).image f).card≤n := by\n      exact (Finset.card_image_le).trans (by simp)\n    by_cases hmem : f n∈(Finset.range n).image f\n    · obtain ⟨i,hi,hfi⟩ := Finset.mem_image.mp hmem\n      have hinew : (i,n)∈indexedEqualPairs f (n+1) := by\n        simp only [indexedEqualPairs,Finset.mem_filter,Finset.mem_product,\n          Finset.mem_range]\n        have hilt := Finset.mem_range.mp hi\n        exact ⟨⟨by omega,by omega⟩,hilt,hfi⟩\n      have hinot : (i,n)∉indexedEqualPairs f n := by\n        simp only [indexedEqualPairs,Finset.mem_filter,Finset.mem_product,\n          Finset.mem_range]\n        omega\n      have hinsert : insert (i,n) (indexedEqualPairs f n)⊆indexedEqualPairs f (n+1) :=\n        Finset.insert_subset_iff.mpr ⟨hinew,hsubset⟩\n      have hinc : (indexedEqualPairs f n).card+1≤(indexedEqualPairs f (n+1)).card := by\n        simpa only [Finset.card_insert_of_notMem hinot] using Finset.card_le_card hinsert\n      rw [Finset.range_add_one,Finset.image_insert,Finset.insert_eq_of_mem hmem]\n      omega\n    · rw [Finset.range_add_one,Finset.image_insert,Finset.card_insert_of_notMem hmem]\n      omega\n\n/-- Multiset form: no bound on individual fibers is required. -/\ntheorem indexed_multiset_surplus_le_equal_pairs (f : ℕ→α) (n : ℕ) :\n    ((Finset.range n).val.map f-((Finset.range n).val.map f).dedup).card≤\n      (indexedEqualPairs f n).card := by\n  rw [Multiset.card_sub (Multiset.dedup_le _),Multiset.card_map,\n    ←Multiset.card_toFinset]\n  simpa only [Finset.card_range,Finset.range_val,Multiset.card_range,Multiset.toFinset_map,\n    Multiset.toFinset_range] using range_surplus_le_equal_pairs f n\n\n/-- List-of-range form matching the original offset list. -/\ntheorem range_list_surplus_le_equal_pairs (f : ℕ→α) (n : ℕ) :\n    (((List.range n).map f : Multiset α)-\n      ((List.range n).map f : Multiset α).dedup).card≤\n      (indexedEqualPairs f n).card := by\n  simpa only [Finset.range_val,←Multiset.coe_range,Multiset.map_coe] using\n    indexed_multiset_surplus_le_equal_pairs f n\n\n\nend PairCount\n\n/-- A squared monic divisor of the literal whole-family carrier is bounded\nby the unordered exact duplicate-pair count, with all row labels retained. -/\ntheorem original_square_divisor_natDegree_le_duplicatePairs\n    {p q m : ℕ} (hp : p.Prime) (hm : 4≤m) (hmprime : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    {A : (ZMod (p*q))[X]} (hA : A.Monic)\n    (hdvd : A^2 ∣ targetPolynomial (seedTargets (projectedUnit g m) m)) :\n    A.natDegree≤(duplicatePairs (p*q) m).card := by\n  have hsurplus := range_list_surplus_le_equal_pairs\n    (fun r => seedOffset (p*q) m (r+1)) (m-1)\n  have hpairs : indexedEqualPairs (fun r => seedOffset (p*q) m (r+1)) (m-1)=\n      duplicatePairs (p*q) m := by\n    ext jk\n    simp only [indexedEqualPairs,duplicatePairs,rowPairs,Finset.mem_filter,and_assoc]\n  rw [hpairs] at hsurplus\n  exact (original_square_divisor_natDegree_le_offset_surplus hp hm hmprime g hlong hA hdvd).trans\n    hsurplus\n\nend RiemannGaussian.SemiprimeOffsetCarryObstruction\n","RiemannGaussian.SemiprimePaidEnumeratedSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidFiniteEnumerations\nimport RiemannGaussian.SemiprimeMaterializedOriginalSource\n\n/-! # Original source acquisition including actual enumeration generation\nOnly original indexed network metadata and numerical parameters are inputs.\nAll enumerations are acquired by the NEW paid constructor before word search.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimePaidEnumeratedSource\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen SemiprimeMaterializedSourceUniversal SemiprimeJetArray\nvariable {n F r Q : ℕ} [NeZero r]\n\n/-- Execute finite data acquisition and source acquisition with BOTH reports retained. -/\ndef acquire (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R : ℕ) : Run (Array (Array (Array ℚ))) :=\n  let en := SemiprimePaidFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let source := SemiprimeMaterializedOriginalSource.acquire owner Sigma.fst en.value eps R\n  ⟨source.value,en.work+source.work+1⟩\n\n/-- Exact original immutable arrays, not just matching membership or size. -/\ntheorem acquire_value (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R : ℕ) :\n    (acquire (r:=r) (Q:=Q) arity coordinate eps R).value=\n      (SemiprimeMaterializedOriginalSource.acquire\n        (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2) Sigma.fst\n        (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R).value := by\n  simp only [acquire,SemiprimePaidFiniteEnumerations.indexed_value]\n\n/-- Existing source accessors read the exact original built-layout coefficient. -/\ntheorem acquire_coefficient (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R : ℕ)\n    (e : Fin F) (i : Fin (arity e)) (v : Fin n) (k : ℕ) (hk : k≤R) :\n    coefficient (SemiprimeSourceArrayAcquisition.read\n      (SemiprimeFiniteEnumerations.indexed n F r Q arity).incidences\n      (acquire (r:=r) (Q:=Q) arity coordinate eps R).value ⟨e,i⟩ v) k=\n      ((SemiprimeSourceLayout.builtLayout\n        (fun j : (f : Fin F) × Fin (arity f) => coordinate j.1 j.2) Sigma.fst\n        (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R).row ⟨e,i⟩ v).coeff k := by\n  rw [acquire_value]\n  exact SemiprimeMaterializedOriginalSource.acquire_coefficient (n:=n) (r:=r) (Q:=Q)\n    (fun j : (f : Fin F) × Fin (arity f) => coordinate j.1 j.2)\n    (fun j : (f : Fin F) × Fin (arity f) => j.1)\n    (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R ⟨e,i⟩ v k hk\n\n/-- Enlarging the explicitly acquired word menu can only enlarge the source work envelope. -/\ntheorem sourceBudget_mono_words (M n a A D T N Q R start : ℕ) (ha : a≤A) :\n    SemiprimeMaterializedOriginalSource.budget M n a D T N Q R start ≤\n      SemiprimeMaterializedOriginalSource.budget M n A D T N Q R start := by\n  unfold SemiprimeMaterializedOriginalSource.budget\n    SemiprimeMaterializedSourceWords.producerBudget\n    SemiprimeMaterializedScoreSearch.evaluatorBudget\n  gcongr\n\n/-- The actual complete finite-data and source producer envelope. -/\ndef budget (n F r Q R M : ℕ) : ℕ :=\n  SemiprimePaidFiniteEnumerations.budget n F r Q M+\n    SemiprimeMaterializedOriginalSource.budget M n (r^Q) (r^(2*Q)) (M^2+Q*n^2) (n+F) Q R\n      (SemiprimeMaterializedSourcePullback.centered r Q R)+1\n\n/-- Initial finite list generation is no longer omitted from this executed source clock. -/\ntheorem acquire_work (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R : ℕ) :\n    (acquire (r:=r) (Q:=Q) arity coordinate eps R).work ≤ budget n F r Q R (∑ e,arity e) := by\n  let en := SemiprimePaidFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  have he : en.work ≤ SemiprimePaidFiniteEnumerations.budget n F r Q (∑ e,arity e) := by\n    exact SemiprimePaidFiniteEnumerations.indexed_work n F r Q arity\n  have hs := SemiprimeMaterializedOriginalSource.acquire_work owner Sigma.fst en.value eps R\n  have ht : en.value.wordTail.length≤r^Q := by\n    rw [SemiprimePaidFiniteEnumerations.indexed_value]\n    exact (List.length_filter_le _ _).trans_eq (SemiprimeFiniteEnumerations.words_length r Q)\n  rw [SemiprimePaidFiniteEnumerations.indexed_incidence_length,\n    SemiprimePaidFiniteEnumerations.indexed_universal_length,\n    SemiprimePaidFiniteEnumerations.indexed_score_length,\n    SemiprimePaidFiniteEnumerations.indexed_indices_length] at hs\n  have hm := sourceBudget_mono_words (∑ e,arity e) n en.value.wordTail.length (r^Q)\n    (r^(2*Q)) ((∑ e,arity e)^2+Q*n^2) (n+F) Q R\n    (SemiprimeMaterializedSourcePullback.centered r Q R) ht\n  unfold acquire budget\n  dsimp only\n  change en.work+_+1≤_\n  exact Nat.add_le_add_right (Nat.add_le_add he (hs.trans hm)) 1\n\nend RiemannGaussian.SemiprimePaidEnumeratedSource\n","RiemannGaussian.SemiprimePaidOriginalConstraints":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidConstraintAcquisition\nimport RiemannGaussian.SemiprimeMaterializedOriginalSource\n\n/-! # Original searched network to stored integer constraints\nThe actual searched labels, packing and universal numerators are constructed\ninternally. There is no label, row, or row-acquisition budget oracle.\nFinite-enumeration generation and primitive bit refinements remain separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimePaidOriginalConstraints\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes Subexp.ConstructivePacking\nopen SemiprimeMaterializedSourceUniversal\nvariable {I E : Type} [Fintype I] [DecidableEq I] [DecidableEq E] {n r Q : ℕ}\n\n/-- Acquire the original computed label search, then all original integer rows. -/\ndef acquire (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (eps : ℚ) (R : ℕ) :\n    Run (SemiprimePaidConstraintAcquisition.Family I r Q) :=\n  let x := eps*(en.incidences.values.length : ℚ)/(en.types.values.length : ℚ)\n  let y := (n : ℚ)/(2*(r : ℚ))\n  let producer := SemiprimeMaterializedSourceWords.producer owner factor en.wordFirst en.wordTail\n    en.terms.values en.indices.values x y\n  let out := SemiprimePaidConstraintAcquisition.acquire (Subexp.TailInterval.intervalStart r Q R) R\n    en.incidences.values owner en.types.values producer.value\n  ⟨out.value,producer.work+out.work+en.incidences.values.length+en.types.values.length+25⟩\n\n/-- Exact original padded row order after the actual deterministic source search. -/\ntheorem acquire_entries (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (eps : ℚ) (R : ℕ) :\n    (acquire owner factor en eps R).value.entries=\n      (List.finRange Q).map (fun t => (List.finRange r).map (fun g =>\n        (SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.map\n          (fun j => (List.finRange n).map (SemiprimePaddedBlockExecution.sourceRow\n            (SemiprimeSourceConstraintAcquisition.packing owner factor en eps) owner\n            (fun u => u.head t) g\n            (SemiprimeUniversalSourceExecution.constraint (Subexp.TailInterval.intervalStart r Q R) R t g) j)))) :=\n  SemiprimePaidConstraintAcquisition.acquire_entries\n    (SemiprimeFiniteEnumerations.searchPacking owner factor en eps)\n    (Subexp.TailInterval.intervalStart r Q R) R owner _\n    (SemiprimeMaterializedOriginalSource.label_value owner factor en eps)\n\n/-- Every scalar/list work term depends only on the original network dimensions. -/\ndef budget (M n A D T N Q R start r blocks : ℕ) : ℕ :=\n  SemiprimeMaterializedSourceWords.producerBudget A T N Q+\n  SemiprimePaidConstraintAcquisition.budget start R M n D (4*N+6*(N+1)^2+7) Q r blocks+M+D+25\n\n/-- Closed label-search and complete integer-row acquisition ledger. -/\ntheorem acquire_work (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (eps : ℚ) (R : ℕ) :\n    (acquire owner factor en eps R).work≤\n      budget en.incidences.values.length n en.wordTail.length en.types.values.length\n        en.terms.values.length en.indices.values.length Q R\n        (Subexp.TailInterval.intervalStart r Q R) r\n        (SemiprimeFiniteEnumerations.searchPacking owner factor en eps).blockCount := by\n  let x := eps*(en.incidences.values.length : ℚ)/(en.types.values.length : ℚ)\n  let y := (n : ℚ)/(2*(r : ℚ))\n  let producer := SemiprimeMaterializedSourceWords.producer owner factor en.wordFirst en.wordTail\n    en.terms.values en.indices.values x y\n  have hp := SemiprimeMaterializedSourceWords.producer_work owner factor en.wordFirst en.wordTail\n    en.terms.values en.indices.values x y\n  have ho := SemiprimePaidConstraintAcquisition.acquire_work\n    (SemiprimeFiniteEnumerations.searchPacking owner factor en eps)\n    (Subexp.TailInterval.intervalStart r Q R) R owner producer.value\n    (SemiprimeMaterializedOriginalSource.label_value owner factor en eps)\n    (4*en.indices.values.length+6*(en.indices.values.length+1)^2+7)\n    (SemiprimeMaterializedSourceWords.producer_label_work owner factor en.wordFirst en.wordTail\n      en.terms.values en.indices.values x y)\n  unfold acquire budget\n  dsimp only\n  exact Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add hp ho) _) _) 25\n\n/-- Four real finite-list scans read one stored original-coordinate entry. -/\ndef read (family : SemiprimePaidConstraintAcquisition.Family I r Q)\n    (t g j v : ℕ) : Run ℤ :=\n  let node := SemiprimePaidConstraintCache.getRun family.entries t\n  let head := SemiprimePaidConstraintCache.getRun (node.value.getD []) g\n  let row := SemiprimePaidConstraintCache.getRun (head.value.getD []) j\n  let entry := SemiprimePaidConstraintCache.getRun (row.value.getD []) v\n  ⟨entry.value.getD 0,node.work+head.work+row.work+entry.work+4⟩\n\nomit [Fintype I] [DecidableEq I] [DecidableEq E] in\n/-- Reading a well-indexed stored map uses the intended original index. -/\ntheorem getRun_map {α β : Type*} (xs : List α) (f : α → β) (j : Fin xs.length) :\n    (SemiprimePaidConstraintCache.getRun (xs.map f) j.val).value=some (f (xs.get j)) := by\n  rw [SemiprimePaidConstraintCache.getRun_value,List.getElem?_map,\n    List.getElem?_eq_getElem j.isLt]\n  rfl\n\nomit [Fintype I] [DecidableEq I] [DecidableEq E] in\n/-- A stored finite-coordinate map is read by its literal coordinate. -/\ntheorem getRun_fin {α : Type*} {k : ℕ} (f : Fin k → α) (j : Fin k) :\n    (SemiprimePaidConstraintCache.getRun ((List.finRange k).map f) j.val).value=some (f j) := by\n  rw [SemiprimePaidConstraintCache.getRun_value,List.getElem?_map,\n    List.getElem?_eq_getElem (by simp),List.getElem_finRange]\n  rfl\n\n/-- On every original head column the stored entry is exactly the old integer matrix. -/\ntheorem read_acquire (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (eps : ℚ) (R : ℕ)\n    (t : Fin Q) (g : Fin r)\n    (j : Fin (SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.length)\n    (v : Fin n) (hv : SemiprimeSourceConstraintAcquisition.head owner factor en eps t v=g) :\n    (read (acquire owner factor en eps R).value t.val g.val j.val v.val).value=\n      SemiprimeSourceConstraintAcquisition.matrix owner factor en eps R t g j v := by\n  unfold read\n  dsimp only\n  rw [acquire_entries,getRun_fin,Option.getD_some,getRun_fin,Option.getD_some,\n    getRun_map,Option.getD_some,getRun_fin,Option.getD_some]\n  unfold SemiprimeSourceConstraintAcquisition.matrix\n  rw [ite_eq_left hv]\n  rfl\n\n/-- The actual four scans have a linear cell-visit bound in the stored dimensions. -/\ntheorem read_acquire_work (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (eps : ℚ) (R : ℕ)\n    (t : Fin Q) (g : Fin r)\n    (j : Fin (SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.length)\n    (v : Fin n) :\n    (read (acquire owner factor en eps R).value t.val g.val j.val v.val).work≤\n      2*(Q+r+(SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.length+n)+8 := by\n  let family := (acquire owner factor en eps R).value\n  let node := SemiprimePaidConstraintCache.getRun family.entries t.val\n  let head := SemiprimePaidConstraintCache.getRun (node.value.getD []) g.val\n  let row := SemiprimePaidConstraintCache.getRun (head.value.getD []) j.val\n  have ht := SemiprimePaidConstraintCache.getRun_work family.entries t.val\n  have hg := SemiprimePaidConstraintCache.getRun_work (node.value.getD []) g.val\n  have hj := SemiprimePaidConstraintCache.getRun_work (head.value.getD []) j.val\n  have hv := SemiprimePaidConstraintCache.getRun_work (row.value.getD []) v.val\n  have hn : family.entries.length=Q := by\n    rw [acquire_entries,List.length_map,List.length_finRange]\n  have hgl : (node.value.getD []).length=r := by\n    dsimp only [node,family]\n    rw [acquire_entries,getRun_fin,Option.getD_some,List.length_map,List.length_finRange]\n  have hjl : (head.value.getD []).length=\n      (SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.length := by\n    dsimp only [head,node,family]\n    rw [acquire_entries,getRun_fin,Option.getD_some,getRun_fin,Option.getD_some,List.length_map]\n  have hvl : (row.value.getD []).length=n := by\n    dsimp only [row,head,node,family]\n    rw [acquire_entries,getRun_fin,Option.getD_some,getRun_fin,Option.getD_some,\n      getRun_map,Option.getD_some,List.length_map,List.length_finRange]\n  rw [hn] at ht\n  rw [hgl] at hg\n  rw [hjl] at hj\n  rw [hvl] at hv\n  change node.work≤2*Q+1 at ht\n  change head.work≤2*r+1 at hg\n  change row.work≤2*(SemiprimeSourceConstraintAcquisition.rowIndices owner factor en eps).values.length+1 at hj\n  change node.work+head.work+row.work+\n    (SemiprimePaidConstraintCache.getRun (row.value.getD []) v.val).work+4≤_\n  omega\n\n/-- Closed fixed-polynomial scalar/list envelope for the original searched family. -/\ndef polynomial (M n A D T N Q R start r : ℕ) : ℕ :=\n  SemiprimeMaterializedSourceWords.producerBudget A T N Q+\n  SemiprimePaidConstraintAcquisition.polynomial start R M n D (4*N+6*(N+1)^2+7) Q r+M+D+25\n\n/-- No packing-size or label-work advice remains in the native acquisition envelope. -/\ntheorem acquire_work_native (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (hr : 2≤r) (eps : ℚ) (R : ℕ) :\n    (acquire owner factor en eps R).work≤\n      polynomial en.incidences.values.length n en.wordTail.length en.types.values.length\n        en.terms.values.length en.indices.values.length Q R\n        (Subexp.TailInterval.intervalStart r Q R) r := by\n  apply (acquire_work owner factor en eps R).trans\n  have hD : 2^(2*Q)≤en.types.values.length := by\n    rw [en.types.length_eq_card,card_universalType]\n    simpa only [show Q*(1+1)=2*Q by omega] using Nat.pow_le_pow_left hr (2*Q)\n  have hb := SemiprimePaidConstraintAcquisition.blocks_le\n    (SemiprimeFiniteEnumerations.searchPacking owner factor en eps)\n  have hc := SemiprimePaidConstraintAcquisition.budget_polynomial\n    (Subexp.TailInterval.intervalStart r Q R) R en.incidences.values.length n en.types.values.length\n    (4*en.indices.values.length+6*(en.indices.values.length+1)^2+7) Q r\n    (SemiprimeFiniteEnumerations.searchPacking owner factor en eps).blockCount hD hb\n  unfold budget polynomial\n  omega\n\nend RiemannGaussian.SemiprimePaidOriginalConstraints\n","RiemannGaussian.SemiprimePrefixEntryWords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeAcquiredPrefixSearch\nimport RiemannGaussian.SemiprimeLocalBits\n\n/-! # Original checker bits directly supply physical local entries\n\nThe actual Boolean checker and every-occurrence restriction execute once.\nTheir accepted bit becomes the one-cell numerator, without an integer or\nrational encoding pass. Finite prefix/address implementation remains the same\nexplicit boundary as the original prefix controller.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimePrefixEntryWords\nopen SemiprimeMacroEntryBitPrimitives SemiprimeLocalBits\nopen SemiprimeBitIndexClipping SemiprimeBitArithmetic\nvariable {n F : ℕ}\n\n/-- Materialize the actual accepted bit and retain checker and prefix-scan work. -/\ndef entry (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) : EntryWord :=\n  let original := base e input\n  let accepted := original.accepted && SemiprimeAcquiredPrefixSearch.prefixGate arity coordinate fixed e input\n  ⟨⟨false,[accepted]⟩,original.clock+fixed.length*(3*arity e+2)+4⟩\n\n/-- The physical one-cell integer is exactly the original restricted entry. -/\ntheorem entry_value (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).bits.value =\n      (SemiprimeAcquiredPrefixSearch.entry arity coordinate base fixed e input).value := by\n  simp [entry,SemiprimeAcquiredPrefixSearch.entry,SignedWord.value,bitValue,bitNat]\n\n/-- No output-height advice is needed for the actual original Boolean table. -/\ntheorem entry_abs (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).bits.value.natAbs ≤ 1 := by\n  rw [entry_value]\n  exact SemiprimeAcquiredPrefixSearch.entry_abs arity coordinate base fixed e input\n\n/-- The original checker produces a literal single-cell magnitude. -/\ntheorem entry_length (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).bits.magnitude.length=1 := rfl\n\n/-- Word construction adds three cells to the retained original entry ledger. -/\ntheorem entry_clock (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).clock =\n      (SemiprimeAcquiredPrefixSearch.entry arity coordinate base fixed e input).arithmetic+3 := by\n  simp only [entry,SemiprimeAcquiredPrefixSearch.entry,Nat.add_assoc]\n\n/-- Uniform costs are supplied by the real checker, with the prefix scan retained. -/\ntheorem entry_clock_le (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (A w : ℕ)\n    (hw : ∀ e, arity e≤w) (hbase : ∀ e input, (base e input).clock≤A)\n    (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).clock ≤ A+fixed.length*(3*w+2)+4 := by\n  change (base e input).clock+fixed.length*(3*arity e+2)+4 ≤ _\n  gcongr\n  exact hbase e input\n  exact hw e\n\nend RiemannGaussian.SemiprimePrefixEntryWords\n","RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeShiftedNormAcquisitionObstruction\nimport Mathlib.Combinatorics.Additive.Energy\n\n/-!\n# Original carry energy obstructs small positive-moment carriers\n\nEvery nontrivial four-tag pair-sum of actual original offsets can occur\nat only one second carry. Their full carry mass is at most cubic in the\nrow count. A sufficiently large local period transfers the exact integer\nenergy to the literal original seed family without losing multiplicities.\nFinite group energy bounds then force a large geometric-grid support.\nPositive pole retention uses a per-row fiber bound, so it works even\nwhen the total raw grid mass exceeds the field characteristic.\n\nThe investigation journal combines these finite source theorems with an\nunconditional classical actual-input count. Its all-width dense-carrier\ncost obstruction is representation-specific; implicit circuits, signed\nweights, internal pivots and general factoring are outside the contract.\nNo analytic infinitude or bit-cost assertion is a new Lean axiom here.\n-/\n\nnamespace RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction\n\nopen scoped BigOperators Pointwise Combinatorics.Additive\nopen Polynomial\nopen SemiprimeGlobalPhaseCancellation SemiprimeDenseRowCarries\nopen SemiprimeOffsetCarryObstruction SemiprimeShiftedNormAcquisitionObstruction\nopen SemiprimeSeedMomentPoleRetention\n\nopen RiemannGaussian.SemiprimeOffsetCarryObstruction\nopen RiemannGaussian.SemiprimeGlobalPhaseCancellation\n\n/-- Equal quadratic pair values have nonzero carry slope unless the unordered pairs agree. -/\ntheorem quadratic_pair_slope_ne_zero {F : Type*} [Field F]\n    {s x y z w : F} (hs : s≠0) (htwo : (2 : F)≠0)\n    (hnontriv : ¬((x=z ∧ y=w) ∨ (x=w ∧ y=z)))\n    (hquad : s*(x^2-2*x)+s*(y^2-2*y)=s*(z^2-2*z)+s*(w^2-2*w)) :\n    x+y-z-w≠0 := by\n  intro hlin\n  have hmul : (2*s)*(x*y-z*w)=0 := by\n    linear_combination s*(x+y+z+w-2)*hlin-hquad\n  have hprod : x*y=z*w :=\n    sub_eq_zero.mp ((mul_eq_zero.mp hmul).resolve_left (mul_ne_zero htwo hs))\n  have hroot : (x-z)*(x-w)=0 := by\n    linear_combination x*hlin-hprod\n  rcases mul_eq_zero.mp hroot with hxz | hxw\n  · have hxz' := sub_eq_zero.mp hxz\n    have hyw : y=w := by linear_combination hlin-hxz'\n    exact hnontriv (Or.inl ⟨hxz',hyw⟩)\n  · have hxw' := sub_eq_zero.mp hxw\n    have hyz : y=z := by linear_combination hlin-hxw'\n    exact hnontriv (Or.inr ⟨hxw',hyz⟩)\n\n/-- The source-exact coefficient of a nontrivial original-row pair-sum carry is a unit. -/\ntheorem actual_pair_carry_coefficient_ne_zero {s m i j k l u : ℕ}\n    (hm : m.Prime) (hm2 : 2 < m) (hs : m.Coprime s)\n    (hi : 1 ≤ i) (him : i < m) (hj : 1 ≤ j) (hjm : j < m)\n    (hk : 1 ≤ k) (hkm : k < m) (hl : 1 ≤ l) (hlm : l < m)\n    (hnontriv : ¬((i=k ∧ j=l) ∨ (i=l ∧ j=k)))\n    (he : seedOffset (s+m*u) m i+seedOffset (s+m*u) m j=\n      seedOffset (s+m*u) m k+seedOffset (s+m*u) m l) :\n    (((j : ℤ)*k*l+(i : ℤ)*k*l-(i : ℤ)*j*l-(i : ℤ)*j*k : ℤ) : ZMod m)≠0 := by\n  let : Fact m.Prime := ⟨hm⟩\n  have hcop {r : ℕ} (hr : 1 ≤ r) (hrm : r < m) : r.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hrm)).symm\n  have hz {r : ℕ} (hr : 1 ≤ r) (hrm : r < m) : (r : ZMod m)≠0 :=\n    ((ZMod.isUnit_iff_coprime r m).mpr (hcop hr hrm)).ne_zero\n  have hinv {a b : ℕ} (ham : a < m) (hbm : b < m)\n      (h : (a : ZMod m)⁻¹=(b : ZMod m)⁻¹) : a=b := by\n    have heq : (a : ZMod m)=(b : ZMod m) := inv_injective h\n    have hval := congrArg ZMod.val heq\n    simpa only [ZMod.val_natCast,Nat.mod_eq_of_lt ham,Nat.mod_eq_of_lt hbm] using hval\n  have hi0 := hz hi him\n  have hj0 := hz hj hjm\n  have hk0 := hz hk hkm\n  have hl0 := hz hl hlm\n  have hs0 : (s : ZMod m)≠0 := ((ZMod.isUnit_iff_coprime s m).mpr hs.symm).ne_zero\n  have hN0 : ((s+m*u : ℕ) : ZMod m)≠0 := by\n    simpa only [Nat.cast_add,Nat.cast_mul,ZMod.natCast_self,zero_mul,add_zero] using hs0\n  have htwo : (2 : ZMod m)≠0 := by\n    intro h\n    exact Nat.not_dvd_of_pos_of_lt (by decide : 0<2) hm2\n      ((ZMod.natCast_eq_zero_iff 2 m).mp h)\n  have hnontriv' : ¬(((i : ZMod m)⁻¹=(k : ZMod m)⁻¹ ∧\n        (j : ZMod m)⁻¹=(l : ZMod m)⁻¹) ∨\n      ((i : ZMod m)⁻¹=(l : ZMod m)⁻¹ ∧ (j : ZMod m)⁻¹=(k : ZMod m)⁻¹)) := by\n    rintro (⟨hik,hjl⟩ | ⟨hil,hjk⟩)\n    · exact hnontriv (Or.inl ⟨hinv him hkm hik,hinv hjm hlm hjl⟩)\n    · exact hnontriv (Or.inr ⟨hinv him hlm hil,hinv hjm hkm hjk⟩)\n  have hiform := quadratic_offset_formula hi0\n    (offset_square_residue (N:=s+m*u) hm.pos (hcop hi him))\n  have hjform := quadratic_offset_formula hj0\n    (offset_square_residue (N:=s+m*u) hm.pos (hcop hj hjm))\n  have hkform := quadratic_offset_formula hk0\n    (offset_square_residue (N:=s+m*u) hm.pos (hcop hk hkm))\n  have hlform := quadratic_offset_formula hl0\n    (offset_square_residue (N:=s+m*u) hm.pos (hcop hl hlm))\n  have hecast := congrArg (fun z : ℤ => (z : ZMod m)) he\n  simp only [Int.cast_add] at hecast\n  rw [hiform,hjform,hkform,hlform] at hecast\n  have hslope := quadratic_pair_slope_ne_zero hN0 htwo hnontriv' hecast\n  have hcoeff : (j : ZMod m)*k*l+(i : ZMod m)*k*l-(i : ZMod m)*j*l-(i : ZMod m)*j*k=\n      (i : ZMod m)*j*k*l*((i : ZMod m)⁻¹+(j : ZMod m)⁻¹-\n        (k : ZMod m)⁻¹-(l : ZMod m)⁻¹) := by\n    field_simp\n  simp only [Int.cast_add,Int.cast_sub,Int.cast_mul,Int.cast_natCast]\n  rw [hcoeff]\n  exact mul_ne_zero (mul_ne_zero (mul_ne_zero (mul_ne_zero hi0 hj0) hk0) hl0) hslope\n\n/-- A nontrivial pair-sum of four literal row offsets occurs at only one bounded carry. -/\ntheorem actual_pair_unique_carry {s m i j k l u v : ℕ}\n    (hm : m.Prime) (hm2 : 2 < m) (hs : m.Coprime s)\n    (hi : 1 ≤ i) (him : i < m) (hj : 1 ≤ j) (hjm : j < m)\n    (hk : 1 ≤ k) (hkm : k < m) (hl : 1 ≤ l) (hlm : l < m)\n    (hnontriv : ¬((i=k ∧ j=l) ∨ (i=l ∧ j=k))) (hu : u < m) (hv : v < m)\n    (he : seedOffset (s+m*u) m i+seedOffset (s+m*u) m j=\n      seedOffset (s+m*u) m k+seedOffset (s+m*u) m l)\n    (he₀ : seedOffset (s+m*v) m i+seedOffset (s+m*v) m j=\n      seedOffset (s+m*v) m k+seedOffset (s+m*v) m l) : u=v := by\n  have hcop {r : ℕ} (hr : 1 ≤ r) (hrm : r < m) : r.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hrm)).symm\n  let D : ℤ := ((s+m*u : ℕ) : ℤ)-(s+m*v : ℕ)\n  let C : ℤ := (j : ℤ)*k*l+(i : ℤ)*k*l-(i : ℤ)*j*l-(i : ℤ)*j*k\n  have hI := offset_difference_modEq hm.pos (hcop hi him)\n    (carry_class (s:=s) (u:=u) (v:=v))\n  have hJ := offset_difference_modEq hm.pos (hcop hj hjm)\n    (carry_class (s:=s) (u:=u) (v:=v))\n  have hK := offset_difference_modEq hm.pos (hcop hk hkm)\n    (carry_class (s:=s) (u:=u) (v:=v))\n  have hL := offset_difference_modEq hm.pos (hcop hl hlm)\n    (carry_class (s:=s) (u:=u) (v:=v))\n  have h := (((hI.mul_left ((j : ℤ)*k*l)).add (hJ.mul_left ((i : ℤ)*k*l))).sub\n    (hK.mul_left ((i : ℤ)*j*l))).sub (hL.mul_left ((i : ℤ)*j*k))\n  have hmod : (0 : ℤ) ≡ -D*C [ZMOD (m : ℤ)^2] := by\n    convert h using 1\n    · linear_combination -(i : ℤ)*j*k*l*(he-he₀)\n    · dsimp [D,C]\n      ring\n  have hprod : (m : ℤ)^2∣C*D := by\n    convert hmod.symm.dvd using 1\n    ring\n  have hC := actual_pair_carry_coefficient_ne_zero hm hm2 hs\n    hi him hj hjm hk hkm hl hlm hnontriv he\n  have hD := (integer_coprime_square hm C hC).dvd_of_dvd_mul_left hprod\n  have hclass : ((s+m*u : ℕ) : ℤ) ≡ ((s+m*v : ℕ) : ℤ) [ZMOD (m : ℤ)^2] := by\n    apply Int.modEq_iff_dvd.mpr\n    simpa only [D,neg_sub] using hD.neg_right\n  exact equal_input_carry hm.pos hu hv hclass\n\nopen scoped BigOperators\n\n/-- Original row tags use the same zero-based range as progressionSeeds. -/\nnoncomputable def rowQuadruples (m : ℕ) : Finset ((ℕ×ℕ)×(ℕ×ℕ)) :=\n  ((Finset.range (m-1))×ˢ(Finset.range (m-1)))×ˢ\n    ((Finset.range (m-1))×ˢ(Finset.range (m-1)))\n\n/-- Two ordered tag pairs have different unordered tag multisets. -/\nabbrev tagPairsDiffer (q : (ℕ×ℕ)×(ℕ×ℕ)) : Prop :=\n  ¬((q.1.1=q.2.1 ∧ q.1.2=q.2.2) ∨ (q.1.1=q.2.2 ∧ q.1.2=q.2.1))\n\n/-- Exact original integer pair-sum equality, with all four labels retained. -/\nabbrev offsetPairEquality (N m : ℕ) (q : (ℕ×ℕ)×(ℕ×ℕ)) : Prop :=\n  seedOffset N m (q.1.1+1)+seedOffset N m (q.1.2+1)=\n    seedOffset N m (q.2.1+1)+seedOffset N m (q.2.2+1)\n\n/-- The nontrivial original pair equalities at one exact input residue. -/\nnoncomputable def nontrivialOffsetQuads (N m : ℕ) : Finset ((ℕ×ℕ)×(ℕ×ℕ)) :=\n  (rowQuadruples m).filter fun q => tagPairsDiffer q ∧ offsetPairEquality N m q\n\n/-- Count all nontrivial original tagged pair-sum equalities. -/\nnoncomputable def nontrivialOffsetEnergy (N m : ℕ) : ℕ :=\n  (nontrivialOffsetQuads N m).card\n\n/-- Necessary lower-residue candidates for exact four-tag equalities. -/\nnoncomputable def residuePairCandidates (s m : ℕ) : Finset ((ℕ×ℕ)×(ℕ×ℕ)) :=\n  (rowQuadruples m).filter fun q => tagPairsDiffer q ∧\n    (seedOffset s m (q.1.1+1) : ZMod m)+(seedOffset s m (q.1.2+1) : ZMod m)=\n      (seedOffset s m (q.2.1+1) : ZMod m)+(seedOffset s m (q.2.2+1) : ZMod m)\n\n/-- Original tags in an arbitrary lower-offset residue fiber. -/\nnoncomputable def phaseFiber (s m : ℕ) (δ : ℤ) : Finset ℕ :=\n  (Finset.range (m-1)).filter fun r => (seedOffset s m (r+1) : ZMod m)=(δ : ZMod m)\n\ntheorem rowQuadruples_mem {m : ℕ} {q : (ℕ×ℕ)×(ℕ×ℕ)} :\n    q∈rowQuadruples m ↔ q.1.1+1 < m ∧ q.1.2+1 < m ∧ q.2.1+1 < m ∧ q.2.2+1 < m := by\n  simp only [rowQuadruples,Finset.mem_product,Finset.mem_range]\n  omega\n\n/-- Every lower-offset fiber, including an arbitrary target phase, has at most two labels. -/\ntheorem phaseFiber_card_le_two {s m : ℕ} (hm : m.Prime) (hs : m.Coprime s) (δ : ℤ) :\n    (phaseFiber s m δ).card≤2 := by\n  classical\n  let : Fact m.Prime := ⟨hm⟩\n  let : NeZero m := ⟨hm.ne_zero⟩\n  let P := phasePolynomial s m δ\n  have hP : P≠0 := phasePolynomial_ne_zero hm hs δ\n  have hb {r : ℕ} (hr : r∈phaseFiber s m δ) :\n      r+1 < m ∧ (m : ℤ)∣seedOffset s m (r+1)-δ := by\n    have h := Finset.mem_filter.mp hr\n    refine ⟨by have hh := Finset.mem_range.mp h.1; omega,?_⟩\n    exact (ZMod.intCast_zmod_eq_zero_iff_dvd _ m).mp\n      (by simpa only [Int.cast_sub] using sub_eq_zero.mpr h.2)\n  have hmaps : Set.MapsTo (fun r : ℕ => ((r+1 : ℕ) : ZMod m))\n      (phaseFiber s m δ : Set ℕ) P.roots.toFinset := by\n    intro r hr\n    have hbr := hb hr\n    have hcop : (r+1).Coprime m :=\n      (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hbr.1)).symm\n    exact Multiset.mem_toFinset.mpr ((Polynomial.mem_roots hP).mpr\n      (phasePolynomial_root hm.pos hcop hbr.2))\n  have hinj : Set.InjOn (fun r : ℕ => ((r+1 : ℕ) : ZMod m))\n      (phaseFiber s m δ : Set ℕ) := by\n    intro r hr t ht he\n    have hval := congrArg ZMod.val he\n    simp only [ZMod.val_natCast,Nat.mod_eq_of_lt (hb hr).1,\n      Nat.mod_eq_of_lt (hb ht).1] at hval\n    omega\n  exact (Finset.card_le_card_of_injOn _ hmaps hinj).trans\n    ((Multiset.toFinset_card_le P.roots).trans\n      ((Polynomial.card_roots' P).trans (phasePolynomial_degree s m δ)))\n\n/-- The whole original lower-residue quadruple family has only cubic candidate mass. -/\ntheorem residuePairCandidates_card_le {s m : ℕ} (hm : m.Prime) (hs : m.Coprime s) :\n    (residuePairCandidates s m).card≤2*(m-1)^3 := by\n  classical\n  have hfold : (residuePairCandidates s m).card=\n      ∑ i∈Finset.range (m-1),∑ j∈Finset.range (m-1),∑ k∈Finset.range (m-1),\n        ((Finset.range (m-1)).filter fun l => tagPairsDiffer ((i,j),(k,l)) ∧\n          (seedOffset s m (i+1) : ZMod m)+(seedOffset s m (j+1) : ZMod m)=\n            (seedOffset s m (k+1) : ZMod m)+(seedOffset s m (l+1) : ZMod m)).card := by\n    simp only [residuePairCandidates,rowQuadruples,Finset.card_eq_sum_ones,\n      Finset.sum_filter,Finset.sum_product]\n  rw [hfold]\n  calc\n    _≤∑ _i∈Finset.range (m-1),∑ _j∈Finset.range (m-1),∑ _k∈Finset.range (m-1),2 := by\n      apply Finset.sum_le_sum\n      intro i hi\n      apply Finset.sum_le_sum\n      intro j hj\n      apply Finset.sum_le_sum\n      intro k hk\n      let δ := seedOffset s m (i+1)+seedOffset s m (j+1)-seedOffset s m (k+1)\n      have hsub : ((Finset.range (m-1)).filter fun l => tagPairsDiffer ((i,j),(k,l)) ∧\n          (seedOffset s m (i+1) : ZMod m)+(seedOffset s m (j+1) : ZMod m)=\n            (seedOffset s m (k+1) : ZMod m)+(seedOffset s m (l+1) : ZMod m))⊆\n          phaseFiber s m δ := by\n        intro l hl\n        have h := Finset.mem_filter.mp hl\n        apply Finset.mem_filter.mpr\n        refine ⟨h.1,?_⟩\n        dsimp only [δ]\n        push_cast\n        linear_combination -h.2.2\n      exact (Finset.card_le_card hsub).trans (phaseFiber_card_le_two hm hs δ)\n    _=2*(m-1)^3 := by simp only [Finset.sum_const,Finset.card_range,smul_eq_mul]; ring\n\ntheorem carry_offset_residue {s m u r : ℕ} (hm : m.Prime) (hr : r+1 < m) :\n    (seedOffset (s+m*u) m (r+1) : ZMod m)=(seedOffset s m (r+1) : ZMod m) := by\n  have hcop : (r+1).Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hr)).symm\n  have h := offset_residue_of_input_modEq hm.pos hcop (carry_class (s:=s) (u:=u) (v:=0))\n  simp only [mul_zero,add_zero] at h\n  exact (ZMod.intCast_eq_intCast_iff _ _ m).mpr h\n\ntheorem nontrivialOffsetQuads_eq_candidates_filter {s m u : ℕ} (hm : m.Prime) :\n    nontrivialOffsetQuads (s+m*u) m=(residuePairCandidates s m).filter\n      (offsetPairEquality (s+m*u) m) := by\n  classical\n  ext q\n  simp only [nontrivialOffsetQuads,residuePairCandidates,Finset.mem_filter]\n  constructor\n  · rintro ⟨hq,hnontriv,he⟩\n    refine ⟨⟨hq,hnontriv,?_⟩,he⟩\n    have hb := rowQuadruples_mem.mp hq\n    have hecast := congrArg (fun z : ℤ => (z : ZMod m)) he\n    simp only [Int.cast_add] at hecast\n    rw [carry_offset_residue hm hb.1,carry_offset_residue hm hb.2.1,\n      carry_offset_residue hm hb.2.2.1,carry_offset_residue hm hb.2.2.2] at hecast\n    exact hecast\n  · exact fun h => ⟨h.1.1,h.1.2.1,h.2⟩\n\n/-- Exact whole-family cubic nontrivial energy mass across every second carry. -/\ntheorem nontrivialOffsetEnergy_carry_mass_le {s m : ℕ} (hm : m.Prime) (hm2 : 2 < m)\n    (hs : m.Coprime s) :\n    ∑ u∈Finset.range m,nontrivialOffsetEnergy (s+m*u) m≤2*(m-1)^3 := by\n  classical\n  have hrewrite : (∑ u∈Finset.range m,nontrivialOffsetEnergy (s+m*u) m)=\n      ∑ q∈residuePairCandidates s m,((Finset.range m).filter fun u =>\n        offsetPairEquality (s+m*u) m q).card := by\n    simp_rw [nontrivialOffsetEnergy,nontrivialOffsetQuads_eq_candidates_filter hm,\n      Finset.card_eq_sum_ones,Finset.sum_filter]\n    exact Finset.sum_comm\n  rw [hrewrite]\n  calc\n    _≤∑ _q∈residuePairCandidates s m,1 := by\n      apply Finset.sum_le_sum\n      intro q hq\n      apply Finset.card_le_one.mpr\n      intro u hu v hv\n      have hb := rowQuadruples_mem.mp (Finset.mem_filter.mp hq).1\n      have hnontriv := (Finset.mem_filter.mp hq).2.1\n      have htags : ¬((q.1.1+1=q.2.1+1 ∧ q.1.2+1=q.2.2+1) ∨\n          (q.1.1+1=q.2.2+1 ∧ q.1.2+1=q.2.1+1)) := by\n        simpa only [tagPairsDiffer,Nat.add_right_cancel_iff] using hnontriv\n      exact actual_pair_unique_carry hm hm2 hs (by omega) hb.1 (by omega) hb.2.1\n        (by omega) hb.2.2.1 (by omega) hb.2.2.2 htags\n        (Finset.mem_range.mp (Finset.mem_filter.mp hu).1)\n        (Finset.mem_range.mp (Finset.mem_filter.mp hv).1)\n        (Finset.mem_filter.mp hu).2 (Finset.mem_filter.mp hv).2\n    _=(residuePairCandidates s m).card := by simp\n    _≤2*(m-1)^3 := residuePairCandidates_card_le hm hs\n\n/-- A finite Markov threshold bound for the original energy, not random carry sampling. -/\ntheorem nontrivialOffsetEnergy_threshold_bound {s m B : ℕ} (hm : m.Prime) (hm2 : 2 < m)\n    (hs : m.Coprime s) :\n    B*((Finset.range m).filter fun u => B≤nontrivialOffsetEnergy (s+m*u) m).card≤\n      2*(m-1)^3 := by\n  classical\n  let bad := (Finset.range m).filter fun u => B≤nontrivialOffsetEnergy (s+m*u) m\n  calc\n    B*bad.card=∑ _u∈bad,B := by simp only [Finset.sum_const,smul_eq_mul,mul_comm]\n    _≤∑ u∈bad,nontrivialOffsetEnergy (s+m*u) m := by\n      apply Finset.sum_le_sum\n      exact fun _ hu => (Finset.mem_filter.mp hu).2\n    _≤∑ u∈Finset.range m,nontrivialOffsetEnergy (s+m*u) m :=\n      Finset.sum_le_sum_of_subset_of_nonneg (Finset.filter_subset _ _) (by intros; omega)\n    _≤2*(m-1)^3 := nontrivialOffsetEnergy_carry_mass_le hm hm2 hs\n\nsection GroupEnergy\n\nopen scoped BigOperators Pointwise Combinatorics.Additive\n\nvariable {G : Type*} [CommGroup G] [Fintype G] [DecidableEq G]\n\n/-- Ordered source-ratio multiplicity used only in finite proofs. -/\nnoncomputable def ratioCount (s : Finset G) (r : G) : ℕ :=\n  ((s ×ˢ s).filter fun ab => ab.1 / ab.2 = r).card\n\ntheorem energy_eq_ratio_sum (s t : Finset G) :\n    s.mulEnergy t = ∑ r : G, ratioCount s r * ratioCount t r := by\n  classical\n  let Q := (((s ×ˢ s) ×ˢ (t ×ˢ t)).filter fun ab =>\n    ab.1.1 / ab.1.2 = ab.2.1 / ab.2.2)\n  have hQ : s.mulEnergy t = Q.card := by\n    unfold Finset.mulEnergy\n    apply Finset.card_bij (fun ab _ => (ab.1, (ab.2.2, ab.2.1)))\n    · intro ab hab\n      simp only [Q, Finset.mem_filter, Finset.mem_product] at hab ⊢\n      exact ⟨⟨hab.1.1, hab.1.2.2, hab.1.2.1⟩,\n        div_eq_div_iff_mul_eq_mul.mpr (by simpa [mul_comm] using hab.2)⟩\n    · intro a _ b _ h\n      have hi := congrArg\n        (fun z : (G × G) × (G × G) => (z.1, (z.2.2, z.2.1))) h\n      simpa only using hi\n    · intro ab hab\n      refine ⟨(ab.1, (ab.2.2, ab.2.1)), ?_, ?_⟩\n      · simp only [Q, Finset.mem_filter, Finset.mem_product] at hab ⊢\n        exact ⟨⟨hab.1.1, hab.1.2.2, hab.1.2.1⟩,\n          by simpa [mul_comm] using div_eq_div_iff_mul_eq_mul.mp hab.2⟩\n      · simp\n  rw [hQ]\n  have hf : Q.card = ∑ r : G,\n      (Q.filter fun ab => ab.1.1 / ab.1.2 = r).card := by\n    exact Finset.card_eq_sum_card_fiberwise (fun _ _ => Finset.mem_univ _)\n  rw [hf]\n  apply Finset.sum_congr rfl\n  intro r _\n  have he : (Q.filter fun ab => ab.1.1 / ab.1.2 = r) =\n      ((s ×ˢ s).filter fun ab => ab.1 / ab.2 = r) ×ˢ\n      ((t ×ˢ t).filter fun ab => ab.1 / ab.2 = r) := by\n    ext ab\n    simp only [Q, Finset.mem_filter, Finset.mem_product]\n    aesop\n  rw [he, Finset.card_product]\n  rfl\n\ntheorem mixed_energy_sq_le (s t : Finset G) :\n    s.mulEnergy t ^ 2 ≤ s.mulEnergy s * t.mulEnergy t := by\n  rw [energy_eq_ratio_sum, energy_eq_ratio_sum s s, energy_eq_ratio_sum t t]\n  simpa only [pow_two] using\n    Finset.sum_mul_sq_le_sq_mul_sq (R := ℕ) Finset.univ (ratioCount s) (ratioCount t)\n\ntheorem product_support_energy_bound (s t : Finset G) :\n    (s.card * t.card) ^ 4 ≤ (s * t).card ^ 2 * s.mulEnergy s * t.mulEnergy t := by\n  have h := Finset.le_card_mul_mul_mulEnergy s t\n  have hs : (s.card * t.card) ^ 2 ≤ (s * t).card * s.mulEnergy t := by\n    simpa only [mul_pow] using h\n  calc\n    _ = ((s.card * t.card) ^ 2) ^ 2 := by ring\n    _ ≤ ((s * t).card * s.mulEnergy t) ^ 2 := Nat.pow_le_pow_left hs 2\n    _ = (s * t).card ^ 2 * (s.mulEnergy t) ^ 2 := by ring\n    _ ≤ (s * t).card ^ 2 * (s.mulEnergy s * t.mulEnergy t) :=\n      Nat.mul_le_mul_left _ (mixed_energy_sq_le s t)\n    _ = _ := by ring\n\nomit [Fintype G] in\ntheorem self_energy_le_card_cubed (s : Finset G) :\n    s.mulEnergy s ≤ s.card ^ 3 := by\n  unfold Finset.mulEnergy\n  have h := Finset.card_le_card_of_injOn\n    (s := (((s ×ˢ s) ×ˢ (s ×ˢ s)).filter fun ab =>\n      ab.1.1 * ab.2.1 = ab.1.2 * ab.2.2))\n    (t := (s ×ˢ s) ×ˢ s) (fun ab => (ab.1, ab.2.1))\n    (by\n      intro ab hab\n      exact Finset.mem_product.mpr\n        ⟨(Finset.mem_product.mp (Finset.mem_filter.mp hab).1).1,\n          (Finset.mem_product.mp (Finset.mem_product.mp (Finset.mem_filter.mp hab).1).2).1⟩)\n    (by\n      intro a ha b hb he\n      have h1 : a.1 = b.1 := congrArg (fun z : (G × G) × G => z.1) he\n      have h2 : a.2.1 = b.2.1 := congrArg Prod.snd he\n      have haeq := (Finset.mem_filter.mp ha).2\n      have hbeq := (Finset.mem_filter.mp hb).2\n      have hlast : a.2.2 = b.2.2 := by\n        apply mul_left_cancel (a := a.1.2)\n        calc\n          _ = a.1.1 * a.2.1 := haeq.symm\n          _ = b.1.1 * b.2.1 := by rw [h1, h2]\n          _ = b.1.2 * b.2.2 := hbeq\n          _ = a.1.2 * b.2.2 := by rw [h1]\n      exact Prod.ext h1 (Prod.ext h2 hlast))\n  have hc : ((s ×ˢ s) ×ˢ s).card = s.card ^ 3 := by\n    simp only [Finset.card_product]\n    ring\n  rw [hc] at h\n  exact h\n\ntheorem product_support_source_energy_bound (s t : Finset G) :\n    (s.card * t.card) ^ 4 ≤ (s * t).card ^ 2 * s.mulEnergy s * t.card ^ 3 := by\n  exact (product_support_energy_bound s t).trans\n    (Nat.mul_le_mul_left _ (self_energy_le_card_cubed t))\n\ntheorem product_support_tradeoff (s t : Finset G) (ht : 0 < t.card)\n    (w L D B : ℕ) (hcover : L ≤ w * t.card)\n    (hdegree : (s * t).card ≤ D) (henergy : s.mulEnergy s ≤ B) :\n    s.card ^ 4 * L ≤ w * D ^ 2 * B := by\n  have he := product_support_source_energy_bound s t\n  have hbase : s.card ^ 4 * t.card ≤ (s * t).card ^ 2 * s.mulEnergy s := by\n    have hh : (s.card ^ 4 * t.card) * t.card ^ 3 ≤\n        ((s * t).card ^ 2 * s.mulEnergy s) * t.card ^ 3 := by\n      calc\n        _ = (s.card * t.card) ^ 4 := by ring\n        _ ≤ _ := he\n    exact Nat.le_of_mul_le_mul_right hh (pow_pos ht _)\n  have hd : s.card ^ 4 * t.card ≤ D ^ 2 * B :=\n    hbase.trans (Nat.mul_le_mul (Nat.pow_le_pow_left hdegree 2) henergy)\n  calc\n    _ ≤ s.card ^ 4 * (w * t.card) := Nat.mul_le_mul_left _ hcover\n    _ = w * (s.card ^ 4 * t.card) := by ring\n    _ ≤ w * (D ^ 2 * B) := Nat.mul_le_mul_left _ hd\n    _ = _ := by ring\n\nomit [Fintype G] in\n/-- Multiplicative energy with every original source label retained. -/\nnoncomputable def labelledEnergy {ι : Type*} (I : Finset ι) (f : ι → G) : ℕ := by\n  classical\n  exact (((I ×ˢ I) ×ˢ (I ×ˢ I)).filter fun q =>\n    f q.1.1 * f q.2.1 = f q.1.2 * f q.2.2).card\n\nomit [Fintype G] in\ntheorem image_self_energy_le_labelled {ι : Type*} (I : Finset ι) (f : ι → G) :\n    (I.image f).mulEnergy (I.image f) ≤ labelledEnergy I f := by\n  classical\n  let S := (((I ×ˢ I) ×ˢ (I ×ˢ I)).filter fun q =>\n    f q.1.1 * f q.2.1 = f q.1.2 * f q.2.2)\n  let F := fun q : (ι × ι) × (ι × ι) =>\n    ((f q.1.1, f q.1.2), (f q.2.1, f q.2.2))\n  have he : S.image F =\n      ((((I.image f) ×ˢ (I.image f)) ×ˢ ((I.image f) ×ˢ (I.image f))).filter\n        fun q => q.1.1 * q.2.1 = q.1.2 * q.2.2) := by\n    ext q\n    constructor\n    · intro hq\n      obtain ⟨a, ha, rfl⟩ := Finset.mem_image.mp hq\n      rcases Finset.mem_filter.mp ha with ⟨ha, heq⟩\n      rcases Finset.mem_product.mp ha with ⟨ha1, ha2⟩\n      rcases Finset.mem_product.mp ha1 with ⟨hi1, hi2⟩\n      rcases Finset.mem_product.mp ha2 with ⟨hi3, hi4⟩\n      exact Finset.mem_filter.mpr\n        ⟨Finset.mem_product.mpr\n          ⟨Finset.mem_product.mpr\n            ⟨Finset.mem_image_of_mem f hi1, Finset.mem_image_of_mem f hi2⟩,\n            Finset.mem_product.mpr\n              ⟨Finset.mem_image_of_mem f hi3, Finset.mem_image_of_mem f hi4⟩⟩,\n          heq⟩\n    · intro hq\n      rcases Finset.mem_filter.mp hq with ⟨hq, heq⟩\n      rcases Finset.mem_product.mp hq with ⟨hq1, hq2⟩\n      rcases Finset.mem_product.mp hq1 with ⟨hy1, hy2⟩\n      rcases Finset.mem_product.mp hq2 with ⟨hy3, hy4⟩\n      obtain ⟨i1, hi1, he1⟩ := Finset.mem_image.mp hy1\n      obtain ⟨i2, hi2, he2⟩ := Finset.mem_image.mp hy2\n      obtain ⟨i3, hi3, he3⟩ := Finset.mem_image.mp hy3\n      obtain ⟨i4, hi4, he4⟩ := Finset.mem_image.mp hy4\n      refine Finset.mem_image.mpr ⟨((i1, i2), (i3, i4)), ?_, ?_⟩\n      · apply Finset.mem_filter.mpr\n        exact ⟨Finset.mem_product.mpr\n          ⟨Finset.mem_product.mpr ⟨hi1, hi2⟩, Finset.mem_product.mpr ⟨hi3, hi4⟩⟩,\n          by simpa only [he1, he2, he3, he4] using heq⟩\n      · dsimp only [F]\n        exact Prod.ext (Prod.ext he1 he2) (Prod.ext he3 he4)\n  have hc := Finset.card_image_le (f := F) (s := S)\n  rw [he] at hc\n  exact hc\n\nomit [CommGroup G] [Fintype G] in\ntheorem card_le_fiber_bound_mul_image {ι : Type*} (I : Finset ι) (f : ι → G)\n    (C : ℕ) (hcap : ∀ y ∈ I.image f, (I.filter fun i => f i = y).card ≤ C) :\n    I.card ≤ C * (I.image f).card := by\n  classical\n  calc\n    _ = ∑ y ∈ I.image f, (I.filter fun i => f i = y).card :=\n      Finset.card_eq_sum_card_image f I\n    _ ≤ ∑ _y ∈ I.image f, C := Finset.sum_le_sum hcap\n    _ = _ := by simp only [Finset.sum_const, smul_eq_mul, mul_comm]\n\nend GroupEnergy\n\nopen scoped BigOperators\nopen Polynomial SemiprimeSeedMomentPoleRetention\n\n/-- Row-injective labelled grids have at most one occurrence per row in\nany point fiber, regardless of the grid's total raw label mass. -/\ntheorem grid_fiber_card_le_rows {G : Type*} [DecidableEq G] {M J : ℕ}\n    (point : Fin M × Fin J → G)\n    (hrow : ∀ i, Function.Injective (fun k => point (i,k))) (y : G) :\n    ((Finset.univ : Finset (Fin M × Fin J)).filter fun ik => point ik=y).card≤M := by\n  classical\n  have hinj : Set.InjOn (fun ik : Fin M × Fin J => ik.1)\n      (((Finset.univ : Finset (Fin M × Fin J)).filter fun ik => point ik=y) : Set _) := by\n    intro a ha b hb he\n    obtain ⟨i,k⟩ := a\n    obtain ⟨j,l⟩ := b\n    dsimp only at he\n    subst j\n    have ha' := (Finset.mem_filter.mp ha).2\n    have hb' := (Finset.mem_filter.mp hb).2\n    have hk := hrow i (ha'.trans hb'.symm)\n    exact Prod.ext rfl hk\n  have hcard := Finset.card_image_of_injOn hinj\n  calc\n    _=((Finset.univ.filter fun ik => point ik=y).image Prod.fst).card := hcard.symm\n    _≤(Finset.univ : Finset (Fin M)).card := Finset.card_le_card (Finset.subset_univ _)\n    _=M := Fintype.card_fin M\n\n/-- Positive local fiber weights below the characteristic retain every\npole, even when the full labelled family has more than p labels. -/\ntheorem fiberwise_prime_denominator_degree {p : ℕ} {ι : Type*}\n    (hp : p.Prime) (I : Finset ι) (x : ι→ZMod p)\n    (hfiber : ∀ y∈I.image x,(I.filter fun i => x i=y).card<p)\n    (hx : ∀ i∈I,x i≠0) (U V : (ZMod p)[X]) (hU : U.coeff 0=1)\n    (hUV : (U : PowerSeries (ZMod p))*(∑ i∈I,positiveMoments (x i))=\n      (V : PowerSeries (ZMod p))) : (I.image x).card≤U.natDegree := by\n  classical\n  let : Fact p.Prime := ⟨hp⟩\n  rw [labelled_moments_group I x] at hUV\n  have hpoints : ∀ y∈I.image x,y≠0 := by\n    intro y hy\n    obtain ⟨i,hi,rfl⟩ := Finset.mem_image.mp hy\n    exact hx i hi\n  have hweights : ∀ y∈I.image x,(((I.filter fun i => x i=y).card : ℕ) : ZMod p)≠0 := by\n    intro y hy\n    obtain ⟨i,hi,he⟩ := Finset.mem_image.mp hy\n    have hpos : 0<(I.filter fun j => x j=y).card :=\n      Finset.card_pos.mpr ⟨i,Finset.mem_filter.mpr ⟨hi,he⟩⟩\n    exact fun hz => Nat.not_dvd_of_pos_of_lt hpos (hfiber y (Finset.mem_image.mpr ⟨i,hi,he⟩))\n      ((ZMod.natCast_eq_zero_iff _ _).mp hz)\n  exact weighted_denominator_degree (I.image x)\n    (fun y => (((I.filter fun i => x i=y).card : ℕ) : ZMod p))\n    hpoints hweights U V hU hUV\n\n/-- A geometric row is injective before its actual unit period. -/\ntheorem geometric_grid_fiber_card_le_rows {p M J : ℕ}\n    (x : Fin M→(ZMod p)ˣ) (beta : (ZMod p)ˣ)\n    (hJ : J≤orderOf beta) (y : ZMod p) :\n    ((Finset.univ : Finset (Fin M × Fin J)).filter\n      fun ik => (((x ik.1)*beta^ik.2.val : (ZMod p)ˣ) : ZMod p)=y).card≤M := by\n  apply grid_fiber_card_le_rows\n  intro i k l he\n  have he' : x i*beta^k.val=x i*beta^l.val := Units.ext he\n  have hpow := mul_left_cancel he'\n  apply Fin.ext\n  exact pow_injOn_Iio_orderOf (k.is_lt.trans_le hJ) (l.is_lt.trans_le hJ) hpow\n\n/-- All positive geometric-grid poles survive as long as the number of\nsource rows is below p; no bound on M*J is needed. -/\ntheorem geometric_grid_denominator_degree {p M J : ℕ}\n    (hp : p.Prime) (x : Fin M→(ZMod p)ˣ) (beta : (ZMod p)ˣ)\n    (hJ : J≤orderOf beta) (hM : M<p)\n    (U V : (ZMod p)[X]) (hU : U.coeff 0=1)\n    (hUV : (U : PowerSeries (ZMod p))*(∑ ik : Fin M × Fin J,\n      positiveMoments ((((x ik.1)*beta^ik.2.val : (ZMod p)ˣ) : ZMod p)))=\n      (V : PowerSeries (ZMod p))) :\n    ((Finset.univ : Finset (Fin M × Fin J)).image\n      fun ik => (((x ik.1)*beta^ik.2.val : (ZMod p)ˣ) : ZMod p)).card≤U.natDegree := by\n  let : Fact p.Prime := ⟨hp⟩\n  apply fiberwise_prime_denominator_degree hp Finset.univ\n    (fun ik : Fin M × Fin J => (((x ik.1)*beta^ik.2.val : (ZMod p)ˣ) : ZMod p))\n    (fun y _ => (geometric_grid_fiber_card_le_rows x beta hJ y).trans_lt hM)\n    (fun ik _ => (x ik.1*beta^ik.2.val).isUnit.ne_zero) U V hU\n  exact hUV\n\nopen SemiprimeGlobalPhaseCancellation SemiprimeDenseRowCarries\n\n/-- The short original four-offset residual lies below the actual local\nperiod. Cancelling the common 2N exponent loses no tagged pair equality. -/\ntheorem original_pair_product_eq_iff_offset_sum {G : Type*} [CommGroup G]\n    (g : G) {N m i j k l : ℕ} (hm : m.Prime)\n    (hi : 1 ≤ i) (him : i < m) (hj : 1 ≤ j) (hjm : j < m)\n    (hk : 1 ≤ k) (hkm : k < m) (hl : 1 ≤ l) (hlm : l < m)\n    (horder : 8*m^2 < orderOf g) :\n    (progressionSeed g N m i).step*(progressionSeed g N m j).step=\n      (progressionSeed g N m k).step*(progressionSeed g N m l).step ↔\n    seedOffset N m i+seedOffset N m j=seedOffset N m k+seedOffset N m l := by\n  have hcop {r : ℕ} (hr : 1 ≤ r) (hrm : r < m) : r.Coprime m :=\n    (hm.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hrm)).symm\n  rw [seed_step_offset g hm.pos (hcop hi him),\n    seed_step_offset g hm.pos (hcop hj hjm),\n    seed_step_offset g hm.pos (hcop hk hkm),\n    seed_step_offset g hm.pos (hcop hl hlm),←zpow_add,←zpow_add]\n  constructor\n  · intro he\n    have hd := (orderOf_dvd_sub_iff_zpow_eq_zpow).mpr he\n    have hbI := seedOffset_bounds (N:=N) hm.one_lt hi him\n    have hbJ := seedOffset_bounds (N:=N) hm.one_lt hj hjm\n    have hbK := seedOffset_bounds (N:=N) hm.one_lt hk hkm\n    have hbL := seedOffset_bounds (N:=N) hm.one_lt hl hlm\n    have hb : |((N : ℤ)+seedOffset N m i)+((N : ℤ)+seedOffset N m j)-\n        (((N : ℤ)+seedOffset N m k)+((N : ℤ)+seedOffset N m l))| ≤ 8*(m : ℤ)^2 := by\n      apply abs_le.mpr\n      constructor  <;> nlinarith only [hbI.1,hbI.2,hbJ.1,hbJ.2,hbK.1,hbK.2,hbL.1,hbL.2]\n    have ho : 8*(m : ℤ)^2 < (orderOf g : ℤ) := by exact_mod_cast horder\n    have hn : (((N : ℤ)+seedOffset N m i)+((N : ℤ)+seedOffset N m j)-\n        (((N : ℤ)+seedOffset N m k)+((N : ℤ)+seedOffset N m l))).natAbs <\n        (orderOf g : ℤ).natAbs := by\n      have hh := hb.trans_lt ho\n      rw [←Int.natCast_natAbs] at hh\n      rw [Int.natAbs_natCast]\n      exact_mod_cast hh\n    have hz := Int.eq_zero_of_dvd_of_natAbs_lt_natAbs hd hn\n    linarith only [hz]\n  · intro he\n    congr 1\n    linarith only [he]\n\n/-- Integer energy of all original row tags, retaining duplicate offsets. -/\nnoncomputable def offsetEnergy (N m : ℕ) : ℕ :=\n  ((Finset.univ : Finset ((Fin (m-1) × Fin (m-1)) × (Fin (m-1) × Fin (m-1)))).filter\n    fun t : ((Fin (m-1) × Fin (m-1)) × (Fin (m-1) × Fin (m-1))) => seedOffset N m (t.1.1.val+1)+seedOffset N m (t.1.2.val+1)=\n      seedOffset N m (t.2.1.val+1)+seedOffset N m (t.2.2.val+1)).card\n\n/-- Multiplicative energy uses the identical original row labels. -/\nnoncomputable def originalSeedEnergy {G : Type*} [CommGroup G] (g : G) (N m : ℕ) : ℕ := by\n  classical\n  exact ((Finset.univ : Finset ((Fin (m-1) × Fin (m-1)) × (Fin (m-1) × Fin (m-1)))).filter\n    fun t : ((Fin (m-1) × Fin (m-1)) × (Fin (m-1) × Fin (m-1))) => (progressionSeed g N m (t.1.1.val+1)).step*\n        (progressionSeed g N m (t.1.2.val+1)).step=\n      (progressionSeed g N m (t.2.1.val+1)).step*\n        (progressionSeed g N m (t.2.2.val+1)).step).card\n\n/-- Exact tagged source-energy transfer at a sufficiently large local\nperiod. The group is proof-side; no local order is supplied to a runtime. -/\ntheorem originalSeedEnergy_eq_offsetEnergy {G : Type*} [CommGroup G]\n    (g : G) {N m : ℕ} (hm : m.Prime) (horder : 8*m^2 < orderOf g) :\n    originalSeedEnergy g N m=offsetEnergy N m := by\n  classical\n  unfold originalSeedEnergy offsetEnergy\n  apply congrArg Finset.card\n  ext t\n  simp only [Finset.mem_filter,Finset.mem_univ,true_and]\n  exact original_pair_product_eq_iff_offset_sum g hm\n    (by omega) (by omega) (by omega) (by omega)\n    (by omega) (by omega) (by omega) (by omega) horder\n\n\nopen scoped BigOperators Pointwise Combinatorics.Additive\nopen Polynomial RiemannGaussian.SemiprimeSeedMomentPoleRetention\nopen RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction\n\ntheorem geometric_unit_grid_support_eq {G : Type*} [CommGroup G] [DecidableEq G]\n    {M J : ℕ} (x : Fin M → G) (beta : G) :\n    (Finset.univ.image x) *\n      (Finset.univ.image fun k : Fin J => beta ^ k.val) =\n    ((Finset.univ : Finset (Fin M × Fin J)).image\n      fun ik => x ik.1 * beta ^ ik.2.val) := by\n  classical\n  ext g\n  simp only [Finset.mem_mul, Finset.mem_image, Finset.mem_univ, true_and, Prod.exists]\n  constructor\n  · rintro ⟨a, ⟨i, rfl⟩, b, ⟨k, rfl⟩, he⟩\n    exact ⟨i, k, he⟩\n  · rintro ⟨i, k, he⟩\n    exact ⟨x i, ⟨i, rfl⟩, beta ^ k.val, ⟨k, rfl⟩, he⟩\n\ntheorem geometric_grid_support_card_eq {p M J : ℕ}\n    (x : Fin M → (ZMod p)ˣ) (beta : (ZMod p)ˣ) :\n    ((Finset.univ.image x) *\n      (Finset.univ.image fun k : Fin J => beta ^ k.val)).card =\n    ((Finset.univ : Finset (Fin M × Fin J)).image\n      fun ik => (((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p)).card := by\n  classical\n  rw [geometric_unit_grid_support_eq]\n  have hi := Finset.card_image_of_injective\n    (s := ((Finset.univ : Finset (Fin M × Fin J)).image\n      fun ik => x ik.1 * beta ^ ik.2.val))\n    (f := fun u : (ZMod p)ˣ => (u : ZMod p))\n    (fun a b h => Units.ext h)\n  rw [Finset.image_image] at hi\n  exact hi.symm\n\ntheorem geometric_moment_source_energy_tradeoff {p M J : ℕ}\n    (hp : p.Prime) (x : Fin M → (ZMod p)ˣ) (beta : (ZMod p)ˣ)\n    (hsource : ∀ y ∈ Finset.univ.image x,\n      ((Finset.univ : Finset (Fin M)).filter fun i => x i = y).card ≤ 2)\n    (hJ : J ≤ orderOf beta) (hJpos : 0 < J) (hM : M < p)\n    (w L : ℕ) (hcover : L ≤ w * J)\n    (H K : (ZMod p)[X]) (hH : H.coeff 0 = 1)\n    (hHK : (H : PowerSeries (ZMod p)) * (∑ ik : Fin M × Fin J,\n      positiveMoments ((((x ik.1) * beta ^ ik.2.val : (ZMod p)ˣ) : ZMod p))) =\n      (K : PowerSeries (ZMod p))) :\n    M ^ 4 * L ≤ 16 * w * H.natDegree ^ 2 * labelledEnergy Finset.univ x := by\n  classical\n  let : NeZero p := ⟨hp.ne_zero⟩\n  let A := Finset.univ.image x\n  let B := Finset.univ.image fun k : Fin J => beta ^ k.val\n  have hB : B.card = J := by\n    rw [Finset.card_image_of_injective]\n    · exact Fintype.card_fin J\n    · intro k l he\n      apply Fin.ext\n      exact pow_injOn_Iio_orderOf (k.is_lt.trans_le hJ) (l.is_lt.trans_le hJ) he\n  have hrows : M ≤ 2 * A.card := by\n    have h := card_le_fiber_bound_mul_image Finset.univ x 2 hsource\n    simpa only [Finset.card_univ, Fintype.card_fin] using h\n  have hdeg : (A * B).card ≤ H.natDegree := by\n    rw [geometric_grid_support_card_eq]\n    exact geometric_grid_denominator_degree hp x beta hJ hM H K hH hHK\n  have he := product_support_tradeoff A B (by rw [hB]; exact hJpos)\n    w L H.natDegree (labelledEnergy Finset.univ x)\n    (by rw [hB]; exact hcover) hdeg (image_self_energy_le_labelled Finset.univ x)\n  calc\n    _ ≤ (2 * A.card) ^ 4 * L := Nat.mul_le_mul_right L (Nat.pow_le_pow_left hrows 4)\n    _ = 16 * (A.card ^ 4 * L) := by ring\n    _ ≤ 16 * (w * H.natDegree ^ 2 * labelledEnergy Finset.univ x) :=\n      Nat.mul_le_mul_left _ he\n    _ = _ := by ring\n\n\nopen SemiprimeGlobalPhaseCancellation SemiprimeDenseRowCarries\n\n/-- At a sufficiently large local order, each original seed fiber retains\nat most the two labels in its public quadratic phase fiber. -/\ntheorem original_seed_fiber_card_le_two {G : Type*} [CommGroup G] [DecidableEq G]\n    (g : G) {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (horder : 8*m^2 < orderOf g) (y : G) :\n    ((Finset.univ : Finset (Fin (m-1))).filter\n      fun i => (progressionSeed g N m (i.val+1)).step=y).card≤2 := by\n  classical\n  let S := (Finset.univ : Finset (Fin (m-1))).filter\n    fun i => (progressionSeed g N m (i.val+1)).step=y\n  change S.card≤2\n  by_cases hs : S.Nonempty\n  · obtain ⟨i₀,hi₀⟩ := hs\n    let δ := seedOffset N m (i₀.val+1)\n    have hi₀eq := (Finset.mem_filter.mp hi₀).2\n    have hmap : Set.MapsTo (fun i : Fin (m-1) => i.val) S (phaseFiber N m δ) := by\n      intro i hi\n      have he := (Finset.mem_filter.mp hi).2.trans hi₀eq.symm\n      have hprod : (progressionSeed g N m (i.val+1)).step*\n          (progressionSeed g N m (i₀.val+1)).step=\n          (progressionSeed g N m (i₀.val+1)).step*\n          (progressionSeed g N m (i₀.val+1)).step := by rw [he]\n      have hoff := (original_pair_product_eq_iff_offset_sum g hm\n        (by omega) (by omega) (by omega) (by omega)\n        (by omega) (by omega) (by omega) (by omega) horder).mp hprod\n      have hd : seedOffset N m (i.val+1)=δ := by dsimp only [δ]; omega\n      apply Finset.mem_filter.mpr\n      exact ⟨Finset.mem_range.mpr i.is_lt,congrArg (fun z : ℤ => (z : ZMod m)) hd⟩\n    have hinj : Set.InjOn (fun i : Fin (m-1) => i.val) S :=\n      fun _ _ _ _ he => Fin.ext he\n    exact (Finset.card_le_card_of_injOn _ hmap hinj).trans\n      (phaseFiber_card_le_two hm hN δ)\n  · simp only [Finset.not_nonempty_iff_eq_empty] at hs\n    simp [hs]\n\n\nopen SemiprimeSeedEnergyAcquisitionObstruction\n\n/-- The Fin-labelled source energy is exactly the same natural-tag count. -/\ntheorem offsetEnergy_eq_nat_card (N m : ℕ) :\n    offsetEnergy N m=((rowQuadruples m).filter (offsetPairEquality N m)).card := by\n  classical\n  unfold offsetEnergy\n  apply Finset.card_bij\n    (fun t _ => ((t.1.1.val,t.1.2.val),(t.2.1.val,t.2.2.val)))\n  · intro t ht\n    simp only [Finset.mem_filter,Finset.mem_univ,true_and] at ht\n    simp only [Finset.mem_filter,rowQuadruples,Finset.mem_product,Finset.mem_range]\n    exact ⟨⟨⟨t.1.1.isLt,t.1.2.isLt⟩,⟨t.2.1.isLt,t.2.2.isLt⟩⟩,ht⟩\n  · intro a _ b _ h\n    exact Prod.ext\n      (Prod.ext (Fin.ext (congrArg (fun q => q.1.1) h))\n        (Fin.ext (congrArg (fun q => q.1.2) h)))\n      (Prod.ext (Fin.ext (congrArg (fun q => q.2.1) h))\n        (Fin.ext (congrArg (fun q => q.2.2) h)))\n  · intro q hq\n    have hb := (Finset.mem_filter.mp hq).1\n    simp only [rowQuadruples,Finset.mem_product,Finset.mem_range] at hb\n    let t : ((Fin (m-1)×Fin (m-1))×(Fin (m-1)×Fin (m-1))) :=\n      ((⟨q.1.1,hb.1.1⟩,⟨q.1.2,hb.1.2⟩),(⟨q.2.1,hb.2.1⟩,⟨q.2.2,hb.2.2⟩))\n    refine ⟨t,?_,rfl⟩\n    simp only [Finset.mem_filter,Finset.mem_univ,true_and]\n    exact (Finset.mem_filter.mp hq).2\n\n/-- The two tag-diagonal images bound every trivial unordered pair match. -/\ntheorem nat_offset_energy_le_nontrivial (N m : ℕ) :\n    ((rowQuadruples m).filter (offsetPairEquality N m)).card≤\n      nontrivialOffsetEnergy N m+2*(m-1)^2 := by\n  classical\n  let P := (Finset.range (m-1))×ˢ(Finset.range (m-1))\n  let D := (P.image fun a : ℕ×ℕ => (a,a)) ∪\n    (P.image fun a : ℕ×ℕ => (a,(a.2,a.1)))\n  have hsub : ((rowQuadruples m).filter (offsetPairEquality N m))⊆\n      nontrivialOffsetQuads N m ∪ D := by\n    intro q hq\n    have hb := (Finset.mem_filter.mp hq).1\n    have he := (Finset.mem_filter.mp hq).2\n    by_cases hn : tagPairsDiffer q\n    · exact Finset.mem_union_left _ (Finset.mem_filter.mpr ⟨hb,hn,he⟩)\n    · have hmatch : (q.1.1=q.2.1 ∧ q.1.2=q.2.2) ∨\n          (q.1.1=q.2.2 ∧ q.1.2=q.2.1) := by\n        simpa only [tagPairsDiffer,not_not] using hn\n      have hp : q.1∈P := (Finset.mem_product.mp hb).1\n      apply Finset.mem_union_right\n      rcases hmatch with ⟨hik,hjl⟩ | ⟨hil,hjk⟩\n      · apply Finset.mem_union_left\n        exact Finset.mem_image.mpr\n          ⟨q.1,hp,Prod.ext rfl (Prod.ext hik hjl)⟩\n      · apply Finset.mem_union_right\n        exact Finset.mem_image.mpr\n          ⟨q.1,hp,Prod.ext rfl (Prod.ext hjk hil)⟩\n  have hD : D.card≤2*(m-1)^2 := by\n    calc\n      D.card≤(P.image fun a : ℕ×ℕ => (a,a)).card+\n          (P.image fun a : ℕ×ℕ => (a,(a.2,a.1))).card := Finset.card_union_le _ _\n      _≤P.card+P.card := Nat.add_le_add (Finset.card_image_le) (Finset.card_image_le)\n      _=2*(m-1)^2 := by simp only [P,Finset.card_product,Finset.card_range]; ring\n  calc\n    _≤(nontrivialOffsetQuads N m ∪ D).card := Finset.card_le_card hsub\n    _≤(nontrivialOffsetQuads N m).card+D.card := Finset.card_union_le _ _\n    _≤nontrivialOffsetEnergy N m+2*(m-1)^2 := Nat.add_le_add_left hD _\n\n/-- Source-exact full energy is bounded by the native carry count plus the diagonals. -/\ntheorem offsetEnergy_le_nontrivial_add (N m : ℕ) :\n    offsetEnergy N m≤nontrivialOffsetEnergy N m+2*(m-1)^2 := by\n  rw [offsetEnergy_eq_nat_card]\n  exact nat_offset_energy_le_nontrivial N m\n\n\n\n/-- Transposing two tuple coordinates aligns the generic ratio-energy\ncount with the literal original seed pair-sum count. -/\ntheorem labelled_original_seed_energy_eq_offset {p N m : ℕ}\n    (gamma : (ZMod p)ˣ) (hm : m.Prime) (horder : 8*m^2 < orderOf gamma) :\n    labelledEnergy Finset.univ\n      (fun i : Fin (m-1) => (progressionSeed gamma N m (i.val+1)).step)=offsetEnergy N m := by\n  classical\n  rw [←originalSeedEnergy_eq_offsetEnergy gamma hm horder]\n  unfold labelledEnergy originalSeedEnergy\n  simp only [Finset.univ_product_univ]\n  apply Finset.card_bij (fun q _ => ((q.1.1,q.2.1),(q.1.2,q.2.2)))\n  · intro q hq\n    simpa only [Finset.mem_filter,Finset.mem_univ,true_and] using hq\n  · intro a _ b _ he\n    have hi := congrArg (fun q => ((q.1.1,q.2.1),(q.1.2,q.2.2))) he\n    exact hi\n  · intro q hq\n    refine ⟨((q.1.1,q.2.1),(q.1.2,q.2.2)),?_,rfl⟩\n    simpa only [Finset.mem_filter,Finset.mem_univ,true_and] using hq\n\n/-- Exact original source tradeoff, with the full energy controlled by the\nnative nontrivial carry count. The analytic actual-input supply is separate. -/\ntheorem literal_original_moment_energy_tradeoff {p N m J : ℕ}\n    (hp : p.Prime) (hm : m.Prime) (hN : m.Coprime N)\n    (gamma beta : (ZMod p)ˣ) (horder : 8*m^2 < orderOf gamma)\n    (hJ : J≤orderOf beta) (hJpos : 0<J) (hM : m-1<p)\n    (w L : ℕ) (hcover : L≤w*J)\n    (H K : (ZMod p)[X]) (hH : H.coeff 0=1)\n    (hHK : (H : PowerSeries (ZMod p))*(∑ ik : Fin (m-1) × Fin J,\n      positiveMoments (((progressionSeed gamma N m (ik.1.val+1)).step*\n        beta^ik.2.val : (ZMod p)ˣ) : ZMod p))=(K : PowerSeries (ZMod p))) :\n    (m-1)^4*L≤16*w*H.natDegree^2*(nontrivialOffsetEnergy N m+2*(m-1)^2) := by\n  classical\n  let x := fun i : Fin (m-1) => (progressionSeed gamma N m (i.val+1)).step\n  have hsource : ∀ y∈Finset.univ.image x,\n      ((Finset.univ : Finset (Fin (m-1))).filter fun i => x i=y).card≤2 := by\n    intro y _\n    exact original_seed_fiber_card_le_two gamma hm hN horder y\n  have he := geometric_moment_source_energy_tradeoff hp x beta hsource\n    hJ hJpos hM w L hcover H K hH hHK\n  rw [labelled_original_seed_energy_eq_offset gamma hm horder] at he\n  exact he.trans (Nat.mul_le_mul_left _ (offsetEnergy_le_nontrivial_add N m))\n\n\nend RiemannGaussian.SemiprimeSeedEnergyAcquisitionObstruction\n","RiemannGaussian.SemiprimeSourceCodeArrays":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeArrayOps\nimport OpenAISemiprime.Algorithms.SubexponentialSAT.SubexpRowInterpolation\n\n/-! # Coefficient arrays from finite source interpolation expressions\nRuntime expressions contain only rational constants, addition and multiplication.\nPolynomial objects occur only in the correctness specification.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceCodeArrays\nopen scoped BigOperators\nopen Polynomial SemiprimeJetArray SemiprimeArrayOps\nopen OAI.Algorithms.SubexponentialSAT.SubexpRowInterpolation\n\n/-- Execute a finite source expression, caching both recursive array results. -/\ndef compile (J : ℕ) : PolynomialCode ℚ → InverseReport\n  | .constant a => ⟨Array.ofFn (fun i : Fin J => if i.val=0 then a else 0),0,0⟩\n  | .indeterminate => ⟨Array.ofFn (fun i : Fin J => if i.val=1 then 1 else 0),0,0⟩\n  | .add p q =>\n      let a := compile J p\n      let b := compile J q\n      let out := addJet a.coefficients b.coefficients J\n      ⟨out.coefficients,a.arithmetic+b.arithmetic+out.arithmetic,\n        a.reads+b.reads+out.reads⟩\n  | .mul p q =>\n      let a := compile J p\n      let b := compile J q\n      let out := multiply a.coefficients b.coefficients J\n      ⟨out.coefficients,a.arithmetic+b.arithmetic+out.arithmetic,\n        a.reads+b.reads+out.reads⟩\n\n/-- Every executed expression returns exactly the requested array width. -/\ntheorem compile_size (J : ℕ) (p : PolynomialCode ℚ) :\n    (compile J p).coefficients.size=J := by\n  cases p <;> simp [compile, addJet_size, multiply_size]\n\n/-- Low coefficients are actual coefficients of the finite source expression. -/\ntheorem compile_coefficient (J : ℕ) (p : PolynomialCode ℚ) (i : ℕ) (hi : i<J) :\n    coefficient (compile J p).coefficients i = p.denote.coeff i := by\n  induction p generalizing i with\n  | constant a => simp [compile, ofFn_coefficient, hi, PolynomialCode.denote, coeff_C]\n  | indeterminate => simp [compile, ofFn_coefficient, hi, PolynomialCode.denote, coeff_X, eq_comm]\n  | add p q hp hq =>\n    change coefficient (addJet (compile J p).coefficients (compile J q).coefficients J).coefficients i = _\n    rw [addJet_coefficient _ _ J i hi]\n    simpa only [PolynomialCode.denote,coeff_add] using congrArg₂ (·+·) (hp i hi) (hq i hi)\n  | mul p q hp hq =>\n    change coefficient (multiply (compile J p).coefficients (compile J q).coefficients J).coefficients i = _\n    rw [multiply_coefficient _ _ J i hi, PolynomialCode.denote, coeff_mul,\n      Finset.Nat.sum_antidiagonal_eq_sum_range_succ_mk]\n    apply Finset.sum_congr rfl\n    intro k hk\n    have hki : k ≤ i := Nat.le_of_lt_succ (Finset.mem_range.mp hk)\n    rw [hp k (by omega),hq (i-k) (by omega)]\n\n/-- Actual scalar-operation count, bounded by the finite expression tree size. -/\ndef nodes : PolynomialCode ℚ → ℕ\n  | .constant _ => 1\n  | .indeterminate => 1\n  | .add p q => nodes p+nodes q+1\n  | .mul p q => nodes p+nodes q+1\n\n/-- The cached expression interpreter performs at most quadratic-width work per node. -/\ntheorem compile_arithmetic (J : ℕ) (p : PolynomialCode ℚ) :\n    (compile J p).arithmetic ≤ nodes p * (J*(J+1)+J) := by\n  induction p with\n  | constant a => simp [compile,nodes]\n  | indeterminate => simp [compile,nodes]\n  | add p q hp hq =>\n    simp only [compile,nodes]\n    have ho := (addJet_work (compile J p).coefficients (compile J q).coefficients J).1\n    rw [ho]\n    nlinarith\n  | mul p q hp hq =>\n    simp only [compile,nodes]\n    have ho := (multiply_work (compile J p).coefficients (compile J q).coefficients J).1\n    rw [ho]\n    nlinarith\n\n/-- Cached coefficient reads are quadratic in width per finite expression node. -/\ntheorem compile_reads (J : ℕ) (p : PolynomialCode ℚ) :\n    (compile J p).reads ≤ nodes p * (J*(J+1)+2*J) := by\n  induction p with\n  | constant a => simp [compile,nodes]\n  | indeterminate => simp [compile,nodes]\n  | add p q hp hq =>\n    simp only [compile,nodes]\n    have ho := (addJet_work (compile J p).coefficients (compile J q).coefficients J).2\n    rw [ho]\n    nlinarith\n  | mul p q hp hq =>\n    simp only [compile,nodes]\n    have ho := (multiply_work (compile J p).coefficients (compile J q).coefficients J).2\n    rw [ho]\n    nlinarith\n\n#print axioms compile_coefficient\nend RiemannGaussian.SemiprimeSourceCodeArrays\n","RiemannGaussian.SemiprimeSourceHistogramArithmeticBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramArithmetic\n\n/-! # Fixed-depth physical histogram arithmetic bounds\nAll report clocks are retained. Width premises concern only actual acquired\ninput payloads; every intermediate shape follows the executed raw operators.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeSourceHistogramArithmeticBounds\nopen SemiprimeRationalBits SemiprimeSourceHistogramArithmetic\nopen SemiprimeSourceIncidenceHistogram (Feature)\nopen SemiprimeReportPolynomialGrowth\n/-- Enlarge only an actually proved input/output physical shape. -/\ntheorem widen {x : RationalWord} {A B : ℕ} (hx : Width x A) (h : A ≤ B) : Width x B :=\n  ⟨hx.1.trans h,hx.2.trans h⟩\n\n/-- Uniform raw arithmetic shape after a fixed number of operator levels. -/\ndef grow (W d : ℕ) : ℕ := 4^d*(W+2)\n\n/-- One fixed quadratic budget dominates every primitive in depth at most 32. -/\ndef unitBudget (W : ℕ) : ℕ := 300*(grow W 32+1)^2+1000\n\n/-- Positive widths are intrinsic to the chosen fixed arithmetic envelope. -/\ntheorem grow_pos (W d : ℕ) : 1 ≤ grow W d := by\n  have h : 0<4^d*(W+2) := by positivity\n  exact h\n\n/-- Larger fixed depths conservatively enlarge physical shape bounds. -/\ntheorem grow_mono (W : ℕ) {a b : ℕ} (h : a ≤ b) : grow W a ≤ grow W b := by\n  unfold grow\n  gcongr\n\n/-- Each raw binary operator fits the next fixed level. -/\ntheorem grow_step (W d : ℕ) : 3*grow W d+1 ≤ grow W (d+1) := by\n  have hp := grow_pos W d\n  simp only [grow,pow_succ]\n  unfold grow at hp\n  nlinarith\n\n/-- Literal unsigned inputs are valid physical shapes. -/\ntheorem unsigned_width (bits : List Bool) (W : ℕ) (hW : 1 ≤ W) (hb : bits.length ≤ W) :\n    Width (unsigned bits) W := ⟨hb,by simpa only [unsigned,List.length_cons,List.length_nil] using hW⟩\n\n/-- Literal signed minus one has constant physical width. -/\ntheorem minusOne_width (W : ℕ) (hW : 1 ≤ W) : Width minusOne W := ⟨hW,hW⟩\n\n/-- Static raw addition has derived next-level width and paid lower clocks. -/\ntheorem add_bound (x y : RationalReport) (W d : ℕ) (hd : d ≤ 32)\n    (hx : Width x.word (grow W d)) (hy : Width y.word (grow W d)) :\n    Width (add x y).word (grow W (d+1)) ∧\n      (add x y).clock ≤ x.clock+y.clock+unitBudget W := by\n  have h := rawAddBits_cost_width x.word y.word hx hy\n  refine ⟨widen h.2 (grow_step W d),?_⟩\n  have hg := grow_mono W hd\n  have hc : 300*(grow W d+1)^2 ≤ 300*(grow W 32+1)^2 := by gcongr\n  unfold add unitBudget\n  dsimp only\n  omega\n\n/-- Static raw multiplication has the same fixed-depth shape/work envelope. -/\ntheorem mul_bound (x y : RationalReport) (W d : ℕ) (hd : d ≤ 32)\n    (hx : Width x.word (grow W d)) (hy : Width y.word (grow W d)) :\n    Width (mul x y).word (grow W (d+1)) ∧\n      (mul x y).clock ≤ x.clock+y.clock+unitBudget W := by\n  have h := rawMulBits_cost_width x.word y.word hx hy\n  refine ⟨widen h.2 (grow_step W d),?_⟩\n  have hg := grow_mono W hd\n  have hc : 300*(grow W d+1)^2 ≤ 300*(grow W 32+1)^2 := by gcongr\n  unfold mul unitBudget\n  dsimp only\n  omega\n\n/-- Sign-bit negation has no unproved word-size or normalization condition. -/\ntheorem neg_bound (x : RationalReport) (W d : ℕ) (hx : Width x.word (grow W d)) :\n    Width (neg x).word (grow W d) ∧ (neg x).clock ≤ x.clock+unitBudget W := by\n  refine ⟨hx,?_⟩\n  unfold neg rawNegBits unitBudget\n  dsimp only\n  omega\n\n/-- All coefficient shapes and the once-only actual L−1 acquisition cost. -/\ntheorem coefficient_bound (L : List Bool) (W : ℕ) (hW : 1 ≤ W) (hL : L.length ≤ W) :\n    (∀ f : Feature,Width (coefficientWord (coefficients L) f) (grow W 1)) ∧\n      (coefficients L).clock ≤ unitBudget W := by\n  have hu := unsigned_width L W hW hL\n  have hm := minusOne_width W hW\n  have hraw := rawAddBits_cost_width (unsigned L) minusOne hu hm\n  have hgw : W ≤ grow W 0 := by simp [grow]\n  have hg : W ≤ grow W 1 := hgw.trans (grow_mono W (by decide : 0 ≤ 1))\n  have hp : Width (coefficients L).predecessor (grow W 1) :=\n    widen hraw.2 ((Nat.add_le_add_right (Nat.mul_le_mul_left 3 hgw) 1).trans (grow_step W 0))\n  refine ⟨?_,?_⟩\n  · intro f\n    fin_cases f\n    · exact unsigned_width [true] _ (grow_pos W 1) (by simp only [List.length_cons,List.length_nil];exact grow_pos W 1)\n    · exact hp\n    · exact widen hu hg\n    · exact widen hm hg\n  · have hmax : W ≤ grow W 32 := hgw.trans (grow_mono W (by decide : 0 ≤ 32))\n    have hc : 300*(W+1)^2 ≤ 300*(grow W 32+1)^2 := by gcongr\n    unfold coefficients unitBudget\n    dsimp only\n    omega\n\n/-- Every term's intermediate shapes and actual producer report are derived. -/\ntheorem term_bound (L : List Bool)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State) (fg : Feature × Feature)\n    (W : ℕ) (hW : 1 ≤ W) (hL : L.length ≤ W)\n    (hh : (hist fg.1 fg.2).bits.length ≤ W) :\n    Width (term (coefficients L) hist fg).word (grow W 3) ∧\n      (term (coefficients L) hist fg).clock ≤ (hist fg.1 fg.2).clock+2*unitBudget W := by\n  have hs := (coefficient_bound L W hW hL).1\n  have hfirst := rawMulBits_cost_width (coefficientWord (coefficients L) fg.1)\n    (coefficientWord (coefficients L) fg.2) (hs fg.1) (hs fg.2)\n  have hfirstw := widen hfirst.2 (grow_step W 1)\n  have hu := unsigned_width (hist fg.1 fg.2).bits W hW hh\n  have hW2 : W ≤ grow W 2 := (show W ≤ grow W 0 by simp [grow]).trans\n    (grow_mono W (by decide : 0 ≤ 2))\n  have hout := rawMulBits_cost_width\n    (rawMulBits (coefficientWord (coefficients L) fg.1) (coefficientWord (coefficients L) fg.2)).word\n    (unsigned (hist fg.1 fg.2).bits) hfirstw (widen hu hW2)\n  refine ⟨widen hout.2 (grow_step W 2),?_⟩\n  have h1 : 300*(grow W 1+1)^2 ≤ 300*(grow W 32+1)^2 := by\n    have h := grow_mono W (by decide : 1 ≤ 32)\n    gcongr\n  have h2 : 300*(grow W 2+1)^2 ≤ 300*(grow W 32+1)^2 := by\n    have h := grow_mono W (by decide : 2 ≤ 32)\n    gcongr\n  have houtc : (rawMulBits\n      (rawMulBits (coefficientWord (coefficients L) fg.1) (coefficientWord (coefficients L) fg.2)).word\n      (unsigned (hist fg.1 fg.2).bits)).clock ≤ 300*(grow W 2+1)^2 := hout.1\n  unfold term unitBudget\n  dsimp only\n  omega\n\n/-- The actual constant-size list fold pays every term producer and raw adder. -/\ntheorem sumTerms_bound (L : List Bool)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State)\n    (pairs : List (Feature × Feature)) (W : ℕ) (hW : 1 ≤ W) (hL : L.length ≤ W)\n    (hh : ∀ f g,(hist f g).bits.length ≤ W) (hlen : pairs.length ≤ 16) :\n    Width (sumTerms (coefficients L) hist pairs).word (grow W (pairs.length+3)) ∧\n      (sumTerms (coefficients L) hist pairs).clock ≤\n        (pairs.map (fun fg => (hist fg.1 fg.2).clock)).sum+(3*pairs.length+1)*unitBudget W := by\n  induction pairs with\n  | nil =>\n    refine ⟨⟨by simp [sumTerms,zeroWord],by simpa only [sumTerms,zeroWord,List.length_cons,List.length_nil] using grow_pos W 3⟩,?_⟩\n    simp only [sumTerms,List.map_nil,List.sum_nil,List.length_nil]\n    unfold unitBudget\n    omega\n  | cons fg pairs ih =>\n    have hrest := ih (by simp only [List.length_cons] at hlen;omega)\n    have hterm := term_bound L hist fg W hW hL (hh fg.1 fg.2)\n    have hw := widen hterm.1 (grow_mono W (show 3 ≤ pairs.length+3 by omega))\n    have hraw := rawAddBits_cost_width (term (coefficients L) hist fg).word\n      (sumTerms (coefficients L) hist pairs).word hw hrest.1\n    have hmax := grow_mono W (show pairs.length+3 ≤ 32 by simp only [List.length_cons] at hlen;omega)\n    have hc : 300*(grow W (pairs.length+3)+1)^2 ≤ 300*(grow W 32+1)^2 := by gcongr\n    refine ⟨?_,?_⟩\n    · simpa only [sumTerms,List.length_cons,Nat.add_assoc] using widen hraw.2 (grow_step W (pairs.length+3))\n    · have hpaid : (rawAddBits (term (coefficients L) hist fg).word\n          (sumTerms (coefficients L) hist pairs).word).clock+3 ≤ unitBudget W := by\n        unfold unitBudget\n        omega\n      simp only [sumTerms,List.map_cons,List.sum_cons,List.length_cons]\n      nlinarith [hrest.2,hterm.2]\n\n/-- Literal feature list has exactly sixteen entries. -/\ntheorem featurePairs_length : featurePairs.length=16 := by decide\n\n/-- Complete physical incidence arithmetic has fixed-degree width and clock overhead.\nThe actual sixteen histogram report clocks are summed, never replaced by values. -/\ntheorem incidence_bound (cache : SemiprimeSourceHistogramScales.Cache)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State)\n    (W : ℕ) (hW : 1 ≤ W) (hL : cache.alphabet.length ≤ W) (hS : cache.square.length ≤ W)\n    (hh : ∀ f g,(hist f g).bits.length ≤ W) :\n    Width (incidence cache hist).word (grow W 20) ∧\n      (incidence cache hist).clock ≤\n        (featurePairs.map (fun fg => (hist fg.1 fg.2).clock)).sum+60*unitBudget W := by\n  have hcs := coefficient_bound cache.alphabet W hW hL\n  have ht := sumTerms_bound cache.alphabet hist featurePairs W hW hL hh (by rw [featurePairs_length])\n  rw [featurePairs_length] at ht\n  have hu := unsigned_width cache.square W hW hS\n  have hmax : W ≤ grow W 19 := (show W ≤ grow W 0 by simp [grow]).trans\n    (grow_mono W (by decide : 0 ≤ 19))\n  have hout := rawMulBits_cost_width (unsigned cache.square)\n    (sumTerms (coefficients cache.alphabet) hist featurePairs).word (widen hu hmax) ht.1\n  have hc : 300*(grow W 19+1)^2 ≤ 300*(grow W 32+1)^2 := by\n    have h := grow_mono W (by decide : 19 ≤ 32)\n    gcongr\n  refine ⟨widen hout.2 (grow_step W 19),?_⟩\n  have hpaid : (rawMulBits (unsigned cache.square)\n      (sumTerms (coefficients cache.alphabet) hist featurePairs).word).clock+1000 ≤ unitBudget W := by\n    have hr := hout.1\n    change (rawMulBits (unsigned cache.square)\n      (sumTerms (coefficients cache.alphabet) hist featurePairs).word).clock ≤ 300*(grow W 19+1)^2 at hr\n    unfold unitBudget\n    omega\n  unfold incidence\n  dsimp only\n  nlinarith [hcs.2,ht.2]\n\n/-- Actual signed head arithmetic has fixed-depth physical shape and retains\nall Q/fixed/free/histogram acquisition reports once. -/\ntheorem head_bound (cache : SemiprimeSourceHistogramScales.Cache)\n    (q p f : SemiprimeSourceCompactBits.Report) (C : RationalReport) (W : ℕ)\n    (hW : 1 ≤ W) (hA : cache.fourth.length ≤ W) (hG : cache.head.length ≤ W)\n    (hq : q.bits.length ≤ W) (hp : p.bits.length ≤ W) (hf : f.bits.length ≤ W)\n    (hC : Width C.word W) :\n    Width (head cache q p f C).word (grow W 8) ∧\n      (head cache q p f C).clock ≤ q.clock+p.clock+f.clock+C.clock+30*unitBudget W := by\n  let qw := borrowed (unsigned q.bits)\n  let pw := borrowed (unsigned p.bits)\n  let fw := borrowed (unsigned f.bits)\n  let cw := borrowed C.word\n  let aw := borrowed (unsigned cache.fourth)\n  let gw := borrowed (unsigned cache.head)\n  let tw := borrowed (unsigned [false,true])\n  have hbase : W ≤ grow W 0 := by simp [grow]\n  have u (bits : List Bool) (hb : bits.length ≤ W) :\n      Width (borrowed (unsigned bits)).word (grow W 0) := widen (unsigned_width bits W hW hb) hbase\n  have hqw := u q.bits hq\n  have hpw := u p.bits hp\n  have hfw := u f.bits hf\n  have hcw : Width cw.word (grow W 0) := widen hC hbase\n  have haw := u cache.fourth hA\n  have hgw := u cache.head hG\n  have htw : Width tw.word (grow W 0) := unsigned_width _ _ (grow_pos W 0) (by simp [grow])\n  let qf := mul qw fw\n  have hqf := mul_bound qw fw W 0 (by decide) hqw hfw\n  let li := add cw qf\n  have hli := add_bound cw qf W 1 (by decide)\n    (widen hcw (grow_mono W (by decide : 0 ≤ 1))) hqf.1\n  let left := mul aw li\n  have hleft := mul_bound aw li W 2 (by decide)\n    (widen haw (grow_mono W (by decide : 0 ≤ 2))) hli.1\n  let tp := mul tw pw\n  have htp := mul_bound tw pw W 0 (by decide) htw hpw\n  let tpf := mul tp fw\n  have htpf := mul_bound tp fw W 1 (by decide) htp.1\n    (widen hfw (grow_mono W (by decide : 0 ≤ 1)))\n  let ff := mul fw fw\n  have hff := mul_bound fw fw W 0 (by decide) hfw hfw\n  let positive := add tpf ff\n  have hpositive := add_bound tpf ff W 2 (by decide) htpf.1\n    (widen hff.1 (grow_mono W (by decide : 1 ≤ 2)))\n  let nf := neg fw\n  have hnf := neg_bound fw W 0 hfw\n  let inner := add positive nf\n  have hinner := add_bound positive nf W 3 (by decide) hpositive.1\n    (widen hnf.1 (grow_mono W (by decide : 0 ≤ 3)))\n  let gq := mul gw qw\n  have hgq := mul_bound gw qw W 0 (by decide) hgw hqw\n  let right := mul gq inner\n  have hright := mul_bound gq inner W 4 (by decide)\n    (widen hgq.1 (grow_mono W (by decide : 1 ≤ 4))) hinner.1\n  let out := add left right\n  have hout := add_bound left right W 5 (by decide)\n    (widen hleft.1 (grow_mono W (by decide : 3 ≤ 5))) hright.1\n  refine ⟨widen hout.1 (grow_mono W (by decide : 6 ≤ 8)),?_⟩\n  have hqw0 : qw.clock=0 := rfl\n  have hpw0 : pw.clock=0 := rfl\n  have hfw0 : fw.clock=0 := rfl\n  have hcw0 : cw.clock=0 := rfl\n  have haw0 : aw.clock=0 := rfl\n  have hgw0 : gw.clock=0 := rfl\n  have htw0 : tw.clock=0 := rfl\n  have hunit : 1000 ≤ unitBudget W := by unfold unitBudget;omega\n  change q.clock+p.clock+f.clock+C.clock+out.clock+1000 ≤ _\n  nlinarith [hqf.2,hli.2,hleft.2,htp.2,htpf.2,hff.2,hpositive.2,hnf.2,hinner.2,hgq.2,hright.2,hout.2]\n\n/-- Actual weighting has three physical operators; both complete lane clocks stay. -/\ntheorem weighted_bound (cache : SemiprimeSourceHistogramScales.Cache) (I H : RationalReport)\n    (W : ℕ) (hW : 1 ≤ W) (hA : cache.weights.incidence.length ≤ W)\n    (hB : cache.weights.head.length ≤ W) (hI : Width I.word W) (hH : Width H.word W) :\n    Width (weighted cache I H).word (grow W 2) ∧\n      (weighted cache I H).clock ≤ I.clock+H.clock+3*unitBudget W := by\n  let aw := borrowed (unsigned cache.weights.incidence)\n  let bw := borrowed (unsigned cache.weights.head)\n  have hbase : W ≤ grow W 0 := by simp [grow]\n  have haw : Width aw.word (grow W 0) := widen (unsigned_width _ _ hW hA) hbase\n  have hbw : Width bw.word (grow W 0) := widen (unsigned_width _ _ hW hB) hbase\n  have hleft := mul_bound aw I W 0 (by decide) haw (widen hI hbase)\n  have hright := mul_bound bw H W 0 (by decide) hbw (widen hH hbase)\n  have hout := add_bound (mul aw I) (mul bw H) W 1 (by decide) hleft.1 hright.1\n  refine ⟨hout.1,?_⟩\n  have ha0 : aw.clock=0 := rfl\n  have hb0 : bw.clock=0 := rfl\n  change (add (mul aw I) (mul bw H)).clock ≤ _\n  nlinarith [hleft.2,hright.2,hout.2]\n\n/-- Original input-width caps can be enlarged without changing the executed data. -/\ntheorem grow_width_mono {W V : ℕ} (h : W ≤ V) (d : ℕ) : grow W d ≤ grow V d := by\n  unfold grow\n  gcongr\n\n/-- Fixed-depth arithmetic budgets are monotone in actual input payload width. -/\ntheorem unitBudget_mono {W V : ℕ} (h : W ≤ V) : unitBudget W ≤ unitBudget V := by\n  unfold unitBudget\n  have hg := grow_width_mono h 32\n  gcongr\n\n/-- Constants are fixed before every source query or acquired payload width. -/\ntheorem unitBudget_monomial : ∃ C k : ℕ,∀ W,unitBudget W ≤ C*(W+1)^k := by\n  have h : SemiprimeReportPolynomialGrowth.Bound (fun W => unitBudget W) := by\n    simp only [unitBudget,grow]\n    boundArithmetic\n  exact h\n\n/-- A term never discards its actual histogram producer clock. -/\ntheorem term_retains (cache : Coefficients)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State) (fg : Feature × Feature) :\n    (hist fg.1 fg.2).clock ≤ (term cache hist fg).clock := by\n  unfold term\n  dsimp only\n  omega\n\n/-- Literal finite summation retains every actually invoked histogram producer. -/\ntheorem sumTerms_retains (cache : Coefficients)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State) (pairs : List (Feature × Feature)) :\n    (pairs.map (fun fg => (hist fg.1 fg.2).clock)).sum ≤ (sumTerms cache hist pairs).clock := by\n  induction pairs with\n  | nil => simp [sumTerms]\n  | cons fg pairs ih =>\n    have ht := term_retains cache hist fg\n    simp only [sumTerms,List.map_cons,List.sum_cons]\n    omega\n\n/-- Complete incidence arithmetic retains the whole actual sixteen-producer ledger. -/\ntheorem incidence_retains (cache : SemiprimeSourceHistogramScales.Cache)\n    (hist : Feature → Feature → SemiprimeSourceHistogramSquares.State) :\n    (featurePairs.map (fun fg => (hist fg.1 fg.2).clock)).sum ≤ (incidence cache hist).clock := by\n  have h := sumTerms_retains (coefficients cache.alphabet) hist featurePairs\n  unfold incidence\n  dsimp only\n  omega\n\n/-- Actual head input acquisitions are retained independently of their values. -/\ntheorem head_retains (cache : SemiprimeSourceHistogramScales.Cache)\n    (q p f : SemiprimeSourceCompactBits.Report) (C : RationalReport) :\n    q.clock+p.clock+f.clock+C.clock ≤ (head cache q p f C).clock := by\n  unfold head\n  dsimp only\n  omega\n\nend RiemannGaussian.SemiprimeSourceHistogramArithmeticBounds\n","RiemannGaussian.SemiprimeSourceHistogramCountInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceCompactBits\n\n/-! # Count actual original records with compact physical increments\nNo native length answer is encoded; the actual list constructors drive the loop.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramCountInput\nopen SemiprimeBitArithmetic\nopen SemiprimeSourceCompactBits (Compact Report)\n\n/-- Inspect each actual record cell and retain its physical counter increment. -/\ndef count {A : Type*} : List A → Report\n  | [] => ⟨[],1⟩\n  | _::xs =>\n    let old := count xs\n    let next := SemiprimeSourceCompactBits.increment old.bits\n    ⟨next.bits,old.clock+next.clock+5⟩\n\n/-- The actual records, not supplied cardinality advice, determine the output. -/\ntheorem count_value {A : Type*} (xs : List A) : bitValue (count xs).bits=xs.length := by\n  induction xs with\n  | nil => rfl\n  | cons a xs ih => simp only [count,SemiprimeSourceCompactBits.increment_value,ih,List.length_cons]\n\n/-- Every recursively acquired count is compact. -/\ntheorem count_compact {A : Type*} (xs : List A) : Compact (count xs).bits := by\n  cases xs with\n  | nil => trivial\n  | cons a xs => exact SemiprimeSourceCompactBits.increment_compact _\n\n/-- Original list count gives intrinsic logarithmic physical storage. -/\ntheorem count_length {A : Type*} (xs : List A) :\n    (count xs).bits.length ≤ Nat.clog 2 (xs.length+1) := by\n  have h := SemiprimeSourceCompactBits.compact_length_clog _ (count_compact xs)\n  simpa only [count_value] using h\n\n/-- One physical increment and visited record cell, in original count width. -/\ndef stepBudget (M : ℕ) : ℕ := 30*(Nat.clog 2 (M+1)+2)+20\n\n/-- All recursive tails fit the same original acquired list-count cap. -/\ntheorem count_clock_cap {A : Type*} (xs : List A) (M : ℕ) (hlen : xs.length ≤ M) :\n    (count xs).clock ≤ xs.length*stepBudget M+1 := by\n  induction xs with\n  | nil => simp [count]\n  | cons a xs ih =>\n    have htail := ih (by simp only [List.length_cons] at hlen;omega)\n    have hw : (count xs).bits.length ≤ Nat.clog 2 (M+1) :=\n      (count_length xs).trans (Nat.clog_mono_right 2 (by simp only [List.length_cons] at hlen;omega))\n    have hi := SemiprimeSourceCompactBits.increment_clock (count xs).bits\n      (Nat.clog 2 (M+1)+1) (by omega) (by omega)\n    unfold stepBudget at htail ⊢\n    simp only [count,List.length_cons]\n    nlinarith\n\n/-- Complete list-driven count clock, no counter/height/work oracle. -/\ntheorem count_clock {A : Type*} (xs : List A) :\n    (count xs).clock ≤ xs.length*stepBudget xs.length+1 := count_clock_cap xs xs.length le_rfl\n\nend RiemannGaussian.SemiprimeSourceHistogramCountInput\n","RiemannGaussian.SemiprimeSourceHistogramHeadBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramRowKeys\nimport RiemannGaussian.SemiprimeSourceHistogramFeatureBits\nimport RiemannGaussian.SemiprimeSourceHistogramDictRefinement\n\n/-! # Actual one-pass fixed/free head histogram acquisition\nFree vertices only increment their actual counter. Every fixed vertex performs\none prefix-ID lookup and one all-coordinate row query before histogramming.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramHeadBits\nopen SemiprimeBitArithmetic SemiprimeMaterializedWords\nopen SemiprimeSourceHistogramTrie (Trie)\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- Original vertex code and its once-acquired physical dictionary key. -/\nstructure Vertex where\n  /-- Original native finite-index metadata for the interval mask. -/\n  code : ℕ\n  /-- Actual compact physical variable key. -/\n  key : List Bool\n\n/-- Acquire one original variable key with its full encoder report. -/\ndef vertex {n : ℕ} (i : Fin n) : Run Vertex :=\n  let out := SemiprimeSourceHistogramPortKeys.encodeKey i.val\n  ⟨⟨i.val,out.bits⟩,out.clock+2⟩\n\n/-- Actual static vertex-key cache in the original supplied finite list order. -/\ndef verticesWith {n : ℕ} : List (Fin n) → Run (List Vertex)\n  | [] => ⟨[],1⟩\n  | i::is =>\n    let first := vertex i\n    let tail := verticesWith is\n    ⟨first.value::tail.value,first.work+tail.work+3⟩\n\n/-- Original-input static cache acquisition with paid finite-index generation. -/\ndef acquireVertices (n : ℕ) : Run (List Vertex) :=\n  let indices := SemiprimePaidFiniteEnumerationLists.fin n\n  let out := verticesWith indices.value\n  ⟨out.value,indices.work+out.work+3⟩\n\n/-- Exact acquired original vertex order. -/\ntheorem verticesWith_value {n : ℕ} (is : List (Fin n)) :\n    (verticesWith is).value=is.map (fun i => (vertex i).value) := by\n  induction is with\n  | nil => rfl\n  | cons i is ih => simp only [verticesWith,List.map_cons,ih]\n\n/-- Every original finite vertex occurs once in its actual original order. -/\ntheorem acquireVertices_value (n : ℕ) :\n    (acquireVertices n).value=(List.finRange n).map (fun i => (vertex i).value) := by\n  simp only [acquireVertices,verticesWith_value,SemiprimePaidFiniteEnumerationLists.fin_value]\n\n/-- Original input acquisition derives physical key value and compactness. -/\ntheorem vertex_rep {n : ℕ} (i : Fin n) :\n    Compact (vertex i).value.key ∧ bitValue (vertex i).value.key=i.val :=\n  ⟨SemiprimeSourceHistogramPortKeys.encodeKey_compact _,\n    SemiprimeSourceHistogramPortKeys.encodeKey_value _⟩\n\n/-- Append actual histogram key references by a paid list-spine traversal. -/\ndef appendKeys : List (List Bool) → List (List Bool) → Run (List (List Bool))\n  | [],ys => ⟨ys,1⟩\n  | x::xs,ys =>\n    let out := appendKeys xs ys\n    ⟨x::out.value,out.work+3⟩\n\n/-- No reordering or duplication occurs in the actual key append. -/\ntheorem appendKeys_value (xs ys : List (List Bool)) :\n    (appendKeys xs ys).value=xs++ys := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [appendKeys,List.cons_append,ih]\n\n/-- Actual list-spine copies are linear in the newly produced key list. -/\ntheorem appendKeys_work (xs ys : List (List Bool)) :\n    (appendKeys xs ys).work=3*xs.length+1 := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [appendKeys,List.length_cons,ih];omega\n\n/-- Actual all-coordinate key stream and physical fixed/free counters. -/\nstructure HeadData where\n  /-- Actual fixed-vertex coordinate-colour keys, preserving all multiplicities. -/\n  keys : List (List Bool)\n  /-- Physical number of fixed original vertices. -/\n  fixed : List Bool\n  /-- Physical number of free original vertices. -/\n  free : List Bool\n  /-- All key queries, appends, increments and original control stages. -/\n  clock : ℕ\n\n/-- Traverse the cached static vertices once; free vertices skip every label read. -/\ndef produce (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) : List Vertex → HeadData\n  | [] => ⟨[],[],[],1⟩\n  | v::vs =>\n    let rest := produce cache dict k s vs\n    if SemiprimeSourceHistogramFeatureBits.active k s v.code then\n      let total := SemiprimeSourceCompactBits.increment rest.free\n      ⟨rest.keys,rest.fixed,total.bits,rest.clock+total.clock+12⟩\n    else\n      let id := SemiprimeSourceHistogramTrie.lookup dict v.key\n      let row := SemiprimeSourceHistogramRowKeys.readKeys cache.source.dictionary cache.coordinates id.bits\n      let joined := appendKeys row.keys rest.keys\n      let total := SemiprimeSourceCompactBits.increment rest.fixed\n      ⟨joined.value,total.bits,rest.free,\n        rest.clock+id.clock+row.clock+joined.work+total.clock+20⟩\n\n/-- Mathematical exact fixed-vertex key list, with runtime answers only as semantics. -/\ndef keyList (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) : List (List Bool) :=\n  vs.flatMap (fun v => if SemiprimeSourceHistogramFeatureBits.active k s v.code then [] else\n    (SemiprimeSourceHistogramRowKeys.readKeys cache.source.dictionary cache.coordinates\n      (SemiprimeSourceHistogramTrie.stored dict v.key)).keys)\n\n/-- Literal actual key-stream identity, including original vertex-major order. -/\ntheorem produce_keys (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) : (produce cache dict k s vs).keys=keyList cache dict k s vs := by\n  induction vs with\n  | nil => rfl\n  | cons v vs ih =>\n    by_cases ha : SemiprimeSourceHistogramFeatureBits.active k s v.code=true\n    · simp [produce,keyList,ha,ih]\n    · simp [produce,keyList,ha,appendKeys_value,SemiprimeSourceHistogramTrie.lookup_bits,ih]\n\n/-- The acquired physical fixed counter is the actual original interval-filter count. -/\ntheorem produce_fixed (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) : bitValue (produce cache dict k s vs).fixed=\n      (vs.filter (fun v => !(SemiprimeSourceHistogramFeatureBits.active k s v.code))).length := by\n  induction vs with\n  | nil => rfl\n  | cons v vs ih =>\n    by_cases ha : SemiprimeSourceHistogramFeatureBits.active k s v.code=true\n    · simp [produce,ha,ih]\n    · simp [produce,ha,SemiprimeSourceCompactBits.increment_value,ih]\n\n/-- The acquired physical free counter is the actual original interval-filter count. -/\ntheorem produce_free (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) : bitValue (produce cache dict k s vs).free=\n      (vs.filter (fun v => SemiprimeSourceHistogramFeatureBits.active k s v.code)).length := by\n  induction vs with\n  | nil => rfl\n  | cons v vs ih =>\n    by_cases ha : SemiprimeSourceHistogramFeatureBits.active k s v.code=true\n    · simp [produce,ha,SemiprimeSourceCompactBits.increment_value,ih]\n    · simp [produce,ha,ih]\n\n/-- Both actual acquired counters are canonical compact physical words. -/\ntheorem produce_compact (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) :\n    Compact (produce cache dict k s vs).fixed ∧ Compact (produce cache dict k s vs).free := by\n  induction vs with\n  | nil => exact ⟨trivial,trivial⟩\n  | cons v vs ih =>\n    by_cases ha : SemiprimeSourceHistogramFeatureBits.active k s v.code=true\n    · exact ⟨by simpa only [produce,ha,ite_true] using ih.1,\n        by simpa only [produce,ha,ite_true] using\n          SemiprimeSourceCompactBits.increment_compact (produce cache dict k s vs).free⟩\n    · exact ⟨by simpa only [produce,ha,Bool.false_eq_true,ite_false] using\n          SemiprimeSourceCompactBits.increment_compact (produce cache dict k s vs).fixed,\n        by simpa only [produce,ha,Bool.false_eq_true,ite_false] using ih.2⟩\n\n/-- Complete actual head-key acquisition and sparse collision-square output. -/\nstructure Result where\n  /-- Actual physical fixed/free counters and vertex-major coordinate keys. -/\n  head : HeadData\n  /-- Executed sparse dictionary and collision-square accumulator. -/\n  histogram : SemiprimeSourceHistogramSquares.State\n  /-- Complete retained head pass plus actual sparse-histogram report. -/\n  clock : ℕ\n\n/-- Feed the actual acquired key list to the executed histogram, without n² pairs. -/\ndef acquire (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) : Result :=\n  let head := produce cache dict k s vs\n  let squares := SemiprimeSourceHistogramSquares.acquire head.keys\n  ⟨head,squares,head.clock+squares.clock+3⟩\n\n/-- Actual output equals the collision count of the exact original fixed-key stream. -/\ntheorem acquire_value (cache : SemiprimeSourceHistogramRowKeys.QueryCache) (dict : Trie)\n    (k s : ℕ) (vs : List Vertex) :\n    bitValue (acquire cache dict k s vs).histogram.bits=\n      SemiprimeSourceHistogramSquares.collisions (keyList cache dict k s vs) := by\n  simp only [acquire,SemiprimeSourceHistogramSquares.acquire_value,produce_keys]\n\nend RiemannGaussian.SemiprimeSourceHistogramHeadBits\n","RiemannGaussian.SemiprimeSourceHistogramPortKeys":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramMetadata\nimport RiemannGaussian.SemiprimeSourceWordIdEnvironmentBounds\nimport RiemannGaussian.SemiprimeSourceCompactBits\n\n/-! # Direct original port codes and acquired compact physical keys\nNo original index scan, source word, score term or histogram answer is a runtime\nfield. Original typed owner/factor access and natural control keep their explicit\nnative stage. Encoding setup is conservatively magnitude-polynomial, not claimed\nnear-linear; compact output keys have logarithmic width for later lookup passes.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeSourceHistogramPortKeys\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT.LocalExpectation\nopen SemiprimeMaterializedWords SemiprimeBitArithmetic\nopen SemiprimeSourceHistogramMetadata\nopen SemiprimeReportPolynomialGrowth\n\n/-- The exact original left/right variable order is acquired without index searches. -/\ntheorem indices_value (n F Q : ℕ) (arity : Fin F→ℕ) :\n    (acquire n F Q arity).indices=\n      (List.finRange n).map Sum.inl++(List.finRange F).map Sum.inr := by\n  simp only [acquire,SemiprimePaidFiniteEnumerationLists.sum_value,finFast_value]\n\n/-- A supplied injective relabelling preserves the original decidable scan. -/\ntheorem indexCode_map {A B : Type*} [DecidableEq A] [DecidableEq B]\n    (f : A→B) (hf : Function.Injective f) (xs : List A) (a : A) :\n    indexCode (xs.map f) (f a)=indexCode xs a := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih =>\n    simp only [indexCode,List.map_cons,List.idxOf_cons] at ih ⊢\n    by_cases h : x=a <;> simp [hf.eq_iff,h,ih]\n\n/-- Generic decidable-index append law avoids a different structural Sum BEq. -/\ntheorem indexCode_append_mem {A : Type*} [DecidableEq A] (xs ys : List A) (a : A)\n    (ha : a∈xs) : indexCode (xs++ys) a=indexCode xs a := by\n  unfold indexCode\n  exact List.idxOf_append_of_mem ha\n\n/-- Generic absent-left append law for the original decidable-equality scan. -/\ntheorem indexCode_append_notMem {A : Type*} [DecidableEq A] (xs ys : List A) (a : A)\n    (ha : a∉xs) : indexCode (xs++ys) a=xs.length+indexCode ys a := by\n  unfold indexCode\n  exact List.idxOf_append_of_notMem ha\n\n/-- Every actual original owner code is its native vertex index. -/\ntheorem indexCode_inl (n F Q : ℕ) (arity : Fin F→ℕ) (v : Fin n) :\n    indexCode (acquire n F Q arity).indices (.inl v)=v.val := by\n  rw [indices_value,indexCode_append_mem _ _ _ (by simp)]\n  rw [indexCode_map Sum.inl Sum.inl_injective]\n  exact List.idxOf_finRange v\n\n/-- Every actual original factor code is its native factor index plus n. -/\ntheorem indexCode_inr (n F Q : ℕ) (arity : Fin F→ℕ) (e : Fin F) :\n    indexCode (acquire n F Q arity).indices (.inr e)=n+e.val := by\n  rw [indices_value,indexCode_append_notMem _ _ _ (by simp)]\n  rw [List.length_map,List.length_finRange,indexCode_map Sum.inr Sum.inr_injective]\n  exact congrArg (fun k => n+k) (List.idxOf_finRange e)\n\n/-- Acquire actual Boolean key digits and remove high zeros, retaining both reports. -/\ndef encodeKey (k : ℕ) : SemiprimeSourceCompactBits.Report :=\n  let raw := SemiprimeSourceWordIdEnvironment.acquireKey k\n  let out := SemiprimeSourceCompactBits.trim raw.value\n  ⟨out.bits,raw.work+out.clock+3⟩\n\n/-- Exact encoded key value without supplied digits. -/\ntheorem encodeKey_value (k : ℕ) : bitValue (encodeKey k).bits=k := by\n  simp only [encodeKey,SemiprimeSourceCompactBits.trim_value,\n    SemiprimeSourceWordIdEnvironment.acquireKey_value]\n\n/-- Every actual key is compact, including the empty zero key. -/\ntheorem encodeKey_compact (k : ℕ) : SemiprimeSourceCompactBits.Compact (encodeKey k).bits :=\n  SemiprimeSourceCompactBits.trim_compact _\n\n/-- Compact original code width used by subsequent physical dictionary passes. -/\ndef keyWidth (N : ℕ) : ℕ := Nat.clog 2 (N+1)\n\n/-- Width comes from the actual original code cap, not intermediate encoding advice. -/\ntheorem encodeKey_length (k N : ℕ) (hk : k≤N) :\n    (encodeKey k).bits.length≤keyWidth N := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ (encodeKey_compact k)\n  rw [encodeKey_value]\n  have hp := Nat.le_pow_clog (by decide : 1<(2:ℕ)) (N+1)\n  unfold keyWidth\n  omega\n\n/-- Conservative full key-encoding setup budget; no logarithmic encoder claim. -/\ndef encodeBudget (N : ℕ) : ℕ := 20*(N+1)^2+6*(N+1)+6\n\n/-- Both actual digit acquisition and the high-zero scan remain in setup work. -/\ntheorem encodeKey_clock (k N : ℕ) (hk : k≤N) :\n    (encodeKey k).clock≤encodeBudget N := by\n  have hc := SemiprimeSourceWordIdEnvironment.acquireKey_work k\n  have hl := SemiprimeSourceWordIdEnvironmentBounds.acquireKey_length k\n  have hm : 20*(k+1)^2≤20*(N+1)^2 := by gcongr\n  have ht := SemiprimeSourceCompactBits.trim_clock\n    (SemiprimeSourceWordIdEnvironment.acquireKey k).value\n  simp only [encodeKey,encodeBudget]\n  omega\n\n/-- Cached original native codes and their acquired compact physical key payloads. -/\nstructure PortRecord where\n  /-- Original left-variable code. -/\n  ownerCode : ℕ\n  /-- Original right-factor code. -/\n  factorCode : ℕ\n  /-- Actual compact owner key. -/\n  ownerKey : List Bool\n  /-- Actual compact factor key. -/\n  factorKey : List Bool\n\n/-- Acquire one original port record; owner/factor access is an explicit native stage. -/\ndef record {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) : Run PortRecord :=\n  let v := owner i\n  let a := encodeKey v.val\n  let b := encodeKey (n+i.1.val)\n  ⟨⟨v.val,n+i.1.val,a.bits,b.bits⟩,a.clock+b.clock+8⟩\n\n/-- Direct records equal the original mathematical index codes, without runtime scans. -/\ntheorem record_codes {n F Q : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) :\n    (record owner i).value.ownerCode=indexCode (acquire n F Q arity).indices (.inl (owner i)) ∧\n    (record owner i).value.factorCode=indexCode (acquire n F Q arity).indices (.inr i.1) := by\n  rw [indexCode_inl,indexCode_inr]\n  exact ⟨rfl,rfl⟩\n\n/-- Both physical key values are the original cached native codes. -/\ntheorem record_values {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) :\n    bitValue (record owner i).value.ownerKey=(record owner i).value.ownerCode ∧\n    bitValue (record owner i).value.factorKey=(record owner i).value.factorCode := by\n  exact ⟨encodeKey_value _,encodeKey_value _⟩\n\n/-- Original dimensions derive both compact record widths and canonicality. -/\ntheorem record_good {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) :\n    SemiprimeSourceCompactBits.Compact (record owner i).value.ownerKey ∧\n    SemiprimeSourceCompactBits.Compact (record owner i).value.factorKey ∧\n    (record owner i).value.ownerKey.length≤keyWidth (n+F) ∧\n    (record owner i).value.factorKey.length≤keyWidth (n+F) := by\n  have hv := (owner i).isLt\n  have he := i.1.isLt\n  exact ⟨encodeKey_compact _,encodeKey_compact _,\n    encodeKey_length _ _ (by omega),encodeKey_length _ _ (by omega)⟩\n\n/-- One conservative actual original-port acquisition budget. -/\ndef recordBudget (N : ℕ) : ℕ := 2*encodeBudget N+8\n\n/-- Record setup pays both complete encoder reports and native record construction. -/\ntheorem record_work {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) :\n    (record owner i).work≤recordBudget (n+F) := by\n  have hv := (owner i).isLt\n  have he := i.1.isLt\n  have ha := encodeKey_clock (owner i).val (n+F) (by omega)\n  have hb := encodeKey_clock (n+i.1.val) (n+F) (by omega)\n  simp only [record,recordBudget]\n  omega\n\n/-- Cache every original record once in original incidence-list order. -/\ndef acquirePorts {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    List ((e : Fin F)×Fin (arity e))→Run (List PortRecord)\n  | [] => ⟨[],1⟩\n  | i::is =>\n    let row := record owner i\n    let rest := acquirePorts owner is\n    ⟨row.value::rest.value,row.work+rest.work+3⟩\n\n/-- Exact original port occurrences/order, without deduplication or source rereads. -/\ntheorem acquirePorts_value {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (is : List ((e : Fin F)×Fin (arity e))) :\n    (acquirePorts owner is).value=is.map (fun i => (record owner i).value) := by\n  induction is with\n  | nil => rfl\n  | cons i is ih => simp only [acquirePorts,List.map_cons,ih]\n\n/-- Every actual record encoder and list constructor remains paid. -/\ntheorem acquirePorts_work {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (is : List ((e : Fin F)×Fin (arity e))) :\n    (acquirePorts owner is).work ≤ is.length*(recordBudget (n+F)+3)+1 := by\n  induction is with\n  | nil => simp [acquirePorts]\n  | cons i is ih =>\n    have h := record_work owner i\n    simp only [acquirePorts,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Original sparse metadata and its actual once-acquired port cache. -/\nstructure Acquired (n F Q : ℕ) (arity : Fin F→ℕ) where\n  /-- Actual metadata; no word functions or quadratic score fields. -/\n  metadata : Metadata n F Q arity\n  /-- Every compact original port record. -/\n  records : List PortRecord\n  /-- Metadata, encoding, normalization and constructor work. -/\n  clock : ℕ\n\n/-- Acquire metadata once and cache its original port records once. -/\ndef acquireOriginal (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) : Acquired n F Q arity :=\n  let data := acquire n F Q arity\n  let rows := acquirePorts owner data.incidences\n  ⟨data,rows.value,data.clock+rows.work+3⟩\n\n/-- Complete setup bound is conservative in original N, not falsely near-linear. -/\ndef budget (n F Q M : ℕ) : ℕ :=\n  SemiprimeSourceHistogramMetadata.budget n F Q M+M*(recordBudget (n+F)+3)+4\n\n/-- Actual acquired metadata supplies M internally; no record-count or width advice. -/\ntheorem acquireOriginal_clock (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquireOriginal n F Q arity owner).clock≤budget n F Q (∑ e,arity e) := by\n  have hm := acquire_clock n F Q arity\n  have hs := (sizes n F Q arity).2.2.1\n  have hp := acquirePorts_work owner (acquire n F Q arity).incidences\n  rw [hs] at hp\n  simp only [acquireOriginal,budget]\n  omega\n\n\n/-- The returned metadata is the actually acquired sparse original metadata. -/\ntheorem acquireOriginal_metadata (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquireOriginal n F Q arity owner).metadata=acquire n F Q arity := rfl\n\n/-- The actual cache contains every original port record in its original order. -/\ntheorem acquireOriginal_records (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquireOriginal n F Q arity owner).records=\n      (acquire n F Q arity).incidences.map (fun i => (record owner i).value) :=\n  acquirePorts_value owner _\n\n/-- The cached record count is the actual total original incidence count. -/\ntheorem acquireOriginal_length (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquireOriginal n F Q arity owner).records.length=∑ e,arity e := by\n  rw [acquireOriginal_records,List.length_map]\n  exact (sizes n F Q arity).2.2.1\n\n/-- Every actually acquired cached record has exact physical values and compact\noriginal-dimension width; there is no supplied record/width representation. -/\ntheorem acquireOriginal_good (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (row : PortRecord) (hr : row∈(acquireOriginal n F Q arity owner).records) :\n    bitValue row.ownerKey=row.ownerCode ∧ bitValue row.factorKey=row.factorCode ∧\n    SemiprimeSourceCompactBits.Compact row.ownerKey ∧\n    SemiprimeSourceCompactBits.Compact row.factorKey ∧\n    row.ownerKey.length≤keyWidth (n+F) ∧ row.factorKey.length≤keyWidth (n+F) := by\n  rw [acquireOriginal_records] at hr\n  rcases List.mem_map.mp hr with ⟨i,_,rfl⟩\n  exact ⟨(record_values owner i).1,(record_values owner i).2,record_good owner i⟩\n\n/-- Original source owner/factor codes are recovered from the actual cached records. -/\ntheorem acquireOriginal_codes (n F Q : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ((acquireOriginal n F Q arity owner).records.map (fun row => (row.ownerCode,row.factorCode)))=\n      (acquire n F Q arity).incidences.map (fun i =>\n        (indexCode (acquire n F Q arity).indices (.inl (owner i)),\n          indexCode (acquire n F Q arity).indices (.inr i.1))) := by\n  rw [acquireOriginal_records,List.map_map]\n  apply List.map_congr_left\n  intro i _\n  exact Prod.ext (record_codes (Q:=Q) owner i).1 (record_codes (Q:=Q) owner i).2\n\n\n/-- A fixed original-dimension polynomial pays the complete acquired port-key setup. -/\ntheorem budget_monomial : ∃ C k : ℕ,∀ n F Q M S,\n    n≤S → F≤S → Q≤S → M≤S → budget n F Q M≤C*(S+1)^k := by\n  have hp : Bound (fun S => budget S S S S) := by\n    simp only [budget,recordBudget,encodeBudget,SemiprimeSourceHistogramMetadata.budget]\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  refine ⟨C,k,?_⟩\n  intro n F Q M S hn hF hQ hM\n  apply le_trans _ (h S)\n  simp only [budget,recordBudget,encodeBudget,SemiprimeSourceHistogramMetadata.budget]\n  gcongr\n\nend RiemannGaussian.SemiprimeSourceHistogramPortKeys\n","RiemannGaussian.SemiprimeSourceHistogramQueryCorrectness":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramQuery\nimport RiemannGaussian.SemiprimeSourceHistogramHeadOriginal\nimport RiemannGaussian.SemiprimeSourceScoreCancellation\n\n/-! # Original score acquired by sparse physical histograms\nThe quadratic original compiler and finite count evaluator occur only in the\nspecification. The executed query acquires its keys and collision counts from\nthe original sparse input. Both lanes and every original integer weight agree.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeSourceHistogramQueryCorrectness\nopen scoped BigOperators\nopen SemiprimeBitArithmetic SemiprimeRationalBits\n\n/-- Proof-side original count specification, including every repeated term.\nThis definition is never called by the physical histogram query. -/\ndef originalCounts (n F r Q : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (fixed : List (List Bool)) (s : ℕ) : SemiprimeSourceScoreCountsObjective.Counts :=\n  let old := SemiprimeSourceWordIdMetadata.acquire n F Q arity\n  (SemiprimeSourceScoreCountsObjective.evaluateCounts (SemiprimeFiniteEnumerations.words r Q).values\n    (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst old.indices old.terms).value\n    (List.range' fixed.length s)\n    (SemiprimeSourceHistogramHeadOriginal.originalEnv r Q fixed)).value\n\n/-- All sixteen actually acquired incidence histograms recover the ORIGINAL\ninteger count lane for every original selected prefix. -/\ntheorem incidence_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramQuery.incidenceWith\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner)\n      (SemiprimeSourceHistogramPrefix.acquire fixed).trie fixed.length s).word.value=\n        ((originalCounts n F r Q arity owner fixed s).incidence:ℚ) := by\n  rw [SemiprimeSourceHistogramQuery.incidence_original n F r Q lam arity owner fixed s hf]\n  have h := (SemiprimeSourceHistogramAcquiredSums.acquired_original_lanes\n    n F r Q arity owner (NeZero.pos r) (List.range' fixed.length s)\n    (SemiprimeSourceHistogramHeadOriginal.originalEnv r Q fixed) (List.nodup_range')).1\n  simp only [SemiprimeSourceHistogramPortKeys.indexCode_inl,\n    SemiprimeSourceHistogramPortKeys.indexCode_inr,\n    SemiprimeSourceHistogramHeadOriginal.originalEnv,\n    SemiprimeSourceHistogramDictRefinement.labels_original] at h\n  exact h.symm\n\n/-- The actual head state and physical counters recover the positive original\nhead formula. The signed subtraction is justified even when the free count is zero. -/\ntheorem head_total (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramQuery.headWith\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner)\n      (SemiprimeSourceHistogramPrefix.acquire fixed).trie fixed.length s).word.value=\n        (SemiprimeSourceHistogramHeadAggregate.total n r Q (List.range' fixed.length s)\n          (SemiprimeSourceHistogramHeadOriginal.originalEnv r Q fixed):ℚ) := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  have hp := SemiprimeSourceHistogramScales.acquire_values r Q lam cache.data.records cache.data.metadata.vertices\n  have hA : bitValue cache.scales.fourth=(r^Q)^4 := hp.2.2.1\n  have hG : bitValue cache.scales.head=r^(4*Q-1) := hp.2.2.2.1\n  change (SemiprimeSourceHistogramQuery.headWith cache _ _ _).word.value=_\n  unfold SemiprimeSourceHistogramQuery.headWith\n  rw [SemiprimeSourceHistogramSetup.rows_actual,\n    SemiprimeSourceHistogramSetup.vertices_actual]\n  let data := SemiprimeSourceHistogramHeadBits.acquire\n    (SemiprimeSourceHistogramRowKeys.acquireCaches r Q)\n    (SemiprimeSourceHistogramPrefix.acquire fixed).trie fixed.length s\n    (SemiprimeSourceHistogramHeadBits.verticesWith (List.finRange n)).value\n  let C : RationalReport :=\n    ⟨(SemiprimeSourceHistogramArithmetic.fromState data.histogram).word,data.clock+3⟩\n  have hC : SemiprimeSourceHistogramArithmetic.DenOne C.word :=\n    SemiprimeSourceHistogramArithmetic.fromState_den data.histogram\n  have hCv : C.word.value=(bitValue data.histogram.bits:ℚ) :=\n    SemiprimeSourceHistogramArithmetic.fromState_value data.histogram\n  change (SemiprimeSourceHistogramArithmetic.head cache.scales\n    ⟨cache.coordinateCount,0⟩ ⟨data.head.fixed,0⟩ ⟨data.head.free,0⟩ C).word.value=_\n  rw [SemiprimeSourceHistogramArithmetic.head_value _ _ _ _ C hC]\n  rw [hCv]\n  change (bitValue cache.scales.fourth:ℚ)*\n      ((bitValue data.histogram.bits:ℚ)+(bitValue cache.coordinateCount:ℚ)*(bitValue data.head.free:ℚ))+\n      (bitValue cache.scales.head:ℚ)*(bitValue cache.coordinateCount:ℚ)*\n        (2*(bitValue data.head.fixed:ℚ)*(bitValue data.head.free:ℚ)+\n          (bitValue data.head.free:ℚ)^2-(bitValue data.head.free:ℚ))=_\n  dsimp only [data]\n  rw [hA,hG,SemiprimeSourceHistogramSetup.coordinate_value,\n    SemiprimeSourceHistogramHeadOriginal.collision_original n r Q fixed hf,\n    SemiprimeSourceHistogramHeadOriginal.fixed_original,\n    SemiprimeSourceHistogramHeadOriginal.free_original]\n  let f := (SemiprimeSourceHistogramHeadAggregate.freeVertices n (List.range' fixed.length s)).length\n  have hoff : (f:ℚ)*((f-1:ℕ):ℚ)=(f:ℚ)^2-(f:ℚ) := by\n    have h := congrArg (fun z : ℕ => (z:ℚ))\n      (SemiprimeSourceHistogramHeadAggregate.free_offdiag f)\n    simp only [Nat.cast_add,Nat.cast_mul,Nat.cast_pow] at h\n    linarith\n  unfold SemiprimeSourceHistogramHeadAggregate.total\n  simp only [Nat.cast_add,Nat.cast_mul,Nat.cast_ofNat]\n  rw [hoff]\n  dsimp only [f]\n  ring\n\n/-- The head query returns the ORIGINAL count, including zero dimensions. -/\ntheorem head_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramQuery.headWith\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner)\n      (SemiprimeSourceHistogramPrefix.acquire fixed).trie fixed.length s).word.value=\n        ((originalCounts n F r Q arity owner fixed s).head:ℚ) := by\n  rw [head_total n F r Q lam arity owner fixed s hf]\n  congr 1\n  exact (SemiprimeSourceHistogramHeadAggregate.original_head_lane n F r Q arity owner\n    (List.range' fixed.length s) (SemiprimeSourceHistogramHeadOriginal.originalEnv r Q fixed)\n    (List.nodup_range')).symm\n\n/-- The full executed query equals the original scheduled integer objective.\nNo positivity of n, M, either lane or either integer weight is required. -/\ntheorem score_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramQuery.score\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner) fixed s).word.value=\n      (SemiprimeSourceScoreCancellation.weight (∑ e,arity e) n lam (r^(2*Q))\n        (originalCounts n F r Q arity owner fixed s).incidence\n        (originalCounts n F r Q arity owner fixed s).head:ℚ) := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  have hp := SemiprimeSourceHistogramScales.acquire_values r Q lam cache.data.records cache.data.metadata.vertices\n  have hn : cache.data.metadata.vertices.length=n := by\n    rw [SemiprimeSourceHistogramSetup.metadata_actual]\n    exact (SemiprimeSourceHistogramMetadata.sizes n F Q arity).1\n  have hM : cache.data.records.length=∑ e,arity e :=\n    SemiprimeSourceHistogramPortKeys.acquireOriginal_length n F Q arity owner\n  have hI : bitValue cache.scales.weights.incidence=n^2*lam^2*(r^Q)^4 := by\n    have h : bitValue cache.scales.weights.incidence=\n        cache.data.metadata.vertices.length^2*lam^2*(r^Q)^4 := hp.2.2.2.2.1\n    simpa only [hn] using h\n  have hH : bitValue cache.scales.weights.head=4*(∑ e,arity e)^2 := by\n    have h : bitValue cache.scales.weights.head=4*cache.data.records.length^2 := hp.2.2.2.2.2\n    simpa only [hM] using h\n  change (SemiprimeSourceHistogramQuery.scoreWith cache dict fixed.length s).word.value=_\n  rw [SemiprimeSourceHistogramQuery.scoreWith,\n    SemiprimeSourceHistogramArithmetic.weighted_value _ _ _\n      (SemiprimeSourceHistogramQuery.incidence_den cache dict fixed.length s)\n      (SemiprimeSourceHistogramQuery.head_den cache dict fixed.length s),hI,hH,\n    incidence_original n F r Q lam arity owner fixed s hf,\n    head_original n F r Q lam arity owner fixed s hf]\n  simp only [SemiprimeSourceScoreCancellation.weight,\n    SemiprimeSourceScoreCancellation.bank_square,Nat.cast_add,Nat.cast_mul,Nat.cast_pow,Nat.cast_ofNat]\n\nend RiemannGaussian.SemiprimeSourceHistogramQueryCorrectness\n","RiemannGaussian.SemiprimeSourceIncidenceCountBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceIncidenceCountFormula\nimport RiemannGaussian.SemiprimeSourceCountPowers\nimport RiemannGaussian.SemiprimeSourceWordIdPredicateBounds\n\n/-! # Physical constant-size classification of original incidence completions\nEach fixed equality uses actual physical ID reads and comparison. A free\nequality contributes a proved degree loss, without enumerating any completion.\nNative descriptor equality/membership and report stages remain explicit.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceIncidenceCountBits\nopen SemiprimeMaterializedWords SemiprimeSourceOffsetInputsCore SemiprimeBitArithmetic\nopen SemiprimeSourceWordIdEnvironment\nopen SemiprimeSourceCountPowers (Powers)\nopen SemiprimeSourceIncidenceCountFormula\n\n/-- One actually evaluated equality constraint and its remaining free degree. -/\nstructure Edge where\n  /-- Whether fixed anchors permit this equality. -/\n  possible : Bool\n  /-- Whether a nonloop equality consumes one free word choice. -/\n  drop : Bool\n  /-- Actual key/ID reads, physical comparison and native membership reports. -/\n  clock : ℕ\n\n/-- Classify one original equality, inspecting anchors only when both ends are fixed. -/\ndef edge (env : Env) (a c : ℕ) (remaining : List ℕ) : Edge :=\n  if a=c then ⟨true,false,3⟩ else\n    let ma := memberRun a remaining\n    let mc := memberRun c remaining\n    if ma.value || mc.value then ⟨true,true,ma.work+mc.work+5⟩ else\n      let ka := acquireKey a\n      let kc := acquireKey c\n      let va := read env ka.value\n      let vc := read env kc.value\n      let same := equalID va.value vc.value\n      ⟨same.value,false,ma.work+mc.work+ka.work+kc.work+va.work+vc.work+same.work+9⟩\n\n/-- The actual physical equality is the original environment-word equality. -/\ntheorem read_equal_original (r Q : ℕ) [NeZero r] (env : Env)\n    (original : SemiprimeMaterializedScoreEnvironment.Environment r Q) (a c : ℕ)\n    (he : Rel (SemiprimeSourceWordBank.acquire r Q).ids\n      (SemiprimeSourceWordBankSemantics.decode r Q) env original) :\n    (equalID (read env (acquireKey a).value).value\n      (read env (acquireKey c).value).value).value=\n      decide (SemiprimeMaterializedScoreEnvironment.denote original a=\n        SemiprimeMaterializedScoreEnvironment.denote original c) := by\n  have ha := read_valid (SemiprimeSourceWordBank.acquire r Q).ids env (acquireKey a).value he.1\n  have hc := read_valid (SemiprimeSourceWordBank.acquire r Q).ids env (acquireKey c).value he.1\n  have h := SemiprimeSourceWordIdPredicate.equalID_decoded r Q _ _ ha hc\n  rw [SemiprimeSourceWordIdPredicate.decoded_read,SemiprimeSourceWordIdPredicate.decoded_read] at h\n  simpa only [SemiprimeMaterializedScoreEnvironment.denote,he.2] using h\n\n/-- Concrete ID operations produce exactly the proved edge predicates. -/\ntheorem edge_original (r Q : ℕ) [NeZero r] (env : Env)\n    (original : SemiprimeMaterializedScoreEnvironment.Environment r Q) (a c : ℕ)\n    (remaining : List ℕ)\n    (he : Rel (SemiprimeSourceWordBank.acquire r Q).ids\n      (SemiprimeSourceWordBankSemantics.decode r Q) env original) :\n    (edge env a c remaining).possible=\n        decide (pairOK remaining (SemiprimeMaterializedScoreEnvironment.denote original) a c) ∧\n      (edge env a c remaining).drop=decide (pairActive remaining a c) := by\n  have h := read_equal_original r Q env original a c he\n  by_cases hac : a=c\n  · simp [edge,hac,pairOK,pairActive]\n  · by_cases ha : a∈remaining <;> by_cases hc : c∈remaining <;>\n      simp [edge,hac,ha,hc,memberRun_value,pairOK,pairActive,h]\n\n/-- Two physical edge classifiers select an actually copied cached count word. -/\ndef count (env : Env) (powers : Powers) (a b c d : ℕ) (remaining : List ℕ) : NatRun :=\n  let first := edge env a c remaining\n  let second := edge env b d remaining\n  if first.possible && second.possible then\n    if first.drop && second.drop then\n      let out := SemiprimeSourceChoiceBits.copyID powers.square\n      ⟨out.value,first.clock+second.clock+out.work+7⟩\n    else if first.drop || second.drop then\n      let out := SemiprimeSourceChoiceBits.copyID powers.cube\n      ⟨out.value,first.clock+second.clock+out.work+9⟩\n    else\n      let out := SemiprimeSourceChoiceBits.copyID powers.fourth\n      ⟨out.value,first.clock+second.clock+out.work+9⟩\n  else ⟨[],first.clock+second.clock+5⟩\n\n/-- Every output branch contains only its actual cached physical payload. -/\ntheorem count_bits (env : Env) (powers : Powers) (a b c d : ℕ) (remaining : List ℕ) :\n    (count env powers a b c d remaining).bits=\n      if (edge env a c remaining).possible && (edge env b d remaining).possible then\n        if (edge env a c remaining).drop && (edge env b d remaining).drop then powers.square\n        else if (edge env a c remaining).drop || (edge env b d remaining).drop then powers.cube\n        else powers.fourth\n      else [] := by\n  unfold count\n  split_ifs <;> simp_all only [SemiprimeSourceChoiceBits.copyID_value,ite_true,ite_false,Bool.false_eq_true]\n\n/-- Output widths follow actual branch payloads, not a decoded count bound. -/\ntheorem count_length (env : Env) (powers : Powers) (a b c d : ℕ) (remaining : List ℕ) :\n    (count env powers a b c d remaining).bits.length ≤\n      max powers.square.length (max powers.cube.length powers.fourth.length) := by\n  rw [count_bits]\n  split_ifs\n  · exact le_max_left _ _\n  · exact (le_max_left _ _).trans (le_max_right _ _)\n  · exact (le_max_right _ _).trans (le_max_right _ _)\n  · simp\n\n/-- Original cache acquisition supplies every output width. -/\ntheorem acquired_length (r Q : ℕ) (env : Env) (a b c d : ℕ) (remaining : List ℕ) :\n    (count env (SemiprimeSourceCountPowers.acquire r Q) a b c d remaining).bits.length ≤\n      SemiprimeSourceCountPowers.width r Q := by\n  apply (count_length _ _ _ _ _ _ _).trans\n  have h := SemiprimeSourceCountPowers.acquire_length r Q\n  exact max_le h.1 (max_le h.2.1 h.2.2.1)\n\n/-- Exact original padded incidence count from physical classifiers and copies.\nOriginal descriptor compilation discharges every namespace inequality. -/\ntheorem count_original (r Q : ℕ) [NeZero r] (env : Env)\n    (original : SemiprimeMaterializedScoreEnvironment.Environment r Q) (a b c d : ℕ)\n    (remaining : List ℕ) (hn : remaining.Nodup)\n    (he : Rel (SemiprimeSourceWordBank.acquire r Q).ids\n      (SemiprimeSourceWordBankSemantics.decode r Q) env original)\n    (hab : a≠b) (had : a≠d) (hcb : c≠b) (hcd : c≠d) :\n    bitValue (count env (SemiprimeSourceCountPowers.acquire r Q) a b c d remaining).bits=\n      (SemiprimeSourceScoreCountsPadding.paddedLocal\n        (SemiprimeFiniteEnumerations.words r Q).values\n        (.incidence a b c d) remaining original).value := by\n  have hfirst := edge_original r Q env original a c remaining he\n  have hsecond := edge_original r Q env original b d remaining he\n  have hp := SemiprimeSourceCountPowers.acquire_value r Q\n  have hsquare : bitValue (SemiprimeSourceCountPowers.acquire r Q).square=(r^Q)^2 := by\n    rw [hp.1,←pow_mul]\n    congr 1\n    omega\n  have hcube : bitValue (SemiprimeSourceCountPowers.acquire r Q).cube=(r^Q)^3 := by\n    rw [hp.2.1,←pow_mul]\n    congr 1\n    omega\n  have hfourth : bitValue (SemiprimeSourceCountPowers.acquire r Q).fourth=(r^Q)^4 := by\n    rw [hp.2.2.1,←pow_mul]\n    congr 1\n    omega\n  have hv := paddedLocal_formula r Q (NeZero.pos r) a b c d remaining original hn hab had hcb hcd\n  simp only [SemiprimeSourceHeadCountFormula.alphabet] at hv\n  rw [count_bits,hfirst.1,hfirst.2,hsecond.1,hsecond.2,hv]\n  simp only [classifiedCount,Bool.and_eq_true,Bool.or_eq_true,decide_eq_true_eq]\n  split_ifs <;> simp only [hsquare,hcube,hfourth,bitValue]\n\nend RiemannGaussian.SemiprimeSourceIncidenceCountBits\n","RiemannGaussian.SemiprimeSourceMemoryBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRationalBits\nimport RiemannGaussian.SemiprimeBitProductSort\n\n/-! # Boolean-addressed sequential source memory\nAddresses are physical Boolean words. Every visited rational payload is copied,\nevery address test and decrement is executed, and all work is retained. Natural\nindices appear only in the correctness specification. This is an explicit memory\nprimitive for the source instruction simulation, not a whole-machine theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeSourceMemoryBits\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitPrimeScan\nopen SemiprimeBitIndexClipping SemiprimeBitIndexTraversal SemiprimeRationalBits\n\n/-- Actual full copy of both rational words and the sign flag. -/\ndef copyWord (x : RationalWord) : RationalReport :=\n  let n := fitBits x.numerator.magnitude x.numerator.magnitude\n  let d := fitBits x.denominator x.denominator\n  ⟨⟨⟨x.numerator.negative,n.bits⟩,d.bits⟩,bitCost n+bitCost d+4⟩\n\n/-- Physical copying retains every supplied bit, including high zero padding. -/\ntheorem copyWord_word (x : RationalWord) : (copyWord x).word=x := by\n  simp only [copyWord,SemiprimeBitProductSort.fitBits_self]\n\n/-- The full payload scan/copy cost follows from its actual word widths. -/\ntheorem copyWord_clock (x : RationalWord) (W : ℕ) (hx : Width x W) :\n    (copyWord x).clock≤8*W+6 := by\n  have hn := fitBits_cost x.numerator.magnitude x.numerator.magnitude\n  have hd := fitBits_cost x.denominator x.denominator\n  dsimp only [copyWord]\n  rcases hx with ⟨hxn,hxd⟩\n  omega\n\n/-- Sequential access with a physical address counter, copying every visited payload.\nOut-of-range access returns the fixed literal rational zero. -/\ndef readWord : List RationalWord → List Bool → RationalReport\n  | [],_ => ⟨SemiprimeRationalBits.zeroWord,4⟩\n  | x::xs,address =>\n    let visit := copyWord x\n    let test := nonzeroBits address\n    if test.nonzero then\n      let decrement := subBits address [true] false\n      let rest := readWord xs decrement.result.bits\n      ⟨rest.word,visit.clock+test.clock+bitCost decrement.result+rest.clock+6⟩\n    else ⟨visit.word,visit.clock+test.clock+4⟩\n\n/-- Exact finite memory lookup, with all indexing confined to the proof. -/\ntheorem readWord_word (xs : List RationalWord) (address : List Bool) :\n    (readWord xs address).word=(xs[bitValue address]?).getD SemiprimeRationalBits.zeroWord := by\n  induction xs generalizing address with\n  | nil => simp [readWord]\n  | cons x xs ih =>\n    by_cases h : (nonzeroBits address).nonzero=true\n    · have hp := (nonzeroBits_correct address).mp h\n      have hd := (decrementBits_value hp).2\n      have he : bitValue address=(bitValue address-1)+1 := by omega\n      simp only [readWord,h,ite_true,ih,hd]\n      conv_rhs => rw [he]\n      rw [List.getElem?_cons_succ]\n    · have hz := (nonzeroBits_false_iff address).mp (Bool.eq_false_of_not_eq_true h)\n      simp only [readWord,Bool.eq_false_of_not_eq_true h,Bool.false_eq_true,ite_false,copyWord_word,hz,List.getElem?_cons_zero,Option.getD_some]\n\n/-- Valid finite memory and its zero default give a valid result, at any address. -/\ntheorem readWord_valid (xs : List RationalWord) (address : List Bool)\n    (hx : ∀ x∈xs,x.Valid) : (readWord xs address).word.Valid := by\n  rw [readWord_word]\n  cases he : xs[bitValue address]? with\n  | none => change 0<(1:ℕ); omega\n  | some x => exact hx x (List.mem_of_getElem? he)\n\n/-- The selected payload has bounded physical width, including the literal default. -/\ntheorem readWord_width (xs : List RationalWord) (address : List Bool) (W : ℕ)\n    (hW : 1≤W) (hx : ∀ x∈xs,Width x W) : Width (readWord xs address).word W := by\n  rw [readWord_word]\n  cases he : xs[bitValue address]? with\n  | none => exact ⟨by simp [SemiprimeRationalBits.zeroWord],by simpa [SemiprimeRationalBits.zeroWord] using hW⟩\n  | some x => exact hx x (List.mem_of_getElem? he)\n\n/-- Both address and payload work are charged at every visited memory cell. -/\ntheorem readWord_clock (xs : List RationalWord) (address : List Bool) (W B : ℕ)\n    (hB : 1≤B) (ha : address.length≤B) (hx : ∀ x∈xs,Width x W) :\n    (readWord xs address).clock≤(xs.length+1)*(8*W+15*B+30) := by\n  induction xs generalizing address with\n  | nil => simp only [readWord,List.length_nil]; omega\n  | cons x xs ih =>\n    have hv := copyWord_clock x W (hx x List.mem_cons_self)\n    have ht := nonzeroBits_cost address\n    have hd := subBits_cost address [true] false\n    have hlen : (subBits address [true] false).result.bits.length≤B := by\n      rw [(subBits_counts address [true] false).2.2.2.2]\n      simp only [List.length_cons,List.length_nil]\n      exact max_le ha hB\n    have hc := ih (subBits address [true] false).result.bits hlen\n      (fun y hy => hx y (List.mem_cons_of_mem x hy))\n    have hmax : max address.length [true].length≤B := max_le ha (by simpa using hB)\n    simp only [readWord,List.length_cons]\n    split_ifs <;> dsimp only <;> nlinarith\n\n/-- Actual copies of all memory cells; used to charge persistence/relocation explicitly. -/\nstructure CopyReport where\n  /-- Copied payloads. -/\n  words : List RationalWord\n  /-- All bit copies and list constructor/branch operations. -/\n  clock : ℕ\n\n/-- A complete sequential memory copy, without a sharing requirement. -/\ndef copyMemory : List RationalWord → CopyReport\n  | [] => ⟨[],1⟩\n  | x::xs =>\n    let head := copyWord x\n    let tail := copyMemory xs\n    ⟨head.word::tail.words,head.clock+tail.clock+3⟩\n\n/-- The copied finite store is physically identical. -/\ntheorem copyMemory_words (xs : List RationalWord) : (copyMemory xs).words=xs := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [copyMemory,copyWord_word,ih]\n\n/-- Entire-store copying has a derived bound in actual cells and physical word width. -/\ntheorem copyMemory_clock (xs : List RationalWord) (W : ℕ) (hx : ∀ x∈xs,Width x W) :\n    (copyMemory xs).clock≤xs.length*(8*W+9)+1 := by\n  induction xs with\n  | nil => simp [copyMemory]\n  | cons x xs ih =>\n    have hh := copyWord_clock x W (hx x List.mem_cons_self)\n    have ht := ih (fun y hy => hx y (List.mem_cons_of_mem x hy))\n    simp only [copyMemory,List.length_cons]\n    nlinarith\n\nend RiemannGaussian.SemiprimeSourceMemoryBits\n","RiemannGaussian.SemiprimeSourceScoreChoice":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceChoiceOrder\n\n/-! # Physical score order with original finite source-label metadata\nAll score comparisons execute the Boolean comparator. Labels and finite loop\nindices retain the original source metadata representation; their complete\nencoding/allocation refinement is a separate whole-machine obligation. This\nentry point permits an acquired physical score producer to replace the original\nrational objective while preserving its exact deterministic labels.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeSourceScoreChoice\nopen SemiprimeRationalBits SemiprimeMaterializedWords\n\n/-- Compare acquired score words and retain the original selected label reference. -/\ndef choose {A : Type} (score : A → RationalReport) (a : A) : List A → Run A\n  | [] => ⟨a,1⟩\n  | b::bs =>\n    let next := choose score b bs\n    let left := score a\n    let right := score next.value\n    let order := SemiprimeSourceComparisonBits.compare left.word right.word\n    ⟨if order.order.le = true then a else next.value,\n      next.work+left.clock+right.clock+order.clock+3⟩\n\n/-- Order equivalence suffices to preserve the original chosen label and tie rule. -/\ntheorem choose_refines {A : Type} (physical : A → RationalReport) (source : A → Run ℚ)\n    (hv : ∀ a,(physical a).word.Valid)\n    (ho : ∀ a b,(physical a).word.value ≤ (physical b).word.value ↔\n      (source a).value ≤ (source b).value) (a : A) (tail : List A) :\n    (choose physical a tail).value=(SemiprimeMaterializedWords.choose source a tail).value := by\n  induction tail generalizing a with\n  | nil => rfl\n  | cons b bs ih =>\n    simp only [choose,SemiprimeMaterializedWords.choose]\n    rw [SemiprimeSourceComparisonBits.compare_branch _ _ (hv a) (hv _)]\n    simp only [ho,ih]\n\n/-- Every actual score callback and physical comparator remains in the report. -/\ntheorem choose_work {A : Type} (physical : A → RationalReport) (a : A) (tail : List A)\n    (F W : ℕ) (h : ∀ a,(physical a).clock ≤ F ∧ Width (physical a).word W) :\n    (choose physical a tail).work ≤ tail.length*(2*F+200*(W+1)^2+3)+1 := by\n  induction tail generalizing a with\n  | nil => simp [choose]\n  | cons b bs ih =>\n    have hn := ih b\n    have hl := h a\n    have hr := h (choose physical b bs).value\n    have hc := SemiprimeSourceComparisonBits.compare_clock _ _ W hl.2 hr.2\n    simp only [choose,List.length_cons]\n    nlinarith\n\n/-- Source-label assignment follows only actual Boolean comparison decisions. -/\ndef assign {A : Type} (a : A) (tail : List A)\n    (physical : ℕ → List A → RationalReport) : ℕ → List A → Run (List A)\n  | 0,fixed => ⟨fixed,1⟩\n  | n+1,fixed =>\n    let next := choose (fun w => physical n (w::fixed)) a tail\n    let rest := assign a tail physical n (next.value::fixed)\n    ⟨rest.value,next.work+rest.work+3⟩\n\n/-- Physical comparison order preserves every original finite assignment step. -/\ntheorem assign_refines {A : Type} (a : A) (tail : List A)\n    (physical : ℕ → List A → RationalReport) (source : ℕ → List A → Run ℚ)\n    (hv : ∀ n xs,(physical n xs).word.Valid)\n    (ho : ∀ n xs v w,(physical n (v::xs)).word.value ≤ (physical n (w::xs)).word.value ↔\n      (source n (v::xs)).value ≤ (source n (w::xs)).value)\n    (n : ℕ) (fixed : List A) :\n    (assign a tail physical n fixed).value=(SemiprimeMaterializedWords.assign a tail source n fixed).value := by\n  induction n generalizing fixed with\n  | zero => rfl\n  | succ n ih =>\n    have hc := choose_refines (fun w => physical n (w::fixed)) (fun w => source n (w::fixed))\n      (fun w => hv n (w::fixed)) (ho n fixed) a tail\n    simp only [assign,ih,hc,SemiprimeMaterializedWords.assign]\n\n/-- Original metadata-prefix lengths bound the whole physical-comparison traversal. -/\ntheorem assign_work {A : Type} (a : A) (tail : List A)\n    (physical : ℕ → List A → RationalReport) (F W N : ℕ)\n    (h : ∀ n xs,n+xs.length ≤ N → (physical n xs).clock ≤ F ∧ Width (physical n xs).word W)\n    (n : ℕ) (fixed : List A) (hlen : n+fixed.length ≤ N) :\n    (assign a tail physical n fixed).work ≤ n*(tail.length*(2*F+200*(W+1)^2+3)+4)+1 := by\n  induction n generalizing fixed with\n  | zero => simp [assign]\n  | succ n ih =>\n    have hc := choose_work (fun w => physical n (w::fixed)) a tail F W\n      (fun w => h n (w::fixed) (by simp only [List.length_cons] at hlen ⊢;omega))\n    have hr := ih ((choose (fun w => physical n (w::fixed)) a tail).value::fixed)\n      (by simp only [List.length_cons] at hlen ⊢;omega)\n    simp only [assign]\n    nlinarith\n\nend RiemannGaussian.SemiprimeSourceScoreChoice\n","RiemannGaussian.SemiprimeSourceScoreCountBitsCore":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceScoreWeightAcquisition\nimport RiemannGaussian.SemiprimeSourceScoreCountsPadding\n\n/-! # Physical branch-word additions for original finite source counts\nThe internal terminal parameter is discharged by the concrete physical original\npredicate in the caller module; no integer count answer drives this recursion.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceScoreCountBitsCore\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedWords SemiprimeMaterializedScoreEnvironment\nopen SemiprimeSourceOffsetInputsCore SemiprimeBitArithmetic\n\n/-- Right-recursive actual addition of the acquired unsigned branch words. -/\ndef sumBits {α : Type*} (f : α→NatRun) : List α→NatRun\n  | [] => ⟨[],1⟩\n  | a::as =>\n    let first := f a\n    let rest := sumBits f as\n    let out := addBits first.bits rest.bits false\n    ⟨out.bits,first.clock+rest.clock+bitCost out+3⟩\n\n/-- Branch words sum in the same original order, including repeated labels. -/\ntheorem sumBits_value {α : Type*} (f : α→NatRun) (xs : List α) :\n    bitValue (sumBits f xs).bits=(xs.map (fun a => bitValue (f a).bits)).sum := by\n  induction xs with\n  | nil => rfl\n  | cons a as ih => simp only [sumBits,addBits_correct,ih,bitNat,Bool.false_eq_true,\n      ite_false,Nat.add_zero,List.map_cons,List.sum_cons]\n\n/-- Actual count recursion: physical terminal then Boolean additions, never a Nat sum. -/\ndef count {r Q : ℕ} (alphabet : List (Word r Q))\n    (terminal : Environment r Q→Run Bool) : List ℕ→Environment r Q→NatRun\n  | [],env => let out := terminal env\n              ⟨if out.value then [true] else [],out.work+2⟩\n  | i::remaining,env =>\n    let out := sumBits (fun w =>\n      let child := count alphabet terminal remaining (extend env i w)\n      ⟨child.bits,child.clock+Q+2⟩) alphabet\n    ⟨out.bits,out.clock+alphabet.length+3⟩\n\n/-- The internal terminal refinement identifies every actual branch with the\noriginal finite integer count. The concrete caller discharges this premise. -/\ntheorem count_value {r Q : ℕ} (alphabet : List (Word r Q)) (p : ScoreProgram Q)\n    (terminal : Environment r Q→Run Bool)\n    (ht : ∀ env,(terminal env).value=(SemiprimeSourceScoreCounts.hit p env).value)\n    (remaining : List ℕ) (env : Environment r Q) :\n    bitValue (count alphabet terminal remaining env).bits=\n      (SemiprimeSourceScoreCounts.count alphabet p remaining env).value := by\n  induction remaining generalizing env with\n  | nil =>\n    simp only [count,SemiprimeSourceScoreCounts.count,ht]\n    split <;> simp [bitValue,bitNat]\n  | cons i remaining ih =>\n    simp only [count,sumBits_value,SemiprimeSourceScoreCounts.count,\n      SemiprimeSourceScoreCounts.sumCount_value]\n    congr 1\n    apply List.map_congr_left\n    intro w _\n    exact ih (extend env i w)\n\n/-- All recursive branch-addition outputs have an explicit physical width. -/\ntheorem sumBits_length {α : Type*} (f : α→NatRun) (xs : List α) (K : ℕ)\n    (h : ∀ a∈xs,(f a).bits.length ≤ K) :\n    (sumBits f xs).bits.length ≤ K+xs.length := by\n  induction xs with\n  | nil => simp [sumBits]\n  | cons a as ih =>\n    have ha := h a List.mem_cons_self\n    have ht := ih (fun a ha => h a (List.mem_cons_of_mem _ ha))\n    have hw := (addBits_counts (f a).bits (sumBits f as).bits false).2.2.2.2\n    simp only [sumBits,List.length_cons]\n    omega\n\n/-- Actual right-recursive adders and child reports have a closed finite-loop bound. -/\ntheorem sumBits_clock {α : Type*} (f : α→NatRun) (xs : List α) (K B : ℕ)\n    (hl : ∀ a∈xs,(f a).bits.length ≤ K) (hc : ∀ a∈xs,(f a).clock ≤ B) :\n    (sumBits f xs).clock ≤ xs.length*(B+11*(K+xs.length)+7)+1 := by\n  induction xs with\n  | nil => simp [sumBits]\n  | cons a as ih =>\n    have ha := hc a List.mem_cons_self\n    have ht := ih (fun a ha => hl a (List.mem_cons_of_mem _ ha))\n      (fun a ha => hc a (List.mem_cons_of_mem _ ha))\n    have hw := sumBits_length f as K (fun a ha => hl a (List.mem_cons_of_mem _ ha))\n    have hla := hl a List.mem_cons_self\n    have had := addBits_cost (f a).bits (sumBits f as).bits false\n    have hm : max (f a).bits.length (sumBits f as).bits.length ≤ K+as.length := by\n      apply max_le <;> omega\n    simp only [sumBits,List.length_cons]\n    nlinarith\n\n/-- Count word width, covering every branch frame without any desired-count bound. -/\ntheorem count_length {r Q : ℕ} (alphabet : List (Word r Q))\n    (terminal : Environment r Q→Run Bool) (remaining : List ℕ) (env : Environment r Q) :\n    (count alphabet terminal remaining env).bits.length ≤ 1+remaining.length*alphabet.length := by\n  induction remaining generalizing env with\n  | nil => simp only [count,List.length_nil,Nat.zero_mul,Nat.add_zero];split <;> simp\n  | cons i remaining ih =>\n    have h := sumBits_length (fun w =>\n      let child := count alphabet terminal remaining (extend env i w)\n      (⟨child.bits,child.clock+Q+2⟩:NatRun)) alphabet (1+remaining.length*alphabet.length)\n      (fun w _ => ih (extend env i w))\n    simpa only [count,List.length_cons,Nat.add_mul,Nat.one_mul,Nat.add_assoc] using h\n\n/-- Original active list and actual acquired padding word followed by a product. -/\ndef padded {r Q : ℕ} (alphabet : List (Word r Q)) (p : ScoreProgram Q)\n    (terminal : Environment r Q→Run Bool) (remaining : List ℕ) (env : Environment r Q) : NatRun :=\n  let active := activeRun (support p) remaining\n  let raw := count alphabet terminal active.value env\n  let pad := unaryPower alphabet.length (4-active.value.length)\n  let encoded := natBits pad.cells.length\n  let out := mulBits raw.bits encoded.bits\n  ⟨out.bits,active.work+raw.clock+pad.clock+pad.cells.length+encoded.clock+bitCost out+8⟩\n\n/-- Padding uses a physically acquired multiplier, not a power/count-answer word. -/\ntheorem padded_value {r Q : ℕ} (alphabet : List (Word r Q)) (p : ScoreProgram Q)\n    (terminal : Environment r Q→Run Bool)\n    (ht : ∀ env,(terminal env).value=(SemiprimeSourceScoreCounts.hit p env).value)\n    (remaining : List ℕ) (env : Environment r Q) :\n    bitValue (padded alphabet p terminal remaining env).bits=\n      (SemiprimeSourceScoreCountsPadding.paddedLocal alphabet p remaining env).value := by\n  simp only [padded,mulBits_correct,natBits_value,unaryPower_length,count_value alphabet p terminal ht,\n    SemiprimeSourceScoreCountsPadding.paddedLocal,\n    (SemiprimeSourceScoreCountsPadding.power_spec _ _).1]\n/-- Width of every actual normalized local word, derived from active support and\noriginal alphabet size rather than the desired count value. -/\ntheorem padded_length {r Q : ℕ} (alphabet : List (Word r Q)) (p : ScoreProgram Q)\n    (terminal : Environment r Q→Run Bool) (remaining : List ℕ) (env : Environment r Q)\n    (hL : 0<alphabet.length) (hr : remaining.Nodup) :\n    (padded alphabet p terminal remaining env).bits.length ≤\n      3+8*alphabet.length+alphabet.length^4 := by\n  have ha := SemiprimeSourceScoreCountsPadding.active_length p remaining hr\n  have hc := count_length alphabet terminal (activeRun (support p) remaining).value env\n  have he := natBits_length (unaryPower alphabet.length\n    (4-(activeRun (support p) remaining).value.length)).cells.length\n  rw [unaryPower_length] at he\n  have hp : alphabet.length^(4-(activeRun (support p) remaining).value.length) ≤\n      alphabet.length^4 := Nat.pow_le_pow_right hL (by omega)\n  have hm := mulBits_length\n    (count alphabet terminal (activeRun (support p) remaining).value env).bits\n    (natBits (unaryPower alphabet.length (4-(activeRun (support p) remaining).value.length)).cells.length).bits\n  simp only [unaryPower_length] at hm\n  have hc' : (count alphabet terminal (activeRun (support p) remaining).value env).bits.length ≤\n      1+4*alphabet.length := hc.trans (by gcongr)\n  simp only [padded,unaryPower_length]\n  omega\n\nend RiemannGaussian.SemiprimeSourceScoreCountBitsCore\n","RiemannGaussian.SemiprimeSourceScorePhysicalBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceScorePhysicalCaller\nimport RiemannGaussian.SemiprimeSourceScoreCountBitsBounds\nimport RiemannGaussian.SemiprimeSourceSearchState\n\n/-! # Original-resource budget of physical integer-count label selection\nEvery terminal/count/weight/comparison report is retained. Original descriptor\nand label metadata still have native scalar interfaces; this is not a completed\nprimitive-machine cost theorem for the whole public factorizer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimeSourceScorePhysicalBudget\nopen SemiprimeRationalBits SemiprimeSourceScoreCountBitsBounds\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedScoreEnvironment SemiprimeReportPolynomialGrowth\n\n/-- Actual acquired original weight width, not a semantic magnitude oracle. -/\ndef weightCap (M n lam U : ℕ) : ℕ :=\n  SemiprimeSourceScoreWeightBits.weightWidth (SemiprimeSourceScoreWeightAcquisition.inputWidth M n lam U)\n/-- Uniform physical score-word cap derived from original list and cached-weight sizes. -/\ndef wordCap (L T M n lam U : ℕ) : ℕ := 3*scoreOperandWidth L T (weightCap M n lam U)+1\n/-- Actual weight acquisition and every candidate score/comparison/control step. -/\ndef runBudget (M n r Q lam U L T N : ℕ) : ℕ :=\n  SemiprimeSourceScoreWeightAcquisition.acquisitionBudget M n r Q lam U+\n    (N*((L-1)*(2*scoreBudget r Q N L T (weightCap M n lam U)+\n      200*(wordCap L T M n lam U+1)^2+3)+4)+1)+2\n\n/-- Exact runtime-derived physical producer bound on all reachable source prefixes. -/\ntheorem run_work {r Q : ℕ} (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (N : ℕ) (hr : 0 < r)\n    (hp : ∀ p∈programs,∀ i∈support p,i ≤ N) :\n    (SemiprimeSourceScorePhysicalSearch.run M n lam a tail programs N).work ≤\n      runBudget M n r Q lam (r^(2*Q)) (a::tail).length programs.length N := by\n  let weights := SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam\n  have hw := SemiprimeSourceScoreWeightAcquisition.acquire_length M n r Q lam\n  have hcallback (s : ℕ) (fixed : List (Word r Q)) (hlen : s+fixed.length ≤ N) :\n      (SemiprimeSourceScoreCountBits.score weights a tail programs s fixed).clock ≤\n          scoreBudget r Q N (a::tail).length programs.length (weightCap M n lam (r^(2*Q))) ∧\n        Width (SemiprimeSourceScoreCountBits.score weights a tail programs s fixed).word\n          (wordCap (a::tail).length programs.length M n lam (r^(2*Q))) := by\n    exact ⟨score_clock weights a tail programs s fixed N _ (by omega) hp hw.1 hw.2,\n      score_width weights a tail programs s fixed _ hw.1 hw.2⟩\n  have hs := SemiprimeSourceScoreChoice.assign_work a tail\n    (SemiprimeSourceScoreCountBits.score weights a tail programs)\n    (scoreBudget r Q N (a::tail).length programs.length (weightCap M n lam (r^(2*Q))))\n    (wordCap (a::tail).length programs.length M n lam (r^(2*Q))) N hcallback N [] (by simp)\n  have ha := SemiprimeSourceScoreWeightAcquisition.acquire_clock M n r Q lam hr\n  exact Nat.add_le_add_right (Nat.add_le_add ha hs) 2\n\n/-- Actual descriptor generation plus the full acquired physical search. -/\ndef computedBudget (M n r Q lam U L T N : ℕ) : ℕ :=\n  T*(8*N+15)+1+runBudget M n r Q lam U L T N+1\n\n/-- The original finite enumeration supplies every descriptor ID bound internally. -/\ntheorem computed_work {I E : Type} [DecidableEq E] {n r Q : ℕ} [NeZero r]\n    (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (lam : ℕ) :\n    (SemiprimeSourceScorePhysicalCaller.computed owner factor en lam).work ≤\n      computedBudget en.incidences.values.length n r Q lam en.types.values.length\n        (en.wordFirst::en.wordTail).length en.terms.values.length en.indices.values.length := by\n  have hp : ∀ p∈(SemiprimeMaterializedSourceWords.compileAll owner factor en.indices.values en.terms.values).value,\n      ∀ i∈support p,i ≤ en.indices.values.length := by\n    intro p hpm i hi\n    exact (SemiprimeSourceSearchState.compileAll_support_lt owner factor en.indices en.terms.values p hpm i hi).le\n  have hs := run_work en.incidences.values.length n lam en.wordFirst en.wordTail\n    (SemiprimeMaterializedSourceWords.compileAll owner factor en.indices.values en.terms.values).value\n    en.indices.values.length (NeZero.pos r) hp\n  rw [SemiprimeSourceSearchState.compileAll_length] at hs\n  have hc := SemiprimeMaterializedSourceWords.compileAll_work owner factor en.indices.values en.terms.values\n  rw [SemiprimeSourceOffsetHeight.caller_universal_length]\n  exact Nat.add_le_add_right (Nat.add_le_add hc hs) 1\n\nend RiemannGaussian.SemiprimeSourceScorePhysicalBudget\n","RiemannGaussian.SemiprimeSourceScorePhysicalResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceScorePhysicalBudget\n\n/-! # Uniform original-family polynomial for physical integer-count selection\nAll dimensions and the actual original alphabet/universal bank are substituted.\nThe theorem bounds the actual retained circuit and native-metadata ledger;\ncomplete original-input primitive-machine refinement remains separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeSourceScorePhysicalResources\nopen SemiprimeSourceScorePhysicalBudget SemiprimeSourceScoreCountBitsBounds\nopen SemiprimeReportPolynomialGrowth\n\n/-- Coarse fixed-polynomial original-resource envelope, including all cached setup. -/\ndef envelope (S : ℕ) : ℕ :=\n  S*(8*S+15)+1+SemiprimeSourceScoreWeightAcquisition.acquisitionBudget S S S S S S+\n    (S*(S*(2*scoreBudget S S S S S (weightCap S S S S)+\n      200*(wordCap S S S S S S+1)^2+3)+4)+1)+3\n\n/-- The complete displayed original-source search budget is monotone into\nthe single resource parameter; no execution field is used as an assumed cap. -/\ntheorem computedBudget_le (M n r Q lam U L T N S : ℕ)\n    (hM : M ≤ S) (hn : n ≤ S) (hr : r ≤ S) (hQ : Q ≤ S) (hlam : lam ≤ S)\n    (hU : U ≤ S) (hL : L ≤ S) (hT : T ≤ S) (hN : N ≤ S) :\n    computedBudget M n r Q lam U L T N ≤ envelope S := by\n  have hK : weightCap M n lam U ≤ weightCap S S S S := by\n    unfold weightCap SemiprimeSourceScoreWeightBits.weightWidth SemiprimeSourceScoreWeightAcquisition.inputWidth\n    gcongr\n  have hF := scoreBudget_mono hr hQ hN hL hT hK\n  have hW : wordCap L T M n lam U ≤ wordCap S S S S S S := by\n    unfold wordCap scoreOperandWidth localWidth\n    gcongr\n  have hA := SemiprimeSourceScoreWeightAcquisition.acquisitionBudget_mono hM hn hr hQ hlam hU\n  have hLm : L-1 ≤ S := (Nat.sub_le L 1).trans hL\n  have hD := Nat.mul_le_mul hT (Nat.add_le_add_right (Nat.mul_le_mul_left 8 hN) 15)\n  unfold computedBudget runBudget envelope\n  have hcontrol := Nat.mul_le_mul hN\n    (Nat.add_le_add_right\n      (Nat.mul_le_mul hLm (Nat.add_le_add_right\n        (Nat.add_le_add (Nat.mul_le_mul_left 2 hF)\n          (Nat.mul_le_mul_left 200 (Nat.pow_le_pow_left (Nat.add_le_add_right hW 1) 2))) 3)) 4)\n  omega\n\n/-- ACTUAL original caller costs are uniformly polynomial in original finite resources. -/\ntheorem caller_work {I E : Type} [DecidableEq E] {n r Q : ℕ} [NeZero r]\n    (owner : I → Fin n) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (lam S : ℕ)\n    (hM : en.incidences.values.length ≤ S) (hn : n ≤ S) (hr : r ≤ S)\n    (hQ : Q ≤ S) (hlam : lam ≤ S) (hU : en.types.values.length ≤ S)\n    (hL : (en.wordFirst::en.wordTail).length ≤ S)\n    (hT : en.terms.values.length ≤ S) (hN : en.indices.values.length ≤ S) :\n    (SemiprimeSourceScorePhysicalCaller.computed owner factor en lam).work ≤ envelope S :=\n  (computed_work owner factor en lam).trans\n    (computedBudget_le _ _ _ _ _ _ _ _ _ S hM hn hr hQ hlam hU hL hT hN)\n\n/-- A fixed coefficient and exponent bound every original-family retained report. -/\ntheorem envelope_monomial : ∃ C k : ℕ,∀ S,envelope S ≤ C*(S+1)^k := by\n  change Bound (fun S => envelope S)\n  simp only [envelope,SemiprimeSourceScoreWeightAcquisition.acquisitionBudget,\n    weightCap,wordCap,scoreOperandWidth,scoreBudget,sequentialBudget,evaluateBudget,\n    localBudget,paddingBudget,localWidth,SemiprimeSourceScoreCountBitsBudget.countBudget,\n    SemiprimeSourceScorePredicateBitsBounds.terminalBudget,\n    SemiprimeSourceScorePredicateBitsBounds.acquisitionBudget,\n    SemiprimeSourceScorePredicateBitsBounds.terminalStepBudget,\n    SemiprimeSourceScorePredicateBitsBounds.workingWidth,\n    SemiprimeSourceScorePredicateBitsBounds.wordBudget,\n    SemiprimeSourceScorePredicateBitsBounds.idBudget,\n    SemiprimeSourceScorePredicateBitsBounds.readBudget,\n    SemiprimeSourceScorePredicateBitsBounds.rowEqualityBudget,\n    SemiprimeSourceScorePredicateBitsBounds.coordinateBudget,\n    SemiprimeSourceScorePredicateBitsBounds.equalityBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,\n    SemiprimeSourceScorePredicateBitsBounds.scanStep,\n    SemiprimeSourceScoreWeightBits.weightWidth,\n    SemiprimeSourceScoreWeightBits.weightBudget,\n    SemiprimeSourceScoreWeightBits.combineBudget,\n    SemiprimeSourceScoreWeightAcquisition.inputWidth]\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceScorePhysicalResources\n","RiemannGaussian.SemiprimeSourceWordIdResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceWordIdSearchBudget\n\n/-! # Uniform original-resource bound for the actual acquired-ID source caller\nOnly original dimension caps occur in the final executed-report theorem. All\nconstants in the diagonal monomial precede the entire family of original inputs.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeSourceWordIdResources\nopen scoped BigOperators\nopen SemiprimeReportPolynomialGrowth\n\n/-- Actual complete original-caller budget is monotone in its ten independent resources. -/\ntheorem indexedBudget_mono {n F r Q lam M L U T N n' F' r' Q' lam' M' L' U' T' N' : ℕ}\n    (hn : n≤n') (hF : F≤F') (hr : r≤r') (hQ : Q≤Q') (hlam : lam≤lam')\n    (hM : M≤M') (hL : L≤L') (hU : U≤U') (hT : T≤T') (hN : N≤N') :\n    SemiprimeSourceWordIdSearchBudget.indexedBudget n F r Q lam M L U T N ≤\n      SemiprimeSourceWordIdSearchBudget.indexedBudget n' F' r' Q' lam' M' L' U' T' N' := by\n  simp only [SemiprimeSourceWordIdSearchBudget.indexedBudget,\n    SemiprimeSourceWordIdSearchBudget.runBudget,SemiprimeSourceWordIdSearchBudget.controlBudget,\n    SemiprimeSourceWordIdSearchBudget.wordCap,SemiprimeSourceWordIdSearchBudget.weightCap,\n    SemiprimeSourceWordIdMetadata.budget,SemiprimePaidFiniteEnumerations.incidenceBudget,\n    SemiprimePaidFiniteEnumerations.scoreBudget,SemiprimeSourceWordBankAcquisitionBudget.budget,\n    SemiprimeSourceWordBankAcquisitionBudget.colourBudget,SemiprimeSourceWordBankAcquisitionBudget.rowStage,\n    SemiprimeSourceScoreWeightAcquisition.acquisitionBudget,SemiprimeSourceScoreWeightAcquisition.inputWidth,\n    SemiprimeSourceScoreWeightBits.weightWidth,SemiprimeSourceScoreWeightBits.weightBudget,\n    SemiprimeSourceScoreWeightBits.combineBudget,SemiprimeSourceWordIdCountsBounds.operandWidth,\n    SemiprimeSourceWordIdCountsBounds.laneWidth,SemiprimeSourceWordIdCountsClock.scoreBudget,\n    SemiprimeSourceWordIdCountsClock.sequentialBudget,SemiprimeSourceWordIdCountsClock.evaluateBudget,\n    SemiprimeSourceWordIdCountsClock.localBudget,SemiprimeSourceWordIdCountsClock.paddingBudget,\n    SemiprimeSourceWordIdCountsClock.pushBudget,SemiprimeSourceWordIdCountsBudget.budget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n  gcongr\n\n/-- Diagonal bound of the ACTUAL displayed original-input caller budget. -/\ndef envelope (S : ℕ) : ℕ :=\n  SemiprimeSourceWordIdSearchBudget.indexedBudget S S S S S S S S S S\n\n/-- Controller majorant replaces only the sole truncated tail length by its full length. -/\ndef controllerMajorant (S : ℕ) : ℕ :=\n  2*S+3+S*(S*(2*SemiprimeSourceWordIdCountsClock.scoreBudget S S S S S\n    (SemiprimeSourceWordIdSearchBudget.weightCap S S S S)+\n    200*(SemiprimeSourceWordIdSearchBudget.wordCap S S S S S S+1)^2+4*(2*S)+5)+\n    4*(2*S)+2+S*(4*(2*S)+4)+4)+S*(4*(2*S)+4)+1\n\n/-- Subtraction-free diagonal with exactly the same acquired bank/weight/callback costs. -/\ndef diagonalMajorant (S : ℕ) : ℕ :=\n  SemiprimeSourceWordIdMetadata.budget S S S S+S*(8*S+15)+1+\n    (SemiprimeSourceWordBankAcquisitionBudget.budget S S S+\n      SemiprimeSourceScoreWeightAcquisition.acquisitionBudget S S S S S S+\n      controllerMajorant S+S+5)+3\n\n/-- Replacing S-1 by S never discards any actual work. -/\ntheorem envelope_le_majorant (S : ℕ) : envelope S≤diagonalMajorant S := by\n  unfold envelope diagonalMajorant controllerMajorant\n    SemiprimeSourceWordIdSearchBudget.indexedBudget SemiprimeSourceWordIdSearchBudget.runBudget\n    SemiprimeSourceWordIdSearchBudget.controlBudget\n  gcongr\n  omega\n\n/-- A fixed monomial bounds the full actual-family resource envelope. -/\ntheorem envelope_monomial : ∃ C k : ℕ,∀ S,envelope S≤C*(S+1)^k := by\n  have hp : Bound diagonalMajorant := by\n    change Bound (fun S => diagonalMajorant S)\n    simp only [diagonalMajorant,controllerMajorant,SemiprimeSourceWordIdSearchBudget.wordCap,SemiprimeSourceWordIdSearchBudget.weightCap,\n    SemiprimeSourceWordIdMetadata.budget,SemiprimePaidFiniteEnumerations.incidenceBudget,\n    SemiprimePaidFiniteEnumerations.scoreBudget,SemiprimeSourceWordBankAcquisitionBudget.budget,\n    SemiprimeSourceWordBankAcquisitionBudget.colourBudget,SemiprimeSourceWordBankAcquisitionBudget.rowStage,\n    SemiprimeSourceScoreWeightAcquisition.acquisitionBudget,SemiprimeSourceScoreWeightAcquisition.inputWidth,\n    SemiprimeSourceScoreWeightBits.weightWidth,SemiprimeSourceScoreWeightBits.weightBudget,\n    SemiprimeSourceScoreWeightBits.combineBudget,SemiprimeSourceWordIdCountsBounds.operandWidth,\n    SemiprimeSourceWordIdCountsBounds.laneWidth,SemiprimeSourceWordIdCountsClock.scoreBudget,\n    SemiprimeSourceWordIdCountsClock.sequentialBudget,SemiprimeSourceWordIdCountsClock.evaluateBudget,\n    SemiprimeSourceWordIdCountsClock.localBudget,SemiprimeSourceWordIdCountsClock.paddingBudget,\n    SemiprimeSourceWordIdCountsClock.pushBudget,SemiprimeSourceWordIdCountsBudget.budget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  exact ⟨C,k,fun S => (envelope_le_majorant S).trans (h S)⟩\n\n/-- The actual original indexed caller is uniformly bounded using only original\nnetwork/alphabet/descriptor dimensions, without a report/word/output oracle. -/\ntheorem indexed_report_actual (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (S : ℕ)\n    (hn : n≤S) (hF : F≤S) (hr : r≤S) (hQ : Q≤S) (hlam : lam≤S)\n    (hM : (∑ e,arity e)≤S) (hL : r^Q≤S) (hU : r^(2*Q)≤S)\n    (hT : (∑ e,arity e)^2+Q*n^2≤S) (hN : n+F≤S) :\n    (SemiprimeSourceWordIdCaller.indexed n F r Q lam arity owner).work≤envelope S := by\n  exact (SemiprimeSourceWordIdSearchBudget.indexed_work n F r Q lam arity owner).trans\n    (indexedBudget_mono hn hF hr hQ hlam hM hL hU hT hN)\n\nend RiemannGaussian.SemiprimeSourceWordIdResources\n","RiemannGaussian.SemiprimeSupportRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCounterEnumeration\nimport RiemannGaussian.SemiprimeCounterRate\nimport Mathlib.Analysis.SpecialFunctions.Log.NegMulLog\n\n/-!\n# Subexponential cost of the literal support traversal\n\nThe count is the actual inclusive weighted binomial menu, not an estimated\nconstant in an exponent. A vanishing support fraction suffices for every\npositive target exponent. This theorem does not supply an algorithm clock.\n-/\nset_option autoImplicit false\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeSupportRate\nopen Filter\nopen scoped Topology\nopen SemiprimeCounterEnumeration SemiprimeCounterRate\n\n/-- Continuous entropy majorant, including the zero-support case. -/\ndef entropy (a : ℝ) : ℝ := a*Real.log 8-a*Real.log a\n\ntheorem entropy_zero : entropy 0=0 := by simp [entropy]\n\n/-- The apparent logarithmic singularity disappears after multiplication by a. -/\ntheorem continuous_entropy : Continuous entropy :=\n  (continuous_id.mul continuous_const).sub Real.continuous_mul_log\n\n/-- Finite bound on the ACTUAL support callback count. No numerical aggregate\nconstant from a separate schedule calculation is assumed. -/\ntheorem weightedCount_bound (n q : ℕ) (hn : 0<n) (hq : q≤n) :\n    (weightedCount n q : ℝ)≤((n : ℝ)+1)*Real.exp ((n : ℝ)*entropy ((q : ℝ)/n)) := by\n  by_cases hq0 : q=0\n  · subst q\n    simp only [weightedCount_zero,Nat.cast_one,Nat.cast_zero,zero_div,entropy_zero,mul_zero,Real.exp_zero,mul_one]\n    have hnonneg : (0 : ℝ)≤n := Nat.cast_nonneg n\n    linarith\n  · have hnR : (0 : ℝ)<n := Nat.cast_pos.mpr hn\n    have hqR : (0 : ℝ)<q := Nat.cast_pos.mpr (by omega)\n    have hqn : (q : ℝ)≤n := Nat.cast_le.mpr hq\n    have hb := weightedCount_le_entropy n q hqR hqn (le_refl (q : ℝ))\n    have he : (8*(n : ℝ)/(q : ℝ))^(q : ℝ)=Real.exp ((n : ℝ)*entropy ((q : ℝ)/n)) := by\n      rw [Real.rpow_def_of_pos (by positivity)]\n      congr 1\n      have heq : 8*(n : ℝ)/(q : ℝ)=8/((q : ℝ)/n) := by field_simp\n      rw [heq,Real.log_div (by norm_num : (8 : ℝ)≠0) (ne_of_gt (div_pos hqR hnR))]\n      unfold entropy\n      field_simp\n    rw [he] at hb\n    exact hb.trans (mul_le_mul_of_nonneg_right (by linarith) (Real.exp_nonneg _))\n\n/-- A vanishing support fraction gives subexponential traversal for every\npositive target exponent, including arbitrary occurrences of q=0. -/\ntheorem weightedCount_subexponential (q : ℕ → ℕ)\n    (hq : Tendsto (fun n : ℕ => (q n : ℝ)/(n : ℝ)) atTop (𝓝 0))\n    (ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop, (weightedCount n (q n) : ℝ)≤Real.exp (ε*(n : ℝ)) := by\n  have he : Tendsto (fun n : ℕ => entropy ((q n : ℝ)/(n : ℝ))) atTop (𝓝 0) := by\n    simpa only [entropy_zero,Function.comp_def] using continuous_entropy.continuousAt.tendsto.comp hq\n  have hnat : Tendsto (fun n : ℕ => (n : ℝ)) atTop atTop := tendsto_natCast_atTop_atTop\n  have hp := hnat.eventually\n    (eventually_constant_polynomial_exp_rho_le 2 1 0 (ε/2) (by positivity))\n  filter_upwards [eventually_ge_atTop (1 : ℕ),\n    hq.eventually (gt_mem_nhds (show (0 : ℝ)<1 by norm_num)),\n    he.eventually (gt_mem_nhds (show (0 : ℝ)<ε/2 by positivity)),hp]\n    with n hn hqn hen hpoly\n  have hnR : (0 : ℝ)<n := Nat.cast_pos.mpr (by omega)\n  have hqle : q n≤n := by\n    have hh := (div_lt_iff₀ hnR).mp hqn\n    exact Nat.cast_le.mp (by linarith : (q n : ℝ)≤n)\n  have hb := weightedCount_bound n (q n) (by omega) hqle\n  have hpoly' : 2*(n : ℝ)≤Real.exp (ε/2*(n : ℝ)) := by\n    simpa only [Real.rpow_one,zero_mul,Real.exp_zero,mul_one] using hpoly\n  calc\n    (weightedCount n (q n) : ℝ)≤((n : ℝ)+1)*Real.exp ((n : ℝ)*entropy ((q n : ℝ)/n)) := hb\n    _ ≤ (2*(n : ℝ))*Real.exp (ε/2*(n : ℝ)) := by\n      apply mul_le_mul\n      · have hnr : (1 : ℝ)≤n := Nat.one_le_cast.mpr hn\n        linarith\n      · apply Real.exp_le_exp.mpr\n        nlinarith\n      · exact Real.exp_nonneg _\n      · positivity\n    _ ≤ Real.exp (ε/2*(n : ℝ))*Real.exp (ε/2*(n : ℝ)) :=\n      mul_le_mul_of_nonneg_right hpoly' (Real.exp_nonneg _)\n    _ = Real.exp (ε*(n : ℝ)) := by rw [← Real.exp_add]; congr 1; ring\n\nend RiemannGaussian.SemiprimeSupportRate\n","RiemannGaussian.SemiprimeWordFoldBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeWordFoldArithmetic\n\n/-! # Physical finite-word fold clocks and buffer widths\nEach bound concerns the actual report-preserving program. Source/table/test\nacquisition is included through its input reports, not a free value oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeWordFoldBounds\nopen SemiprimeWordFoldArithmetic SemiprimeRationalBits SemiprimeJetBits\nopen SemiprimeRepresentativeExecution\n\n/-- Literal allocated zero buffers fit the actual template. -/\ntheorem zero_bounded (J W : ℕ) (hW : 0< W) : Bounded (zero J).words W :=\n  SemiprimeCorrectedPortBitsBounds.zeroBits_bounded J W hW\n/-- Literal allocated one buffers fit the actual template. -/\ntheorem one_bounded (J W : ℕ) (hW : 0< W) : Bounded (one J).words W :=\n  SemiprimeLocalBits.oneArray_bounded J W hW\n\n/-- Actual fitting makes every physical addition buffer occupy the template. -/\ntheorem add_bounded (template : List Bool) (J : ℕ) (a b : JetReport) :\n    Bounded (add template J a b).words template.length := addBits_bounded template _ _ J\n/-- Actual fitting makes every physical multiplication buffer occupy the template. -/\ntheorem mul_bounded (template : List Bool) (J : ℕ) (a b : JetReport) (ht : 0< template.length) :\n    Bounded (mul template J a b).words template.length := multiplyBits_bounded template ht _ _ J\n/-- Sign scaling uses the same physically bounded output buffers. -/\ntheorem scale_bounded (template : List Bool) (J : ℕ) (a : JetReport) (negative : Bool) :\n    Bounded (scale template J a negative).words template.length := scaleBits_bounded template _ _ J\n\n/-- A gate copies its acquired body or allocates physical zero. -/\ntheorem gate_bounded (J : ℕ) (test : TestReport) (body : Unit → JetReport) (W : ℕ)\n    (hW : 0< W) (hb : Bounded (body ()).words W) : Bounded (gate J test body).words W := by\n  cases he : test.accepted\n  · simpa only [gate,he,Bool.false_eq_true,ite_false] using zero_bounded J W hW\n  · simpa only [gate,he,ite_true] using hb\n\n/-- The finite sum retains bounded physical accumulator buffers at every step. -/\ntheorem sumFrom_bounded (template : List Bool) (J : ℕ) (f : ℕ → JetReport)\n    (fuel start : ℕ) (acc : JetReport) (ha : Bounded acc.words template.length) :\n    Bounded (sumFrom template J f fuel start acc).words template.length := by\n  induction fuel generalizing start acc with\n  | zero => exact ha\n  | succ fuel ih => exact ih (start+1) _ (add_bounded template J acc (f start))\n\n/-- A finite sum preserves exact precision after every accumulator update. -/\ntheorem sumFrom_size (template : List Bool) (J : ℕ) (f : ℕ → JetReport)\n    (fuel start : ℕ) (acc : JetReport) (ha : acc.words.size=J) :\n    (sumFrom template J f fuel start acc).words.size=J := by\n  induction fuel generalizing start acc with\n  | zero => exact ha\n  | succ fuel ih => exact ih (start+1) _ (add_size template J acc (f start))\n\n@[simp] theorem sumCodes_size (template : List Bool) (J N : ℕ) (f : Fin N → JetReport) :\n    (sumCodes template J N f).words.size=J := sumFrom_size template J _ N 0 _ (zero_size J)\n\ntheorem sumCodes_bounded (template : List Bool) (J N : ℕ) (f : Fin N → JetReport)\n    (ht : 0< template.length) : Bounded (sumCodes template J N f).words template.length :=\n  sumFrom_bounded template J _ N 0 _ (zero_bounded J _ ht)\n\n/-- Physical add instructions, actual coefficient addressing and fold control. -/\ndef addBudget (W J : ℕ) : ℕ :=\n  SemiprimeCorrectedPortBitsBounds.addBudget W J+J+1\n/-- Physical multiplication instructions and fold control. -/\ndef mulBudget (W J : ℕ) : ℕ := SemiprimeNativeGroupBitsBudget.multiplyBudget W J+J+1\n/-- Literal sign scaling includes its actual physical source access and control. -/\ndef scaleBudget (W J : ℕ) : ℕ :=\n  J*(20000*(W+1)^3+(J+1)*(2*W+3)+(2*W+3))+(2*J+1)+J+4\n\n/-- Actual addition retains both acquired reports and all new bit work. -/\ntheorem add_clock (template : List Bool) (J : ℕ) (a b : JetReport)\n    (ht : 0< template.length) (ha : Bounded a.words template.length) (hb : Bounded b.words template.length)\n    (hsa : a.words.size≤ J) (hsb : b.words.size≤ J) :\n    (add template J a b).clock≤ a.clock+b.clock+addBudget template.length J := by\n  have hp := addBits_cost template ht a.words b.words J ha hb\n  have h : (addBits template a.words b.words J).clock≤ SemiprimeCorrectedPortBitsBounds.addBudget template.length J := by\n    apply hp.trans\n    unfold SemiprimeCorrectedPortBitsBounds.addBudget accessCost\n    gcongr\n  unfold add addBudget\n  dsimp only\n  omega\n\n/-- Actual convolution retains both acquired reports and all new bit work. -/\ntheorem mul_clock (template : List Bool) (J : ℕ) (a b : JetReport)\n    (ht : 0< template.length) (ha : Bounded a.words template.length) (hb : Bounded b.words template.length)\n    (hsa : a.words.size≤ J) (hsb : b.words.size≤ J) :\n    (mul template J a b).clock≤ a.clock+b.clock+mulBudget template.length J := by\n  have hp := multiplyBits_cost template ht a.words b.words J ha hb\n  have h : (multiplyBits template a.words b.words J).clock≤ SemiprimeNativeGroupBitsBudget.multiplyBudget template.length J := by\n    apply hp.trans\n    unfold SemiprimeNativeGroupBitsBudget.multiplyBudget accessCost\n    gcongr\n  unfold mul mulBudget\n  dsimp only\n  omega\n\n/-- Literal sign multiplication is physically acquired with constant-sized words, not advice. -/\ntheorem scale_clock (template : List Bool) (J : ℕ) (a : JetReport) (negative : Bool)\n    (ht : 0< template.length) (ha : Bounded a.words template.length) (hsa : a.words.size≤ J) :\n    (scale template J a negative).clock≤ a.clock+scaleBudget template.length J := by\n  have hc : Width (if negative then negOneWord else oneWord) template.length := by\n    cases negative\n    · exact oneWord_width ht\n    · exact negOneWord_width ht\n  have hp := scaleBits_cost template ht a.words (if negative then negOneWord else oneWord) J ha hc\n  have h : (scaleBits template a.words (if negative then negOneWord else oneWord) J).clock≤\n      J*(20000*(template.length+1)^3+(J+1)*(2*template.length+3)+(2*template.length+3))+(2*J+1) := by\n    apply hp.trans\n    unfold accessCost\n    gcongr\n  unfold scale scaleBudget\n  dsimp only\n  omega\n\n/-- A rejected test pays its actual report and zero allocation, skipping body. -/\ntheorem gate_clock (J B : ℕ) (test : TestReport) (body : Unit → JetReport)\n    (hb : (body ()).clock≤ B) : (gate J test body).clock≤ test.work+B+3*J+2 := by\n  cases he : test.accepted <;> simp only [gate,he,Bool.false_eq_true,ite_false,ite_true]\n  · simp only [zero,SemiprimeCorrectedPortBits.zeroBits]\n    omega\n  · omega\n\n/-- Complete sum clock: original accumulator, EVERY callback and EVERY physical\naddition are retained, without regenerating old callbacks inside a closure. -/\ntheorem sumFrom_clock (template : List Bool) (J fuel start B : ℕ) (f : ℕ → JetReport)\n    (acc : JetReport) (ht : 0< template.length) (ha : Bounded acc.words template.length)\n    (hsize : acc.words.size≤ J)\n    (hf : ∀ i,start≤ i → i< start+fuel → (f i).clock≤ B ∧ Bounded (f i).words template.length ∧ (f i).words.size≤ J) :\n    (sumFrom template J f fuel start acc).clock≤ acc.clock+fuel*(B+addBudget template.length J) := by\n  induction fuel generalizing start acc with\n  | zero => simp [sumFrom]\n  | succ fuel ih =>\n    have hi := hf start (by omega) (by omega)\n    have hh := add_clock template J acc (f start) ht ha hi.2.1 hsize hi.2.2\n    have ho := ih (start+1) (add template J acc (f start)) (add_bounded template J acc (f start))\n      (by simp) (fun i h₁ h₂ => hf i (by omega) (by omega))\n    change (sumFrom template J f fuel (start+1) (add template J acc (f start))).clock≤_\n    nlinarith only [hi.1,hh,ho]\n\n/-- Literal finite code acquisition has the same linear-in-code count clock. -/\ntheorem sumCodes_clock (template : List Bool) (J N B : ℕ) (f : Fin N → JetReport)\n    (ht : 0< template.length)\n    (hf : ∀ i,(f i).clock≤ B ∧ Bounded (f i).words template.length ∧ (f i).words.size≤ J) :\n    (sumCodes template J N f).clock≤3*J+1+N*(B+addBudget template.length J) := by\n  have h := sumFrom_clock template J N 0 B\n    (fun i => if hi : i<N then f ⟨i,hi⟩ else zero J) (zero J) ht (zero_bounded J _ ht) (by simp) (by\n    intro i _ hi\n    have hi' : i< N := by omega\n    simpa only [dite_eq_left hi'] using hf ⟨i,hi'⟩)\n  simpa only [sumCodes,zero,SemiprimeCorrectedPortBits.zeroBits] using h\n\n/-- Product suffix clocks reuse the actual native physical multiplication fold. -/\ntheorem productList_clock {A : Type} (template : List Bool) (J B : ℕ) (xs : List A)\n    (f : A → JetReport) (ht : 0< template.length)\n    (hf : ∀ e∈xs,(f e).clock≤ B) (hw : ∀ e∈xs,Bounded (f e).words template.length)\n    (hs : ∀ e∈xs,(f e).words.size≤ J) :\n    (productList template J xs f).clock≤\n      xs.length*(B+SemiprimeNativeGroupBitsBudget.multiplyBudget template.length J+J+3)+(3*J+1) :=\n  SemiprimeNativeGroupBitsBudget.productList_clock template J B xs f ht hf hw hs\n\nend RiemannGaussian.SemiprimeWordFoldBounds\n"};
